insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'en', 'Common Swift', 'Swifts can stay airborne for months at a time, even sleeping on the wing.', 'On warm summer evenings, watch high over rooftops and listen for screaming parties.', 'Put up a swift box under your eaves before the birds return in spring.', 'When renovating, keep the small gaps under eaves where swifts nest.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'en', 'Barn Swallow', 'Barn swallows migrate all the way to southern Africa and back each year.', 'From spring to early autumn, look for them skimming low over open fields and water.', 'Leave a barn or shed door ajar so they can reach their nest ledges.', 'Avoid knocking down old mud nests — swallows reuse them year after year.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'en', 'Common Cuckoo', 'Cuckoos lay their eggs in other birds’ nests and never raise their own young.', 'In late spring, listen for the far-carrying "cuck-oo" call from woodland edges.', 'Support insect-rich meadows and hedgerows that feed the birds cuckoos rely on.', 'Keep to paths near scrub and reedbeds so host birds are not disturbed.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'en', 'European Robin', 'Robins are fiercely territorial and will sing through the night near streetlights.', 'Year-round in gardens and woodland; they often follow diggers hoping for worms.', 'Leave a corner of the garden with leaf litter where robins can forage.', 'Delay heavy hedge-cutting until nesting is over in late summer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'en', 'Common Blackbird', 'The male’s rich, fluting song is one of the most recognisable in Europe.', 'Year-round; listen for males singing from rooftops and treetops at dawn and dusk.', 'Put out fresh water for drinking and bathing, especially in dry spells.', 'Keep cats indoors at dawn during the nesting season.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'en', 'Fieldfare', 'Fieldfares are social thrushes that roam in noisy, chattering winter flocks.', 'In autumn and winter, watch flocks stripping berries from hedges and rowan trees.', 'Leave berry-bearing shrubs like rowan and hawthorn unpruned over winter.', 'Let windfall apples lie in winter — they are vital cold-weather food.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'en', 'Great Tit', 'Great tits have a huge vocabulary and learn new calls from their neighbours.', 'Year-round; listen for the ringing "teacher-teacher" song from late winter.', 'Hang a nest box with a 32 mm hole in a quiet, shaded spot.', 'Avoid garden pesticides so there are enough caterpillars to feed the chicks.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'en', 'Eurasian Blue Tit', 'A single brood of blue tits can eat over a thousand caterpillars.', 'Year-round in gardens and woods, often hanging upside-down on thin twigs.', 'Put up a small nest box with a 25 mm hole away from prevailing wind.', 'Skip insecticides in spring so caterpillars are available for the chicks.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'en', 'Common Chaffinch', 'Chaffinch songs vary by region, almost like local dialects.', 'Spring to autumn; males sing a bright, descending phrase from open perches.', 'Leave some seed heads and weedy patches standing over the season.', 'Keep feeders clean to prevent disease spreading among finches.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'en', 'Eurasian Jay', 'Jays bury thousands of acorns each autumn and plant whole oak woods by forgetting some.', 'Year-round in oak woodland; watch for flashes of pink and blue in autumn.', 'Leave fallen acorns and leaf litter under oaks undisturbed.', 'Keep dogs on paths in woodland so ground-feeding birds are not flushed.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'en', 'Great Spotted Woodpecker', 'Its spring "drumming" is not feeding but a fast tattoo to claim territory.', 'Year-round; in late winter listen for drumming echoing through the woods.', 'Leave standing dead wood, which holds the insects woodpeckers feed on.', 'Do not fell dead or dying trees that may hold nest holes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'en', 'White Wagtail', 'The wagtail’s constant tail-bobbing may signal alertness to predators.', 'Spring to autumn near water and open ground, running and pausing to snatch insects.', 'Keep a patch of short grass or gravel near water where they can forage.', 'Avoid disturbing shingle and shoreline where wagtails feed and nest.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'en', 'Common Crane', 'Cranes perform leaping, bowing courtship dances in early spring.', 'From spring to autumn around wetlands; listen for bugling calls carrying for miles.', 'Support the protection of undrained bogs and wet meadows where cranes breed.', 'Watch nesting wetlands from a distance — cranes abandon disturbed nests.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'en', 'Whooper Swan', 'Whooper swans mate for life and announce arrivals with loud, trumpeting calls.', 'In spring and autumn on lakes and flooded fields, often in family groups.', 'Support keeping shallow lake margins and wet fields free of drainage.', 'Never feed bread to swans — it harms them; keep your distance on the ice.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'en', 'Mallard', 'Ducklings can swim and feed themselves within hours of hatching.', 'Year-round on almost any pond, lake, or slow river.', 'If you feed ducks, use oats, peas, or seeds rather than bread.', 'Keep dogs out of the water where ducks are nesting in spring.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'en', 'Common Buzzard', 'Buzzards soar on broad wings and often call with a cat-like "peee-yow".', 'Spring to autumn; scan for them circling high over fields and forest edges.', 'Support rough grassland and field margins that hold voles and small prey.', 'Never use rodent poisons, which move up the food chain into birds of prey.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'en', 'Osprey', 'Ospreys plunge feet-first to catch fish and can carry prey half their own weight.', 'Spring to autumn near large lakes; watch for hovering then a dramatic dive.', 'Support artificial nest platforms on tall poles near fish-rich lakes.', 'Give nesting platforms a wide berth so pairs are not scared off their eggs.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'en', 'Red Fox', 'Foxes use the Earth’s magnetic field to help judge pounces on hidden prey.', 'Year-round, most active at dawn and dusk along woodland and field edges.', 'Leave a wild, undisturbed corner where foxes can rest and den.', 'Secure bins and never leave harmful food scraps out for foxes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'en', 'European Hedgehog', 'A hedgehog can travel a couple of kilometres in a single night’s foraging.', 'From spring to autumn after dark; in winter they hibernate under leaf and log piles.', 'Cut a 13 cm gap in fences so hedgehogs can roam between gardens.', 'Check long grass before strimming and leave leaf piles for hibernation.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'en', 'Roe Deer', 'Roe deer delay their pregnancy so fawns are always born in early summer.', 'Year-round at woodland edges, most visible grazing at dawn and dusk.', 'Support unmown field margins and scrub that give deer cover and food.', 'Keep dogs leashed near woodland in early summer when fawns lie hidden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'en', 'Moose', 'The moose is the largest deer on Earth; a big bull can weigh over half a tonne.', 'Year-round in forests and wetlands, most active at dawn and dusk.', 'Support connected forests and wetland corridors that moose need to roam.', 'Drive carefully at dawn and dusk on forest roads and never approach a calf.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'en', 'Eurasian Red Squirrel', 'Red squirrels build several nests, called dreys, and move between them.', 'Year-round in conifer and mixed woods, busiest in the early morning.', 'Leave cones, nuts, and standing trees that squirrels feed and nest in.', 'Keep dogs on paths and avoid disturbing trees that may hold a drey.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'en', 'European Beaver', 'Beaver dams create wetlands that boost fish, birds, and insects for miles.', 'From spring to late autumn around slow rivers, most active at dusk.', 'Support leaving beaver dams and waterside trees in place where safe.', 'Keep back from lodges and dams, especially when kits are young.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'en', 'Mountain Hare', 'Mountain hares turn white in winter for camouflage against the snow.', 'Year-round on open ground and forest clearings, mainly at dawn and dusk.', 'Support a mix of open ground and cover that hares need through the year.', 'Keep dogs leashed on open ground so resting hares are not chased.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'en', 'European Badger', 'Badgers live in family groups in underground setts used for generations.', 'From spring to autumn after dark near woodland; they sleep away the winter.', 'Leave undisturbed banks and hedgerows where badgers can dig setts.', 'Never block or dig near an active sett — it is their long-term home.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'en', 'Common Pipistrelle', 'This tiny bat can eat up to 3,000 midges and mosquitoes in one night.', 'On summer evenings, watch for fast, jinking flight around dusk over gardens.', 'Put up a bat box high on a wall or tree that catches the evening sun.', 'Avoid bright lights on roost entrances and keep the night sky dark for bats.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'en', 'Small Tortoiseshell', 'This butterfly hibernates as an adult, often in sheds and lofts.', 'From early spring to autumn on sunny flowers, especially nettles and buddleia.', 'Leave a patch of nettles in a sunny corner — its caterpillars need them.', 'Leave hibernating butterflies undisturbed in sheds over winter.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'en', 'European Peacock', 'Its eyespots flash to startle birds, and its wings can hiss when opened.', 'Spring to autumn on sunny days, feeding on thistles, buddleia, and windfall fruit.', 'Let a sunny nettle patch grow for its caterpillars.', 'Do not disturb adults sheltering in sheds and log piles over winter.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'en', 'Common Brimstone', 'The word "butterfly" may come from the male brimstone’s butter-yellow colour.', 'One of the first butterflies of spring; look along woodland edges on warm days.', 'Support buckthorn shrubs in hedges, the only plants its caterpillars eat.', 'Avoid clearing scrubby hedgerows that shelter overwintering adults.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'en', 'Orange Tip', 'Only the males have the bright orange wingtips; females are white.', 'In spring along damp meadows and lanes where cuckoo flower grows.', 'Let cuckoo flower and garlic mustard grow in damp, unmown corners.', 'Delay cutting verges until its caterpillars have finished feeding.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'en', 'Common Blue', 'The common blue’s caterpillars are sometimes tended by ants for their sweet secretions.', 'From late spring on sunny grassland rich in clover and bird’s-foot trefoil.', 'Leave grassland unmown so trefoils and clovers can flower.', 'Avoid spraying wildflower-rich grassland with weedkiller.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'en', 'Green-veined White', 'Despite looking like a cabbage white, it prefers wild plants, not garden crops.', 'Spring to late summer in damp meadows, ditches, and woodland rides.', 'Let damp corners grow wild with native crucifers like cuckoo flower.', 'Avoid draining and spraying damp meadows where it breeds.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'en', 'Seven-spot Ladybird', 'A single ladybird can eat thousands of aphids in its lifetime.', 'From spring to autumn on plants with aphids; they cluster to hibernate in winter.', 'Tolerate some aphids and skip sprays so ladybirds have food.', 'Leave hollow stems and leaf litter where ladybirds shelter over winter.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'en', 'Buff-tailed Bumblebee', 'Queens are among the first bees out in spring, buzzing low to find nest holes.', 'From early spring to autumn on flowers; queens search hedge bottoms in spring.', 'Grow or leave early-flowering plants and let clover bloom in the lawn.', 'Leave undisturbed banks and old mouse holes where colonies nest.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'en', 'Western Honey Bee', 'Foragers tell the hive where flowers are by dancing in a figure-of-eight.', 'From spring to autumn on flowers on warm, still days.', 'Let a range of flowers bloom across the seasons and leave a shallow water dish.', 'Avoid spraying flowering plants, and never spray in the middle of the day.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'en', 'Emperor Dragonfly', 'One of Europe’s largest dragonflies, it can even catch prey in mid-air.', 'On warm summer days, watch it patrolling ponds and lake margins.', 'Keep or dig a pond with plants and leave its edges vegetated.', 'Keep ponds free of pollution and run-off so larvae can develop.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'en', 'Common Darter', 'Darters often perch on the same warm spot, darting out to grab passing insects.', 'From midsummer to autumn near still water, basking on paths and posts.', 'Leave sunny perches and vegetation around ponds and ditches.', 'Avoid letting fertiliser or oil wash into ponds where larvae live.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'en', 'Red Wood Ant', 'Their thatched nest mounds can be over a metre tall and house half a million ants.', 'From spring to autumn in conifer woods; look for domed mounds of needles.', 'Leave nest mounds undisturbed — they take years to build.', 'Keep to paths and never kick or dig into an ant mound.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'en', 'Wood Anemone', 'Wood anemones spread so slowly that dense carpets signal ancient woodland.', 'In spring, look for carpets of white flowers before the trees leaf out.', 'Leave woodland floors undisturbed so the slow-spreading roots can thrive.', 'Enjoy them where they grow — picking removes flowers that took years to spread.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'en', 'Lily of the Valley', 'Every part of this sweetly scented plant is poisonous if eaten.', 'In late spring, follow the scent to shady woodland and shaded gardens.', 'Leave shaded woodland edges and leaf litter where it grows.', 'Do not pick or dig it up, and keep it away from children and pets.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'en', 'Ramsons', 'You often smell ramsons — wild garlic — before you see the white flowers.', 'In spring, look for broad green leaves and starry flowers in damp woods.', 'Leave damp woodland undisturbed so the carpets can regrow each year.', 'If foraging is allowed locally, take only a little and never uproot bulbs.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'en', 'Marsh Marigold', 'One of the oldest native plants, it survived the last Ice Age in Scandinavia.', 'In spring, look for big golden flowers in marshes, ditches, and pond edges.', 'Keep pond and ditch margins wet and unmown so it can flower.', 'Avoid draining wet ground and leave the plants where they grow.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'en', 'Cowslip', 'Cowslips were once so common in hay meadows that children made them into balls.', 'In spring, look for nodding yellow flowers in old, unimproved meadows.', 'Leave meadows unmown until the cowslips have flowered and set seed.', 'Do not pick or dig them from the wild — meadow flowers are declining.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'en', 'Oxeye Daisy', 'The oxeye daisy’s flower is actually dozens of tiny flowers packed together.', 'In summer, look for large white daisies along roadsides and meadows.', 'Leave a strip of grass unmown through midsummer so it can flower.', 'Avoid spraying verges and meadows with weedkiller.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'en', 'Common Dandelion', 'Dandelions are one of the most important early nectar sources for bees.', 'From spring onwards almost anywhere; flowers open in sun and close at dusk.', 'Let dandelions flower on the lawn in spring before the first mow.', 'Skip lawn weedkillers so early pollinators keep this vital food.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'en', 'Heather', 'A single heather plant can produce over a hundred thousand tiny seeds.', 'In late summer, look for purple carpets on open heaths and bogs.', 'Support keeping heathland open and free of drainage.', 'Keep to paths on heaths and never light fires in dry conditions.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'en', 'Bilberry', 'Bilberries stain your fingers blue and feed everything from birds to bears.', 'In summer, look for low bushes with dark berries in pine and spruce forest.', 'Leave forest undergrowth intact so the low bushes can fruit.', 'If picking is allowed locally, leave plenty of berries for wildlife.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'en', 'Lingonberry', 'Lingonberries keep for months thanks to a natural preservative in the fruit.', 'In late summer and autumn, look for glossy red berries on evergreen mats.', 'Leave forest floor vegetation undisturbed so the mats can spread.', 'If picking is allowed locally, tread carefully to avoid crushing the plants.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'en', 'Silver Birch', 'A birch supports hundreds of insect species, feeding countless birds.', 'Year-round; the white, peeling bark makes it easy to spot in any season.', 'Leave fallen birch leaves and dead wood to enrich the soil and feed insects.', 'Avoid stripping bark, which can wound and weaken the tree.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'en', 'Norway Spruce', 'A Norway spruce in Sweden grows from roots that are thousands of years old.', 'Year-round in forests; its drooping cones are the longest of any spruce.', 'Leave fallen cones and dead wood, which shelter insects and fungi.', 'Keep to trails in forests to avoid compacting shallow spruce roots.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'en', 'Scots Pine', 'Old Scots pines glow orange near the top and can live for centuries.', 'Year-round on sandy and rocky ground; look for the orange upper bark.', 'Leave standing deadwood and old pines, which are rich in wildlife.', 'Never light fires against or near pines on dry, sandy ground.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'en', 'Northern Pike', 'The pike is an ambush predator that can lunge from stillness in a blink.', 'From spring to autumn in weedy shallows of lakes and slow rivers.', 'Support keeping reedy shallows and water plants where young fish shelter.', 'Keep pollution and litter out of the water; follow local fishing rules.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'en', 'European Perch', 'Perch hunt in packs and wear bold stripes that break up their outline.', 'In the warmer months around jetties, weed beds, and drop-offs.', 'Support clean water and submerged structure that shelters small fish.', 'Never tip anything into lakes and rivers; follow local fishing rules.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'en', 'Common Roach', 'Roach are a key food fish that many lake predators depend on.', 'In the warmer months in shoals near the surface of lakes and slow rivers.', 'Support keeping water clean and margins vegetated for spawning.', 'Keep run-off and litter out of the water; follow local fishing rules.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'sv', 'Tornseglare', 'Tornseglare kan hålla sig i luften i flera månader i sträck och sover till och med under flykten.', 'Under varma sommarkvällar, spana högt över hustaken och lyssna efter skrikande flockar.', 'Sätt upp en holk för tornseglare under takfoten innan fåglarna återvänder på våren.', 'Vid renovering, bevara de små springorna under takfoten där tornseglare häckar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'sv', 'Ladusvala', 'Ladusvalan flyttar ända till södra Afrika och tillbaka varje år.', 'Från vår till tidig höst, håll utkik efter dem när de svävar lågt över öppna fält och vatten.', 'Lämna en lad- eller skjulsdörr på glänt så att de når sina boplatser.', 'Undvik att riva gamla lerbon – svalor återanvänder dem år efter år.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'sv', 'Gök', 'Göken lägger sina ägg i andra fåglars bon och uppfostrar aldrig sina egna ungar.', 'På senvåren, lyssna efter det långväga ”ko-ko”-ropet från skogsbryn.', 'Stöd insektsrika ängar och häckar som föder de fåglar göken är beroende av.', 'Håll dig till stigarna nära buskmark och vassar så att värdfåglarna inte störs.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'sv', 'Rödhake', 'Rödhaken är hårt revirhävdande och kan sjunga natten igenom nära gatlyktor.', 'Året runt i trädgårdar och skog; de följer ofta efter grävande arbete i hopp om maskar.', 'Lämna ett hörn av trädgården med löv där rödhaken kan söka föda.', 'Skjut upp kraftig häckklippning tills häckningen är över på sensommaren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'sv', 'Koltrast', 'Hanens rika, flöjtande sång är en av de mest igenkännliga i Europa.', 'Året runt; lyssna efter hanar som sjunger från tak och trädtoppar i gryning och skymning.', 'Ställ ut färskt vatten för dryck och bad, särskilt under torra perioder.', 'Håll katter inomhus i gryningen under häckningssäsongen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'sv', 'Björktrast', 'Björktrasten är en social trast som stryker omkring i högljudda, pratsamma vinterflockar.', 'Under höst och vinter, se flockar rensa bär från häckar och rönnar.', 'Lämna bärbärande buskar som rönn och hagtorn oklippta över vintern.', 'Låt fallfrukt ligga kvar på vintern – det är viktig föda i kylan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'sv', 'Talgoxe', 'Talgoxar har ett stort läten-register och lär sig nya rop av sina grannar.', 'Året runt; lyssna efter den ringande ”ti-ta, ti-ta”-sången från senvintern.', 'Sätt upp en holk med 32 mm hål på en lugn, skuggig plats.', 'Undvik trädgårdsbekämpningsmedel så att det finns tillräckligt med larver till ungarna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'sv', 'Blåmes', 'En enda kull blåmesar kan äta över tusen larver.', 'Året runt i trädgårdar och skog, ofta hängande upp och ner på tunna kvistar.', 'Sätt upp en liten holk med 25 mm hål i lä för rådande vind.', 'Hoppa över insektsmedel på våren så att larver finns till ungarna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'sv', 'Bofink', 'Bofinkens sång varierar mellan regioner, nästan som lokala dialekter.', 'Vår till höst; hanar sjunger en ljus, fallande fras från öppna sittplatser.', 'Lämna en del fröställningar och ogräsfläckar stående under säsongen.', 'Håll fågelmatningar rena för att hindra att sjukdomar sprids bland finkar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'sv', 'Nötskrika', 'Nötskrikan gömmer tusentals ekollon varje höst och planterar hela ekskogar genom att glömma en del.', 'Året runt i ekskog; håll utkik efter skymtar av rosa och blått på hösten.', 'Lämna fallna ekollon och löv under ekar orörda.', 'Håll hundar på stigarna i skogen så att markfödande fåglar inte skräms upp.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'sv', 'Större hackspett', 'Dess vårtrummande är inte födosök utan en snabb trumvirvel för att hävda revir.', 'Året runt; lyssna på senvintern efter trummande som ekar genom skogen.', 'Lämna stående död ved, som hyser de insekter hackspettar äter.', 'Fäll inte döda eller döende träd som kan innehålla bohål.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'sv', 'Sädesärla', 'Ärlans ständiga stjärtviftande kan signalera vaksamhet mot rovdjur.', 'Vår till höst nära vatten och öppen mark, springande och stannande för att fånga insekter.', 'Behåll en fläck kortklippt gräs eller grus nära vatten där de kan söka föda.', 'Undvik att störa grus- och strandkanter där ärlor söker föda och häckar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'sv', 'Trana', 'Tranor utför hoppande, bugande speldanser tidigt på våren.', 'Från vår till höst kring våtmarker; lyssna efter trumpetande rop som bär flera kilometer.', 'Stöd skyddet av odikade mossar och våta ängar där tranor häckar.', 'Betrakta häckningsvåtmarker på avstånd – tranor överger störda bon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'sv', 'Sångsvan', 'Sångsvanar parar sig för livet och annonserar ankomster med höga, trumpetande rop.', 'Vår och höst på sjöar och översvämmade fält, ofta i familjegrupper.', 'Stöd att behålla grunda sjökanter och våta fält fria från dikning.', 'Mata aldrig svanar med bröd – det skadar dem; håll avstånd på isen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'sv', 'Gräsand', 'Ungarna kan simma och söka föda själva bara timmar efter kläckningen.', 'Året runt på nästan vilken damm, sjö eller lugnt vattendrag som helst.', 'Om du matar änder, använd havre, ärtor eller frön i stället för bröd.', 'Håll hundar borta från vattnet där änder häckar på våren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'sv', 'Ormvråk', 'Ormvråken svävar på breda vingar och ropar ofta med ett kattlikt ”pi-ää”.', 'Vår till höst; spana efter dem när de kretsar högt över fält och skogsbryn.', 'Stöd ängsmark och åkerkanter som hyser sorkar och smådjur.', 'Använd aldrig råttgift, som vandrar upp i näringskedjan till rovfåglar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'sv', 'Fiskgjuse', 'Fiskgjusen dyker med fötterna först för att fånga fisk och kan bära byte som väger hälften av den själv.', 'Vår till höst nära stora sjöar; håll utkik efter ryttling följt av ett dramatiskt dyk.', 'Stöd konstgjorda boplattformar på höga stolpar nära fiskrika sjöar.', 'Ge boplattformar gott om utrymme så att paren inte skräms från äggen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'sv', 'Rödräv', 'Rävar använder jordens magnetfält för att bedöma sina hopp mot dolt byte.', 'Året runt, mest aktiv i gryning och skymning längs skogs- och åkerkanter.', 'Lämna ett vilt, ostört hörn där rävar kan vila och gräva lya.', 'Säkra sopkärl och lämna aldrig skadliga matrester ute åt rävar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'sv', 'Igelkott', 'En igelkott kan färdas ett par kilometer under en enda natts födosök.', 'Från vår till höst efter mörkrets inbrott; på vintern går de i ide under löv- och vedhögar.', 'Klipp ett 13 cm hål i staket så att igelkottar kan röra sig mellan trädgårdar.', 'Kolla högt gräs innan du trimmar och lämna lövhögar för vinteride.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'sv', 'Rådjur', 'Rådjur fördröjer sin dräktighet så att killingarna alltid föds på försommaren.', 'Året runt i skogsbryn, mest synliga när de betar i gryning och skymning.', 'Stöd oklippta åkerkanter och buskmark som ger rådjur skydd och föda.', 'Håll hundar kopplade nära skog på försommaren när killingar ligger gömda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'sv', 'Älg', 'Älgen är världens största hjortdjur; en stor tjur kan väga över ett halvt ton.', 'Året runt i skogar och våtmarker, mest aktiv i gryning och skymning.', 'Stöd sammanhängande skogar och våtmarkskorridorer som älgar behöver för att vandra.', 'Kör försiktigt i gryning och skymning på skogsvägar och närma dig aldrig en kalv.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'sv', 'Ekorre', 'Ekorren bygger flera bon, kallade risbon, och flyttar mellan dem.', 'Året runt i barr- och blandskog, flitigast tidigt på morgonen.', 'Lämna kottar, nötter och stående träd som ekorrar äter och bor i.', 'Håll hundar på stigarna och undvik att störa träd som kan hysa ett risbo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'sv', 'Bäver', 'Bäverdammar skapar våtmarker som gynnar fisk, fåglar och insekter i milsvida områden.', 'Från vår till sen höst kring lugna vattendrag, mest aktiv i skymningen.', 'Stöd att lämna bäverdammar och strandträd på plats där det är säkert.', 'Håll avstånd från hyddor och dammar, särskilt när kuttingarna är små.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'sv', 'Skogshare', 'Skogsharen blir vit på vintern för att smälta in mot snön.', 'Året runt på öppen mark och skogsgläntor, främst i gryning och skymning.', 'Stöd en blandning av öppen mark och skydd som harar behöver året om.', 'Håll hundar kopplade på öppen mark så att vilande harar inte jagas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'sv', 'Grävling', 'Grävlingar lever i familjegrupper i underjordiska gryt som används i generationer.', 'Från vår till höst efter mörkrets inbrott nära skog; de sover bort vintern.', 'Lämna ostörda slänter och häckar där grävlingar kan gräva gryt.', 'Blockera eller gräv aldrig nära ett aktivt gryt – det är deras långvariga hem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'sv', 'Dvärgpipistrell', 'Denna lilla fladdermus kan äta upp till 3 000 mygg på en natt.', 'Sommarkvällar, håll utkik efter snabb, sicksackande flykt i skymningen över trädgårdar.', 'Sätt upp en fladdermusholk högt på en vägg eller ett träd som fångar kvällssolen.', 'Undvik starkt ljus vid boplatser och håll natthimlen mörk för fladdermöss.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'sv', 'Nässelfjäril', 'Denna fjäril övervintrar som vuxen, ofta i skjul och på vindar.', 'Från tidig vår till höst på soliga blommor, särskilt nässlor och buddleja.', 'Lämna en fläck nässlor i ett soligt hörn – dess larver behöver dem.', 'Lämna övervintrande fjärilar i fred i skjul över vintern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'sv', 'Påfågelöga', 'Ögonfläckarna blixtrar till för att skrämma fåglar, och vingarna kan väsa när de öppnas.', 'Vår till höst under soliga dagar, på tistlar, buddleja och fallfrukt.', 'Låt en solig nässelfläck växa för dess larver.', 'Stör inte vuxna fjärilar som söker skydd i skjul och vedhögar över vintern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'sv', 'Citronfjäril', 'Det engelska ordet ”butterfly” kan komma från citronfjärilshanens smörgula färg.', 'En av vårens första fjärilar; spana längs skogsbryn under varma dagar.', 'Stöd brakvedsbuskar i häckar, de enda växter dess larver äter.', 'Undvik att röja buskiga häckar som skyddar övervintrande vuxna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'sv', 'Aurorafjäril', 'Bara hanarna har de klarorange vingspetsarna; honorna är vita.', 'På våren längs fuktiga ängar och vägkanter där ängsbräsma växer.', 'Låt ängsbräsma och löktrav växa i fuktiga, oklippta hörn.', 'Skjut upp klippning av vägkanter tills larverna ätit färdigt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'sv', 'Puktörneblåvinge', 'Puktörneblåvingens larver sköts ibland av myror för deras söta utsöndringar.', 'Från sen vår på soliga gräsmarker rika på klöver och käringtand.', 'Lämna gräsmark oklippt så att käringtand och klöver kan blomma.', 'Undvik att spruta blomrika gräsmarker med ogräsmedel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'sv', 'Rapsfjäril', 'Trots att den liknar en kålfjäril föredrar den vilda växter framför trädgårdsgrödor.', 'Vår till sensommar på fuktiga ängar, diken och skogsstigar.', 'Låt fuktiga hörn växa vilt med inhemska korsblommiga växter som ängsbräsma.', 'Undvik att dika ut och spruta fuktiga ängar där den förökar sig.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'sv', 'Sjuprickig nyckelpiga', 'En enda nyckelpiga kan äta tusentals bladlöss under sin livstid.', 'Från vår till höst på växter med bladlöss; de samlas för att övervintra.', 'Tolerera en del bladlöss och hoppa över sprutning så att nyckelpigor har föda.', 'Lämna ihåliga stjälkar och löv där nyckelpigor söker skydd över vintern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'sv', 'Mörk jordhumla', 'Drottningarna är bland de första bina ute på våren, surrande lågt för att hitta bohål.', 'Från tidig vår till höst på blommor; drottningar söker häckbottnar på våren.', 'Odla eller lämna tidigblommande växter och låt klöver blomma i gräsmattan.', 'Lämna ostörda slänter och gamla musgångar där kolonier bygger bo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'sv', 'Honungsbi', 'Samlare talar om för kupan var blommor finns genom att dansa i en åtta.', 'Från vår till höst på blommor under varma, stilla dagar.', 'Låt en mängd blommor blomma över säsongerna och ställ ut ett grunt vattenfat.', 'Undvik att spruta blommande växter, och spruta aldrig mitt på dagen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'sv', 'Kejsartrollslända', 'En av Europas största trollsländor; den kan till och med fånga byte i luften.', 'Under varma sommardagar, se den patrullera dammar och sjökanter.', 'Behåll eller gräv en damm med växter och lämna kanterna bevuxna.', 'Håll dammar fria från föroreningar och avrinning så att larver kan utvecklas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'sv', 'Större ängstrollslända', 'Ängstrollsländor sitter ofta på samma varma plats och rusar ut för att fånga förbipasserande insekter.', 'Från midsommar till höst nära stillastående vatten, solande på stigar och stolpar.', 'Lämna soliga sittplatser och växtlighet kring dammar och diken.', 'Undvik att låta gödsel eller olja rinna ner i dammar där larver lever.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'sv', 'Röd skogsmyra', 'Deras tuvbon kan vara över en meter höga och rymma en halv miljon myror.', 'Från vår till höst i barrskog; leta efter kupolformade bon av barr.', 'Lämna myrstackar orörda – de tar år att bygga.', 'Håll dig till stigarna och sparka eller gräv aldrig i en myrstack.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'sv', 'Vitsippa', 'Vitsippor sprider sig så långsamt att täta mattor tyder på gammal skog.', 'På våren, leta efter mattor av vita blommor innan träden slår ut.', 'Lämna skogsbottnar ostörda så att de långsamt spridande rötterna kan trivas.', 'Njut av dem där de växer – att plocka tar bort blommor som tagit år att sprida.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'sv', 'Liljekonvalj', 'Hela denna ljuvligt doftande växt är giftig om den äts.', 'På senvåren, följ doften till skuggig skog och skuggiga trädgårdar.', 'Lämna skuggiga skogsbryn och löv där den växer.', 'Plocka eller gräv inte upp den, och håll den borta från barn och husdjur.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'sv', 'Ramslök', 'Man känner ofta lukten av ramslök – vitlöksdoftande – innan man ser de vita blommorna.', 'På våren, leta efter breda gröna blad och stjärnformade blommor i fuktig skog.', 'Lämna fuktig skog ostörd så att mattorna kan växa tillbaka varje år.', 'Om plockning är tillåten lokalt, ta bara lite och dra aldrig upp lökarna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'sv', 'Kabbleka', 'En av de äldsta inhemska växterna, den överlevde den senaste istiden i Skandinavien.', 'På våren, leta efter stora gyllene blommor i kärr, diken och dammkanter.', 'Håll damm- och dikeskanter våta och oklippta så att den kan blomma.', 'Undvik att dika ut våt mark och lämna växterna där de växer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'sv', 'Gullviva', 'Gullvivor var förr så vanliga på slåtterängar att barn gjorde bollar av dem.', 'På våren, leta efter nickande gula blommor på gamla, ogödslade ängar.', 'Lämna ängar oklippta tills gullvivorna blommat och satt frö.', 'Plocka eller gräv inte upp dem från det vilda – ängsblommor minskar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'sv', 'Prästkrage', 'Prästkragens blomma är egentligen dussintals små blommor tätt samlade.', 'På sommaren, leta efter stora vita prästkragar längs vägkanter och ängar.', 'Lämna en remsa gräs oklippt över midsommar så att den kan blomma.', 'Undvik att spruta vägkanter och ängar med ogräsmedel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'sv', 'Maskros', 'Maskrosor är en av de viktigaste tidiga nektarkällorna för bin.', 'Från våren nästan var som helst; blommorna öppnar sig i sol och sluter sig i skymningen.', 'Låt maskrosor blomma i gräsmattan på våren före första klippningen.', 'Hoppa över gräsmatteogräsmedel så att tidiga pollinatörer behåller denna viktiga föda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'sv', 'Ljung', 'En enda ljungplanta kan producera över hundratusen små frön.', 'På sensommaren, leta efter lila mattor på öppna hedar och myrar.', 'Stöd att hålla hedmark öppen och fri från dikning.', 'Håll dig till stigarna på hedar och tänd aldrig eld i torka.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'sv', 'Blåbär', 'Blåbär färgar fingrarna blå och föder allt från fåglar till björnar.', 'På sommaren, leta efter låga buskar med mörka bär i barrskog.', 'Lämna skogens undervegetation intakt så att de låga buskarna kan bära frukt.', 'Om plockning är tillåten lokalt, lämna gott om bär åt djurlivet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'sv', 'Lingon', 'Lingon håller sig i månader tack vare ett naturligt konserveringsmedel i frukten.', 'På sensommaren och hösten, leta efter blanka röda bär på städsegröna mattor.', 'Lämna skogsbottnens växtlighet ostörd så att mattorna kan sprida sig.', 'Om plockning är tillåten lokalt, trampa försiktigt för att inte krossa växterna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'sv', 'Vårtbjörk', 'En björk hyser hundratals insektsarter, som föder otaliga fåglar.', 'Året runt; den vita, flagnande barken gör den lätt att känna igen i alla årstider.', 'Lämna fallna björklöv och död ved för att berika jorden och föda insekter.', 'Undvik att skala bark, vilket kan såra och försvaga trädet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'sv', 'Gran', 'En gran i Sverige växer från rötter som är tusentals år gamla.', 'Året runt i skogar; dess hängande kottar är de längsta av alla granar.', 'Lämna fallna kottar och död ved, som hyser insekter och svampar.', 'Håll dig till stigarna i skogen för att inte packa granens ytliga rötter.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'sv', 'Tall', 'Gamla tallar lyser orange högt upp och kan bli flera hundra år gamla.', 'Året runt på sandig och stenig mark; leta efter den orange övre barken.', 'Lämna stående död ved och gamla tallar, som är rika på liv.', 'Tänd aldrig eld mot eller nära tallar på torr, sandig mark.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'sv', 'Gädda', 'Gäddan är ett bakhållsrovdjur som kan hugga ur stillhet på ett ögonblick.', 'Från vår till höst i vassrika grunda områden i sjöar och lugna vattendrag.', 'Stöd att bevara vassrika grundområden och vattenväxter där ungfisk söker skydd.', 'Håll föroreningar och skräp borta från vattnet; följ lokala fiskeregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'sv', 'Abborre', 'Abborrar jagar i stim och bär djärva ränder som bryter upp deras siluett.', 'Under de varmare månaderna kring bryggor, vassbälten och branter.', 'Stöd rent vatten och undervattensstruktur som skyddar småfisk.', 'Häll aldrig något i sjöar och vattendrag; följ lokala fiskeregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'sv', 'Mört', 'Mörten är en viktig bytesfisk som många rovdjur i sjön är beroende av.', 'Under de varmare månaderna i stim nära ytan i sjöar och lugna vattendrag.', 'Stöd att hålla vattnet rent och kanterna bevuxna för lek.', 'Håll avrinning och skräp borta från vattnet; följ lokala fiskeregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'so', 'Dabagaale-hawleed caadi ah', 'Waxay awoodaan inay bilo badan hawada ku sii jiraan, xitaa way seexdaan iyagoo duulaya.', 'Fiidkii xagaaga oo diiran, kor u fiiri saqafyada oo dhegayso kooxaha qaylinaya.', 'Sanduuq buul u dhig darbiga hoostiisa ka hor inta aysan gu’ga soo noqon.', 'Marka aad guriga dayactirto, ilaali daloolladii yaraa ee ay buulka ka samaystaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'so', 'Dabafallaadh guryaha', 'Waxay sannad kasta u haajiraan koonfurta Afrika oo dib u soo noqdaan.', 'Gu’ga ilaa dayrta hore, waxaad ku aragtaa iyagoo hoos u dul duulaya beeraha iyo biyaha.', 'Albaabka xerada ama bakhaarka wax yar u fur si ay meelaha buulkooda u gaaraan.', 'Ha dumin buulasha dhoobada ah ee hore — sannad kasta ayay dib u isticmaalaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'so', 'Shimbir kuuku', 'Ukuntooda waxay ku dhigaan buulasha shimbiraha kale, mana korsadaan dhashooda.', 'Gu’ga dambe, dhegayso codka fog ee "kuu-kuu" ee ka yimaada geesaha kaynta.', 'Taageer berrimaha iyo xayndaabyada cayayaanka badan leh ee quudiya shimbiraha ay ku tiirsan yihiin.', 'Ku sii soco waddooyinka agagaarka duurka iyo cawska si aan shimbiraha loo dhibin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'so', 'Shimbir laab-cas', 'Aad bay u difaacaan dhulkooda, waxayna habeenkii ku heesaan agagaarka nalalka waddada.', 'Sannadka oo dhan beeraha iyo kaynta; badanaa way raacaan qofka ciidda qodaya.', 'Beerta gees ka mid ah ku dhaaf caleemo dhacay si ay cunto uga raadsadaan.', 'Dib u dhig jarista culus ee xayndaabka ilaa xilliga buulku dhammaado xagaaga dambe.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'so', 'Shimbir madow', 'Heesta labka oo qurux badan waa mid ka mid ah kuwa ugu caansan Yurub.', 'Sannadka oo dhan; dhegayso labka oo ka heesaya saqafyada waaberiga iyo fiidkii.', 'U dhig biyo nadiif ah oo ay cabbaan kuna maydhaan, gaar ahaan xilliga abaarta.', 'Bisadaha guriga ku hay waaberiga xilliga buulka.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'so', 'Shimbir beeraha', 'Waa shimbir bulsho ah oo jiilaalka ku wareega kooxo buuqsan.', 'Dayrta iyo jiilaalka, fiiri kooxaha oo miraha ka gurta xayndaabyada iyo geedaha.', 'Geedaha miraha leh ha jarin inta lagu jiro jiilaalka.', 'Tufaaxa dhulka ku dhacay jiilaalka ku dhaaf — waa cunto muhiim ah xilliga qabowga.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'so', 'Shimbir yar oo weyn', 'Waxay leeyihiin codad badan, waxayna kuwa cusub ka bartaan deriskooda.', 'Sannadka oo dhan; dhegayso heestooda dhawaaqa leh laga bilaabo jiilaalka dambe.', 'Sanduuq buul oo dalool 32 mm leh ku laalaadi meel deggan oo hoos leh.', 'Iska ilaali sunta beerta si dirxiga ay dhashooda ku quudiyaan uu ku filnaado.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'so', 'Shimbir yar oo buluug ah', 'Hal koox oo dhal ah waxay cuni kartaa in ka badan kun dirxi.', 'Sannadka oo dhan beeraha iyo kaynta, badanaa laamaha khafiifka ah ayay ka laalaadaan.', 'Sanduuq yar oo dalool 25 mm leh ku dhig meel dabaysha ka fog.', 'Gu’ga ha isticmaalin sunta cayayaanka si dirxigu dhashooda ugu diyaar noqdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'so', 'Shimbir miro-cune', 'Heestoodu gobol ilaa gobol way kala duwan tahay, sida lahjado maxalli ah.', 'Gu’ga ilaa dayrta; labku waxay ka heesaan meelo furan oo cad.', 'Qaar ka mid ah madaxyada abuurka iyo cawska ku dhaaf inta xilligu socdo.', 'Nadiifi meelaha cuntada si cudurro aysan ugu faafin shimbiraha.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'so', 'Shimbir jaay', 'Dayr kasta waxay aasaan kumanaan miro geed, qaarna way ilaawaan oo kayn cusub bay abuuraan.', 'Sannadka oo dhan kaynta; dayrta fiiri midabbada casaanka iyo buluugga ah.', 'Miraha dhulka ku dhacay iyo caleemaha geedaha hoostooda sida ay yihiin uga tag.', 'Eeyaha waddada ku hay kaynta si shimbiraha dhulka ka cunaya aan loo argaggaxin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'so', 'Shimbir geed-tuma oo bakhtiyay', 'Garaaca gu’ga ma aha cunto raadin — waa calaamad uu dhulkiisa ku sheegto.', 'Sannadka oo dhan; jiilaalka dambe dhegayso garaaca ka dhex dhawaaqaya kaynta.', 'Ku dhaaf geedaha dhintay ee taagan, waxay hoy u yihiin cayayaanka uu cuno.', 'Ha jarin geedaha dhintay ama curyaamay, waxaa ku jiri kara buulal.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'so', 'Shimbir dabo-ruxa cad', 'Ruxitaanka joogtada ah ee dabada waxay u badan tahay digniin ka dhan ah ugaadhsadayaasha.', 'Gu’ga ilaa dayrta agagaarka biyaha, way ordaan oo istaagaan si ay cayayaan u qabtaan.', 'Ku hay cawska gaaban ama quruurux biyaha agtooda si ay cunto uga raadsadaan.', 'Ha carqaladayn xeebaha iyo quruuruxda ay wax ka cunaan buulkana ka sameeyaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'so', 'Haad-dheer', 'Gu’ga hore waxay sameeyaan qoob-ka-cayaar guur oo ay ku booddaan kuna foororsadaan.', 'Gu’ga ilaa dayrta agagaarka dhul-biyoodka; dhegayso codkooda meel fog laga maqlo.', 'Taageer ilaalinta dhul-biyoodka aan la qalajin ee ay ku tarmaan.', 'Meelaha ay buulka ka sameeyaan meel fog ka fiiri — way ka tagaan haddii la dhibo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'so', 'Xuur cad oo qaylo badan', 'Nolosha oo dhan hal lammaane bay la joogaan, imaatinkoodana cod dheer bay ku sheegaan.', 'Gu’ga iyo dayrta harooyinka iyo beeraha biyaha ka buuxaan, badanaa qoys ahaan.', 'Taageer in xeebaha gaabinta ah iyo beeraha qoyan aan la qalajin.', 'Weligaa rooti ha siin — way waxyeelleysaa; barafka korkiisana meel ka fogow.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'so', 'Boolboolo madax-cagaaran', 'Dhashu waxay dabaali karaan oo is-quudin karaan saacado gudahood markay dhalaan.', 'Sannadka oo dhan ku dhawaad har, haro, ama webi socod gaabis ah kasta.', 'Haddii aad quudiso, isticmaal galley, digir, ama abuur halkii rooti.', 'Eeyaha biyaha ka fogee halka ay gu’ga buulka ka sameeyaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'so', 'Gorgor caadi ah', 'Baalal ballaaran bay ku duulaan, waxayna dhawaaqaan cod bisad u eg.', 'Gu’ga ilaa dayrta; fiiri iyagoo wareegaya beeraha iyo geesaha kaynta korkooda.', 'Taageer cawska qallafsan iyo geesaha beeraha ee jiirarka yaryar ku nool yihiin.', 'Weligaa ha isticmaalin sunta jiirka — silsiladda cuntada ayay kor ugu socotaa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'so', 'Gorgor kalluun-qabsade', 'Cagaha ayay hore ugu dhacaan si ay kalluun u qabtaan, waxayna qaadi karaan wax nuskooda le’eg.', 'Gu’ga ilaa dayrta harooyinka waaweyn; fiiri markay hawada joogsadaan kadibna dhacaan.', 'Taageer sameynta goobo buul oo tiirar dhaadheer lagu dhigo harooyinka kalluunka badan.', 'Goobaha buulka meel fog ka ilaali si lammaanuhu ugaan ukuntooda ka carrarin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'so', 'Dawaco cas', 'Waxay ka faa’iidaystaan birlabta dhulka si ay u qiyaasaan boodada ugaadha qarsoon.', 'Sannadka oo dhan, waxay ugu firfircoon yihiin waaberiga iyo fiidkii geesaha kaynta.', 'Ku dhaaf gees duurjoog ah oo deggan oo ay ku nasan karaan godna ka qodan karaan.', 'Qashinka xir, hana uga tegin cunto waxyeello leh.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'so', 'Cirridle Yurub', 'Hal habeen waxay ku socon karaan laba kiiloomitir cunto raadis.', 'Gu’ga ilaa dayrta habeenkii; jiilaalka waxay hurdaan caleemo iyo qoryo hoostooda.', 'Xayndaabka ka samee dalool 13 sm ah si ay beero u kala dhex mari karaan.', 'Hubi cawska dheer ka hor intaanad jarin, caleemahana u dhaaf hurdada jiilaalka.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'so', 'Deero yar oo kaynta', 'Uurka way dib u dhigaan si dhashu had iyo jeer xagaaga hore u dhalato.', 'Sannadka oo dhan geesaha kaynta, waxaa ugu badan in la arko waaberiga iyo fiidkii.', 'Taageer geesaha beeraha aan la jarin iyo duurka oo hoy iyo cunto siiya.', 'Eeyaha xidho kaynta agteeda xagaaga hore markay dhashu qarsoon tahay.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'so', 'Deero weyn (muus)', 'Waa deerada ugu weyn adduunka; lab weyni wuxuu ka culus yahay nus tan.', 'Sannadka oo dhan kaynta iyo dhul-biyoodka, waxay ugu firfircoon yihiin waaberiga iyo fiidkii.', 'Taageer kaynta isku xidhan iyo marinnada dhul-biyoodka ay u baahan yihiin.', 'Si taxaddar leh u wad waaberiga iyo fiidkii waddooyinka kaynta, dhashana ha u dhowaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'so', 'Dabagaale cas', 'Waxay dhisaan buulal badan oo ay is dhaafsadaan.', 'Sannadka oo dhan kaynta, waxay ugu firfircoon yihiin subaxa hore.', 'Ku dhaaf miraha geedaha iyo geedaha taagan ee ay ka cunaan buulkana ka sameeyaan.', 'Eeyaha waddada ku hay, geedaha buul lagu qariyo ha carqaladayn.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'so', 'Biifar Yurub', 'Biyo-xidhkoodu wuxuu abuuraa dhul-biyood kordhiya kalluun, shimbiro iyo cayayaan.', 'Gu’ga ilaa dayrta dambe webiyada gaabiska ah, waxay ugu firfircoon yihiin fiidkii.', 'Taageer in biyo-xidhka iyo geedaha xeebta meeshooda laga tago halka ay ammaan tahay.', 'Ka fogow guryahooda iyo biyo-xidhka, gaar ahaan markay dhashu yaryar tahay.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'so', 'Bakayle buuraleyda', 'Jiilaalka dhogortoodu way caddaataa si ay barafka ugu qariso.', 'Sannadka oo dhan dhulka furan iyo bannaanka kaynta, badanaa waaberiga iyo fiidkii.', 'Taageer isku darka dhul furan iyo hoy oo ay sannadka oo dhan u baahan yihiin.', 'Eeyaha xidho dhulka furan si aan loo eryin bakaylaha nasanaya.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'so', 'Baajar Yurub', 'Qoys ahaan bay ku noolaadaan godad dhulka hoostiisa ah oo jiil ilaa jiil la isticmaalo.', 'Gu’ga ilaa dayrta habeenkii kaynta agteeda; jiilaalka badankiis way seexdaan.', 'Ku dhaaf kaymaha iyo xayndaabyada aan la carqaladayn si ay god u qodan karaan.', 'Weligaa ha xidhin ama u dhowaan god firfircoon — waa gurigooda joogtada ah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'so', 'Fiidmeer yar', 'Fiidmeerkan yar wuxuu hal habeen cuni karaa ilaa 3,000 kaneeco iyo cayayaan yaryar.', 'Fiidkii xagaaga, fiiri duulimaadkooda dhaqsaha badan ee beeraha korkooda.', 'Sanduuq fiidmeer ku dhig meel sare oo qorraxda fiidka hesho.', 'Iska ilaali nalalka iftiinka badan albaabbada hoygooda, cirkana mugdi u dhaaf.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'so', 'Balanbaalis diin-midabka ah', 'Jiilaalka way seexdaan iyagoo weyn, badanaa bakhaarrada iyo saqafyada hoostooda.', 'Gu’ga hore ilaa dayrta ubaxyada qorraxda leh, gaar ahaan haramaha.', 'Gees qorrax leh ku dhaaf haramo — dirxigoodu way u baahan yihiin.', 'Kuwa jiilaalka hurda ee bakhaarrada ku jira ha carqaladayn.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'so', 'Balanbaalis daa’uus', 'Dhibcaha isha u eg way baqdin geliyaan shimbiraha, baalashooduna cod bay dhigaan.', 'Gu’ga ilaa dayrta maalmaha qorraxda leh, waxay cunaan ubaxyo iyo miro dhacay.', 'U dhaaf gees haramo ah oo qorrax leh dirxigooda.', 'Ha carqaladayn kuwa jiilaalka ku hoyda bakhaarrada iyo qoryaha.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'so', 'Balanbaalis huruud ah', 'Magaca Ingiriisiga ee balanbaalista waxaa laga yaabaa inuu ka yimid midabka labka huruudka ah.', 'Mid ka mid ah kuwa ugu horreeya gu’ga; raadi geesaha kaynta maalmaha diiran.', 'Taageer geedaha xayndaabka ee ay dirxigoodu keliya cunaan.', 'Ha nadiifin xayndaabyada duurjoogta ah ee jiilaalka ay ku hoydaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'so', 'Balanbaalis baalasha oranji leh', 'Labka keliya ayaa leh baalal caarradoodu oranji tahay; dheddigu waa cad.', 'Gu’ga berrimaha qoyan iyo waddooyinka ay ubaxyadu ka baxaan.', 'U dhaaf ubaxyada duurjoogta ah inay ka baxaan geesaha qoyan ee aan la jarin.', 'Dib u dhig jarista geesaha waddada ilaa dirxigu cunista dhammeeyo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'so', 'Balanbaalis buluug ah', 'Qudhaanjadu mararka qaar way ilaaliyaan dirxigooda si ay macaanka uga helaan.', 'Gu’ga dambe berrimaha qorraxda leh ee ubaxyada macaan badan yihiin.', 'Ku dhaaf berrimaha aan la jarin si ubaxyadu u baxaan.', 'Ha buufin sunta cawska berrimaha ubaxyada duurjoogta badan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'so', 'Balanbaalis cad oo xidido cagaar leh', 'In kasta oo ay u eg tahay balanbaalista kaabashka, waxay doorbidaan dhirta duurjoogta ah.', 'Gu’ga ilaa xagaaga dambe berrimaha qoyan, godadka iyo waddooyinka kaynta.', 'U dhaaf geesaha qoyan inay duurjoog noqdaan iyagoo dhir maxalli ah leh.', 'Ha qalajin ama buufin berrimaha qoyan ee ay ku tarmaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'so', 'Kaneeco toddoba-dhibcood', 'Hal mid noloshiisa wuxuu cuni karaa kumanaan cayayaan yaryar oo dhirta waxyeeleeya.', 'Gu’ga ilaa dayrta dhirta cayayaanku ku jiro; jiilaalka way isu tagaan.', 'U dulqaado cayayaan yar oo dhirta jooga hana buufin si cunto ay u helaan.', 'Ku dhaaf caleemaha dhacay iyo jirridaha godan ee ay jiilaalka ku hoydaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'so', 'Shinni weyn dabo-huruud ah', 'Boqoraddu waa kuwa ugu horreeya ee gu’ga soo baxa, hoosna way u guuxaan iyagoo god raadinaya.', 'Gu’ga hore ilaa dayrta ubaxyada; boqoraddu gu’ga waxay baaraan xayndaabka hoostiisa.', 'Beero ama u dhaaf dhirta hore u ubaxda, cawskana u dhaaf inuu ubaxdo.', 'Ku dhaaf kaymaha iyo godadka jiirka ee hore ee ay buulka ka sameeyaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'so', 'Shinnida malabka', 'Shinnidu waxay xeradda ku tustaa meesha ubaxyadu joogaan iyadoo qoob-ka-cayaar sideed u eg samaynaysa.', 'Gu’ga ilaa dayrta ubaxyada maalmaha diiran ee aan dabayl lahayn.', 'U dhaaf ubaxyo kala duwan inay xilliyada oo dhan baxaan, biyo gaabanna dhig.', 'Ha buufin dhirta ubaxda, weligaana ha buufin duhurkii.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'so', 'Diqsi-weyne boqortooyo', 'Mid ka mid ah kuwa ugu waaweyn Yurub, wuxuuna ugaadh ku qaban karaa hawada.', 'Maalmaha xagaaga diiran, fiiri isagoo wareegaya harooyinka geesahooda.', 'Hayso ama qod har dhir leh, geesihiisana dhir ku dhaaf.', 'Ka ilaali harooyinka wasakhda si dirxigu u koro.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'so', 'Diqsi-weyne yar oo dhaqso leh', 'Badanaa isla meeshii diirran bay fadhiistaan, kadibna u boodaan cayayaanka soo maraya.', 'Bartamaha xagaaga ilaa dayrta biyaha xasilloon agtooda, waxay ku qorraxdaan waddooyinka.', 'Ku dhaaf meelo qorrax leh iyo dhir agagaarka harooyinka iyo godadka.', 'Ha u oggolaan bacriminta ama saliidda inay harooyinka ku dhacdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'so', 'Qudhaanjo cas oo kaynta', 'Buulashoodu waxay ka dhaafi karaan mitir sarahood, waxaana ku nool nus milyan qudhaanjo.', 'Gu’ga ilaa dayrta kaynta; raadi tuulmooyin geed-caleemo ah oo qaabaysan.', 'Ku dhaaf buulashooda sida ay yihiin — sannado ayay dhisidoodu qaadataa.', 'Ku sii soco waddada, hana laadin ama qodin tuulmada qudhaanjada.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'so', 'Ubax kaynta oo cad', 'Aad bay u gaabis u fidaan, sidaas darteed roog buuxa wuxuu tilmaamayaa kayn aad u da’ weyn.', 'Gu’ga, raadi roogag ubax cad ah ka hor inta geeduhu caleemo yeelan.', 'Ku dhaaf dhulka kaynta sida uu yahay si xididdada gaabiska ah u koraan.', 'Halka ay ka baxaan ka daawo — goynta waxay meesha ka saaraysaa ubax sannado qaatay.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'so', 'Ubax dooxada', 'Qayb kasta oo dhirtan udgoon waa sun haddii la cuno.', 'Gu’ga dambe, urta raac ilaa kaynta hooska leh iyo beeraha hooska ah.', 'Ku dhaaf geesaha kaynta hooska leh iyo caleemaha halka ay ka baxdo.', 'Ha goyn ama rujin, carruurta iyo xayawaanka gurigana ka fogee.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'so', 'Toon duurjoog ah', 'Badanaa urta ayaad maqashaa ka hor inta aadan ubaxyada caddaanka ah arag.', 'Gu’ga, raadi caleemo ballaaran oo cagaar ah iyo ubaxyo xiddig u eg kaynta qoyan.', 'Ku dhaaf kaynta qoyan sida ay tahay si roogagu sannad kasta dib u soo baxaan.', 'Haddii goynta halkaas la oggol yahay, wax yar qaado, xididdadana ha rujin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'so', 'Ubax dhoobada oo dahab ah', 'Mid ka mid ah dhirta ugu da’da weyn — waxay ka badbaaday barafowgii ugu dambeeyay Iskandineefiya.', 'Gu’ga, raadi ubax dahab ah oo waaweyn dhoobada, godadka iyo geesaha harooyinka.', 'Ku hay geesaha harooyinka iyo godadka qoyan oo aan la jarin si ay u ubaxdo.', 'Ha qalajin dhulka qoyan, dhirtana halkeeda uga tag.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'so', 'Ubax gu’ga oo huruud ah', 'Mar bay berrimaha cawska ku badnaayeen sida carruurtu kubbado ka samayn jireen.', 'Gu’ga, raadi ubax huruud ah oo foororsan berrimaha hore ee aan wax laga bedelin.', 'Ha jarin berrimaha ilaa ay ubaxdo oo abuur samayso.', 'Ha goyn ama duurka ka rujin — ubaxyada berrimuhu way yaraanayaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'so', 'Ubax daysi weyn', 'Ubaxa muuqda dhab ahaan waa daraasiin ubax oo yaryar oo isku dhow.', 'Xagaaga, raadi ubax cad oo waaweyn geesaha waddooyinka iyo berrimaha.', 'Ku dhaaf xarig caws ah oo aan la jarin bartamaha xagaaga si ay u ubaxdo.', 'Ha buufin sunta cawska geesaha waddooyinka iyo berrimaha.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'so', 'Ubax daandeleen', 'Waa mid ka mid ah ilaha malabka ee ugu muhiimsan shinnida xilliga hore.', 'Gu’ga wixii ka dambeeya meel kasta; ubaxyadu qorraxda way furmaan fiidkiina way xidhmaan.', 'U dhaaf inay cawska ka baxaan gu’ga ka hor jaridda ugu horraysa.', 'Ha isticmaalin sunta cawska si cayayaanka wax dhaliya cuntadan muhiimka ah u helaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'so', 'Geed xeedho ah', 'Hal geed wuxuu soo saari karaa in ka badan boqol kun oo abuur oo yaryar.', 'Xagaaga dambe, raadi roogag guduud ah dhulka furan iyo dhoobada.', 'Taageer in dhulka geedkan uu furan yahay oo aan la qalajin.', 'Ku sii soco waddooyinka, dab hana shidin marka ay qalalan tahay.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'so', 'Miro buluug ah oo duurjoog', 'Faraha way buluugiyaan, waxayna quudiyaan wax kasta oo shimbiro ilaa orso ah.', 'Xagaaga, raadi geedo gaagaaban oo miro madow leh kaynta.', 'Ku dhaaf dhirta hoose ee kaynta sida ay tahay si geeduhu miro u dhalaan.', 'Haddii goynta halkaas la oggol yahay, miro badan ugu tag duurjoogta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'so', 'Miro cas oo duurjoog', 'Bilo bay raagaan iyagoo fiican, waana walax dabiici ah oo miraha ku jirta.', 'Xagaaga dambe iyo dayrta, raadi miro casaan dhalaalaya oo roogag cagaar ah.', 'Ku dhaaf dhirta dhulka kaynta sida ay tahay si roogagu u fidaan.', 'Haddii goynta la oggol yahay, si taxaddar leh u soco si aanad dhirta u burburin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'so', 'Geed biirij lacag ah', 'Hal geed wuxuu quudiyaa boqollaal nooc oo cayayaan ah, taasna waxay quudisaa shimbiro badan.', 'Sannadka oo dhan; jiirka cad ee iska diirta ayaa fudud in la garto xilli kasta.', 'Ku dhaaf caleemaha dhacay iyo qoryaha dhintay si ay ciidda u barwaaqoobaan.', 'Ha ka rujin jiirka, waxay geedka dhaawacdaa oo daciifisaa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'so', 'Geed sabruus Noorway', 'Geed Iswiidhan ku yaal wuxuu ka baxay xidido kumanaan sano jir ah.', 'Sannadka oo dhan kaynta; miraha foororsan ee geedkan waa kuwa ugu dhaadheer.', 'Ku dhaaf miraha dhacay iyo qoryaha dhintay, waxay hoy u yihiin cayayaan iyo boqoshaad.', 'Ku sii soco waddooyinka kaynta si aad uga ilaaliso xididdada dushiisa ah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'so', 'Geed baynuus Iskotland', 'Geedaha da’da weyn korkoodu wuxuu u dhalaalaa oranji, waxayna noolaan karaan qarniyo.', 'Sannadka oo dhan dhulka ciidda iyo dhagaxa leh; raadi jiirka oranjiga ah ee sare.', 'Ku dhaaf qoryaha dhintay ee taagan iyo geedaha da’da weyn, waa nolol badan.', 'Weligaa dab ha ka shidin geedahan agtooda dhulka ciidda qalalan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'so', 'Kalluun bayk woqooyi', 'Waa ugaadhsade gaadmo ah oo isla markiiba ka boodi kara xasilloonaan.', 'Gu’ga ilaa dayrta biyaha gaabinta ah ee cawska leh ee harooyinka iyo webiyada.', 'Taageer in cawska biyaha iyo dhirta lagu hayo halka kalluunka yaryar ku dhuunto.', 'Wasakhda iyo qashinka biyaha ka fogee; raac xeerarka kalluumaysiga maxalliga ah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'so', 'Kalluun beerj Yurub', 'Koox ahaan bay ugaadhsadaan, xariiqyadooda madowna qaabkooda way qariyaan.', 'Bilaha diiran agagaarka biriijyada, cawska iyo meelaha biyuhu hoos u dhacaan.', 'Taageer biyo nadiif ah iyo dhirta biyaha hoosteeda ee kalluunka yaryar dhowrta.', 'Waxba ha ku tuurin harooyinka iyo webiyada; raac xeerarka kalluumaysiga maxalliga ah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'so', 'Kalluun rooj', 'Waa cunto muhiim ah oo ugaadhsadayaal badan oo harooyinka ku nool ku tiirsan yihiin.', 'Bilaha diiran, koox ahaan dusha sare ee harooyinka iyo webiyada gaabiska ah.', 'Taageer in biyuhu nadiif ahaadaan geesahana dhir leeyihiin si ay u tarmaan.', 'Biyaha ka ilaali qashinka; raac xeerarka kalluumaysiga maxalliga ah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'fa', 'بادخورک معمولی', 'بادخورک‌ها می‌توانند ماه‌ها پیوسته در هوا بمانند و حتی در حال پرواز بخوابند.', 'در غروب‌های گرم تابستان، بالای بام‌ها را بنگرید و به دسته‌های پرهیاهو گوش بسپارید.', 'پیش از بازگشت پرندگان در بهار، جعبه لانه‌ای زیر لبه بام نصب کنید.', 'هنگام بازسازی ساختمان، شکاف‌های کوچک زیر لبه بام را که محل لانه است حفظ کنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'fa', 'پرستوی خانگی', 'پرستوی خانگی هر سال تا جنوب آفریقا کوچ می‌کند و بازمی‌گردد.', 'از بهار تا اوایل پاییز، آن را در پرواز کم‌ارتفاع بر فراز مزارع و آب‌ها ببینید.', 'در انبار یا طویله را کمی باز بگذارید تا به لبه‌های لانه‌سازی برسد.', 'لانه‌های گِلی کهنه را خراب نکنید؛ پرستوها سال‌به‌سال از آن‌ها دوباره استفاده می‌کنند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'fa', 'فاخته', 'فاخته تخم‌هایش را در لانه پرندگان دیگر می‌گذارد و هرگز جوجه‌های خود را بزرگ نمی‌کند.', 'در اواخر بهار، به آوای دوردست «کوکو» از حاشیه جنگل گوش بسپارید.', 'از مرغزارها و پرچین‌های پر از حشره که غذای پرندگان میزبان را تأمین می‌کنند حمایت کنید.', 'نزدیک بوته‌زارها و نیزارها در مسیرها بمانید تا پرندگان میزبان آزرده نشوند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'fa', 'سینه‌سرخ اروپایی', 'سینه‌سرخ‌ها به‌شدت از قلمرو خود دفاع می‌کنند و کنار چراغ‌های خیابان تا شب می‌خوانند.', 'همه سال در باغ‌ها و جنگل‌ها؛ اغلب به دنبال کسی می‌روند که خاک را زیر و رو می‌کند.', 'گوشه‌ای از باغ را با برگ‌های ریخته رها کنید تا در آن دنبال غذا بگردند.', 'هرس سنگین پرچین را تا پایان فصل لانه‌سازی در اواخر تابستان به تعویق بیندازید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'fa', 'توکای سیاه', 'آواز پرمایه و نی‌مانند نر یکی از شناخته‌شده‌ترین آواهای اروپاست.', 'همه سال؛ سپیده‌دم و غروب به نرها که از بام‌ها و نوک درختان می‌خوانند گوش دهید.', 'به‌ویژه در دوره‌های خشکی، آب تازه برای نوشیدن و آبتنی بگذارید.', 'در فصل لانه‌سازی، گربه‌ها را سپیده‌دم داخل خانه نگه دارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'fa', 'توکای مزرعه', 'توکای مزرعه پرنده‌ای اجتماعی است که زمستان‌ها در دسته‌های پرهیاهو می‌گردد.', 'در پاییز و زمستان، دسته‌ها را ببینید که میوه پرچین‌ها و درختان را می‌چینند.', 'بوته‌های میوه‌دار را در طول زمستان هرس نکنید.', 'سیب‌های افتاده را در زمستان روی زمین بگذارید؛ در سرما غذایی حیاتی‌اند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'fa', 'چرخ‌ریسک بزرگ', 'چرخ‌ریسک بزرگ گنجینه آوایی گسترده‌ای دارد و آواهای تازه را از همسایگانش می‌آموزد.', 'همه سال؛ از اواخر زمستان به آواز زنگ‌دار و تکرارشونده‌اش گوش دهید.', 'جعبه لانه‌ای با سوراخ ۳۲ میلی‌متری در جایی آرام و سایه‌دار بیاویزید.', 'از سموم باغی بپرهیزید تا کرم‌های کافی برای خوراک جوجه‌ها بماند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'fa', 'چرخ‌ریسک آبی', 'یک دسته جوجه چرخ‌ریسک آبی می‌تواند بیش از هزار کرم بخورد.', 'همه سال در باغ‌ها و جنگل‌ها، اغلب وارونه از شاخه‌های نازک آویزان می‌شود.', 'جعبه کوچکی با سوراخ ۲۵ میلی‌متری دور از مسیر باد نصب کنید.', 'در بهار از حشره‌کش استفاده نکنید تا کرم‌ها برای جوجه‌ها در دسترس باشند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'fa', 'سهره جنگلی', 'آواز سهره از منطقه‌ای به منطقه دیگر فرق می‌کند، تقریباً مانند لهجه‌های محلی.', 'از بهار تا پاییز؛ نرها عبارتی روشن و رو به پایین را از جایگاه‌های باز می‌خوانند.', 'بخشی از خوشه‌های بذر و لکه‌های علفی را در طول فصل برجا بگذارید.', 'ظرف‌های دانه را تمیز نگه دارید تا بیماری میان سهره‌ها پخش نشود.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'fa', 'زاغ بلوط', 'هر پاییز هزاران بلوط دفن می‌کند و با فراموش کردن برخی، جنگل‌های بلوط می‌کارد.', 'همه سال در جنگل بلوط؛ در پاییز مراقب برق رنگ‌های صورتی و آبی باشید.', 'بلوط‌های افتاده و برگ‌های زیر درختان را دست‌نخورده بگذارید.', 'سگ‌ها را در جنگل روی مسیر نگه دارید تا پرندگانِ زمین‌چر رمانده نشوند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'fa', 'دارکوب خالدار بزرگ', 'تق‌تق بهاری‌اش برای غذا نیست؛ ضرب تندی است برای اعلام قلمرو.', 'همه سال؛ در اواخر زمستان به پژواک تق‌تق در میان درختان گوش دهید.', 'چوب‌های خشک سرپا را رها کنید؛ حشراتی که غذایش‌اند در آن‌ها زندگی می‌کنند.', 'درختان مرده یا در حال خشک شدن را قطع نکنید؛ ممکن است لانه در آن‌ها باشد.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'fa', 'دم‌جنبانک سفید', 'جنبش پیوسته دم شاید نشانه هوشیاری در برابر شکارچیان باشد.', 'از بهار تا پاییز کنار آب و زمین باز؛ می‌دود و می‌ایستد تا حشره بگیرد.', 'کنار آب تکه‌ای چمن کوتاه یا شن نگه دارید تا در آن دنبال غذا بگردد.', 'ساحل‌های سنگریزه‌ای را که محل تغذیه و لانه است بر هم نزنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'fa', 'درنای خاکستری', 'در اوایل بهار رقص جفت‌گیری با پرش و تعظیم اجرا می‌کند.', 'از بهار تا پاییز پیرامون تالاب‌ها؛ به بانگ شیپورمانندش که تا دوردست می‌رود گوش دهید.', 'از حفاظت مرداب‌ها و مرغزارهای مرطوب زهکشی‌نشده که محل زادآوری است حمایت کنید.', 'تالاب‌های لانه‌سازی را از فاصله تماشا کنید؛ درنا لانه آزرده را رها می‌کند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'fa', 'قوی فریادکش', 'قوی فریادکش تا پایان عمر جفت می‌ماند و ورودش را با بانگ بلند اعلام می‌کند.', 'بهار و پاییز روی دریاچه‌ها و مزارع آب‌گرفته، اغلب به‌صورت خانوادگی.', 'از حفظ حاشیه‌های کم‌عمق دریاچه و مزارع مرطوب بدون زهکشی حمایت کنید.', 'هرگز به قوها نان ندهید؛ زیانبار است. روی یخ نیز فاصله را حفظ کنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'fa', 'اردک سرسبز', 'جوجه‌ها چند ساعت پس از تخم‌گشایی می‌توانند شنا کنند و خود غذا بخورند.', 'همه سال در تقریباً هر برکه، دریاچه یا رود کم‌جریان.', 'اگر غذا می‌دهید، به‌جای نان از جو دوسر، نخود یا دانه استفاده کنید.', 'در بهار سگ‌ها را از آبی که اردک‌ها در آن لانه دارند دور نگه دارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'fa', 'سارگپه معمولی', 'با بال‌های پهن اوج می‌گیرد و بانگی شبیه میو گربه سر می‌دهد.', 'از بهار تا پاییز؛ بالای مزارع و حاشیه جنگل دنبال چرخ زدنش بگردید.', 'از علفزارهای خشن و حاشیه مزارع که موش‌های صحرایی در آن‌ها زندگی می‌کنند حمایت کنید.', 'هرگز از سم جوندگان استفاده نکنید؛ در زنجیره غذایی به پرندگان شکاری می‌رسد.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'fa', 'عقاب ماهی‌خوار', 'با پاها ابتدا شیرجه می‌زند تا ماهی بگیرد و می‌تواند شکاری به نیمِ وزن خود ببرد.', 'از بهار تا پاییز کنار دریاچه‌های بزرگ؛ ابتدا در هوا معلق می‌ماند و سپس شیرجه می‌رود.', 'از نصب سکوهای لانه روی تیرهای بلند نزدیک دریاچه‌های پرماهی حمایت کنید.', 'از سکوهای لانه فاصله زیاد بگیرید تا جفت‌ها تخم‌ها را رها نکنند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'fa', 'روباه قرمز', 'روباه از میدان مغناطیسی زمین برای سنجش جهش به‌سوی شکار پنهان کمک می‌گیرد.', 'همه سال، فعال‌تر در سپیده‌دم و غروب در حاشیه جنگل و مزرعه.', 'گوشه‌ای وحشی و آرام بگذارید تا روباه بیاساید و لانه بسازد.', 'سطل زباله را محکم ببندید و هرگز پس‌مانده زیان‌آور برای روباه‌ها نگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'fa', 'خارپشت اروپایی', 'خارپشت در یک شب جست‌وجو می‌تواند دو کیلومتر راه برود.', 'از بهار تا پاییز پس از تاریکی؛ زمستان زیر توده برگ و کنده می‌خوابد.', 'در حصار شکافی به عرض ۱۳ سانتی‌متر باز کنید تا میان باغ‌ها رفت‌وآمد کند.', 'پیش از چیدن علف بلند آن را وارسی کنید و توده برگ را برای خواب زمستانی بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'fa', 'آهوی اروپایی', 'آبستنی را به تأخیر می‌اندازد تا بره‌ها همیشه در اوایل تابستان به دنیا بیایند.', 'همه سال در حاشیه جنگل، بیشتر هنگام چرا در سپیده‌دم و غروب دیده می‌شود.', 'از حاشیه‌های نچیده مزارع و بوته‌زارهایی که پناه و غذا می‌دهند حمایت کنید.', 'در اوایل تابستان که بره‌ها پنهان‌اند، سگ‌ها را نزدیک جنگل ببندید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'fa', 'گوزن شمالی بزرگ (موس)', 'بزرگ‌ترین گوزن جهان است؛ یک نر تنومند بیش از نیم تن وزن دارد.', 'همه سال در جنگل‌ها و تالاب‌ها، فعال‌تر در سپیده‌دم و غروب.', 'از پیوستگی جنگل‌ها و دالان‌های تالابی که برای جابه‌جایی لازم دارد حمایت کنید.', 'در جاده‌های جنگلی سپیده‌دم و غروب با احتیاط برانید و هرگز به بره نزدیک نشوید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'fa', 'سنجاب قرمز', 'چند لانه می‌سازد و میان آن‌ها جابه‌جا می‌شود.', 'همه سال در جنگل‌های سوزنی‌برگ و آمیخته، پرکارتر در اول صبح.', 'مخروط‌ها، مغزها و درختان سرپا را که غذا و لانه‌اند رها کنید.', 'سگ‌ها را روی مسیر نگه دارید و درختانی را که ممکن است لانه داشته باشند بر هم نزنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'fa', 'سگ آبی اروپایی', 'سدهایش تالاب‌هایی می‌سازد که تا فرسنگ‌ها ماهی، پرنده و حشره را پررونق می‌کند.', 'از بهار تا اواخر پاییز کنار رودهای کم‌جریان، فعال‌تر هنگام غروب.', 'از باقی‌ماندن سدها و درختان کنار آب در جایی که ایمن است حمایت کنید.', 'از لانه‌ها و سدها دور بمانید، به‌ویژه وقتی بچه‌ها کوچک‌اند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'fa', 'خرگوش کوهی', 'زمستان‌ها برای استتار روی برف سفید می‌شود.', 'همه سال در زمین باز و روشنگاه جنگل، بیشتر سپیده‌دم و غروب.', 'از آمیزه‌ای از زمین باز و پوشش که در طول سال لازم دارد حمایت کنید.', 'در زمین باز سگ‌ها را ببندید تا خرگوش‌های در حال استراحت دنبال نشوند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'fa', 'گورکن اروپایی', 'گروهی خانوادگی در لانه‌های زیرزمینی زندگی می‌کند که نسل‌به‌نسل به‌کار می‌رود.', 'از بهار تا پاییز پس از تاریکی نزدیک جنگل؛ زمستان را می‌خوابد.', 'کناره‌ها و پرچین‌های دست‌نخورده را بگذارید تا در آن‌ها لانه بکَند.', 'هرگز لانه فعال را مسدود نکنید و کنارش نکَنید؛ خانه درازمدت اوست.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'fa', 'خفاش کوتوله', 'این خفاش کوچک می‌تواند در یک شب تا ۳۰۰۰ پشه و حشره ریز بخورد.', 'در غروب‌های تابستان، پرواز تند و پرپیچ‌وخم آن را بالای باغ‌ها ببینید.', 'جعبه خفاش را بالای دیوار یا درختی که آفتاب غروب می‌گیرد نصب کنید.', 'از نور شدید بر دهانه پناهگاه بپرهیزید و آسمان شب را تاریک نگه دارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'fa', 'پروانه لاک‌پشتی کوچک', 'این پروانه به‌صورت بالغ خواب زمستانی می‌رود، اغلب در انبارها و زیرشیروانی‌ها.', 'از اوایل بهار تا پاییز روی گل‌های آفتاب‌گیر، به‌ویژه گزنه.', 'تکه‌ای گزنه در گوشه‌ای آفتاب‌گیر بگذارید؛ کرم‌هایش به آن نیاز دارند.', 'پروانه‌های خفته در انبارها را در طول زمستان بی‌آزار بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'fa', 'پروانه طاووسی', 'خال‌های چشم‌مانندش پرندگان را می‌رماند و بال‌هایش هنگام باز شدن صدا می‌دهد.', 'از بهار تا پاییز در روزهای آفتابی، روی خار و میوه‌های افتاده.', 'بگذارید تکه‌ای گزنه آفتاب‌گیر برای کرم‌هایش بروید.', 'بالغ‌هایی را که زمستان در انبار و توده هیزم پناه گرفته‌اند بر هم نزنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'fa', 'پروانه گوگردی', 'گفته‌اند نام انگلیسی پروانه شاید از رنگ زرد کره‌ای نرِ این گونه آمده باشد.', 'از نخستین پروانه‌های بهار؛ در روزهای گرم حاشیه جنگل را بگردید.', 'از بوته‌های خارمقدس در پرچین‌ها حمایت کنید؛ تنها خوراک کرم‌هایش است.', 'پرچین‌های بوته‌ای را که پناه زمستانی بالغ‌هاست پاکسازی نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'fa', 'پروانه نوک‌نارنجی', 'تنها نرها نوک بال نارنجی روشن دارند؛ ماده‌ها سفیدند.', 'در بهار در مرغزارهای مرطوب و کوره‌راه‌هایی که گل‌های وحشی می‌رویند.', 'بگذارید گل‌های وحشی در گوشه‌های مرطوب و نچیده برویند.', 'چیدن حاشیه جاده‌ها را تا پایان تغذیه کرم‌ها به تعویق بیندازید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'fa', 'پروانه آبی معمولی', 'گاهی مورچه‌ها از کرم‌هایش در ازای ترشحات شیرین نگهداری می‌کنند.', 'از اواخر بهار در مرغزارهای آفتاب‌گیر پر از شبدر.', 'مرغزار را نچینید تا شبدرها گل بدهند.', 'مرغزارهای پر از گل وحشی را با علف‌کش سم‌پاشی نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'fa', 'پروانه سفید رگ‌سبز', 'با آنکه شبیه پروانه سفید کلم است، گیاهان وحشی را به محصولات باغی ترجیح می‌دهد.', 'از بهار تا اواخر تابستان در مرغزارهای مرطوب، آبراهه‌ها و گذرهای جنگلی.', 'بگذارید گوشه‌های مرطوب با گیاهان بومی وحشی شوند.', 'مرغزارهای مرطوب محل زادآوری‌اش را زهکشی و سم‌پاشی نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'fa', 'کفشدوزک هفت‌خال', 'یک کفشدوزک در طول عمرش هزاران شته می‌خورد.', 'از بهار تا پاییز روی گیاهان شته‌زده؛ زمستان دسته‌جمعی می‌خوابند.', 'کمی شته را تحمل کنید و سم‌پاشی نکنید تا خوراکشان فراهم باشد.', 'ساقه‌های توخالی و برگ‌های ریخته را که زمستان در آن پناه می‌گیرند بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'fa', 'زنبور درشت دم‌نخودی', 'ملکه‌ها از نخستین زنبورهای بهارند و کم‌ارتفاع وزوزکنان دنبال سوراخ لانه می‌گردند.', 'از اوایل بهار تا پاییز روی گل‌ها؛ ملکه‌ها بهار پای پرچین‌ها را می‌کاوند.', 'گیاهان زودگل را بکارید یا رها کنید و بگذارید شبدر در چمن گل بدهد.', 'کناره‌ها و سوراخ‌های کهنه موش را که محل کلنی است دست‌نخورده بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'fa', 'زنبور عسل غربی', 'زنبور جوینده با رقصی به شکل عدد هشت جای گل‌ها را به کندو نشان می‌دهد.', 'از بهار تا پاییز روی گل‌ها در روزهای گرم و بی‌باد.', 'بگذارید گل‌های گوناگون در طول فصول بشکفند و ظرف آب کم‌عمقی بگذارید.', 'گیاهان گل‌دار را سم‌پاشی نکنید و هرگز میانه روز سم نپاشید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'fa', 'سنجاقک امپراتور', 'از بزرگ‌ترین سنجاقک‌های اروپاست و می‌تواند شکار را در هوا بگیرد.', 'در روزهای گرم تابستان، گشت‌زنی‌اش را کنار برکه‌ها و حاشیه دریاچه ببینید.', 'برکه‌ای گیاه‌دار نگه دارید یا بکَنید و حاشیه‌اش را پوشیده بگذارید.', 'برکه‌ها را از آلودگی و روان‌آب دور نگه دارید تا نوزادها رشد کنند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'fa', 'سنجاقک تیرانداز معمولی', 'اغلب روی همان نقطه گرم می‌نشیند و برای گرفتن حشرات گذری بیرون می‌جهد.', 'از میانه تابستان تا پاییز کنار آب راکد، آفتاب‌گیری روی مسیرها و تیرها.', 'نشیمن‌های آفتاب‌گیر و پوشش گیاهی پیرامون برکه‌ها را رها کنید.', 'نگذارید کود یا روغن به برکه‌هایی که نوزادها در آن‌اند شسته شود.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'fa', 'مورچه قرمز جنگلی', 'تپه‌های لانه‌اش می‌تواند بیش از یک متر بلند باشد و نیم‌میلیون مورچه در خود جای دهد.', 'از بهار تا پاییز در جنگل سوزنی‌برگ؛ دنبال تپه‌های گنبدی از سوزن برگ بگردید.', 'تپه‌های لانه را دست‌نخورده بگذارید؛ ساختنشان سال‌ها طول می‌کشد.', 'روی مسیر بمانید و هرگز به تپه مورچه لگد نزنید و در آن نکَنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'fa', 'شقایق جنگلی', 'چنان کند پخش می‌شود که فرش انبوهش نشانه جنگلی کهن است.', 'در بهار، پیش از برگ دادن درختان دنبال فرش‌های گل سفید بگردید.', 'کف جنگل را دست‌نخورده بگذارید تا ریشه‌های کندروَش رشد کنند.', 'همان‌جا که می‌روید از آن لذت ببرید؛ چیدن گلی را می‌برد که سال‌ها برای پخش شدن وقت گذاشته.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'fa', 'موگه (سوسن دره)', 'همه بخش‌های این گیاه خوشبو در صورت خوردن سمی است.', 'در اواخر بهار، بوی آن را تا جنگل‌های سایه‌دار دنبال کنید.', 'حاشیه‌های سایه‌دار جنگل و برگ‌های ریخته را که در آن می‌روید رها کنید.', 'آن را نچینید و از ریشه درنیاورید؛ از کودکان و حیوانات خانگی دور نگه دارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'fa', 'سیر وحشی', 'اغلب پیش از دیدن گل‌های سفیدش، بوی سیر وحشی را حس می‌کنید.', 'در بهار، دنبال برگ‌های پهن سبز و گل‌های ستاره‌ای در جنگل مرطوب بگردید.', 'جنگل مرطوب را دست‌نخورده بگذارید تا فرش‌ها هر سال دوباره برویند.', 'اگر برداشت محلی مجاز است، اندکی بردارید و هرگز پیاز را درنیاورید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'fa', 'همیشه‌بهار مردابی', 'از کهن‌ترین گیاهان بومی است و از آخرین عصر یخبندان در اسکاندیناوی جان به‌در برده.', 'در بهار، دنبال گل‌های درشت طلایی در مرداب‌ها و حاشیه برکه‌ها بگردید.', 'حاشیه برکه‌ها و آبراهه‌ها را مرطوب و نچیده نگه دارید تا گل بدهد.', 'زمین مرطوب را زهکشی نکنید و گیاهان را همان‌جا که هستند بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'fa', 'پامچال بهاری', 'زمانی در مرغزارها چنان فراوان بود که کودکان از آن گوی می‌ساختند.', 'در بهار، دنبال گل‌های زرد سرافکنده در مرغزارهای کهن بگردید.', 'مرغزار را تا گل دادن و بذر بستن آن نچینید.', 'از طبیعت نچینید و درنیاورید؛ گل‌های مرغزار رو به کاهش‌اند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'fa', 'مینای بزرگ', 'آنچه یک گل به نظر می‌رسد در واقع ده‌ها گل ریز کنار هم است.', 'در تابستان، دنبال مینای سفید درشت در حاشیه جاده‌ها و مرغزارها بگردید.', 'نواری از چمن را در میانه تابستان نچیده بگذارید تا گل بدهد.', 'حاشیه جاده‌ها و مرغزارها را با علف‌کش سم‌پاشی نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'fa', 'قاصدک', 'قاصدک یکی از مهم‌ترین منابع شهد زودهنگام برای زنبورهاست.', 'از بهار به بعد تقریباً هر جا؛ گل‌ها در آفتاب باز و هنگام غروب بسته می‌شوند.', 'بگذارید قاصدک‌ها بهار پیش از نخستین چمن‌زنی گل بدهند.', 'از علف‌کش چمن پرهیز کنید تا گرده‌افشان‌های زودهنگام این خوراک حیاتی را داشته باشند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'fa', 'خلنگ', 'یک بوته خلنگ می‌تواند بیش از صد هزار بذر ریز تولید کند.', 'در اواخر تابستان، دنبال فرش‌های ارغوانی در خلنگ‌زارها و مرداب‌ها بگردید.', 'از باز و زهکشی‌نشده ماندن خلنگ‌زارها حمایت کنید.', 'در خلنگ‌زار روی مسیر بمانید و در هوای خشک هرگز آتش روشن نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'fa', 'بلوبری وحشی', 'انگشتان را آبی می‌کند و خوراک همه، از پرندگان تا خرس‌هاست.', 'در تابستان، دنبال بوته‌های کوتاه با میوه‌های تیره در جنگل کاج و صنوبر بگردید.', 'پوشش زیرین جنگل را دست‌نخورده بگذارید تا بوته‌ها میوه بدهند.', 'اگر چیدن محلی مجاز است، میوه فراوانی برای جانوران بگذارید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'fa', 'زغال‌اخته قرمز', 'به لطف ماده‌ای نگهدارنده در میوه، ماه‌ها سالم می‌ماند.', 'در اواخر تابستان و پاییز، دنبال میوه‌های قرمز براق روی فرش‌های همیشه‌سبز بگردید.', 'پوشش کف جنگل را دست‌نخورده بگذارید تا فرش‌ها گسترش یابند.', 'اگر چیدن مجاز است، با احتیاط قدم بردارید تا گیاهان له نشوند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'fa', 'توس نقره‌ای', 'یک درخت توس صدها گونه حشره را تغذیه می‌کند و آن‌ها خوراک پرندگان بی‌شمارند.', 'همه سال؛ پوست سفید و ورقه‌ورقه‌اش شناسایی را در هر فصل آسان می‌کند.', 'برگ‌های ریخته و چوب خشک را بگذارید تا خاک را غنی و حشرات را تغذیه کنند.', 'پوست درخت را نکَنید؛ زخمی و ناتوانش می‌کند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'fa', 'صنوبر نروژی', 'صنوبری در سوئد از ریشه‌هایی می‌روید که هزاران سال قدمت دارند.', 'همه سال در جنگل‌ها؛ مخروط‌های آویزانش بلندترین مخروط میان صنوبرهاست.', 'مخروط‌های افتاده و چوب خشک را بگذارید؛ پناه حشرات و قارچ‌هایند.', 'در جنگل روی مسیر بمانید تا ریشه‌های کم‌عمق صنوبر فشرده نشوند.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'fa', 'کاج اسکاتلندی', 'کاج‌های کهنسال نزدیک تاج نارنجی می‌درخشند و می‌توانند قرن‌ها زندگی کنند.', 'همه سال در زمین‌های شنی و سنگی؛ دنبال پوست نارنجی بالای تنه بگردید.', 'چوب خشک سرپا و کاج‌های کهن را رها کنید؛ سرشار از حیات‌اند.', 'هرگز کنار کاج‌ها روی زمین شنی خشک آتش روشن نکنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'fa', 'اردک‌ماهی شمالی', 'شکارچی کمین‌گر است و در یک چشم‌برهم‌زدن از سکون به جهش درمی‌آید.', 'از بهار تا پاییز در کم‌عمق‌های علف‌دار دریاچه‌ها و رودهای کم‌جریان.', 'از حفظ کم‌عمق‌های نیزار و گیاهان آبی که پناه بچه‌ماهی‌هاست حمایت کنید.', 'آلودگی و زباله را از آب دور نگه دارید؛ مقررات محلی ماهیگیری را رعایت کنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'fa', 'سوف اروپایی', 'گروهی شکار می‌کند و نوارهای پررنگش خط بدنش را می‌شکند.', 'در ماه‌های گرم پیرامون اسکله‌ها، علف‌زارهای آبی و شیب‌های زیرآب.', 'از آب پاک و ساختارهای زیرآبی که پناه بچه‌ماهی‌هاست حمایت کنید.', 'هرگز چیزی در دریاچه و رود نریزید؛ مقررات محلی ماهیگیری را رعایت کنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'fa', 'ماهی سرخ‌باله', 'ماهی خوراکی کلیدی است که بسیاری از شکارچیان دریاچه به آن وابسته‌اند.', 'در ماه‌های گرم، در دسته‌ها نزدیک سطح دریاچه‌ها و رودهای کم‌جریان.', 'از پاکی آب و پوشش گیاهی حاشیه‌ها برای تخم‌ریزی حمایت کنید.', 'روان‌آب و زباله را از آب دور نگه دارید؛ مقررات محلی ماهیگیری را رعایت کنید.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ti', 'ቅልጡፍ ነፋሪት ዑፍ', 'ንኣዋርሕ ኣብ ኣየር ክጸንሑ ይኽእሉ፣ ክነፍሩ እንከለዉ እውን ይድቅሱ።', 'ብሙቐት ምሸት ሓጋይ፣ ልዕሊ ናሕሲ ኣንቃዕሪርካ ጫውጫው ዝብል መጓሰ ስማዕ።', 'ኣብ ጽድያ ቅድሚ ምምላሶም ኣብ ትሕቲ ጫፍ ናሕሲ ሳጹን መንበሪ ግበረሎም።', 'ገዛ ክትዕድስ እንከለኻ፣ እቲ መንበሪኦም ዝኾነ ንኡስ ቀዳድ ኣብ ትሕቲ ጫፍ ናሕሲ ሓልዎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ti', 'ዓባይ ጨርቂ ዑፍ', 'ዓመት መጸ ናብ ደቡብ ኣፍሪቃ ተጓዒዞም ይምለሱ።', 'ካብ ጽድያ ክሳብ መጀመርታ ቀውዒ፣ ልዕሊ ግራትን ማይን ትሒቶም ክነፍሩ ርአዮም።', 'ናብ መንበሪኦም ክበጽሑ ምእንቲ ማዕጾ መኽዘን ቁሩብ ክፉት ግደፎ።', 'ነቲ ኣረጊት ናይ ጭቃ መንበሪ ኣይተፍርሶ — ዓመት መጸ ደጋጊሞም ይጥቀሙሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ti', 'ኩኩ ዑፍ', 'ኣብ መንበሪ ካልኦት ኣዕዋፍ እንቋቝሖ የንብር፣ ንደቁ ፈጺሙ ኣየዕቢን።', 'ኣብ መወዳእታ ጽድያ፣ ካብ ጫፍ ጫካ ዝመጽእ ናይ ርሑቕ "ኩ-ኩ" ድምጺ ስማዕ።', 'ነቶም ዝምርኮሶም ኣዕዋፍ ዝምግቡ ብሓሸራ ዝህብትሙ መሮርን ሓጹርን ደግፍ።', 'እቶም ኣአንገድቲ ኣዕዋፍ ከይሽበሩ ኣብ ጥቓ ቁጥቋጦን ሻምብቆን ኣብ መገዲ ጽናሕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ti', 'ቀይሕ ኣፍ-ልቢ ዑፍ', 'ንግዝኣቶም ኣበርቲዖም ይከላኸሉ፣ ኣብ ጥቓ ብርሃን መገዲ ለይቲ እውን ይዝምሩ።', 'ዓመት ምሉእ ኣብ ጀርዲንን ጫካን፤ መሬት ንዝኹዕት ሰብ ንዓሶ ኢሎም ይስዕብዎ።', 'ኣብ ሓደ ኩርናዕ ጀርዲን ዝረገፈ ቆጽሊ ግደፍ፣ ኣብኡ መግቢ ክደልዩ።', 'ከቢድ ምቕንጣብ ሓጹር ናብ መወዳእታ ሓጋይ፣ ምፍራይ ምስ ተወድአ ኣሰጋግሮ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ti', 'ጸሊም ዑፍ', 'እቲ ሃብታም ናይ ተባዕታይ ዜማ ካብቶም ኣብ ኤውሮጳ ዝያዳ ዝፍለጡ ሓደ እዩ።', 'ዓመት ምሉእ፤ ኣብ ወጋሕታን ምሸትን ካብ ናሕስን ጫፍ ኦምን ክዝምሩ ስማዕ።', 'ብፍላይ ብእዋን ደርቂ፣ ንመስተን ንሕጽቦን ንጹህ ማይ ኣንብር።', 'ብእዋን ምፍራይ፣ ኣብ ወጋሕታ ድሙታት ኣብ ውሽጢ ገዛ ኣጽንሓዮም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ti', 'ናይ ግራት ዑፍ', 'ማሕበራዊ ዑፍ እዩ፣ ብኽረምቲ ብጫውጫው ዝመልአ መጓሰ ይዘውር።', 'ብቐውዕን ክረምትን፣ ካብ ሓጹርን ኦምን ፍረ ክለቕሙ ርአዮም።', 'ነተን ፍረ ዘለወን ቁጥቋጦታት ብእዋን ክረምቲ ኣይትቕንጥበን።', 'ብኽረምቲ እቲ ዝረገፈ ቱፋሕ ኣብ መሬት ግደፎ — ኣብ ቁሪ ወሳኒ መግቢ እዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ti', 'ዓባይ ንእሽቶ ዑፍ', 'ብዙሕ ዓይነት ድምጺ ኣለዎም፣ ካብ ጎረባብቶም እውን ሓድሽ ይመሃሩ።', 'ዓመት ምሉእ፤ ካብ መወዳእታ ክረምቲ ጀሚሩ ነቲ ደጋጋሚ ዜማኡ ስማዕ።', 'ናይ 32 ሚሜ ነዃል ዘለዎ ሳጹን መንበሪ ኣብ ህዱእን ጽላሎት ዘለዎን ቦታ ስቐሎ።', 'ንደቆም ዝኸውን እኹል ሓሳኹ ምእንቲ ክህሉ ናይ ጀርዲን መርዚ ኣወግድ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ti', 'ሰማያዊት ንእሽቶ ዑፍ', 'ሓንቲ ጣብያ ደቂ ካብ ሽሕ ንላዕሊ ሓሳኹ ክትበልዕ ትኽእል።', 'ዓመት ምሉእ ኣብ ጀርዲንን ጫካን፣ መብዛሕትኡ ግዜ ካብ ቀጠንቲ ጨናፍር ተገልቢጦም ይንጠልጠሉ።', 'ናይ 25 ሚሜ ነዃል ዘለዎ ንእሽቶ ሳጹን ካብ ንፋስ ርሒቑ ኣንብር።', 'ሓሳኹ ንደቆም ምእንቲ ክርከብ ብጽድያ መቕተሊ ሓሸራ ኣይትጠቐም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ti', 'ዘርኢ በላዒ ዑፍ', 'ዜማኦም ካብ ከባቢ ናብ ከባቢ ይፈላለ፣ ከም ናይ ዞባ ቋንቋ።', 'ካብ ጽድያ ክሳብ ቀውዒ፤ ተባዕትዮ ካብ ክፉት ቦታ ብሩህ ዜማ ይዝምሩ።', 'ገለ ካብቲ ርእሲ ዘርኢን ሳዕርን ብእዋን ወቕቲ ጠጠው ኢሉ ግደፎ።', 'ሕማም ከይላባዕ ነቲ መግቢ ዝቕመጠሉ ንጹህ ግበሮ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ti', 'ናይ ኦክ ዑፍ', 'ኣብ ነፍሲ ወከፍ ቀውዒ ኣሽሓት ፍረ ኦክ ይቐብሩ፣ ገሊኡ ረሲዖም ጫካ ኦክ ይተኽሉ።', 'ዓመት ምሉእ ኣብ ጫካ ኦክ፤ ብቐውዒ ነቲ ጭራንሽውን ሰማያውን ሕብሪ ተጠንቀቐሉ።', 'እቲ ኣብ ትሕቲ ኦክ ዝረገፈ ፍረን ቆጽልን ከምዘሎ ግደፎ።', 'ኣብ መሬት ዝምገቡ ኣዕዋፍ ከይሰግኡ ኣኽላባት ኣብ መገዲ ኣጽንሓዮም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ti', 'ዓባይ ነቃቲ ዕንጨይቲ ዑፍ', 'እቲ ናይ ጽድያ ቅጥቃጥ መግቢ ንምድላይ ኣይኮነን — ግዝኣቱ ንምእዋጅ እዩ።', 'ዓመት ምሉእ፤ ኣብ መወዳእታ ክረምቲ ኣብ ጫካ ዘቓልሕ ቅጥቃጥ ስማዕ።', 'እቲ ጠጠው ዝበለ ዝሞተ ዕንጨይቲ ግደፎ፣ እቶም ዝምገቦም ሓሸራ ኣብኡ ኣለዉ።', 'ዝሞቱ ወይ ዝደኸሙ ኣእዋም ኣይትቑረጾም፣ መንበሪ ክህልዎም ይኽእል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ti', 'ጻዕዳ ጭራ-ንቅናቕ ዑፍ', 'እቲ ቀጻሊ ምንቕናቕ ጭራ ንኣንበሳታት ንቕሓት ዘመልክት ክኸውን ይኽእል።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ጥቓ ማይ፤ እናጎየየ ደው እናበለ ሓሸራ ይሕዝ።', 'ኣብ ጥቓ ማይ ሓጺር ሳዕሪ ወይ ንኡስ እምኒ ግደፍ፣ ኣብኡ መግቢ ክደሊ።', 'እቲ ዝምገበሉን ዝፈርየሉን ገምገም ማይን ንኡስ እምንን ኣይትረብሾ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ti', 'ነዊሕ እግሪ ዑፍ', 'ኣብ መጀመርታ ጽድያ እናነጠሩን እናደነኑን ናይ ሓዳር ሳዕስዒት የርእዩ።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ከባቢ ረግረግ፤ ነቲ ናብ ርሑቕ ዝሰምዕ ድምጺ ስማዕ።', 'እቲ ዘይነቐጸ ረግረግን ጠሊ ዘለዎ መሮርን ምሕላው ደግፍ።', 'እቲ ዝፈርዩሉ ረግረግ ካብ ርሑቕ ርአዮ — እንተተረቢሾም መንበሪኦም ይገድፉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ti', 'ዓው ኢሉ ዝጭድር ስዋን', 'ንመላእ ህይወቶም ሓደ መጻምድቲ ይሕዙ፣ ምምጻኦም ብዓው ዝበለ ድምጺ የፍልጡ።', 'ብጽድያን ቀውዕን ኣብ ቀላያትን ማይ ዝመልኦ ግራትን፣ መብዛሕትኡ ግዜ ብስድራ።', 'እቲ ትሑት ገምገም ቀላይን ጠሊ ዘለዎ ግራትን ከይነቕጽ ደግፍ።', 'ፈጺምካ ባኒ ኣይትሃቦም — ይጎድኦም እዩ፤ ኣብ በረድ እውን ርሒቕካ ጽናሕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ti', 'ቀጠልያ ርእሲ ደርሆ-ማይ', 'ደቆም ካብ ዝፍልፍሉ ኣብ ውሽጢ ሒደት ሰዓታት ክሕንብሱን ባዕሎም ክምገቡን ይኽእሉ።', 'ዓመት ምሉእ ኣብ ዳርጋ ኩሉ ቀላይ፣ ኩሬ ወይ ህዱእ ወሓዚ።', 'እንተመጊብካዮም፣ ኣብ ክንዲ ባኒ ዓተር ወይ ዘርኢ ተጠቐም።', 'ብጽድያ እቶም ደርሁ ማይ ኣብ ዝፈርዩሉ ማይ ኣኽላባት ኣየእቱ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ti', 'ንቡር ንስሪ', 'ብገፊሕ ኣኽናፍ ይንሳፈፉ፣ ከም ድምጺ ድሙ ዝመስል ጭራሕ የስምዑ።', 'ካብ ጽድያ ክሳብ ቀውዒ፤ ልዕሊ ግራትን ጫፍ ጫካን ክዘውሩ ርአዮም።', 'እቲ ንኣናጹን ንኣሽቱ እንስሳን ዝሕዝ ሓርፋፍ መሮርን ጫፍ ግራትን ደግፍ።', 'ናይ ኣናጹ መርዚ ፈጺምካ ኣይትጠቐም — ብሰንሰለት መግቢ ናብ ኣዕዋፍ ይመጽእ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ti', 'ዓሳ ሓዛዚ ንስሪ', 'ብእግሩ ኣቐዲሙ ናብ ማይ ይጥሕል፣ ፍርቂ ክብደቱ ዝኸውን ዓሳ ክጸውር ይኽእል።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ጥቓ ዓበይቲ ቀላያት፤ ኣብ ኣየር ደው ኢሉ ድሕሪኡ ይጥሕል።', 'ኣብ ጥቓ ብዓሳ ዝህብትሙ ቀላያት ኣብ ነዋሕቲ ዓንዲ መንበሪ ምግባር ደግፍ።', 'እቶም መጻምድቲ እንቋቝሖኦም ገዲፎም ከይሃድሙ ካብቲ መንበሪ ርሒቕካ ጽናሕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ti', 'ቀይሕ ወኻርያ', 'ንዝተሓብአ ዕዳጋ ንምንጣር ነቲ ማግኔታዊ ሓይሊ መሬት ይጥቀሙሉ።', 'ዓመት ምሉእ፣ ብዝያዳ ኣብ ወጋሕታን ምሸትን ኣብ ጫፍ ጫካን ግራትን።', 'ክዓርፉን ጉድጓድ ክኹዕቱን ዝኽእሉሉ ህዱእ በረኻዊ ኩርናዕ ግደፍ።', 'ናይ ጓሓፍ ኣቕሓ ዕጸዎ፣ ጎዳኢ ትርፊ መግቢ ፈጺምካ ኣይትግደፈሎም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ti', 'ኤውሮጳዊ ቅንፍዝ', 'ኣብ ሓንቲ ለይቲ መግቢ እናደለየ ክልተ ኪሎሜተር ክኸይድ ይኽእል።', 'ካብ ጽድያ ክሳብ ቀውዒ ድሕሪ ጸልማት፤ ብኽረምቲ ኣብ ትሕቲ ቆጽልን ዕንጨይትን ይድቅስ።', 'ኣብ ሓጹር 13 ሴሜ ዝኸውን ነዃል ግበር፣ ኣብ መንጎ ጀርዲናት ክንቀሳቐስ።', 'ነዊሕ ሳዕሪ ቅድሚ ምቕንጣብካ ርኣዮ፣ ንክረምታዊ ድቃስ ቆጽሊ ግደፍ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ti', 'ንእሽቶ ኣጋዘን', 'ጥንሲ የደንጉዩ፣ ስለዚ ደቆም ኩሉ ግዜ ኣብ መጀመርታ ሓጋይ ይውለዱ።', 'ዓመት ምሉእ ኣብ ጫፍ ጫካ፣ ብዝያዳ ኣብ ወጋሕታን ምሸትን ክግምዱ ይረኣዩ።', 'መጽለልን መግብን ዝህብ ዘይተቐንጠበ ጫፍ ግራትን ቁጥቋጦን ደግፍ።', 'ኣብ መጀመርታ ሓጋይ ደቆም ተሓቢኦም እንከለዉ ኣብ ጥቓ ጫካ ኣኽላባት እሰር።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ti', 'ዓባይ ኣጋዘን (ሙስ)', 'ኣብ ዓለም እቲ ዝዓበየ ኣጋዘን እዩ፤ ዓቢ ተባዕታይ ካብ ፍርቂ ቶን ንላዕሊ ይምዘን።', 'ዓመት ምሉእ ኣብ ጫካን ረግረግን፣ ብዝያዳ ኣብ ወጋሕታን ምሸትን ንጡፍ።', 'ዝተኣሳሰረ ጫካን ናይ ረግረግ መተሓላለፍን ደግፍ።', 'ኣብ ወጋሕታን ምሸትን ኣብ መገዲ ጫካ ተጠንቂቕካ ዘውር፣ ናብ ደቁ ፈጺምካ ኣይትቕረብ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ti', 'ቀይሕ ሽኮኮ', 'ብዙሕ መንበሪ ይሃንጹ፣ ካብ ሓደ ናብ ካልእ ይቕይሩ።', 'ዓመት ምሉእ ኣብ ጫካ፣ ብዝያዳ ኣብ ንግሆ ንጡፋት።', 'እቲ ዝምገቦምን ዝፈርዩሎምን ፍረን ጠጠው ዝበሉ ኣእዋምን ግደፍ።', 'ኣኽላባት ኣብ መገዲ ኣጽንሓዮም፣ መንበሪ ክህልዎም ዝኽእል ኦም ኣይትረብሽ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ti', 'ኤውሮጳዊ ቢቨር', 'እቲ ዝሰርሕዎ ዓድሚ ንዓሳ፣ ኣዕዋፍን ሓሸራን ዘማዕብል ረግረግ ይፈጥር።', 'ካብ ጽድያ ክሳብ መወዳእታ ቀውዒ ኣብ ህዱእ ወሓዚ፣ ብዝያዳ ምሸት ንጡፍ።', 'ውሑስ ኣብ ዝኾነሉ እቲ ዓድምን ናይ ገምገም ኣእዋምን ከምዘሎ ክገድፍ ደግፍ።', 'ካብ መንበሪኦምን ዓድሚኦምን ርሒቕካ ጽናሕ፣ ብፍላይ ደቆም ንኣሽቱ እንከለዉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ti', 'ናይ እምባ ማንቲለ', 'ብኽረምቲ ኣብ በረድ ንምሽፋን ጸጉሮም ጻዕዳ ይኸውን።', 'ዓመት ምሉእ ኣብ ክፉት መሬትን ጋህታን፣ ብዝያዳ ኣብ ወጋሕታን ምሸትን።', 'ዓመት ምሉእ ዘድልዮም ሕውስዋስ ክፉት መሬትን መጽለልን ደግፍ።', 'ዝዓርፉ ዘለዉ ማንቲለ ከይስጎጉ ኣብ ክፉት መሬት ኣኽላባት እሰር።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ti', 'ኤውሮጳዊ ባጀር', 'ብስድራ ኣብ ትሕቲ መሬት ኣብ ዝርከብ ንወለዶታት ዝጸንሐ ጉድጓድ ይነብሩ።', 'ካብ ጽድያ ክሳብ ቀውዒ ድሕሪ ጸልማት ኣብ ጥቓ ጫካ፤ ክረምቲ ይድቅሱ።', 'ጉድጓድ ክኹዕቱሉ ዝኽእሉ ዘይተረበሸ ገምገምን ሓጹርን ግደፍ።', 'ንጡፍ ጉድጓድ ፈጺምካ ኣይትዕጸዎ ወይ ኣብ ጥቓኡ ኣይትኹዓት — ነባሪ ገዞኦም እዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ti', 'ንእሽቶ መንካዕ', 'እዚ ንእሽቶ መንካዕ ኣብ ሓንቲ ለይቲ ክሳብ 3,000 ጣንጡን ንኣሽቱ ሓሸራን ክበልዕ ይኽእል።', 'ብምሸት ሓጋይ፣ ልዕሊ ጀርዲን ቅልጡፍን ጠዋይን በረራኡ ርአዮ።', 'ናይ ምሸት ጸሓይ ኣብ ዝረኽበሉ ልዕሊ መንደቕ ወይ ኦም ሳጹን መንካዕ ስቐል።', 'ኣብ ኣፍ መዕቆቢኦም ብሩህ ብርሃን ኣወግድ፣ ሰማይ ለይቲ ጸልማት ግደፎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ti', 'ንእሽቶ ሕብረ-ኤሊ ጽንብላሊዕ', 'እዛ ጽንብላሊዕ ዓባይ ኮይና ትድቅስ፣ መብዛሕትኡ ግዜ ኣብ መኽዘንን ናሕስን።', 'ካብ መጀመርታ ጽድያ ክሳብ ቀውዒ ኣብ ጸሓያዊ ዕንባባ፣ ብፍላይ ኣብ ቆጽሊ ሓርማዝ።', 'ኣብ ጸሓያዊ ኩርናዕ ቁሩብ ቆጽሊ ሓርማዝ ግደፍ — ደቃ የድልዮም እዩ።', 'እተን ኣብ መኽዘን ክረምቲ ዝድቅሳ ጽንብላሊዕ ኣይትረብሸን።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ti', 'ጣዎስ ጽንብላሊዕ', 'እቲ ከም ዓይኒ ዝመስል ነጥቢ ንኣዕዋፍ የሰንብድ፣ ኣኽናፋ ክኽፈት እንከሎ ድምጺ የስምዕ።', 'ካብ ጽድያ ክሳብ ቀውዒ ብጸሓያዊ መዓልቲ፣ ኣብ ኣሻኹን ዝረገፈ ፍረን ትምገብ።', 'ንደቃ ዝኸውን ጸሓያዊ ቆጽሊ ሓርማዝ ክበቁል ግደፍ።', 'ኣብ መኽዘንን ኩምራ ዕንጨይትን ክረምቲ ዝዕቆባ ኣይትረብሸን።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ti', 'ብጫ ጽንብላሊዕ', 'እቲ ናይ እንግሊዝኛ ስም ጽንብላሊዕ ካብዚ ናይ ተባዕታይ ብጫ ሕብሪ ዝመጸ ክኸውን ይኽእል።', 'ካብተን ቀዳሞት ጽንብላሊዕ ጽድያ፤ ብሙቐት መዓልቲ ኣብ ጫፍ ጫካ ድለ።', 'ኣብ ሓጹር እቲ ደቃ ጥራይ ዝበልዕዎ ቁጥቋጦ ደግፍ።', 'ክረምቲ ንዝዕቆባሉ ቁጥቋጦ ዘለዎ ሓጹር ኣይተጽርዮ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ti', 'ብርቱኳናዊ ጫፍ ጽንብላሊዕ', 'ተባዕትዮ ጥራይ እዮም ብርቱኳናዊ ጫፍ ኣኽናፍ ዘለዎም፤ ኣንስትዮ ጻዕዳ እየን።', 'ብጽድያ ኣብ ጠሊ ዘለዎ መሮርን ጎደናታትን በረኻዊ ዕንባባ ኣብ ዝበቅለሉ።', 'ኣብ ጠሊ ዘለዎ ዘይተቐንጠበ ኩርናዕ በረኻዊ ዕንባባ ክበቁል ግደፍ።', 'ደቃ ምምጋብ ክሳብ ዝውድኡ ምቕንጣብ ጫፍ መገዲ ኣሰጋግሮ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ti', 'ሰማያዊት ጽንብላሊዕ', 'ጻጸ ሓደ ሓደ ግዜ ንጥዑም ፈሳሲኦም ኢሎም ንደቃ ይናብይዎም።', 'ካብ መወዳእታ ጽድያ ኣብ ጸሓያዊ መሮር ብጻዕዳ ዕንባባ ዝህብትም።', 'እቲ መሮር ኣይትቕንጥቦ፣ እቲ ዕንባባ ክዕምብብ።', 'ብበረኻዊ ዕንባባ ዝህብትም መሮር ብመቕተሊ ሳዕሪ ኣይትንጻጎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ti', 'ቀጠልያ ስራት ዘለዋ ጻዕዳ ጽንብላሊዕ', 'ምስ ናይ ጣይታ ጻዕዳ ጽንብላሊዕ ትመሳሰል እኳ እንተኾነት፣ በረኻዊ ኣትክልቲ ትመርጽ።', 'ካብ ጽድያ ክሳብ መወዳእታ ሓጋይ ኣብ ጠሊ ዘለዎ መሮርን መትረብን።', 'ጠሊ ዘለዎም ኩርናዓት ብዘቤታዊ ኣትክልቲ በረኻዊ ክኾኑ ግደፍ።', 'እቲ እትፈርየሉ ጠሊ ዘለዎ መሮር ኣይተንጽፎ ኣይትንጻጎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ti', 'ሸውዓተ ነጥቢ ዘለዋ ዲኒት', 'ሓንቲ ዲኒት ኣብ ህይወታ ኣሽሓት ንኣሽቱ ሓሸራ ትበልዕ።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ብሓሸራ ዝተጠቕዐ ኣትክልቲ፤ ክረምቲ ተኣኪበን ይድቅሳ።', 'ቁሩብ ሓሸራ ተጻወሮ፣ መርዚ ኣይትንጸግ፣ መግቢ ክህልወን።', 'ክረምቲ ዝዕቆባሉ ጥቕልል ዝበለ ቀንዲን ዝረገፈ ቆጽልን ግደፍ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ti', 'ብጫ ጭራ ዘለዋ ዓባይ ንህቢ', 'ንግስቲ ካብተን ቀዳሞት ናይ ጽድያ ንህቢ እየን፣ ጉድጓድ መንበሪ እናደለያ ትሒተን ይጭርሓ።', 'ካብ መጀመርታ ጽድያ ክሳብ ቀውዒ ኣብ ዕንባባ፤ ንግስቲ ብጽድያ ትሕቲ ሓጹር ይደልያ።', 'ኣቐዲሞም ዝዓብለሉ ኣትክልቲ ትከል ወይ ግደፍ፣ ኣብ ሳዕሪ ዕንባባ ክዕምብብ ግደፍ።', 'እቲ ዝፈርዩሉ ዘይተረበሸ ገምገምን ኣረጊት ጉድጓድ ኣናጹን ግደፍ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ti', 'ናይ መዓር ንህቢ', 'እታ ዝደለየት ንህቢ ንቐፎ ስምንተ ዝመስል ሳዕስዒት ብምስዓስዕ ቦታ ዕንባባ ትሕብር።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ዕንባባ ብሙቐትን ህድኣትን ዘለዎ መዓልቲ።', 'ብዝተፈላለየ ወቕቲ ዝዓብለል ዕንባባ ግደፍ፣ ትሑት ኣቕሓ ማይ እውን ኣንብር።', 'ዝዓበለሉ ኣትክልቲ ኣይትንጻጎም፣ ፍርቂ መዓልቲ ፈጺምካ ኣይትንጻጎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ti', 'ንጉሳዊ ዛግራ', 'ካብቶም ኣብ ኤውሮጳ ዝዓበዩ ዛግራ ሓደ እዩ፣ ኣብ ኣየር እውን ዕዳጋ ክሕዝ ይኽእል።', 'ብሙቐት መዓልቲ ሓጋይ፣ ኣብ ጫፍ ኩሬን ቀላይን ክዘውር ርአዮ።', 'ኣትክልቲ ዘለዎ ኩሬ ሓሉ ወይ ኩዓት፣ ጫፉ ብኣትክልቲ ተሸፊኑ ግደፎ።', 'ደቁ ክዓብዩ ምእንቲ ኩሬታት ካብ ብከላ ሓልዎም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ti', 'ንቡር ንእሽቶ ዛግራ', 'መብዛሕትኡ ግዜ ኣብቲ ሓደ ውዑይ ቦታ ይቕመጥ፣ ሓሸራ ንምሓዝ ይነጥር።', 'ካብ ማእከል ሓጋይ ክሳብ ቀውዒ ኣብ ጥቓ ህዱእ ማይ፣ ኣብ መገድን ዓንድን ይጽሃ።', 'ኣብ ከባቢ ኩሬታት ጸሓያዊ መቐመጥን ኣትክልትን ግደፍ።', 'ድኹዒ ወይ ዘይቲ ናብ ኩሬታት ከይሓልፍ ሓልዎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ti', 'ቀይሕ ናይ ጫካ ጻጸ', 'እቲ ዝሃንጽዎ ኩምራ ካብ ሓደ ሜተር ክነውሕን ፍርቂ ሚልዮን ጻጸ ክሕዝን ይኽእል።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ጫካ፤ ብመርፍእ ቆጽሊ ዝተሰርሐ ኩምራ ድለ።', 'እቲ ኩምራ ከምዘሎ ግደፎ — ንምህናጹ ዓመታት ይወስድ።', 'ኣብ መገዲ ጽናሕ፣ ንኩምራ ጻጸ ፈጺምካ ኣይትዘውሮ ኣይትኹዓቶ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ti', 'ጻዕዳ ናይ ጫካ ዕንባባ', 'ኣዝዩ ቀስ ኢሉ ስለ ዝላባዕ፣ ብዙሕ ምስ ዝርአ ጥንታዊ ጫካ ምዃኑ የመልክት።', 'ብጽድያ፣ ኣእዋም ቆጽሊ ቅድሚ ምውጻኦም ጻዕዳ ዕንባባ ድለ።', 'እቲ ቀስ ዝላባዕ ሱር ክዓቢ መሬት ጫካ ከምዘሎ ግደፎ።', 'ኣብ ዝበቅለሉ ተዘናጋዕ — ምቕንጣብ ንዓመታት ዝወሰደ ዕንባባ የጥፍእ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ti', 'ናይ ስንጭሮ ዕንባባ', 'ኩሉ ክፋል እዚ ጥዑም ጨና ዘለዎ ተኽሊ እንተተበሊዑ መርዛም እዩ።', 'ኣብ መወዳእታ ጽድያ፣ ነቲ ጨና ስዒብካ ናብ ጽላሎት ዘለዎ ጫካ ኪድ።', 'እቲ ዝበቅለሉ ጽላሎት ዘለዎ ጫፍ ጫካን ዝረገፈ ቆጽልን ግደፍ።', 'ኣይትቐንጥቦ ኣይትምንቀሎ፣ ካብ ቆልዑን እንስሳን ኣርሕቖ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ti', 'በረኻዊ ሽጉርቲ', 'መብዛሕትኡ ግዜ ጻዕዳ ዕንባባኡ ቅድሚ ምርኣይካ ጨናኡ ትሽትት።', 'ብጽድያ፣ ኣብ ጠሊ ዘለዎ ጫካ ገፋሕቲ ቀጠልያ ቆጽልን ኮኾባዊ ዕንባባን ድለ።', 'ዓመት መጸ ክበቅል ጠሊ ዘለዎ ጫካ ከምዘሎ ግደፎ።', 'ኣብቲ ከባቢ እንተተፈቒዱ፣ ቁሩብ ውሰድ፣ ሱሩ ፈጺምካ ኣይትምንቀሎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ti', 'ወርቃዊ ናይ ረግረግ ዕንባባ', 'ካብቶም ዝኣረጉ ዘቤታዊ ኣትክልቲ ሓደ እዩ፣ ካብ ናይ መወዳእታ ናይ በረድ ዘመን ተሪፉ።', 'ብጽድያ፣ ኣብ ረግረግን መትረብን ዓበይቲ ወርቃዊ ዕንባባ ድለ።', 'ክዕምብብ ምእንቲ ጫፍ ኩሬን መትረብን ጠሊ ዘለዎን ዘይተቐንጠበን ግበሮ።', 'ጠሊ ዘለዎ መሬት ኣይተንጽፎ፣ ነቲ ተኽሊ ኣብ ዝበቅለሉ ግደፎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ti', 'ብጫ ናይ ጽድያ ዕንባባ', 'ሓደ እዋን ኣብ መሮር ኣዝዩ ብዙሕ ስለ ዝነበረ ቆልዑ ኩዕሶ ይሰርሑሉ ነይሮም።', 'ብጽድያ፣ ኣብ ጥንታዊ መሮር ዝቐንዐ ብጫ ዕንባባ ድለ።', 'ክሳብ ዝዓብልልን ዘርኢ ዝገብርን መሮር ኣይትቐንጥቦ።', 'ካብ በረኻ ኣይትቐንጥቦ ኣይትምንቀሎ — ናይ መሮር ዕንባባ እናነከየ እዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ti', 'ዓባይ ጻዕዳ ዕንባባ', 'እቲ ከም ሓደ ዕንባባ ዝርአ ብሓቂ ብዙሓት ንኣሽቱ ዕንባባ ተኣኪቦም እዮም።', 'ብሓጋይ፣ ኣብ ጫፍ መገድን መሮርን ዓበይቲ ጻዕዳ ዕንባባ ድለ።', 'ክዕምብብ ምእንቲ ኣብ ማእከል ሓጋይ ሓደ መስመር ሳዕሪ ዘይተቐንጠበ ግደፍ።', 'ጫፍ መገድን መሮርን ብመቕተሊ ሳዕሪ ኣይትንጻጎ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ti', 'ብጫ ዘርኢ-ነፋሲ ዕንባባ', 'ንንህቢ ካብቶም ኣዝዮም ኣገደስቲ ናይ ቀዳማይ ወቕቲ ምንጪ መዓር ሓደ እዩ።', 'ካብ ጽድያ ንደሓር ኣብ ዳርጋ ኩሉ ቦታ፤ ዕንባባ ብጸሓይ ይኽፈት ብምሸት ይዕጾ።', 'ብጽድያ ቅድሚ ቀዳማይ ምቕንጣብ ኣብ ሳዕሪ ክዕምብቡ ግደፎም።', 'እቶም ቀዳሞት ኣዕለብቲ እዚ ወሳኒ መግቢ ክረኽቡ መቕተሊ ሳዕሪ ኣይትጠቐም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ti', 'ናይ በረኻ ቁጥቋጦ', 'ሓደ ተኽሊ ካብ ሚእቲ ሽሕ ንላዕሊ ንኡስ ዘርኢ ከፍሪ ይኽእል።', 'ኣብ መወዳእታ ሓጋይ፣ ኣብ ክፉት በረኻን ረግረግን ወይንያዊ ምንጻፍ ድለ።', 'እቲ ከባቢ ክፉትን ዘይነቐጸን ኮይኑ ክጸንሕ ደግፍ።', 'ኣብ መገዲ ጽናሕ፣ ብእዋን ደርቂ ፈጺምካ ሓዊ ኣይትውልዕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ti', 'ሰማያዊ በረኻዊ ፍረ', 'ኣጻብዕትኻ ሰማያዊ ይገብር፣ ካብ ኣዕዋፍ ክሳብ ዲብ ንኹሉ ይምግብ።', 'ብሓጋይ፣ ኣብ ጫካ ጽሕድን ስፕሩስን ትሑት ቁጥቋጦ ምስ ጸሊም ፍረ ድለ።', 'እቲ ቁጥቋጦ ክፈሪ ትሕቲ ኣትክልቲ ጫካ ከምዘሎ ግደፎ።', 'ምልቓም እንተተፈቒዱ፣ ንዱር እንስሳ እኹል ፍረ ግደፍ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ti', 'ቀይሕ በረኻዊ ፍረ', 'ኣብ ፍረኡ ብዘሎ ተፈጥሮኣዊ ዓቃቢ ንኣዋርሕ ይጸንሕ።', 'ኣብ መወዳእታ ሓጋይን ቀውዕን፣ ኣብ ቀጠልያ ምንጻፍ ዘንጸባርቕ ቀይሕ ፍረ ድለ።', 'እቲ ምንጻፍ ክላባዕ መሬት ጫካ ከምዘሎ ግደፎ።', 'ምልቓም እንተተፈቒዱ፣ ነቲ ተኽሊ ከይትጭፍልቖ ተጠንቂቕካ ረግጽ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ti', 'ብሩር በርች ኦም', 'ሓደ በርች ንኣማእታት ዓይነት ሓሸራ ይምግብ፣ እዚኣቶም ድማ ንብዙሓት ኣዕዋፍ።', 'ዓመት ምሉእ፤ እቲ ጻዕዳ ዝቕረፍ ቅርፍቲ ኣብ ዝኾነ ወቕቲ ንምልላዩ ቀሊል ይገብሮ።', 'ንሓመድ ከህብትምን ንሓሸራ ክምግብን ዝረገፈ ቆጽልን ዝሞተ ዕንጨይትን ግደፍ።', 'ቅርፍቲ ኣይትግፈፎ፣ ነቲ ኦም የቑስሎን የድክሞን።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ti', 'ናይ ኖርወይ ስፕሩስ ኦም', 'ኣብ ሽወደን ዘሎ ሓደ ስፕሩስ ኣሽሓት ዓመታት ካብ ዝዕድሚኡ ሱር ይበቅል።', 'ዓመት ምሉእ ኣብ ጫካ፤ እቲ ዝንጠልጠል ፍረኡ ካብ ኩሉ ስፕሩስ ዝነውሐ እዩ።', 'ንሓሸራን ቅንጣብን መዕቆቢ ዝኾነ ዝረገፈ ፍረን ዝሞተ ዕንጨይትን ግደፍ።', 'እቲ ጽፍሒ ሱር ስፕሩስ ከይጭቆን ኣብ ጫካ ኣብ መገዲ ጽናሕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ti', 'ናይ ስኮትላንድ ጽሕዲ', 'ኣረጋውያን ጽሕዲ ኣብ ላዕሊ ብርቱኳናዊ የንጸባርቑ፣ ንዘመናት ክነብሩ ይኽእሉ።', 'ዓመት ምሉእ ኣብ ሑጻውን እምናውን መሬት፤ እቲ ላዕለዋይ ብርቱኳናዊ ቅርፍቲ ድለ።', 'ብህይወት ዝህብትም ጠጠው ዝበለ ዝሞተ ዕንጨይትን ኣረጋውያን ጽሕድን ግደፍ።', 'ኣብ ንቑጽ ሑጻዊ መሬት ኣብ ጥቓ ጽሕዲ ፈጺምካ ሓዊ ኣይትውልዕ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ti', 'ሰሜናዊ ፓይክ ዓሳ', 'ተሓቢኡ ዝጽበ ኣዳኒ እዩ፣ ካብ ህድኣት ብቕጽበት ይነጥር።', 'ካብ ጽድያ ክሳብ ቀውዒ ኣብ ብሳዕሪ ዝመልአ ትሑት ማይ ቀላያትን ወሓዝትን።', 'ንኣሽቱ ዓሳ ዝዕቆቡሉ ሻምብቆን ናይ ማይ ኣትክልትን ምሕላው ደግፍ።', 'ብከላን ጓሓፍን ካብ ማይ ኣርሕቕ፣ ናይቲ ከባቢ ሕጊ ምግፋፍ ዓሳ ተኸተል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ti', 'ኤውሮጳዊ ፐርች ዓሳ', 'ብጭፍራ የደንዩ፣ እቲ ጽዑቕ መስመሮም ቅርጾም ይሰብሮ።', 'ብውዑያት ኣዋርሕ ኣብ ከባቢ መሳገርን ናይ ማይ ሳዕርን።', 'ንኣሽቱ ዓሳ ዝዕቆቡሉ ንጹህ ማይን ትሕቲ-ማይ ቅርጽን ደግፍ።', 'ኣብ ቀላያትን ወሓዝትን ገለ ኣይትደርብ፣ ናይቲ ከባቢ ሕጊ ምግፋፍ ዓሳ ተኸተል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ti', 'ሮች ዓሳ', 'ብዙሓት ኣዳነይቲ ቀላይ ዝምርኮሱሉ ወሳኒ መግቢ ዓሳ እዩ።', 'ብውዑያት ኣዋርሕ፣ ኣብ ላዕለዋይ ክፋል ቀላያትን ህዱኣት ወሓዝትን ብጭፍራ።', 'ንምፍራይ ንጹህ ማይን ብኣትክልቲ ዝተሸፈነ ገምገምን ደግፍ።', 'ውሒዝን ጓሓፍን ካብ ማይ ኣርሕቕ፣ ናይቲ ከባቢ ሕጊ ምግፋፍ ዓሳ ተኸተል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ckb', 'باڵندەی خێرای ئاسمان', 'دەتوانن مانگەها بەردەوام لە ئاسماندا بمێننەوە، تەنانەت لە کاتی فڕیندا دەخەون.', 'لە ئێوارە گەرمەکانی هاویندا، سەیری سەرووی بانەکان بکە و گوێ لە کۆمەڵە هاواردەرەکان بگرە.', 'پێش گەڕانەوەیان لە بەهاردا، سندوقی هێلانە لە ژێر لێواری بانەکەت دابنێ.', 'کاتێک خانووەکە نۆژەن دەکەیتەوە، ئەو کەلێنە بچووکانەی ژێر لێوار بپارێزە کە هێلانەیانە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ckb', 'پەڕەسێلکەی ماڵان', 'هەموو ساڵێک تا باشووری ئەفریقا کۆچ دەکەن و دەگەڕێنەوە.', 'لە بەهارەوە تا سەرەتای پاییز، بیانبینە کە نزم بەسەر کێڵگە و ئاودا دەفڕن.', 'دەرگای تەویلە یان ئەمباری کەمێک کراوە بەجێبهێڵە تا بگەنە شوێنی هێلانەیان.', 'هێلانە قوڕینە کۆنەکان مەڕووخێنە — پەڕەسێلکە ساڵ لەدوای ساڵ دووبارە بەکاریان دەهێنێتەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ckb', 'باڵندەی کوکو', 'هێلکەکانی لە هێلانەی باڵندەی تر دەنێتەوە و هەرگیز بێچووەکانی خۆی پەروەردە ناکات.', 'لە کۆتایی بەهاردا، گوێ لە دەنگی دوورەدەستی «کوو-کوو» بگرە کە لە قەراغی دارستانەوە دێت.', 'پشتیوانی لە مەرغزار و پەرژینە پڕ مێروولەکان بکە کە خۆراکی باڵندە خانەخوێکان دابین دەکەن.', 'لە نزیک دەوەن و قامیشەڵاندا لەسەر ڕێڕەوەکان بمێنەوە تا باڵندە خانەخوێکان نەتەنگ بن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ckb', 'سنگ‌سوورەی ئەورووپی', 'بە توندی بەرگری لە سنووری خۆیان دەکەن و لە نزیک ڕووناکی شەقامدا بە شەویش دەخوێنن.', 'بە درێژایی ساڵ لە باخچە و دارستاندا؛ زۆرجار بەدوای ئەو کەسەوە دەکەون کە خاک هەڵدەکۆڵێت.', 'گۆشەیەکی باخچە بە گەڵای وەریو بەجێبهێڵە تا تیایدا بەدوای خۆراکدا بگەڕێن.', 'بڕینی قورسی پەرژین دوابخە تا کۆتایی هێلانەکردن لە دواهەمین هاویندا.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ckb', 'باڵندەی ڕەش', 'گۆرانیی دەوڵەمەندی نێرەکە یەکێکە لە ناسراوترین دەنگەکانی ئەورووپا.', 'بە درێژایی ساڵ؛ لە بەرەبەیان و ئێواراندا گوێ لە نێرەکان بگرە کە لە سەربان دەخوێنن.', 'ئاوی تازە بۆ خواردنەوە و خۆشوشتن دابنێ، بەتایبەت لە ماوەی وشکەساڵیدا.', 'لە وەرزی هێلانەکردندا، بەرەبەیانان پشیلەکان لە ماڵەوە ڕابگرە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ckb', 'توڕاخەی کێڵگە', 'باڵندەیەکی کۆمەڵایەتییە کە زستانان بە کۆمەڵی بە دەنگ‌وباس دەگەڕێت.', 'لە پاییز و زستاندا، سەیری کۆمەڵەکان بکە کە توو لە پەرژین و دارەکان دەلێسنەوە.', 'دەوەنە بەرداەکان بەدرێژایی زستان مەبڕە.', 'سێوی وەریو لە زستاندا لەسەر زەوی بەجێبهێڵە — لە ساردیدا خۆراکێکی گرنگە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ckb', 'چۆلەکەی گەورە', 'فەرهەنگی دەنگیی فراوانیان هەیە و دەنگی نوێ لە دراوسێکانیان فێردەبن.', 'بە درێژایی ساڵ؛ لە کۆتایی زستانەوە گوێ لە گۆرانییە زەنگدارەکەی بگرە.', 'سندوقی هێلانە بە کونی ٣٢ ملم لە شوێنێکی هێمن و سێبەردار هەڵبواسە.', 'دووری لە ژەهری باخچە بگرە تا کرمی پێویست بۆ خۆراکی بێچووەکان بمێنێتەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ckb', 'چۆلەکەی شین', 'یەک هێلانە بێچووی چۆلەکەی شین دەتوانێت زیاتر لە هەزار کرم بخوات.', 'بە درێژایی ساڵ لە باخچە و دارستاندا، زۆرجار بە پێچەوانە لە لقە باریکەکان هەڵدەواسرێن.', 'سندوقێکی بچووک بە کونی ٢٥ ملم دوور لە ڕێگای با دابنێ.', 'لە بەهاردا ژەهری مێروو بەکارمەهێنە تا کرم بۆ بێچووەکان بەردەست بێت.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ckb', 'باڵندەی تۆودانخۆر', 'گۆرانییان لە ناوچەیەکەوە بۆ ناوچەیەکی تر جیاوازە، وەک زاراوەی خۆجێیی.', 'لە بەهارەوە تا پاییز؛ نێرەکان دەستەواژەیەکی ڕوون لە شوێنی کراوەوە دەخوێنن.', 'هەندێک لە سەری تۆو و گیاچرەکان بەدرێژایی وەرزەکە بەجێبهێڵە.', 'شوێنی دانەخواردن پاک ڕابگرە تا نەخۆشی لەنێو باڵندەکاندا بڵاو نەبێتەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ckb', 'باڵندەی بەڕوو', 'هەموو پاییزێک هەزاران بەڕوو دەنێژن و بە لەبیرکردنی هەندێکیان دارستانی بەڕوو دەچێنن.', 'بە درێژایی ساڵ لە دارستانی بەڕوودا؛ لە پاییزدا چاوەڕێی ڕەنگە پەمەیی و شینەکە بە.', 'بەڕووە وەریوەکان و گەڵای ژێر دارەکان وەک خۆی بەجێبهێڵە.', 'سەگەکان لە دارستاندا لەسەر ڕێڕەو ڕابگرە تا باڵندە زەوی‌خۆرەکان نەتۆقێن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ckb', 'دارکوتی خاڵدار', 'لێدانی بەهارەکەی بۆ خۆراک نییە، بەڵکو ڕیتمێکی خێرایە بۆ ڕاگەیاندنی سنوور.', 'بە درێژایی ساڵ؛ لە کۆتایی زستاندا گوێ لە دەنگدانەوەی لێدان بگرە.', 'دارە مردووە ڕاوەستاوەکان بەجێبهێڵە، ئەو مێروولانەی تێیدان کە خۆراکییەتی.', 'دارە مردوو یان لاواز مەبڕەوە، لەوانەیە کونی هێلانەی تێدابێت.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ckb', 'کلک‌لەرزێنەی سپی', 'لەرزاندنی بەردەوامی کلک لەوانەیە نیشانەی ئاگاداری بێت لە بەرامبەر ڕاوکەران.', 'لە بەهارەوە تا پاییز لە نزیک ئاو و زەوی کراوە؛ ڕادەکات و دەوەستێت تا مێروو بگرێت.', 'لە نزیک ئاودا گیای کورت یان بەردەبچووک ڕابگرە تا لێی بەدوای خۆراکدا بگەڕێت.', 'کەناری بەردەبچووک و ئاوی کە تێیدا دەخوات و هێلانە دەکات مەشێوێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ckb', 'قوقنووسی خۆڵەمێشی', 'لە سەرەتای بەهاردا سەمای هاوسەرگیری بە بازدان و چەمانەوە پێشکەش دەکەن.', 'لە بەهارەوە تا پاییز لە دەوروبەری زۆنگاوەکان؛ گوێ لە دەنگە دوورەدەستەکەی بگرە.', 'پشتیوانی لە پاراستنی زۆنگاو و مەرغزارە تەڕە ئاوەکێشراوەکان بکە کە تێیدا زاوزێ دەکەن.', 'زۆنگاوی هێلانەکردن لە دوورەوە سەیر بکە — ئەگەر بشێوێنرێن هێلانەکە بەجێدەهێڵن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ckb', 'قووی دەنگ‌بەرز', 'بۆ هەموو تەمەن جووت دەبن و هاتنیان بە دەنگی بەرز ڕادەگەیەنن.', 'لە بەهار و پاییزدا لەسەر دەریاچە و کێڵگە ئاوگیراوەکان، زۆرجار بە کۆمەڵی خێزانی.', 'پشتیوانی بکە لەوەی کەناری قووڵ‌نەبووی دەریاچە و کێڵگە تەڕەکان ئاو لێ نەکێشرێت.', 'هەرگیز نان مەدە بە قووەکان — زیانیان پێدەگەیەنێت؛ لەسەر سەهۆڵیش دووری بگرە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ckb', 'مراویی سەرسەوز', 'بێچووەکان چەند کاتژمێرێک دوای هەڵهاتن دەتوانن مەلە بکەن و خۆیان بخۆن.', 'بە درێژایی ساڵ لە هەموو گۆم و دەریاچە و ڕووبارێکی هێواردا.', 'ئەگەر خۆراکیان دەدەیتێ، لە جیاتی نان جۆ یان نۆک یان تۆو بەکاربهێنە.', 'لە بەهاردا سەگەکان دوور بخەرەوە لەو ئاوەی مراوییەکان تێیدا هێلانە دەکەن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ckb', 'سیسارکەی ئاسایی', 'بە باڵی پان دەفڕن و دەنگێکی وەک مەوی پشیلە دەردەکەن.', 'لە بەهارەوە تا پاییز؛ بەدوایاندا بگەڕێ کە بەسەر کێڵگە و قەراغی دارستاندا دەسووڕێنەوە.', 'پشتیوانی لە مەرغزارە توندەکان و لێواری کێڵگە بکە کە مشکی کێڵگەی تێدایە.', 'هەرگیز ژەهری مشک بەکارمەهێنە — بە زنجیرەی خۆراکدا بەرەو باڵندە ڕاوکەرەکان دەڕوات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ckb', 'هەڵۆی ماسی‌گر', 'بە پێ سەرەتا خۆی هەڵدەدات تا ماسی بگرێت و دەتوانێت نیوەی کێشی خۆی هەڵبگرێت.', 'لە بەهارەوە تا پاییز لە نزیک دەریاچە گەورەکان؛ سەرەتا لە ئاسماندا ڕادەوەستێت پاشان خۆی هەڵدەدات.', 'پشتیوانی لە دانانی سەکۆی هێلانە لەسەر کۆڵەکە بەرزەکان لە نزیک دەریاچە پڕ ماسییەکان بکە.', 'زۆر دوور بە لە سەکۆکانی هێلانە تا جووتەکان هێلکەکانیان بەجێنەهێڵن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ckb', 'ڕێویی سوور', 'لە بواری موگناتیسی زەوی کەڵک وەردەگرن بۆ خەملاندنی باز بۆ نێچیری شاراوە.', 'بە درێژایی ساڵ، چالاکتر لە بەرەبەیان و ئێوارە لە قەراغی دارستان و کێڵگە.', 'گۆشەیەکی کێوی و هێمن بەجێبهێڵە تا تێیدا بحەسێنەوە و کون هەڵبکەنن.', 'سەتڵی زبڵ داخە و هەرگیز پاشماوەی زیانبەخش بۆ ڕێوی مەهێڵەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ckb', 'ژیژووی ئەورووپی', 'لە یەک شەودا دەتوانێت دوو کیلۆمەتر بەدوای خۆراکدا بڕوات.', 'لە بەهارەوە تا پاییز دوای تاریکی؛ زستانان لە ژێر کۆمەڵە گەڵا و دار دەخەوێت.', 'کەلێنێکی ١٣ سم لە پەرژیندا بکەرەوە تا لەنێوان باخچەکاندا بگەڕێت.', 'پێش بڕینی گیای درێژ سەیری بکە و کۆمەڵە گەڵا بۆ خەوی زستانە بەجێبهێڵە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ckb', 'ئاسکی بچووکی دار', 'سکپڕی دوادەخەن تا بێچووەکان هەمیشە لە سەرەتای هاویندا لەدایک ببن.', 'بە درێژایی ساڵ لە قەراغی دارستان، زۆرتر لە بەرەبەیان و ئێواراندا لە کاتی لەوەڕاندا.', 'پشتیوانی لە لێواری نەبڕدراوی کێڵگە و دەوەن بکە کە پەناگە و خۆراک دەدەن.', 'لە سەرەتای هاویندا کە بێچووەکان شاردراوەن، سەگەکان لە نزیک دارستاندا ببەستە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ckb', 'ئاسکی گەورە (مووس)', 'گەورەترین ئاسکی سەر زەوییە؛ نێرێکی گەورە زیاتر لە نیو تۆن کێشی دەبێت.', 'بە درێژایی ساڵ لە دارستان و زۆنگاودا، چالاکتر لە بەرەبەیان و ئێوارەدا.', 'پشتیوانی لە دارستانە پێکەوەبەستراوەکان و ڕێڕەوی زۆنگاو بکە کە پێویستیانە.', 'لە ڕێگا دارستانییەکاندا بە وریاییەوە لێبخوڕە و هەرگیز لە بێچوو نزیک مەبەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ckb', 'سمۆرەی سوور', 'چەند هێلانەیەک دروست دەکەن و لەنێوانیاندا دەگوازنەوە.', 'بە درێژایی ساڵ لە دارستاندا، چالاکتر لە بەیانی زوودا.', 'تۆپکە و گوێز و دارە ڕاوەستاوەکان بەجێبهێڵە کە خۆراک و هێلانەیانن.', 'سەگەکان لەسەر ڕێڕەو ڕابگرە و ئەو دارانە مەشێوێنە کە لەوانەیە هێلانەیان تێدابێت.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ckb', 'سەگی ئاوی ئەورووپی', 'بەنداوەکانیان زۆنگاو دروست دەکەن کە ماسی و باڵندە و مێروو زیاد دەکەن.', 'لە بەهارەوە تا کۆتایی پاییز لە دەوروبەری ڕووبارە هێوارەکان، چالاکتر لە ئێوارەدا.', 'پشتیوانی بکە لەوەی بەنداو و دارە کەنارئاوییەکان لە شوێنی خۆیان بمێننەوە لە کوێ سەلامەت بێت.', 'لە هێلانە و بەنداوەکان دووربە، بەتایبەت کاتێک بێچووەکان بچووکن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ckb', 'کەروێشکی چیا', 'زستانان مووەکانیان سپی دەبێت بۆ خۆشاردنەوە لەسەر بەفر.', 'بە درێژایی ساڵ لە زەوی کراوە و بۆشایی دارستاندا، زۆرتر بەرەبەیان و ئێواران.', 'پشتیوانی لەو تێکەڵەیەی زەوی کراوە و پەناگە بکە کە بەدرێژایی ساڵ پێویستیانە.', 'لە زەوی کراوەدا سەگەکان ببەستە تا کەروێشکە پشوودەرەکان ڕانەکرێن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ckb', 'ورچە‌کوێرەی ئەورووپی', 'بە کۆمەڵی خێزانی لە کونە ژێرزەوییەکاندا دەژین کە بۆ چەند نەوەیەک بەکاردێن.', 'لە بەهارەوە تا پاییز دوای تاریکی لە نزیک دارستان؛ زستان دەخەون.', 'کەنار و پەرژینە نەشێواوەکان بەجێبهێڵە تا تێیاندا کون هەڵبکەنن.', 'هەرگیز کونی چالاک دامەخە و لە نزیکی مەکۆڵە — ماڵی درێژخایەنیانە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ckb', 'شەمشەمەکوێرەی بچووک', 'ئەم شەمشەمەکوێرە بچووکە دەتوانێت لە یەک شەودا تا ٣٠٠٠ مێشوولە بخوات.', 'لە ئێوارەکانی هاویندا، فڕینە خێرا و پێچاوپێچەکەی بەسەر باخچەکاندا سەیر بکە.', 'سندوقی شەمشەمەکوێرە لە بەرزایی دیوار یان دارێک دابنێ کە خۆری ئێوارە بەرکەوێت.', 'دووری لە ڕووناکی توند لە دەمی پەناگەیان بگرە و ئاسمانی شەو تاریک ڕابگرە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ckb', 'پەپوولەی کیسەڵ‌ڕەنگی بچووک', 'ئەم پەپوولەیە وەک گەورە دەخەوێت، زۆرجار لە ئەمبار و ژووری ژێربانەکاندا.', 'لە سەرەتای بەهارەوە تا پاییز لەسەر گوڵە خۆرەتاوییەکان، بەتایبەت گەزگەزک.', 'پارچەیەک گەزگەزک لە گۆشەیەکی خۆرەتاویدا بەجێبهێڵە — کرمەکانی پێویستیانە.', 'پەپوولە خەوتووەکان لە ئەمباردا بەدرێژایی زستان مەشێوێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ckb', 'پەپوولەی تاووس', 'خاڵە چاوشێوەکانی باڵندە دەتۆقێنن و باڵەکانی لە کاتی کردنەوەدا دەنگ دەدەن.', 'لە بەهارەوە تا پاییز لە ڕۆژە خۆرەتاوییەکاندا، لەسەر دڕک و میوەی وەریو.', 'ڕێگە بدە پارچەیەک گەزگەزکی خۆرەتاوی بۆ کرمەکانی گەشە بکات.', 'ئەوانەی زستان لە ئەمبار و کۆمەڵە دار پەنا دەگرن مەشێوێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ckb', 'پەپوولەی گۆگردی', 'وشەی ئینگلیزی «پەپوولە» لەوانەیە لە ڕەنگە زەردە کەرەییەکەی نێری ئەم جۆرەوە هاتبێت.', 'یەکێکە لە یەکەم پەپوولەکانی بەهار؛ لە ڕۆژە گەرمەکاندا لە قەراغی دارستاندا بگەڕێ.', 'پشتیوانی لە دەوەنەکانی پەرژین بکە، تاکە ڕووەکێکە کرمەکانی دەیخۆن.', 'ئەو پەرژینە دەوەنداران پاک مەکەرەوە کە گەورەکان زستان تێیاندا پەنا دەگرن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ckb', 'پەپوولەی سەرپرتەقاڵی', 'تەنها نێرەکان سەری باڵی پرتەقاڵی ڕوونیان هەیە؛ مێینەکان سپین.', 'لە بەهاردا لە مەرغزارە تەڕەکان و ڕێڕەوەکاندا کە گوڵی کێوی لێی دەڕوێت.', 'ڕێگە بدە گوڵە کێوییەکان لە گۆشە تەڕ و نەبڕدراوەکاندا بڕوێن.', 'بڕینی لێواری ڕێگاکان دوابخە تا کرمەکانی لە خواردن تەواو دەبن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ckb', 'پەپوولەی شینی ئاسایی', 'مێروولەکان هەندێک جار بەخێوی کرمەکانی دەکەن لە بەرامبەر تراوێژە شیرینەکانیان.', 'لە کۆتایی بەهارەوە لە مەرغزارە خۆرەتاوییەکاندا کە پڕن لە شەبەق.', 'مەرغزار مەبڕە تا شەبەقەکان گوڵ بکەن.', 'مەرغزارە پڕ گوڵە کێوییەکان بە ژەهری گیا مەپرژێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ckb', 'پەپوولەی سپیی ڕەگ‌سەوز', 'سەرەڕای لێکچوونی لەگەڵ پەپوولەی سپیی کەلەرەم، ڕووەکی کێوی پێباشترە نەک بەروبوومی باخچە.', 'لە بەهارەوە تا کۆتایی هاوین لە مەرغزارە تەڕەکان و جۆگە و ڕێڕەوی دارستاندا.', 'ڕێگە بدە گۆشە تەڕەکان بە ڕووەکی خۆماڵی کێوی بن.', 'ئەو مەرغزارە تەڕانەی تێیدا زاوزێ دەکات ئاوی لێ مەکێشە و مەیپرژێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ckb', 'کاڵەژیرەی حەوت‌خاڵ', 'یەک کاڵەژیرە لە ماوەی ژیانیدا هەزاران مێرووی بچووک دەخوات.', 'لە بەهارەوە تا پاییز لەسەر ڕووەکە تووشبووەکان؛ زستان بە کۆمەڵ دەخەون.', 'هەندێک مێرووی بچووک بەرگە بگرە و مەپرژێنە تا خۆراکیان هەبێت.', 'قەدە بۆشەکان و گەڵای وەریو بەجێبهێڵە کە زستان تێیاندا پەنا دەگرن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ckb', 'هەنگی گەورەی کلک‌زەرد', 'شاژنەکان لە یەکەم هەنگەکانی بەهارن و نزم دەگەڕێن بەدوای کونی هێلانەدا.', 'لە سەرەتای بەهارەوە تا پاییز لەسەر گوڵ؛ شاژنەکان بەهاران ژێر پەرژین دەپشکنن.', 'ڕووەکە زوو گوڵدارەکان بچێنە یان بەجێبهێڵە و ڕێگە بدە شەبەق لە چیمەندا گوڵ بکات.', 'کەنارە نەشێواوەکان و کونە کۆنەکانی مشک بەجێبهێڵە کە کۆمەڵگاکان تێیاندا هێلانە دەکەن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ckb', 'هەنگی هەنگوینی ڕۆژئاوا', 'هەنگی گەڕۆک بە سەمایەکی هەشت‌شێوە شوێنی گوڵەکان بە کۆمەڵگاکەی دەڵێت.', 'لە بەهارەوە تا پاییز لەسەر گوڵ لە ڕۆژە گەرم و بێ‌بایەکاندا.', 'ڕێگە بدە جۆرەها گوڵ بەدرێژایی وەرزەکان بکەن و قاپێکی کەم‌قووڵی ئاو دابنێ.', 'ڕووەکە گوڵدارەکان مەپرژێنە و هەرگیز لە نیوەڕۆدا مەپرژێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ckb', 'دووپشکە‌باڵدارە ئیمپراتۆر', 'یەکێکە لە گەورەترینەکانی ئەورووپا و دەتوانێت نێچیر لە ئاسماندا بگرێت.', 'لە ڕۆژە گەرمەکانی هاویندا، سەیری بکە کە بەسەر گۆم و کەناری دەریاچەدا دەگەڕێت.', 'گۆمێکی ڕووەکدار ڕابگرە یان هەڵیبکەنە و کەنارەکانی بە ڕووەک بەجێبهێڵە.', 'گۆمەکان لە پیسبوون بپارێزە تا بێچووەکان گەشە بکەن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ckb', 'دووپشکە‌باڵدارەی بچووک', 'زۆرجار لەسەر هەمان شوێنی گەرم دادەنیشێت و بۆ گرتنی مێروو دەفڕێت.', 'لە ناوەڕاستی هاوینەوە تا پاییز لە نزیک ئاوی هێور، لەسەر ڕێڕەو و کۆڵەکە خۆ ڕادەخات.', 'شوێنی دانیشتنی خۆرەتاوی و ڕووەک لە دەوروبەری گۆمەکاندا بەجێبهێڵە.', 'ڕێگە مەدە پەین یان ڕۆن بۆ ناو ئەو گۆمانە بشۆردرێت کە بێچووەکان تێیدان.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ckb', 'مێروولەی سووری دار', 'گردە هێلانەکانیان دەتوانن زیاتر لە مەترێک بەرز بن و نیو ملیۆن مێروولە لەخۆبگرن.', 'لە بەهارەوە تا پاییز لە دارستانی کاجدا؛ بەدوای گردە قوبەییەکانی دەرزیدا بگەڕێ.', 'گردە هێلانەکان وەک خۆیان بەجێبهێڵە — دروستکردنیان ساڵانی دەوێت.', 'لەسەر ڕێڕەو بمێنەوە و هەرگیز گردی مێروولە مەشکێنە و مەکۆڵە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ckb', 'گوڵی دارستانی سپی', 'ئەوەندە هێواش بڵاو دەبێتەوە کە فەرشی چڕی نیشانەی دارستانێکی کۆنە.', 'لە بەهاردا، پێش ئەوەی دارەکان گەڵا بکەن بەدوای فەرشی گوڵی سپیدا بگەڕێ.', 'زەوی دارستان وەک خۆی بەجێبهێڵە تا ڕەگە هێواش‌بڵاوەکان گەشە بکەن.', 'لەو شوێنەی دەڕوێت چێژی لێوەربگرە — لێکردنەوەی گوڵێک لادەبات کە ساڵانی خایاندووە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ckb', 'گوڵی دۆڵ', 'هەموو بەشەکانی ئەم ڕووەکە بۆنخۆشە ئەگەر بخورێت ژەهراوین.', 'لە کۆتایی بەهاردا، بۆنەکە بگرە تا دارستانی سێبەردار.', 'قەراغە سێبەردارەکانی دارستان و گەڵای وەریو بەجێبهێڵە کە لێی دەڕوێت.', 'لێی مەکەرەوە و هەڵیمەکەنە، لە منداڵ و ئاژەڵی ماڵی دووری بخەرەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ckb', 'سیری کێوی', 'زۆرجار بۆنی سیری کێوی دەکەیت پێش ئەوەی گوڵە سپییەکانی ببینیت.', 'لە بەهاردا، بەدوای گەڵای پانی سەوز و گوڵی ئەستێرەییدا لە دارستانی تەڕدا بگەڕێ.', 'دارستانی تەڕ وەک خۆی بەجێبهێڵە تا فەرشەکان هەموو ساڵێک دووبارە بڕوێن.', 'ئەگەر لێکردنەوە لە ناوچەکەدا ڕێگەپێدراوە، کەمێک ببە و هەرگیز بنجەکان هەڵمەکەنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ckb', 'گوڵی زێڕینی زۆنگاو', 'یەکێکە لە کۆنترین ڕووەکە خۆماڵییەکان، لە دوایین سەردەمی سەهۆڵبەندی سکاندیناڤیا ڕزگاری بووە.', 'لە بەهاردا، بەدوای گوڵە زێڕینە گەورەکاندا لە زۆنگاو و کەناری گۆمدا بگەڕێ.', 'کەناری گۆم و جۆگەکان تەڕ و نەبڕدراو ڕابگرە تا گوڵ بکات.', 'زەوی تەڕ ئاوی لێ مەکێشە و ڕووەکەکان لە شوێنی خۆیان بەجێبهێڵە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ckb', 'گوڵی بەهاری زەرد', 'جارێک لە مەرغزارەکاندا ئەوەندە زۆر بوو کە منداڵان تۆپیان لێدروست دەکرد.', 'لە بەهاردا، بەدوای گوڵە زەردە چەماوەکاندا لە مەرغزارە کۆنەکاندا بگەڕێ.', 'مەرغزار مەبڕە تا گوڵ دەکەن و تۆو دەگرن.', 'لە سروشتدا لێی مەکەرەوە و هەڵیمەکەنە — گوڵی مەرغزار کەم دەبێتەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ckb', 'بەیبوونی گەورە', 'ئەوەی وەک یەک گوڵ دیارە لە ڕاستیدا دەیان گوڵی بچووکی تەنیشت یەکن.', 'لە هاویندا، بەدوای بەیبوونی سپیی گەورەدا لە قەراغی ڕێگا و مەرغزاردا بگەڕێ.', 'تەنیشتێک گیا لە ناوەڕاستی هاویندا نەبڕدراو بەجێبهێڵە تا گوڵ بکات.', 'قەراغی ڕێگا و مەرغزارەکان بە ژەهری گیا مەپرژێنە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ckb', 'گوڵی قاسپە', 'یەکێکە لە گرنگترین سەرچاوەکانی شەربەتی زوو بۆ هەنگ.', 'لە بەهارەوە بەدواوە لە هەموو شوێنێک؛ گوڵەکان لە خۆردا دەکرێنەوە و ئێواران دادەخرێن.', 'ڕێگە بدە لە بەهاردا پێش یەکەم بڕین لە چیمەندا گوڵ بکەن.', 'ژەهری گیای چیمەن بەکارمەهێنە تا تۆزهەڵگرە زووەکان ئەم خۆراکە گرنگە بەدەست بهێنن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ckb', 'دەوەنی کێوی', 'یەک ڕووەکی دەوەن دەتوانێت زیاتر لە سەد هەزار تۆوی بچووک بەرهەم بهێنێت.', 'لە کۆتایی هاویندا، بەدوای فەرشی مۆردا لە دەشتە کراوەکان و زۆنگاودا بگەڕێ.', 'پشتیوانی بکە لەوەی ئەم ناوچانە کراوە بمێننەوە و ئاویان لێ نەکێشرێت.', 'لەسەر ڕێڕەو بمێنەوە و لە کەشی وشکدا هەرگیز ئاگر مەکەرەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ckb', 'تووە شینەی کێوی', 'پەنجەکانت شین دەکات و لە باڵندەوە تا ورچ خۆراکی هەمووان دەدات.', 'لە هاویندا، بەدوای دەوەنە نزمەکاندا بە توویەکی تاریک لە دارستانی کاجدا بگەڕێ.', 'ڕووەکی ژێری دارستان وەک خۆی بەجێبهێڵە تا دەوەنەکان بەر بگرن.', 'ئەگەر لێکردنەوە ڕێگەپێدراوە، تووی زۆر بۆ ژیانی کێوی بەجێبهێڵە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ckb', 'تووە سوورەی کێوی', 'بەهۆی پارێزەرێکی سروشتی ناو بەرەکەیەوە بۆ مانگەها دەمێنێتەوە.', 'لە کۆتایی هاوین و پاییزدا، بەدوای تووی سووری بریسکەداردا لەسەر فەرشی هەمیشەسەوزدا بگەڕێ.', 'ڕووەکی سەر زەوی دارستان وەک خۆی بەجێبهێڵە تا فەرشەکان بڵاو ببنەوە.', 'ئەگەر لێکردنەوە ڕێگەپێدراوە، بە وریاییەوە پێ بنێ تا ڕووەکەکان نەشێلێیت.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ckb', 'داری بەڕووی زیوین', 'یەک داری بەڕووی زیوین سەدان جۆر مێروو بەخێو دەکات کە خۆراکی باڵندەی بێشوماری تێدایە.', 'بە درێژایی ساڵ؛ توێکڵە سپییە هەڵکەندراوەکەی لە هەموو وەرزێکدا ناسینەوەی ئاسان دەکات.', 'گەڵا وەریوەکان و داری مردوو بەجێبهێڵە تا خاک دەوڵەمەند بکات و مێروو بەخێو بکات.', 'توێکڵەکە هەڵمەکەنە، دار برینداری دەکات و لاوازی دەکات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ckb', 'داری کاجی نەرویجی', 'کاجێک لە سوێد لە ڕەگێکەوە دەڕوێت کە هەزاران ساڵ تەمەنی هەیە.', 'بە درێژایی ساڵ لە دارستاندا؛ تۆپکە شۆڕەکانی درێژترینن لەنێو هەموو کاجەکاندا.', 'تۆپکە وەریوەکان و داری مردوو بەجێبهێڵە کە پەناگەی مێروو و کەڕووە.', 'لە دارستاندا لەسەر ڕێڕەو بمێنەوە تا ڕەگە قووڵ‌نەبووەکانی کاج نەپەستێن.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ckb', 'داری سنەوبەری سکۆتلەندی', 'سنەوبەرە کۆنەکان لە سەرەوە بە پرتەقاڵی دەدرەوشێنەوە و دەتوانن سەدان ساڵ بژین.', 'بە درێژایی ساڵ لە زەوی خۆڵ و بەردیندا؛ بەدوای توێکڵە پرتەقاڵییەکەی سەرەوەدا بگەڕێ.', 'داری مردووی ڕاوەستاو و سنەوبەرە کۆنەکان بەجێبهێڵە کە پڕن لە ژیان.', 'هەرگیز لە زەوی خۆڵینی وشکدا لە نزیک سنەوبەردا ئاگر مەکەرەوە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ckb', 'ماسی پایکی باکوور', 'ڕاوکەرێکی بۆسەگرە کە لە بێدەنگییەوە بە چاوتروکانێک هەڵدەدات.', 'لە بەهارەوە تا پاییز لە ئاوە کەم‌قووڵە گیاوییەکانی دەریاچە و ڕووبارە هێوارەکاندا.', 'پشتیوانی لە پاراستنی قامیشەڵان و ڕووەکی ئاوی بکە کە ماسییە بچووکەکان تێیدا پەنا دەگرن.', 'پیسبوون و زبڵ لە ئاو دووربخەرەوە؛ یاسا خۆجێییەکانی ڕاوی ماسی پەیڕەو بکە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ckb', 'ماسی پەرچی ئەورووپی', 'بە کۆمەڵ ڕاو دەکەن و هێڵە تۆخەکانیان شێوەی لەشیان دەشێوێنن.', 'لە مانگە گەرمەکاندا لە دەوروبەری بەندەر و گیای ئاوی و نشێوەکاندا.', 'پشتیوانی لە ئاوی پاک و پێکهاتەی ژێرئاو بکە کە ماسییە بچووکەکان دەپارێزێت.', 'هەرگیز شت فڕێمەدە ناو دەریاچە و ڕووبار؛ یاسا خۆجێییەکانی ڕاوی ماسی پەیڕەو بکە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ckb', 'ماسی ڕۆچ', 'ماسییەکی خۆراکی سەرەکییە کە زۆرێک لە ڕاوکەرانی دەریاچە پشتی پێدەبەستن.', 'لە مانگە گەرمەکاندا، بە کۆمەڵ لە نزیک ڕووی دەریاچە و ڕووبارە هێوارەکاندا.', 'پشتیوانی لە پاکی ئاو و ڕووەکداری کەنارەکان بکە بۆ تۆوکردن.', 'ئاوی ڕۆیشتوو و زبڵ لە ئاو دووربخەرەوە؛ یاسا خۆجێییەکانی ڕاوی ماسی پەیڕەو بکە.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'tr', 'Ebabil', 'Ebabiller aylarca havada kalabilir, hatta uçarken uyurlar.', 'Sıcak yaz akşamlarında çatıların üstüne bakın ve cıyaklayan sürüleri dinleyin.', 'Kuşlar ilkbaharda dönmeden önce saçak altına bir yuva kutusu asın.', 'Tadilat yaparken saçak altındaki, yuva yaptıkları küçük boşlukları koruyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'tr', 'Kır kırlangıcı', 'Kır kırlangıçları her yıl Güney Afrika’ya kadar göç edip geri dönerler.', 'İlkbahardan erken sonbahara, tarlaların ve suların üzerinde alçak uçarken arayın.', 'Yuva çıkıntılarına ulaşabilmeleri için ahır ya da depo kapısını aralık bırakın.', 'Eski çamur yuvaları yıkmayın — kırlangıçlar onları yıllarca yeniden kullanır.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'tr', 'Guguk kuşu', 'Yumurtalarını başka kuşların yuvasına bırakır, kendi yavrularını hiç büyütmez.', 'İlkbahar sonunda orman kenarından gelen uzaktan duyulan "gu-guk" sesini dinleyin.', 'Guguğun bağlı olduğu kuşları besleyen böcek zengini çayır ve çitleri destekleyin.', 'Çalılık ve sazlık yakınında patikalarda kalın ki konak kuşlar rahatsız olmasın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'tr', 'Kızılgerdan', 'Bölgelerini şiddetle savunur, sokak lambalarının yanında gece boyunca öterler.', 'Yıl boyu bahçelerde ve ormanda; çoğu zaman toprağı kazan kişiyi solucan umuduyla izlerler.', 'Bahçenin bir köşesini dökülen yapraklarla bırakın ki orada yiyecek arasınlar.', 'Ağır çit budamasını yaz sonunda kuluçka bitene kadar erteleyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'tr', 'Karatavuk', 'Erkeğin zengin, flüt gibi ötüşü Avrupa’nın en tanınmış seslerinden biridir.', 'Yıl boyu; şafakta ve akşam çatılardan, ağaç tepelerinden öten erkekleri dinleyin.', 'Özellikle kurak dönemlerde içmek ve yıkanmak için temiz su koyun.', 'Kuluçka mevsiminde kedileri şafak vakti evde tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'tr', 'Tarla ardıcı', 'Kışın gürültülü, cıvıldayan sürüler halinde dolaşan sosyal bir ardıç kuşudur.', 'Sonbahar ve kışın sürülerin çitlerden ve ağaçlardan meyve topladığını izleyin.', 'Meyveli çalıları kış boyunca budamadan bırakın.', 'Kışın yere düşen elmaları bırakın — soğukta hayati bir besindir.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'tr', 'Büyük baştankara', 'Çok geniş bir ses dağarcıkları vardır ve komşularından yeni sesler öğrenirler.', 'Yıl boyu; kış sonundan itibaren çınlayan, yinelenen ötüşünü dinleyin.', '32 mm delikli bir yuva kutusunu sessiz, gölgeli bir yere asın.', 'Yavruları beslemeye yetecek tırtıl kalsın diye bahçe ilaçlarından kaçının.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'tr', 'Mavi baştankara', 'Tek bir yavru grubu binden fazla tırtıl yiyebilir.', 'Yıl boyu bahçelerde ve ormanlarda, çoğu kez ince dallardan baş aşağı sarkarlar.', '25 mm delikli küçük bir yuva kutusunu hâkim rüzgârdan uzağa yerleştirin.', 'Yavrulara tırtıl kalsın diye ilkbaharda böcek ilacı kullanmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'tr', 'İspinoz', 'Ötüşleri bölgeden bölgeye değişir, neredeyse yerel bir ağız gibi.', 'İlkbahardan sonbahara; erkekler açık tüneklerden parlak, alçalan bir ezgi söyler.', 'Bazı tohum başlarını ve otlu alanları mevsim boyunca ayakta bırakın.', 'İspinozlar arasında hastalık yayılmasın diye yemlikleri temiz tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'tr', 'Alakarga', 'Her sonbahar binlerce meşe palamudu gömer, bazılarını unutup meşe ormanları diker.', 'Yıl boyu meşe ormanlarında; sonbaharda pembe ve mavi parıltılara dikkat edin.', 'Meşelerin altındaki dökülmüş palamutları ve yaprakları olduğu gibi bırakın.', 'Yerde beslenen kuşlar ürkmesin diye köpekleri ormanda patikada tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'tr', 'Büyük ağaçkakan', 'İlkbahardaki tıkırtısı beslenmek için değil, bölgesini ilan eden hızlı bir ritimdir.', 'Yıl boyu; kış sonunda ormanda yankılanan tıkırtıyı dinleyin.', 'Ayakta duran ölü odunu bırakın; beslendiği böcekler orada yaşar.', 'Ölü ya da kuruyan ağaçları kesmeyin, yuva delikleri barındırabilirler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'tr', 'Ak kuyruksallayan', 'Kuyruğunu sürekli sallaması avcılara karşı tetikte olduğunun işareti olabilir.', 'İlkbahardan sonbahara su kenarında ve açık alanda; koşup durarak böcek kapar.', 'Su yakınında kısa çim ya da çakıllı bir alan bırakın ki orada yem arasın.', 'Beslendiği ve yuva yaptığı çakıllı kıyıları rahatsız etmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'tr', 'Turna', 'İlkbahar başında sıçrayıp eğilerek kur dansları yaparlar.', 'İlkbahardan sonbahara sulak alanlarda; kilometrelerce duyulan borazan sesini dinleyin.', 'Ürediği, kurutulmamış bataklık ve ıslak çayırların korunmasını destekleyin.', 'Yuva yaptıkları sulak alanları uzaktan izleyin — rahatsız edilen yuvayı terk ederler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'tr', 'Ötücü kuğu', 'Ömür boyu eş tutar ve gelişlerini yüksek, borazan gibi seslerle duyururlar.', 'İlkbahar ve sonbaharda göllerde ve su basmış tarlalarda, çoğu kez aile grupları hâlinde.', 'Sığ göl kenarlarının ve ıslak tarlaların kurutulmamasını destekleyin.', 'Kuğulara asla ekmek vermeyin — zarar verir; buz üzerinde de mesafenizi koruyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'tr', 'Yeşilbaş ördek', 'Yavrular yumurtadan çıktıktan birkaç saat sonra yüzebilir ve kendi başlarına beslenebilir.', 'Yıl boyu neredeyse her gölette, gölde ya da yavaş akan nehirde.', 'Yem verecekseniz ekmek yerine yulaf, bezelye ya da tohum kullanın.', 'İlkbaharda ördeklerin kuluçkaya yattığı sudan köpekleri uzak tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'tr', 'Şahin (bayağı doğan)', 'Geniş kanatlarıyla süzülür ve kedi miyavlamasına benzer bir ses çıkarır.', 'İlkbahardan sonbahara; tarlaların ve orman kenarlarının üstünde daire çizerken arayın.', 'Tarla farelerini barındıran kaba çayırları ve tarla kenarlarını destekleyin.', 'Asla kemirgen zehri kullanmayın; besin zinciriyle yırtıcı kuşlara ulaşır.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'tr', 'Balık kartalı', 'Balık yakalamak için önce ayaklarıyla dalar ve kendi ağırlığının yarısını taşıyabilir.', 'İlkbahardan sonbahara büyük göllerin yakınında; havada asılı kalıp sonra dalar.', 'Balık zengini göllerin yanında yüksek direklere yuva platformları kurulmasını destekleyin.', 'Çiftler yumurtalarını bırakıp kaçmasın diye yuva platformlarından çok uzak durun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'tr', 'Kızıl tilki', 'Gizlenmiş ava atlarken mesafeyi kestirmek için Dünya’nın manyetik alanından yararlanırlar.', 'Yıl boyu, en çok şafakta ve akşam orman ve tarla kenarlarında etkindirler.', 'Dinlenip in kazabilecekleri sessiz, doğal bir köşe bırakın.', 'Çöp kutularını kapatın ve tilkilere asla zararlı yiyecek artığı bırakmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'tr', 'Avrupa kirpisi', 'Bir kirpi tek bir gecede yiyecek ararken birkaç kilometre yol gidebilir.', 'İlkbahardan sonbahara karanlıktan sonra; kışın yaprak ve odun yığınları altında uyurlar.', 'Bahçeler arasında dolaşabilmeleri için çitte 13 cm’lik bir boşluk açın.', 'Uzun otu biçmeden önce kontrol edin ve kış uykusu için yaprak yığınlarını bırakın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'tr', 'Karaca', 'Gebeliklerini geciktirirler, böylece yavrular hep yaz başında doğar.', 'Yıl boyu orman kenarlarında, en çok şafakta ve akşam otlarken görülürler.', 'Barınak ve besin sağlayan biçilmemiş tarla kenarlarını ve çalılıkları destekleyin.', 'Yavruların gizlendiği yaz başında köpekleri orman yakınında tasmalı tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'tr', 'Mus geyiği', 'Dünyanın en büyük geyiğidir; iri bir erkek yarım tondan fazla gelebilir.', 'Yıl boyu ormanlarda ve sulak alanlarda, en çok şafakta ve akşam etkin.', 'Dolaşmak için ihtiyaç duydukları bağlantılı ormanları ve sulak koridorları destekleyin.', 'Orman yollarında şafak ve akşam dikkatli sürün, yavruya asla yaklaşmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'tr', 'Kızıl sincap', 'Birden fazla yuva yapar ve aralarında yer değiştirirler.', 'Yıl boyu iğne yapraklı ve karışık ormanlarda, en hareketli sabahın erken saatlerinde.', 'Beslendikleri ve yuva yaptıkları kozalakları, fındıkları ve ayakta ağaçları bırakın.', 'Köpekleri patikada tutun ve yuva barındırabilecek ağaçları rahatsız etmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'tr', 'Avrupa kunduzu', 'Barajları kilometrelerce boyunca balığı, kuşu ve böceği artıran sulak alanlar yaratır.', 'İlkbahardan geç sonbahara yavaş nehirlerde, en çok alacakaranlıkta etkin.', 'Güvenli olduğu yerde barajların ve su kenarı ağaçlarının yerinde kalmasını destekleyin.', 'Yuvalardan ve barajlardan uzak durun, özellikle yavrular küçükken.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'tr', 'Dağ tavşanı', 'Kışın kara karşı kamufle olmak için beyaza dönerler.', 'Yıl boyu açık arazide ve orman açıklıklarında, çoğunlukla şafakta ve akşam.', 'Yıl boyunca ihtiyaç duydukları açık alan ile örtü karışımını destekleyin.', 'Dinlenen tavşanlar kovalanmasın diye açık arazide köpekleri tasmalı tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'tr', 'Porsuk', 'Kuşaklar boyu kullanılan yer altı yuvalarında aile grupları hâlinde yaşarlar.', 'İlkbahardan sonbahara karanlıktan sonra orman yakınında; kışı uyuyarak geçirirler.', 'Yuva kazabilecekleri el değmemiş şevleri ve çitleri bırakın.', 'Etkin bir yuvayı asla kapatmayın ya da yakınını kazmayın — uzun süreli evleridir.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'tr', 'Cüce yarasa', 'Bu küçücük yarasa bir gecede 3.000’e kadar tatarcık ve sivrisinek yiyebilir.', 'Yaz akşamlarında, bahçelerin üstünde alacakaranlıkta hızlı, zikzaklı uçuşunu izleyin.', 'Akşam güneşi alan bir duvara ya da ağaca yüksekten yarasa kutusu asın.', 'Barınak girişlerinde parlak ışıktan kaçının ve gece göğünü karanlık tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'tr', 'Küçük kaplumbağa kelebeği', 'Bu kelebek erişkin hâlde kış uykusuna yatar, çoğu kez depolarda ve çatı aralarında.', 'Erken ilkbahardan sonbahara güneşli çiçeklerde, özellikle ısırganda.', 'Güneşli bir köşede bir parça ısırgan bırakın — tırtılları buna muhtaçtır.', 'Depolarda kış uykusundaki kelebekleri kış boyunca rahatsız etmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'tr', 'Tavus kelebeği', 'Göz benekleri kuşları ürkütür, kanatları açılırken tıslama sesi çıkarabilir.', 'İlkbahardan sonbahara güneşli günlerde; devedikeni ve düşmüş meyvelerle beslenir.', 'Tırtılları için güneşli bir ısırgan alanının büyümesine izin verin.', 'Kışın depolarda ve odun yığınlarında barınan erişkinleri rahatsız etmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'tr', 'Kükürt kelebeği', 'İngilizcedeki "butterfly" sözcüğü bu türün erkeğinin tereyağı sarısı renginden gelmiş olabilir.', 'İlkbaharın ilk kelebeklerindendir; ılık günlerde orman kenarlarında arayın.', 'Çitlerdeki cehri çalılarını destekleyin, tırtıllarının yediği tek bitkidir.', 'Kışlayan erişkinleri barındıran çalılı çitleri temizlemeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'tr', 'Turuncu uçlu kelebek', 'Yalnızca erkeklerin kanat uçları parlak turuncudur; dişiler beyazdır.', 'İlkbaharda nemli çayırlarda ve kır yollarında, kır çiçeklerinin bittiği yerlerde.', 'Nemli, biçilmemiş köşelerde kır çiçeklerinin büyümesine izin verin.', 'Tırtılları beslenmeyi bitirene kadar yol kenarlarını biçmeyi erteleyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'tr', 'Çokgözlü mavi kelebek', 'Tırtıllarına bazen karıncalar tatlı salgıları karşılığında bakar.', 'İlkbahar sonundan itibaren yonca bakımından zengin güneşli çayırlarda.', 'Yoncalar çiçek açabilsin diye çayırı biçmeden bırakın.', 'Kır çiçeği zengini çayırlara yabani ot ilacı püskürtmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'tr', 'Yeşil damarlı beyaz kelebek', 'Lahana kelebeğine benzese de bahçe ürünlerini değil yabani bitkileri tercih eder.', 'İlkbahardan yaz sonuna nemli çayırlarda, hendeklerde ve orman yollarında.', 'Nemli köşelerin yerli yabani bitkilerle doğallaşmasına izin verin.', 'Ürediği nemli çayırları kurutmayın ve ilaçlamayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'tr', 'Yedi noktalı uğur böceği', 'Tek bir uğur böceği ömrü boyunca binlerce yaprak biti yiyebilir.', 'İlkbahardan sonbahara yaprak bitli bitkilerde; kışın toplu hâlde uyurlar.', 'Biraz yaprak bitine katlanın ve ilaçlamayın ki besinleri olsun.', 'Kışın barındıkları içi boş sapları ve dökülmüş yaprakları bırakın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'tr', 'Sarı kuyruklu bombus arısı', 'Kraliçeler ilkbaharın ilk arılarındandır; yuva deliği ararken alçaktan vızıldarlar.', 'Erken ilkbahardan sonbahara çiçeklerde; kraliçeler ilkbaharda çit diplerini arar.', 'Erken çiçek açan bitkiler yetiştirin ya da bırakın, çimde yoncanın çiçeklenmesine izin verin.', 'Kolonilerin yuvalandığı el değmemiş şevleri ve eski fare deliklerini bırakın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'tr', 'Bal arısı', 'Yiyecek arayan arı, sekiz şeklinde dans ederek kovana çiçeklerin yerini anlatır.', 'İlkbahardan sonbahara ılık ve rüzgârsız günlerde çiçeklerde.', 'Mevsimler boyunca çeşitli çiçeklerin açmasına izin verin ve sığ bir su kabı bırakın.', 'Çiçekli bitkileri ilaçlamayın ve asla günün ortasında ilaç püskürtmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'tr', 'İmparator yusufçuk', 'Avrupa’nın en büyük yusufçuklarından biridir, avını havada bile yakalayabilir.', 'Sıcak yaz günlerinde göletleri ve göl kenarlarını devriye gezerken izleyin.', 'Bitkili bir gölet tutun ya da kazın ve kenarlarını bitkili bırakın.', 'Larvalar gelişebilsin diye göletleri kirlilikten ve akıntıdan koruyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'tr', 'Bayağı kızböceği', 'Çoğu kez aynı sıcak noktaya konar ve geçen böcekleri kapmak için fırlar.', 'Yaz ortasından sonbahara durgun su yakınında, patikalarda ve direklerde güneşlenir.', 'Göletlerin ve hendeklerin çevresinde güneşli tünekleri ve bitkileri bırakın.', 'Larvaların yaşadığı göletlere gübre ya da yağ karışmasına izin vermeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'tr', 'Kızıl orman karıncası', 'Yuva tepeleri bir metreyi aşabilir ve yarım milyon karınca barındırabilir.', 'İlkbahardan sonbahara iğne yapraklı ormanlarda; iğne yapraklardan kubbeli tepeler arayın.', 'Yuva tepelerini olduğu gibi bırakın — yapımı yıllar sürer.', 'Patikada kalın ve bir karınca tepesine asla tekme atmayın ya da kazmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'tr', 'Orman anemonu', 'O kadar yavaş yayılır ki sık örtüsü kadim ormanın işaretidir.', 'İlkbaharda, ağaçlar yapraklanmadan önce beyaz çiçek halılarını arayın.', 'Yavaş yayılan kökleri gelişebilsin diye orman tabanını el değmemiş bırakın.', 'Bittiği yerde keyfini çıkarın — koparmak, yayılması yıllar almış bir çiçeği yok eder.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'tr', 'İnci çiçeği', 'Bu güzel kokulu bitkinin her parçası yendiğinde zehirlidir.', 'İlkbahar sonunda kokuyu izleyerek gölgeli ormanlara gidin.', 'Bittiği gölgeli orman kenarlarını ve dökülmüş yaprakları bırakın.', 'Koparmayın ve sökmeyin; çocuklardan ve evcil hayvanlardan uzak tutun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'tr', 'Yabani sarımsak', 'Yabani sarımsağı çoğu kez beyaz çiçeklerini görmeden önce kokusundan fark edersiniz.', 'İlkbaharda nemli ormanlarda geniş yeşil yaprakları ve yıldız çiçekleri arayın.', 'Örtüler her yıl yeniden büyüsün diye nemli ormanı el değmemiş bırakın.', 'Yerel olarak toplamaya izin varsa azıcık alın ve soğanları asla sökmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'tr', 'Bataklık nergisi', 'En eski yerli bitkilerden biridir; İskandinavya’da son Buz Çağı’ndan sağ çıkmıştır.', 'İlkbaharda bataklıklarda, hendeklerde ve gölet kenarlarında iri altın çiçekleri arayın.', 'Çiçek açabilsin diye gölet ve hendek kenarlarını ıslak ve biçilmemiş tutun.', 'Islak zemini kurutmayın ve bitkileri bittikleri yerde bırakın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'tr', 'Çuha çiçeği', 'Bir zamanlar çayırlarda o kadar boldu ki çocuklar onlardan top yapardı.', 'İlkbaharda eski, işlenmemiş çayırlarda sarkan sarı çiçekleri arayın.', 'Çuha çiçekleri açıp tohum bağlayana kadar çayırı biçmeyin.', 'Doğadan koparmayın ve sökmeyin — çayır çiçekleri azalıyor.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'tr', 'Büyük papatya', 'Tek bir çiçek gibi görünen şey aslında bir arada duran onlarca minik çiçektir.', 'Yazın yol kenarlarında ve çayırlarda iri beyaz papatyaları arayın.', 'Çiçek açabilsin diye yaz ortasında bir şerit çimi biçmeden bırakın.', 'Yol kenarlarına ve çayırlara yabani ot ilacı püskürtmeyin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'tr', 'Karahindiba', 'Karahindiba arılar için en önemli erken nektar kaynaklarından biridir.', 'İlkbahardan itibaren neredeyse her yerde; çiçekler güneşte açılır, akşam kapanır.', 'İlkbaharda ilk biçimden önce çimde çiçek açmalarına izin verin.', 'Erken tozlaştırıcılar bu hayati besini bulsun diye çim ilacı kullanmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'tr', 'Süpürge çalısı', 'Tek bir süpürge çalısı yüz binden fazla minik tohum üretebilir.', 'Yaz sonunda açık fundalıklarda ve bataklıklarda mor örtüleri arayın.', 'Fundalıkların açık ve kurutulmamış kalmasını destekleyin.', 'Fundalıklarda patikada kalın ve kuru havada asla ateş yakmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'tr', 'Yaban mersini', 'Parmaklarınızı maviye boyar ve kuşlardan ayılara kadar her şeyi besler.', 'Yazın çam ve ladin ormanlarında koyu meyveli alçak çalıları arayın.', 'Alçak çalılar meyve verebilsin diye orman altı örtüsünü bozmayın.', 'Yerel olarak toplamaya izin varsa yaban hayatı için bolca meyve bırakın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'tr', 'Kırmızı yaban mersini', 'Meyvesindeki doğal bir koruyucu sayesinde aylarca bozulmadan durur.', 'Yaz sonunda ve sonbaharda her dem yeşil örtüler üzerinde parlak kırmızı meyveleri arayın.', 'Örtüler yayılabilsin diye orman tabanı bitkilerini el değmemiş bırakın.', 'Toplamaya izin varsa bitkileri ezmemek için dikkatle basın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'tr', 'Gümüşi huş ağacı', 'Bir huş ağacı yüzlerce böcek türünü besler, onlar da sayısız kuşu doyurur.', 'Yıl boyu; beyaz, soyulan kabuğu her mevsim tanınmasını kolaylaştırır.', 'Toprağı zenginleştirsin ve böcekleri beslesin diye dökülen yaprakları ve ölü odunu bırakın.', 'Kabuğu soymayın; ağacı yaralar ve zayıflatır.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'tr', 'Norveç ladini', 'İsveç’teki bir Norveç ladini binlerce yıllık köklerden büyümektedir.', 'Yıl boyu ormanlarda; sarkan kozalakları tüm ladinler arasında en uzunudur.', 'Böcek ve mantarları barındıran düşmüş kozalakları ve ölü odunu bırakın.', 'Ladinin yüzeysel kökleri sıkışmasın diye ormanda patikada kalın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'tr', 'Sarıçam', 'Yaşlı sarıçamlar tepeye yakın turuncu parlar ve yüzyıllarca yaşayabilir.', 'Yıl boyu kumlu ve kayalık zeminde; üst gövdedeki turuncu kabuğu arayın.', 'Yaban hayatı bakımından zengin olan ayakta ölü odunu ve yaşlı çamları bırakın.', 'Kuru, kumlu zeminde çamların dibinde ya da yakınında asla ateş yakmayın.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'tr', 'Turna balığı', 'Pusu kuran bir avcıdır; hareketsizken göz açıp kapayıncaya kadar atılabilir.', 'İlkbahardan sonbahara göllerin ve yavaş nehirlerin otlu sığlıklarında.', 'Yavru balıkların barındığı sazlı sığlıkların ve su bitkilerinin korunmasını destekleyin.', 'Kirliliği ve çöpü sudan uzak tutun; yerel balıkçılık kurallarına uyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'tr', 'Tatlı su levreği', 'Sürüler hâlinde avlanır; belirgin çizgileri vücut hatlarını gizler.', 'Ilık aylarda iskelelerin, su bitkilerinin ve derinleşen kenarların çevresinde.', 'Küçük balıkları barındıran temiz suyu ve su altı yapılarını destekleyin.', 'Göllere ve nehirlere asla bir şey dökmeyin; yerel balıkçılık kurallarına uyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'tr', 'Kızılkanat balığı', 'Birçok göl avcısının bağlı olduğu kilit bir yem balığıdır.', 'Ilık aylarda göllerin ve yavaş nehirlerin yüzeyine yakın sürüler hâlinde.', 'Yumurtlama için suyun temiz ve kenarların bitkili kalmasını destekleyin.', 'Akıntıyı ve çöpü sudan uzak tutun; yerel balıkçılık kurallarına uyun.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'bs', 'Obična čiopa', 'Čiope mogu mjesecima ostati u zraku, čak i spavaju u letu.', 'Toplih ljetnih večeri gledajte visoko iznad krovova i slušajte vrišteća jata.', 'Postavite kućicu za gniježđenje pod strehu prije nego se ptice vrate u proljeće.', 'Pri renoviranju sačuvajte male otvore pod strehom u kojima se gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'bs', 'Lastavica pokućarka', 'Lastavice svake godine sele sve do juga Afrike i natrag.', 'Od proljeća do rane jeseni tražite ih kako nisko klize iznad polja i vode.', 'Ostavite vrata štale ili šupe odškrinuta da dođu do svojih gnijezda.', 'Ne rušite stara blatna gnijezda — lastavice ih koriste iz godine u godinu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'bs', 'Kukavica', 'Kukavica polaže jaja u gnijezda drugih ptica i nikada ne odgaja vlastite mlade.', 'U kasno proljeće slušajte daleki zov "ku-ku" s rubova šume.', 'Podržite livade i živice bogate insektima koje hrane ptice o kojima kukavica ovisi.', 'Držite se staza uz šikaru i trščake da ptice domaćini ne budu uznemirene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'bs', 'Crvendać', 'Crvendaći žestoko brane teritorij i pjevaju kroz noć blizu uličnih svjetiljki.', 'Cijele godine u vrtovima i šumama; često prate onoga ko kopa, nadajući se glistama.', 'Ostavite kut vrta s otpalim lišćem gdje mogu tražiti hranu.', 'Odgodite jako orezivanje živice dok gniježđenje ne završi u kasno ljeto.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'bs', 'Kos', 'Bogata, flautasta pjesma mužjaka jedna je od najprepoznatljivijih u Evropi.', 'Cijele godine; u zoru i sumrak slušajte mužjake kako pjevaju s krovova i krošnji.', 'Iznesite svježu vodu za piće i kupanje, naročito u sušnim razdobljima.', 'U sezoni gniježđenja držite mačke u kući u zoru.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'bs', 'Drozd bravenjak', 'Društveni je drozd koji zimi luta bučnim, brbljavim jatima.', 'U jesen i zimu gledajte jata kako skidaju bobice s živica i stabala.', 'Ne orezujte grmlje s bobicama tokom zime.', 'Ostavite otpale jabuke na tlu zimi — u hladnoći su ključna hrana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'bs', 'Velika sjenica', 'Imaju velik glasovni repertoar i uče nove zovove od susjeda.', 'Cijele godine; od kasne zime slušajte zvonku, ponavljajuću pjesmu.', 'Objesite kućicu s otvorom od 32 mm na mirno, sjenovito mjesto.', 'Izbjegavajte vrtne pesticide da ostane dovoljno gusjenica za hranjenje mladih.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'bs', 'Plava sjenica', 'Jedno leglo plavih sjenica može pojesti više od hiljadu gusjenica.', 'Cijele godine u vrtovima i šumama, često vise naopako s tankih grančica.', 'Postavite malu kućicu s otvorom od 25 mm dalje od prevladavajućeg vjetra.', 'U proljeće preskočite insekticide da gusjenice budu dostupne mladima.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'bs', 'Zeba', 'Pjesma zebe razlikuje se po krajevima, gotovo kao lokalni dijalekti.', 'Od proljeća do jeseni; mužjaci pjevaju vedru, silaznu frazu s otvorenih grana.', 'Ostavite dio sjemenskih glavica i travnatih površina kroz sezonu.', 'Držite hranilice čistima da se bolest ne širi među zebama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'bs', 'Šojka', 'Svake jeseni zakopa hiljade žireva i, zaboravljajući neke, posadi cijele hrastove šume.', 'Cijele godine u hrastovim šumama; u jesen pazite na bljeskove ružičaste i plave.', 'Ostavite otpale žireve i lišće pod hrastovima netaknutima.', 'Držite pse na stazama u šumi da se ptice koje se hrane na tlu ne uznemire.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'bs', 'Veliki djetlić', 'Proljetno bubnjanje nije traženje hrane nego brz ritam kojim označava teritorij.', 'Cijele godine; u kasnu zimu slušajte bubnjanje koje odzvanja šumom.', 'Ostavite stojeće mrtvo drvo u kojem žive insekti kojima se hrani.', 'Ne sijecite mrtva ili sušna stabla koja mogu sadržavati gnijezda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'bs', 'Bijela pastirica', 'Stalno njihanje repa možda signalizira opreznost pred grabežljivcima.', 'Od proljeća do jeseni uz vodu i otvoreno tlo; trči i zastaje da uhvati insekte.', 'Uz vodu održavajte komad niske trave ili šljunka gdje može tražiti hranu.', 'Ne uznemiravajte šljunkovite obale gdje se hrani i gnijezdi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'bs', 'Ždral', 'U rano proljeće izvode svadbene plesove sa skokovima i naklonima.', 'Od proljeća do jeseni oko močvara; slušajte trubljenje koje se čuje kilometrima.', 'Podržite zaštitu neisušenih tresetišta i vlažnih livada u kojima se gnijezde.', 'Gnijezdeća močvarna staništa promatrajte izdaleka — uznemireno gnijezdo napuštaju.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'bs', 'Labud pjevač', 'Labudovi pjevači se pare doživotno i dolazak najavljuju glasnim trubljenjem.', 'U proljeće i jesen na jezerima i poplavljenim poljima, često u porodičnim grupama.', 'Podržite očuvanje plitkih rubova jezera i vlažnih polja bez isušivanja.', 'Nikada ne hranite labudove hljebom — škodi im; na ledu držite odstojanje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'bs', 'Divlja patka', 'Pačići plivaju i sami se hrane već nekoliko sati nakon izlijeganja.', 'Cijele godine na gotovo svakom ribnjaku, jezeru ili sporoj rijeci.', 'Ako ih hranite, koristite zob, grašak ili sjemenke umjesto hljeba.', 'U proljeće držite pse podalje od vode u kojoj se patke gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'bs', 'Škanjac', 'Lebdi na širokim krilima i često se glasa mačkastim "pijaaau".', 'Od proljeća do jeseni; tražite ga kako kruži visoko iznad polja i rubova šume.', 'Podržite grube travnjake i rubove polja u kojima žive voluharice i sitan plijen.', 'Nikada ne koristite otrove za glodare; lancem ishrane dospijevaju do ptica grabljivica.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'bs', 'Orao ribar', 'Roni nogama naprijed da uhvati ribu i može ponijeti plijen upola svoje težine.', 'Od proljeća do jeseni uz velika jezera; prvo lebdi, potom slijedi dramatičan uron.', 'Podržite postavljanje gnijezdećih platformi na visokim stupovima uz jezera bogata ribom.', 'Zaobiđite gnijezdeće platforme nadaleko da parovi ne napuste jaja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'bs', 'Crvena lisica', 'Lisice se služe Zemljinim magnetskim poljem pri procjeni skoka na skriveni plijen.', 'Cijele godine, najaktivnije u zoru i sumrak uz rubove šume i polja.', 'Ostavite divlji, mirni kut gdje se lisice mogu odmarati i kopati jazbinu.', 'Osigurajte kante i nikada ne ostavljajte štetne ostatke hrane lisicama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'bs', 'Evropski jež', 'Jež u jednoj noći traženja hrane može prijeći nekoliko kilometara.', 'Od proljeća do jeseni nakon mraka; zimi spava pod hrpama lišća i trupaca.', 'Napravite otvor od 13 cm u ogradi da ježevi mogu prelaziti između vrtova.', 'Provjerite visoku travu prije košnje i ostavite hrpe lišća za zimski san.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'bs', 'Srna', 'Srne odgađaju trudnoću tako da se lanad uvijek rađa u rano ljeto.', 'Cijele godine na rubovima šume, najvidljivije pri ispaši u zoru i sumrak.', 'Podržite nepokošene rubove polja i šikaru koje daju zaklon i hranu.', 'U rano ljeto, kad lanad leži skrivena, držite pse na povodcu uz šumu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'bs', 'Los', 'Los je najveći jelen na svijetu; krupan mužjak može težiti preko pola tone.', 'Cijele godine u šumama i močvarama, najaktivniji u zoru i sumrak.', 'Podržite povezane šume i močvarne koridore kojima se los kreće.', 'Vozite oprezno u zoru i sumrak šumskim putevima i nikada ne prilazite mladunčetu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'bs', 'Crvena vjeverica', 'Grade više gnijezda i sele se između njih.', 'Cijele godine u četinarskim i mješovitim šumama, najaktivnije rano ujutro.', 'Ostavite češere, orašaste plodove i stojeća stabla u kojima se hrane i gnijezde.', 'Držite pse na stazama i ne uznemiravajte stabla koja mogu sadržavati gnijezdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'bs', 'Evropski dabar', 'Dabrove brane stvaraju močvare koje kilometrima podižu broj riba, ptica i insekata.', 'Od proljeća do kasne jeseni uz spore rijeke, najaktivniji u sumrak.', 'Podržite ostavljanje brana i priobalnog drveća gdje je to sigurno.', 'Držite se podalje od nastambi i brana, naročito dok su mladunci mali.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'bs', 'Planinski zec', 'Zimi pobijele radi maskiranja na snijegu.', 'Cijele godine na otvorenom tlu i šumskim čistinama, uglavnom u zoru i sumrak.', 'Podržite mješavinu otvorenog tla i zaklona koja im treba tokom godine.', 'Držite pse na povodcu na otvorenom da se zečevi u odmoru ne progone.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'bs', 'Jazavac', 'Žive u porodičnim skupinama u podzemnim jazbinama koje se koriste generacijama.', 'Od proljeća do jeseni nakon mraka blizu šume; zimu prespavaju.', 'Ostavite netaknute obronke i živice gdje jazavci mogu kopati jazbine.', 'Nikada ne zatvarajte aktivnu jazbinu niti kopajte blizu nje — to je njihov trajni dom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'bs', 'Patuljasti šišmiš', 'Ovaj sićušni šišmiš može u jednoj noći pojesti do 3.000 mušica i komaraca.', 'Ljetnih večeri pratite brz, isprekidan let u sumrak iznad vrtova.', 'Postavite kućicu za šišmiše visoko na zid ili stablo koje hvata večernje sunce.', 'Izbjegavajte jaka svjetla na ulazima skloništa i održavajte noćno nebo tamnim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'bs', 'Mali kostrijet leptir', 'Ovaj leptir prezimljava kao odrastao, često u šupama i potkrovljima.', 'Od ranog proljeća do jeseni na sunčanim cvjetovima, naročito na koprivi.', 'Ostavite komad kopriva u sunčanom kutu — gusjenicama su nužne.', 'Ne uznemiravajte leptire koji prezimljavaju u šupama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'bs', 'Paunovo oko', 'Očaste mrlje bljesnu da preplaše ptice, a krila pri otvaranju mogu zasiktati.', 'Od proljeća do jeseni po suncu, hrani se čkaljem i otpalim voćem.', 'Pustite da sunčani busen kopriva raste za njegove gusjenice.', 'Ne dirajte odrasle koji zimi borave u šupama i hrpama drva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'bs', 'Limunov leptir', 'Engleska riječ za leptira možda potječe od maslačastožute boje mužjaka ove vrste.', 'Jedan od prvih proljetnih leptira; toplih dana tražite ga uz rubove šume.', 'Podržite grmove krkavine u živicama, jedine biljke koje gusjenice jedu.', 'Ne krčite šikaraste živice koje zaklanjaju odrasle tokom zime.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'bs', 'Narandžasti vrh', 'Samo mužjaci imaju jarko narandžaste vrhove krila; ženke su bijele.', 'U proljeće uz vlažne livade i putove gdje raste livadna režuha.', 'Pustite da livadno cvijeće raste u vlažnim, nepokošenim kutovima.', 'Odgodite košnju bankina dok gusjenice ne završe hranjenje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'bs', 'Obični plavac', 'Gusjenice ponekad njeguju mravi zbog njihovih slatkih izlučevina.', 'Od kasnog proljeća na sunčanim travnjacima bogatim djetelinom.', 'Ostavite travnjak nepokošen da djeteline mogu cvjetati.', 'Ne prskajte herbicidom travnjake bogate divljim cvijećem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'bs', 'Zelenožilni bijelac', 'Iako liči na kupusara, više voli divlje biljke nego vrtne usjeve.', 'Od proljeća do kasnog ljeta na vlažnim livadama, u jarcima i šumskim prosjekama.', 'Pustite da vlažni kutovi podivljaju s domaćim krstašicama.', 'Ne isušujte i ne prskajte vlažne livade na kojima se razmnožava.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'bs', 'Bubamara sa sedam tačaka', 'Jedna bubamara tokom života može pojesti hiljade lisnih uši.', 'Od proljeća do jeseni na biljkama s lisnim ušima; zimi se skupljaju na prezimljavanje.', 'Podnesite nešto lisnih uši i preskočite prskanje da bubamare imaju hranu.', 'Ostavite šuplje stabljike i otpalo lišće u kojima zimi nalaze zaklon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'bs', 'Bumbar žutorepi', 'Matice su među prvim pčelama u proljeće i nisko zuje tražeći rupe za gnijezdo.', 'Od ranog proljeća do jeseni na cvijeću; matice u proljeće pretražuju podnožja živica.', 'Uzgajajte ili ostavite rano cvjetajuće biljke i pustite djetelinu da cvjeta u travnjaku.', 'Ostavite netaknute obronke i stare mišje rupe u kojima se kolonije gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'bs', 'Medonosna pčela', 'Sakupljačice plesom u obliku osmice govore košnici gdje je cvijeće.', 'Od proljeća do jeseni na cvijeću za toplih, mirnih dana.', 'Pustite da raznoliko cvijeće cvjeta kroz sezone i ostavite plitku posudu s vodom.', 'Ne prskajte biljke u cvatu i nikada ne prskajte sredinom dana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'bs', 'Carski vilin konjic', 'Jedan je od najvećih evropskih vilinih konjica i plijen može uhvatiti čak u zraku.', 'Toplih ljetnih dana gledajte ga kako patrolira ribnjacima i rubovima jezera.', 'Održavajte ili iskopajte ribnjak s biljkama i ostavite rubove zaraslima.', 'Čuvajte ribnjake od zagađenja i otjecanja da se ličinke mogu razviti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'bs', 'Obični strijelac', 'Često sjeda na isto toplo mjesto i izlijeće da uhvati insekte koji prolaze.', 'Od sredine ljeta do jeseni uz mirnu vodu, sunča se na stazama i stupovima.', 'Ostavite sunčana mjesta za sjedenje i vegetaciju oko ribnjaka i jaraka.', 'Ne dopustite da gnojivo ili ulje dospiju u ribnjake u kojima žive ličinke.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'bs', 'Crveni šumski mrav', 'Njihovi humci mogu biti viši od metra i sadržavati pola miliona mrava.', 'Od proljeća do jeseni u četinarskim šumama; tražite kupolaste humke od iglica.', 'Ostavite mravinjake netaknutima — grade ih godinama.', 'Držite se staza i nikada ne udarajte i ne kopajte po mravinjaku.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'bs', 'Šumska šumarica', 'Šire se tako sporo da gusti tepisi označavaju staru šumu.', 'U proljeće tražite tepihe bijelog cvijeća prije nego stabla prolistaju.', 'Ostavite šumsko tlo netaknuto da sporo rastuće korijenje uspijeva.', 'Uživajte u njima ondje gdje rastu — branje uklanja cvijet kojem je trebalo godina.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'bs', 'Đurđevak', 'Svaki dio ove mirisne biljke otrovan je ako se pojede.', 'U kasno proljeće slijedite miris do sjenovitih šuma i zasjenjenih vrtova.', 'Ostavite sjenovite rubove šume i otpalo lišće gdje raste.', 'Ne berite ga i ne iskopavajte; držite ga podalje od djece i kućnih ljubimaca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'bs', 'Medvjeđi luk', 'Medvjeđi luk često namirišete prije nego ugledate bijele cvjetove.', 'U proljeće tražite široke zelene listove i zvjezdaste cvjetove u vlažnim šumama.', 'Ostavite vlažnu šumu netaknutom da tepisi svake godine ponovo izrastu.', 'Ako je branje lokalno dopušteno, uzmite malo i nikada ne čupajte lukovice.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'bs', 'Barski kaljužnjak', 'Jedna od najstarijih domaćih biljaka; preživjela je posljednje ledeno doba u Skandinaviji.', 'U proljeće tražite velike zlatne cvjetove u močvarama, jarcima i uz ribnjake.', 'Održavajte rubove ribnjaka i jaraka vlažnima i nepokošenima da može cvjetati.', 'Ne isušujte vlažno tlo i ostavite biljke ondje gdje rastu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'bs', 'Jagorčevina', 'Jagorčevine su nekad bile toliko česte na livadama da su djeca od njih pravila lopte.', 'U proljeće tražite klimave žute cvjetove na starim, neobrađenim livadama.', 'Ne kosite livade dok jagorčevine ne odcvjetaju i ne razviju sjeme.', 'Ne berite ih i ne iskopavajte iz prirode — livadno cvijeće je u opadanju.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'bs', 'Velika ivančica', 'Ono što izgleda kao jedan cvijet zapravo je na desetke sićušnih cvjetova zajedno.', 'Ljeti tražite velike bijele ivančice uz puteve i na livadama.', 'Ostavite traku trave nepokošenom kroz sredinu ljeta da može cvjetati.', 'Ne prskajte bankine i livade herbicidom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'bs', 'Maslačak', 'Maslačak je jedan od najvažnijih ranih izvora nektara za pčele.', 'Od proljeća nadalje gotovo svugdje; cvjetovi se otvaraju na suncu i zatvaraju u sumrak.', 'Pustite maslačke da cvjetaju u travnjaku u proljeće prije prve košnje.', 'Preskočite herbicide za travnjak da rani oprašivači zadrže ovu ključnu hranu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'bs', 'Vrijes', 'Jedna biljka vrijeska može proizvesti više od sto hiljada sićušnih sjemenki.', 'U kasno ljeto tražite ljubičaste tepihe na otvorenim vrištinama i tresetištima.', 'Podržite održavanje vriština otvorenima i bez isušivanja.', 'Držite se staza na vrištinama i nikada ne palite vatru po suhom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'bs', 'Borovnica', 'Borovnice oboje prste u plavo i hrane sve, od ptica do medvjeda.', 'Ljeti tražite niske grmove s tamnim bobicama u borovoj i smrčevoj šumi.', 'Ostavite šumsko podrast netaknutim da niski grmovi mogu roditi.', 'Ako je branje lokalno dopušteno, ostavite dovoljno bobica divljim životinjama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'bs', 'Brusnica', 'Brusnice se drže mjesecima zahvaljujući prirodnom konzervansu u plodu.', 'U kasno ljeto i jesen tražite sjajne crvene bobice na zimzelenim tepisima.', 'Ostavite vegetaciju šumskog tla netaknutom da se tepisi mogu širiti.', 'Ako je branje dopušteno, gazite pažljivo da ne zgnječite biljke.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'bs', 'Bijela breza', 'Breza hrani stotine vrsta insekata, koji pak hrane bezbroj ptica.', 'Cijele godine; bijela kora koja se ljušti čini je lako prepoznatljivom u svakom dobu.', 'Ostavite otpalo brezovo lišće i mrtvo drvo da obogate tlo i hrane insekte.', 'Izbjegavajte guljenje kore, koje može raniti i oslabiti stablo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'bs', 'Smrča', 'Jedna smrča u Švedskoj raste iz korijena starog nekoliko hiljada godina.', 'Cijele godine u šumama; njezini viseći češeri najduži su među smrčama.', 'Ostavite otpale češere i mrtvo drvo koji daju zaklon insektima i gljivama.', 'Držite se staza u šumi da se plitko korijenje smrče ne zbija.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'bs', 'Bijeli bor', 'Stari borovi pri vrhu svijetle narandžasto i mogu živjeti stoljećima.', 'Cijele godine na pjeskovitom i kamenitom tlu; tražite narandžastu koru pri vrhu.', 'Ostavite stojeće mrtvo drvo i stare borove, bogate divljim svijetom.', 'Nikada ne palite vatru uz borove na suhom, pjeskovitom tlu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'bs', 'Štuka', 'Štuka je grabežljivac iz zasjede koji iz mirovanja napada u trenu.', 'Od proljeća do jeseni u zaraslim plićacima jezera i sporih rijeka.', 'Podržite očuvanje trščanih plićaka i vodenog bilja u kojima se skriva mlađ.', 'Držite zagađenje i smeće podalje od vode; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'bs', 'Grgeč', 'Grgeči love u jatima, a izrazite pruge razbijaju obrise njihova tijela.', 'U toplijim mjesecima oko gatova, busena vodenog bilja i podvodnih rubova.', 'Podržite čistu vodu i podvodne strukture koje pružaju zaklon sitnoj ribi.', 'Nikada ništa ne bacajte u jezera i rijeke; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'bs', 'Bodorka', 'Bodorka je ključna riba hraniteljica o kojoj ovise mnogi jezerski grabežljivci.', 'U toplijim mjesecima u jatima blizu površine jezera i sporih rijeka.', 'Podržite čistu vodu i obrasle rubove potrebne za mrijest.', 'Držite otjecanje i smeće podalje od vode; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'sr', 'Обична чиопа', 'Чиопе могу месецима остати у зраку, чак и спавају у лету.', 'Топлих летних вечери гледајте високо изнад кровова и слушајте вриштећа јата.', 'Поставите кућицу за гнежђење под стреху пре него се птице врате у пролеће.', 'При реновирању сачувајте мале отворе под стрехом у којима се гнезде.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'sr', 'Ластавица покућарка', 'Ластавице сваке године селе све до југа Африке и натраг.', 'Од пролећа до ране јесени тражите их како ниско клизе изнад поља и воде.', 'Оставите врата штале или шупе одшкринута да дођу до својих гнезда.', 'Не рушите стара блатна гнезда — ластавице их користе из године у годину.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'sr', 'Кукавица', 'Кукавица полаже јаја у гнезда других птица и никада не одгаја властите младе.', 'У касно пролеће слушајте далеки зов "ку-ку" с рубова шуме.', 'Подржите ливаде и живице богате инсектима које хране птице о којима кукавица овиси.', 'Држите се стаза уз шикару и тршчаке да птице домаћини не буду узнемирене.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'sr', 'Црвендаћ', 'Црвендаћи жестоко бране териториј и певају кроз ноћ близу уличних светиљки.', 'Целе године у вртовима и шумама; често прате онога ко копа, надајући се глистама.', 'Оставите кут врта с отпалим лишћем где могу тражити храну.', 'Одгодите јако орезивање живице док гнежђење не заврши у касно лето.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'sr', 'Кос', 'Богата, флаутаста песма мужјака једна је од најпрепознатљивијих у Европи.', 'Целе године; у зору и сумрак слушајте мужјаке како певају с кровова и крошњи.', 'Изнесите свежу воду за пиће и купање, нарочито у сушним раздобљима.', 'У сезони гнежђења држите мачке у кући у зору.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'sr', 'Дрозд бравењак', 'Друштвени је дрозд који зими лута бучним, брбљавим јатима.', 'У јесен и зиму гледајте јата како скидају бобице с живица и стабала.', 'Не орезујте грмље с бобицама током зиме.', 'Оставите отпале јабуке на тлу зими — у хладноћи су кључна храна.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'sr', 'Велика сеница', 'Имају велик гласовни репертоар и уче нове зовове од суседа.', 'Целе године; од касне зиме слушајте звонку, понављајућу песму.', 'Обесите кућицу с отвором од 32 мм на мирно, сеновито место.', 'Избегавајте вртне пестициде да остане довољно гусеница за храњење младих.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'sr', 'Плава сеница', 'Једно легло плавих сеница може појести више од хиљаду гусеница.', 'Целе године у вртовима и шумама, често висе наопако с танких гранчица.', 'Поставите малу кућицу с отвором од 25 мм даље од превладавајућег ветра.', 'У пролеће прескочите инсектициде да гусенице буду доступне младима.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'sr', 'Зеба', 'Песма зебе разликује се по крајевима, готово као локални дијалекти.', 'Од пролећа до јесени; мужјаци певају ведру, силазну фразу с отворених грана.', 'Оставите дио семенских главица и травнатих површина кроз сезону.', 'Држите хранилице чистима да се болест не шири међу зебама.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'sr', 'Шојка', 'Сваке јесени закопа хиљаде жирева и, заборављајући неке, посади целе храстове шуме.', 'Целе године у храстовим шумама; у јесен пазите на блескове ружичасте и плаве.', 'Оставите отпале жиреве и лишће под храстовима нетакнутима.', 'Држите псе на стазама у шуми да се птице које се хране на тлу не узнемире.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'sr', 'Велики детлић', 'Пролећно бубњање није тражење хране него брз ритам којим означава териториј.', 'Целе године; у касну зиму слушајте бубњање које одзвања шумом.', 'Оставите стојеће мртво дрво у којем живе инсекти којима се храни.', 'Не сеците мртва или сушна стабла која могу садржавати гнезда.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'sr', 'Бијела пастирица', 'Стално њихање репа можда сигнализира опрезност пред грабежљивцима.', 'Од пролећа до јесени уз воду и отворено тло; трчи и застаје да ухвати инсекте.', 'Уз воду одржавајте комад ниске траве или шљунка где може тражити храну.', 'Не узнемиравајте шљунковите обале где се храни и гнезди.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'sr', 'Ждрал', 'У рано пролеће изводе свадбене плесове са скоковима и наклонима.', 'Од пролећа до јесени око мочвара; слушајте трубљење које се чује километрима.', 'Подржите заштиту неисушених тресетишта и влажних ливада у којима се гнезде.', 'Гнездећа мочварна станишта проматрајте издалека — узнемирено гнездо напуштају.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'sr', 'Лабуд певач', 'Лабудови певачи се паре доживотно и долазак најављују гласним трубљењем.', 'У пролеће и јесен на језерима и поплављеним пољима, често у породичним групама.', 'Подржите очување плитких рубова језера и влажних поља без исушивања.', 'Никада не храните лабудове хлебом — шкоди им; на леду држите одстојање.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'sr', 'Дивља патка', 'Пачићи пливају и сами се хране већ неколико сати након излегања.', 'Целе године на готово сваком рибњаку, језеру или спорој реци.', 'Ако их храните, користите зоб, грашак или семенке уместо хлеба.', 'У пролеће држите псе подаље од воде у којој се патке гнезде.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'sr', 'Шкањац', 'Лебди на широким крилима и често се гласа мачкастим "пијааау".', 'Од пролећа до јесени; тражите га како кружи високо изнад поља и рубова шуме.', 'Подржите грубе травњаке и рубове поља у којима живе волухарице и ситан плен.', 'Никада не користите отрове за глодаре; ланцем исхране доспевају до птица грабљивица.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'sr', 'Орао рибар', 'Рони ногама напред да ухвати рибу и може понети плен упола своје тежине.', 'Од пролећа до јесени уз велика језера; прво лебди, потом следи драматичан урон.', 'Подржите постављање гнездећих платформи на високим ступовима уз језера богата рибом.', 'Заобиђите гнездеће платформе надалеко да парови не напусте јаја.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'sr', 'Црвена лисица', 'Лисице се служе Земљиним магнетским пољем при процени скока на скривени плен.', 'Целе године, најактивније у зору и сумрак уз рубове шуме и поља.', 'Оставите дивљи, мирни кут где се лисице могу одмарати и копати јазбину.', 'Осигурајте канте и никада не остављајте штетне остатке хране лисицама.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'sr', 'Европски јеж', 'Јеж у једној ноћи тражења хране може прећи неколико километара.', 'Од пролећа до јесени након мрака; зими спава под хрпама лишћа и трупаца.', 'Направите отвор од 13 цм у огради да јежеви могу прелазити између вртова.', 'Проверите високу траву пре кошње и оставите хрпе лишћа за зимски сан.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'sr', 'Срна', 'Срне одгађају трудноћу тако да се ланад увек рађа у рано лето.', 'Целе године на рубовима шуме, највидљивије при испаши у зору и сумрак.', 'Подржите непокошене рубове поља и шикару које дају заклон и храну.', 'У рано лето, кад ланад лежи скривена, држите псе на поводцу уз шуму.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'sr', 'Лос', 'Лос је највећи јелен на свету; крупан мужјак може тежити преко пола тоне.', 'Целе године у шумама и мочварама, најактивнији у зору и сумрак.', 'Подржите повезане шуме и мочварне коридоре којима се лос креће.', 'Возите опрезно у зору и сумрак шумским путевима и никада не прилазите младунчету.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'sr', 'Црвена веверица', 'Граде више гнезда и селе се између њих.', 'Целе године у четинарским и мешовитим шумама, најактивније рано ујутро.', 'Оставите чешере, орашасте плодове и стојећа стабла у којима се хране и гнезде.', 'Држите псе на стазама и не узнемиравајте стабла која могу садржавати гнездо.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'sr', 'Европски дабар', 'Даброве бране стварају мочваре које километрима подижу број риба, птица и инсеката.', 'Од пролећа до касне јесени уз споре реке, најактивнији у сумрак.', 'Подржите остављање брана и приобалног дрвећа где је то сигурно.', 'Држите се подаље од настамби и брана, нарочито док су младунци мали.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'sr', 'Планински зец', 'Зими побеле ради маскирања на снегу.', 'Целе године на отвореном тлу и шумским чистинама, углавном у зору и сумрак.', 'Подржите мешавину отвореног тла и заклона која им треба током године.', 'Држите псе на поводцу на отвореном да се зечеви у одмору не прогоне.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'sr', 'Јазавац', 'Живе у породичним скупинама у подземним јазбинама које се користе генерацијама.', 'Од пролећа до јесени након мрака близу шуме; зиму преспавају.', 'Оставите нетакнуте обронке и живице где јазавци могу копати јазбине.', 'Никада не затварајте активну јазбину нити копајте близу ње — то је њихов трајни дом.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'sr', 'Патуљасти шишмиш', 'Овај сићушни шишмиш може у једној ноћи појести до 3.000 мушица и комараца.', 'Летних вечери пратите брз, испрекидан лет у сумрак изнад вртова.', 'Поставите кућицу за шишмише високо на зид или стабло које хвата вечерње сунце.', 'Избегавајте јака светла на улазима склоништа и одржавајте ноћно небо тамним.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'sr', 'Мали костријет лептир', 'Овај лептир презимљава као одрастао, често у шупама и поткровљима.', 'Од раног пролећа до јесени на сунчаним цветовима, нарочито на коприви.', 'Оставите комад коприва у сунчаном куту — гусеницама су нужне.', 'Не узнемиравајте лептире који презимљавају у шупама.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'sr', 'Пауново око', 'Очасте мрље блесну да преплаше птице, а крила при отварању могу засиктати.', 'Од пролећа до јесени по сунцу, храни се чкаљем и отпалим воћем.', 'Пустите да сунчани бусен коприва расте за његове гусенице.', 'Не дирајте одрасле који зими бораве у шупама и хрпама дрва.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'sr', 'Лимунов лептир', 'Енглеска реч за лептира можда потиче од маслачастожуте боје мужјака ове врсте.', 'Један од првих пролећних лептира; топлих дана тражите га уз рубове шуме.', 'Подржите грмове кркавине у живицама, једине биљке које гусенице једу.', 'Не крчите шикарасте живице које заклањају одрасле током зиме.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'sr', 'Наранџасти врх', 'Само мужјаци имају јарко наранџасте врхове крила; женке су беле.', 'У пролеће уз влажне ливаде и путове где расте ливадна режуха.', 'Пустите да ливадно цвеће расте у влажним, непокошеним кутовима.', 'Одгодите кошњу банкина док гусенице не заврше храњење.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'sr', 'Обични плавац', 'Гусенице понекад његују мрави због њихових слатких излучевина.', 'Од касног пролећа на сунчаним травњацима богатим детелином.', 'Оставите травњак непокошен да детелине могу цветати.', 'Не прскајте хербицидом травњаке богате дивљим цвећем.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'sr', 'Зеленожилни бијелац', 'Иако личи на купусара, више воли дивље биљке него вртне усеве.', 'Од пролећа до касног лета на влажним ливадама, у јарцима и шумским просекама.', 'Пустите да влажни кутови подивљају с домаћим крсташицама.', 'Не исушујте и не прскајте влажне ливаде на којима се размножава.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'sr', 'Бубамара са седам тачака', 'Једна бубамара током живота може појести хиљаде лисних уши.', 'Од пролећа до јесени на биљкама с лисним ушима; зими се скупљају на презимљавање.', 'Поднесите нешто лисних уши и прескочите прскање да бубамаре имају храну.', 'Оставите шупље стабљике и отпало лишће у којима зими налазе заклон.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'sr', 'Бумбар жуторепи', 'Матице су међу првим пчелама у пролеће и ниско зује тражећи рупе за гнездо.', 'Од раног пролећа до јесени на цвећу; матице у пролеће претражују подножја живица.', 'Узгајајте или оставите рано цветајуће биљке и пустите детелину да цвета у травњаку.', 'Оставите нетакнуте обронке и старе мишје рупе у којима се колоније гнезде.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'sr', 'Медоносна пчела', 'Сакупљачице плесом у облику осмице говоре кошници где је цвеће.', 'Од пролећа до јесени на цвећу за топлих, мирних дана.', 'Пустите да разнолико цвеће цвета кроз сезоне и оставите плитку посуду с водом.', 'Не прскајте биљке у цвату и никада не прскајте средином дана.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'sr', 'Царски вилин коњиц', 'Један је од највећих европских вилиних коњица и плен може ухватити чак у зраку.', 'Топлих летних дана гледајте га како патролира рибњацима и рубовима језера.', 'Одржавајте или ископајте рибњак с биљкама и оставите рубове зараслима.', 'Чувајте рибњаке од загађења и отицања да се личинке могу развити.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'sr', 'Обични стријелац', 'Често седа на исто топло место и излеће да ухвати инсекте који пролазе.', 'Од средине лета до јесени уз мирну воду, сунча се на стазама и ступовима.', 'Оставите сунчана места за седење и вегетацију око рибњака и јарака.', 'Не допустите да гнојиво или уље доспију у рибњаке у којима живе личинке.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'sr', 'Црвени шумски мрав', 'Њихови хумци могу бити виши од метра и садржавати пола милиона мрава.', 'Од пролећа до јесени у четинарским шумама; тражите куполасте хумке од иглица.', 'Оставите мравињаке нетакнутима — граде их годинама.', 'Држите се стаза и никада не ударајте и не копајте по мравињаку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'sr', 'Шумска шумарица', 'Шире се тако споро да густи теписи означавају стару шуму.', 'У пролеће тражите тепихе белог цвећа пре него стабла пролистају.', 'Оставите шумско тло нетакнуто да споро растуће корење успева.', 'Уживајте у њима онде где расту — брање уклања цвет којем је требало година.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'sr', 'Ђурђевак', 'Сваки дио ове мирисне биљке отрован је ако се поједе.', 'У касно пролеће следите мирис до сеновитих шума и засењених вртова.', 'Оставите сеновите рубове шуме и отпало лишће где расте.', 'Не берите га и не ископавајте; држите га подаље од деце и кућних љубимаца.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'sr', 'Медвеђи лук', 'Медвеђи лук често намиришете пре него угледате беле цветове.', 'У пролеће тражите широке зелене листове и звездасте цветове у влажним шумама.', 'Оставите влажну шуму нетакнутом да теписи сваке године поново израсту.', 'Ако је брање локално допуштено, узмите мало и никада не чупајте луковице.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'sr', 'Барски каљужњак', 'Једна од најстаријих домаћих биљака; преживела је последње ледено доба у Скандинавији.', 'У пролеће тражите велике златне цветове у мочварама, јарцима и уз рибњаке.', 'Одржавајте рубове рибњака и јарака влажнима и непокошенима да може цветати.', 'Не исушујте влажно тло и оставите биљке онде где расту.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'sr', 'Јагорчевина', 'Јагорчевине су некад биле толико честе на ливадама да су деца од њих правила лопте.', 'У пролеће тражите климаве жуте цветове на старим, необрађеним ливадама.', 'Не косите ливаде док јагорчевине не одцветају и не развију семе.', 'Не берите их и не ископавајте из природе — ливадно цвеће је у опадању.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'sr', 'Велика иванчица', 'Оно што изгледа као један цвет заправо је на десетке сићушних цветова заједно.', 'Лети тражите велике беле иванчице уз путеве и на ливадама.', 'Оставите траку траве непокошеном кроз средину лета да може цветати.', 'Не прскајте банкине и ливаде хербицидом.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'sr', 'Маслачак', 'Маслачак је један од најважнијих раних извора нектара за пчеле.', 'Од пролећа надаље готово свугде; цветови се отварају на сунцу и затварају у сумрак.', 'Пустите маслачке да цветају у травњаку у пролеће пре прве кошње.', 'Прескочите хербициде за травњак да рани опрашивачи задрже ову кључну храну.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'sr', 'Вријес', 'Једна биљка вреска може произвести више од сто хиљада сићушних семенки.', 'У касно лето тражите љубичасте тепихе на отвореним вриштинама и тресетиштима.', 'Подржите одржавање вриштина отворенима и без исушивања.', 'Држите се стаза на вриштинама и никада не палите ватру по сухом.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'sr', 'Боровница', 'Боровнице обоје прсте у плаво и хране све, од птица до медведа.', 'Лети тражите ниске грмове с тамним бобицама у боровој и смрчевој шуми.', 'Оставите шумско подраст нетакнутим да ниски грмови могу родити.', 'Ако је брање локално допуштено, оставите довољно бобица дивљим животињама.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'sr', 'Брусница', 'Бруснице се држе месецима захваљујући природном конзервансу у плоду.', 'У касно лето и јесен тражите сјајне црвене бобице на зимзеленим теписима.', 'Оставите вегетацију шумског тла нетакнутом да се теписи могу ширити.', 'Ако је брање допуштено, газите пажљиво да не згњечите биљке.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'sr', 'Бијела бреза', 'Бреза храни стотине врста инсеката, који пак хране безброј птица.', 'Целе године; бела кора која се љушти чини је лако препознатљивом у сваком добу.', 'Оставите отпало брезово лишће и мртво дрво да обогате тло и хране инсекте.', 'Избегавајте гуљење коре, које може ранити и ослабити стабло.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'sr', 'Смрча', 'Једна смрча у Шведској расте из корена старог неколико хиљада година.', 'Целе године у шумама; њезини висећи чешери најдужи су међу смрчама.', 'Оставите отпале чешере и мртво дрво који дају заклон инсектима и гљивама.', 'Држите се стаза у шуми да се плитко корење смрче не збија.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'sr', 'Бијели бор', 'Стари борови при врху светле наранџасто и могу живети столећима.', 'Целе године на песковитом и каменитом тлу; тражите наранџасту кору при врху.', 'Оставите стојеће мртво дрво и старе борове, богате дивљим светом.', 'Никада не палите ватру уз борове на сухом, песковитом тлу.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'sr', 'Штука', 'Штука је грабежљивац из заседе који из мировања напада у трену.', 'Од пролећа до јесени у зараслим плићацима језера и спорих река.', 'Подржите очување тршчаних плићака и воденог биља у којима се скрива млађ.', 'Држите загађење и смеће подаље од воде; поштујте локална риболовна правила.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'sr', 'Гргеч', 'Гргечи лове у јатима, а изразите пруге разбијају обрисе њихова тела.', 'У топлијим месецима око гатова, бусена воденог биља и подводних рубова.', 'Подржите чисту воду и подводне структуре које пружају заклон ситној риби.', 'Никада ништа не бацајте у језера и реке; поштујте локална риболовна правила.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'sr', 'Бодорка', 'Бодорка је кључна риба хранитељица о којој овисе многи језерски грабежљивци.', 'У топлијим месецима у јатима близу површине језера и спорих река.', 'Подржите чисту воду и обрасле рубове потребне за мрест.', 'Држите отицање и смеће подаље од воде; поштујте локална риболовна правила.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'sq', 'Dejka e zakonshme', 'Dejkat mund të qëndrojnë me muaj në ajër, madje flenë duke fluturuar.', 'Në mbrëmjet e ngrohta të verës, shihni lart mbi çati dhe dëgjoni tufat që klithin.', 'Vendosni një folezë nën strehë para se zogjtë të kthehen në pranverë.', 'Kur rinovoni, ruani të çarat e vogla nën strehë ku bëjnë fole.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'sq', 'Dallëndyshja e shtëpisë', 'Dallëndyshet migrojnë çdo vit deri në jug të Afrikës dhe kthehen.', 'Nga pranvera deri në fillim të vjeshtës, shihini duke fluturuar ulët mbi ara dhe ujëra.', 'Lëreni derën e stallës ose depos gjysmë të hapur që të arrijnë foletë.', 'Mos i prishni foletë e vjetra prej balte — dallëndyshet i ripërdorin vit pas viti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'sq', 'Qyqja', 'Qyqja i lëshon vezët në foletë e zogjve të tjerë dhe kurrë nuk i rrit vetë të vegjlit.', 'Në fund të pranverës, dëgjoni thirrjen e largët "ku-ku" nga buzët e pyllit.', 'Mbështetni livadhet dhe gardhet e gjalla plot insekte që ushqejnë zogjtë pritës.', 'Qëndroni në shtigje pranë shkurreve dhe kallamishteve që zogjtë pritës të mos shqetësohen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'sq', 'Gushëkuqi', 'Gushëkuqët e mbrojnë territorin ashpër dhe këndojnë natën pranë dritave të rrugës.', 'Gjithë vitin në kopshte dhe pyje; shpesh ndjekin atë që gërmon tokën, duke shpresuar për krimba.', 'Lini një qoshe të kopshtit me gjethe të rëna ku të kërkojnë ushqim.', 'Shtyjeni krasitjen e rëndë të gardhit derisa të mbarojë folezimi në fund të verës.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'sq', 'Mëllenja e zezë', 'Kënga e pasur, si fyell, e mashkullit është nga më të njohurat në Evropë.', 'Gjithë vitin; në agim dhe muzg dëgjoni meshkujt që këndojnë nga çatitë dhe majat e pemëve.', 'Vendosni ujë të freskët për të pirë e për t’u larë, sidomos në periudha thatësire.', 'Në sezonin e folezimit mbajini macet brenda në agim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'sq', 'Mëllenja e arave', 'Është mëllenjë shoqërore që dimrit endet në tufa të zhurmshme.', 'Në vjeshtë dhe dimër, shihni tufat që heqin kokrrat nga gardhet dhe pemët.', 'Mos i krasitni shkurret me kokrra gjatë dimrit.', 'Lini mollët e rëna përtokë në dimër — janë ushqim jetik në të ftohtë.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'sq', 'Trishtili i madh', 'Kanë fjalor të gjerë zërash dhe mësojnë thirrje të reja nga fqinjët.', 'Gjithë vitin; nga fundi i dimrit dëgjoni këngën kumbuese e të përsëritur.', 'Varni një folezë me vrimë 32 mm në një vend të qetë e me hije.', 'Shmangni pesticidet e kopshtit që të mbeten vemje të mjaftueshme për zogjtë.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'sq', 'Trishtili blu', 'Një çerdhe e vetme trishtilash blu mund të hajë mbi një mijë vemje.', 'Gjithë vitin në kopshte dhe pyje, shpesh varen përmbys nga degëzat e holla.', 'Vendosni një folezë të vogël me vrimë 25 mm larg erës mbizotëruese.', 'Në pranverë hiqni dorë nga insekticidet që vemjet të jenë të disponueshme për zogjtë.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'sq', 'Borëbardhi i pyllit', 'Kënga ndryshon sipas krahinës, thuajse si dialekte vendore.', 'Nga pranvera në vjeshtë; meshkujt këndojnë një frazë të ndritur zbritëse nga vende të hapura.', 'Lini disa kokrra farash dhe njolla barishtesh në këmbë gjatë sezonit.', 'Mbajini ushqyeset të pastra që sëmundja të mos përhapet mes tyre.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'sq', 'Laraska e lisit', 'Çdo vjeshtë varros mijëra lende dhe, duke harruar disa, mbjell pyje të tërë lisi.', 'Gjithë vitin në pyje lisi; në vjeshtë vini re shkëlqimet rozë dhe blu.', 'Lini të paprekura lendet e rëna dhe gjethet nën lisa.', 'Mbajini qentë në shteg në pyll që zogjtë që ushqehen përtokë të mos trembën.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'sq', 'Qukapiku i madh me pika', 'Trokitja e pranverës nuk është për ushqim, por një ritëm i shpejtë që shpall territorin.', 'Gjithë vitin; në fund të dimrit dëgjoni trokitjen që jehon nëpër pyll.', 'Lini drurin e vdekur në këmbë, ku jetojnë insektet me të cilat ushqehet.', 'Mos i prisni pemët e vdekura ose në tharje, mund të kenë vrima foleje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'sq', 'Bishtundara e bardhë', 'Tundja e vazhdueshme e bishtit mund të sinjalizojë vigjilencë ndaj grabitqarëve.', 'Nga pranvera në vjeshtë pranë ujit dhe tokës së hapur; vrapon e ndalon për të kapur insekte.', 'Mbani pranë ujit një copë bar të shkurtër ose zhavorr ku të kërkojë ushqim.', 'Mos shqetësoni brigjet me zhavorr ku ushqehet dhe bën fole.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'sq', 'Krilla gri', 'Në fillim të pranverës bëjnë valle dasme me kërcime dhe përkulje.', 'Nga pranvera në vjeshtë rreth ligatinave; dëgjoni thirrjen që dëgjohet kilometra larg.', 'Mbështetni mbrojtjen e moçaleve dhe livadheve të lagështa të pakulluara ku riprodhohen.', 'Vëzhgoni ligatinat e folezimit nga larg — folenë e shqetësuar e braktisin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'sq', 'Mjellma këngëtare', 'Çiftëzohen për gjithë jetën dhe ardhjen e shpallin me thirrje të forta si buri.', 'Në pranverë e vjeshtë në liqene dhe ara të përmbytura, shpesh në grupe familjare.', 'Mbështetni ruajtjen e brigjeve të cekëta dhe arave të lagështa pa kullim.', 'Kurrë mos u jepni bukë — u bën dëm; mbani distancë edhe mbi akull.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'sq', 'Rosa e egër kokëgjelbër', 'Zogjtë notojnë dhe ushqehen vetë brenda pak orësh nga çelja.', 'Gjithë vitin në pothuajse çdo pellg, liqen ose lumë të ngadaltë.', 'Nëse i ushqeni, përdorni tërshërë, bizele ose fara në vend të bukës.', 'Në pranverë mbajini qentë larg ujit ku rosat bëjnë fole.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'sq', 'Huta e zakonshme', 'Fluturon me krahë të gjerë dhe thërret me një zë si mjaullimë maceje.', 'Nga pranvera në vjeshtë; kërkojeni duke u rrotulluar lart mbi ara dhe buzë pyjesh.', 'Mbështetni livadhet e ashpra dhe buzët e arave ku jetojnë minjtë e fushës.', 'Kurrë mos përdorni helm minjsh; përmes zinxhirit ushqimor arrin te shpendët grabitqarë.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'sq', 'Shqiponja peshkatare', 'Zhytet me këmbët përpara për të kapur peshk dhe mban gjah sa gjysma e peshës së vet.', 'Nga pranvera në vjeshtë pranë liqeneve të mëdhenj; rri pezull e pastaj zhytet.', 'Mbështetni platforma foleje mbi shtylla të larta pranë liqeneve të pasur me peshk.', 'Qëndroni shumë larg platformave të foleve që çiftet të mos i braktisin vezët.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'sq', 'Dhelpra e kuqe', 'Dhelprat përdorin fushën magnetike të Tokës për të matur kërcimin mbi gjahun e fshehur.', 'Gjithë vitin, më aktive në agim e muzg përgjatë buzëve të pyllit dhe arave.', 'Lini një qoshe të egër e të qetë ku të pushojnë dhe të gërmojnë strofull.', 'Mbyllni koshat dhe kurrë mos u lini mbetje ushqimore të dëmshme.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'sq', 'Iriqi evropian', 'Iriqi mund të përshkojë disa kilometra në një natë të vetme duke kërkuar ushqim.', 'Nga pranvera në vjeshtë pas errësirës; dimrit fle nën grumbuj gjethesh e trungjesh.', 'Hapni një vrimë 13 cm në gardh që iriqët të lëvizin mes kopshteve.', 'Kontrolloni barin e gjatë para se ta prisni dhe lini grumbuj gjethesh për dimërimin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'sq', 'Kaprolli', 'E vonojnë shtatzëninë që të vegjlit të lindin gjithmonë në fillim të verës.', 'Gjithë vitin në buzë pyjesh, më të dukshëm duke kullotur në agim dhe muzg.', 'Mbështetni buzët e pakositura të arave dhe shkurret që japin strehë e ushqim.', 'Në fillim të verës, kur të vegjlit rrinë të fshehur, mbajini qentë me zinxhir pranë pyllit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'sq', 'Dreri i madh (mus)', 'Është dreri më i madh në botë; një mashkull i rritur kalon gjysmë toni.', 'Gjithë vitin në pyje dhe ligatina, më aktiv në agim dhe muzg.', 'Mbështetni pyjet e lidhura dhe korridoret e ligatinave që i duhen për të lëvizur.', 'Ngisni me kujdes në agim e muzg nëpër rrugë pyjore dhe kurrë mos iu afroni një të voglit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'sq', 'Ketri i kuq', 'Ndërtojnë disa fole dhe lëvizin mes tyre.', 'Gjithë vitin në pyje halorë e të përzier, më aktivë herët në mëngjes.', 'Lini kukurecat, arrat dhe pemët në këmbë ku ushqehen e bëjnë fole.', 'Mbajini qentë në shteg dhe mos i shqetësoni pemët që mund të kenë fole.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'sq', 'Kastori evropian', 'Digat e kastorit krijojnë ligatina që rrisin peshqit, zogjtë dhe insektet me kilometra.', 'Nga pranvera deri në vjeshtë të vonë pranë lumenjve të ngadaltë, më aktivë në muzg.', 'Mbështetni lënien e digave dhe pemëve buzë ujit aty ku është e sigurt.', 'Qëndroni larg strehëve dhe digave, sidomos kur të vegjlit janë të vegjël.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'sq', 'Lepuri i malit', 'Dimrit zbardhen për t’u kamufluar mbi dëborë.', 'Gjithë vitin në tokë të hapur dhe lëndina pyjore, kryesisht në agim dhe muzg.', 'Mbështetni përzierjen e tokës së hapur dhe strehës që u duhet gjatë vitit.', 'Mbajini qentë me zinxhir në tokë të hapur që lepujt në pushim të mos ndiqen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'sq', 'Baldosa', 'Jetojnë në grupe familjare në strofuj nëntokësorë të përdorur brez pas brezi.', 'Nga pranvera në vjeshtë pas errësirës pranë pyllit; dimrin e flenë.', 'Lini të paprekura brinjat dhe gardhet ku baldosat gërmojnë strofuj.', 'Kurrë mos e mbyllni një strofull aktive dhe mos gërmoni pranë saj — është shtëpia e tyre.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'sq', 'Lakuriqi i vogël i natës', 'Ky lakuriq i vockël mund të hajë deri në 3.000 mushkonja në një natë.', 'Në mbrëmjet e verës, vëzhgoni fluturimin e shpejtë e të thyer në muzg mbi kopshte.', 'Vendosni një folezë lakuriqësh lart në mur ose pemë që kap diellin e mbrëmjes.', 'Shmangni dritat e forta te hyrjet e strehëve dhe mbajeni qiellin e natës të errët.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'sq', 'Flutura breshkore e vogël', 'Kjo flutur dimëron si e rritur, shpesh në depo dhe papafingo.', 'Nga fillimi i pranverës në vjeshtë mbi lule me diell, sidomos hithra.', 'Lini një copë hithrash në një qoshe me diell — vemjeve u duhen.', 'Mos i shqetësoni fluturat që dimërojnë në depo gjatë dimrit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'sq', 'Flutura palloi', 'Njollat si sy ndriçojnë për të trembur zogjtë, dhe krahët mund të fërshëllejnë kur hapen.', 'Nga pranvera në vjeshtë në ditë me diell, ushqehet me gjemba dhe fruta të rëna.', 'Lëreni një copë hithrash me diell të rritet për vemjet e saj.', 'Mos i shqetësoni të rriturat që strehohen dimrit në depo dhe grumbuj drush.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'sq', 'Flutura squfurore', 'Fjala angleze për fluturën mund të vijë nga ngjyra e verdhë si gjalpë e mashkullit të kësaj specieje.', 'Një nga fluturat e para të pranverës; në ditë të ngrohta kërkojeni buzë pyjeve.', 'Mbështetni shkurret e gjembit të kuq në gardhe, bimët e vetme që hanë vemjet.', 'Mos i pastroni gardhet me shkurre që strehojnë të rriturat gjatë dimrit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'sq', 'Flutura majëportokalli', 'Vetëm meshkujt kanë majat e krahëve portokalli të ndezur; femrat janë të bardha.', 'Në pranverë përgjatë livadheve të lagështa dhe rrugicave ku rriten lulet e egra.', 'Lëreni lulet e egra të rriten në qoshe të lagështa e të pakositura.', 'Shtyjeni prerjen e buzëve të rrugëve derisa vemjet të mbarojnë ushqimin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'sq', 'Flutura blu e zakonshme', 'Vemjet e saj ndonjëherë ruhen nga milingonat për sekrecionet e tyre të ëmbla.', 'Nga fundi i pranverës në livadhe me diell të pasura me tërfil.', 'Lëreni livadhin pa kositur që tërfilat të lulëzojnë.', 'Mos spërkatni me herbicid livadhet e pasura me lule të egra.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'sq', 'Flutura e bardhë me damarë të gjelbër', 'Edhe pse ngjan me fluturën e lakrës, preferon bimët e egra, jo kulturat e kopshtit.', 'Nga pranvera në fund të verës në livadhe të lagështa, kanale dhe shtigje pyjore.', 'Lini qoshet e lagështa të egërsohen me bimë vendase.', 'Mos i thani dhe mos i spërkatni livadhet e lagështa ku riprodhohet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'sq', 'Mollëkuqja me shtatë pika', 'Një mollëkuqe mund të hajë mijëra afide gjatë jetës së saj.', 'Nga pranvera në vjeshtë mbi bimë me afide; dimrit grumbullohen për të dimëruar.', 'Duroni ca afide dhe mos spërkatni që mollëkuqet të kenë ushqim.', 'Lini kërcellet e zbrazëta dhe gjethet e rëna ku strehohen gjatë dimrit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'sq', 'Grerëza bishtverdhë', 'Mbretëreshat janë nga bletët e para të pranverës, gumëzhijnë ulët duke kërkuar vrima foleje.', 'Nga fillimi i pranverës në vjeshtë mbi lule; mbretëreshat kërkojnë nën gardhe.', 'Rritni ose lini bimë që lulëzojnë herët dhe lëreni tërfilin të lulëzojë në lëndinë.', 'Lini të paprekura brinjat dhe vrimat e vjetra të minjve ku foleziojnë koloni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'sq', 'Bleta e mjaltit', 'Bletët mbledhëse i tregojnë koshereve ku janë lulet duke vallëzuar në formë tetëshe.', 'Nga pranvera në vjeshtë mbi lule në ditë të ngrohta e pa erë.', 'Lini lule të ndryshme të çelin nëpër stinë dhe vendosni një enë të cekët me ujë.', 'Mos spërkatni bimët në lulëzim dhe kurrë mos spërkatni në mesditë.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'sq', 'Pilivesa perandorake', 'Një nga pilivesat më të mëdha të Evropës, mund ta kapë gjahun edhe në fluturim.', 'Në ditë të ngrohta vere, shihni si patrullon pellgjet dhe buzët e liqeneve.', 'Mbani ose hapni një pellg me bimë dhe lini buzët të mbuluara me bimësi.', 'Mbajini pellgjet pa ndotje që larvat të zhvillohen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'sq', 'Pilivesa e vogël e zakonshme', 'Shpesh ulet në të njëjtin vend të ngrohtë dhe kërcen për të kapur insektet që kalojnë.', 'Nga mesi i verës në vjeshtë pranë ujit të qetë, ngrohet në shtigje dhe shtylla.', 'Lini vende me diell për t’u ulur dhe bimësi rreth pellgjeve e kanaleve.', 'Mos lejoni që plehu ose vaji të rrjedhë në pellgjet ku jetojnë larvat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'sq', 'Milingona e kuqe e pyllit', 'Kodrat e foleve mund të kalojnë një metër lartësi dhe të strehojnë gjysmë milioni milingona.', 'Nga pranvera në vjeshtë në pyje halorë; kërkoni kodra të rrumbullakëta gjilpërash.', 'Lini kodrat e foleve të paprekura — ndërtimi u merr vite.', 'Qëndroni në shteg dhe kurrë mos e godisni e mos gërmoni një kodër milingonash.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'sq', 'Lulja e pyllit e bardhë', 'Përhapet aq ngadalë sa tapetet e dendura tregojnë pyll të lashtë.', 'Në pranverë kërkoni tapete lulesh të bardha para se pemët të nxjerrin gjethe.', 'Lini dyshemenë e pyllit të paprekur që rrënjët ngadalë-përhapëse të lulëzojnë.', 'Shijojini aty ku rriten — këputja heq një lule që i deshi vite për t’u përhapur.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'sq', 'Zambaku i luginës', 'Çdo pjesë e kësaj bime aromatike është helmuese nëse hahet.', 'Në fund të pranverës ndiqni aromën deri te pyjet me hije.', 'Lini buzët e pyllit me hije dhe gjethet e rëna ku rritet.', 'Mos e këputni dhe mos e shkulni; mbajeni larg fëmijëve dhe kafshëve shtëpiake.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'sq', 'Hudhra e egër', 'Hudhrën e egër shpesh e nuhat para se t’i shohësh lulet e bardha.', 'Në pranverë kërkoni gjethe të gjera të gjelbra dhe lule si yje në pyje të lagështa.', 'Lini pyllin e lagësht të paprekur që tapetet të rriten sërish çdo vit.', 'Nëse mbledhja lejohet lokalisht, merrni pak dhe kurrë mos i shkulni qepujkat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'sq', 'Lulja e artë e kënetës', 'Një nga bimët vendase më të vjetra; i mbijetoi epokës së fundit të akullnajave në Skandinavi.', 'Në pranverë kërkoni lule të mëdha të arta në moçale, kanale dhe buzë pellgjesh.', 'Mbajini buzët e pellgjeve dhe kanaleve të lagështa e të pakositura që të lulëzojë.', 'Mos e thani tokën e lagësht dhe lini bimët aty ku rriten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'sq', 'Aguliçja', 'Aguliçet ishin dikur aq të zakonshme në livadhe sa fëmijët bënin topa prej tyre.', 'Në pranverë kërkoni lule të verdha të varura në livadhe të vjetra e të papunuara.', 'Mos i kosisni livadhet derisa aguliçet të lulëzojnë dhe të bëjnë farë.', 'Mos i këputni e mos i shkulni nga natyra — lulet e livadhit po pakësohen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'sq', 'Luleshqerra e madhe', 'Ajo që duket si një lule është në të vërtetë dhjetëra lule të vockla bashkë.', 'Në verë kërkoni luleshqerra të mëdha të bardha buzë rrugëve dhe në livadhe.', 'Lini një rrip bari pa kositur gjatë mesit të verës që të lulëzojë.', 'Mos spërkatni me herbicid buzët e rrugëve dhe livadhet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'sq', 'Luleradhiqja', 'Luleradhiqja është një nga burimet më të rëndësishme të hershme të nektarit për bletët.', 'Nga pranvera e tutje pothuajse kudo; lulet hapen në diell dhe mbyllen në muzg.', 'Lini luleradhiqet të lulëzojnë në lëndinë në pranverë para kositjes së parë.', 'Hiqni dorë nga herbicidet e lëndinës që polenizuesit e hershëm ta ruajnë këtë ushqim jetik.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'sq', 'Shqopa', 'Një bimë e vetme shqope mund të prodhojë mbi njëqind mijë fara të vockla.', 'Në fund të verës kërkoni tapete vjollce në shqopishte të hapura dhe moçale.', 'Mbështetni mbajtjen e shqopishteve të hapura dhe pa kullim.', 'Qëndroni në shtigje në shqopishte dhe kurrë mos ndizni zjarr në kushte të thata.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'sq', 'Boronica e kaltër', 'Boronicat t’i ngjyrosin gishtat blu dhe ushqejnë gjithçka, nga zogjtë te arinjtë.', 'Në verë kërkoni shkurre të ulëta me kokrra të errëta në pyje pishe e bredhi.', 'Lini nënshtresën e pyllit të paprekur që shkurret e ulëta të japin frut.', 'Nëse mbledhja lejohet lokalisht, lini shumë kokrra për botën e egër.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'sq', 'Boronica e kuqe', 'Ruhen me muaj falë një konservuesi natyror në frut.', 'Në fund të verës dhe vjeshtë kërkoni kokrra të kuqe të shndritshme mbi tapete gjithnjë të gjelbra.', 'Lini bimësinë e dyshemesë së pyllit të paprekur që tapetet të përhapen.', 'Nëse mbledhja lejohet, shkelni me kujdes për të mos i shtypur bimët.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'sq', 'Mështekna e argjendtë', 'Një mështekën mban qindra lloje insektesh, që nga ana e tyre ushqejnë panumër zogj.', 'Gjithë vitin; lëvorja e bardhë që qëron e bën të lehtë për t’u dalluar në çdo stinë.', 'Lini gjethet e rëna dhe drurin e vdekur të pasurojnë tokën dhe të ushqejnë insektet.', 'Shmangni heqjen e lëvores, që mund ta plagosë e dobësojë pemën.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'sq', 'Bredhi i Norvegjisë', 'Një bredh në Suedi rritet nga rrënjë të vjetra mijëra vjeç.', 'Gjithë vitin në pyje; kukurecat e varura janë më të gjatat mes bredhave.', 'Lini kukurecat e rëna dhe drurin e vdekur, që strehojnë insekte dhe kërpudha.', 'Qëndroni në shtigje në pyll për të mos ngjeshur rrënjët e cekëta të bredhit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'sq', 'Pisha skoceze', 'Pishat e vjetra shkëlqejnë portokalli lart dhe mund të jetojnë me shekuj.', 'Gjithë vitin në tokë ranore e shkëmbore; kërkoni lëvoren portokalli lart.', 'Lini drurin e vdekur në këmbë dhe pishat e vjetra, të pasura me jetë të egër.', 'Kurrë mos ndizni zjarr pranë pishave në tokë të thatë ranore.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'sq', 'Mlyshi verior', 'Është grabitqar prite që sulet nga qetësia brenda një çasti.', 'Nga pranvera në vjeshtë në cektinat me bimë të liqeneve dhe lumenjve të ngadaltë.', 'Mbështetni ruajtjen e cektinave me kallamishte dhe bimëve ujore ku strehohen peshqit e vegjël.', 'Mbajini ndotjen dhe mbeturinat larg ujit; ndiqni rregullat vendore të peshkimit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'sq', 'Perka evropiane', 'Gjuajnë në tufa dhe vijat e forta ua thyejnë siluetën.', 'Në muajt e ngrohtë rreth skelave, shtretërve me bimë dhe thyerjeve nënujore.', 'Mbështetni ujin e pastër dhe strukturat nënujore që strehojnë peshqit e vegjël.', 'Kurrë mos hidhni asgjë në liqene e lumenj; ndiqni rregullat vendore të peshkimit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'sq', 'Peshku roç', 'Është peshk ushqimor kyç nga i cili varen shumë grabitqarë liqenorë.', 'Në muajt e ngrohtë në tufa pranë sipërfaqes së liqeneve dhe lumenjve të ngadaltë.', 'Mbështetni ujin e pastër dhe buzët me bimësi për shumimin.', 'Mbajini rrjedhjet dhe mbeturinat larg ujit; ndiqni rregullat vendore të peshkimit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ru', 'Чёрный стриж', 'Стрижи могут месяцами держаться в воздухе и даже спят в полёте.', 'Тёплыми летними вечерами смотрите высоко над крышами и слушайте кричащие стаи.', 'Повесьте гнездовой ящик под карнизом до возвращения птиц весной.', 'При ремонте сохраните узкие щели под карнизом, где стрижи устраивают гнёзда.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ru', 'Деревенская ласточка', 'Ласточки каждый год летят на юг Африки и обратно.', 'С весны до начала осени ищите их в низком полёте над полями и водой.', 'Оставьте дверь сарая приоткрытой, чтобы они добрались до гнездовых выступов.', 'Не сбивайте старые глиняные гнёзда — ласточки используют их из года в год.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ru', 'Обыкновенная кукушка', 'Кукушка откладывает яйца в чужие гнёзда и никогда не растит собственных птенцов.', 'В конце весны слушайте далёкое «ку-ку» с опушек леса.', 'Поддержите богатые насекомыми луга и живые изгороди, кормящие птиц-хозяев.', 'Держитесь троп у зарослей и тростников, чтобы не тревожить птиц-хозяев.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ru', 'Зарянка', 'Зарянки яростно защищают территорию и поют всю ночь у уличных фонарей.', 'Круглый год в садах и лесах; часто следуют за тем, кто копает землю, в надежде на червей.', 'Оставьте угол сада с опавшей листвой, где они смогут искать корм.', 'Отложите сильную обрезку изгороди до конца гнездования в конце лета.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ru', 'Чёрный дрозд', 'Богатая флейтовая песня самца — одна из самых узнаваемых в Европе.', 'Круглый год; на рассвете и в сумерках слушайте самцов, поющих с крыш и вершин деревьев.', 'Поставьте свежую воду для питья и купания, особенно в засушливые периоды.', 'В сезон гнездования держите кошек дома на рассвете.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ru', 'Рябинник', 'Общественный дрозд, зимой кочующий шумными трещащими стаями.', 'Осенью и зимой смотрите, как стаи обирают ягоды с изгородей и рябин.', 'Не обрезайте кусты с ягодами в течение зимы.', 'Оставьте зимой падалицу яблок на земле — в холода это важнейший корм.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ru', 'Большая синица', 'У больших синиц огромный набор звуков, и новые они перенимают у соседей.', 'Круглый год; с конца зимы слушайте звонкую повторяющуюся песню.', 'Повесьте домик с летком 32 мм в тихом затенённом месте.', 'Избегайте садовых пестицидов, чтобы гусениц хватило на выкармливание птенцов.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ru', 'Лазоревка', 'Один выводок лазоревок может съесть более тысячи гусениц.', 'Круглый год в садах и лесах, часто висят вниз головой на тонких веточках.', 'Повесьте небольшой домик с летком 25 мм вдали от господствующих ветров.', 'Весной откажитесь от инсектицидов, чтобы гусеницы достались птенцам.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ru', 'Зяблик', 'Песня зяблика различается по местностям — почти как местные говоры.', 'С весны до осени; самцы поют яркую нисходящую фразу с открытых веток.', 'Оставьте на сезон часть семенных головок и травянистых куртин.', 'Держите кормушки чистыми, чтобы среди вьюрков не распространялись болезни.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ru', 'Сойка', 'Каждую осень сойки прячут тысячи желудей и, забывая часть, засевают дубравы.', 'Круглый год в дубравах; осенью высматривайте вспышки розового и голубого.', 'Оставьте опавшие жёлуди и листву под дубами нетронутыми.', 'Держите собак на тропах в лесу, чтобы не спугнуть птиц, кормящихся на земле.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ru', 'Большой пёстрый дятел', 'Весенняя барабанная дробь — не добыча корма, а быстрый сигнал о своей территории.', 'Круглый год; в конце зимы слушайте дробь, разносящуюся по лесу.', 'Оставьте сухостой — в нём живут насекомые, которыми он кормится.', 'Не спиливайте мёртвые и усыхающие деревья: в них могут быть дупла с гнёздами.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ru', 'Белая трясогузка', 'Постоянное покачивание хвостом, возможно, сигнализирует хищникам о бдительности.', 'С весны до осени у воды и на открытых местах; бегает и замирает, ловя насекомых.', 'Сохраните у воды участок низкой травы или гальки, где она сможет кормиться.', 'Не тревожьте галечные берега, где трясогузки кормятся и гнездятся.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ru', 'Серый журавль', 'Ранней весной журавли исполняют брачные танцы с прыжками и поклонами.', 'С весны до осени у болот; слушайте трубный клич, слышный за километры.', 'Поддержите охрану неосушенных болот и влажных лугов, где журавли гнездятся.', 'Наблюдайте гнездовые болота издали — потревоженное гнездо журавли бросают.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ru', 'Лебедь-кликун', 'Кликуны образуют пару на всю жизнь и возвещают прилёт громкими трубными криками.', 'Весной и осенью на озёрах и залитых полях, часто семейными группами.', 'Поддержите сохранение мелководных берегов и влажных полей без осушения.', 'Никогда не кормите лебедей хлебом — это им вредит; на льду держите дистанцию.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ru', 'Кряква', 'Утята плавают и кормятся сами уже через несколько часов после вылупления.', 'Круглый год почти на любом пруду, озере или медленной реке.', 'Если кормите уток, используйте овёс, горох или семена вместо хлеба.', 'Весной не пускайте собак в воду, где утки устраивают гнёзда.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ru', 'Обыкновенный канюк', 'Канюк парит на широких крыльях и часто кричит по-кошачьи «пиии-у».', 'С весны до осени; высматривайте его кружащим высоко над полями и опушками.', 'Поддержите грубые луга и краевые полосы полей, где живут полёвки и мелкая добыча.', 'Никогда не применяйте яды от грызунов: по пищевой цепи они попадают к хищным птицам.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ru', 'Скопа', 'Скопа ныряет вперёд лапами и может унести добычу в половину собственного веса.', 'С весны до осени у крупных озёр; сначала зависает в воздухе, затем резко пикирует.', 'Поддержите установку гнездовых платформ на высоких столбах у богатых рыбой озёр.', 'Обходите гнездовые платформы далеко стороной, чтобы пары не бросили кладку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ru', 'Обыкновенная лисица', 'Лисицы используют магнитное поле Земли, рассчитывая прыжок на скрытую добычу.', 'Круглый год, активнее всего на рассвете и в сумерках у опушек и краёв полей.', 'Оставьте дикий тихий угол, где лисицы смогут отдыхать и рыть нору.', 'Закрывайте баки и никогда не оставляйте лисам вредные пищевые отходы.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ru', 'Европейский ёж', 'За одну ночь поисков корма ёж может пройти пару километров.', 'С весны до осени после наступления темноты; зимой спит под кучами листьев и брёвен.', 'Сделайте в заборе проём 13 см, чтобы ежи могли перемещаться между садами.', 'Проверяйте высокую траву перед покосом и оставляйте кучи листьев для зимовки.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ru', 'Косуля', 'Косули задерживают развитие беременности, чтобы телята рождались в начале лета.', 'Круглый год на опушках, заметнее всего на пастьбе на рассвете и в сумерках.', 'Поддержите нескошенные краевые полосы полей и заросли, дающие укрытие и корм.', 'В начале лета, когда телята лежат в укрытии, держите собак на поводке у леса.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ru', 'Лось', 'Лось — самый крупный олень на Земле; крупный самец весит более полутонны.', 'Круглый год в лесах и на болотах, активнее всего на рассвете и в сумерках.', 'Поддержите связность лесов и болотных коридоров, нужных лосю для перемещений.', 'Осторожно ведите машину на лесных дорогах на рассвете и в сумерках; не подходите к телёнку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ru', 'Обыкновенная белка', 'Белки строят несколько гнёзд-гайно и перемещаются между ними.', 'Круглый год в хвойных и смешанных лесах, активнее всего ранним утром.', 'Оставьте шишки, орехи и стоящие деревья, где белки кормятся и гнездятся.', 'Держите собак на тропах и не тревожьте деревья, где может быть гайно.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ru', 'Речной бобр', 'Бобровые плотины создают водно-болотные угодья, где прибавляется рыбы, птиц и насекомых.', 'С весны до поздней осени у медленных рек, активнее всего в сумерках.', 'Поддержите сохранение плотин и прибрежных деревьев там, где это безопасно.', 'Держитесь подальше от хаток и плотин, особенно пока бобрята малы.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ru', 'Заяц-беляк', 'Зимой беляки белеют для маскировки на снегу.', 'Круглый год на открытых местах и лесных полянах, в основном на рассвете и в сумерках.', 'Поддержите чередование открытых участков и укрытий, нужное им весь год.', 'Держите собак на поводке на открытых местах, чтобы не гоняли отдыхающих зайцев.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ru', 'Барсук', 'Барсуки живут семейными группами в подземных норах, используемых поколениями.', 'С весны до осени после темноты у леса; зиму проводят во сне.', 'Оставьте нетронутыми склоны и живые изгороди, где барсуки могут рыть норы.', 'Никогда не заваливайте жилую нору и не копайте рядом — это их постоянный дом.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ru', 'Нетопырь-карлик', 'Эта крошечная летучая мышь съедает за ночь до 3000 мошек и комаров.', 'Летними вечерами наблюдайте быстрый зигзагообразный полёт в сумерках над садами.', 'Повесьте домик для летучих мышей высоко на стене или дереве, освещаемом вечерним солнцем.', 'Избегайте яркого света у входов в убежища и сохраняйте ночное небо тёмным.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ru', 'Крапивница', 'Эта бабочка зимует во взрослом состоянии, часто в сараях и на чердаках.', 'С ранней весны до осени на солнечных цветах, особенно на крапиве.', 'Оставьте куртину крапивы в солнечном углу — её гусеницам она необходима.', 'Не тревожьте зимующих бабочек в сараях в течение зимы.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ru', 'Павлиний глаз', 'Глазчатые пятна вспыхивают, пугая птиц, а крылья при раскрытии могут шипеть.', 'С весны до осени в солнечные дни; кормится на чертополохе и падалице.', 'Дайте разрастись солнечной куртине крапивы для её гусениц.', 'Не тревожьте взрослых бабочек, зимующих в сараях и поленницах.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ru', 'Лимонница', 'Английское слово «butterfly» могло произойти от масляно-жёлтого цвета самца этого вида.', 'Одна из первых бабочек весны; в тёплые дни ищите её по опушкам.', 'Поддержите кусты крушины в изгородях — единственный корм её гусениц.', 'Не расчищайте заросшие кустарником изгороди, где взрослые бабочки зимуют.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ru', 'Зорька', 'Только у самцов ярко-оранжевые вершины крыльев; самки белые.', 'Весной вдоль сырых лугов и просёлков, где растёт сердечник луговой.', 'Дайте сердечнику и чесночнице расти в сырых нескошенных углах.', 'Отложите скашивание обочин, пока гусеницы не закончат питание.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ru', 'Голубянка икар', 'За гусеницами голубянки иногда ухаживают муравьи ради их сладких выделений.', 'С конца весны на солнечных лугах, богатых клевером и лядвенцем.', 'Не косите луг, чтобы клевер и лядвенец могли зацвести.', 'Не обрабатывайте гербицидами луга, богатые дикими цветами.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ru', 'Брюквенница', 'Хотя похожа на капустницу, предпочитает дикие растения, а не садовые культуры.', 'С весны до конца лета на сырых лугах, в канавах и на лесных просеках.', 'Дайте сырым углам зарасти местными крестоцветными.', 'Не осушайте и не опрыскивайте сырые луга, где она размножается.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ru', 'Семиточечная коровка', 'Одна коровка за жизнь может съесть тысячи тлей.', 'С весны до осени на растениях с тлёй; зимой собираются на зимовку скоплениями.', 'Потерпите немного тли и откажитесь от опрыскиваний, чтобы коровкам было чем питаться.', 'Оставьте полые стебли и опавшую листву, где коровки укрываются зимой.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ru', 'Земляной шмель', 'Матки — среди первых пчёл весной; они низко гудят, отыскивая норки для гнезда.', 'С ранней весны до осени на цветах; весной матки обследуют основания изгородей.', 'Выращивайте или оставляйте рано цветущие растения и дайте клеверу цвести в газоне.', 'Оставьте нетронутыми склоны и старые мышиные норы, где гнездятся колонии.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ru', 'Медоносная пчела', 'Фуражиры сообщают улью, где цветы, танцуя восьмёркой.', 'С весны до осени на цветах в тёплые безветренные дни.', 'Пусть разные цветы сменяют друг друга весь сезон, и поставьте мелкую поилку.', 'Не опрыскивайте цветущие растения и никогда не опрыскивайте в середине дня.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ru', 'Дозорщик-император', 'Одна из крупнейших стрекоз Европы, способна ловить добычу прямо в воздухе.', 'В тёплые летние дни смотрите, как она патрулирует пруды и берега озёр.', 'Сохраните или выкопайте пруд с растениями и оставьте берега заросшими.', 'Берегите пруды от загрязнения и стоков, чтобы личинки могли развиваться.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ru', 'Стрекоза обыкновенная', 'Часто садится на одно и то же тёплое место и вылетает, хватая пролетающих насекомых.', 'С середины лета до осени у стоячей воды, греется на тропах и столбиках.', 'Оставьте солнечные присады и растительность вокруг прудов и канав.', 'Не допускайте смыва удобрений и масел в пруды, где живут личинки.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ru', 'Рыжий лесной муравей', 'Их купола могут быть выше метра и вмещать полмиллиона муравьёв.', 'С весны до осени в хвойных лесах; ищите куполообразные кучи из хвои.', 'Оставьте муравейники нетронутыми — на их постройку уходят годы.', 'Держитесь троп и никогда не разбивайте и не раскапывайте муравейник.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ru', 'Ветреница дубравная', 'Разрастается так медленно, что сплошные ковры указывают на старый лес.', 'Весной ищите ковры белых цветов до того, как деревья оденутся листвой.', 'Оставьте лесную подстилку нетронутой, чтобы медленно ползущие корневища разрастались.', 'Любуйтесь ими там, где они растут — срывая, вы уносите цветок, росший годами.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ru', 'Ландыш майский', 'Все части этого душистого растения ядовиты при проглатывании.', 'В конце весны идите на запах в тенистые леса и затенённые сады.', 'Оставьте тенистые опушки и опавшую листву там, где он растёт.', 'Не рвите и не выкапывайте его; держите подальше от детей и домашних животных.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ru', 'Черемша', 'Черемшу обычно чувствуешь по запаху раньше, чем увидишь белые цветы.', 'Весной ищите широкие зелёные листья и звёздчатые цветы в сырых лесах.', 'Оставьте сырой лес нетронутым, чтобы ковры отрастали каждый год.', 'Если сбор разрешён местно, берите немного и никогда не выкапывайте луковицы.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ru', 'Калужница болотная', 'Одно из древнейших местных растений: пережило последний ледниковый период в Скандинавии.', 'Весной ищите крупные золотистые цветы на болотах, в канавах и по краям прудов.', 'Держите края прудов и канав влажными и нескошенными, чтобы растение цвело.', 'Не осушайте сырые места и оставляйте растения там, где они растут.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ru', 'Первоцвет весенний', 'Первоцветы были так обычны на сенокосных лугах, что дети скатывали из них шары.', 'Весной ищите поникающие жёлтые цветы на старых неулучшенных лугах.', 'Не косите луга, пока первоцветы не отцветут и не завяжут семена.', 'Не рвите и не выкапывайте их в природе — луговые цветы сокращаются.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ru', 'Нивяник обыкновенный', 'То, что кажется одним цветком, на деле — десятки крошечных цветков вместе.', 'Летом ищите крупные белые ромашки вдоль дорог и на лугах.', 'Оставьте полосу травы нескошенной в середине лета, чтобы растение зацвело.', 'Не обрабатывайте гербицидами обочины и луга.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ru', 'Одуванчик лекарственный', 'Одуванчик — один из важнейших ранних источников нектара для пчёл.', 'С весны почти повсюду; цветки раскрываются на солнце и закрываются в сумерках.', 'Дайте одуванчикам зацвести на газоне весной до первого покоса.', 'Откажитесь от газонных гербицидов, чтобы ранние опылители сохранили этот важный корм.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ru', 'Вереск обыкновенный', 'Один куст вереска может дать более ста тысяч крошечных семян.', 'В конце лета ищите лиловые ковры на открытых пустошах и болотах.', 'Поддержите сохранение пустошей открытыми и неосушенными.', 'Держитесь троп на пустошах и никогда не разводите огонь в сухую погоду.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ru', 'Черника', 'Черника красит пальцы синим и кормит всех — от птиц до медведей.', 'Летом ищите низкие кустики с тёмными ягодами в сосновых и еловых лесах.', 'Оставьте лесной подлесок нетронутым, чтобы кустики могли плодоносить.', 'Если сбор разрешён местно, оставьте вдоволь ягод дикой природе.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ru', 'Брусника', 'Брусника хранится месяцами благодаря природному консерванту в ягодах.', 'В конце лета и осенью ищите блестящие красные ягоды на вечнозелёных куртинах.', 'Оставьте растительность лесной подстилки нетронутой, чтобы куртины разрастались.', 'Если сбор разрешён, ступайте осторожно, чтобы не примять растения.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ru', 'Берёза повислая', 'Берёза кормит сотни видов насекомых, а те — бесчисленных птиц.', 'Круглый год; белая отслаивающаяся кора делает её узнаваемой в любой сезон.', 'Оставьте опавшую листву и валежник, чтобы обогащать почву и кормить насекомых.', 'Не сдирайте кору — это ранит и ослабляет дерево.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ru', 'Ель европейская', 'Одна ель в Швеции растёт из корней возрастом в несколько тысяч лет.', 'Круглый год в лесах; её свисающие шишки — самые длинные среди елей.', 'Оставьте опавшие шишки и валежник, дающие приют насекомым и грибам.', 'Держитесь троп в лесу, чтобы не уплотнять поверхностные корни ели.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ru', 'Сосна обыкновенная', 'Старые сосны светятся оранжевым у вершины и могут жить веками.', 'Круглый год на песчаных и каменистых почвах; ищите оранжевую кору вверху ствола.', 'Оставьте сухостой и старые сосны — они богаты жизнью.', 'Никогда не разводите огонь у сосен на сухой песчаной почве.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ru', 'Обыкновенная щука', 'Щука — засадный хищник, способный броситься из полной неподвижности в мгновение ока.', 'С весны до осени на заросших мелководьях озёр и медленных рек.', 'Поддержите сохранение тростниковых мелководий и водных растений, где прячется молодь.', 'Не допускайте загрязнения и мусора в воде; соблюдайте местные правила рыболовства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ru', 'Речной окунь', 'Окуни охотятся стаями, а яркие полосы разбивают очертания их тела.', 'В тёплые месяцы у мостков, зарослей водных растений и свалов глубин.', 'Поддержите чистую воду и подводные укрытия, где прячется мелкая рыба.', 'Никогда ничего не сбрасывайте в озёра и реки; соблюдайте местные правила рыболовства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ru', 'Плотва', 'Плотва — ключевая кормовая рыба, от которой зависят многие озёрные хищники.', 'В тёплые месяцы стаями у поверхности озёр и медленных рек.', 'Поддержите чистоту воды и заросшие берега, нужные для нереста.', 'Не допускайте стоков и мусора в воде; соблюдайте местные правила рыболовства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'uk', 'Серпокрилець чорний', 'Серпокрильці можуть місяцями триматися в повітрі й навіть сплять у польоті.', 'Теплими літніми вечорами дивіться високо над дахами й слухайте крикливі зграї.', 'Повісьте гніздівлю під карнизом, доки птахи не повернулися навесні.', 'Під час ремонту збережіть вузькі щілини під карнизом, де вони гніздяться.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'uk', 'Ластівка сільська', 'Ластівки щороку летять аж на південь Африки й повертаються назад.', 'Від весни до початку осені шукайте їх у низькому польоті над полями та водою.', 'Залиште двері хліва чи повітки прочиненими, щоб вони дісталися до гнізд.', 'Не збивайте старі глиняні гнізда — ластівки використовують їх рік у рік.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'uk', 'Зозуля звичайна', 'Зозуля відкладає яйця в чужі гнізда й ніколи не вирощує власних пташенят.', 'Наприкінці весни слухайте далеке «ку-ку» з узлісь.', 'Підтримуйте багаті на комах луки та живоплоти, що годують птахів-господарів.', 'Тримайтеся стежок біля чагарників і очеретів, щоб не турбувати птахів-господарів.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'uk', 'Вільшанка', 'Вільшанки затято боронять територію й співають уночі біля вуличних ліхтарів.', 'Цілий рік у садах і лісах; часто йдуть за тим, хто копає землю, сподіваючись на черв’яків.', 'Залиште куток саду з опалим листям, де вони шукатимуть їжу.', 'Відкладіть сильне підрізання живоплоту, доки не завершиться гніздування наприкінці літа.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'uk', 'Дрізд чорний', 'Багата флейтова пісня самця — одна з найвпізнаваніших у Європі.', 'Цілий рік; на світанку й у сутінках слухайте самців, що співають з дахів і верхівок дерев.', 'Поставте свіжу воду для пиття й купання, особливо в посушливі періоди.', 'У сезон гніздування тримайте котів удома на світанку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'uk', 'Дрізд-чикотень', 'Товариський дрізд, що взимку кочує галасливими зграями.', 'Восени та взимку дивіться, як зграї обирають ягоди з живоплотів і горобин.', 'Не підрізайте кущі з ягодами протягом зими.', 'Залиште взимку падалицю яблук на землі — у холод це життєво важливий корм.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'uk', 'Синиця велика', 'У великих синиць величезний набір звуків, і нові вони переймають у сусідів.', 'Цілий рік; від кінця зими слухайте дзвінку повторювану пісню.', 'Повісьте будиночок з льотком 32 мм у тихому затіненому місці.', 'Уникайте садових пестицидів, щоб гусені вистачило на вигодовування пташенят.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'uk', 'Синиця блакитна', 'Один виводок блакитних синиць може з’їсти понад тисячу гусениць.', 'Цілий рік у садах і лісах, часто висять униз головою на тонких гілочках.', 'Повісьте невеликий будиночок з льотком 25 мм подалі від панівних вітрів.', 'Навесні відмовтеся від інсектицидів, щоб гусінь дісталася пташенятам.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'uk', 'Зяблик', 'Пісня зяблика різниться за місцевостями — майже як місцеві говірки.', 'Від весни до осені; самці співають яскраву низхідну фразу з відкритих гілок.', 'Залиште на сезон частину насінних голівок і трав’янистих куртин.', 'Тримайте годівниці чистими, щоб серед в’юрків не поширювалися хвороби.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'uk', 'Сойка', 'Щоосені сойки ховають тисячі жолудів і, забуваючи частину, засівають діброви.', 'Цілий рік у дібровах; восени виглядайте спалахи рожевого й блакитного.', 'Залиште опалі жолуді та листя під дубами недоторканими.', 'Тримайте собак на стежках у лісі, щоб не сполохати птахів, які годуються на землі.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'uk', 'Дятел звичайний', 'Весняний барабанний дріб — не пошук їжі, а швидкий сигнал про свою територію.', 'Цілий рік; наприкінці зими слухайте дріб, що лунає лісом.', 'Залиште сухостій — у ньому живуть комахи, якими він годується.', 'Не спилюйте мертві та всихаючі дерева: у них можуть бути дупла з гніздами.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'uk', 'Плиска біла', 'Постійне погойдування хвостом, можливо, сигналізує хижакам про пильність.', 'Від весни до осені біля води та на відкритих місцях; бігає й завмирає, ловлячи комах.', 'Збережіть біля води ділянку низької трави чи рінища, де вона зможе годуватися.', 'Не турбуйте галькові береги, де плиски годуються й гніздяться.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'uk', 'Журавель сірий', 'Ранньою весною журавлі виконують шлюбні танці зі стрибками й поклонами.', 'Від весни до осені біля боліт; слухайте сурмовий клич, чутний за кілометри.', 'Підтримайте охорону неосушених боліт і вологих лук, де журавлі гніздяться.', 'Спостерігайте гніздові болота здалеку — потривожене гніздо журавлі кидають.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'uk', 'Лебідь-кликун', 'Кликуни утворюють пару на все життя й сповіщають про приліт гучними сурмовими криками.', 'Навесні й восени на озерах і залитих полях, часто родинними групами.', 'Підтримайте збереження мілководних берегів і вологих полів без осушення.', 'Ніколи не годуйте лебедів хлібом — це їм шкодить; на кризі тримайте дистанцію.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'uk', 'Крижень', 'Каченята плавають і годуються самі вже за кілька годин після вилуплення.', 'Цілий рік майже на будь-якому ставку, озері чи повільній річці.', 'Якщо годуєте качок, беріть овес, горох або насіння замість хліба.', 'Навесні не пускайте собак у воду, де качки влаштовують гнізда.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'uk', 'Канюк звичайний', 'Канюк ширяє на широких крилах і часто кричить по-котячому «піі-у».', 'Від весни до осені; виглядайте його, коли кружляє високо над полями й узліссями.', 'Підтримуйте грубі луки та краї полів, де живуть полівки й дрібна здобич.', 'Ніколи не застосовуйте отрути від гризунів: харчовим ланцюгом вони потрапляють до хижих птахів.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'uk', 'Скопа', 'Скопа пірнає вперед лапами й може віднести здобич у половину власної ваги.', 'Від весни до осені біля великих озер; спершу зависає в повітрі, тоді різко пікірує.', 'Підтримайте встановлення гніздових платформ на високих стовпах біля багатих на рибу озер.', 'Обходьте гніздові платформи далеко стороною, щоб пари не покинули кладку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'uk', 'Лисиця руда', 'Лисиці використовують магнітне поле Землі, розраховуючи стрибок на приховану здобич.', 'Цілий рік, найактивніші на світанку й у сутінках біля узлісь і країв полів.', 'Залиште дикий тихий куток, де лисиці зможуть відпочивати й рити нору.', 'Закривайте баки й ніколи не залишайте лисицям шкідливих харчових решток.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'uk', 'Їжак європейський', 'За одну ніч пошуків їжі їжак може пройти кілька кілометрів.', 'Від весни до осені після темряви; узимку спить під купами листя й колод.', 'Зробіть у паркані отвір 13 см, щоб їжаки могли переходити між садами.', 'Перевіряйте високу траву перед косінням і залишайте купи листя для зимівлі.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'uk', 'Козуля європейська', 'Козулі затримують розвиток вагітності, щоб малята народжувалися на початку літа.', 'Цілий рік на узліссях, найпомітніші на випасі на світанку й у сутінках.', 'Підтримуйте нескошені краї полів і чагарники, що дають прихисток і корм.', 'На початку літа, коли малята лежать у схованці, тримайте собак на повідку біля лісу.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'uk', 'Лось', 'Лось — найбільший олень на Землі; великий самець важить понад пів тонни.', 'Цілий рік у лісах і на болотах, найактивніший на світанку й у сутінках.', 'Підтримуйте зв’язність лісів і болотних коридорів, потрібних лосю для переходів.', 'Обережно ведіть авто лісовими дорогами на світанку й у сутінках; не підходьте до теляти.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'uk', 'Вивірка звичайна', 'Вивірки будують кілька гнізд і переміщуються між ними.', 'Цілий рік у хвойних і мішаних лісах, найактивніші рано вранці.', 'Залиште шишки, горіхи й стоячі дерева, де вивірки годуються й гніздяться.', 'Тримайте собак на стежках і не турбуйте дерева, де може бути гніздо.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'uk', 'Бобер європейський', 'Боброві греблі створюють водно-болотні угіддя, де більшає риби, птахів і комах.', 'Від весни до пізньої осені біля повільних річок, найактивніші в сутінках.', 'Підтримайте збереження гребель і прибережних дерев там, де це безпечно.', 'Тримайтеся подалі від хаток і гребель, особливо поки бобренята малі.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'uk', 'Заєць білий', 'Узимку зайці білішають для маскування на снігу.', 'Цілий рік на відкритих місцях і лісових галявинах, переважно на світанку й у сутінках.', 'Підтримуйте чергування відкритих ділянок і прихистку, потрібне їм цілий рік.', 'Тримайте собак на повідку на відкритих місцях, щоб не ганяли зайців на відпочинку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'uk', 'Борсук', 'Борсуки живуть родинними групами в підземних норах, які використовують поколіннями.', 'Від весни до осені після темряви біля лісу; зиму проводять уві сні.', 'Залиште недоторканими схили й живоплоти, де борсуки можуть рити нори.', 'Ніколи не засипайте жилу нору й не копайте поруч — це їхня постійна оселя.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'uk', 'Нетопир-карлик', 'Ця крихітна летюча миша з’їдає за ніч до 3000 мошок і комарів.', 'Літніми вечорами спостерігайте швидкий зигзагоподібний політ у сутінках над садами.', 'Повісьте будиночок для кажанів високо на стіні чи дереві, освітленому вечірнім сонцем.', 'Уникайте яскравого світла біля входів у сховища й зберігайте нічне небо темним.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'uk', 'Кропив’янка', 'Ця метелиця зимує дорослою, часто в сараях і на горищах.', 'Від ранньої весни до осені на сонячних квітах, особливо на кропиві.', 'Залиште куртину кропиви в сонячному кутку — її гусені вона необхідна.', 'Не турбуйте метеликів, що зимують у сараях, протягом зими.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'uk', 'Павичеве око', 'Очкасті плями спалахують, лякаючи птахів, а крила при розкритті можуть шипіти.', 'Від весни до осені в сонячні дні; годується на будяках і падалиці.', 'Дайте розростися сонячній куртині кропиви для її гусені.', 'Не турбуйте дорослих метеликів, що зимують у сараях і дровітнях.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'uk', 'Лимонниця', 'Англійське слово «butterfly» могло походити від масляно-жовтого кольору самця цього виду.', 'Один з перших метеликів весни; у теплі дні шукайте його на узліссях.', 'Підтримуйте кущі крушини в живоплотах — єдиний корм її гусені.', 'Не розчищайте зарослі чагарником живоплоти, де дорослі метелики зимують.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'uk', 'Зірочка', 'Лише в самців яскраво-помаранчеві вершини крил; самиці білі.', 'Навесні вздовж вологих лук і путівців, де росте люмбаж лучний.', 'Дайте польовим квітам рости у вологих нескошених кутках.', 'Відкладіть скошування узбіч, доки гусінь не закінчить живлення.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'uk', 'Голубʼянка ікар', 'За гусінню голуб’янки іноді доглядають мурахи заради їхніх солодких виділень.', 'Від кінця весни на сонячних луках, багатих на конюшину та лядвенець.', 'Не косіть луку, щоб конюшина й лядвенець могли зацвісти.', 'Не обробляйте гербіцидами луки, багаті на дикі квіти.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'uk', 'Біланка брукв’яна', 'Хоч і схожа на капустянку, віддає перевагу диким рослинам, а не садовим культурам.', 'Від весни до кінця літа на вологих луках, у канавах і на лісових просіках.', 'Дайте вологим куткам зарости місцевими хрестоцвітими.', 'Не осушуйте й не обприскуйте вологі луки, де вона розмножується.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'uk', 'Сонечко семикрапкове', 'Одне сонечко за життя може з’їсти тисячі попелиць.', 'Від весни до осені на рослинах з попелицею; узимку збираються на зимівлю.', 'Потерпіть трохи попелиці й відмовтеся від обприскувань, щоб сонечкам було чим живитися.', 'Залиште порожнисті стебла й опале листя, де сонечка ховаються взимку.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'uk', 'Джміль земляний', 'Матки — серед перших бджіл навесні; вони низько гудуть, шукаючи нірки для гнізда.', 'Від ранньої весни до осені на квітах; навесні матки обстежують основи живоплотів.', 'Вирощуйте або залишайте ранньоквітучі рослини й дайте конюшині цвісти в газоні.', 'Залиште недоторканими схили й старі мишачі нірки, де гніздяться колонії.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'uk', 'Бджола медоносна', 'Фуражири повідомляють вулику, де квіти, танцюючи вісімкою.', 'Від весни до осені на квітах у теплі безвітряні дні.', 'Хай різні квіти змінюють одна одну весь сезон, і поставте мілку напувалку.', 'Не обприскуйте квітучі рослини й ніколи не обприскуйте серед дня.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'uk', 'Коромисло імператорське', 'Одна з найбільших бабок Європи, здатна ловити здобич просто в повітрі.', 'У теплі літні дні дивіться, як вона патрулює ставки та береги озер.', 'Збережіть або викопайте ставок з рослинами й залиште береги зарослими.', 'Бережіть ставки від забруднення й стоків, щоб личинки могли розвиватися.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'uk', 'Бабка звичайна', 'Часто сідає на те саме тепле місце й вилітає, хапаючи комах, що пролітають.', 'Від середини літа до осені біля стоячої води, гріється на стежках і стовпчиках.', 'Залиште сонячні присади й рослинність навколо ставків і канав.', 'Не допускайте змиву добрив і олив у ставки, де живуть личинки.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'uk', 'Мурашка руда лісова', 'Їхні куполи можуть бути вищими за метр і вміщати пів мільйона мурах.', 'Від весни до осені в хвойних лісах; шукайте куполоподібні купи з хвої.', 'Залиште мурашники недоторканими — на їхню побудову йдуть роки.', 'Тримайтеся стежок і ніколи не розбивайте й не розкопуйте мурашник.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'uk', 'Анемона дібровна', 'Розростається так повільно, що суцільні килими вказують на старий ліс.', 'Навесні шукайте килими білих квітів, доки дерева не вкрилися листям.', 'Залиште лісову підстилку недоторканою, щоб повільні кореневища розросталися.', 'Милуйтеся ними там, де вони ростуть — зриваючи, ви забираєте квітку, що росла роками.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'uk', 'Конвалія травнева', 'Усі частини цієї запашної рослини отруйні, якщо їх з’їсти.', 'Наприкінці весни йдіть на запах у затінені ліси й сади.', 'Залиште затінені узлісся й опале листя там, де вона росте.', 'Не рвіть і не викопуйте її; тримайте подалі від дітей і домашніх тварин.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'uk', 'Черемша', 'Черемшу зазвичай відчуваєш за запахом раніше, ніж побачиш білі квіти.', 'Навесні шукайте широкі зелені листки й зіркові квіти у вологих лісах.', 'Залиште вологий ліс недоторканим, щоб килими відростали щороку.', 'Якщо збір дозволено місцево, беріть небагато й ніколи не викопуйте цибулини.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'uk', 'Калюжниця болотна', 'Одна з найдавніших місцевих рослин: пережила останній льодовиковий період у Скандинавії.', 'Навесні шукайте великі золотисті квіти на болотах, у канавах і по краях ставків.', 'Тримайте краї ставків і канав вологими й нескошеними, щоб рослина цвіла.', 'Не осушуйте вологі місця й залишайте рослини там, де вони ростуть.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'uk', 'Первоцвіт весняний', 'Первоцвіти були такі звичайні на сінокосах, що діти скочували з них кулі.', 'Навесні шукайте похилі жовті квіти на старих неполіпшених луках.', 'Не косіть луки, доки первоцвіти не відцвітуть і не зав’яжуть насіння.', 'Не рвіть і не викопуйте їх у природі — лучні квіти зникають.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'uk', 'Королиця звичайна', 'Те, що здається однією квіткою, насправді — десятки крихітних квіточок разом.', 'Улітку шукайте великі білі ромашки вздовж доріг і на луках.', 'Залиште смугу трави нескошеною в середині літа, щоб рослина зацвіла.', 'Не обробляйте гербіцидами узбіччя й луки.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'uk', 'Кульбаба лікарська', 'Кульбаба — одне з найважливіших ранніх джерел нектару для бджіл.', 'Від весни майже всюди; квітки розкриваються на сонці й закриваються в сутінках.', 'Дайте кульбабам зацвісти в газоні навесні до першого косіння.', 'Відмовтеся від газонних гербіцидів, щоб ранні запилювачі зберегли цей важливий корм.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'uk', 'Верес звичайний', 'Один кущ вересу може дати понад сто тисяч крихітних насінин.', 'Наприкінці літа шукайте бузкові килими на відкритих пустищах і болотах.', 'Підтримайте збереження пустищ відкритими й неосушеними.', 'Тримайтеся стежок на пустищах і ніколи не розводьте вогонь у суху погоду.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'uk', 'Чорниця', 'Чорниця фарбує пальці в синє й годує всіх — від птахів до ведмедів.', 'Улітку шукайте низькі кущики з темними ягодами в соснових і ялинових лісах.', 'Залиште лісовий підлісок недоторканим, щоб кущики могли плодоносити.', 'Якщо збір дозволено місцево, залиште вдосталь ягід дикій природі.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'uk', 'Брусниця', 'Брусниця зберігається місяцями завдяки природному консерванту в ягодах.', 'Наприкінці літа й восени шукайте блискучі червоні ягоди на вічнозелених куртинах.', 'Залиште рослинність лісової підстилки недоторканою, щоб куртини розросталися.', 'Якщо збір дозволено, ступайте обережно, щоб не прим’яти рослини.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'uk', 'Береза повисла', 'Береза годує сотні видів комах, а ті — незліченних птахів.', 'Цілий рік; біла кора, що лущиться, робить її впізнаваною будь-якої пори.', 'Залиште опале листя й повалену деревину, щоб збагачувати ґрунт і годувати комах.', 'Не здирайте кору — це ранить і послаблює дерево.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'uk', 'Ялина європейська', 'Одна ялина у Швеції росте з коренів віком у кілька тисяч років.', 'Цілий рік у лісах; її звисаючі шишки — найдовші серед ялин.', 'Залиште опалі шишки й повалену деревину, що дають прихисток комахам і грибам.', 'Тримайтеся стежок у лісі, щоб не ущільнювати поверхневі корені ялини.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'uk', 'Сосна звичайна', 'Старі сосни світяться помаранчевим угорі й можуть жити століттями.', 'Цілий рік на піщаних і кам’янистих ґрунтах; шукайте помаранчеву кору вгорі стовбура.', 'Залиште сухостій і старі сосни — вони багаті на життя.', 'Ніколи не розводьте вогонь біля сосен на сухому піщаному ґрунті.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'uk', 'Щука звичайна', 'Щука — засадний хижак, здатний кинутися з цілковитої нерухомості за мить.', 'Від весни до осені на зарослих мілинах озер і повільних річок.', 'Підтримайте збереження очеретяних мілин і водяних рослин, де ховається молодь.', 'Не допускайте забруднення й сміття у воді; дотримуйтеся місцевих правил рибальства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'uk', 'Окунь річковий', 'Окуні полюють зграями, а яскраві смуги розбивають обриси їхнього тіла.', 'У теплі місяці біля містків, заростей водяних рослин і свалів глибин.', 'Підтримайте чисту воду й підводні укриття, де ховається дрібна риба.', 'Ніколи нічого не скидайте в озера й річки; дотримуйтеся місцевих правил рибальства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'uk', 'Плітка', 'Плітка — ключова кормова риба, від якої залежать багато озерних хижаків.', 'У теплі місяці зграями біля поверхні озер і повільних річок.', 'Підтримайте чистоту води й зарослі береги, потрібні для нересту.', 'Не допускайте стоків і сміття у воді; дотримуйтеся місцевих правил рибальства.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ps', 'چټک الوتونکی مرغه', 'دوی کولی شي میاشتې په هوا کې پاتې شي، حتی د الوتنې پر مهال ویده کیږي.', 'د اوړي په ګرمو ماښامونو کې د بامونو پورته وګورئ او چغې وهونکو ډلو ته غوږ ونیسئ.', 'د پسرلي په راستنېدو مخکې د بام تر څنډې لاندې د ځالې بکس کېږدئ.', 'کله چې کور نوی کوئ، هغه وړې درزونه وساتئ چې د بام تر څنډې لاندې ځالې جوړوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ps', 'د کور زوزۍ', 'کلنۍ تر سویلي افریقا پورې کډه کوي او بېرته راګرځي.', 'د پسرلي څخه تر مني پیل، د پټیو او اوبو پر سر ټیټ الوتنه یې وګورئ.', 'د طویلې یا ګودام دروازه لږ خلاصه پرېږدئ چې خپلو ځالو ته ورسیږي.', 'زړې خټینې ځالې مه ړنګوئ — زوزۍ یې کال په کال بیا کاروي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ps', 'کوکو مرغه', 'خپلې هګۍ د نورو مرغانو په ځالو کې اچوي او هیڅکله خپل بچي نه روزي.', 'د پسرلي په پای کې د ځنګل له څنډو د لرې «کو-کو» غږ ته غوږ ونیسئ.', 'هغه څړځایونه او پولې ملاتړ کړئ چې د حشراتو بډایه دي او کوربه مرغان پرې ژوند کوي.', 'د بوټو او نيو تر څنګ په لارو پاتې شئ چې کوربه مرغان ونه ځورول شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ps', 'سره سینه مرغه', 'له خپلې سیمې سخت دفاع کوي او د کوڅې د څراغونو تر څنګ شپه هم سندرې وايي.', 'ټول کال په باغونو او ځنګلونو کې؛ ډېری وخت د خاورې کیندونکي شاته ځي چې چینجي ومومي.', 'د باغ یوه ګوښه له لوېدلو پاڼو سره پرېږدئ چې هلته خواړه ولټوي.', 'د پولې درنه پرېکړه تر اوړي پایه وځنډوئ، کله چې ځاله جوړول پای ته ورسیږي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ps', 'تور مرغه', 'د نر بډایه، بانسري‌ډوله سندره په اروپا کې تر ټولو پېژندل شوې ده.', 'ټول کال؛ سهار او ماښام نرانو ته غوږ ونیسئ چې له بامونو او د ونو له څوکو سندرې وايي.', 'د څښلو او لمبېدو لپاره تازه اوبه کېږدئ، په تېره د وچکالۍ په وختونو کې.', 'د ځالې په موسم کې پیشوګانې سهار په کور کې وساتئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ps', 'د پټي توتکۍ', 'ټولنیز مرغه دی چې ژمی په غږیزو ډلو کې ګرځي.', 'په مني او ژمي کې وګورئ چې ډلې له پولو او ونو څخه توتان راټولوي.', 'د توتانو بوټي د ژمي په اوږدو کې مه پرېکوئ.', 'د ژمي په وخت کې لوېدلي مڼې پر ځمکه پرېږدئ — په یخنۍ کې مهم خواړه دي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ps', 'لوی چڼچڼک', 'ډېر ډول غږونه لري او نوي یې له ګاونډیانو زده کوي.', 'ټول کال؛ د ژمي له پایه یې زنګ‌وهونکې تکرارېدونکې سندرې ته غوږ ونیسئ.', 'د ۳۲ ملي‌متره سوري لرونکی د ځالې بکس په آرام او سیوري ځای کې ځوړند کړئ.', 'د باغ زهرو ته شا کړئ چې د بچو د خوړلو لپاره کافي چینجي پاتې شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ps', 'شین چڼچڼک', 'د یوې ځالې بچي کولی شي له زرو ډېر چینجي وخوري.', 'ټول کال په باغونو او ځنګلونو کې، ډېری وخت له نریو څانګو نه سرچپه ځوړند وي.', 'د ۲۵ ملي‌متره سوري لرونکی وړوکی بکس له باده لرې کېږدئ.', 'په پسرلي کې د حشراتو زهر مه کاروئ چې چینجي د بچو لپاره شتون ولري.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ps', 'د ځنګله زرکه', 'سندرې یې له سیمې تر سیمې توپیر کوي، نږدې لکه سیمه‌ییزې لهجې.', 'له پسرلي تر مني؛ نران له خلاصو ځایونو څخه روښانه ښکته‌کېدونکې جمله وايي.', 'د موسم په اوږدو کې ځینې د تخم سرونه او واښه ولاړ پرېږدئ.', 'د خوړو ځایونه پاک وساتئ چې ناروغي په مرغانو کې خپره نه شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ps', 'د ونې زاغ', 'هره مني زرګونه د ونې مېوې خښوي او ځینې هېروي، نو د ونو ځنګلونه کري.', 'ټول کال په ځنګلونو کې؛ په مني کې د ګلابي او شنه رنګ ځلا ته پام وکړئ.', 'لوېدلې مېوې او پاڼې د ونو لاندې لکه څنګه چې دي پرېږدئ.', 'سپي په ځنګل کې پر لار وساتئ چې پر ځمکه خوړونکي مرغان ونه ډارول شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ps', 'لوی خالدار ونه‌ټکوونکی', 'د پسرلي ټکول یې د خوړو لپاره نه دي بلکې د سیمې د اعلان لپاره چټک ریتم دی.', 'ټول کال؛ د ژمي په پای کې هغه ټکول واورئ چې په ځنګل کې انګازې کوي.', 'ولاړې مړې ونې پرېږدئ، هلته هغه حشرات دي چې پرې ژوند کوي.', 'مړې یا وچېدونکې ونې مه پرېکوئ، ښايي ځالې پکې وي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ps', 'سپین لکۍ‌خوځوونکی', 'د لکۍ دوامداره خوځښت ښايي د ښکاریانو پر وړاندې د هوښیارۍ نښه وي.', 'له پسرلي تر مني د اوبو او خلاصې ځمکې تر څنګ؛ ځغلي او ودریږي چې حشرات ونیسي.', 'د اوبو تر څنګ لنډ واښه یا شګلن ځای وساتئ چې هلته خواړه ولټوي.', 'هغه شګلن غاړې مه ګډوډوئ چې خواړه پکې مومي او ځالې جوړوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ps', 'خړ لکلک', 'د پسرلي په پیل کې د ودې ګډېدنې کوي، ټوپونه وهي او ټیټیږي.', 'له پسرلي تر مني د لندبل ځایونو شاوخوا؛ هغه غږ واورئ چې تر کیلومترونو اوریدل کیږي.', 'د هغو نه‌وچ شویو لندبل ځایونو ساتنه ملاتړ کړئ چې پکې زېږون کوي.', 'د ځالې لندبل ځایونه له لرې وګورئ — ګډوډه شوې ځاله پرېږدي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ps', 'غږیز هنس', 'د ټول عمر لپاره جوړه کوي او راتګ یې په لوړ غږ اعلانوي.', 'په پسرلي او مني کې پر جهیلونو او ډنډو پټیو، ډېری وخت په کورنیو ډلو کې.', 'د جهیلونو د کم‌ژورو غاړو او لندو پټیو ساتنه بې‌وچولو ملاتړ کړئ.', 'هیڅکله ډوډۍ مه ورکوئ — زیان یې رسوي؛ پر یخ هم واټن وساتئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ps', 'شین‌سر هیلۍ', 'بچي یې له زېږېدو څو ساعته وروسته لامبو وهلی او پخپله خوراک کولی شي.', 'ټول کال نږدې په هر ډنډ، جهیل یا ورو سیند کې.', 'که خواړه ورکوئ، د ډوډۍ پرځای جوار، مټر یا تخمونه وکاروئ.', 'په پسرلي کې سپي له هغو اوبو لرې وساتئ چې هیلۍ پکې ځالې جوړوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ps', 'عام باز', 'په پراخو وزرونو الوځي او ډېری وخت د پیشو غږ ته ورته چیغه وهي.', 'له پسرلي تر مني؛ ولټوئ یې چې د پټیو او ځنګل د څنډو پر سر ګرځي.', 'هغه سخت څړځایونه او د پټیو څنډې ملاتړ کړئ چې موږکان پکې اوسیږي.', 'هیڅکله د موږکانو زهر مه کاروئ — د خوړو له سلسلې ښکاري مرغانو ته رسیږي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ps', 'د کب‌نیوونکي عقاب', 'د کب نیولو لپاره لومړی په پښو ټوپ وهي او د خپل وزن نیمايي بار وړي.', 'له پسرلي تر مني د لویو جهیلونو تر څنګ؛ لومړی په هوا کې ودریږي بیا ښکته کیږي.', 'د کبانو بډایه جهیلونو تر څنګ پر لوړو ستنو د ځالې تختو جوړول ملاتړ کړئ.', 'د ځالې تختو څخه ډېر لرې واوسئ چې جوړې خپلې هګۍ پرې نږدي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ps', 'سور ګیدړ', 'د ځمکې مقناطیسي ساحه کاروي چې پر پټ ښکار د ټوپ اندازه وټاکي.', 'ټول کال، تر ټولو فعال سهار او ماښام د ځنګل او پټیو په څنډو کې.', 'یوه ځنګلي او آرامه ګوښه پرېږدئ چې هلته آرام وکړي او سوړه وکیندي.', 'د کثافاتو لوښي وتړئ او هیڅکله زیانمن پاتې خواړه مه پرېږدئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ps', 'اروپايي ځنګلي ژو', 'په یوه شپه کې د خوړو په لټه دوه کیلومتره لاره وهلی شي.', 'له پسرلي تر مني د تیارې وروسته؛ ژمی د پاڼو او لرګیو تر ډېرو لاندې ویده کیږي.', 'په پولې کې ۱۳ سانتي‌متره سوری جوړ کړئ چې د باغونو ترمنځ وګرځي.', 'د لوړو واښو پرېکولو مخکې یې وګورئ او د ژمي خوب لپاره د پاڼو ډېرۍ پرېږدئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ps', 'کوچنی هوسۍ', 'امیندواري ځنډوي چې بچي یې تل د اوړي په پیل کې وزیږي.', 'ټول کال د ځنګل په څنډو کې، تر ټولو ښکاره سهار او ماښام د څرېدو پر مهال.', 'هغه نه‌پرېکړل شوې د پټیو څنډې او بوټي ملاتړ کړئ چې پناه او خواړه ورکوي.', 'د اوړي په پیل کې چې بچي پټ پراته وي، سپي د ځنګل تر څنګ وتړئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ps', 'لوی هوسۍ (موس)', 'په نړۍ کې تر ټولو لوی هوسۍ دی؛ یو غټ نر تر نیم ټنه ډېر وزن لري.', 'ټول کال په ځنګلونو او لندبل ځایونو کې، تر ټولو فعال سهار او ماښام.', 'هغه سره‌تړلي ځنګلونه او د لندبل لارې ملاتړ کړئ چې د ګرځېدو لپاره ورته اړین دي.', 'د ځنګل په لارو کې سهار او ماښام په احتیاط چلوئ او بچي ته هیڅکله مه نږدې کیږئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ps', 'سره لېوه‌ماشه', 'څو ځالې جوړوي او ترمنځ یې بدلیږي.', 'ټول کال په ونو ځنګلونو کې، تر ټولو فعال سهار وختي.', 'هغه مېوې، غوزان او ولاړې ونې پرېږدئ چې خواړه او ځالې پکې لري.', 'سپي پر لار وساتئ او هغه ونې مه ګډوډوئ چې ښايي ځاله پکې وي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ps', 'اروپايي اوبلن ژوی', 'د دوی بندونه لندبل ځایونه جوړوي چې کبان، مرغان او حشرات ډېروي.', 'له پسرلي تر وروستۍ مني د ورو سیندونو شاوخوا، تر ټولو فعال ماښام.', 'ملاتړ وکړئ چې بندونه او د اوبو غاړې ونې پر خپل ځای پاتې شي چیرې چې خوندي وي.', 'له کورونو او بندونو لرې واوسئ، په تېره کله چې بچي وړوکي وي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ps', 'د غرو سوی', 'ژمی یې وړۍ سپینې کیږي چې پر واوره کې پټ شي.', 'ټول کال په خلاصه ځمکه او د ځنګل په ډاګونو کې، ډېری سهار او ماښام.', 'د خلاصې ځمکې او پناه هغه ګډون ملاتړ کړئ چې ټول کال ورته اړین دی.', 'په خلاصه ځمکه سپي وتړئ چې آرام‌کوونکي سوی و نه شړل شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ps', 'اروپايي ګورکن', 'په کورنیو ډلو کې د ځمکې لاندې په هغو سوړو کې ژوند کوي چې نسل په نسل کارول کیږي.', 'له پسرلي تر مني د تیارې وروسته د ځنګل تر څنګ؛ ژمی ویده وي.', 'نه‌ګډوډې غاړې او پولې پرېږدئ چې هلته سوړې وکیندي.', 'فعاله سوړه هیڅکله مه بندوئ او تر څنګ یې مه کیندئ — د دوی دايمي کور دی.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ps', 'کوچنی شپیرک', 'دا وړوکی شپیرک په یوه شپه کې تر ۳۰۰۰ ماشو او مچان خوري.', 'د اوړي په ماښامونو کې د باغونو پر سر چټک او کږلیچ الوتنه یې وګورئ.', 'د شپیرک بکس پر دیوال یا ونه لوړ کېږدئ چې د ماښام لمر ورته ورسیږي.', 'د پناه ځایونو په خولو کې له تېزو رڼاګانو ډډه وکړئ او د شپې آسمان تیاره وساتئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ps', 'کوچنۍ کچوکړۍ‌رنګه پتنګه', 'دا پتنګه لویه شوې ژمی تېروي، ډېری وخت په ګودامونو او د بام په خونو کې.', 'د پسرلي له پیله تر مني پر لمرینو ګلونو، په تېره پر ژرندو.', 'په لمرینه ګوښه کې د ژرندو یوه ټوټه پرېږدئ — چینجیو ته یې اړینه ده.', 'هغه پتنګې چې په ګودامونو کې ژمی ویده وي مه ګډوډوئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ps', 'د طاووس پتنګه', 'د سترګو په څېر داغونه یې مرغان ډاروي او وزرونه یې د خلاصېدو پر مهال غږ کوي.', 'له پسرلي تر مني په لمرینو ورځو کې، پر اغزو او لوېدلو مېوو خوراک کوي.', 'پرېږدئ چې د لمر لاندې د ژرندو ټوټه د چینجیو لپاره وده وکړي.', 'هغه لویې پتنګې مه ګډوډوئ چې ژمی په ګودامونو او د لرګیو ډېرو کې پناه اخلي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ps', 'ګوګړي پتنګه', 'د انګلیسي «butterfly» کلمه ښايي د دې ډول د نر له کوچ‌ژېړ رنګه راغلې وي.', 'د پسرلي له لومړنیو پتنګو څخه ده؛ په ګرمو ورځو کې یې د ځنګل په څنډو ولټوئ.', 'په پولو کې هغه بوټي ملاتړ کړئ چې یوازینی خواړه یې د چینجیو دي.', 'هغه بوټي‌لرونکې پولې مه پاکوئ چې لویې پتنګې ژمی پکې پناه اخلي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ps', 'نارنجي‌څوکه پتنګه', 'یوازې نران د وزرونو نارنجي څوکې لري؛ ښځینه سپینې دي.', 'په پسرلي کې د لندو څړځایونو او لارو تر څنګ چیرې چې ځنګلي ګلونه شنه کیږي.', 'پرېږدئ چې ځنګلي ګلونه په لندو نه‌پرېکړل شویو ګوښو کې وده وکړي.', 'د لارو د څنډو پرېکړه وځنډوئ تر څو چینجي خوراک پای ته ورسوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ps', 'عامه شنه پتنګه', 'میږیان کله ناکله د دې چینجي د خوږو ترشحاتو په بدل کې ساتي.', 'د پسرلي له پایه پر لمرینو څړځایونو چې د شبدر بډایه وي.', 'څړځای مه پرېکوئ چې شبدر ګل وکړي.', 'هغه څړځایونه چې د ځنګلي ګلونو بډایه دي په زهرو مه شیندئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ps', 'شنه‌رګه سپینه پتنګه', 'که څه هم د کرم سپینې پتنګې ته ورته ده، ځنګلي بوټي غوره ګڼي نه د باغ حاصلات.', 'له پسرلي تر وروستي اوړي په لندو څړځایونو، ویالو او د ځنګل په لارو کې.', 'پرېږدئ چې لندې ګوښې په سیمه‌ییزو ځنګلي بوټو ښه شي.', 'هغه لند څړځایونه مه وچوئ او مه شیندئ چې پکې زېږون کوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ps', 'اوه‌ټکیه ګیدړمچ', 'یو ګیدړمچ په ژوند کې زرګونه وړوکي زیانمن حشرات خوري.', 'له پسرلي تر مني پر هغو بوټو چې حشرات پرې وي؛ ژمی ډله‌ییز ویده کیږي.', 'لږ حشرات زغم کړئ او مه شیندئ چې خواړه ولري.', 'تشې ډډې او لوېدلې پاڼې پرېږدئ چې ژمی پکې پناه اخلي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ps', 'ژېړ‌لکۍ غټه شاتمچۍ', 'مېرمنې د پسرلي له لومړنیو مچیو دي، ټیټ ږغیږي او د ځالې سوري لټوي.', 'د پسرلي له پیله تر مني پر ګلونو؛ مېرمنې په پسرلي کې د پولو بېخونه لټوي.', 'هغه بوټي وکرئ یا پرېږدئ چې وختي ګل کوي، او شبدر پرېږدئ چې په واښو کې ګل وکړي.', 'نه‌ګډوډې غاړې او د موږکانو زړې سوړې پرېږدئ چې ډلې پکې ځالې جوړوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ps', 'د شاتو مچۍ', 'لټونکې مچۍ د اتو په بڼه په ګډېدو ځالې ته وايي چې ګلونه چیرې دي.', 'له پسرلي تر مني پر ګلونو په ګرمو او بې‌بادو ورځو کې.', 'پرېږدئ چې بېلابېل ګلونه په ټولو موسمونو کې وشکوفي، او کم‌ژوره د اوبو لوښی کېږدئ.', 'ګل‌شوي بوټي مه شیندئ، او هیڅکله د غرمې په منځ کې مه شیندئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ps', 'امپراتور ښامار‌مچ', 'په اروپا کې تر ټولو غټو څخه دی او ښکار یې حتی په هوا کې نیولی شي.', 'د اوړي په ګرمو ورځو کې وګورئ چې د ډنډونو او جهیلونو پر غاړو ګرځي.', 'د بوټو لرونکی ډنډ وساتئ یا وکیندئ او غاړې یې له بوټو ډکې پرېږدئ.', 'ډنډونه له ککړتیا وساتئ چې بچي یې وده وکړي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ps', 'عام کوچنی ښامار‌مچ', 'ډېری وخت پر هماغه ګرم ځای کښیني او د تېرېدونکو حشراتو نیولو لپاره ټوپ وهي.', 'د اوړي له نیمايي تر مني د ولاړو اوبو تر څنګ، پر لارو او ستنو ځان ګرموي.', 'د ډنډونو او ویالو شاوخوا لمرین د کښېناستو ځایونه او بوټي پرېږدئ.', 'مه پرېږدئ چې سره یا غوړي هغو ډنډونو ته ولاړ شي چې بچي پکې دي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ps', 'د ځنګله سره ميږي', 'د دوی د ځالو غونډۍ تر یو متره لوړې کیدی شي او نیم میلیون میږیان پکې وي.', 'له پسرلي تر مني په ونو ځنګلونو کې؛ د ستنو له پاڼو جوړې ګنبدي غونډۍ ولټوئ.', 'د ځالو غونډۍ لکه څنګه چې دي پرېږدئ — جوړول یې کلونه نیسي.', 'پر لار پاتې شئ او د میږیانو غونډۍ هیڅکله مه ولتړئ او مه کیندئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ps', 'د ځنګله سپین ګل', 'دومره ورو خپریږي چې کثیف فرش یې د ډېر زوړ ځنګل نښه ده.', 'په پسرلي کې د سپینو ګلونو فرش ولټوئ مخکې له دې چې ونې پاڼې وکړي.', 'د ځنګل ځمکه لکه څنګه چې ده پرېږدئ چې ورو خپرېدونکې ریښې وده وکړي.', 'هلته یې خوند واخلئ چې شنه کیږي — شکول هغه ګل لرې کوي چې کلونه یې وخت نیولی.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ps', 'د درې ګل', 'د دې خوشبویه بوټي هره برخه که وخوړل شي زهرجنه ده.', 'د پسرلي په پای کې بوی ورپسې ونیسئ تر سیوري لرونکو ځنګلونو.', 'د ځنګل سیوري لرونکې څنډې او لوېدلې پاڼې پرېږدئ چیرې چې شنه کیږي.', 'مه یې شکوئ او مه یې باسئ؛ له ماشومانو او کورنیو څارویو یې لرې وساتئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ps', 'ځنګلي هوږه', 'ډېری وخت یې بوی مومئ مخکې له دې چې سپین ګلونه یې وګورئ.', 'په پسرلي کې پراخې شنې پاڼې او ستوري‌ډوله ګلونه په لندو ځنګلونو کې ولټوئ.', 'لند ځنګل لکه څنګه چې دی پرېږدئ چې فرشونه یې هر کال بیا وشنه شي.', 'که سیمه‌ییز اجازه وي، لږ واخلئ او هیڅکله ریښې مه باسئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ps', 'د جهيل زرين ګل', 'له تر ټولو زړو سیمه‌ییزو بوټو څخه دی؛ په سکانډینیویا کې یې وروستی یخ دور تېر کړی.', 'په پسرلي کې لوی زرین ګلونه په جهیلونو، ویالو او د ډنډونو غاړو کې ولټوئ.', 'د ډنډونو او ویالو غاړې لندې او نه‌پرېکړل شوې وساتئ چې ګل وکړي.', 'لنده ځمکه مه وچوئ او بوټي پر خپل ځای پرېږدئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ps', 'د پسرلي ژېړ ګل', 'یو وخت په څړځایونو کې دومره ډېر و چې ماشومانو ترې غونډارې جوړولې.', 'په پسرلي کې ټیټ‌شوي ژېړ ګلونه په زړو نه‌بدل شویو څړځایونو کې ولټوئ.', 'څړځایونه مه پرېکوئ تر څو ګل وکړي او تخم ونیسي.', 'له طبیعت یې مه شکوئ او مه باسئ — د څړځای ګلونه کمیږي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ps', 'لوی سپین ګل', 'هغه څه چې یو ګل ښکاري په حقیقت کې لسګونه وړوکي ګلونه یو ځای دي.', 'په اوړي کې لوی سپین ګلونه د لارو په څنډو او څړځایونو کې ولټوئ.', 'د اوړي په منځ کې د واښو یوه پټه نه‌پرېکړل شوې پرېږدئ چې ګل وکړي.', 'د لارو څنډې او څړځایونه په زهرو مه شیندئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ps', 'د زېړ‌ګل واښه', 'د مچیو لپاره له تر ټولو مهمو وختي د شاتو سرچینو څخه دی.', 'له پسرلي وروسته نږدې هر ځای؛ ګلونه یې په لمر کې خلاصیږي او ماښام تړل کیږي.', 'پرېږدئ چې په پسرلي کې د لومړۍ پرېکړې مخکې په واښو کې ګل وکړي.', 'د واښو زهر مه کاروئ چې وختي ګرده‌وړونکي دا مهم خواړه ولري.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ps', 'د بوټو ونه', 'یو بوټی کولی شي له سلو زرو ډېر وړوکي تخمونه ورکړي.', 'د اوړي په پای کې بنفشي فرشونه په خلاصو ډاګونو او جهیلونو کې ولټوئ.', 'ملاتړ وکړئ چې دا سیمې خلاصې او نه‌وچې پاتې شي.', 'پر لارو پاتې شئ او په وچ هوا کې هیڅکله اور مه بلوئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ps', 'ځنګلي شنه توت', 'ګوتې شنې کوي او له مرغانو تر ږیرواتو هر څه ته خواړه ورکوي.', 'په اوړي کې ټیټ بوټي له تورو توتانو سره په ونو ځنګلونو کې ولټوئ.', 'د ځنګل لاندنی بوټي لکه څنګه چې دی پرېږدئ چې مېوه ورکړي.', 'که راټولول اجازه وي، ډېر توتان د ځنګلي ژوند لپاره پرېږدئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ps', 'ځنګلي سور توت', 'د مېوې د طبیعي ساتونکي له امله میاشتې پاتې کیږي.', 'د اوړي په پای او مني کې ځلیدونکي سره توتان پر تلپاتې‌شنو فرشونو ولټوئ.', 'د ځنګل د ځمکې بوټي لکه څنګه چې دي پرېږدئ چې فرشونه خپاره شي.', 'که راټولول اجازه وي، په احتیاط قدم کېږدئ چې بوټي ونه ټکول شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ps', 'سپینه بېرچ ونه', 'یوه ونه سلګونه ډوله حشرات ساتي، هغه هم بې‌شمېره مرغان تغذیه کوي.', 'ټول کال؛ سپینه پوستکی یې په هر موسم کې پېژندل اسانوي.', 'لوېدلې پاڼې او مړ لرګی پرېږدئ چې خاوره بډایه او حشرات تغذیه کړي.', 'پوستکی مه باسئ، ونه ټپي او کمزورې کوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ps', 'د ناروې نښتر', 'په سویډن کې یوه ونه له هغو ریښو زېږي چې زرګونه کاله عمر لري.', 'ټول کال په ځنګلونو کې؛ ځوړند مېوې یې د ټولو نښترونو تر ټولو اوږدې دي.', 'لوېدلې مېوې او مړ لرګی پرېږدئ چې حشراتو او خوځیدونکو ته پناه ورکوي.', 'په ځنګل کې پر لار پاتې شئ چې د ونې کم‌ژورې ریښې ونه فشارول شي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ps', 'د سکاټلنډ سرو', 'زړې ونې پورته نارنجي ځلیږي او پېړۍ ژوند کولی شي.', 'ټول کال په شګلنه او ډبرینه ځمکه؛ پورتنی نارنجي پوستکی ولټوئ.', 'ولاړ مړ لرګی او زړې ونې پرېږدئ، له ژونده ډکې دي.', 'په وچه شګلنه ځمکه کې د ونو تر څنګ هیڅکله اور مه بلوئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ps', 'شمالي پایک کب', 'د کمین ښکاري دی چې له بشپړ سکون څخه په سترګو رپ کې ټوپ وهي.', 'له پسرلي تر مني د جهیلونو او ورو سیندونو په بوټو ډکو کم‌ژورو کې.', 'د نیو کم‌ژورو او اوبو د بوټو ساتنه ملاتړ کړئ چې وړوکي کبان پکې پناه اخلي.', 'ککړتیا او کثافات له اوبو لرې وساتئ؛ د سیمې د کب نیولو قوانین ومنئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ps', 'اروپايي پرچ کب', 'په ډلو ښکار کوي او تیارې کرښې یې د بدن بڼه ماتوي.', 'په ګرمو میاشتو کې د پلونو، د اوبو بوټو او د ژورو غاړو شاوخوا.', 'پاکې اوبه او د اوبو لاندې جوړښتونه ملاتړ کړئ چې وړوکي کبان ساتي.', 'هیڅکله څه شی په جهیلونو او سیندونو کې مه غورځوئ؛ د سیمې قوانین ومنئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ps', 'روچ کب', 'مهم خوراکي کب دی چې ډېری د جهیل ښکاري پرې تکیه کوي.', 'په ګرمو میاشتو کې په ډلو د جهیلونو او ورو سیندونو د سطحې تر څنګ.', 'د اوبو پاکوالی او د غاړو بوټي د زېږون لپاره ملاتړ کړئ.', 'بهېدونکې اوبه او کثافات له اوبو لرې وساتئ؛ د سیمې قوانین ومنئ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'kmr', 'Bezoka asîmanî', 'Dikarin mehan di hewayê de bimînin, heta di firînê de radizên.', 'Di êvarên germ ên havînê de li jor banan binêrin û guh bidin refên qîrîner.', 'Berî ku çûk di biharê de vegerin, qutîyeke hêlînê li bin kêleka banî daynin.', 'Dema hûn malê nû dikin, wan qelîştên biçûk ên bin kêleka banî biparêzin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'kmr', 'Dûmehingiva malê', 'Her sal heta başûrê Afrîkayê koç dikin û vedigerin.', 'Ji biharê heta destpêka payizê, wan li ser zeviyan û avê nizm difirin bibînin.', 'Deriyê axûr an embarê hinekî vekirî bihêlin da ku bigihîjin hêlînên xwe.', 'Hêlînên kevin ên herrî hilneweşînin — dûmehingiv sal bi sal wan dîsa bikar tînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'kmr', 'Pepûk', 'Hêkên xwe di hêlînên çûkên din de datîne û tu carî çêlikên xwe mezin nake.', 'Di dawiya biharê de guh bidin bangê dûr ê "ku-ku" ji kêleka daristanê.', 'Çîmen û perçînên dewlemend ên kêzikan piştgirî bikin ku çûkên mêvandar têr dikin.', 'Li nêzî devî û qamîşan li ser rêyan bimînin da ku çûkên mêvandar neyên aciz kirin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'kmr', 'Sînesor', 'Ji herêma xwe bi hêrs diparêzin û li nêzî çirayên kolanê bi şev jî distirên.', 'Tevahiya salê di bexçe û daristanan de; gelek caran li pey kesê ku axê dikole diçin.', 'Quncikek bexçe bi pelên weşiyayî bihêlin ku li wir xwarinê bigerin.', 'Birrîna giran a perçînê taloq bikin heta hêlîndanîn di dawiya havînê de biqede.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'kmr', 'Refşika reş', 'Stranê dewlemend ê nêr yek ji navdartirînên Ewropayê ye.', 'Tevahiya salê; berbang û êvaran guh bidin nêran ku ji ban û serê daran distirên.', 'Ava taze ji bo vexwarin û şuştinê deynin, nemaze di demên hişkesaliyê de.', 'Di demsala hêlînê de pisîkan berbangê li malê bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'kmr', 'Refşika zeviyan', 'Çûkeke civakî ye ku zivistanê bi refên dengbilind digere.', 'Di payiz û zivistanê de bibînin ka ref çawa berên perçîn û daran datînin.', 'Devîyên berdar di tevahiya zivistanê de nebirrin.', 'Sêvên weşiyayî zivistanê li erdê bihêlin — di sermayê de xwarineke girîng in.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'kmr', 'Baziyê mezin', 'Dengên wan pir cûre ne û yên nû ji cîranan hîn dibin.', 'Tevahiya salê; ji dawiya zivistanê guh bidin stranê zeng û dubarekirî.', 'Qutîyeke hêlînê bi qulika 32 mm li ciyekî bêdeng û siyê daliqînin.', 'Ji jehrên bexçe dûr bisekinin da ku têra çêlikan kurm bimîne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'kmr', 'Baziyê şîn', 'Çêlikên hêlîneke bi tenê dikarin ji hezar kurman zêdetir bixwin.', 'Tevahiya salê di bexçe û daristanan de, gelek caran ji şaxên zirav berevajî daliqîne.', 'Qutîyeke biçûk bi qulika 25 mm dûrî bayê serdest deynin.', 'Di biharê de jehra kêzikan bikar neynin da ku kurm ji bo çêlikan hebin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'kmr', 'Çivîka daran', 'Stranên wan ji herêmê bi herêmê diguhere, hema wek zaravayên herêmî.', 'Ji biharê heta payizê; nêr ji ciyên vekirî hevokeke ronî ya dadikeve distirên.', 'Hin serên tovê û qadên çîmenî di tevahiya demsalê de rawestandî bihêlin.', 'Ciyên xwarinê paqij bihêlin da ku nexweşî di nav çûkan de belav nebe.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'kmr', 'Qijika berû', 'Her payiz hezaran berû vedişêrin û bi jibîrkirina hinan daristanên berû diçînin.', 'Tevahiya salê di daristanên berû de; payizê li şewqên pembe û şîn binêrin.', 'Berûyên weşiyayî û pelên bin daran wek xwe bihêlin.', 'Kûçikan di daristanê de li ser rê bihêlin da ku çûkên li erdê xwarindar netirsin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'kmr', 'Darkutkê xaldar', 'Lêdana biharê ne ji bo xwarinê ye, lê ritmeke bilez e ku herêma xwe diyar dike.', 'Tevahiya salê; di dawiya zivistanê de guh bidin lêdanê ku di daristanê de deng vedide.', 'Daran mirî yên rawestandî bihêlin, kêzikên ku pê xwarinê dixwin li wir dijîn.', 'Darên mirî an ziwabûyî nebirrin, dibe ku hêlîn tê de hebin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'kmr', 'Dûvhejîna spî', 'Hejandina berdewam a dûvê dibe ku nîşana hişyariyê li hember nêçîrvanan be.', 'Ji biharê heta payizê li nêzî avê û erdê vekirî; dibeze û radiweste da kêzikan bigire.', 'Li nêzî avê perçeyek çîmenê kurt an xîzê bihêlin ku li wir xwarinê bigere.', 'Keviyên xîzî yên ku lê dixwe û hêlînê datîne aciz nekin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'kmr', 'Qulingê gewr', 'Di destpêka biharê de bi bazdan û tewandinê dîlanên zewacê dikin.', 'Ji biharê heta payizê li dor avzêman; guh bidin bangê ku bi kîlometreyan tê bihîstin.', 'Parastina genav û çîmenên şil ên ne-ziwakirî piştgirî bikin ku lê zêde dibin.', 'Avzêmên hêlînê ji dûr ve temaşe bikin — hêlîna aciz dihêlin û diçin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'kmr', 'Qûyê dengbêj', 'Ji bo tevahiya jiyanê cot dibin û hatina xwe bi bangên bilind diyar dikin.', 'Di bihar û payizê de li gol û zeviyên avdayî, gelek caran bi komên malbatî.', 'Parastina keviyên hûr ên golan û zeviyên şil bêyî ziwakirin piştgirî bikin.', 'Tu carî nan nedin — zirarê dide wan; li ser qeşayê jî dûrahiyê biparêzin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'kmr', 'Werdeka serkesk', 'Çêlik çend saetan piştî derketinê dikarin avjenî bikin û bi xwe bixwin.', 'Tevahiya salê hema li her golik, gol an çemê hêdî.', 'Heke xwarinê didin, li şûna nan garis, polik an tovan bikar bînin.', 'Di biharê de kûçikan ji ava ku werdek lê hêlîn datînin dûr bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'kmr', 'Elîhê asayî', 'Bi baskên fireh difire û gelek caran bi dengekî wek mîyawa pisîkê dixwîne.', 'Ji biharê heta payizê; li wan bigerin ku li jor zeviyan û kêleka daristanê dizivirin.', 'Çîmenên hişk û keviyên zeviyan piştgirî bikin ku mişkên zeviyan lê dijîn.', 'Tu carî jehra mişkan bikar neynin — bi zincîra xwarinê digihîje çûkên nêçîrvan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'kmr', 'Elîhê masîgir', 'Ji bo girtina masî pêşî bi pêyan diherike û nêçîra nîvê giraniya xwe hildigire.', 'Ji biharê heta payizê li nêzî golên mezin; pêşî li hewayê radiweste paşê dadikeve.', 'Danîna platformên hêlînê li ser stûnên bilind li nêzî golên masîdar piştgirî bikin.', 'Ji platformên hêlînê pir dûr bimînin da ku cot hêkên xwe nehêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'kmr', 'Rovîyê sor', 'Rovî qada magnetîsî ya Erdê bikar tînin da ku bazdana li ser nêçîra veşartî bipîvin.', 'Tevahiya salê, herî çalak berbang û êvaran li kêleka daristan û zeviyan.', 'Quncikeke kovî û bêdeng bihêlin ku lê bêhna xwe vedin û qulik bikolin.', 'Bidonên çopê bigirin û tu carî bermahiyên xwarinê yên zirardar nehêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'kmr', 'Jîjoka ewropî', 'Jîjok dikare di şevekê de li pey xwarinê çend kîlometreyan bimeşe.', 'Ji biharê heta payizê piştî tariyê; zivistanê di bin kom pel û darikan de radizê.', 'Di perçînê de qulikeke 13 cm veke da ku jîjok di navbera bexçeyan de bigerin.', 'Berî birrîna çîmenê bilind lê binêrin û komên pelan ji bo xewa zivistanê bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'kmr', 'Xezala biçûk', 'Ducaniyê taloq dikin da ku çêlik her dem di destpêka havînê de bên dinyayê.', 'Tevahiya salê li kêleka daristanan, herî xuya dema çêrê berbang û êvaran.', 'Keviyên nebirrî yên zeviyan û devîyan piştgirî bikin ku stargeh û xwarin didin.', 'Di destpêka havînê de, dema çêlik veşartî radizin, kûçikan li nêzî daristanê girêdin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'kmr', 'Gakûvîyê mezin (mûs)', 'Mezintirîn gakûvî ya cîhanê ye; nêrekî mezin ji nîv tonê zêdetir e.', 'Tevahiya salê di daristan û avzêman de, herî çalak berbang û êvaran.', 'Daristanên girêdayî û rêyên avzêm piştgirî bikin ku ji bo geriyanê pêwîst in.', 'Li rêyên daristanê berbang û êvaran bi baldarî ajotinê bikin û nêzî çêlikekê nebin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'kmr', 'Sivorê sor', 'Çend hêlînan çêdikin û di navbera wan de diguherin.', 'Tevahiya salê di daristanên darqozî û tevlihev de, herî çalak sibehê zû.', 'Kozik, gûz û darên rawestandî bihêlin ku lê dixwin û hêlînê datînin.', 'Kûçikan li ser rê bihêlin û darên ku dibe hêlîn tê de hebin aciz nekin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'kmr', 'Sagoka ewropî', 'Bendên wan avzêman çêdikin ku bi kîlometreyan masî, çûk û kêzikan zêde dikin.', 'Ji biharê heta dawiya payizê li dor çemên hêdî, herî çalak êvarê.', 'Man a bend û darên kêleka avê li cihê ewle piştgirî bikin.', 'Ji hêlîn û bendan dûr bimînin, nemaze dema çêlik biçûk in.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'kmr', 'Kerguhê çiyê', 'Zivistanê spî dibin da ku li ser berfê xwe veşêrin.', 'Tevahiya salê li erdê vekirî û valahiyên daristanê, bi giranî berbang û êvaran.', 'Tevliheviya erdê vekirî û stargehê piştgirî bikin ku bi salê pêwîst e.', 'Li erdê vekirî kûçikan girêdin da ku kerguhên bêhnvedanê neyên qewitandin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'kmr', 'Gurbeşkê ewropî', 'Bi komên malbatî di qulikên bin erdê de dijîn ku bi nifşan tên bikaranîn.', 'Ji biharê heta payizê piştî tariyê li nêzî daristanê; zivistanê radizin.', 'Kevî û perçînên ne-aciz bihêlin ku lê qulikan bikolin.', 'Qulikeke çalak tu carî negirin û li nêzî wê nekolin — mala wan a domdar e.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'kmr', 'Şevşevoka biçûk', 'Ev şevşevoka biçûk dikare di şevekê de heta 3.000 mêş û pêşûyan bixwe.', 'Di êvarên havînê de firîna bilez û xwar li ser bexçeyan temaşe bikin.', 'Qutîyeke şevşevokê bilind li dîwar an darekê daynin ku tava êvarê digire.', 'Ji ronahiya tûj li deriyên stargehê dûr bisekinin û asîmanê şevê tarî bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'kmr', 'Perperoka kûsîreng a biçûk', 'Ev perperok wek mezin zivistanê derbas dike, gelek caran di embar û ban de.', 'Ji destpêka biharê heta payizê li ser kulîlkên tavî, nemaze gezgezk.', 'Perçeyek gezgezkê li quncikeke tavî bihêlin — kurmên wê hewce ne.', 'Perperokên ku di embaran de radizin di tevahiya zivistanê de aciz nekin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'kmr', 'Perperoka tawis', 'Lekeyên wek çav çûkan ditirsînin û bask dema vedibin dikarin dengê fişînê derxin.', 'Ji biharê heta payizê di rojên tavî de, li ser stirî û fêkiyên weşiyayî dixwe.', 'Bihêlin perçeyek gezgezkê ya tavî ji bo kurmên wê mezin bibe.', 'Yên mezin ên ku zivistanê di embar û komên daran de xwe vedişêrin aciz nekin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'kmr', 'Perperoka kewkurtî', 'Peyva îngilîzî ya perperokê dibe ku ji rengê zer ê nêrê vî cureyî hatibe.', 'Yek ji perperokên pêşî yên biharê; di rojên germ de li kêleka daristanan bigerin.', 'Devîyên perçînê piştgirî bikin, tenê riwekên ku kurmên wê dixwin.', 'Perçînên devîdar paqij nekin ku yên mezin zivistanê tê de xwe diparêzin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'kmr', 'Perperoka serpirteqal', 'Tenê nêr serê baskên pirteqalî yên geş hene; mê spî ne.', 'Di biharê de li kêleka çîmenên şil û rêyan ku kulîlkên kovî lê şîn dibin.', 'Bihêlin kulîlkên kovî li quncikên şil û nebirrî mezin bibin.', 'Birrîna keviyên rê taloq bikin heta kurm xwarina xwe biqedînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'kmr', 'Perperoka şîn a asayî', 'Mûrî carinan kurmên wê ji ber şileyên şîrîn ên wan diparêzin.', 'Ji dawiya biharê li çîmenên tavî yên dewlemend ên nîskê.', 'Çîmen nebirrin da ku nîsk bikaribin kulîlk bidin.', 'Çîmenên dewlemend ên kulîlkên kovî bi jehra pelan neşilînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'kmr', 'Perperoka spî ya damarkesk', 'Her çend dişibe perperoka kelemê jî, riwekên kovî ji berhemên bexçe çêtir dibîne.', 'Ji biharê heta dawiya havînê li çîmenên şil, kanal û rêyên daristanê.', 'Bihêlin quncikên şil bi riwekên herêmî yên kovî werin.', 'Çîmenên şil ên ku lê zêde dibe ziwa nekin û neşilînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'kmr', 'Kêzika heftxal', 'Kêzikek dikare di jiyana xwe de hezaran kêzikên biçûk ên zirardar bixwe.', 'Ji biharê heta payizê li ser riwekên bi kêzik; zivistanê bi kom radizin.', 'Hinek kêzikan tehemûl bikin û neşilînin da ku xwarina wan hebe.', 'Qedên vala û pelên weşiyayî bihêlin ku zivistanê tê de xwe diparêzin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'kmr', 'Mêşa mezin a dûvzer', 'Şahbanû ji mêşên pêşî yên biharê ne, nizm dizûrin û li qulikên hêlînê digerin.', 'Ji destpêka biharê heta payizê li ser kulîlkan; şahbanû biharê binê perçînan digerin.', 'Riwekên zû-kulîlkdar biçînin an bihêlin û bihêlin nîsk di çîmen de kulîlk bide.', 'Kevî û qulikên kevin ên mişkan bihêlin ku kolonî tê de hêlînê datînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'kmr', 'Mêşa hingiv', 'Mêşa gerok bi dîlanek bi şiklê heştê ji koçikê re dibêje kulîlk li ku ne.', 'Ji biharê heta payizê li ser kulîlkan di rojên germ û bêba de.', 'Bihêlin kulîlkên cûrbecûr di demsalan de vebin û tasek ava hûr deynin.', 'Riwekên kulîlkdar neşilînin û tu carî nîvro neşilînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'kmr', 'Mêşhingivê împerator', 'Yek ji mezintirînên Ewropayê ye û dikare nêçîrê di hewayê de jî bigire.', 'Di rojên germ ên havînê de bibînin ka çawa li golik û keviyên golan digere.', 'Golikeke bi riwek biparêzin an bikolin û keviyên wê bi riwek bihêlin.', 'Golikan ji qirêjiyê biparêzin da ku çêlik pêş ve biçin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'kmr', 'Mêşhingivê biçûk ê asayî', 'Gelek caran li ser heman cihê germ rûdine û ji bo girtina kêzikên derbasbûyî difire.', 'Ji nîvê havînê heta payizê li nêzî ava rawestayî, li ser rê û stûnan xwe germ dike.', 'Ciyên tavî yên rûniştinê û riwekan li dora golik û kanalan bihêlin.', 'Nehêlin gubre an rûn bikeve golikên ku çêlik tê de dijîn.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'kmr', 'Mûriya sor a daristanê', 'Girên hêlînên wan dikarin ji metreyekê bilindtir bin û nîv mîlyon mûriyan bihewînin.', 'Ji biharê heta payizê di daristanên darqozî de; li girên gumbazî yên derziyan bigerin.', 'Girên hêlînê wek xwe bihêlin — avakirina wan salan digire.', 'Li ser rê bimînin û tu carî li girê mûriyan nexin û nekolin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'kmr', 'Gula spî ya daristanê', 'Ewqas hêdî belav dibe ku bergên qalind nîşana daristaneke pir kevn in.', 'Di biharê de berî ku dar pel bidin li bergên kulîlkên spî bigerin.', 'Erdê daristanê wek xwe bihêlin da ku rehên hêdî-belavbûyî mezin bibin.', 'Li cihê ku şîn dibin jê kêf bikin — çinîn kulîlkek ku salan girtiye ji holê radike.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'kmr', 'Gula gelî', 'Her perçeyek vê riweka bîhnxweş heke bê xwarin jehrî ye.', 'Di dawiya biharê de li pey bîhnê biçin daristanên siyê.', 'Keviyên siyê yên daristanê û pelên weşiyayî bihêlin ku lê şîn dibe.', 'Neçinin û ranekin; ji zarok û heywanên malê dûr bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'kmr', 'Sîrê kovî', 'Gelek caran bîhna sîrê kovî distînin berî ku kulîlkên spî bibînin.', 'Di biharê de li pelên fireh ên kesk û kulîlkên stêrkî li daristanên şil bigerin.', 'Daristana şil wek xwe bihêlin da ku berg her sal dîsa şîn bibin.', 'Heke berhevkirin li herêmê destûr be, hindik bigirin û tu carî bêkokan ranekin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'kmr', 'Gula zêrîn a genavê', 'Yek ji riwekên herêmî yên herî kevn e; li Skandînavyayê serdema qeşayê ya dawî derbas kiriye.', 'Di biharê de li kulîlkên mezin ên zêrîn li genav, kanal û keviyên golikan bigerin.', 'Keviyên golik û kanalan şil û nebirrî bihêlin da ku kulîlk bide.', 'Erdê şil ziwa nekin û riwekan li cihê ku şîn dibin bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'kmr', 'Gula bihara zer', 'Carekê li çîmenan ewqas gelemperî bûn ku zarokan jê gogan çêdikirin.', 'Di biharê de li kulîlkên zer ên daleqandî li çîmenên kevn bigerin.', 'Çîmenan nebirrin heta kulîlk bidin û tovê xwe girêdin.', 'Ji xwezayê neçinin û ranekin — kulîlkên çîmenan kêm dibin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'kmr', 'Beybûna mezin', 'Ya ku wek kulîlkek xuya dike bi rastî dehan kulîlkên hûr in bi hev re.', 'Di havînê de li beybûnên spî yên mezin li kêleka rê û çîmenan bigerin.', 'Rêzeyek çîmen di nîvê havînê de nebirrî bihêlin da ku kulîlk bide.', 'Keviyên rê û çîmenan bi jehra pelan neşilînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'kmr', 'Gulzêrk', 'Yek ji çavkaniyên herî girîng ên hingivê zû ji bo mêşan e.', 'Ji biharê pê ve hema li her derê; kulîlk di tavê de vedibin û êvarê digirin.', 'Bihêlin di biharê de berî birrîna yekem li çîmen kulîlk bidin.', 'Jehra çîmen bikar neynin da ku tozvekerên zû vê xwarina girîng biparêzin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'kmr', 'Devîya çiyê', 'Riwekek tenê dikare ji sed hezar tovên hûr zêdetir çêbike.', 'Di dawiya havînê de li bergên binefşî li deştên vekirî û genavan bigerin.', 'Piştgirî bikin ku ev herêm vekirî û ne-ziwakirî bimînin.', 'Li ser rê bimînin û di hewaya hişk de tu carî agir venexin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'kmr', 'Tûya şîn a kovî', 'Tiliyan şîn dike û ji çûkan heta hirçan her tiştî têr dike.', 'Di havînê de li devîyên nizm bi berên tarî li daristanên çam û kajê bigerin.', 'Riwekên bin daristanê wek xwe bihêlin da ku devî ber bidin.', 'Heke berhevkirin destûr be, gelek beran ji bo jiyana kovî bihêlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'kmr', 'Tûya sor a kovî', 'Bi saya parêzerekî xwezayî di berî de mehan dimîne.', 'Di dawiya havîn û payizê de li berên sor ên biriqî li ser bergên hergav-kesk bigerin.', 'Riwekên erdê daristanê wek xwe bihêlin da ku berg belav bibin.', 'Heke berhevkirin destûr be, bi baldarî pê deynin da ku riwek neyên pelçiqandin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'kmr', 'Dara bejna zîvîn', 'Darek sedan cureyên kêzikan têr dike, ew jî bêhejmar çûkan têr dikin.', 'Tevahiya salê; qalikê spî yê ku diqeşire nasîna wê di her demsalê de hêsan dike.', 'Pelên weşiyayî û darê mirî bihêlin da ku axê dewlemend bikin û kêzikan têr bikin.', 'Qalik ranekin, darê birîndar û qels dike.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'kmr', 'Dara kajê ya Norwêcê', 'Darek li Swêdê ji rehên bi hezaran salan kevn şîn dibe.', 'Tevahiya salê di daristanan de; kozikên wê yên daliqandî ji hemûyan dirêjtir in.', 'Kozikên weşiyayî û darê mirî bihêlin ku stargeha kêzik û kivarkan in.', 'Di daristanê de li ser rê bimînin da ku rehên hûr ên darê neyên pelçiqandin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'kmr', 'Dara çamê ya Skotlandê', 'Darên kevn li jorê pirteqalî diçirisin û dikarin sedsalan bijîn.', 'Tevahiya salê li erdê xîzî û keviran; li qalikê pirteqalî yê jorîn bigerin.', 'Darê mirî yê rawestandî û darên kevn bihêlin, dewlemendî jiyanê ne.', 'Li erdê xîzî yê hişk li nêzî daran tu carî agir venexin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'kmr', 'Masîyê pîk ê bakur', 'Nêçîrvanekî xefkê ye ku ji bêdengiyê di çav vekirinê de diherike.', 'Ji biharê heta payizê li hûrahiyên çîmenî yên gol û çemên hêdî.', 'Parastina hûrahiyên qamîşî û riwekên avê piştgirî bikin ku masiyên biçûk lê dimînin.', 'Qirêjî û çopê ji avê dûr bihêlin; qaîdeyên masîgirtinê yên herêmî bişopînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'kmr', 'Masîyê perç ê ewropî', 'Bi kom nêçîrê dikin û xêzên wan ên tarî şiklê laşê wan dişikînin.', 'Di mehên germ de li dor pir, riwekên avê û keviyên kûr.', 'Ava paqij û avahiyên bin avê piştgirî bikin ku masiyên biçûk diparêzin.', 'Tu carî tiştekî nefirînin nav gol û çeman; qaîdeyên herêmî bişopînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'kmr', 'Masîyê roç', 'Masiyekî xwarinê yê sereke ye ku gelek nêçîrvanên golan pê ve girêdayî ne.', 'Di mehên germ de bi kom li nêzî rûyê gol û çemên hêdî.', 'Paqijiya avê û keviyên bi riwek ji bo hêkdanînê piştgirî bikin.', 'Ava herikî û çopê ji avê dûr bihêlin; qaîdeyên herêmî bişopînin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'th', 'นกแอ่นตึกยุโรป', 'นกแอ่นอยู่กลางอากาศได้ติดต่อกันหลายเดือน แม้แต่หลับขณะบิน', 'ในเย็นอบอุ่นของฤดูร้อน มองสูงเหนือหลังคาและฟังเสียงฝูงที่ร้องแหลม', 'ติดกล่องรังใต้ชายคาก่อนนกจะกลับมาในฤดูใบไม้ผลิ', 'เมื่อซ่อมแซมบ้าน จงรักษาช่องเล็ก ๆ ใต้ชายคาที่นกใช้ทำรัง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'th', 'นกนางแอ่นบ้าน', 'นกนางแอ่นบ้านอพยพไกลถึงแอฟริกาตอนใต้แล้วกลับมาทุกปี', 'ตั้งแต่ฤดูใบไม้ผลิถึงต้นฤดูใบไม้ร่วง มองหาพวกมันบินต่ำเหนือทุ่งและผืนน้ำ', 'เปิดประตูโรงนาหรือเพิงไว้แง้ม ๆ เพื่อให้เข้าถึงชั้นวางรังได้', 'อย่ารื้อรังดินเก่า — นกนางแอ่นใช้ซ้ำปีแล้วปีเล่า') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'th', 'นกคัคคูยุโรป', 'นกคัคคูวางไข่ในรังนกชนิดอื่นและไม่เคยเลี้ยงลูกของตนเอง', 'ปลายฤดูใบไม้ผลิ ฟังเสียง "คุก-คู" ที่ดังไกลจากชายป่า', 'สนับสนุนทุ่งหญ้าและแนวพุ่มที่อุดมด้วยแมลงซึ่งเลี้ยงนกเจ้าบ้าน', 'เดินตามทางเดินใกล้พุ่มไม้และดงกก เพื่อไม่รบกวนนกเจ้าบ้าน') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'th', 'นกโรบินอกแดง', 'นกโรบินหวงถิ่นอย่างดุดัน และร้องเพลงข้ามคืนใกล้ไฟถนน', 'ตลอดปีในสวนและป่า มักตามคนที่ขุดดินโดยหวังจะได้ไส้เดือน', 'เว้นมุมสวนที่มีใบไม้ร่วงทับถมไว้ให้นกคุ้ยหาอาหาร', 'เลื่อนการตัดแต่งแนวพุ่มหนัก ๆ ไปจนพ้นฤดูทำรังปลายฤดูร้อน') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'th', 'นกเบลิร์ดดำ', 'เสียงเพลงนุ่มลึกคล้ายขลุ่ยของตัวผู้เป็นหนึ่งในเสียงที่คุ้นหูที่สุดในยุโรป', 'ตลอดปี ฟังตัวผู้ร้องจากหลังคาและยอดไม้ยามรุ่งสางและพลบค่ำ', 'วางน้ำสะอาดให้ดื่มและอาบ โดยเฉพาะช่วงแล้ง', 'ในฤดูทำรัง ให้แมวอยู่ในบ้านช่วงรุ่งสาง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'th', 'นกเดินดงทุ่ง', 'เป็นนกเดินดงที่อยู่รวมฝูง ฤดูหนาวเร่ร่อนเป็นฝูงส่งเสียงเจี๊ยวจ๊าว', 'ฤดูใบไม้ร่วงและฤดูหนาว ดูฝูงนกเก็บผลเบอร์รีจากแนวพุ่มและต้นไม้', 'อย่าตัดแต่งพุ่มที่มีผลเบอร์รีตลอดฤดูหนาว', 'ปล่อยแอปเปิลที่ร่วงไว้บนพื้นในฤดูหนาว — เป็นอาหารสำคัญยามอากาศเย็น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'th', 'นกติ๊ดใหญ่', 'มีคลังเสียงมากมายและเรียนรู้เสียงใหม่จากเพื่อนบ้าน', 'ตลอดปี ตั้งแต่ปลายฤดูหนาวฟังเสียงเพลงกังวานที่ร้องซ้ำ ๆ', 'แขวนกล่องรังรูขนาด 32 มม. ในที่เงียบและร่มรื่น', 'เลี่ยงยาฆ่าแมลงในสวน เพื่อให้มีหนอนพอเลี้ยงลูกนก') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'th', 'นกติ๊ดสีฟ้า', 'ลูกนกชุดเดียวกินหนอนผีเสื้อได้มากกว่าหนึ่งพันตัว', 'ตลอดปีในสวนและป่า มักห้อยหัวลงจากกิ่งเล็ก ๆ', 'ติดกล่องรังเล็กรูขนาด 25 มม. ให้พ้นทิศทางลมประจำ', 'งดยาฆ่าแมลงในฤดูใบไม้ผลิ เพื่อให้ลูกนกมีหนอนกิน') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'th', 'นกแชฟฟินช์', 'เสียงเพลงต่างกันไปตามท้องถิ่น เกือบเหมือนสำเนียงประจำถิ่น', 'ฤดูใบไม้ผลิถึงฤดูใบไม้ร่วง ตัวผู้ร้องวลีสดใสไล่เสียงลงจากคอนโล่ง', 'ปล่อยช่อเมล็ดและหย่อมหญ้าบางส่วนยืนต้นไว้ตลอดฤดู', 'ทำความสะอาดที่ให้อาหารนกเสมอ เพื่อไม่ให้โรคระบาดในหมู่นก') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'th', 'นกเจย์ยูเรเชีย', 'ทุกฤดูใบไม้ร่วงมันฝังลูกโอ๊กนับพัน และการลืมบางส่วนทำให้เกิดป่าโอ๊กทั้งผืน', 'ตลอดปีในป่าโอ๊ก ฤดูใบไม้ร่วงคอยสังเกตแวบสีชมพูและน้ำเงิน', 'ปล่อยลูกโอ๊กที่ร่วงและใบไม้ใต้ต้นโอ๊กไว้ตามเดิม', 'จูงสุนัขให้อยู่บนทางเดินในป่า เพื่อไม่ให้นกที่หากินบนพื้นตกใจบินหนี') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'th', 'นกหัวขวานลายจุดใหญ่', 'เสียงรัวในฤดูใบไม้ผลิไม่ใช่การหาอาหาร แต่เป็นจังหวะเร็วเพื่อประกาศอาณาเขต', 'ตลอดปี ปลายฤดูหนาวฟังเสียงรัวก้องไปทั่วป่า', 'ปล่อยไม้ยืนต้นที่ตายแล้วไว้ เพราะมีแมลงที่มันกินอาศัยอยู่', 'อย่าโค่นต้นไม้ที่ตายหรือกำลังโทรม อาจมีโพรงรังอยู่') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'th', 'นกกระเต็นหางกระดกขาว', 'การกระดกหางไม่หยุดอาจเป็นสัญญาณความตื่นตัวต่อผู้ล่า', 'ฤดูใบไม้ผลิถึงฤดูใบไม้ร่วงใกล้น้ำและพื้นโล่ง วิ่งแล้วหยุดเพื่อฉวยแมลง', 'รักษาหย่อมหญ้าสั้นหรือกรวดใกล้น้ำไว้ให้มันหากิน', 'อย่ารบกวนชายฝั่งกรวดที่มันหากินและทำรัง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'th', 'นกกระเรียนสีเทา', 'ต้นฤดูใบไม้ผลิ นกกระเรียนเต้นเกี้ยวพาราสีด้วยการกระโดดและโค้งคำนับ', 'ฤดูใบไม้ผลิถึงฤดูใบไม้ร่วงรอบพื้นที่ชุ่มน้ำ ฟังเสียงร้องคล้ายแตรที่ดังไกลหลายกิโลเมตร', 'สนับสนุนการรักษาพรุและทุ่งชื้นที่ไม่ถูกระบายน้ำ ซึ่งเป็นที่ผสมพันธุ์', 'ดูพื้นที่ชุ่มน้ำที่ทำรังจากระยะไกล — หากถูกรบกวนนกจะทิ้งรัง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'th', 'หงส์เสียงแตร', 'จับคู่กันตลอดชีวิตและประกาศการมาถึงด้วยเสียงร้องดังคล้ายแตร', 'ฤดูใบไม้ผลิและใบไม้ร่วงบนทะเลสาบและทุ่งน้ำท่วม มักมาเป็นกลุ่มครอบครัว', 'สนับสนุนการรักษาริมทะเลสาบตื้นและทุ่งชื้นไม่ให้ถูกระบายน้ำ', 'อย่าให้ขนมปังแก่หงส์เด็ดขาด — เป็นอันตราย และบนน้ำแข็งก็ควรเว้นระยะ') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'th', 'เป็ดหัวเขียว', 'ลูกเป็ดว่ายน้ำและหากินเองได้ภายในไม่กี่ชั่วโมงหลังฟักออกจากไข่', 'ตลอดปีในบ่อ ทะเลสาบ หรือแม่น้ำไหลช้าแทบทุกแห่ง', 'หากให้อาหารเป็ด ใช้ข้าวโอ๊ต ถั่ว หรือเมล็ดพืชแทนขนมปัง', 'ฤดูใบไม้ผลิ อย่าให้สุนัขลงน้ำบริเวณที่เป็ดทำรัง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'th', 'เหยี่ยวบัซซาร์ด', 'ร่อนด้วยปีกกว้างและมักส่งเสียงร้องคล้ายเสียงแมว', 'ฤดูใบไม้ผลิถึงใบไม้ร่วง มองหามันวนสูงเหนือทุ่งและชายป่า', 'สนับสนุนทุ่งหญ้ารกและขอบทุ่งที่มีหนูนาและเหยื่อขนาดเล็กอาศัย', 'อย่าใช้ยาเบื่อหนูเด็ดขาด เพราะไล่ขึ้นห่วงโซ่อาหารไปถึงนกล่าเหยื่อ') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'th', 'เหยี่ยวออสเปรย์', 'พุ่งลงน้ำด้วยเท้าก่อนเพื่อจับปลา และแบกเหยื่อหนักครึ่งหนึ่งของตัวเองได้', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงใกล้ทะเลสาบใหญ่ ลอยนิ่งกลางอากาศแล้วดิ่งลง', 'สนับสนุนการตั้งแท่นรังบนเสาสูงใกล้ทะเลสาบที่มีปลาชุกชุม', 'เว้นระยะห่างจากแท่นรังมาก ๆ เพื่อไม่ให้คู่นกทิ้งไข่') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'th', 'สุนัขจิ้งจอกแดง', 'สุนัขจิ้งจอกใช้สนามแม่เหล็กโลกช่วยกะระยะกระโจนใส่เหยื่อที่ซ่อนอยู่', 'ตลอดปี ตื่นตัวที่สุดยามรุ่งสางและพลบค่ำตามชายป่าและขอบทุ่ง', 'เว้นมุมรกเงียบ ๆ ไว้ให้มันพักและขุดโพรง', 'ปิดถังขยะให้แน่นและอย่าทิ้งเศษอาหารที่เป็นอันตรายไว้ให้') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'th', 'เม่นแคระยุโรป', 'เม่นแคระเดินหาอาหารได้ราวสองกิโลเมตรในคืนเดียว', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงหลังมืดค่ำ ฤดูหนาวจำศีลใต้กองใบไม้และท่อนไม้', 'เจาะช่องกว้าง 13 ซม. ในรั้ว เพื่อให้เม่นเดินข้ามระหว่างสวนได้', 'ตรวจหญ้าสูงก่อนตัด และเว้นกองใบไม้ไว้สำหรับการจำศีล') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'th', 'กวางโร', 'กวางโรชะลอการตั้งท้องเพื่อให้ลูกเกิดต้นฤดูร้อนเสมอ', 'ตลอดปีตามชายป่า เห็นชัดที่สุดขณะแทะเล็มยามรุ่งสางและพลบค่ำ', 'สนับสนุนขอบทุ่งที่ไม่ถูกตัดและพุ่มไม้ที่ให้ที่กำบังและอาหาร', 'ต้นฤดูร้อนที่ลูกกวางนอนซ่อน ให้จูงสุนัขด้วยสายจูงใกล้ป่า') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'th', 'กวางมูส', 'กวางมูสเป็นกวางที่ใหญ่ที่สุดในโลก ตัวผู้ใหญ่หนักเกินครึ่งตัน', 'ตลอดปีในป่าและพื้นที่ชุ่มน้ำ ตื่นตัวที่สุดยามรุ่งสางและพลบค่ำ', 'สนับสนุนผืนป่าที่เชื่อมต่อกันและแนวพื้นที่ชุ่มน้ำที่มันต้องใช้เดินทาง', 'ขับรถอย่างระวังบนถนนป่ายามรุ่งสางและพลบค่ำ และอย่าเข้าใกล้ลูกกวาง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'th', 'กระรอกแดง', 'กระรอกแดงสร้างรังหลายรังและย้ายไปมาระหว่างรัง', 'ตลอดปีในป่าสนและป่าผสม คึกคักที่สุดตอนเช้าตรู่', 'ปล่อยลูกสน ถั่วเปลือกแข็ง และต้นไม้ยืนต้นที่มันกินและทำรังไว้', 'จูงสุนัขบนทางเดินและอย่ารบกวนต้นไม้ที่อาจมีรังอยู่') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'th', 'บีเวอร์ยุโรป', 'เขื่อนบีเวอร์สร้างพื้นที่ชุ่มน้ำที่เพิ่มปลา นก และแมลงไปหลายกิโลเมตร', 'ฤดูใบไม้ผลิถึงปลายใบไม้ร่วงรอบแม่น้ำไหลช้า ตื่นตัวที่สุดยามพลบค่ำ', 'สนับสนุนการปล่อยเขื่อนบีเวอร์และต้นไม้ริมน้ำไว้ตามเดิมในที่ที่ปลอดภัย', 'อยู่ห่างจากรังและเขื่อน โดยเฉพาะเมื่อลูกยังเล็ก') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'th', 'กระต่ายป่าภูเขา', 'ฤดูหนาวขนจะเปลี่ยนเป็นสีขาวเพื่อพรางตัวกับหิมะ', 'ตลอดปีบนพื้นโล่งและที่โล่งในป่า ส่วนใหญ่ยามรุ่งสางและพลบค่ำ', 'สนับสนุนการมีทั้งพื้นโล่งและที่กำบังผสมกันซึ่งมันต้องใช้ตลอดปี', 'จูงสุนัขด้วยสายจูงบนพื้นโล่ง เพื่อไม่ให้ไล่กระต่ายที่กำลังพัก') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'th', 'แบดเจอร์ยุโรป', 'อยู่รวมกันเป็นครอบครัวในโพรงใต้ดินที่ใช้สืบต่อกันหลายรุ่น', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงหลังมืดค่ำใกล้ป่า ฤดูหนาวนอนหลับยาว', 'ปล่อยตลิ่งและแนวพุ่มที่ไม่ถูกรบกวนไว้ให้มันขุดโพรง', 'อย่าปิดหรือขุดใกล้โพรงที่ยังใช้งานเด็ดขาด — เป็นบ้านถาวรของมัน') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'th', 'ค้างคาวแคระ', 'ค้างคาวจิ๋วชนิดนี้กินริ้นและยุงได้ถึง 3,000 ตัวในคืนเดียว', 'ในเย็นฤดูร้อน มองหาการบินเร็วหักเลี้ยวยามพลบค่ำเหนือสวน', 'ติดกล่องค้างคาวสูง ๆ บนผนังหรือต้นไม้ที่ได้รับแดดยามเย็น', 'เลี่ยงไฟสว่างจ้าตรงปากที่พักอาศัย และรักษาท้องฟ้ายามค่ำให้มืด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'th', 'ผีเสื้อกระดองเต่าเล็ก', 'ผีเสื้อชนิดนี้จำศีลในระยะตัวเต็มวัย มักอยู่ในเพิงและใต้หลังคา', 'ต้นฤดูใบไม้ผลิถึงใบไม้ร่วงบนดอกไม้กลางแดด โดยเฉพาะต้นตำแย', 'เว้นหย่อมต้นตำแยไว้ในมุมที่มีแดด — หนอนของมันต้องใช้', 'อย่ารบกวนผีเสื้อที่จำศีลในเพิงตลอดฤดูหนาว') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'th', 'ผีเสื้อนกยูง', 'จุดคล้ายดวงตาวาบขึ้นเพื่อขู่นก และปีกอาจส่งเสียงฟ่อเมื่อกาง', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงในวันแดดจัด กินน้ำหวานจากดอกหนามและผลไม้ร่วง', 'ปล่อยให้หย่อมต้นตำแยกลางแดดเติบโตเพื่อหนอนของมัน', 'อย่ารบกวนตัวเต็มวัยที่หลบในเพิงและกองฟืนช่วงฤดูหนาว') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'th', 'ผีเสื้อสีกำมะถัน', 'คำว่า "butterfly" ในภาษาอังกฤษอาจมาจากสีเหลืองเนยของตัวผู้ชนิดนี้', 'เป็นผีเสื้อกลุ่มแรกของฤดูใบไม้ผลิ วันอากาศอุ่นให้มองหาตามชายป่า', 'สนับสนุนพุ่มไม้ในแนวรั้วซึ่งเป็นพืชชนิดเดียวที่หนอนของมันกิน', 'อย่าถางแนวพุ่มรกที่เป็นที่หลบของตัวเต็มวัยช่วงฤดูหนาว') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'th', 'ผีเสื้อปลายปีกส้ม', 'เฉพาะตัวผู้เท่านั้นที่มีปลายปีกสีส้มสด ตัวเมียเป็นสีขาว', 'ฤดูใบไม้ผลิตามทุ่งชื้นและทางเดินที่มีดอกไม้ป่าขึ้น', 'ปล่อยให้ดอกไม้ป่าเติบโตในมุมชื้นที่ไม่ถูกตัดหญ้า', 'เลื่อนการตัดหญ้าริมทางจนกว่าหนอนจะกินอาหารเสร็จ') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'th', 'ผีเสื้อสีน้ำเงินธรรมดา', 'บางครั้งมดคอยดูแลหนอนของผีเสื้อชนิดนี้เพื่อแลกกับของเหลวรสหวาน', 'ตั้งแต่ปลายฤดูใบไม้ผลิบนทุ่งหญ้ากลางแดดที่มีโคลเวอร์มาก', 'ปล่อยทุ่งหญ้าไม่ให้ถูกตัดเพื่อให้โคลเวอร์ออกดอก', 'อย่าพ่นยาฆ่าวัชพืชบนทุ่งหญ้าที่มีดอกไม้ป่าอุดมสมบูรณ์') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'th', 'ผีเสื้อขาวเส้นเขียว', 'แม้หน้าตาคล้ายผีเสื้อกะหล่ำ แต่ชอบพืชป่ามากกว่าพืชสวน', 'ฤดูใบไม้ผลิถึงปลายฤดูร้อนในทุ่งชื้น คูน้ำ และทางเดินในป่า', 'ปล่อยให้มุมชื้นรกไปด้วยพืชวงศ์ผักกาดพื้นถิ่น', 'อย่าระบายน้ำหรือพ่นยาในทุ่งชื้นที่มันขยายพันธุ์') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'th', 'ด้วงเต่าลายเจ็ดจุด', 'ด้วงเต่าลายตัวเดียวกินเพลี้ยได้นับพันตัวตลอดช่วงชีวิต', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงบนพืชที่มีเพลี้ย ฤดูหนาวรวมกลุ่มกันจำศีล', 'ทนเพลี้ยไว้บ้างและงดพ่นยา เพื่อให้ด้วงเต่าลายมีอาหาร', 'เว้นลำต้นกลวงและใบไม้ร่วงที่มันใช้หลบในฤดูหนาว') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'th', 'ผึ้งภมรหางเหลือง', 'นางพญาเป็นผึ้งกลุ่มแรก ๆ ของฤดูใบไม้ผลิ บินต่ำส่งเสียงหึ่งเพื่อหารูทำรัง', 'ต้นฤดูใบไม้ผลิถึงใบไม้ร่วงบนดอกไม้ นางพญาสำรวจโคนแนวพุ่มในฤดูใบไม้ผลิ', 'ปลูกหรือเว้นพืชที่ออกดอกเร็ว และปล่อยให้โคลเวอร์ออกดอกในสนามหญ้า', 'เว้นตลิ่งที่ไม่ถูกรบกวนและรูหนูเก่าที่รังผึ้งใช้ทำรัง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'th', 'ผึ้งพันธุ์ตะวันตก', 'ผึ้งงานบอกรังว่าดอกไม้อยู่ที่ไหนด้วยการเต้นเป็นรูปเลขแปด', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงบนดอกไม้ในวันอากาศอุ่นและลมสงบ', 'ปล่อยให้ดอกไม้หลากชนิดบานสลับกันตลอดฤดู และวางจานน้ำตื้นไว้', 'อย่าพ่นยาบนพืชที่กำลังออกดอก และอย่าพ่นยากลางวันเด็ดขาด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'th', 'แมลงปอจักรพรรดิ', 'เป็นแมลงปอที่ใหญ่ที่สุดชนิดหนึ่งของยุโรป จับเหยื่อกลางอากาศได้ด้วย', 'ในวันฤดูร้อนที่อากาศอุ่น ดูมันบินตรวจตราตามบ่อและริมทะเลสาบ', 'รักษาหรือขุดบ่อที่มีพืชน้ำ และปล่อยขอบบ่อให้มีพืชปกคลุม', 'รักษาบ่อให้ปลอดมลพิษและน้ำไหลบ่า เพื่อให้ตัวอ่อนเติบโตได้') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'th', 'แมลงปอดาร์เตอร์', 'มักเกาะจุดอุ่น ๆ จุดเดิมแล้วพุ่งออกไปฉวยแมลงที่บินผ่าน', 'กลางฤดูร้อนถึงใบไม้ร่วงใกล้น้ำนิ่ง ผึ่งแดดบนทางเดินและเสา', 'เว้นจุดเกาะกลางแดดและพืชพรรณรอบบ่อและคูน้ำ', 'อย่าให้ปุ๋ยหรือน้ำมันไหลลงบ่อที่ตัวอ่อนอาศัยอยู่') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'th', 'มดแดงป่าสน', 'จอมปลวกรังของมันสูงเกินหนึ่งเมตรได้และมีมดอยู่ถึงครึ่งล้านตัว', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงในป่าสน มองหากองใบสนทรงโดม', 'ปล่อยกองรังไว้ตามเดิม — ใช้เวลาสร้างหลายปี', 'เดินอยู่บนทางเดินและอย่าเตะหรือขุดกองรังมดเด็ดขาด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'th', 'ดอกอะนีโมนีป่า', 'แผ่ขยายช้ามากจนพรมดอกไม้หนาแน่นเป็นสัญญาณของป่าดึกดำบรรพ์', 'ฤดูใบไม้ผลิ มองหาพรมดอกสีขาวก่อนที่ต้นไม้จะผลิใบ', 'ปล่อยพื้นป่าไว้ตามเดิม เพื่อให้รากที่แผ่ช้าเติบโตได้', 'ชื่นชมมันตรงที่มันขึ้น — การเด็ดคือการเอาดอกที่ใช้เวลาหลายปีแผ่ขยายไป') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'th', 'ลิลลี่ออฟเดอะแวลลีย์', 'ทุกส่วนของพืชหอมหวานชนิดนี้มีพิษหากกินเข้าไป', 'ปลายฤดูใบไม้ผลิ ตามกลิ่นไปยังป่าร่มครึ้มและสวนที่มีเงา', 'ปล่อยชายป่าที่มีร่มเงาและใบไม้ร่วงตรงที่มันขึ้นไว้ตามเดิม', 'อย่าเด็ดหรือขุด และเก็บให้พ้นมือเด็กและสัตว์เลี้ยง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'th', 'กระเทียมป่า', 'มักได้กลิ่นกระเทียมป่าก่อนจะเห็นดอกสีขาวของมัน', 'ฤดูใบไม้ผลิ มองหาใบเขียวกว้างและดอกรูปดาวในป่าชื้น', 'ปล่อยป่าชื้นไว้ตามเดิม เพื่อให้พรมใบงอกใหม่ทุกปี', 'หากท้องถิ่นอนุญาตให้เก็บ ให้เก็บแต่น้อยและอย่าถอนหัวขึ้นมาเด็ดขาด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'th', 'ดอกดาวเรืองน้ำ', 'เป็นพืชพื้นถิ่นที่เก่าแก่ที่สุดชนิดหนึ่ง รอดพ้นยุคน้ำแข็งครั้งสุดท้ายในสแกนดิเนเวีย', 'ฤดูใบไม้ผลิ มองหาดอกสีทองขนาดใหญ่ในพรุ คูน้ำ และริมบ่อ', 'รักษาริมบ่อและคูน้ำให้ชื้นและไม่ถูกตัดหญ้า เพื่อให้มันออกดอก', 'อย่าระบายน้ำออกจากพื้นที่ชื้น และปล่อยต้นไม้ไว้ตรงที่มันขึ้น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'th', 'ดอกคาวสลิป', 'ครั้งหนึ่งดอกคาวสลิปมีมากในทุ่งหญ้าจนเด็ก ๆ เอามาทำเป็นลูกบอล', 'ฤดูใบไม้ผลิ มองหาดอกสีเหลืองที่โน้มลงในทุ่งหญ้าเก่าที่ไม่ถูกปรับปรุง', 'อย่าตัดหญ้าจนกว่าดอกคาวสลิปจะบานและติดเมล็ดแล้ว', 'อย่าเด็ดหรือขุดจากธรรมชาติ — ดอกไม้ทุ่งหญ้ากำลังลดจำนวนลง') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'th', 'ดอกเดซี่ใหญ่', 'สิ่งที่ดูเหมือนดอกเดียวแท้จริงคือดอกจิ๋วหลายสิบดอกอัดแน่นอยู่ด้วยกัน', 'ฤดูร้อน มองหาดอกเดซี่ขาวขนาดใหญ่ตามริมถนนและทุ่งหญ้า', 'เว้นแถบหญ้าไม่ให้ถูกตัดตลอดกลางฤดูร้อน เพื่อให้มันออกดอก', 'อย่าพ่นยาฆ่าวัชพืชบนไหล่ทางและทุ่งหญ้า') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'th', 'ดอกแดนดิไลออน', 'ดอกแดนดิไลออนเป็นแหล่งน้ำหวานช่วงต้นฤดูที่สำคัญที่สุดแหล่งหนึ่งของผึ้ง', 'ตั้งแต่ฤดูใบไม้ผลิเป็นต้นไปแทบทุกที่ ดอกบานกลางแดดและหุบยามพลบค่ำ', 'ปล่อยให้ดอกแดนดิไลออนบานในสนามหญ้าช่วงฤดูใบไม้ผลิก่อนตัดหญ้าครั้งแรก', 'งดยาฆ่าวัชพืชในสนามหญ้า เพื่อให้แมลงผสมเกสรช่วงต้นฤดูยังมีอาหารสำคัญนี้') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'th', 'ต้นเฮเทอร์', 'ต้นเฮเทอร์ต้นเดียวผลิตเมล็ดจิ๋วได้มากกว่าหนึ่งแสนเมล็ด', 'ปลายฤดูร้อน มองหาพรมสีม่วงบนทุ่งโล่งและพรุ', 'สนับสนุนการรักษาทุ่งเฮเทอร์ให้โล่งและไม่ถูกระบายน้ำ', 'เดินอยู่บนทางเดินในทุ่งเฮเทอร์ และอย่าก่อไฟในสภาพอากาศแห้งเด็ดขาด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'th', 'บิลเบอร์รี', 'บิลเบอร์รีย้อมนิ้วมือให้เป็นสีน้ำเงิน และเป็นอาหารของทุกอย่างตั้งแต่นกจนถึงหมี', 'ฤดูร้อน มองหาพุ่มเตี้ยที่มีผลสีเข้มในป่าสนและป่าสปรูซ', 'ปล่อยพืชชั้นล่างของป่าไว้ตามเดิม เพื่อให้พุ่มเตี้ยติดผลได้', 'หากท้องถิ่นอนุญาตให้เก็บ ให้เหลือผลไว้มาก ๆ สำหรับสัตว์ป่า') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'th', 'ลิงกอนเบอร์รี', 'ลิงกอนเบอร์รีเก็บได้นานหลายเดือนเพราะมีสารกันเสียตามธรรมชาติในผล', 'ปลายฤดูร้อนและใบไม้ร่วง มองหาผลสีแดงเป็นมันบนพรมพืชเขียวตลอดปี', 'ปล่อยพืชคลุมพื้นป่าไว้ตามเดิม เพื่อให้พรมพืชแผ่ขยายได้', 'หากอนุญาตให้เก็บ ให้เหยียบอย่างระวังเพื่อไม่ให้ต้นไม้ถูกทับ') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'th', 'ต้นเบิร์ชเงิน', 'ต้นเบิร์ชหนึ่งต้นเลี้ยงแมลงได้หลายร้อยชนิด ซึ่งเลี้ยงนกอีกนับไม่ถ้วน', 'ตลอดปี เปลือกสีขาวที่ลอกเป็นแผ่นทำให้สังเกตได้ง่ายทุกฤดู', 'ปล่อยใบเบิร์ชที่ร่วงและไม้ตายไว้ เพื่อบำรุงดินและเลี้ยงแมลง', 'อย่าลอกเปลือกไม้ เพราะทำให้ต้นไม้เป็นแผลและอ่อนแอ') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'th', 'ต้นสปรูซนอร์เวย์', 'ต้นสปรูซต้นหนึ่งในสวีเดนเติบโตจากรากที่มีอายุหลายพันปี', 'ตลอดปีในป่า ลูกสนห้อยของมันยาวที่สุดในบรรดาสปรูซทั้งหมด', 'ปล่อยลูกสนที่ร่วงและไม้ตายไว้ เพราะเป็นที่หลบของแมลงและเห็ดรา', 'เดินอยู่บนเส้นทางในป่า เพื่อไม่ให้รากตื้นของสปรูซถูกอัดแน่น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'th', 'ต้นสนสกอต', 'ต้นสนสกอตเก่าแก่เรืองสีส้มใกล้ยอดและมีอายุยืนได้หลายศตวรรษ', 'ตลอดปีบนพื้นทรายและพื้นหิน มองหาเปลือกสีส้มช่วงบนของลำต้น', 'ปล่อยไม้ตายยืนต้นและต้นสนเก่าแก่ไว้ เพราะอุดมด้วยสิ่งมีชีวิต', 'อย่าก่อไฟใกล้ต้นสนบนพื้นทรายแห้งเด็ดขาด') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'th', 'ปลาไพก์เหนือ', 'ปลาไพก์เป็นนักล่าซุ่มโจมตีที่พุ่งออกจากความนิ่งได้ในพริบตา', 'ฤดูใบไม้ผลิถึงใบไม้ร่วงในน้ำตื้นที่มีพืชน้ำของทะเลสาบและแม่น้ำไหลช้า', 'สนับสนุนการรักษาน้ำตื้นที่มีกกและพืชน้ำซึ่งลูกปลาใช้หลบภัย', 'อย่าให้มลพิษและขยะลงน้ำ และปฏิบัติตามกฎการตกปลาของท้องถิ่น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'th', 'ปลาเพิร์ชยุโรป', 'ปลาเพิร์ชล่าเป็นฝูง และลายพาดเข้มช่วยพรางรูปร่างของมัน', 'ในเดือนที่อากาศอุ่นรอบท่าเทียบเรือ ดงพืชน้ำ และแนวน้ำลึก', 'สนับสนุนน้ำสะอาดและโครงสร้างใต้น้ำที่เป็นที่หลบของปลาเล็ก', 'อย่าทิ้งสิ่งใดลงทะเลสาบและแม่น้ำ และปฏิบัติตามกฎการตกปลาของท้องถิ่น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'th', 'ปลาโรช', 'ปลาโรชเป็นปลาอาหารสำคัญที่นักล่าในทะเลสาบหลายชนิดพึ่งพา', 'ในเดือนที่อากาศอุ่น อยู่รวมฝูงใกล้ผิวน้ำของทะเลสาบและแม่น้ำไหลช้า', 'สนับสนุนน้ำสะอาดและริมตลิ่งที่มีพืชปกคลุมสำหรับการวางไข่', 'อย่าให้น้ำไหลบ่าและขยะลงน้ำ และปฏิบัติตามกฎการตกปลาของท้องถิ่น') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'vi', 'Chim yến châu Âu', 'Chim yến có thể ở trên không hàng tháng liền, thậm chí ngủ khi đang bay.', 'Vào những chiều hè ấm áp, hãy nhìn cao trên mái nhà và nghe tiếng đàn kêu ríu rít.', 'Lắp một hộp làm tổ dưới mái hiên trước khi chim trở về vào mùa xuân.', 'Khi sửa nhà, hãy giữ lại những khe nhỏ dưới mái hiên nơi chim làm tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'vi', 'Chim nhạn bụng trắng', 'Chim nhạn di cư tới tận miền nam châu Phi rồi quay về mỗi năm.', 'Từ xuân đến đầu thu, tìm chúng bay là là trên đồng ruộng và mặt nước.', 'Để hé cửa kho hoặc chuồng để chúng vào được chỗ làm tổ.', 'Đừng phá tổ bùn cũ — chim nhạn dùng lại chúng năm này qua năm khác.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'vi', 'Chim cu cu', 'Cu cu đẻ trứng vào tổ chim khác và không bao giờ tự nuôi con mình.', 'Cuối xuân, hãy nghe tiếng "cu-cu" vọng xa từ bìa rừng.', 'Hãy giữ những đồng cỏ và hàng rào cây giàu côn trùng nuôi các loài chim chủ.', 'Đi theo lối mòn gần bụi rậm và bãi sậy để không quấy rầy chim chủ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'vi', 'Chim cổ đỏ châu Âu', 'Chim cổ đỏ giữ lãnh thổ rất dữ và hót suốt đêm gần đèn đường.', 'Quanh năm trong vườn và rừng; chúng thường theo người xới đất để tìm giun.', 'Chừa một góc vườn có lá rụng để chúng bới tìm thức ăn.', 'Hoãn cắt tỉa hàng rào cây nặng tay đến khi mùa làm tổ kết thúc cuối hè.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'vi', 'Chim hoét đen', 'Tiếng hót trầm ấm như sáo của con đực là một trong những âm thanh dễ nhận nhất châu Âu.', 'Quanh năm; lúc bình minh và chạng vạng, nghe con đực hót từ mái nhà và ngọn cây.', 'Đặt nước sạch để chúng uống và tắm, nhất là trong đợt khô hạn.', 'Vào mùa làm tổ, giữ mèo trong nhà lúc rạng sáng.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'vi', 'Chim hoét đồng', 'Là loài hoét sống bầy đàn, mùa đông đi lang thang theo đàn ồn ào.', 'Mùa thu và mùa đông, xem các đàn vặt quả mọng từ hàng rào cây và cây thanh lương trà.', 'Đừng cắt tỉa bụi cây có quả mọng suốt mùa đông.', 'Để táo rụng nằm trên đất vào mùa đông — đó là thức ăn thiết yếu khi trời lạnh.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'vi', 'Chim bạc má lớn', 'Chúng có vốn tiếng kêu rất phong phú và học tiếng mới từ hàng xóm.', 'Quanh năm; từ cuối đông hãy nghe tiếng hót vang lặp đi lặp lại.', 'Treo hộp làm tổ có lỗ 32 mm ở nơi yên tĩnh, râm mát.', 'Tránh thuốc trừ sâu trong vườn để còn đủ sâu bướm nuôi chim non.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'vi', 'Chim bạc má xanh', 'Một lứa chim bạc má xanh có thể ăn hơn một nghìn con sâu bướm.', 'Quanh năm trong vườn và rừng, thường treo ngược trên cành nhỏ.', 'Lắp hộp làm tổ nhỏ có lỗ 25 mm, tránh hướng gió thịnh hành.', 'Bỏ thuốc diệt côn trùng vào mùa xuân để chim non có sâu ăn.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'vi', 'Chim sẻ rừng', 'Tiếng hót khác nhau theo vùng, gần như những phương ngữ địa phương.', 'Từ xuân đến thu; con đực hót một câu tươi sáng đi xuống từ cành trống.', 'Chừa lại một phần cụm hạt và vạt cỏ dại đứng nguyên suốt mùa.', 'Giữ máng ăn sạch sẽ để bệnh không lây lan giữa các con chim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'vi', 'Chim giẻ cùi sồi', 'Mỗi mùa thu chúng chôn hàng nghìn quả sồi, và vì quên một số nên gieo cả rừng sồi.', 'Quanh năm trong rừng sồi; mùa thu để ý ánh hồng và xanh lóe lên.', 'Để nguyên quả sồi rụng và lá dưới gốc sồi.', 'Giữ chó trên lối mòn trong rừng để chim kiếm ăn dưới đất không bị đánh động.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'vi', 'Chim gõ kiến đốm lớn', 'Tiếng gõ mùa xuân không phải để kiếm ăn mà là nhịp nhanh để tuyên bố lãnh thổ.', 'Quanh năm; cuối đông hãy nghe tiếng gõ vọng khắp rừng.', 'Để lại gỗ chết đứng, nơi có côn trùng mà chim gõ kiến ăn.', 'Đừng chặt cây đã chết hoặc đang tàn, chúng có thể chứa hốc làm tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'vi', 'Chim chìa vôi trắng', 'Việc vẫy đuôi liên tục có thể là tín hiệu cảnh giác trước kẻ săn mồi.', 'Từ xuân đến thu gần nước và đất trống; chạy rồi dừng để chộp côn trùng.', 'Giữ một vạt cỏ ngắn hoặc sỏi gần nước để chúng kiếm ăn.', 'Đừng quấy rầy bờ sỏi nơi chúng kiếm ăn và làm tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'vi', 'Sếu xám', 'Đầu xuân, sếu múa giao duyên bằng những cú nhảy và cúi chào.', 'Từ xuân đến thu quanh vùng đất ngập nước; nghe tiếng kêu vang xa hàng cây số.', 'Ủng hộ việc bảo vệ đầm lầy và đồng cỏ ẩm chưa bị tháo nước, nơi sếu sinh sản.', 'Quan sát vùng đất ngập nước làm tổ từ xa — bị quấy rầy, sếu sẽ bỏ tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'vi', 'Thiên nga kêu', 'Chúng kết đôi trọn đời và báo hiệu đến nơi bằng tiếng kêu vang như kèn.', 'Mùa xuân và mùa thu trên hồ và cánh đồng ngập nước, thường theo nhóm gia đình.', 'Ủng hộ giữ mép hồ nông và ruộng ẩm không bị tháo nước.', 'Đừng bao giờ cho thiên nga ăn bánh mì — có hại; trên băng cũng nên giữ khoảng cách.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'vi', 'Vịt trời đầu xanh', 'Vịt con biết bơi và tự kiếm ăn chỉ vài giờ sau khi nở.', 'Quanh năm ở hầu hết mọi ao, hồ hay sông chảy chậm.', 'Nếu cho vịt ăn, hãy dùng yến mạch, đậu hoặc hạt thay cho bánh mì.', 'Mùa xuân, giữ chó tránh xa vùng nước nơi vịt làm tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'vi', 'Diều hâu thường', 'Diều hâu lượn bằng đôi cánh rộng và thường kêu một tiếng giống mèo.', 'Từ xuân đến thu; tìm chúng lượn vòng cao trên đồng ruộng và bìa rừng.', 'Ủng hộ đồng cỏ thô và dải mép ruộng nơi có chuột đồng và con mồi nhỏ.', 'Đừng bao giờ dùng bả chuột — nó đi lên chuỗi thức ăn tới các loài chim săn mồi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'vi', 'Ó cá', 'Ó cá lao xuống bằng chân trước để bắt cá và mang được con mồi nặng bằng nửa mình.', 'Từ xuân đến thu gần các hồ lớn; đầu tiên treo mình trên không rồi lao xuống.', 'Ủng hộ dựng bệ làm tổ trên cột cao gần những hồ nhiều cá.', 'Tránh xa bệ làm tổ để các cặp chim không bỏ trứng mà bay đi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'vi', 'Cáo đỏ', 'Cáo dùng từ trường Trái Đất để ước lượng cú vồ vào con mồi đang ẩn.', 'Quanh năm, hoạt động mạnh nhất lúc rạng sáng và chạng vạng ở bìa rừng và mép ruộng.', 'Chừa một góc hoang yên tĩnh để cáo nghỉ ngơi và đào hang.', 'Đậy kín thùng rác và đừng bao giờ để thức ăn thừa có hại cho cáo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'vi', 'Nhím gai châu Âu', 'Một con nhím có thể đi vài cây số chỉ trong một đêm kiếm ăn.', 'Từ xuân đến thu sau khi trời tối; mùa đông ngủ dưới đống lá và khúc gỗ.', 'Mở một khe rộng 13 cm trên hàng rào để nhím đi lại giữa các vườn.', 'Kiểm tra cỏ cao trước khi cắt và để lại đống lá cho nhím ngủ đông.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'vi', 'Hoẵng châu Âu', 'Hoẵng trì hoãn thai kỳ để con non luôn ra đời vào đầu mùa hè.', 'Quanh năm ở bìa rừng, dễ thấy nhất khi gặm cỏ lúc rạng sáng và chạng vạng.', 'Ủng hộ mép ruộng không bị cắt và bụi rậm cho hoẵng chỗ nấp và thức ăn.', 'Đầu hè khi con non nằm ẩn, hãy xích chó khi ở gần rừng.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'vi', 'Nai sừng tấm', 'Nai sừng tấm là loài hươu nai lớn nhất Trái Đất; con đực lớn nặng hơn nửa tấn.', 'Quanh năm trong rừng và vùng đất ngập nước, hoạt động mạnh nhất lúc rạng sáng và chạng vạng.', 'Ủng hộ những cánh rừng nối liền và hành lang đất ngập nước mà chúng cần để di chuyển.', 'Lái xe cẩn thận trên đường rừng lúc rạng sáng và chạng vạng, và đừng lại gần con non.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'vi', 'Sóc đỏ', 'Sóc đỏ làm nhiều tổ và di chuyển qua lại giữa chúng.', 'Quanh năm trong rừng lá kim và rừng hỗn giao, bận rộn nhất vào sáng sớm.', 'Để lại nón thông, hạt và cây đứng nơi sóc kiếm ăn và làm tổ.', 'Giữ chó trên lối mòn và đừng quấy rầy những cây có thể chứa tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'vi', 'Hải ly châu Âu', 'Đập hải ly tạo ra vùng đất ngập nước làm tăng cá, chim và côn trùng suốt nhiều cây số.', 'Từ xuân đến cuối thu quanh những dòng sông chảy chậm, hoạt động mạnh nhất lúc chạng vạng.', 'Ủng hộ giữ nguyên đập hải ly và cây ven nước ở nơi an toàn.', 'Tránh xa hang và đập, nhất là khi hải ly con còn nhỏ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'vi', 'Thỏ rừng núi', 'Mùa đông, lông chúng chuyển trắng để ngụy trang trên tuyết.', 'Quanh năm trên đất trống và trảng rừng, chủ yếu lúc rạng sáng và chạng vạng.', 'Ủng hộ sự xen kẽ giữa đất trống và chỗ nấp mà chúng cần suốt năm.', 'Xích chó ở nơi đất trống để thỏ đang nghỉ không bị rượt đuổi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'vi', 'Lửng châu Âu', 'Lửng sống thành nhóm gia đình trong hang ngầm được dùng qua nhiều thế hệ.', 'Từ xuân đến thu sau khi trời tối, gần rừng; mùa đông chúng ngủ.', 'Để nguyên các bờ dốc và hàng rào cây nơi lửng có thể đào hang.', 'Đừng bao giờ bịt hoặc đào gần một hang đang có lửng ở — đó là nhà lâu dài của chúng.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'vi', 'Dơi muỗi nhỏ', 'Con dơi tí hon này có thể ăn tới 3.000 con muỗi mắt và muỗi trong một đêm.', 'Vào những chiều hè, quan sát đường bay nhanh và ngoặt gấp lúc chạng vạng trên các khu vườn.', 'Treo hộp dơi trên cao ở tường hoặc cây đón được nắng chiều.', 'Tránh ánh sáng chói ở cửa nơi trú và giữ bầu trời đêm tối.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'vi', 'Bướm mai rùa nhỏ', 'Loài bướm này ngủ đông ở giai đoạn trưởng thành, thường trong nhà kho và gác mái.', 'Từ đầu xuân đến thu trên những bông hoa có nắng, đặc biệt là cây tầm ma.', 'Chừa một vạt tầm ma ở góc có nắng — sâu của nó cần loài cây này.', 'Đừng quấy rầy bướm đang ngủ đông trong nhà kho suốt mùa đông.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'vi', 'Bướm công', 'Những đốm giống mắt lóe lên để dọa chim, và cánh có thể rít lên khi mở ra.', 'Từ xuân đến thu vào ngày nắng, ăn trên cây kế, và trái cây rụng.', 'Hãy để một vạt tầm ma có nắng mọc lên cho sâu của nó.', 'Đừng quấy rầy bướm trưởng thành trú trong nhà kho và đống củi qua mùa đông.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'vi', 'Bướm lưu huỳnh', 'Từ "butterfly" trong tiếng Anh có thể bắt nguồn từ màu vàng bơ của con đực loài này.', 'Là một trong những loài bướm đầu tiên của mùa xuân; ngày ấm hãy tìm dọc bìa rừng.', 'Ủng hộ các bụi cây mận gai trong hàng rào, loài cây duy nhất mà sâu của nó ăn.', 'Đừng phát quang hàng rào cây rậm nơi bướm trưởng thành trú qua mùa đông.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'vi', 'Bướm chóp cam', 'Chỉ con đực mới có chóp cánh màu cam rực; con cái màu trắng.', 'Mùa xuân dọc theo đồng cỏ ẩm và đường làng nơi hoa dại mọc.', 'Hãy để hoa dại mọc ở những góc ẩm không bị cắt cỏ.', 'Hoãn cắt cỏ ven đường cho đến khi sâu ăn xong.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'vi', 'Bướm xanh thường', 'Sâu của loài bướm này đôi khi được kiến chăm sóc để đổi lấy dịch ngọt.', 'Từ cuối xuân trên đồng cỏ nhiều nắng, giàu cỏ ba lá.', 'Đừng cắt đồng cỏ để cỏ ba lá có thể ra hoa.', 'Tránh phun thuốc diệt cỏ lên đồng cỏ giàu hoa dại.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'vi', 'Bướm trắng gân xanh', 'Dù trông giống bướm cải, nó thích cây dại hơn là cây trồng trong vườn.', 'Từ xuân đến cuối hè ở đồng cỏ ẩm, mương rãnh và lối mòn trong rừng.', 'Hãy để những góc ẩm mọc hoang với cây họ cải bản địa.', 'Đừng tháo nước hay phun thuốc lên đồng cỏ ẩm nơi nó sinh sản.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'vi', 'Bọ rùa bảy chấm', 'Một con bọ rùa có thể ăn hàng nghìn con rệp trong đời.', 'Từ xuân đến thu trên cây có rệp; mùa đông chúng tụ lại ngủ đông.', 'Chịu đựng một chút rệp và bỏ phun thuốc để bọ rùa có thức ăn.', 'Để lại thân cây rỗng và lá rụng nơi bọ rùa trú qua mùa đông.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'vi', 'Ong nghệ đuôi vàng', 'Ong chúa là một trong những con ong ra sớm nhất mùa xuân, bay thấp vo ve tìm hốc làm tổ.', 'Từ đầu xuân đến thu trên hoa; mùa xuân ong chúa lùng sục dưới chân hàng rào cây.', 'Trồng hoặc chừa lại cây ra hoa sớm và để cỏ ba lá nở trên bãi cỏ.', 'Để nguyên các bờ dốc và hang chuột cũ nơi đàn ong làm tổ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'vi', 'Ong mật phương Tây', 'Ong đi kiếm ăn báo cho tổ biết hoa ở đâu bằng điệu múa hình số tám.', 'Từ xuân đến thu trên hoa vào những ngày ấm và lặng gió.', 'Hãy để nhiều loài hoa nở nối tiếp qua các mùa và đặt một đĩa nước nông.', 'Đừng phun thuốc lên cây đang ra hoa, và tuyệt đối không phun vào giữa trưa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'vi', 'Chuồn chuồn hoàng đế', 'Là một trong những loài chuồn chuồn lớn nhất châu Âu, có thể bắt mồi ngay giữa không trung.', 'Vào những ngày hè ấm, xem nó tuần tra quanh ao và mép hồ.', 'Giữ hoặc đào một cái ao có cây thủy sinh và để mép ao có cây cối.', 'Giữ ao không bị ô nhiễm và nước chảy tràn để ấu trùng phát triển được.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'vi', 'Chuồn chuồn kim thường', 'Nó thường đậu ở cùng một chỗ ấm rồi lao ra chộp côn trùng bay ngang.', 'Từ giữa hè đến thu gần vùng nước tĩnh, sưởi nắng trên lối mòn và cọc.', 'Để lại chỗ đậu có nắng và thảm thực vật quanh ao và mương.', 'Đừng để phân bón hay dầu trôi vào ao nơi ấu trùng sinh sống.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'vi', 'Kiến rừng đỏ', 'Ụ tổ của chúng có thể cao hơn một mét và chứa nửa triệu con kiến.', 'Từ xuân đến thu trong rừng lá kim; hãy tìm những ụ hình vòm bằng lá kim.', 'Để nguyên các ụ tổ — phải mất nhiều năm mới xây xong.', 'Đi trên lối mòn và đừng bao giờ đá hay đào vào ụ kiến.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'vi', 'Hoa hải quỳ rừng', 'Loài này lan chậm đến mức thảm hoa dày là dấu hiệu của rừng cổ.', 'Mùa xuân, hãy tìm những thảm hoa trắng trước khi cây ra lá.', 'Để nguyên nền rừng để bộ rễ lan chậm có thể phát triển.', 'Hãy ngắm chúng ngay nơi chúng mọc — hái đi là lấy mất bông hoa đã mất nhiều năm mới lan tới.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'vi', 'Hoa linh lan', 'Mọi bộ phận của loài cây thơm ngát này đều độc nếu ăn phải.', 'Cuối xuân, hãy theo mùi hương tới những khu rừng và vườn râm mát.', 'Để nguyên bìa rừng râm mát và lá rụng nơi nó mọc.', 'Đừng hái hay đào nó lên, và giữ xa tầm tay trẻ em và vật nuôi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'vi', 'Tỏi rừng', 'Bạn thường ngửi thấy mùi tỏi rừng trước khi nhìn thấy hoa trắng của nó.', 'Mùa xuân, hãy tìm những lá xanh rộng và hoa hình sao trong rừng ẩm.', 'Để nguyên rừng ẩm để các thảm cây mọc lại mỗi năm.', 'Nếu địa phương cho phép hái, hãy lấy ít thôi và đừng bao giờ nhổ củ lên.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'vi', 'Hoa cúc vàng đầm lầy', 'Là một trong những loài cây bản địa cổ nhất, sống sót qua Kỷ Băng hà cuối cùng ở Scandinavia.', 'Mùa xuân, hãy tìm những bông hoa vàng lớn ở đầm lầy, mương và mép ao.', 'Giữ mép ao và mương luôn ẩm và không cắt cỏ để cây có thể ra hoa.', 'Đừng tháo nước vùng đất ẩm và hãy để cây ở nguyên nơi nó mọc.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'vi', 'Hoa anh thảo vàng', 'Xưa kia hoa anh thảo nhiều đến mức trẻ con kết chúng thành những quả bóng.', 'Mùa xuân, hãy tìm những bông hoa vàng rủ xuống trên đồng cỏ cũ chưa cải tạo.', 'Đừng cắt cỏ cho đến khi hoa anh thảo nở xong và kết hạt.', 'Đừng hái hay đào chúng từ tự nhiên — hoa đồng cỏ đang suy giảm.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'vi', 'Hoa cúc trắng lớn', 'Thứ trông như một bông hoa thực ra là hàng chục bông hoa tí hon ghép lại.', 'Mùa hè, hãy tìm những bông cúc trắng lớn dọc ven đường và trên đồng cỏ.', 'Chừa một dải cỏ không cắt suốt giữa hè để cây có thể ra hoa.', 'Tránh phun thuốc diệt cỏ lên lề đường và đồng cỏ.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'vi', 'Bồ công anh', 'Bồ công anh là một trong những nguồn mật hoa đầu mùa quan trọng nhất cho ong.', 'Từ mùa xuân trở đi ở hầu như mọi nơi; hoa nở dưới nắng và khép lại lúc chạng vạng.', 'Hãy để bồ công anh nở trên bãi cỏ vào mùa xuân trước lần cắt đầu tiên.', 'Bỏ thuốc diệt cỏ cho bãi cỏ để các loài thụ phấn sớm giữ được nguồn thức ăn thiết yếu này.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'vi', 'Cây thạch nam', 'Một cây thạch nam có thể tạo ra hơn một trăm nghìn hạt li ti.', 'Cuối hè, hãy tìm những thảm tím trên vùng đất hoang trống và đầm lầy.', 'Ủng hộ giữ vùng thạch nam luôn thoáng và không bị tháo nước.', 'Đi trên lối mòn ở vùng thạch nam và đừng bao giờ đốt lửa khi trời khô.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'vi', 'Việt quất rừng', 'Việt quất rừng nhuộm xanh ngón tay bạn và nuôi mọi loài, từ chim đến gấu.', 'Mùa hè, hãy tìm những bụi thấp có quả sẫm màu trong rừng thông và vân sam.', 'Để nguyên tầng cây bụi dưới rừng để những bụi thấp có thể ra quả.', 'Nếu địa phương cho phép hái, hãy chừa lại thật nhiều quả cho động vật hoang dã.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'vi', 'Nham lê đỏ', 'Nham lê đỏ giữ được hàng tháng nhờ một chất bảo quản tự nhiên trong quả.', 'Cuối hè và mùa thu, hãy tìm những quả đỏ bóng trên thảm cây thường xanh.', 'Để nguyên thảm thực vật nền rừng để các thảm cây lan rộng.', 'Nếu được phép hái, hãy bước cẩn thận để không giẫm nát cây.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'vi', 'Cây bạch dương bạc', 'Một cây bạch dương nuôi hàng trăm loài côn trùng, và chúng lại nuôi vô số chim.', 'Quanh năm; lớp vỏ trắng bong tróc khiến cây dễ nhận ra trong mọi mùa.', 'Để lại lá bạch dương rụng và gỗ chết để làm giàu đất và nuôi côn trùng.', 'Tránh bóc vỏ cây, việc đó có thể làm cây bị thương và suy yếu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'vi', 'Cây vân sam Na Uy', 'Một cây vân sam ở Thụy Điển mọc lên từ bộ rễ đã hàng nghìn năm tuổi.', 'Quanh năm trong rừng; nón rủ của nó dài nhất trong các loài vân sam.', 'Để lại nón rụng và gỗ chết, nơi trú ẩn của côn trùng và nấm.', 'Đi trên đường mòn trong rừng để không nén chặt bộ rễ nông của vân sam.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'vi', 'Cây thông Scotland', 'Những cây thông Scotland già ánh lên màu cam gần ngọn và có thể sống hàng thế kỷ.', 'Quanh năm trên đất cát và đá; hãy tìm lớp vỏ màu cam ở phần thân trên.', 'Để lại gỗ chết đứng và những cây thông già, vốn giàu sự sống hoang dã.', 'Đừng bao giờ đốt lửa cạnh hay gần cây thông trên nền cát khô.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'vi', 'Cá chó phương Bắc', 'Cá chó là kẻ săn mồi phục kích, có thể lao ra từ trạng thái bất động trong chớp mắt.', 'Từ xuân đến thu ở vùng nước nông nhiều rong của hồ và sông chảy chậm.', 'Ủng hộ giữ vùng nước nông có sậy và cây thủy sinh, nơi cá con trú ẩn.', 'Giữ ô nhiễm và rác ra khỏi nước; tuân thủ quy định đánh bắt của địa phương.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'vi', 'Cá rô châu Âu', 'Cá rô săn theo đàn và những sọc đậm giúp phá vỡ đường nét cơ thể chúng.', 'Vào các tháng ấm quanh cầu tàu, thảm rong và những chỗ hụt sâu.', 'Ủng hộ nước sạch và các cấu trúc ngầm che chở cho cá nhỏ.', 'Đừng bao giờ đổ thứ gì xuống hồ và sông; tuân thủ quy định đánh bắt của địa phương.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'vi', 'Cá roach', 'Cá roach là loài cá mồi then chốt mà nhiều loài săn mồi trong hồ phụ thuộc vào.', 'Vào các tháng ấm, đi thành đàn gần mặt nước của hồ và sông chảy chậm.', 'Ủng hộ giữ nước sạch và mép bờ có cây cối để cá đẻ trứng.', 'Giữ nước chảy tràn và rác ra khỏi nước; tuân thủ quy định đánh bắt của địa phương.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'am', 'ፈጣን በራሪ ወፍ', 'ለወራት ያህል በአየር ላይ መቆየት ይችላሉ፤ በሚበሩበት ጊዜም ይተኛሉ።', 'በበጋ ሞቃት ምሽቶች ከጣሪያዎች በላይ ተመልከቱ እና የሚጮሁ መንጋዎችን አዳምጡ።', 'በፀደይ ከመመለሳቸው በፊት ከጣሪያው ጠርዝ ስር የጎጆ ሳጥን አስቀምጡ።', 'ቤቱን ስታድሱ ጎጆ የሚሠሩባቸውን ከጣሪያው ጠርዝ ስር ያሉ ትናንሽ ክፍተቶች ጠብቁ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'am', 'የቤት ዋልያ ወፍ', 'በየዓመቱ እስከ ደቡብ አፍሪካ ድረስ ተሰድደው ይመለሳሉ።', 'ከፀደይ እስከ መኸር መጀመሪያ በእርሻና በውሃ ላይ ዝቅ ብለው ሲበሩ ይመልከቱ።', 'ወደ ጎጆአቸው እንዲደርሱ የጋጣ ወይም የመጋዘን በር በትንሹ ክፍት ተውት።', 'የቆዩ የጭቃ ጎጆዎችን አታፍርሱ — ዋልያዎች ዓመት በዓመት ደግመው ይጠቀሙባቸዋል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'am', 'ኩኩ ወፍ', 'እንቁላሎቹን በሌሎች ወፎች ጎጆ ውስጥ ይጥላል፤ የራሱን ጫጩቶች ፈጽሞ አያሳድግም።', 'በፀደይ መጨረሻ ከደን ዳር የሚመጣውን የሩቅ "ኩ-ኩ" ድምፅ አዳምጡ።', 'አስተናጋጅ ወፎችን የሚመግቡ በነፍሳት የበለጸጉ ሜዳዎችንና አጥሮችን ደግፉ።', 'አስተናጋጅ ወፎች እንዳይረበሹ ከቁጥቋጦና ከሸምበቆ አጠገብ በመንገዶች ላይ ቆዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'am', 'ቀይ ደረት ወፍ', 'ግዛታቸውን በጽናት ይከላከላሉ፤ ከመንገድ መብራት አጠገብ በሌሊትም ይዘምራሉ።', 'ዓመቱን ሙሉ በአትክልትና በደን ውስጥ፤ አፈር የሚቆፍርን ሰው ትል ፍለጋ ይከተላሉ።', 'ምግብ የሚፈልጉበት የወደቁ ቅጠሎች ያሉበት የአትክልት ጥግ ተውላቸው።', 'ከባድ የአጥር መከርከምን በበጋ መጨረሻ ጎጆ መሥራት እስኪያልቅ ድረስ አዘግዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'am', 'ጥቁር ወፍ', 'የወንዱ ጥልቅ የዋሽንት መሰል ዝማሬ በአውሮፓ ከሚታወቁት አንዱ ነው።', 'ዓመቱን ሙሉ፤ በንጋትና በምሽት ከጣሪያና ከዛፍ ጫፍ ሲዘምሩ አዳምጡ።', 'በተለይ በደረቅ ወቅት ለመጠጥና ለመታጠቢያ ንጹህ ውሃ አስቀምጡ።', 'በጎጆ ወቅት ድመቶችን በንጋት በቤት ውስጥ ያቆዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'am', 'የእርሻ ወፍ', 'ማህበራዊ ወፍ ሲሆን በክረምት በጫጫታ በተሞሉ መንጋዎች ይንቀሳቀሳል።', 'በመኸርና በክረምት መንጋዎቹ ከአጥርና ከዛፎች ፍሬ ሲለቅሙ ይመልከቱ።', 'ፍሬ ያላቸውን ቁጥቋጦዎች በክረምት ወራት አትከርክሙ።', 'የወደቁ ፖምዎችን በክረምት መሬት ላይ ተውዋቸው — በብርድ ወሳኝ ምግብ ናቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'am', 'ትልቅ ትንንሽ ወፍ', 'ብዙ ዓይነት ድምፆች አሏቸው፤ አዳዲሶቹንም ከጎረቤቶቻቸው ይማራሉ።', 'ዓመቱን ሙሉ፤ ከክረምት መጨረሻ ጀምሮ ተደጋጋሚውን ጩኸት አዳምጡ።', '32 ሚሜ ቀዳዳ ያለው የጎጆ ሳጥን ጸጥ ባለና ጥላ ባለው ቦታ ስቀሉ።', 'ጫጩቶችን ለመመገብ በቂ ትል እንዲኖር የአትክልት ፀረ-ተባይ አስወግዱ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'am', 'ሰማያዊ ትንንሽ ወፍ', 'የአንድ ጎጆ ጫጩቶች ከሺህ በላይ ትሎችን መብላት ይችላሉ።', 'ዓመቱን ሙሉ በአትክልትና በደን፤ ብዙ ጊዜ ከቀጭን ቅርንጫፎች ተገልብጠው ይንጠለጠላሉ።', '25 ሚሜ ቀዳዳ ያለው ትንሽ ሳጥን ከነፋስ አቅጣጫ ራቅ አድርጋችሁ አስቀምጡ።', 'ትሎች ለጫጩቶች እንዲገኙ በፀደይ ፀረ-ተባይ አትጠቀሙ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'am', 'የደን ዘር በላ ወፍ', 'ዝማሬያቸው ከአካባቢ አካባቢ ይለያያል፤ ልክ እንደ አካባቢያዊ ቀበሌኛ።', 'ከፀደይ እስከ መኸር፤ ወንዶቹ ከክፍት ቦታ ብሩህ ወራጅ ዜማ ይዘምራሉ።', 'ከዘር ራሶችና ከሳር አንዳንዶቹን በወቅቱ ሙሉ ቆመው ተውዋቸው።', 'በሽታ እንዳይሰራጭ የመመገቢያ ቦታዎችን ንጹህ ያድርጉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'am', 'የኦክ ወፍ', 'በየመኸሩ ሺዎችን የኦክ ፍሬ ይቀብራል፤ አንዳንዶቹን በመርሳት ሙሉ የኦክ ደኖችን ይተክላል።', 'ዓመቱን ሙሉ በኦክ ደን፤ በመኸር የሮዝና የሰማያዊ ብልጭታዎችን ተጠንቀቁ።', 'የወደቁ የኦክ ፍሬዎችንና ቅጠሎችን ከዛፎቹ ስር እንዳሉ ተውዋቸው።', 'መሬት ላይ የሚመገቡ ወፎች እንዳይደናገጡ ውሾችን በደን ውስጥ በመንገድ ላይ ያቆዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'am', 'ትልቅ ነጠብጣብ እንጨት ቆራጭ ወፍ', 'የፀደዩ ምት ምግብ ለመፈለግ ሳይሆን ግዛቱን ለማወጅ የሚደረግ ፈጣን ምት ነው።', 'ዓመቱን ሙሉ፤ በክረምት መጨረሻ በደኑ ውስጥ የሚያስተጋባውን ምት አዳምጡ።', 'የሚመገባቸው ነፍሳት ያሉበትን የቆመ የሞተ እንጨት ተውት።', 'የሞቱ ወይም የደረቁ ዛፎችን አትቁረጡ፤ የጎጆ ጉድጓድ ሊኖራቸው ይችላል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'am', 'ነጭ ጅራት አወዛዋዥ ወፍ', 'የማያቋርጠው የጅራት እንቅስቃሴ ለአዳኞች የንቃት ምልክት ሊሆን ይችላል።', 'ከፀደይ እስከ መኸር ከውሃ አጠገብና በክፍት መሬት፤ እየሮጠ ቆሞ ነፍሳት ይይዛል።', 'ከውሃ አጠገብ አጭር ሳር ወይም ጠጠር ያለበት ቦታ ተውለት።', 'የሚመገብበትንና ጎጆ የሚሠራበትን የጠጠር ዳርቻ አትረብሹ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'am', 'ግራጫ ሽመላ', 'በፀደይ መጀመሪያ እየዘለሉና እያጎነበሱ የፍቅር ጭፈራ ያሳያሉ።', 'ከፀደይ እስከ መኸር በእርጥብ መሬቶች ዙሪያ፤ ለኪሎ ሜትሮች የሚሰማውን ድምፅ አዳምጡ።', 'የሚራቡበትን ያልደረቀ ረግረግና እርጥብ ሜዳ መጠበቅን ደግፉ።', 'ጎጆ የሚሠሩበትን ቦታ ከሩቅ ተመልከቱ — ከተረበሸ ጎጆውን ይተዋሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'am', 'ጩኸት ያለው ስዋን', 'ለሕይወት ዘመናቸው ጥንድ ይሆናሉ፤ መምጣታቸውንም በከፍተኛ ድምፅ ያውጃሉ።', 'በፀደይና በመኸር በሐይቆችና በውሃ በተሞሉ እርሻዎች፤ ብዙ ጊዜ በቤተሰብ ቡድን።', 'የሐይቅ ጥልቀት የሌላቸው ዳርቻዎችና እርጥብ እርሻዎች ሳይደርቁ እንዲቆዩ ደግፉ።', 'ለስዋኖች ዳቦ በፍጹም አትስጡ — ይጎዳቸዋል፤ በበረዶ ላይም ርቀት ጠብቁ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'am', 'አረንጓዴ ራስ ዳክዬ', 'ጫጩቶቹ ከተፈለፈሉ በጥቂት ሰዓታት ውስጥ መዋኘትና ራሳቸውን መመገብ ይችላሉ።', 'ዓመቱን ሙሉ በማንኛውም ኩሬ፣ ሐይቅ ወይም ቀስ የሚፈስ ወንዝ።', 'ብትመግቧቸው በዳቦ ፋንታ አጃ፣ አተር ወይም ዘር ተጠቀሙ።', 'በፀደይ ዳክዬዎች ጎጆ በሚሠሩበት ውሃ ውስጥ ውሾችን አታስገቡ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'am', 'ተራ ጭልፊት', 'በሰፊ ክንፎች ይንሳፈፋል፤ ብዙ ጊዜም እንደ ድመት ጩኸት ያለ ድምፅ ያሰማል።', 'ከፀደይ እስከ መኸር፤ ከእርሻና ከደን ዳር በላይ ሲዞር ፈልጉት።', 'አይጦችና ትናንሽ ምርኮዎች የሚኖሩባቸውን ሸካራ ሜዳዎችና የእርሻ ዳርቻዎች ደግፉ።', 'የአይጥ መርዝ በፍጹም አትጠቀሙ — በምግብ ሰንሰለት ወደ አዳኝ ወፎች ይደርሳል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'am', 'ዓሣ አጥማጅ ንስር', 'ዓሣ ለመያዝ በእግሮቹ ቀድሞ ይወርዳል፤ ከክብደቱ ግማሽ የሚሆን ምርኮም መሸከም ይችላል።', 'ከፀደይ እስከ መኸር ከትላልቅ ሐይቆች አጠገብ፤ በአየር ላይ ቆሞ ከዚያ ይወርዳል።', 'ዓሣ በበዛባቸው ሐይቆች አጠገብ በረጃጅም ምሰሶዎች ላይ የጎጆ መድረኮች መሥራትን ደግፉ።', 'ጥንዶቹ እንቁላሎቻቸውን ትተው እንዳይሸሹ ከጎጆ መድረኮች በጣም ራቁ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'am', 'ቀይ ቀበሮ', 'ቀበሮዎች ለተደበቀ ምርኮ የሚያደርጉትን ዝላይ ለመገመት የምድርን መግነጢሳዊ መስክ ይጠቀማሉ።', 'ዓመቱን ሙሉ፤ በተለይ በንጋትና በምሽት በደንና በእርሻ ዳርቻዎች ንቁ ናቸው።', 'የሚያርፉበትና ጉድጓድ የሚቆፍሩበት ጸጥ ያለ የዱር ጥግ ተውላቸው።', 'የቆሻሻ መያዣዎችን ዝጉ፤ ጎጂ የምግብ ትራፊ በፍጹም አትተዉላቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'am', 'የአውሮፓ ጃርት', 'ጃርት በአንድ ሌሊት ምግብ ፍለጋ ሁለት ኪሎ ሜትር ሊጓዝ ይችላል።', 'ከፀደይ እስከ መኸር ከጨለማ በኋላ፤ በክረምት ከቅጠልና ከግንድ ክምር ስር ይተኛል።', 'በአጥሩ ላይ 13 ሴሜ ክፍተት ስሩ፤ በአትክልቶች መካከል እንዲንቀሳቀስ።', 'ረጅም ሳር ከመቁረጥዎ በፊት ይመልከቱ፤ ለክረምት እንቅልፍም የቅጠል ክምር ተዉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'am', 'ትንሽ ድኩላ', 'እርግዝናቸውን ያዘገያሉ፤ ስለዚህ ግልገሎቻቸው ሁልጊዜ በበጋ መጀመሪያ ይወለዳሉ።', 'ዓመቱን ሙሉ በደን ዳርቻዎች፤ በንጋትና በምሽት ሲግጡ በይበልጥ ይታያሉ።', 'መጠለያና ምግብ የሚሰጡ ያልታጨዱ የእርሻ ዳርቻዎችንና ቁጥቋጦዎችን ደግፉ።', 'በበጋ መጀመሪያ ግልገሎች ተደብቀው ሲተኙ ውሾችን ከደን አጠገብ አስሩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'am', 'ትልቅ ድኩላ (ሙስ)', 'በምድር ላይ ትልቁ ድኩላ ነው፤ ትልቅ ወንድ ከግማሽ ቶን በላይ ይመዝናል።', 'ዓመቱን ሙሉ በደንና በእርጥብ መሬቶች፤ በንጋትና በምሽት በይበልጥ ንቁ።', 'ለመንቀሳቀስ የሚያስፈልጋቸውን የተያያዙ ደኖችና የእርጥብ መሬት መተላለፊያዎች ደግፉ።', 'በደን መንገዶች በንጋትና በምሽት በጥንቃቄ ንዱ፤ ወደ ግልገል በፍጹም አትቅረቡ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'am', 'ቀይ ሽኮኮ', 'በርካታ ጎጆዎችን ይሠራሉ፤ በመካከላቸውም ይንቀሳቀሳሉ።', 'ዓመቱን ሙሉ በጥድና በተቀላቀሉ ደኖች፤ በጠዋት በይበልጥ ንቁ።', 'የሚመገቡባቸውንና ጎጆ የሚሠሩባቸውን ኮኖች፣ ለውዞችና የቆሙ ዛፎች ተውዋቸው።', 'ውሾችን በመንገድ ላይ ያቆዩ፤ ጎጆ ሊኖርባቸው የሚችሉ ዛፎችንም አትረብሹ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'am', 'የአውሮፓ ቢቨር', 'የቢቨር ግድቦች ዓሣን፣ ወፎችንና ነፍሳትን ለኪሎ ሜትሮች የሚያበዙ እርጥብ መሬቶችን ይፈጥራሉ።', 'ከፀደይ እስከ መኸር መጨረሻ በቀስታ በሚፈሱ ወንዞች ዙሪያ፤ በምሽት በይበልጥ ንቁ።', 'ደህንነቱ በተጠበቀበት ቦታ ግድቦችና የውሃ ዳር ዛፎች እንዲቆዩ ደግፉ።', 'ከመኖሪያና ከግድብ ራቁ፤ በተለይ ግልገሎቹ ትንንሽ ሲሆኑ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'am', 'የተራራ ጥንቸል', 'በክረምት በበረዶ ላይ ለመሸሸግ ፀጉራቸው ነጭ ይሆናል።', 'ዓመቱን ሙሉ በክፍት መሬትና በደን ክፍት ቦታዎች፤ በአብዛኛው በንጋትና በምሽት።', 'ዓመቱን ሙሉ የሚያስፈልጋቸውን የክፍት መሬትና የመጠለያ ቅይጥ ደግፉ።', 'የሚያርፉ ጥንቸሎች እንዳይባረሩ በክፍት መሬት ውሾችን አስሩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'am', 'የአውሮፓ ባጀር', 'ለትውልዶች በሚያገለግሉ የመሬት ውስጥ ጉድጓዶች በቤተሰብ ቡድን ይኖራሉ።', 'ከፀደይ እስከ መኸር ከጨለማ በኋላ ከደን አጠገብ፤ ክረምቱን በእንቅልፍ ያሳልፋሉ።', 'ጉድጓድ የሚቆፍሩባቸውን ያልተረበሹ ዳርቻዎችና አጥሮች ተውዋቸው።', 'በሥራ ላይ ያለን ጉድጓድ በፍጹም አትዝጉ ወይም አጠገቡ አትቆፍሩ — ዘላቂ ቤታቸው ነው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'am', 'ትንሽ የሌሊት ወፍ', 'ይህ ትንሽ የሌሊት ወፍ በአንድ ሌሊት እስከ 3,000 ትንኞችን መብላት ይችላል።', 'በበጋ ምሽቶች ከአትክልት በላይ ፈጣንና ጠመዝማዛ በረራውን ተመልከቱ።', 'የምሽት ፀሐይ በሚያገኝ ግድግዳ ወይም ዛፍ ላይ ከፍ አድርጋችሁ የሌሊት ወፍ ሳጥን ስቀሉ።', 'በመጠለያ መግቢያዎች ላይ ደማቅ ብርሃን አስወግዱ፤ የሌሊቱንም ሰማይ ጨለማ አድርጉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'am', 'ትንሽ የኤሊ ቅርፊት ቢራቢሮ', 'ይህች ቢራቢሮ ጎልማሳ ሆና ትተኛለች፤ ብዙ ጊዜም በመጋዘንና በጣሪያ ክፍሎች።', 'ከፀደይ መጀመሪያ እስከ መኸር በፀሐያማ አበቦች ላይ፤ በተለይ በሚያሳክክ ቅጠል።', 'በፀሐያማ ጥግ የሚያሳክክ ቅጠል ተውላት — ትሎቿ ያስፈልጓቸዋል።', 'በመጋዘን ውስጥ በክረምት የሚተኙ ቢራቢሮዎችን አትረብሹ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'am', 'የጣዎስ ቢራቢሮ', 'እንደ ዓይን የሚመስሉ ነጠብጣቦቿ ወፎችን ያስደነግጣሉ፤ ክንፎቿም ሲከፈቱ ድምፅ ያሰማሉ።', 'ከፀደይ እስከ መኸር በፀሐያማ ቀናት፤ በእሾህ አበባና በወደቀ ፍራፍሬ ትመገባለች።', 'ለትሎቿ የፀሐይ የሚያሳክክ ቅጠል እንዲያድግ ተውት።', 'በክረምት በመጋዘንና በእንጨት ክምር የሚጠለሉ ጎልማሶችን አትረብሹ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'am', 'ድኝ ቀለም ቢራቢሮ', 'የእንግሊዝኛው "butterfly" ቃል ከዚህ ዝርያ ወንድ ቅቤ-ቢጫ ቀለም የመጣ ሊሆን ይችላል።', 'ከፀደይ የመጀመሪያ ቢራቢሮዎች አንዷ ናት፤ በሞቃት ቀናት በደን ዳር ፈልጓት።', 'ትሎቿ የሚበሉትን ብቸኛ ተክል በአጥር ውስጥ ደግፉ።', 'ጎልማሶች በክረምት የሚጠለሉባቸውን ቁጥቋጦ ያላቸው አጥሮች አታጽዱ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'am', 'ብርቱካናማ ጫፍ ቢራቢሮ', 'ወንዶቹ ብቻ ደማቅ ብርቱካናማ የክንፍ ጫፍ አላቸው፤ ሴቶቹ ነጭ ናቸው።', 'በፀደይ በእርጥብ ሜዳዎችና በመንገዶች ዳር የዱር አበቦች በሚበቅሉበት።', 'የዱር አበቦች በእርጥብና ባልታጨዱ ጥጎች እንዲያድጉ ተውዋቸው።', 'ትሎቹ መመገብ እስኪጨርሱ ድረስ የመንገድ ዳር ማጨድን አዘግዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'am', 'ተራ ሰማያዊ ቢራቢሮ', 'ጉንዳኖች አንዳንዴ ለጣፋጭ ፈሳሻቸው ሲሉ ትሎቿን ይንከባከባሉ።', 'ከፀደይ መጨረሻ ጀምሮ በክሎቨር በበለጸጉ ፀሐያማ ሜዳዎች።', 'ክሎቨሮች እንዲያብቡ ሜዳውን አታጭዱ።', 'በዱር አበቦች የበለጸጉ ሜዳዎችን በአረም ገዳይ አትርጩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'am', 'አረንጓዴ ደም ስር ነጭ ቢራቢሮ', 'የጎመን ቢራቢሮን ብትመስልም የአትክልት ሰብል ሳይሆን የዱር ተክሎችን ትመርጣለች።', 'ከፀደይ እስከ በጋ መጨረሻ በእርጥብ ሜዳዎች፣ በቦዮችና በደን መንገዶች።', 'እርጥብ ጥጎች በአገር በቀል የዱር ተክሎች እንዲሞሉ ተውዋቸው።', 'የምትራባባቸውን እርጥብ ሜዳዎች አታድርቁ አትርጩም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'am', 'ሰባት ነጥብ ያለው ጥንዚዛ', 'አንዲት ጥንዚዛ በሕይወት ዘመኗ ሺዎችን ትናንሽ ተባዮች ትበላለች።', 'ከፀደይ እስከ መኸር ተባይ ባለባቸው ተክሎች ላይ፤ በክረምት ተሰብስበው ይተኛሉ።', 'ጥቂት ተባይ ታገሱና አትርጩ፤ ምግብ እንዲኖራቸው።', 'በክረምት የሚጠለሉባቸውን ባዶ ግንዶችና የወደቁ ቅጠሎች ተውዋቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'am', 'ቢጫ ጅራት ትልቅ ንብ', 'ንግስቶቹ በፀደይ ከመጀመሪያዎቹ ንቦች ናቸው፤ የጎጆ ጉድጓድ ፍለጋ ዝቅ ብለው ያንጎራጉራሉ።', 'ከፀደይ መጀመሪያ እስከ መኸር በአበቦች ላይ፤ ንግስቶቹ በፀደይ የአጥር ስርን ይፈትሻሉ።', 'ቀድመው የሚያብቡ ተክሎችን ተክሉ ወይም ተውዋቸው፤ ክሎቨርም በሳር ላይ እንዲያብብ ተውት።', 'ቅኝ ግዛቶች ጎጆ የሚሠሩባቸውን ያልተረበሹ ዳርቻዎችና የቆዩ የአይጥ ጉድጓዶች ተውዋቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'am', 'የማር ንብ', 'ምግብ ፈላጊዋ ንብ ስምንት በሚመስል ጭፈራ አበቦች የት እንዳሉ ለቀፎው ትነግራለች።', 'ከፀደይ እስከ መኸር በአበቦች ላይ በሞቃትና ነፋስ በሌለበት ቀናት።', 'የተለያዩ አበቦች በወቅቶች ሁሉ እንዲያብቡ ተውና ጥልቀት የሌለው የውሃ ሳህን አስቀምጡ።', 'ያበቡ ተክሎችን አትርጩ፤ በቀትርም በፍጹም አትርጩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'am', 'ንጉሠ ነገሥት የውሃ ተርብ', 'በአውሮፓ ካሉት ትልቁ አንዱ ነው፤ ምርኮን በአየር ላይም መያዝ ይችላል።', 'በሞቃት የበጋ ቀናት በኩሬዎችና በሐይቅ ዳርቻዎች ሲዘዋወር ተመልከቱ።', 'ተክል ያለበት ኩሬ ጠብቁ ወይም ቆፍሩ፤ ዳርቻዎቹንም በተክል ተውዋቸው።', 'ጫጩቶቹ እንዲያድጉ ኩሬዎችን ከብክለት ጠብቁ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'am', 'ተራ ትንሽ የውሃ ተርብ', 'ብዙ ጊዜ በዚያው ሞቃት ቦታ ላይ ያርፍና የሚያልፉ ነፍሳትን ለመያዝ ይዘላል።', 'ከበጋ አጋማሽ እስከ መኸር ከጸጥ ካለ ውሃ አጠገብ፤ በመንገዶችና በምሰሶዎች ላይ ይሞቃል።', 'በኩሬዎችና በቦዮች ዙሪያ ፀሐያማ ማረፊያዎችንና ተክሎችን ተውዋቸው።', 'ማዳበሪያ ወይም ዘይት ጫጩቶች ወደሚኖሩባቸው ኩሬዎች እንዳይገባ ተጠንቀቁ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'am', 'ቀይ የደን ጉንዳን', 'የጎጆ ክምራቸው ከአንድ ሜትር በላይ ሊረዝምና ግማሽ ሚሊዮን ጉንዳኖችን ሊይዝ ይችላል።', 'ከፀደይ እስከ መኸር በጥድ ደኖች፤ ከመርፌ ቅጠል የተሠሩ ጉልላታማ ክምሮችን ፈልጉ።', 'የጎጆ ክምሮችን እንዳሉ ተውዋቸው — ለመሥራት ዓመታት ይወስዳል።', 'በመንገድ ላይ ቆዩ፤ የጉንዳን ክምርን በፍጹም አትምቱ አትቆፍሩም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'am', 'የደን ነጭ አበባ', 'በጣም ቀስ ብሎ ስለሚስፋፋ ጥቅጥቅ ያለ ምንጣፍ የጥንት ደን ምልክት ነው።', 'በፀደይ ዛፎች ቅጠል ከማውጣታቸው በፊት የነጭ አበባ ምንጣፎችን ፈልጉ።', 'ቀስ ብለው የሚስፋፉ ሥሮች እንዲያድጉ የደኑን መሬት እንዳለ ተውት።', 'በሚበቅሉበት ቦታ ተደሰቱባቸው — መቁረጥ ዓመታት የፈጀ አበባን ያስወግዳል።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'am', 'የሸለቆ አበባ', 'የዚህ ጥሩ መዓዛ ያለው ተክል እያንዳንዱ ክፍል ቢበላ መርዛማ ነው።', 'በፀደይ መጨረሻ መዓዛውን ተከትላችሁ ወደ ጥላማ ደኖች ሂዱ።', 'የሚበቅልበትን ጥላማ የደን ዳርቻና የወደቁ ቅጠሎች ተውዋቸው።', 'አትቁረጡት አትንቀሉትም፤ ከልጆችና ከቤት እንስሳት አርቁት።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'am', 'የዱር ነጭ ሽንኩርት', 'ብዙ ጊዜ ነጭ አበባዎቹን ከማየታችሁ በፊት ሽታውን ታሸታላችሁ።', 'በፀደይ በእርጥብ ደኖች ሰፊ አረንጓዴ ቅጠሎችንና ኮከባማ አበቦችን ፈልጉ።', 'ምንጣፎቹ በየዓመቱ እንዲያድጉ እርጥቡን ደን እንዳለ ተውት።', 'በአካባቢው ከተፈቀደ ጥቂት ውሰዱ፤ ሥሮቹን በፍጹም አትንቀሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'am', 'የረግረግ ወርቃማ አበባ', 'ከጥንታዊ አገር በቀል ተክሎች አንዱ ነው፤ በስካንዲኔቪያ የመጨረሻውን የበረዶ ዘመን ተርፏል።', 'በፀደይ በረግረግ፣ በቦዮችና በኩሬ ዳር ትላልቅ ወርቃማ አበቦችን ፈልጉ።', 'እንዲያብብ የኩሬና የቦይ ዳርቻዎችን እርጥብና ያልታጨደ አድርጉ።', 'እርጥብ መሬትን አታድርቁ፤ ተክሎቹንም በሚበቅሉበት ተውዋቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'am', 'የፀደይ ቢጫ አበባ', 'በአንድ ወቅት በሜዳዎች በጣም የተለመዱ ስለነበሩ ልጆች ኳስ ይሠሩባቸው ነበር።', 'በፀደይ በቆዩ ባልተሻሻሉ ሜዳዎች ያጎነበሱ ቢጫ አበቦችን ፈልጉ።', 'እስኪያብቡና ዘር እስኪይዙ ድረስ ሜዳዎችን አታጭዱ።', 'ከተፈጥሮ አትቁረጡ አትንቀሉም — የሜዳ አበቦች እየቀነሱ ናቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'am', 'ትልቅ ነጭ አበባ', 'እንደ አንድ አበባ የሚታየው በእውነቱ በአንድ ላይ የተሰበሰቡ በርካታ ጥቃቅን አበቦች ናቸው።', 'በበጋ በመንገድ ዳርና በሜዳዎች ትላልቅ ነጭ አበቦችን ፈልጉ።', 'እንዲያብብ በበጋ አጋማሽ አንድ የሳር መስመር ሳይታጨድ ተውት።', 'የመንገድ ዳርቻዎችንና ሜዳዎችን በአረም ገዳይ አትርጩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'am', 'የዳንደሊዮን አበባ', 'ለንቦች ከቀዳሚዎቹ የማር ምንጮች አንዱ ነው።', 'ከፀደይ ጀምሮ በሁሉም ቦታ ማለት ይቻላል፤ አበቦቹ በፀሐይ ይከፈታሉ በምሽትም ይዘጋሉ።', 'በፀደይ ከመጀመሪያው ማጨድ በፊት በሳር ላይ እንዲያብቡ ተውዋቸው።', 'ቀዳሚ የአበባ ዱቄት አዘዋዋሪዎች ይህን ወሳኝ ምግብ እንዲያገኙ የሳር አረም ገዳይ አትጠቀሙ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'am', 'የሜዳ ቁጥቋጦ', 'አንድ ተክል ከመቶ ሺህ በላይ ጥቃቅን ዘሮችን ማምረት ይችላል።', 'በበጋ መጨረሻ በክፍት ሜዳዎችና በረግረግ ወይንጠጅ ምንጣፎችን ፈልጉ።', 'እነዚህ ቦታዎች ክፍትና ሳይደርቁ እንዲቆዩ ደግፉ።', 'በመንገድ ላይ ቆዩ፤ በደረቅ አየርም በፍጹም እሳት አታቃጥሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'am', 'ሰማያዊ የዱር ፍሬ', 'ጣቶቻችሁን ሰማያዊ ያደርጋል፤ ከወፎች እስከ ድቦችም ሁሉንም ይመግባል።', 'በበጋ በጥድና በስፕሩስ ደኖች ጥቁር ፍሬ ያላቸውን ዝቅተኛ ቁጥቋጦዎች ፈልጉ።', 'ቁጥቋጦዎቹ እንዲያፈሩ የደኑን የታችኛ ተክል እንዳለ ተውት።', 'በአካባቢው መልቀም ከተፈቀደ ለዱር እንስሳት በቂ ፍሬ ተውዋቸው።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'am', 'ቀይ የዱር ፍሬ', 'በፍሬው ውስጥ ባለ ተፈጥሯዊ ጠባቂ ንጥረ ነገር ምክንያት ለወራት ይቆያል።', 'በበጋ መጨረሻና በመኸር በዘላለም አረንጓዴ ምንጣፎች ላይ የሚያብረቀርቁ ቀይ ፍሬዎችን ፈልጉ።', 'ምንጣፎቹ እንዲስፋፉ የደኑን የመሬት ተክል እንዳለ ተውት።', 'መልቀም ከተፈቀደ ተክሎቹን እንዳትረግጡ በጥንቃቄ ራመዱ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'am', 'የብር በርች ዛፍ', 'አንድ በርች በመቶዎች የሚቆጠሩ የነፍሳት ዝርያዎችን ይመግባል፤ እነሱም ስፍር ቁጥር የሌላቸውን ወፎች።', 'ዓመቱን ሙሉ፤ የሚላጠው ነጭ ቅርፊቱ በማንኛውም ወቅት ለመለየት ቀላል ያደርገዋል።', 'አፈርን እንዲያበለጽግና ነፍሳትን እንዲመግብ የወደቁ ቅጠሎችንና የሞተ እንጨት ተውዋቸው።', 'ቅርፊቱን አትላጡ፤ ዛፉን ይጎዳል ያዳክማልም።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'am', 'የኖርዌይ ስፕሩስ ዛፍ', 'በስዊድን ያለ አንድ ስፕሩስ ከሺዎች ዓመታት ዕድሜ ካላቸው ሥሮች ይበቅላል።', 'ዓመቱን ሙሉ በደኖች፤ የተንጠለጠሉ ኮኖቹ ከሁሉም ስፕሩሶች ረጅሙ ናቸው።', 'ለነፍሳትና ለፈንገሶች መጠለያ የሆኑ የወደቁ ኮኖችንና የሞተ እንጨት ተውዋቸው።', 'የስፕሩሱ ጥልቀት የሌላቸው ሥሮች እንዳይጨመቁ በደን ውስጥ በመንገድ ላይ ቆዩ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'am', 'የስኮትላንድ ጥድ', 'የቆዩ ጥዶች ከጫፍ አካባቢ ብርቱካናማ ያበራሉ፤ ለዘመናትም ሊኖሩ ይችላሉ።', 'ዓመቱን ሙሉ በአሸዋማና በድንጋያማ መሬት፤ የላይኛውን ብርቱካናማ ቅርፊት ፈልጉ።', 'በሕይወት የበለጸጉ የቆሙ የሞቱ እንጨቶችንና የቆዩ ጥዶች ተውዋቸው።', 'በደረቅ አሸዋማ መሬት ከጥዶች አጠገብ በፍጹም እሳት አታቃጥሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'am', 'የሰሜን ፓይክ ዓሣ', 'ተደብቆ የሚያደን አዳኝ ነው፤ ከፍጹም ጸጥታ በቅጽበት ይዘላል።', 'ከፀደይ እስከ መኸር በሐይቆችና በቀስታ በሚፈሱ ወንዞች ሳር በበዛበት ጥልቀት የሌለው ውሃ።', 'ትናንሽ ዓሦች የሚጠለሉባቸውን የሸምበቆ ጥልቀት የሌላቸው ቦታዎችና የውሃ ተክሎች መጠበቅን ደግፉ።', 'ብክለትንና ቆሻሻን ከውሃ አርቁ፤ የአካባቢውን የዓሣ ማጥመድ ሕጎች ተከተሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'am', 'የአውሮፓ ፐርች ዓሣ', 'በመንጋ ያድናሉ፤ ደማቅ ጭረቶቻቸውም የሰውነታቸውን ቅርጽ ይሰብራሉ።', 'በሞቃት ወራት በመትከያዎች፣ በውሃ ሳር አካባቢና በጥልቀት መውረጃዎች ዙሪያ።', 'ትናንሽ ዓሦችን የሚጠብቁ ንጹህ ውሃና በውሃ ውስጥ ያሉ መዋቅሮች ደግፉ።', 'ወደ ሐይቆችና ወንዞች ምንም አትጣሉ፤ የአካባቢውን ሕጎች ተከተሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'am', 'ሮች ዓሣ', 'ብዙ የሐይቅ አዳኞች የሚተማመኑበት ወሳኝ የምግብ ዓሣ ነው።', 'በሞቃት ወራት በሐይቆችና በቀስታ በሚፈሱ ወንዞች ወለል አጠገብ በመንጋ።', 'ለመራባት ንጹህ ውሃና በተክል የተሸፈኑ ዳርቻዎችን ደግፉ።', 'የሚፈስ ውሃንና ቆሻሻን ከውሃ አርቁ፤ የአካባቢውን ሕጎች ተከተሉ።') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'pl', 'Jerzyk zwyczajny', 'Jerzyki potrafią miesiącami nie siadać na ziemi, a nawet śpią w locie.', 'W ciepłe letnie wieczory patrz wysoko nad dachy i nasłuchuj krzykliwych stad.', 'Zawieś budkę dla jerzyków pod okapem, zanim ptaki wrócą wiosną.', 'Podczas remontu zachowaj wąskie szczeliny pod okapem, w których jerzyki gniazdują.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'pl', 'Dymówka', 'Dymówki co roku wędrują aż na południe Afryki i wracają.', 'Od wiosny do wczesnej jesieni szukaj ich nisko nad polami i wodą.', 'Zostaw uchylone drzwi stodoły lub szopy, by mogły dolecieć do gniazd.', 'Nie strącaj starych glinianych gniazd — jaskółki używają ich rok po roku.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'pl', 'Kukułka zwyczajna', 'Kukułka składa jaja w gniazdach innych ptaków i nigdy sama nie wychowuje piskląt.', 'Późną wiosną nasłuchuj dalekiego "ku-ku" dochodzącego ze skraju lasu.', 'Wspieraj bogate w owady łąki i żywopłoty, które karmią ptaki-gospodarzy.', 'Trzymaj się ścieżek przy zaroślach i trzcinowiskach, by nie płoszyć gospodarzy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'pl', 'Rudzik', 'Rudziki zaciekle bronią terytorium i śpiewają nocą przy latarniach.', 'Cały rok w ogrodach i lasach; często chodzą za kopiącym ziemię, licząc na dżdżownice.', 'Zostaw kąt ogrodu z opadłymi liśćmi, gdzie mogą szukać pokarmu.', 'Odłóż mocne cięcie żywopłotu do końca lęgów późnym latem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'pl', 'Kos zwyczajny', 'Bogaty, fletowy śpiew samca należy do najbardziej rozpoznawalnych w Europie.', 'Cały rok; o świcie i zmierzchu słuchaj samców śpiewających z dachów i koron drzew.', 'Wystaw świeżą wodę do picia i kąpieli, zwłaszcza w czasie suszy.', 'W sezonie lęgowym trzymaj koty w domu o świcie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'pl', 'Kwiczoł', 'Kwiczoł to towarzyski drozd, który zimą wędruje hałaśliwymi stadami.', 'Jesienią i zimą obserwuj stada obierające owoce z żywopłotów i jarzębin.', 'Nie przycinaj krzewów owocujących przez całą zimę.', 'Zostaw zimą opadłe jabłka na ziemi — w mróz to kluczowy pokarm.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'pl', 'Bogatka', 'Bogatki mają ogromny repertuar głosów i uczą się nowych od sąsiadów.', 'Cały rok; od późnej zimy słuchaj dźwięcznej, powtarzanej piosenki.', 'Powieś budkę z otworem 32 mm w cichym, zacienionym miejscu.', 'Unikaj ogrodowych pestycydów, by starczyło gąsienic na wykarmienie piskląt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'pl', 'Modraszka', 'Jeden lęg modraszek potrafi zjeść ponad tysiąc gąsienic.', 'Cały rok w ogrodach i lasach, często wiszą głową w dół na cienkich gałązkach.', 'Zawieś małą budkę z otworem 25 mm z dala od przeważających wiatrów.', 'Wiosną odpuść insektycydy, by gąsienice były dostępne dla piskląt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'pl', 'Zięba zwyczajna', 'Śpiew zięby różni się w zależności od okolicy, niemal jak lokalne gwary.', 'Od wiosny do jesieni; samce śpiewają jasną, opadającą frazę z odkrytych gałęzi.', 'Zostaw część kwiatostanów nasiennych i kęp traw stojących przez sezon.', 'Utrzymuj karmniki w czystości, by nie roznosić chorób wśród ptaków.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'pl', 'Sójka zwyczajna', 'Każdej jesieni zakopuje tysiące żołędzi i, zapominając część, sadzi całe dąbrowy.', 'Cały rok w dąbrowach; jesienią wypatruj błysków różu i błękitu.', 'Zostaw opadłe żołędzie i ściółkę pod dębami nienaruszone.', 'Trzymaj psy na ścieżkach w lesie, by nie płoszyć ptaków żerujących na ziemi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'pl', 'Dzięcioł duży', 'Wiosenne bębnienie to nie zdobywanie pokarmu, lecz szybki rytm obwieszczający terytorium.', 'Cały rok; późną zimą nasłuchuj bębnienia niosącego się po lesie.', 'Zostaw stojące martwe drewno, w którym żyją owady stanowiące jego pokarm.', 'Nie wycinaj drzew martwych ani zamierających — mogą kryć dziuple lęgowe.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'pl', 'Pliszka siwa', 'Nieustanne kiwanie ogonem może sygnalizować drapieżnikom czujność.', 'Od wiosny do jesieni przy wodzie i na otwartym gruncie; biegnie i przystaje, chwytając owady.', 'Zachowaj przy wodzie kawałek niskiej trawy lub żwiru, gdzie może żerować.', 'Nie zakłócaj żwirowych brzegów, na których żeruje i gniazduje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'pl', 'Żuraw zwyczajny', 'Wczesną wiosną żurawie tańczą godowo, podskakując i kłaniając się.', 'Od wiosny do jesieni wokół mokradeł; nasłuchuj klangoru niosącego się kilometrami.', 'Wspieraj ochronę nieosuszonych torfowisk i wilgotnych łąk, gdzie żurawie lęgną się.', 'Obserwuj lęgowe mokradła z daleka — spłoszony żuraw porzuca gniazdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'pl', 'Łabędź krzykliwy', 'Łabędzie krzykliwe łączą się w pary na całe życie i przylot obwieszczają głośnym trąbieniem.', 'Wiosną i jesienią na jeziorach i zalanych polach, często w grupach rodzinnych.', 'Wspieraj zachowanie płytkich brzegów jezior i wilgotnych pól bez osuszania.', 'Nigdy nie karm łabędzi chlebem — szkodzi im; na lodzie też zachowaj dystans.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'pl', 'Krzyżówka', 'Kaczęta pływają i same żerują już kilka godzin po wykluciu.', 'Cały rok na niemal każdym stawie, jeziorze czy wolno płynącej rzece.', 'Jeśli karmisz kaczki, użyj owsa, grochu lub nasion zamiast chleba.', 'Wiosną trzymaj psy z dala od wody, gdzie kaczki mają gniazda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'pl', 'Myszołów zwyczajny', 'Myszołów szybuje na szerokich skrzydłach i często woła głosem podobnym do miauknięcia.', 'Od wiosny do jesieni; wypatruj go krążącego wysoko nad polami i skrajem lasu.', 'Wspieraj szorstkie murawy i miedze, w których żyją norniki i drobna zdobycz.', 'Nigdy nie używaj trutek na gryzonie — łańcuchem pokarmowym trafiają do ptaków drapieżnych.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'pl', 'Rybołów', 'Rybołów nurkuje nogami do przodu i uniesie zdobycz o połowie własnej masy.', 'Od wiosny do jesieni przy dużych jeziorach; najpierw zawisa w powietrzu, potem nurkuje.', 'Wspieraj stawianie platform lęgowych na wysokich słupach przy jeziorach bogatych w ryby.', 'Omijaj platformy lęgowe szerokim łukiem, by pary nie porzuciły jaj.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'pl', 'Lis rudy', 'Lisy wykorzystują pole magnetyczne Ziemi, by ocenić skok na ukrytą zdobycz.', 'Cały rok, najaktywniejsze o świcie i zmierzchu na skraju lasów i pól.', 'Zostaw dziki, spokojny kąt, gdzie lisy mogą odpoczywać i kopać norę.', 'Zabezpiecz kosze na śmieci i nigdy nie zostawiaj lisom szkodliwych resztek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'pl', 'Jeż zachodni', 'Jeż potrafi w ciągu jednej nocy przejść kilka kilometrów w poszukiwaniu pokarmu.', 'Od wiosny do jesieni po zmroku; zimą śpi pod stertami liści i kłód.', 'Wytnij w płocie otwór 13 cm, by jeże mogły przechodzić między ogrodami.', 'Sprawdź wysoką trawę przed koszeniem i zostaw sterty liści na zimowanie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'pl', 'Sarna europejska', 'Sarny opóźniają ciążę, by koźlęta rodziły się zawsze wczesnym latem.', 'Cały rok na skraju lasów, najlepiej widoczne przy żerowaniu o świcie i zmierzchu.', 'Wspieraj niekoszone miedze i zarośla dające schronienie i pokarm.', 'Wczesnym latem, gdy koźlęta leżą ukryte, prowadź psy na smyczy przy lesie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'pl', 'Łoś euroazjatycki', 'Łoś to największy jeleniowaty na Ziemi; duży byk waży ponad pół tony.', 'Cały rok w lasach i na mokradłach, najaktywniejszy o świcie i zmierzchu.', 'Wspieraj połączone lasy i korytarze mokradeł, których łoś potrzebuje do wędrówek.', 'Jedź ostrożnie o świcie i zmierzchu drogami leśnymi i nigdy nie zbliżaj się do młodego.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'pl', 'Wiewiórka pospolita', 'Wiewiórki budują kilka gniazd i przenoszą się między nimi.', 'Cały rok w lasach iglastych i mieszanych, najruchliwsze wczesnym rankiem.', 'Zostaw szyszki, orzechy i stojące drzewa, w których żerują i gniazdują.', 'Trzymaj psy na ścieżkach i nie niepokój drzew mogących kryć gniazdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'pl', 'Bóbr europejski', 'Tamy bobrów tworzą mokradła, które na kilometry zwiększają liczbę ryb, ptaków i owadów.', 'Od wiosny do późnej jesieni przy wolnych rzekach, najaktywniejsze o zmierzchu.', 'Wspieraj pozostawianie tam i nadwodnych drzew tam, gdzie jest to bezpieczne.', 'Trzymaj się z dala od żeremi i tam, zwłaszcza gdy młode są małe.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'pl', 'Zając bielak', 'Zimą bielaki bieleją dla maskowania na śniegu.', 'Cały rok na otwartym terenie i leśnych polanach, głównie o świcie i zmierzchu.', 'Wspieraj mozaikę otwartego terenu i osłony, której potrzebują przez cały rok.', 'Prowadź psy na smyczy na otwartym terenie, by nie goniły odpoczywających zajęcy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'pl', 'Borsuk europejski', 'Borsuki żyją w grupach rodzinnych w podziemnych norach użytkowanych przez pokolenia.', 'Od wiosny do jesieni po zmroku w pobliżu lasu; zimę przesypiają.', 'Zostaw nienaruszone skarpy i żywopłoty, gdzie borsuki mogą kopać nory.', 'Nigdy nie zasypuj czynnej nory ani nie kop obok — to ich wieloletni dom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'pl', 'Karlik malutki', 'Ten maleńki nietoperz potrafi zjeść w ciągu nocy do 3000 muszek i komarów.', 'Letnimi wieczorami obserwuj szybki, zygzakowaty lot o zmierzchu nad ogrodami.', 'Zawieś budkę dla nietoperzy wysoko na ścianie lub drzewie, gdzie sięga wieczorne słońce.', 'Unikaj jasnego światła przy wlotach kryjówek i zachowaj ciemne nocne niebo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'pl', 'Rusałka pokrzywnik', 'Ten motyl zimuje jako owad dorosły, często w szopach i na strychach.', 'Od wczesnej wiosny do jesieni na słonecznych kwiatach, zwłaszcza na pokrzywach.', 'Zostaw kępę pokrzyw w słonecznym kącie — jego gąsienice ich potrzebują.', 'Nie niepokój motyli zimujących w szopach przez całą zimę.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'pl', 'Rusałka pawik', 'Oczkowe plamy błyskają, płosząc ptaki, a skrzydła przy otwieraniu potrafią syczeć.', 'Od wiosny do jesieni w słoneczne dni, żeruje na ostach i opadłych owocach.', 'Pozwól słonecznej kępie pokrzyw rosnąć dla jego gąsienic.', 'Nie niepokój dorosłych zimujących w szopach i stosach drewna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'pl', 'Latolistek cytrynek', 'Angielskie słowo "butterfly" mogło powstać od maślanożółtej barwy samca tego gatunku.', 'Jeden z pierwszych motyli wiosny; w ciepłe dni szukaj go na skraju lasu.', 'Wspieraj krzewy kruszyny w żywopłotach — jedyne rośliny, które jedzą jego gąsienice.', 'Nie wycinaj zakrzewionych żywopłotów, w których zimują dorosłe motyle.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'pl', 'Zorzynek rzeżuchowiec', 'Tylko samce mają jaskrawopomarańczowe końce skrzydeł; samice są białe.', 'Wiosną wzdłuż wilgotnych łąk i dróg, gdzie rośnie rzeżucha łąkowa.', 'Pozwól rzeżusze i czosnaczkowi rosnąć w wilgotnych, niekoszonych kątach.', 'Odłóż koszenie poboczy, aż gąsienice skończą żerowanie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'pl', 'Modraszek ikar', 'Gąsienicami modraszka opiekują się czasem mrówki dla ich słodkiej wydzieliny.', 'Od późnej wiosny na słonecznych murawach bogatych w koniczynę i komonicę.', 'Zostaw murawę niekoszoną, by koniczyny i komonice mogły zakwitnąć.', 'Nie opryskuj herbicydem muraw bogatych w dzikie kwiaty.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'pl', 'Bielinek bytomkowiec', 'Choć przypomina bielinka kapustnika, woli rośliny dziko rosnące niż uprawy.', 'Od wiosny do późnego lata na wilgotnych łąkach, w rowach i na leśnych duktach.', 'Pozwól wilgotnym kątom zdziczeć z rodzimymi krzyżowymi.', 'Nie osuszaj i nie opryskuj wilgotnych łąk, na których się rozmnaża.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'pl', 'Biedronka siedmiokropka', 'Jedna biedronka może w ciągu życia zjeść tysiące mszyc.', 'Od wiosny do jesieni na roślinach z mszycami; zimą gromadzą się na zimowanie.', 'Znieś trochę mszyc i odpuść opryski, by biedronki miały co jeść.', 'Zostaw puste łodygi i opadłe liście, w których biedronki chronią się zimą.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'pl', 'Trzmiel ziemny', 'Królowe należą do pierwszych pszczół wiosny; nisko brzęczą, szukając nor na gniazdo.', 'Od wczesnej wiosny do jesieni na kwiatach; wiosną królowe przeszukują podstawy żywopłotów.', 'Sadź lub zostaw wcześnie kwitnące rośliny i pozwól koniczynie zakwitnąć w trawniku.', 'Zostaw nienaruszone skarpy i stare nory myszy, w których gniazdują kolonie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'pl', 'Pszczoła miodna', 'Zbieraczki wskazują ulowi miejsce kwiatów, tańcząc w kształcie ósemki.', 'Od wiosny do jesieni na kwiatach w ciepłe, bezwietrzne dni.', 'Pozwól różnym kwiatom kwitnąć przez cały sezon i postaw płytkie naczynie z wodą.', 'Nie opryskuj kwitnących roślin i nigdy nie opryskuj w środku dnia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'pl', 'Husarz władca', 'To jedna z największych ważek Europy; potrafi chwytać zdobycz nawet w locie.', 'W ciepłe letnie dni obserwuj, jak patroluje stawy i brzegi jezior.', 'Utrzymuj lub wykop staw z roślinami i zostaw brzegi zarośnięte.', 'Chroń stawy przed zanieczyszczeniem i spływami, by larwy mogły się rozwijać.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'pl', 'Szablak zwyczajny', 'Często siada w tym samym ciepłym miejscu i wylatuje, chwytając przelatujące owady.', 'Od połowy lata do jesieni przy stojącej wodzie, wygrzewa się na ścieżkach i słupkach.', 'Zostaw słoneczne miejsca do siadania i roślinność wokół stawów i rowów.', 'Nie dopuszczaj, by nawozy lub oleje spływały do stawów, w których żyją larwy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'pl', 'Mrówka rudnica', 'Ich kopce mogą mieć ponad metr wysokości i mieścić pół miliona mrówek.', 'Od wiosny do jesieni w borach; szukaj kopulastych kopców z igliwia.', 'Zostaw mrowiska nienaruszone — ich budowa trwa lata.', 'Trzymaj się ścieżek i nigdy nie kop ani nie rozgrzebuj mrowiska.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'pl', 'Zawilec gajowy', 'Zawilce rozprzestrzeniają się tak wolno, że gęste kobierce znamionują stary las.', 'Wiosną szukaj kobierców białych kwiatów, zanim drzewa wypuszczą liście.', 'Zostaw dno lasu nienaruszone, by wolno rosnące kłącza mogły się rozwijać.', 'Podziwiaj je tam, gdzie rosną — zerwanie usuwa kwiat, który rósł latami.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'pl', 'Konwalia majowa', 'Każda część tej pachnącej rośliny jest trująca po zjedzeniu.', 'Późną wiosną idź za zapachem do cienistych lasów i zacienionych ogrodów.', 'Zostaw cieniste skraje lasu i ściółkę tam, gdzie rośnie.', 'Nie zrywaj jej ani nie wykopuj; trzymaj z dala od dzieci i zwierząt domowych.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'pl', 'Czosnek niedźwiedzi', 'Czosnek niedźwiedzi zwykle czuje się węchem, zanim zobaczy się jego białe kwiaty.', 'Wiosną szukaj szerokich zielonych liści i gwiazdkowatych kwiatów w wilgotnych lasach.', 'Zostaw wilgotny las nienaruszony, by kobierce odrastały co roku.', 'Jeśli zbiór jest lokalnie dozwolony, bierz niewiele i nigdy nie wykopuj cebul.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'pl', 'Knieć błotna', 'Jedna z najstarszych rodzimych roślin; przetrwała ostatnią epokę lodowcową w Skandynawii.', 'Wiosną szukaj dużych złotych kwiatów na bagnach, w rowach i przy brzegach stawów.', 'Utrzymuj brzegi stawów i rowów wilgotne i niekoszone, by mogła zakwitnąć.', 'Nie osuszaj wilgotnego gruntu i zostaw rośliny tam, gdzie rosną.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'pl', 'Pierwiosnek lekarski', 'Pierwiosnki bywały na łąkach tak pospolite, że dzieci robiły z nich kule.', 'Wiosną szukaj zwisających żółtych kwiatów na starych, nienawożonych łąkach.', 'Nie koś łąk, dopóki pierwiosnki nie przekwitną i nie zawiążą nasion.', 'Nie zrywaj ich ani nie wykopuj z natury — kwiatów łąkowych ubywa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'pl', 'Jastrun właściwy', 'To, co wygląda na jeden kwiat, to w rzeczywistości dziesiątki maleńkich kwiatków razem.', 'Latem szukaj dużych białych margerytek przy drogach i na łąkach.', 'Zostaw pas trawy niekoszony przez pełnię lata, by mogła zakwitnąć.', 'Nie opryskuj herbicydem poboczy i łąk.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'pl', 'Mniszek lekarski', 'Mniszek to jedno z najważniejszych wczesnych źródeł nektaru dla pszczół.', 'Od wiosny niemal wszędzie; kwiaty otwierają się w słońcu i zamykają o zmierzchu.', 'Pozwól mniszkom zakwitnąć w trawniku wiosną przed pierwszym koszeniem.', 'Odpuść herbicydy do trawnika, by wczesne zapylacze zachowały ten kluczowy pokarm.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'pl', 'Wrzos zwyczajny', 'Jedna roślina wrzosu może wytworzyć ponad sto tysięcy maleńkich nasion.', 'Późnym latem szukaj fioletowych kobierców na otwartych wrzosowiskach i torfowiskach.', 'Wspieraj utrzymanie wrzosowisk otwartych i nieosuszonych.', 'Trzymaj się ścieżek na wrzosowiskach i nigdy nie rozpalaj ognia przy suszy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'pl', 'Borówka czarna', 'Borówki barwią palce na niebiesko i karmią wszystkich, od ptaków po niedźwiedzie.', 'Latem szukaj niskich krzewinek z ciemnymi owocami w borach sosnowych i świerkowych.', 'Zostaw runo leśne nienaruszone, by krzewinki mogły owocować.', 'Jeśli zbiór jest lokalnie dozwolony, zostaw dużo owoców dla zwierząt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'pl', 'Borówka brusznica', 'Borówka brusznica trzyma się miesiącami dzięki naturalnemu konserwantowi w owocach.', 'Późnym latem i jesienią szukaj lśniących czerwonych owoców na wiecznie zielonych kobiercach.', 'Zostaw roślinność dna lasu nienaruszoną, by kobierce mogły się rozrastać.', 'Jeśli zbiór jest dozwolony, stąpaj ostrożnie, by nie zgnieść roślin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'pl', 'Brzoza brodawkowata', 'Brzoza żywi setki gatunków owadów, a te z kolei niezliczone ptaki.', 'Cały rok; biała, łuszcząca się kora czyni ją łatwo rozpoznawalną o każdej porze.', 'Zostaw opadłe liście brzozy i martwe drewno, by wzbogacały glebę i karmiły owady.', 'Unikaj zdzierania kory — rani to i osłabia drzewo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'pl', 'Świerk pospolity', 'Pewien świerk w Szwecji wyrasta z korzeni liczących tysiące lat.', 'Cały rok w lasach; jego zwisające szyszki są najdłuższe ze wszystkich świerków.', 'Zostaw opadłe szyszki i martwe drewno, które dają schronienie owadom i grzybom.', 'Trzymaj się szlaków w lesie, by nie ubijać płytkich korzeni świerka.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'pl', 'Sosna zwyczajna', 'Stare sosny świecą pomarańczowo przy wierzchołku i mogą żyć stulecia.', 'Cały rok na gruntach piaszczystych i skalistych; szukaj pomarańczowej kory u góry pnia.', 'Zostaw stojące martwe drewno i stare sosny — są bogate w życie.', 'Nigdy nie rozpalaj ognia przy sosnach na suchym, piaszczystym gruncie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'pl', 'Szczupak pospolity', 'Szczupak to drapieżnik zasadzkowy, który z bezruchu atakuje w mgnieniu oka.', 'Od wiosny do jesieni w zarośniętych płyciznach jezior i wolnych rzek.', 'Wspieraj zachowanie trzcinowych płycizn i roślin wodnych, gdzie chowa się narybek.', 'Nie dopuszczaj zanieczyszczeń i śmieci do wody; przestrzegaj lokalnych przepisów wędkarskich.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'pl', 'Okoń pospolity', 'Okonie polują w stadach, a wyraziste pręgi rozbijają zarys ich ciała.', 'W cieplejszych miesiącach wokół pomostów, łąk roślinnych i uskoków dna.', 'Wspieraj czystą wodę i podwodne struktury dające schronienie drobnym rybom.', 'Nigdy nic nie wrzucaj do jezior i rzek; przestrzegaj lokalnych przepisów wędkarskich.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'pl', 'Płoć', 'Płoć to kluczowa ryba pokarmowa, od której zależy wiele jeziornych drapieżników.', 'W cieplejszych miesiącach w ławicach przy powierzchni jezior i wolnych rzek.', 'Wspieraj czystą wodę i zarośnięte brzegi potrzebne do tarła.', 'Nie dopuszczaj spływów i śmieci do wody; przestrzegaj lokalnych przepisów wędkarskich.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'de', 'Mauersegler', 'Mauersegler können monatelang in der Luft bleiben und schlafen sogar im Flug.', 'An warmen Sommerabenden hoch über die Dächer schauen und auf die rufenden Trupps hören.', 'Bringen Sie einen Seglerkasten unter der Traufe an, bevor die Vögel im Frühling zurückkehren.', 'Erhalten Sie beim Sanieren die schmalen Spalten unter der Traufe, in denen sie brüten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'de', 'Rauchschwalbe', 'Rauchschwalben ziehen jedes Jahr bis ins südliche Afrika und wieder zurück.', 'Vom Frühling bis zum Frühherbst tief über Feldern und Wasser dahinstreichend zu sehen.', 'Lassen Sie eine Scheunen- oder Schuppentür angelehnt, damit sie zu ihren Nestern gelangen.', 'Schlagen Sie alte Lehmnester nicht ab — Schwalben nutzen sie Jahr für Jahr wieder.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'de', 'Kuckuck', 'Der Kuckuck legt seine Eier in fremde Nester und zieht nie eigene Junge auf.', 'Im Spätfrühling auf den weit tragenden „Kuck-uck“-Ruf vom Waldrand hören.', 'Fördern Sie insektenreiche Wiesen und Hecken, die seine Wirtsvögel ernähren.', 'Bleiben Sie nahe Gebüsch und Schilf auf den Wegen, damit Wirtsvögel ungestört bleiben.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'de', 'Rotkehlchen', 'Rotkehlchen verteidigen ihr Revier heftig und singen bei Straßenlaternen die Nacht hindurch.', 'Ganzjährig in Gärten und Wäldern; oft folgen sie Grabenden in der Hoffnung auf Würmer.', 'Lassen Sie eine Gartenecke mit Falllaub, in der sie nach Nahrung suchen können.', 'Verschieben Sie starken Heckenschnitt, bis die Brutzeit im Spätsommer vorbei ist.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'de', 'Amsel', 'Der volle, flötende Gesang des Männchens gehört zu den bekanntesten Europas.', 'Ganzjährig; in Morgen- und Abenddämmerung singen Männchen von Dächern und Baumwipfeln.', 'Stellen Sie frisches Wasser zum Trinken und Baden bereit, besonders in Trockenzeiten.', 'Halten Sie Katzen zur Brutzeit im Morgengrauen im Haus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'de', 'Wacholderdrossel', 'Die Wacholderdrossel ist gesellig und zieht im Winter in lauten, schackernden Trupps umher.', 'Im Herbst und Winter Trupps beobachten, die Beeren von Hecken und Ebereschen abernten.', 'Schneiden Sie beerentragende Sträucher über den Winter nicht zurück.', 'Lassen Sie Fallobst im Winter liegen — bei Kälte ist es lebenswichtige Nahrung.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'de', 'Kohlmeise', 'Kohlmeisen haben ein großes Lautrepertoire und lernen neue Rufe von Nachbarn.', 'Ganzjährig; ab dem Spätwinter auf den hellen, wiederholten Gesang achten.', 'Hängen Sie einen Nistkasten mit 32-mm-Loch an einen ruhigen, schattigen Platz.', 'Verzichten Sie auf Gartenpestizide, damit genug Raupen für die Jungen bleiben.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'de', 'Blaumeise', 'Eine einzige Blaumeisenbrut kann über tausend Raupen fressen.', 'Ganzjährig in Gärten und Wäldern, oft kopfüber an dünnen Zweigen hängend.', 'Bringen Sie einen kleinen Nistkasten mit 25-mm-Loch abseits der Hauptwindrichtung an.', 'Verzichten Sie im Frühling auf Insektizide, damit Raupen für die Jungen da sind.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'de', 'Buchfink', 'Der Gesang des Buchfinks unterscheidet sich je nach Gegend, fast wie ein Dialekt.', 'Vom Frühling bis Herbst; Männchen singen eine helle, abfallende Strophe von freien Warten.', 'Lassen Sie einen Teil der Samenstände und Krautfluren über die Saison stehen.', 'Halten Sie Futterstellen sauber, damit sich Krankheiten nicht ausbreiten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'de', 'Eichelhäher', 'Jeden Herbst vergräbt er Tausende Eicheln und pflanzt, indem er manche vergisst, ganze Eichenwälder.', 'Ganzjährig im Eichenwald; im Herbst auf rosa und blaue Blitze achten.', 'Lassen Sie heruntergefallene Eicheln und Laub unter Eichen unberührt.', 'Führen Sie Hunde im Wald auf den Wegen, damit Bodenbrüter nicht aufgescheucht werden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'de', 'Buntspecht', 'Das Frühlingstrommeln dient nicht der Nahrungssuche, sondern der Reviermarkierung.', 'Ganzjährig; im Spätwinter auf das durch den Wald hallende Trommeln hören.', 'Lassen Sie stehendes Totholz — darin leben die Insekten, von denen er sich ernährt.', 'Fällen Sie keine toten oder absterbenden Bäume, sie können Bruthöhlen enthalten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'de', 'Bachstelze', 'Das ständige Schwanzwippen signalisiert Fressfeinden womöglich Wachsamkeit.', 'Vom Frühling bis Herbst an Gewässern und offenem Boden; läuft und hält an, um Insekten zu fangen.', 'Erhalten Sie am Wasser eine kurzrasige oder kiesige Fläche zum Nahrungssuchen.', 'Stören Sie Kiesufer nicht, an denen sie fressen und brüten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'de', 'Kranich', 'Im Frühjahr führen Kraniche Balztänze mit Sprüngen und Verbeugungen auf.', 'Vom Frühling bis Herbst an Feuchtgebieten; auf die kilometerweit tragenden Rufe hören.', 'Unterstützen Sie den Schutz unentwässerter Moore und Feuchtwiesen, wo Kraniche brüten.', 'Beobachten Sie Brutgebiete aus der Ferne — gestörte Nester geben Kraniche auf.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'de', 'Singschwan', 'Singschwäne bleiben lebenslang zusammen und künden ihre Ankunft mit lauten Trompetenrufen an.', 'Im Frühling und Herbst auf Seen und überschwemmten Feldern, oft in Familiengruppen.', 'Unterstützen Sie den Erhalt flacher Seeufer und feuchter Felder ohne Entwässerung.', 'Füttern Sie Schwäne nie mit Brot — es schadet ihnen; halten Sie auch auf Eis Abstand.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'de', 'Stockente', 'Küken schwimmen und fressen schon wenige Stunden nach dem Schlüpfen selbstständig.', 'Ganzjährig an fast jedem Teich, See oder langsam fließenden Fluss.', 'Wenn Sie Enten füttern, nehmen Sie Hafer, Erbsen oder Körner statt Brot.', 'Halten Sie Hunde im Frühling aus Gewässern fern, in denen Enten brüten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'de', 'Mäusebussard', 'Der Bussard kreist auf breiten Schwingen und ruft oft katzenartig „hiäh“.', 'Vom Frühling bis Herbst; halten Sie Ausschau nach kreisenden Vögeln über Feldern und Waldrändern.', 'Fördern Sie Raingras und Feldränder, in denen Wühlmäuse und Kleinbeute leben.', 'Verwenden Sie nie Rattengift — es gelangt über die Nahrungskette zu Greifvögeln.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'de', 'Fischadler', 'Der Fischadler stößt mit den Füßen voran ins Wasser und trägt Beute vom halben Eigengewicht.', 'Vom Frühling bis Herbst an großen Seen; erst rüttelnd stehend, dann im Sturzflug.', 'Unterstützen Sie Nistplattformen auf hohen Masten an fischreichen Seen.', 'Halten Sie großen Abstand zu Nistplattformen, damit Paare ihr Gelege nicht aufgeben.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'de', 'Rotfuchs', 'Füchse nutzen das Erdmagnetfeld, um den Sprung auf verborgene Beute abzuschätzen.', 'Ganzjährig, am aktivsten in der Dämmerung an Wald- und Feldrändern.', 'Lassen Sie eine wilde, ruhige Ecke, in der Füchse ruhen und einen Bau graben können.', 'Sichern Sie Mülltonnen und lassen Sie nie schädliche Essensreste für Füchse liegen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'de', 'Braunbrustigel', 'Ein Igel kann in einer einzigen Nacht auf Nahrungssuche einige Kilometer zurücklegen.', 'Vom Frühling bis Herbst nach Einbruch der Dunkelheit; im Winter schläft er unter Laub- und Holzhaufen.', 'Schneiden Sie eine 13 cm große Lücke in den Zaun, damit Igel zwischen Gärten wandern können.', 'Prüfen Sie hohes Gras vor dem Mähen und lassen Sie Laubhaufen für den Winterschlaf.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'de', 'Reh', 'Rehe verzögern die Trächtigkeit, damit die Kitze stets im Frühsommer geboren werden.', 'Ganzjährig an Waldrändern, am besten beim Äsen in der Dämmerung zu sehen.', 'Fördern Sie ungemähte Feldränder und Gebüsch, die Deckung und Nahrung bieten.', 'Führen Sie Hunde im Frühsommer am Waldrand an der Leine, wenn Kitze versteckt liegen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'de', 'Elch', 'Der Elch ist der größte Hirsch der Erde; ein starker Bulle wiegt über eine halbe Tonne.', 'Ganzjährig in Wäldern und Feuchtgebieten, am aktivsten in der Dämmerung.', 'Unterstützen Sie vernetzte Wälder und Feuchtkorridore, die Elche zum Wandern brauchen.', 'Fahren Sie auf Waldwegen in der Dämmerung vorsichtig und nähern Sie sich nie einem Kalb.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'de', 'Eichhörnchen', 'Eichhörnchen bauen mehrere Kobel und wechseln zwischen ihnen.', 'Ganzjährig in Nadel- und Mischwäldern, am regsten am frühen Morgen.', 'Lassen Sie Zapfen, Nüsse und stehende Bäume, in denen sie fressen und nisten.', 'Führen Sie Hunde auf den Wegen und stören Sie keine Bäume mit möglichem Kobel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'de', 'Europäischer Biber', 'Biberdämme schaffen Feuchtgebiete, die auf Kilometern Fische, Vögel und Insekten fördern.', 'Vom Frühling bis Spätherbst an langsamen Flüssen, am aktivsten in der Dämmerung.', 'Unterstützen Sie, dass Dämme und Ufergehölze bleiben, wo es sicher ist.', 'Halten Sie Abstand zu Burgen und Dämmen, besonders wenn die Jungen klein sind.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'de', 'Schneehase', 'Im Winter wird das Fell weiß, zur Tarnung im Schnee.', 'Ganzjährig auf offenem Gelände und Waldlichtungen, vor allem in der Dämmerung.', 'Fördern Sie das Nebeneinander von Offenland und Deckung, das sie ganzjährig brauchen.', 'Führen Sie Hunde im Offenland an der Leine, damit ruhende Hasen nicht gehetzt werden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'de', 'Europäischer Dachs', 'Dachse leben in Familiengruppen in unterirdischen Bauen, die über Generationen genutzt werden.', 'Vom Frühling bis Herbst nach Dunkelheit nahe Wäldern; den Winter verschlafen sie weitgehend.', 'Lassen Sie ungestörte Böschungen und Hecken, in denen Dachse Baue graben können.', 'Verschließen Sie nie einen bewohnten Bau und graben Sie nicht daneben — er ist ihr dauerhaftes Zuhause.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'de', 'Zwergfledermaus', 'Diese winzige Fledermaus frisst in einer Nacht bis zu 3.000 Mücken.', 'An Sommerabenden den schnellen, zickzackartigen Flug in der Dämmerung über Gärten beobachten.', 'Hängen Sie einen Fledermauskasten hoch an eine Wand oder einen Baum mit Abendsonne.', 'Vermeiden Sie helles Licht an Quartiereingängen und halten Sie den Nachthimmel dunkel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'de', 'Kleiner Fuchs', 'Dieser Falter überwintert als erwachsenes Tier, oft in Schuppen und Dachböden.', 'Vom Frühjahr bis Herbst an sonnigen Blüten, besonders an Brennnesseln.', 'Lassen Sie eine Brennnesselecke in der Sonne stehen — seine Raupen brauchen sie.', 'Stören Sie überwinternde Falter in Schuppen den Winter über nicht.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'de', 'Tagpfauenauge', 'Die Augenflecken blitzen auf, um Vögel zu erschrecken, und die Flügel können beim Öffnen zischen.', 'Vom Frühling bis Herbst an Sonnentagen, an Disteln und Fallobst saugend.', 'Lassen Sie eine sonnige Brennnesselflur für seine Raupen wachsen.', 'Stören Sie erwachsene Falter nicht, die den Winter in Schuppen und Holzstößen verbringen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'de', 'Zitronenfalter', 'Das englische Wort „butterfly“ soll von der buttergelben Farbe des Männchens stammen.', 'Einer der ersten Falter des Frühjahrs; an warmen Tagen an Waldrändern suchen.', 'Fördern Sie Faulbaum in Hecken, die einzigen Pflanzen, die seine Raupen fressen.', 'Roden Sie keine verbuschten Hecken, in denen erwachsene Falter überwintern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'de', 'Aurorafalter', 'Nur die Männchen haben leuchtend orange Flügelspitzen; die Weibchen sind weiß.', 'Im Frühling an feuchten Wiesen und Wegen, wo Wiesenschaumkraut wächst.', 'Lassen Sie Wiesenschaumkraut und Knoblauchsrauke in feuchten, ungemähten Ecken wachsen.', 'Verschieben Sie das Mähen der Bankette, bis die Raupen ausgewachsen sind.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'de', 'Hauhechel-Bläuling', 'Seine Raupen werden manchmal von Ameisen betreut, die deren süßes Sekret nutzen.', 'Ab dem Spätfrühling auf sonnigem Grasland, reich an Klee und Hornklee.', 'Lassen Sie Grasland ungemäht, damit Klee und Hornklee blühen können.', 'Spritzen Sie blütenreiches Grasland nicht mit Herbiziden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'de', 'Grünader-Weißling', 'Obwohl er dem Kohlweißling ähnelt, bevorzugt er Wildpflanzen statt Gartenkulturen.', 'Vom Frühling bis Spätsommer auf feuchten Wiesen, in Gräben und auf Waldwegen.', 'Lassen Sie feuchte Ecken mit heimischen Kreuzblütlern verwildern.', 'Entwässern und spritzen Sie keine feuchten Wiesen, in denen er sich fortpflanzt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'de', 'Siebenpunkt-Marienkäfer', 'Ein einzelner Marienkäfer kann in seinem Leben Tausende Blattläuse fressen.', 'Vom Frühling bis Herbst an Pflanzen mit Blattläusen; im Winter überwintern sie in Gruppen.', 'Dulden Sie ein paar Blattläuse und verzichten Sie auf Spritzmittel, damit Marienkäfer Futter haben.', 'Lassen Sie hohle Stängel und Falllaub, in denen Marienkäfer überwintern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'de', 'Dunkle Erdhummel', 'Königinnen gehören zu den ersten Bienen im Frühjahr und brummen tief auf Nistplatzsuche.', 'Vom Vorfrühling bis Herbst an Blüten; im Frühjahr suchen Königinnen Heckenfüße ab.', 'Pflanzen oder belassen Sie früh blühende Pflanzen und lassen Sie Klee im Rasen blühen.', 'Lassen Sie ungestörte Böschungen und alte Mäuselöcher, in denen Völker nisten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'de', 'Westliche Honigbiene', 'Sammlerinnen zeigen dem Stock mit einem Achtertanz, wo Blüten stehen.', 'Vom Frühling bis Herbst an Blüten an warmen, windstillen Tagen.', 'Lassen Sie über die Jahreszeiten verschiedene Blüten blühen und stellen Sie eine flache Wasserschale auf.', 'Spritzen Sie keine blühenden Pflanzen und nie in der Mittagszeit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'de', 'Große Königslibelle', 'Eine der größten Libellen Europas; sie fängt Beute sogar im Flug.', 'An warmen Sommertagen patrouilliert sie über Teichen und Seeufern.', 'Erhalten oder graben Sie einen bepflanzten Teich und lassen Sie die Ufer bewachsen.', 'Halten Sie Teiche frei von Verschmutzung und Abschwemmungen, damit sich Larven entwickeln.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'de', 'Große Heidelibelle', 'Sie sitzt oft auf derselben warmen Stelle und stößt nach vorbeifliegenden Insekten vor.', 'Vom Hochsommer bis Herbst an stehenden Gewässern, sonnend auf Wegen und Pfosten.', 'Lassen Sie sonnige Sitzwarten und Bewuchs rund um Teiche und Gräben.', 'Verhindern Sie, dass Dünger oder Öl in Teiche gelangt, in denen Larven leben.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'de', 'Rote Waldameise', 'Ihre Nesthügel können über einen Meter hoch sein und eine halbe Million Ameisen beherbergen.', 'Vom Frühling bis Herbst in Nadelwäldern; nach kuppelförmigen Nadelhügeln Ausschau halten.', 'Lassen Sie Nesthügel unberührt — ihr Bau dauert Jahre.', 'Bleiben Sie auf den Wegen und treten oder graben Sie nie in einen Ameisenhügel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'de', 'Buschwindröschen', 'Buschwindröschen breiten sich so langsam aus, dass dichte Teppiche alten Wald anzeigen.', 'Im Frühling nach weißen Blütenteppichen suchen, bevor die Bäume austreiben.', 'Lassen Sie den Waldboden unberührt, damit die langsam kriechenden Rhizome gedeihen.', 'Erfreuen Sie sich daran, wo sie wachsen — Pflücken nimmt eine Blüte, die Jahre brauchte.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'de', 'Maiglöckchen', 'Alle Teile dieser duftenden Pflanze sind beim Verzehr giftig.', 'Im Spätfrühling dem Duft in schattige Wälder und Gärten folgen.', 'Lassen Sie schattige Waldränder und Falllaub dort, wo sie wächst.', 'Pflücken oder graben Sie sie nicht aus; halten Sie sie von Kindern und Haustieren fern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'de', 'Bärlauch', 'Bärlauch riecht man meist, bevor man die weißen Blüten sieht.', 'Im Frühling nach breiten grünen Blättern und sternförmigen Blüten in feuchten Wäldern suchen.', 'Lassen Sie feuchte Wälder unberührt, damit die Teppiche jedes Jahr neu wachsen.', 'Wo Sammeln erlaubt ist, nehmen Sie wenig und graben Sie nie die Zwiebeln aus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'de', 'Sumpfdotterblume', 'Eine der ältesten heimischen Pflanzen; sie überstand die letzte Eiszeit in Skandinavien.', 'Im Frühling nach großen goldenen Blüten in Sümpfen, Gräben und Teichrändern suchen.', 'Halten Sie Teich- und Grabenränder feucht und ungemäht, damit sie blühen kann.', 'Entwässern Sie feuchte Standorte nicht und lassen Sie die Pflanzen dort, wo sie wachsen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'de', 'Echte Schlüsselblume', 'Schlüsselblumen waren auf Heuwiesen einst so häufig, dass Kinder Bälle daraus formten.', 'Im Frühling nach nickenden gelben Blüten auf alten, ungedüngten Wiesen suchen.', 'Mähen Sie Wiesen erst, wenn die Schlüsselblumen verblüht sind und Samen angesetzt haben.', 'Pflücken oder graben Sie sie nicht aus der Natur — Wiesenblumen gehen zurück.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'de', 'Margerite', 'Was wie eine Blüte aussieht, sind in Wahrheit Dutzende winziger Einzelblüten.', 'Im Sommer nach großen weißen Margeriten an Wegrändern und auf Wiesen suchen.', 'Lassen Sie im Hochsommer einen Grasstreifen ungemäht, damit sie blühen kann.', 'Spritzen Sie Bankette und Wiesen nicht mit Herbiziden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'de', 'Löwenzahn', 'Der Löwenzahn ist eine der wichtigsten frühen Nektarquellen für Bienen.', 'Ab dem Frühling fast überall; die Blüten öffnen sich in der Sonne und schließen abends.', 'Lassen Sie Löwenzahn im Frühling vor dem ersten Mähen im Rasen blühen.', 'Verzichten Sie auf Rasenherbizide, damit frühe Bestäuber diese wichtige Nahrung behalten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'de', 'Besenheide', 'Eine einzige Heidepflanze kann über hunderttausend winzige Samen bilden.', 'Im Spätsommer nach violetten Teppichen auf offenen Heiden und Mooren suchen.', 'Unterstützen Sie, dass Heiden offen und unentwässert bleiben.', 'Bleiben Sie auf Heiden auf den Wegen und machen Sie bei Trockenheit nie Feuer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'de', 'Heidelbeere', 'Heidelbeeren färben die Finger blau und ernähren alles von Vögeln bis zu Bären.', 'Im Sommer nach niedrigen Sträuchern mit dunklen Beeren in Kiefern- und Fichtenwäldern suchen.', 'Lassen Sie die Waldbodenvegetation unberührt, damit die Zwergsträucher fruchten können.', 'Wo Sammeln erlaubt ist, lassen Sie reichlich Beeren für die Tierwelt.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'de', 'Preiselbeere', 'Preiselbeeren halten sich monatelang dank eines natürlichen Konservierungsstoffs in der Frucht.', 'Im Spätsommer und Herbst nach glänzend roten Beeren auf immergrünen Teppichen suchen.', 'Lassen Sie die Waldbodenvegetation unberührt, damit sich die Teppiche ausbreiten.', 'Wo Sammeln erlaubt ist, treten Sie vorsichtig auf, um die Pflanzen nicht zu zerdrücken.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'de', 'Hängebirke', 'Eine Birke ernährt Hunderte Insektenarten, die wiederum unzählige Vögel versorgen.', 'Ganzjährig; die weiße, sich schälende Rinde macht sie zu jeder Jahreszeit leicht erkennbar.', 'Lassen Sie Falllaub und Totholz liegen, um den Boden zu bereichern und Insekten zu nähren.', 'Schälen Sie keine Rinde ab — das verletzt und schwächt den Baum.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'de', 'Gemeine Fichte', 'Eine Fichte in Schweden wächst aus Wurzeln, die Tausende Jahre alt sind.', 'Ganzjährig in Wäldern; ihre hängenden Zapfen sind die längsten aller Fichten.', 'Lassen Sie heruntergefallene Zapfen und Totholz, das Insekten und Pilzen Unterschlupf bietet.', 'Bleiben Sie im Wald auf den Pfaden, um die flachen Fichtenwurzeln nicht zu verdichten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'de', 'Waldkiefer', 'Alte Kiefern leuchten im oberen Stammbereich orange und können Jahrhunderte alt werden.', 'Ganzjährig auf sandigen und felsigen Böden; auf die orange Rinde oben achten.', 'Lassen Sie stehendes Totholz und alte Kiefern — sie sind reich an Leben.', 'Machen Sie auf trockenem Sandboden nie Feuer an oder nahe Kiefern.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'de', 'Hecht', 'Der Hecht ist ein Lauerjäger, der aus völliger Ruhe blitzschnell vorstößt.', 'Vom Frühling bis Herbst im krautigen Flachwasser von Seen und langsamen Flüssen.', 'Unterstützen Sie den Erhalt von Schilfflachwasser und Wasserpflanzen, wo Jungfische Schutz finden.', 'Halten Sie Verschmutzung und Müll aus dem Wasser; befolgen Sie örtliche Angelregeln.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'de', 'Flussbarsch', 'Barsche jagen im Schwarm; ihre kräftigen Streifen lösen die Körperkontur auf.', 'In den wärmeren Monaten an Stegen, Krautfeldern und Kanten.', 'Unterstützen Sie sauberes Wasser und Unterwasserstrukturen, die Kleinfischen Schutz bieten.', 'Werfen Sie nie etwas in Seen und Flüsse; befolgen Sie örtliche Angelregeln.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'de', 'Rotauge', 'Das Rotauge ist ein wichtiger Futterfisch, von dem viele Seeräuber abhängen.', 'In den wärmeren Monaten in Schwärmen nahe der Oberfläche von Seen und langsamen Flüssen.', 'Unterstützen Sie sauberes Wasser und bewachsene Ufer für das Laichen.', 'Halten Sie Abschwemmungen und Müll aus dem Wasser; befolgen Sie örtliche Angelregeln.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'fi', 'Tervapääsky', 'Tervapääskyt voivat pysyä ilmassa kuukausia ja nukkuvat jopa lentäessään.', 'Lämpiminä kesäiltoina katso korkealle kattojen yli ja kuuntele kirkuvia parvia.', 'Asenna pesäpönttö räystään alle ennen kuin linnut palaavat keväällä.', 'Säilytä remontoidessasi räystään alla olevat pienet raot, joissa ne pesivät.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'fi', 'Haarapääsky', 'Haarapääskyt muuttavat joka vuosi aina eteläiseen Afrikkaan ja takaisin.', 'Keväästä alkusyksyyn niitä näkee liitämässä matalalla peltojen ja veden yllä.', 'Jätä ladon tai vajan ovi raolleen, jotta ne pääsevät pesäpaikoilleen.', 'Älä pudota vanhoja savipesiä — pääskyt käyttävät niitä vuodesta toiseen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'fi', 'Käki', 'Käki munii muiden lintujen pesiin eikä koskaan kasvata omia poikasiaan.', 'Loppukeväästä kuuntele kauas kantautuvaa "kukkuu"-huutoa metsänreunasta.', 'Tue hyönteisrikkaita niittyjä ja pensasaitoja, jotka ruokkivat isäntälintuja.', 'Pysy poluilla pensaikkojen ja ruovikoiden lähellä, jottei isäntälintuja häiritä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'fi', 'Punarinta', 'Punarinnat puolustavat reviiriään kiivaasti ja laulavat yön yli katuvalojen lähellä.', 'Ympäri vuoden puutarhoissa ja metsissä; usein ne seuraavat maata kaivavaa toivoen matoja.', 'Jätä puutarhan nurkkaan karikekerros, josta ne voivat etsiä ravintoa.', 'Siirrä raskas pensasaidan leikkuu loppukesään, kun pesintä on ohi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'fi', 'Mustarastas', 'Koiraan täyteläinen, huilumainen laulu on Euroopan tunnistettavimpia.', 'Ympäri vuoden; kuuntele aamun ja illan hämärissä koiraita katoilta ja puiden latvoista.', 'Aseta raikasta vettä juomiseen ja kylpemiseen, etenkin kuivina jaksoina.', 'Pidä kissat sisällä aamuhämärissä pesimäaikaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'fi', 'Räkättirastas', 'Räkättirastas on seurallinen ja liikkuu talvella meluisina, rähisevinä parvina.', 'Syksyllä ja talvella katso parvia, jotka riipivät marjoja pensasaidoista ja pihlajista.', 'Älä leikkaa marjovia pensaita talven aikana.', 'Jätä pudonneet omenat maahan talvella — pakkasella ne ovat elintärkeää ravintoa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'fi', 'Talitiainen', 'Talitiaisilla on laaja äänivarasto, ja ne oppivat uusia ääniä naapureiltaan.', 'Ympäri vuoden; loppitalvesta kuuntele kirkasta, toistuvaa laulua.', 'Ripusta pönttö, jonka lentoaukko on 32 mm, rauhalliseen ja varjoisaan paikkaan.', 'Vältä puutarhan torjunta-aineita, jotta toukkia riittää poikasten ruokkimiseen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'fi', 'Sinitiainen', 'Yksi sinitiaispoikue voi syödä yli tuhat toukkaa.', 'Ympäri vuoden puutarhoissa ja metsissä, usein roikkuen ylösalaisin ohuilla oksilla.', 'Aseta pieni pönttö, jonka lentoaukko on 25 mm, suojaan vallitsevalta tuulelta.', 'Jätä hyönteismyrkyt keväällä pois, jotta toukkia riittää poikasille.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'fi', 'Peippo', 'Peipon laulu vaihtelee alueittain, melkein kuin paikallinen murre.', 'Keväästä syksyyn; koiraat laulavat kirkkaan, laskevan säkeen avoimilta oksilta.', 'Jätä osa siemenkodista ja heinikoista pystyyn kauden ajaksi.', 'Pidä ruokintapaikat puhtaina, jottei tauteja leviä lintujen kesken.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'fi', 'Närhi', 'Närhi hautaa joka syksy tuhansia tammenterhoja ja istuttaa unohtamalla osan kokonaisia tammimetsiä.', 'Ympäri vuoden tammimetsissä; syksyllä tarkkaile vaaleanpunaisia ja sinisiä välähdyksiä.', 'Jätä pudonneet terhot ja karike tammien alle koskematta.', 'Pidä koirat metsässä polulla, jottei maassa ruokailevia lintuja säikäytetä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'fi', 'Käpytikka', 'Kevään rummutus ei ole ravinnonhakua vaan nopea rytmi, jolla se ilmoittaa reviiristään.', 'Ympäri vuoden; loppitalvesta kuuntele metsässä kaikuvaa rummutusta.', 'Jätä pystyyn kuollutta puuta, jossa elävät sen ravinnoksi käyvät hyönteiset.', 'Älä kaada kuolleita tai kuolevia puita, joissa voi olla pesäkoloja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'fi', 'Västäräkki', 'Jatkuva pyrstön heiluttelu saattaa viestiä valppaudesta saalistajille.', 'Keväästä syksyyn veden äärellä ja avoimella maalla; juoksee ja pysähtyy nappaamaan hyönteisiä.', 'Säilytä veden lähellä lyhyttä nurmea tai soraa, josta se voi etsiä ravintoa.', 'Älä häiritse sorarantoja, joilla se ruokailee ja pesii.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'fi', 'Kurki', 'Alkukeväästä kurjet tanssivat soidintanssia hypellen ja kumartaen.', 'Keväästä syksyyn kosteikoilla; kuuntele kilometrien päähän kantautuvaa torvimaista huutoa.', 'Tue ojittamattomien soiden ja kosteiden niittyjen suojelua, joilla kurjet pesivät.', 'Tarkkaile pesimäkosteikkoja kaukaa — häiritty kurki hylkää pesänsä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'fi', 'Laulujoutsen', 'Laulujoutsenet pariutuvat eliniäkseen ja ilmoittavat saapumisensa kovilla torvimaisilla huudoilla.', 'Keväällä ja syksyllä järvillä ja tulvapelloilla, usein perhekunnittain.', 'Tue matalien järvenrantojen ja kosteiden peltojen säilymistä ojittamattomina.', 'Älä koskaan syötä joutsenille leipää — se vahingoittaa niitä; pidä jäälläkin etäisyys.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'fi', 'Sinisorsa', 'Poikaset uivat ja ruokailevat itse jo tuntien kuluttua kuoriutumisesta.', 'Ympäri vuoden lähes millä tahansa lammella, järvellä tai hitaassa joessa.', 'Jos ruokit sorsia, käytä kauraa, herneitä tai siemeniä leivän sijaan.', 'Pidä koirat keväällä poissa vedestä, jossa sorsat pesivät.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'fi', 'Hiirihaukka', 'Hiirihaukka liitää leveillä siivillä ja huutaa usein kissamaisesti.', 'Keväästä syksyyn; etsi sitä kaartelemassa korkealla peltojen ja metsänreunojen yllä.', 'Tue karkeita niittyjä ja peltojen reunuksia, joissa elää myyriä ja pikkusaalista.', 'Älä koskaan käytä jyrsijämyrkkyä — se kulkeutuu ravintoketjussa petolintuihin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'fi', 'Sääksi', 'Sääksi syöksyy jalat edellä ja kantaa saalista, joka painaa puolet sen omasta painosta.', 'Keväästä syksyyn suurten järvien äärellä; ensin se liikkuu paikallaan ilmassa, sitten syöksyy.', 'Tue tekopesälavojen rakentamista korkeille pylväille kalaisten järvien lähelle.', 'Kierrä pesälavat kaukaa, jottei pari hylkää muniaan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'fi', 'Kettu', 'Ketut käyttävät Maan magneettikenttää arvioidessaan hyppyä piilossa olevan saaliin päälle.', 'Ympäri vuoden, aktiivisimmillaan hämärissä metsän- ja pellonreunoilla.', 'Jätä villi, rauhallinen nurkka, jossa ketut voivat levätä ja kaivaa pesän.', 'Sulje roska-astiat äläkä koskaan jätä ketuille haitallisia ruoantähteitä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'fi', 'Siili', 'Siili voi kulkea yhden yön ravinnonhaussa pari kilometriä.', 'Keväästä syksyyn pimeän tultua; talvella se nukkuu lehti- ja risukasojen alla.', 'Tee aitaan 13 cm aukko, jotta siilit pääsevät liikkumaan puutarhojen välillä.', 'Tarkista pitkä heinä ennen niittoa ja jätä lehtikasat talvihorrosta varten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'fi', 'Metsäkauris', 'Metsäkauriit viivyttävät tiineyttä, jotta vasat syntyvät aina alkukesällä.', 'Ympäri vuoden metsänreunoilla, parhaiten näkyvissä laiduntaessaan hämärissä.', 'Tue niittämättömiä pellonreunuksia ja pensaikkoja, jotka antavat suojaa ja ravintoa.', 'Pidä koirat kytkettyinä metsän lähellä alkukesällä, kun vasat makaavat piilossa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'fi', 'Hirvi', 'Hirvi on maailman suurin hirvieläin; iso uros painaa yli puoli tonnia.', 'Ympäri vuoden metsissä ja soilla, aktiivisimmillaan hämärissä.', 'Tue yhtenäisiä metsiä ja kosteikkokäytäviä, joita hirvi tarvitsee liikkumiseen.', 'Aja metsäteillä hämärissä varovasti äläkä koskaan lähesty vasaa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'fi', 'Orava', 'Oravat rakentavat useita pesiä ja siirtyvät niiden välillä.', 'Ympäri vuoden havu- ja sekametsissä, vilkkaimmillaan varhain aamulla.', 'Jätä kävyt, pähkinät ja pystyssä olevat puut, joissa ne ruokailevat ja pesivät.', 'Pidä koirat polulla äläkä häiritse puita, joissa voi olla pesä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'fi', 'Euroopanmajava', 'Majavan padot luovat kosteikkoja, jotka lisäävät kaloja, lintuja ja hyönteisiä laajalti.', 'Keväästä myöhäissyksyyn hitaiden jokien varsilla, aktiivisimmillaan iltahämärissä.', 'Tue patojen ja rantapuiden säilyttämistä siellä, missä se on turvallista.', 'Pysy etäällä pesistä ja padoista, etenkin kun poikaset ovat pieniä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'fi', 'Metsäjänis', 'Talvella metsäjänis valkenee suojavärikseen lumelle.', 'Ympäri vuoden avomailla ja metsäaukioilla, pääosin hämärissä.', 'Tue avomaan ja suojan vaihtelua, jota ne tarvitsevat läpi vuoden.', 'Pidä koirat kytkettyinä avomaalla, jottei levähtäviä jäniksiä ajeta takaa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'fi', 'Mäyrä', 'Mäyrät elävät perhekunnittain maanalaisissa pesissä, joita käytetään sukupolvien ajan.', 'Keväästä syksyyn pimeän tultua metsän lähellä; talven ne nukkuvat pois.', 'Jätä koskemattomat töyräät ja pensasaidat, joihin mäyrät voivat kaivaa pesän.', 'Älä koskaan tuki käytössä olevaa pesää tai kaiva sen viereen — se on niiden pysyvä koti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'fi', 'Kääpiölepakko', 'Tämä pikkuinen lepakko voi syödä yhdessä yössä jopa 3 000 sääskeä ja hyttystä.', 'Kesäiltoina tarkkaile nopeaa, mutkittelevaa lentoa hämärissä puutarhojen yllä.', 'Ripusta lepakkopönttö korkealle seinään tai puuhun, johon iltapäivän aurinko osuu.', 'Vältä kirkkaita valoja piilopaikkojen suulla ja pidä yötaivas pimeänä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'fi', 'Nokkosperhonen', 'Tämä perhonen talvehtii aikuisena, usein vajoissa ja ullakoilla.', 'Alkukeväästä syksyyn aurinkoisilla kukilla, etenkin nokkosilla.', 'Jätä nokkoskasvusto aurinkoiseen nurkkaan — sen toukat tarvitsevat sitä.', 'Älä häiritse vajoissa talvehtivia perhosia talven aikana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'fi', 'Neitoperhonen', 'Silmäkuviot välähtävät säikyttääkseen lintuja, ja siivet voivat sihistä avautuessaan.', 'Keväästä syksyyn aurinkoisina päivinä, ruokailee ohdakkeilla ja pudonneilla hedelmillä.', 'Anna aurinkoisen nokkoskasvuston kasvaa sen toukille.', 'Älä häiritse aikuisia, jotka talvehtivat vajoissa ja puupinoissa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'fi', 'Sitruunaperhonen', 'Englannin sana "butterfly" saattaa juontua tämän lajin koiraan voinkeltaisesta väristä.', 'Yksi kevään ensimmäisistä perhosista; etsi sitä lämpiminä päivinä metsänreunoilta.', 'Tue paatsamapensaita pensasaidoissa — ainoa kasvi, jota sen toukat syövät.', 'Älä raivaa pensoittuneita aitoja, joissa aikuiset talvehtivat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'fi', 'Auroraperhonen', 'Vain koirailla on kirkkaanoranssit siivenkärjet; naaraat ovat valkoisia.', 'Keväällä kosteilla niityillä ja teiden varsilla, missä kasvaa niittyluhtaa.', 'Anna niittykasvien kasvaa kosteissa, niittämättömissä nurkissa.', 'Siirrä pientareiden niittoa, kunnes toukat ovat lopettaneet syömisen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'fi', 'Niittysinisiipi', 'Muurahaiset hoitavat toisinaan sen toukkia näiden makean erityksen vuoksi.', 'Loppukeväästä aurinkoisilla nurmilla, joilla kasvaa runsaasti apilaa.', 'Jätä nurmi niittämättä, jotta apilat ehtivät kukkia.', 'Älä ruiskuta rikkakasvimyrkkyä kukkarikkaille nurmille.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'fi', 'Lanttuperhonen', 'Vaikka se muistuttaa kaaliperhosta, se suosii luonnonkasveja puutarhakasvien sijaan.', 'Keväästä loppukesään kosteilla niityillä, ojissa ja metsäurilla.', 'Anna kosteiden nurkkien villiintyä kotimaisilla ristikukkaisilla.', 'Älä ojita tai ruiskuta kosteita niittyjä, joilla se lisääntyy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'fi', 'Seitsenpistepirkko', 'Yksi leppäkerttu voi syödä elinaikanaan tuhansia kirvoja.', 'Keväästä syksyyn kirvaisilla kasveilla; talvella ne kerääntyvät talvehtimaan.', 'Siedä hieman kirvoja ja jätä ruiskutukset väliin, jotta leppäkertuille riittää ravintoa.', 'Jätä ontot varret ja karike, joissa leppäkertut suojautuvat talveksi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'fi', 'Mantukimalainen', 'Kuningattaret ovat kevään ensimmäisiä mehiläisiä ja surisevat matalalla pesäkoloja etsien.', 'Alkukeväästä syksyyn kukilla; keväällä kuningattaret tutkivat pensasaitojen tyviä.', 'Kasvata tai jätä aikaisin kukkivia kasveja ja anna apilan kukkia nurmikolla.', 'Jätä koskemattomat töyräät ja vanhat hiirenkolot, joihin yhdyskunnat pesivät.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'fi', 'Mehiläinen', 'Keruumehiläiset kertovat pesälle kukkien sijainnin tanssimalla kahdeksikkoa.', 'Keväästä syksyyn kukilla lämpiminä ja tyyninä päivinä.', 'Anna eri kukkien kukkia läpi kausien ja aseta matala vesiastia.', 'Älä ruiskuta kukkivia kasveja äläkä koskaan keskellä päivää.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'fi', 'Keisarikorento', 'Yksi Euroopan suurimmista sudenkorennoista; se nappaa saaliin jopa ilmasta.', 'Lämpiminä kesäpäivinä katso, kun se partioi lampia ja järvenrantoja.', 'Säilytä tai kaiva kasvillinen lampi ja jätä rannat kasvipeitteisiksi.', 'Pidä lammet vapaana saasteista ja valumista, jotta toukat voivat kehittyä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'fi', 'Elokorento', 'Se laskeutuu usein samaan lämpimään kohtaan ja syöksyy nappaamaan ohilentäviä hyönteisiä.', 'Keskikesästä syksyyn seisovan veden äärellä, lämmittelemässä poluilla ja tolpissa.', 'Jätä aurinkoiset istuinpaikat ja kasvillisuus lampien ja ojien ympärille.', 'Älä anna lannoitteen tai öljyn valua lampiin, joissa toukat elävät.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'fi', 'Kekomuurahainen', 'Niiden keot voivat olla yli metrin korkuisia ja sisältää puoli miljoonaa muurahaista.', 'Keväästä syksyyn havumetsissä; etsi neulasista kasattuja kupumaisia kekoja.', 'Jätä keot koskematta — niiden rakentaminen kestää vuosia.', 'Pysy poluilla äläkä koskaan potki tai kaiva kekoa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'fi', 'Valkovuokko', 'Valkovuokko leviää niin hitaasti, että tiheä matto kertoo vanhasta metsästä.', 'Keväällä etsi valkoisia kukkamattoja ennen kuin puut lehtevät.', 'Jätä metsänpohja koskematta, jotta hitaasti leviävät juurakot voivat menestyä.', 'Ihaile niitä siellä, missä ne kasvavat — poimiminen vie kukan, jonka leviäminen kesti vuosia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'fi', 'Kielo', 'Tämän tuoksuvan kasvin kaikki osat ovat syötynä myrkyllisiä.', 'Loppukeväästä seuraa tuoksua varjoisiin metsiin ja puutarhoihin.', 'Jätä varjoisat metsänreunat ja karike sinne, missä se kasvaa.', 'Älä poimi tai kaiva sitä; pidä poissa lasten ja lemmikkien ulottuvilta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'fi', 'Karhunlaukka', 'Karhunlaukan haistaa usein ennen kuin näkee sen valkoiset kukat.', 'Keväällä etsi leveitä vihreitä lehtiä ja tähtimäisiä kukkia kosteista metsistä.', 'Jätä kostea metsä koskematta, jotta matot kasvavat uudelleen joka vuosi.', 'Jos keruu on paikallisesti sallittua, ota vähän äläkä koskaan kaiva sipuleita.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'fi', 'Rentukka', 'Yksi vanhimmista kotimaisista kasveista; se selvisi viime jääkaudesta Skandinaviassa.', 'Keväällä etsi suuria kultaisia kukkia soilta, ojista ja lampien reunoilta.', 'Pidä lampien ja ojien reunat kosteina ja niittämättöminä, jotta se voi kukkia.', 'Älä ojita kosteita maita ja jätä kasvit sinne, missä ne kasvavat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'fi', 'Kevätesikko', 'Kevätesikot olivat niityillä aikoinaan niin yleisiä, että lapset tekivät niistä palloja.', 'Keväällä etsi nuokkuvia keltaisia kukkia vanhoilta, lannoittamattomilta niityiltä.', 'Älä niitä niittyjä ennen kuin esikot ovat kukkineet ja siementäneet.', 'Älä poimi tai kaiva niitä luonnosta — niittykukat vähenevät.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'fi', 'Päivänkakkara', 'Se, mikä näyttää yhdeltä kukalta, on todellisuudessa kymmeniä pikkukukkia yhdessä.', 'Kesällä etsi suuria valkoisia päivänkakkaroita tienpientareilta ja niityiltä.', 'Jätä nurmikaista niittämättä keskikesän yli, jotta se voi kukkia.', 'Älä ruiskuta pientareita ja niittyjä rikkakasvimyrkyllä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'fi', 'Voikukka', 'Voikukka on yksi tärkeimmistä varhaisista mesilähteistä mehiläisille.', 'Keväästä alkaen lähes kaikkialla; kukat avautuvat auringossa ja sulkeutuvat illalla.', 'Anna voikukkien kukkia nurmikolla keväällä ennen ensimmäistä leikkuuta.', 'Jätä nurmikon rikkakasvimyrkyt pois, jotta varhaiset pölyttäjät säilyttävät tämän tärkeän ravinnon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'fi', 'Kanerva', 'Yksi kanervakasvi voi tuottaa yli satatuhatta pientä siementä.', 'Loppukesästä etsi violetteja mattoja avoimilta nummilta ja soilta.', 'Tue nummien pitämistä avoimina ja ojittamattomina.', 'Pysy nummilla poluilla äläkä koskaan tee tulta kuivalla säällä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'fi', 'Mustikka', 'Mustikka värjää sormet sinisiksi ja ruokkii kaikkia linnuista karhuihin.', 'Kesällä etsi matalia varpuja tummine marjoineen mänty- ja kuusimetsistä.', 'Jätä metsän aluskasvillisuus koskematta, jotta varvut voivat tuottaa marjoja.', 'Jos poiminta on paikallisesti sallittua, jätä runsaasti marjoja luonnoneläimille.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'fi', 'Puolukka', 'Puolukka säilyy kuukausia marjassa olevan luontaisen säilöntäaineen ansiosta.', 'Loppukesästä ja syksyllä etsi kiiltäviä punaisia marjoja ainavihannilta matoilta.', 'Jätä metsänpohjan kasvillisuus koskematta, jotta matot voivat levitä.', 'Jos poiminta on sallittua, astu varovasti, ettet murskaa kasveja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'fi', 'Rauduskoivu', 'Koivu elättää satoja hyönteislajeja, jotka puolestaan ruokkivat lukemattomia lintuja.', 'Ympäri vuoden; valkoinen, kuoriutuva tuohi tekee siitä helposti tunnistettavan.', 'Jätä pudonneet lehdet ja lahopuu rikastuttamaan maaperää ja ruokkimaan hyönteisiä.', 'Vältä tuohen kiskomista — se haavoittaa ja heikentää puuta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'fi', 'Kuusi', 'Eräs kuusi Ruotsissa kasvaa juurista, jotka ovat tuhansia vuosia vanhoja.', 'Ympäri vuoden metsissä; sen riippuvat kävyt ovat kuusista pisimmät.', 'Jätä pudonneet kävyt ja lahopuu, jotka suojaavat hyönteisiä ja sieniä.', 'Pysy metsässä poluilla, jottei kuusen pinnalliset juuret tiivisty.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'fi', 'Mänty', 'Vanhat männyt hehkuvat latvan lähellä oranssina ja voivat elää vuosisatoja.', 'Ympäri vuoden hiekkaisilla ja kallioisilla mailla; etsi oranssia kaarnaa rungon yläosasta.', 'Jätä pystyyn lahopuuta ja vanhoja mäntyjä — ne ovat rikkaita elämästä.', 'Älä koskaan tee tulta mäntyjen vieressä kuivalla hiekkamaalla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'fi', 'Hauki', 'Hauki on väijyvä saalistaja, joka syöksyy täydestä liikkumattomuudesta silmänräpäyksessä.', 'Keväästä syksyyn järvien ja hitaiden jokien kasvillisilla matalikoilla.', 'Tue ruovikkomatalikoiden ja vesikasvien säilyttämistä, joissa poikaset suojautuvat.', 'Pidä saasteet ja roskat poissa vedestä; noudata paikallisia kalastussääntöjä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'fi', 'Ahven', 'Ahvenet saalistavat parvissa, ja voimakkaat raidat rikkovat niiden ääriviivan.', 'Lämpiminä kuukausina laitureiden, kasvustojen ja jyrkänteiden ympärillä.', 'Tue puhdasta vettä ja vedenalaisia rakenteita, jotka suojaavat pikkukaloja.', 'Älä koskaan heitä mitään järviin ja jokiin; noudata paikallisia kalastussääntöjä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'fi', 'Särki', 'Särki on keskeinen ravintokala, josta monet järvien petokalat ovat riippuvaisia.', 'Lämpiminä kuukausina parvina järvien ja hitaiden jokien pinnan tuntumassa.', 'Tue puhdasta vettä ja kasvillisia rantoja kutua varten.', 'Pidä valumat ja roskat poissa vedestä; noudata paikallisia kalastussääntöjä.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'da', 'Mursejler', 'Mursejlere kan blive i luften i månedsvis og sover endda under flugten.', 'På lune sommeraftener: kig højt over tagene og lyt efter de skrigende flokke.', 'Sæt en redekasse op under tagudhænget, før fuglene vender tilbage om foråret.', 'Bevar ved renovering de små sprækker under tagudhænget, hvor de yngler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'da', 'Landsvale', 'Landsvaler trækker hvert år helt til det sydlige Afrika og tilbage igen.', 'Fra forår til det tidlige efterår ses de stryge lavt hen over marker og vand.', 'Lad en lade- eller skurdør stå på klem, så de kan nå deres redehylder.', 'Slå ikke gamle lerreder ned — svaler genbruger dem år efter år.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'da', 'Gøg', 'Gøgen lægger sine æg i andre fugles reder og opfostrer aldrig sine egne unger.', 'I det sene forår: lyt efter det vidtrækkende "ku-kuk" fra skovbryn.', 'Støt insektrige enge og hegn, som brødføder de værtsfugle, gøgen afhænger af.', 'Hold dig til stierne nær krat og rørskov, så værtsfuglene ikke forstyrres.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'da', 'Rødhals', 'Rødhalse forsvarer deres territorium indædt og synger natten igennem nær gadelys.', 'Året rundt i haver og skove; de følger ofte den, der graver, i håb om orme.', 'Lad et hjørne af haven ligge med nedfaldne blade, hvor de kan søge føde.', 'Udskyd kraftig hækklipning, til ynglesæsonen er slut sidst på sommeren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'da', 'Solsort', 'Hannens fyldige, fløjtende sang er en af Europas mest genkendelige.', 'Året rundt; lyt i daggry og skumring efter hanner, der synger fra tage og trætoppe.', 'Stil frisk vand frem til drikke og bad, især i tørre perioder.', 'Hold katte inde i daggryet i ynglesæsonen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'da', 'Sjagger', 'Sjaggeren er en selskabelig drossel, der om vinteren strejfer i støjende flokke.', 'Efterår og vinter: se flokke plukke bær fra hegn og røn.', 'Lad bærbærende buske stå uklippede hen over vinteren.', 'Lad nedfaldsæbler ligge om vinteren — i kulden er de livsvigtig føde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'da', 'Musvit', 'Musvitter har et stort lydrepertoire og lærer nye kald af naboerne.', 'Året rundt; fra sidst på vinteren kan man høre den klingende, gentagne sang.', 'Hæng en redekasse med 32 mm hul op et roligt, skyggefuldt sted.', 'Undgå havepesticider, så der er larver nok til at fodre ungerne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'da', 'Blåmejse', 'Et enkelt kuld blåmejser kan æde over tusind larver.', 'Året rundt i haver og skove, ofte hængende på hovedet i tynde grene.', 'Sæt en lille kasse med 25 mm hul op væk fra den fremherskende vind.', 'Drop insektmidler om foråret, så larverne er der til ungerne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'da', 'Bogfinke', 'Bogfinkens sang varierer fra egn til egn, næsten som lokale dialekter.', 'Fra forår til efterår; hannerne synger en lys, faldende strofe fra åbne grene.', 'Lad en del frøstande og græspletter stå hen over sæsonen.', 'Hold foderbrætterne rene, så sygdom ikke spredes blandt finkerne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'da', 'Skovskade', 'Hvert efterår graver den tusindvis af agern ned og planter hele egeskove ved at glemme nogle.', 'Året rundt i egeskov; hold om efteråret øje med glimt af rosa og blåt.', 'Lad nedfaldne agern og bladlag under egene ligge urørt.', 'Hold hunde på stien i skoven, så fugle, der søger føde på jorden, ikke skræmmes op.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'da', 'Stor flagspætte', 'Forårets trommen handler ikke om føde, men er et hurtigt signal om territorium.', 'Året rundt; sidst på vinteren kan man høre trommen give genlyd i skoven.', 'Lad stående dødt ved blive stående — heri lever de insekter, den æder.', 'Fæld ikke døde eller døende træer, de kan rumme redehuller.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'da', 'Hvid vipstjert', 'Den konstante vippen med halen signalerer måske årvågenhed over for rovdyr.', 'Fra forår til efterår ved vand og på åben bund; løber og standser for at snappe insekter.', 'Bevar et stykke kort græs eller grus nær vandet, hvor den kan søge føde.', 'Forstyr ikke gruskyster, hvor den æder og yngler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'da', 'Trane', 'Tidligt på foråret udfører traner parringsdanse med spring og buk.', 'Fra forår til efterår omkring vådområder; lyt efter trompetkaldet, der bæres kilometervidt.', 'Støt beskyttelsen af udrænede moser og våde enge, hvor traner yngler.', 'Betragt ynglevådområder på afstand — en forstyrret trane forlader reden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'da', 'Sangsvane', 'Sangsvaner parrer sig for livet og bebuder ankomsten med høje, trompetagtige kald.', 'Forår og efterår på søer og oversvømmede marker, ofte i familiegrupper.', 'Støt bevarelsen af lavvandede søbredder og våde marker uden dræning.', 'Giv aldrig svaner brød — det skader dem; hold også afstand på isen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'da', 'Gråand', 'Ællingerne kan svømme og finde føde selv få timer efter klækningen.', 'Året rundt på næsten enhver dam, sø eller langsom å.', 'Hvis du fodrer ænder, så brug havre, ærter eller frø i stedet for brød.', 'Hold hunde væk fra vandet om foråret, hvor ænderne yngler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'da', 'Musvåge', 'Musvågen svæver på brede vinger og kalder ofte med et katteagtigt "piii-æh".', 'Fra forår til efterår; spejd efter den, når den kredser højt over marker og skovbryn.', 'Støt grove græsarealer og markkanter, hvor mus og småbytte lever.', 'Brug aldrig rottegift — den vandrer op gennem fødekæden til rovfuglene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'da', 'Fiskeørn', 'Fiskeørnen styrtdykker med fødderne først og kan bære bytte på halvdelen af sin egen vægt.', 'Fra forår til efterår ved store søer; først står den stille i luften, så følger dykket.', 'Støt redeplatforme på høje pæle nær fiskerige søer.', 'Hold god afstand til redeplatforme, så parrene ikke forlader æggene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'da', 'Rød ræv', 'Ræve bruger Jordens magnetfelt til at bedømme springet mod skjult bytte.', 'Året rundt, mest aktive i daggry og skumring langs skov- og markkanter.', 'Lad et vildt, roligt hjørne stå, hvor ræve kan hvile og grave grav.', 'Luk skraldespandene og efterlad aldrig skadelige madrester til ræve.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'da', 'Pindsvin', 'Et pindsvin kan tilbagelægge et par kilometer på en enkelt nats fødesøgning.', 'Fra forår til efterår efter mørkets frembrud; om vinteren sover de under blade og kvasbunker.', 'Skær et hul på 13 cm i hegnet, så pindsvin kan færdes mellem haverne.', 'Tjek højt græs før slåning og lad bladbunker ligge til vinterdvalen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'da', 'Rådyr', 'Rådyr udskyder drægtigheden, så lammene altid fødes i det tidlige forsommer.', 'Året rundt i skovbryn, tydeligst når de græsser i daggry og skumring.', 'Støt uslåede markkanter og krat, der giver dækning og føde.', 'Hold hunde i snor nær skoven i det tidlige forsommer, når lammene ligger skjult.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'da', 'Elg', 'Elgen er verdens største hjortedyr; en stor tyr vejer over et halvt ton.', 'Året rundt i skove og vådområder, mest aktiv i daggry og skumring.', 'Støt sammenhængende skove og våde korridorer, som elgen har brug for til at vandre.', 'Kør forsigtigt på skovveje i daggry og skumring, og nærm dig aldrig en kalv.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'da', 'Egern', 'Egern bygger flere reder og flytter mellem dem.', 'Året rundt i nåle- og blandskove, mest travle tidligt om morgenen.', 'Lad kogler, nødder og stående træer blive, hvor de æder og yngler.', 'Hold hunde på stien og forstyr ikke træer, der kan rumme en rede.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'da', 'Europæisk bæver', 'Bæverdæmninger skaber vådområder, der giver flere fisk, fugle og insekter kilometervidt.', 'Fra forår til sent efterår ved langsomme åer, mest aktive i skumringen.', 'Støt, at dæmninger og bredtræer får lov at blive, hvor det er sikkert.', 'Hold afstand til boer og dæmninger, især når ungerne er små.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'da', 'Sneha', 'Om vinteren bliver pelsen hvid som camouflage mod sneen.', 'Året rundt på åbent land og skovlysninger, mest i daggry og skumring.', 'Støt en blanding af åbent land og dækning, som de har brug for året igennem.', 'Hold hunde i snor på åbent land, så hvilende harer ikke jages.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'da', 'Grævling', 'Grævlinger lever i familiegrupper i underjordiske grave, der bruges i generationer.', 'Fra forår til efterår efter mørkets frembrud nær skov; vinteren sover de væk.', 'Lad uforstyrrede skrænter og hegn stå, hvor grævlinger kan grave grave.', 'Bloker aldrig en aktiv grav og grav ikke ved siden af — det er deres varige hjem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'da', 'Dværgflagermus', 'Denne bittesmå flagermus kan æde op til 3.000 myg og mitter på én nat.', 'På sommeraftener: hold øje med den hurtige, siksakkende flugt i skumringen over haver.', 'Sæt en flagermuskasse højt op på en mur eller et træ, der fanger aftensolen.', 'Undgå skarpt lys ved indflyvningshuller og hold nattehimlen mørk.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'da', 'Nældens takvinge', 'Denne sommerfugl overvintrer som voksen, ofte i skure og på lofter.', 'Fra det tidlige forår til efteråret på solrige blomster, især brændenælder.', 'Lad en plet brændenælder stå i et solrigt hjørne — larverne har brug for dem.', 'Forstyr ikke overvintrende sommerfugle i skure hen over vinteren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'da', 'Dagpåfugleøje', 'Øjepletterne blinker for at skræmme fugle, og vingerne kan hvæse, når de åbnes.', 'Fra forår til efterår på solskinsdage; æder på tidsler og nedfaldsfrugt.', 'Lad en solrig nældeplet vokse til larverne.', 'Forstyr ikke voksne, der overvintrer i skure og brændestabler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'da', 'Citronsommerfugl', 'Det engelske ord "butterfly" stammer måske fra hannens smørgule farve hos denne art.', 'En af forårets første sommerfugle; søg langs skovbryn på lune dage.', 'Støt tørst-buske i hegn, de eneste planter larverne æder.', 'Ryd ikke kratbevoksede hegn, hvor voksne overvintrer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'da', 'Aurora', 'Kun hannerne har de klart orange vingespidser; hunnerne er hvide.', 'Om foråret langs fugtige enge og markveje, hvor engkarse vokser.', 'Lad engkarse og løgkarse gro i fugtige, uslåede hjørner.', 'Udskyd slåning af rabatter, til larverne er færdige med at æde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'da', 'Almindelig blåfugl', 'Larverne passes undertiden af myrer for deres søde afsondring.', 'Fra sidst på foråret på solrige græsarealer rige på kløver og kællingetand.', 'Lad græsarealet stå uslået, så kløver og kællingetand kan blomstre.', 'Sprøjt ikke blomsterrige græsarealer med ukrudtsmiddel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'da', 'Grønåret kålsommerfugl', 'Selv om den ligner kålsommerfuglen, foretrækker den vilde planter frem for havens afgrøder.', 'Fra forår til sensommer på fugtige enge, i grøfter og på skovveje.', 'Lad fugtige hjørner gro til med hjemmehørende korsblomstrede.', 'Dræn og sprøjt ikke de fugtige enge, hvor den yngler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'da', 'Syvplettet mariehøne', 'En enkelt mariehøne kan æde tusindvis af bladlus i sit liv.', 'Fra forår til efterår på planter med bladlus; om vinteren samles de i klynger.', 'Tål lidt bladlus og drop sprøjtningen, så mariehønsene har føde.', 'Lad hule stængler og nedfaldne blade ligge, hvor mariehøns søger ly om vinteren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'da', 'Jordhumle', 'Dronningerne er blandt forårets første bier og summer lavt på jagt efter redehuller.', 'Fra det tidlige forår til efteråret på blomster; om foråret søger dronningerne langs hegnsfødder.', 'Dyrk eller lad tidligt blomstrende planter stå, og lad kløver blomstre i græsplænen.', 'Lad uforstyrrede skrænter og gamle musehuller ligge, hvor kolonier yngler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'da', 'Honningbi', 'Samlerne fortæller stadet, hvor blomsterne er, ved at danse i et ottetal.', 'Fra forår til efterår på blomster på lune, vindstille dage.', 'Lad forskellige blomster blomstre hen over sæsonerne, og stil en lav vandskål frem.', 'Sprøjt ikke blomstrende planter, og sprøjt aldrig midt på dagen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'da', 'Stor kejserguldsmed', 'En af Europas største guldsmede; den kan endda fange bytte i luften.', 'På lune sommerdage: se den patruljere damme og søbredder.', 'Bevar eller grav en dam med planter, og lad bredderne stå bevoksede.', 'Hold damme fri for forurening og afstrømning, så larverne kan udvikle sig.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'da', 'Almindelig hedelibel', 'Den sætter sig ofte på samme varme plet og flyver ud efter forbipasserende insekter.', 'Fra midsommer til efterår nær stillestående vand, solende sig på stier og pæle.', 'Lad solrige siddepladser og bevoksning stå omkring damme og grøfter.', 'Lad ikke gødning eller olie skylle ud i damme, hvor larverne lever.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'da', 'Rød skovmyre', 'Deres tuer kan være over en meter høje og rumme en halv million myrer.', 'Fra forår til efterår i nåleskov; kig efter kuppelformede tuer af nåle.', 'Lad myretuer stå urørte — de tager år at bygge.', 'Hold dig til stierne, og spark eller grav aldrig i en myretue.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'da', 'Hvid anemone', 'Anemoner breder sig så langsomt, at tætte tæpper røber gammel skov.', 'Om foråret: kig efter tæpper af hvide blomster, før træerne springer ud.', 'Lad skovbunden ligge urørt, så de langsomt krybende rodstængler kan trives.', 'Nyd dem der, hvor de vokser — at plukke fjerner en blomst, det tog år at brede ud.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'da', 'Liljekonval', 'Alle dele af denne sødt duftende plante er giftige, hvis de spises.', 'Sidst på foråret: følg duften ind i skyggefulde skove og haver.', 'Lad skyggefulde skovbryn og bladlag ligge, hvor den vokser.', 'Pluk den ikke og grav den ikke op; hold den væk fra børn og husdyr.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'da', 'Ramsløg', 'Man lugter som regel ramsløg, før man ser de hvide blomster.', 'Om foråret: kig efter brede grønne blade og stjerneformede blomster i fugtig skov.', 'Lad fugtig skov ligge urørt, så tæpperne vokser frem igen hvert år.', 'Hvis indsamling er tilladt lokalt, så tag kun lidt og grav aldrig løgene op.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'da', 'Engkabbeleje', 'En af de ældste hjemmehørende planter; den overlevede sidste istid i Skandinavien.', 'Om foråret: kig efter store gyldne blomster i moser, grøfter og dambredder.', 'Hold dam- og grøftekanter våde og uslåede, så den kan blomstre.', 'Dræn ikke våd bund, og lad planterne blive, hvor de vokser.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'da', 'Hulkravet kodriver', 'Kodrivere var engang så almindelige på høenge, at børn lavede bolde af dem.', 'Om foråret: kig efter nikkende gule blomster på gamle, ugødede enge.', 'Lad være med at slå enge, før kodriverne er afblomstret og har sat frø.', 'Pluk dem ikke og grav dem ikke op i naturen — engblomsterne går tilbage.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'da', 'Hvid okseøje', 'Det, der ligner én blomst, er i virkeligheden snesevis af små blomster samlet.', 'Om sommeren: kig efter store hvide margueritter langs veje og på enge.', 'Lad en stribe græs stå uslået hen over højsommeren, så den kan blomstre.', 'Sprøjt ikke rabatter og enge med ukrudtsmiddel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'da', 'Mælkebøtte', 'Mælkebøtten er en af de vigtigste tidlige nektarkilder for bier.', 'Fra foråret og frem næsten overalt; blomsterne åbner sig i sol og lukker i skumringen.', 'Lad mælkebøtter blomstre i plænen om foråret før første slåning.', 'Drop ukrudtsmidler til plænen, så tidlige bestøvere beholder denne vigtige føde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'da', 'Hedelyng', 'En enkelt lyngplante kan producere over hundrede tusind bittesmå frø.', 'Sidst på sommeren: kig efter lilla tæpper på åbne heder og moser.', 'Støt, at heder holdes åbne og udrænede.', 'Hold dig til stierne på heden, og tænd aldrig bål i tørt vejr.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'da', 'Blåbær', 'Blåbær farver fingrene blå og brødføder alt fra fugle til bjørne.', 'Om sommeren: kig efter lave buske med mørke bær i fyrre- og granskov.', 'Lad skovbundens vegetation ligge urørt, så de lave buske kan bære frugt.', 'Hvis plukning er tilladt lokalt, så lad rigeligt med bær blive til dyrelivet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'da', 'Tyttebær', 'Tyttebær holder sig i månedsvis takket være et naturligt konserveringsstof i bærret.', 'Sidst på sommeren og i efteråret: kig efter blanke røde bær på stedsegrønne tæpper.', 'Lad skovbundens vegetation ligge urørt, så tæpperne kan brede sig.', 'Hvis plukning er tilladt, så træd varsomt for ikke at mase planterne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'da', 'Vortebirk', 'En birk brødføder hundredvis af insektarter, som igen mætter utallige fugle.', 'Året rundt; den hvide, afskallende bark gør den let at kende i enhver årstid.', 'Lad nedfaldne birkeblade og dødt ved ligge, så de beriger jorden og føder insekterne.', 'Undgå at flå barken af — det sårer og svækker træet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'da', 'Rødgran', 'En gran i Sverige vokser fra rødder, der er flere tusind år gamle.', 'Året rundt i skovene; dens hængende kogler er de længste blandt graner.', 'Lad nedfaldne kogler og dødt ved ligge, de giver ly til insekter og svampe.', 'Hold dig til stierne i skoven, så granens overfladiske rødder ikke presses sammen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'da', 'Skovfyr', 'Gamle skovfyr gløder orange oppe mod toppen og kan blive århundreder gamle.', 'Året rundt på sandet og stenet bund; kig efter den orange bark øverst på stammen.', 'Lad stående dødt ved og gamle fyrretræer blive — de er rige på liv.', 'Tænd aldrig bål op ad eller nær fyrretræer på tør, sandet bund.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'da', 'Gedde', 'Gedden er en baghold-rovfisk, der kan skyde frem fra fuldstændig ro på et øjeblik.', 'Fra forår til efterår på plantefyldte lavvandede områder i søer og langsomme åer.', 'Støt bevarelsen af rørskov og vandplanter, hvor yngel kan søge ly.', 'Hold forurening og affald ude af vandet; følg de lokale fiskeriregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'da', 'Aborre', 'Aborrer jager i stimer, og de markante striber bryder kroppens omrids.', 'I de varmere måneder omkring broer, plantebælter og skrænter.', 'Støt rent vand og undervandsstrukturer, der giver ly til småfisk.', 'Smid aldrig noget i søer og åer; følg de lokale fiskeriregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'da', 'Skalle', 'Skallen er en nøglefødefisk, som mange rovfisk i søerne er afhængige af.', 'I de varmere måneder i stimer nær overfladen i søer og langsomme åer.', 'Støt rent vand og bevoksede bredder til gydning.', 'Hold afstrømning og affald ude af vandet; følg de lokale fiskeriregler.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'hr', 'Obična čiopa', 'Čiope mogu mjesecima ostati u zraku, čak i spavaju u letu.', 'Toplih ljetnih večeri gledajte visoko iznad krovova i slušajte vrišteća jata.', 'Postavite kućicu za gniježđenje pod strehu prije nego se ptice vrate u proljeće.', 'Pri renoviranju sačuvajte male otvore pod strehom u kojima se gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'hr', 'Lastavica pokućarka', 'Lastavice svake godine sele sve do juga Afrike i natrag.', 'Od proljeća do rane jeseni tražite ih kako nisko klize iznad polja i vode.', 'Ostavite vrata štale ili šupe odškrinuta da dođu do svojih gnijezda.', 'Ne rušite stara blatna gnijezda — lastavice ih koriste iz godine u godinu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'hr', 'Kukavica', 'Kukavica polaže jaja u gnijezda drugih ptica i nikada ne odgaja vlastite mlade.', 'U kasno proljeće slušajte daleki zov "ku-ku" s rubova šume.', 'Podržite livade i živice bogate kukcima koje hrane ptice o kojima kukavica ovisi.', 'Držite se staza uz šikaru i trščake da ptice domaćini ne budu uznemirene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'hr', 'Crvendać', 'Crvendaći žestoko brane teritorij i pjevaju kroz noć blizu uličnih svjetiljki.', 'Cijele godine u vrtovima i šumama; često prate onoga ko kopa, nadajući se glistama.', 'Ostavite kut vrta s otpalim lišćem gdje mogu tražiti hranu.', 'Odgodite jako orezivanje živice dok gniježđenje ne završi u kasno ljeto.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'hr', 'Kos', 'Bogata, flautasta pjesma mužjaka jedna je od najprepoznatljivijih u Evropi.', 'Cijele godine; u zoru i sumrak slušajte mužjake kako pjevaju s krovova i krošnji.', 'Iznesite svježu vodu za piće i kupanje, naročito u sušnim razdobljima.', 'U sezoni gniježđenja držite mačke u kući u zoru.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'hr', 'Drozd bravenjak', 'Društveni je drozd koji zimi luta bučnim, brbljavim jatima.', 'U jesen i zimu gledajte jata kako skidaju bobice s živica i stabala.', 'Ne orezujte grmlje s bobicama tokom zime.', 'Ostavite otpale jabuke na tlu zimi — u hladnoći su ključna hrana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'hr', 'Velika sjenica', 'Imaju velik glasovni repertoar i uče nove zovove od susjeda.', 'Cijele godine; od kasne zime slušajte zvonku, ponavljajuću pjesmu.', 'Objesite kućicu s otvorom od 32 mm na mirno, sjenovito mjesto.', 'Izbjegavajte vrtne pesticide da ostane dovoljno gusjenica za hranjenje mladih.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'hr', 'Plava sjenica', 'Jedno leglo plavih sjenica može pojesti više od tisuću gusjenica.', 'Cijele godine u vrtovima i šumama, često vise naopako s tankih grančica.', 'Postavite malu kućicu s otvorom od 25 mm dalje od prevladavajućeg vjetra.', 'U proljeće preskočite insekticide da gusjenice budu dostupne mladima.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'hr', 'Zeba', 'Pjesma zebe razlikuje se po krajevima, gotovo kao lokalni dijalekti.', 'Od proljeća do jeseni; mužjaci pjevaju vedru, silaznu frazu s otvorenih grana.', 'Ostavite dio sjemenskih glavica i travnatih površina kroz sezonu.', 'Držite hranilice čistima da se bolest ne širi među zebama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'hr', 'Šojka', 'Svake jeseni zakopa tisuće žireva i, zaboravljajući neke, posadi cijele hrastove šume.', 'Cijele godine u hrastovim šumama; u jesen pazite na bljeskove ružičaste i plave.', 'Ostavite otpale žireve i lišće pod hrastovima netaknutima.', 'Držite pse na stazama u šumi da se ptice koje se hrane na tlu ne uznemire.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'hr', 'Veliki djetlić', 'Proljetno bubnjanje nije traženje hrane nego brz ritam kojim označava teritorij.', 'Cijele godine; u kasnu zimu slušajte bubnjanje koje odzvanja šumom.', 'Ostavite stojeće mrtvo drvo u kojem žive kukci kojima se hrani.', 'Ne sijecite mrtva ili sušna stabla koja mogu sadržavati gnijezda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'hr', 'Bijela pastirica', 'Stalno njihanje repa možda signalizira opreznost pred grabežljivcima.', 'Od proljeća do jeseni uz vodu i otvoreno tlo; trči i zastaje da uhvati kukce.', 'Uz vodu održavajte komad niske trave ili šljunka gdje može tražiti hranu.', 'Ne uznemiravajte šljunkovite obale gdje se hrani i gnijezdi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'hr', 'Ždral', 'U rano proljeće izvode svadbene plesove sa skokovima i naklonima.', 'Od proljeća do jeseni oko močvara; slušajte trubljenje koje se čuje kilometrima.', 'Podržite zaštitu neisušenih tresetišta i vlažnih livada u kojima se gnijezde.', 'Gnijezdeća močvarna staništa promatrajte izdaleka — uznemireno gnijezdo napuštaju.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'hr', 'Labud pjevač', 'Labudovi pjevači se pare doživotno i dolazak najavljuju glasnim trubljenjem.', 'U proljeće i jesen na jezerima i poplavljenim poljima, često u obiteljskim skupinama.', 'Podržite očuvanje plitkih rubova jezera i vlažnih polja bez isušivanja.', 'Nikada ne hranite labudove kruhom — škodi im; na ledu držite odstojanje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'hr', 'Divlja patka', 'Pačići plivaju i sami se hrane već nekoliko sati nakon izlijeganja.', 'Cijele godine na gotovo svakom ribnjaku, jezeru ili sporoj rijeci.', 'Ako ih hranite, koristite zob, grašak ili sjemenke umjesto kruha.', 'U proljeće držite pse podalje od vode u kojoj se patke gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'hr', 'Škanjac', 'Lebdi na širokim krilima i često se glasa mačkastim "pijaaau".', 'Od proljeća do jeseni; tražite ga kako kruži visoko iznad polja i rubova šume.', 'Podržite grube travnjake i rubove polja u kojima žive voluharice i sitan plijen.', 'Nikada ne koristite otrove za glodare; lancem ishrane dospijevaju do ptica grabljivica.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'hr', 'Orao ribar', 'Roni nogama naprijed da uhvati ribu i može ponijeti plijen upola svoje težine.', 'Od proljeća do jeseni uz velika jezera; prvo lebdi, potom slijedi dramatičan uron.', 'Podržite postavljanje gnijezdećih platformi na visokim stupovima uz jezera bogata ribom.', 'Zaobiđite gnijezdeće platforme nadaleko da parovi ne napuste jaja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'hr', 'Crvena lisica', 'Lisice se služe Zemljinim magnetskim poljem pri procjeni skoka na skriveni plijen.', 'Cijele godine, najaktivnije u zoru i sumrak uz rubove šume i polja.', 'Ostavite divlji, mirni kut gdje se lisice mogu odmarati i kopati jazbinu.', 'Osigurajte kante i nikada ne ostavljajte štetne ostatke hrane lisicama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'hr', 'Evropski jež', 'Jež u jednoj noći traženja hrane može prijeći nekoliko kilometara.', 'Od proljeća do jeseni nakon mraka; zimi spava pod hrpama lišća i trupaca.', 'Napravite otvor od 13 cm u ogradi da ježevi mogu prelaziti između vrtova.', 'Provjerite visoku travu prije košnje i ostavite hrpe lišća za zimski san.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'hr', 'Srna', 'Srne odgađaju trudnoću tako da se lanad uvijek rađa u rano ljeto.', 'Cijele godine na rubovima šume, najvidljivije pri ispaši u zoru i sumrak.', 'Podržite nepokošene rubove polja i šikaru koje daju zaklon i hranu.', 'U rano ljeto, kad lanad leži skrivena, držite pse na povodcu uz šumu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'hr', 'Los', 'Los je najveći jelen na svijetu; krupan mužjak može težiti preko pola tone.', 'Cijele godine u šumama i močvarama, najaktivniji u zoru i sumrak.', 'Podržite povezane šume i močvarne koridore kojima se los kreće.', 'Vozite oprezno u zoru i sumrak šumskim putevima i nikada ne prilazite mladunčetu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'hr', 'Crvena vjeverica', 'Grade više gnijezda i sele se između njih.', 'Cijele godine u četinarskim i mješovitim šumama, najaktivnije rano ujutro.', 'Ostavite češere, orašaste plodove i stojeća stabla u kojima se hrane i gnijezde.', 'Držite pse na stazama i ne uznemiravajte stabla koja mogu sadržavati gnijezdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'hr', 'Evropski dabar', 'Dabrove brane stvaraju močvare koje kilometrima podižu broj riba, ptica i insekata.', 'Od proljeća do kasne jeseni uz spore rijeke, najaktivniji u sumrak.', 'Podržite ostavljanje brana i priobalnog drveća gdje je to sigurno.', 'Držite se podalje od nastambi i brana, naročito dok su mladunci mali.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'hr', 'Planinski zec', 'Zimi pobijele radi maskiranja na snijegu.', 'Cijele godine na otvorenom tlu i šumskim čistinama, uglavnom u zoru i sumrak.', 'Podržite mješavinu otvorenog tla i zaklona koja im treba tokom godine.', 'Držite pse na povodcu na otvorenom da se zečevi u odmoru ne progone.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'hr', 'Jazavac', 'Žive u obiteljskim skupinama u podzemnim jazbinama koje se koriste generacijama.', 'Od proljeća do jeseni nakon mraka blizu šume; zimu prespavaju.', 'Ostavite netaknute obronke i živice gdje jazavci mogu kopati jazbine.', 'Nikada ne zatvarajte aktivnu jazbinu niti kopajte blizu nje — to je njihov trajni dom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'hr', 'Patuljasti šišmiš', 'Ovaj sićušni šišmiš može u jednoj noći pojesti do 3.000 mušica i komaraca.', 'Ljetnih večeri pratite brz, isprekidan let u sumrak iznad vrtova.', 'Postavite kućicu za šišmiše visoko na zid ili stablo koje hvata večernje sunce.', 'Izbjegavajte jaka svjetla na ulazima skloništa i održavajte noćno nebo tamnim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'hr', 'Mali kostrijet leptir', 'Ovaj leptir prezimljava kao odrastao, često u šupama i potkrovljima.', 'Od ranog proljeća do jeseni na sunčanim cvjetovima, naročito na koprivi.', 'Ostavite komad kopriva u sunčanom kutu — gusjenicama su nužne.', 'Ne uznemiravajte leptire koji prezimljavaju u šupama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'hr', 'Paunovo oko', 'Očaste mrlje bljesnu da preplaše ptice, a krila pri otvaranju mogu zasiktati.', 'Od proljeća do jeseni po suncu, hrani se čkaljem i otpalim voćem.', 'Pustite da sunčani busen kopriva raste za njegove gusjenice.', 'Ne dirajte odrasle koji zimi borave u šupama i hrpama drva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'hr', 'Limunov leptir', 'Engleska riječ za leptira možda potječe od maslačastožute boje mužjaka ove vrste.', 'Jedan od prvih proljetnih leptira; toplih dana tražite ga uz rubove šume.', 'Podržite grmove krkavine u živicama, jedine biljke koje gusjenice jedu.', 'Ne krčite šikaraste živice koje zaklanjaju odrasle tokom zime.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'hr', 'Narandžasti vrh', 'Samo mužjaci imaju jarko narandžaste vrhove krila; ženke su bijele.', 'U proljeće uz vlažne livade i putove gdje raste livadna režuha.', 'Pustite da livadno cvijeće raste u vlažnim, nepokošenim kutovima.', 'Odgodite košnju bankina dok gusjenice ne završe hranjenje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'hr', 'Obični plavac', 'Gusjenice ponekad njeguju mravi zbog njihovih slatkih izlučevina.', 'Od kasnog proljeća na sunčanim travnjacima bogatim djetelinom.', 'Ostavite travnjak nepokošen da djeteline mogu cvjetati.', 'Ne prskajte herbicidom travnjake bogate divljim cvijećem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'hr', 'Zelenožilni bijelac', 'Iako liči na kupusara, više voli divlje biljke nego vrtne usjeve.', 'Od proljeća do kasnog ljeta na vlažnim livadama, u jarcima i šumskim prosjekama.', 'Pustite da vlažni kutovi podivljaju s domaćim krstašicama.', 'Ne isušujte i ne prskajte vlažne livade na kojima se razmnožava.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'hr', 'Bubamara sa sedam tačaka', 'Jedna bubamara tokom života može pojesti tisuće lisnih uši.', 'Od proljeća do jeseni na biljkama s lisnim ušima; zimi se skupljaju na prezimljavanje.', 'Podnesite nešto lisnih uši i preskočite prskanje da bubamare imaju hranu.', 'Ostavite šuplje stabljike i otpalo lišće u kojima zimi nalaze zaklon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'hr', 'Bumbar žutorepi', 'Matice su među prvim pčelama u proljeće i nisko zuje tražeći rupe za gnijezdo.', 'Od ranog proljeća do jeseni na cvijeću; matice u proljeće pretražuju podnožja živica.', 'Uzgajajte ili ostavite rano cvjetajuće biljke i pustite djetelinu da cvjeta u travnjaku.', 'Ostavite netaknute obronke i stare mišje rupe u kojima se kolonije gnijezde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'hr', 'Medonosna pčela', 'Sakupljačice plesom u obliku osmice govore košnici gdje je cvijeće.', 'Od proljeća do jeseni na cvijeću za toplih, mirnih dana.', 'Pustite da raznoliko cvijeće cvjeta kroz sezone i ostavite plitku posudu s vodom.', 'Ne prskajte biljke u cvatu i nikada ne prskajte sredinom dana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'hr', 'Carski vilin konjic', 'Jedan je od najvećih evropskih vilinih konjica i plijen može uhvatiti čak u zraku.', 'Toplih ljetnih dana gledajte ga kako patrolira ribnjacima i rubovima jezera.', 'Održavajte ili iskopajte ribnjak s biljkama i ostavite rubove zaraslima.', 'Čuvajte ribnjake od zagađenja i otjecanja da se ličinke mogu razviti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'hr', 'Obični strijelac', 'Često sjeda na isto toplo mjesto i izlijeće da uhvati kukce koji prolaze.', 'Od sredine ljeta do jeseni uz mirnu vodu, sunča se na stazama i stupovima.', 'Ostavite sunčana mjesta za sjedenje i vegetaciju oko ribnjaka i jaraka.', 'Ne dopustite da gnojivo ili ulje dospiju u ribnjake u kojima žive ličinke.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'hr', 'Crveni šumski mrav', 'Njihovi humci mogu biti viši od metra i sadržavati pola miliona mrava.', 'Od proljeća do jeseni u četinarskim šumama; tražite kupolaste humke od iglica.', 'Ostavite mravinjake netaknutima — grade ih godinama.', 'Držite se staza i nikada ne udarajte i ne kopajte po mravinjaku.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'hr', 'Šumska šumarica', 'Šire se tako sporo da gusti tepisi označavaju staru šumu.', 'U proljeće tražite tepihe bijelog cvijeća prije nego stabla prolistaju.', 'Ostavite šumsko tlo netaknuto da sporo rastuće korijenje uspijeva.', 'Uživajte u njima ondje gdje rastu — branje uklanja cvijet kojem je trebalo godina.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'hr', 'Đurđevak', 'Svaki dio ove mirisne biljke otrovan je ako se pojede.', 'U kasno proljeće slijedite miris do sjenovitih šuma i zasjenjenih vrtova.', 'Ostavite sjenovite rubove šume i otpalo lišće gdje raste.', 'Ne berite ga i ne iskopavajte; držite ga podalje od djece i kućnih ljubimaca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'hr', 'Medvjeđi luk', 'Medvjeđi luk često namirišete prije nego ugledate bijele cvjetove.', 'U proljeće tražite široke zelene listove i zvjezdaste cvjetove u vlažnim šumama.', 'Ostavite vlažnu šumu netaknutom da tepisi svake godine ponovo izrastu.', 'Ako je branje lokalno dopušteno, uzmite malo i nikada ne čupajte lukovice.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'hr', 'Barski kaljužnjak', 'Jedna od najstarijih domaćih biljaka; preživjela je posljednje ledeno doba u Skandinaviji.', 'U proljeće tražite velike zlatne cvjetove u močvarama, jarcima i uz ribnjake.', 'Održavajte rubove ribnjaka i jaraka vlažnima i nepokošenima da može cvjetati.', 'Ne isušujte vlažno tlo i ostavite biljke ondje gdje rastu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'hr', 'Jagorčevina', 'Jagorčevine su nekad bile toliko česte na livadama da su djeca od njih pravila lopte.', 'U proljeće tražite klimave žute cvjetove na starim, neobrađenim livadama.', 'Ne kosite livade dok jagorčevine ne odcvjetaju i ne razviju sjeme.', 'Ne berite ih i ne iskopavajte iz prirode — livadno cvijeće je u opadanju.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'hr', 'Velika ivančica', 'Ono što izgleda kao jedan cvijet zapravo je na desetke sićušnih cvjetova zajedno.', 'Ljeti tražite velike bijele ivančice uz puteve i na livadama.', 'Ostavite traku trave nepokošenom kroz sredinu ljeta da može cvjetati.', 'Ne prskajte bankine i livade herbicidom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'hr', 'Maslačak', 'Maslačak je jedan od najvažnijih ranih izvora nektara za pčele.', 'Od proljeća nadalje gotovo svugdje; cvjetovi se otvaraju na suncu i zatvaraju u sumrak.', 'Pustite maslačke da cvjetaju u travnjaku u proljeće prije prve košnje.', 'Preskočite herbicide za travnjak da rani oprašivači zadrže ovu ključnu hranu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'hr', 'Vrijes', 'Jedna biljka vrijeska može proizvesti više od sto tisuća sićušnih sjemenki.', 'U kasno ljeto tražite ljubičaste tepihe na otvorenim vrištinama i tresetištima.', 'Podržite održavanje vriština otvorenima i bez isušivanja.', 'Držite se staza na vrištinama i nikada ne palite vatru po suhom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'hr', 'Borovnica', 'Borovnice oboje prste u plavo i hrane sve, od ptica do medvjeda.', 'Ljeti tražite niske grmove s tamnim bobicama u borovoj i smrčevoj šumi.', 'Ostavite šumsko podrast netaknutim da niski grmovi mogu roditi.', 'Ako je branje lokalno dopušteno, ostavite dovoljno bobica divljim životinjama.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'hr', 'Brusnica', 'Brusnice se drže mjesecima zahvaljujući prirodnom konzervansu u plodu.', 'U kasno ljeto i jesen tražite sjajne crvene bobice na zimzelenim tepisima.', 'Ostavite vegetaciju šumskog tla netaknutom da se tepisi mogu širiti.', 'Ako je branje dopušteno, gazite pažljivo da ne zgnječite biljke.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'hr', 'Bijela breza', 'Breza hrani stotine vrsta insekata, koji pak hrane bezbroj ptica.', 'Cijele godine; bijela kora koja se ljušti čini je lako prepoznatljivom u svakom dobu.', 'Ostavite otpalo brezovo lišće i mrtvo drvo da obogate tlo i hrane kukce.', 'Izbjegavajte guljenje kore, koje može raniti i oslabiti stablo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'hr', 'Smrča', 'Jedna smrča u Švedskoj raste iz korijena starog nekoliko tisuća godina.', 'Cijele godine u šumama; njezini viseći češeri najduži su među smrčama.', 'Ostavite otpale češere i mrtvo drvo koji daju zaklon kukcima i gljivama.', 'Držite se staza u šumi da se plitko korijenje smrče ne zbija.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'hr', 'Bijeli bor', 'Stari borovi pri vrhu svijetle narandžasto i mogu živjeti stoljećima.', 'Cijele godine na pjeskovitom i kamenitom tlu; tražite narandžastu koru pri vrhu.', 'Ostavite stojeće mrtvo drvo i stare borove, bogate divljim svijetom.', 'Nikada ne palite vatru uz borove na suhom, pjeskovitom tlu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'hr', 'Štuka', 'Štuka je grabežljivac iz zasjede koji iz mirovanja napada u trenu.', 'Od proljeća do jeseni u zaraslim plićacima jezera i sporih rijeka.', 'Podržite očuvanje trščanih plićaka i vodenog bilja u kojima se skriva mlađ.', 'Držite zagađenje i smeće podalje od vode; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'hr', 'Grgeč', 'Grgeči love u jatima, a izrazite pruge razbijaju obrise njihova tijela.', 'U toplijim mjesecima oko gatova, busena vodenog bilja i podvodnih rubova.', 'Podržite čistu vodu i podvodne strukture koje pružaju zaklon sitnoj ribi.', 'Nikada ništa ne bacajte u jezera i rijeke; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'hr', 'Bodorka', 'Bodorka je ključna riba hraniteljica o kojoj ovise mnogi jezerski grabežljivci.', 'U toplijim mjesecima u jatima blizu površine jezera i sporih rijeka.', 'Podržite čistu vodu i obrasle rubove potrebne za mrijest.', 'Držite otjecanje i smeće podalje od vode; poštujte lokalna ribolovna pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'es', 'Vencejo común', 'Los vencejos pueden pasar meses en el aire e incluso duermen en vuelo.', 'En las tardes cálidas de verano, mira alto sobre los tejados y escucha los bandos chillones.', 'Coloca una caja nido bajo el alero antes de que las aves regresen en primavera.', 'Al reformar, conserva las pequeñas rendijas bajo el alero donde anidan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'es', 'Golondrina común', 'Las golondrinas migran cada año hasta el sur de África y regresan.', 'De primavera a principios de otoño, búscalas volando bajo sobre campos y agua.', 'Deja entornada la puerta del granero o del cobertizo para que alcancen sus nidos.', 'No derribes los nidos viejos de barro: las golondrinas los reutilizan año tras año.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'es', 'Cuco común', 'El cuco pone sus huevos en nidos ajenos y nunca cría a sus propios pollos.', 'A finales de primavera, escucha el "cu-cú" que llega de lejos desde los bordes del bosque.', 'Apoya prados y setos ricos en insectos que alimentan a las aves anfitrionas.', 'Mantente en los senderos junto a matorrales y carrizales para no molestar a las anfitrionas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'es', 'Petirrojo europeo', 'Los petirrojos defienden su territorio con fiereza y cantan de noche cerca de las farolas.', 'Todo el año en jardines y bosques; suelen seguir a quien cava, esperando lombrices.', 'Deja un rincón del jardín con hojarasca donde puedan buscar alimento.', 'Retrasa la poda fuerte del seto hasta que termine la cría a finales de verano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'es', 'Mirlo común', 'El canto rico y aflautado del macho es uno de los más reconocibles de Europa.', 'Todo el año; al amanecer y al anochecer escucha a los machos cantar desde tejados y copas.', 'Pon agua fresca para beber y bañarse, sobre todo en épocas secas.', 'En época de cría, mantén a los gatos dentro al amanecer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'es', 'Zorzal real', 'El zorzal real es sociable y en invierno vaga en bandos ruidosos y parlanchines.', 'En otoño e invierno, observa los bandos despojando de bayas setos y serbales.', 'No podes los arbustos con bayas durante el invierno.', 'Deja en el suelo las manzanas caídas en invierno: con frío son alimento vital.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'es', 'Carbonero común', 'Los carboneros tienen un enorme repertorio de voces y aprenden reclamos nuevos de sus vecinos.', 'Todo el año; desde finales del invierno escucha su canto sonoro y repetido.', 'Cuelga una caja nido con orificio de 32 mm en un lugar tranquilo y sombreado.', 'Evita los pesticidas de jardín para que queden orugas suficientes para los pollos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'es', 'Herrerillo común', 'Una sola nidada de herrerillos puede comer más de mil orugas.', 'Todo el año en jardines y bosques, a menudo colgando boca abajo de ramitas finas.', 'Coloca una caja pequeña con orificio de 25 mm resguardada del viento dominante.', 'Prescinde de insecticidas en primavera para que haya orugas para los pollos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'es', 'Pinzón vulgar', 'El canto del pinzón varía según la comarca, casi como dialectos locales.', 'De primavera a otoño; los machos cantan una frase clara y descendente desde perchas abiertas.', 'Deja parte de las cabezuelas con semillas y las manchas de hierba en pie durante la temporada.', 'Mantén limpios los comederos para que no se propaguen enfermedades entre los pinzones.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'es', 'Arrendajo euroasiático', 'Cada otoño entierra miles de bellotas y, al olvidar algunas, planta robledales enteros.', 'Todo el año en robledales; en otoño fíjate en los destellos rosados y azules.', 'Deja intactas las bellotas caídas y la hojarasca bajo los robles.', 'Lleva a los perros por el sendero en el bosque para no espantar a las aves que comen en el suelo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'es', 'Pico picapinos', 'El tamborileo de primavera no busca comida: es un redoble rápido para marcar territorio.', 'Todo el año; a finales del invierno escucha el tamborileo resonando por el bosque.', 'Deja en pie la madera muerta, donde viven los insectos de los que se alimenta.', 'No tales árboles muertos o decrépitos: pueden albergar huecos de nidificación.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'es', 'Lavandera blanca', 'El constante balanceo de la cola quizá señale a los depredadores que está alerta.', 'De primavera a otoño junto al agua y en terreno abierto; corre y se detiene para atrapar insectos.', 'Conserva junto al agua una zona de hierba corta o grava donde pueda alimentarse.', 'No perturbes las orillas de grava donde come y anida.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'es', 'Grulla común', 'A principios de primavera las grullas ejecutan danzas nupciales con saltos y reverencias.', 'De primavera a otoño en humedales; escucha su trompeteo, audible a kilómetros.', 'Apoya la protección de turberas y prados húmedos sin drenar donde crían las grullas.', 'Observa los humedales de cría desde lejos: una grulla molestada abandona el nido.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'es', 'Cisne cantor', 'Los cisnes cantores se emparejan de por vida y anuncian su llegada con fuertes trompeteos.', 'En primavera y otoño en lagos y campos inundados, a menudo en grupos familiares.', 'Apoya la conservación de orillas someras y campos húmedos sin drenaje.', 'Nunca des pan a los cisnes: les hace daño; sobre el hielo mantén también la distancia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'es', 'Ánade real', 'Los patitos nadan y se alimentan solos a las pocas horas de eclosionar.', 'Todo el año en casi cualquier charca, lago o río lento.', 'Si alimentas a los patos, usa avena, guisantes o semillas en lugar de pan.', 'En primavera, mantén a los perros fuera del agua donde los patos anidan.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'es', 'Busardo ratonero', 'El busardo planea con alas anchas y suele reclamar con un maullido agudo.', 'De primavera a otoño; búscalo trazando círculos alto sobre campos y linderos.', 'Apoya los pastizales bastos y los márgenes de cultivo donde viven topillos y presas pequeñas.', 'Nunca uses raticidas: ascienden por la cadena alimentaria hasta las rapaces.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'es', 'Águila pescadora', 'El águila pescadora se zambulle con las patas por delante y carga presas de medio peso propio.', 'De primavera a otoño cerca de lagos grandes; primero se cierne y luego se lanza en picado.', 'Apoya la instalación de plataformas de nidificación en postes altos junto a lagos con peces.', 'Rodea las plataformas de nidificación a buena distancia para que las parejas no abandonen la puesta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'es', 'Zorro rojo', 'Los zorros se ayudan del campo magnético terrestre para calcular el salto sobre presas ocultas.', 'Todo el año, más activos al amanecer y al anochecer en linderos de bosque y campo.', 'Deja un rincón silvestre y tranquilo donde los zorros puedan descansar y excavar madriguera.', 'Asegura los cubos de basura y nunca dejes restos de comida dañinos para los zorros.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'es', 'Erizo europeo', 'Un erizo puede recorrer un par de kilómetros en una sola noche buscando alimento.', 'De primavera a otoño tras anochecer; en invierno hiberna bajo montones de hojas y troncos.', 'Abre un hueco de 13 cm en la valla para que los erizos circulen entre jardines.', 'Revisa la hierba alta antes de segar y deja montones de hojas para la hibernación.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'es', 'Corzo', 'Los corzos retrasan la gestación para que los cervatillos nazcan siempre a principios de verano.', 'Todo el año en linderos de bosque, más visibles pastando al amanecer y al anochecer.', 'Apoya los márgenes sin segar y el matorral que dan refugio y alimento.', 'A principios de verano, con los cervatillos escondidos, lleva los perros atados cerca del bosque.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'es', 'Alce', 'El alce es el cérvido más grande del mundo; un macho grande supera media tonelada.', 'Todo el año en bosques y humedales, más activo al amanecer y al anochecer.', 'Apoya los bosques conectados y los corredores húmedos que el alce necesita para desplazarse.', 'Conduce con cuidado al amanecer y al anochecer en pistas forestales y nunca te acerques a una cría.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'es', 'Ardilla roja', 'Las ardillas construyen varios nidos y se mudan entre ellos.', 'Todo el año en bosques de coníferas y mixtos, más activas a primera hora de la mañana.', 'Deja piñas, frutos secos y árboles en pie donde se alimentan y anidan.', 'Lleva a los perros por el sendero y no molestes árboles que puedan albergar un nido.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'es', 'Castor europeo', 'Las presas de castor crean humedales que multiplican peces, aves e insectos durante kilómetros.', 'De primavera a finales de otoño junto a ríos lentos, más activos al anochecer.', 'Apoya que las presas y los árboles de ribera permanezcan donde sea seguro.', 'Mantente lejos de madrigueras y presas, sobre todo cuando las crías son pequeñas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'es', 'Liebre de montaña', 'En invierno su pelaje se vuelve blanco para camuflarse sobre la nieve.', 'Todo el año en terreno abierto y claros del bosque, sobre todo al amanecer y al anochecer.', 'Apoya la mezcla de terreno abierto y refugio que necesitan a lo largo del año.', 'Lleva los perros atados en terreno abierto para que no persigan a las liebres en reposo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'es', 'Tejón europeo', 'Los tejones viven en grupos familiares en tejoneras subterráneas usadas durante generaciones.', 'De primavera a otoño tras anochecer cerca del bosque; pasan el invierno durmiendo.', 'Deja taludes y setos sin alterar donde los tejones puedan excavar sus tejoneras.', 'Nunca tapones una tejonera activa ni caves junto a ella: es su hogar duradero.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'es', 'Murciélago enano', 'Este murciélago diminuto puede comer hasta 3.000 mosquitos en una sola noche.', 'En las tardes de verano, observa su vuelo rápido y quebrado al anochecer sobre los jardines.', 'Coloca una caja para murciélagos alta en un muro o árbol que reciba el sol de la tarde.', 'Evita las luces intensas en las entradas de los refugios y mantén oscuro el cielo nocturno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'es', 'Ortiguera', 'Esta mariposa hiberna como adulto, a menudo en cobertizos y desvanes.', 'De principios de primavera a otoño en flores soleadas, sobre todo ortigas.', 'Deja una mancha de ortigas en un rincón soleado: sus orugas las necesitan.', 'No molestes a las mariposas que hibernan en cobertizos durante el invierno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'es', 'Pavo real (mariposa)', 'Los ocelos destellan para asustar a las aves, y las alas pueden sisear al abrirse.', 'De primavera a otoño en días soleados; se alimenta de cardos y fruta caída.', 'Deja crecer una mancha soleada de ortigas para sus orugas.', 'No molestes a los adultos que se refugian en cobertizos y leñeras durante el invierno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'es', 'Limonera', 'La palabra inglesa "butterfly" quizá venga del color amarillo mantequilla del macho de esta especie.', 'Una de las primeras mariposas de la primavera; búscala en los linderos en días templados.', 'Apoya los arraclanes de los setos, las únicas plantas que comen sus orugas.', 'No desbroces los setos con matorral donde los adultos pasan el invierno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'es', 'Musgosa de punta naranja', 'Solo los machos tienen las puntas de las alas de un naranja vivo; las hembras son blancas.', 'En primavera por prados húmedos y caminos donde crece la cardamina.', 'Deja que la cardamina y la aliaria crezcan en rincones húmedos sin segar.', 'Retrasa la siega de las cunetas hasta que las orugas terminen de alimentarse.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'es', 'Dos puntos azul', 'A sus orugas a veces las cuidan las hormigas por sus secreciones dulces.', 'Desde finales de primavera en pastizales soleados ricos en tréboles y loto.', 'Deja el pastizal sin segar para que los tréboles y el loto puedan florecer.', 'No fumigues con herbicida los pastizales ricos en flores silvestres.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'es', 'Blanca verdinervada', 'Aunque se parece a la blanca de la col, prefiere plantas silvestres antes que cultivos de huerta.', 'De primavera a finales de verano en prados húmedos, cunetas y caminos forestales.', 'Deja que los rincones húmedos se asilvestren con crucíferas autóctonas.', 'No drenes ni fumigues los prados húmedos donde se reproduce.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'es', 'Mariquita de siete puntos', 'Una sola mariquita puede comer miles de pulgones a lo largo de su vida.', 'De primavera a otoño en plantas con pulgón; en invierno se agrupan para hibernar.', 'Tolera algo de pulgón y prescinde de los tratamientos para que las mariquitas tengan alimento.', 'Deja los tallos huecos y la hojarasca donde las mariquitas se refugian en invierno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'es', 'Abejorro de cola leonada', 'Las reinas están entre las primeras abejas de la primavera y zumban bajo buscando huecos para el nido.', 'De principios de primavera a otoño en las flores; en primavera las reinas rastrean la base de los setos.', 'Cultiva o conserva plantas de floración temprana y deja que el trébol florezca en el césped.', 'Deja sin alterar los taludes y las viejas madrigueras de ratón donde anidan las colonias.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'es', 'Abeja melífera occidental', 'Las pecoreadoras indican a la colmena dónde están las flores bailando en forma de ocho.', 'De primavera a otoño en las flores, en días cálidos y sin viento.', 'Deja que distintas flores se sucedan a lo largo de las estaciones y pon un plato de agua poco profundo.', 'No fumigues plantas en flor y nunca fumigues en pleno mediodía.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'es', 'Libélula emperador', 'Una de las libélulas más grandes de Europa; captura presas incluso en pleno vuelo.', 'En los días cálidos de verano, obsérvala patrullando charcas y orillas de lago.', 'Conserva o excava una charca con plantas y deja sus bordes con vegetación.', 'Mantén las charcas libres de contaminación y escorrentía para que las larvas se desarrollen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'es', 'Libélula común de otoño', 'Suele posarse en el mismo punto cálido y salir disparada a atrapar insectos que pasan.', 'De pleno verano a otoño cerca de aguas quietas, asoleándose en senderos y postes.', 'Deja posaderos soleados y vegetación alrededor de charcas y acequias.', 'Evita que abonos o aceites lleguen a las charcas donde viven las larvas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'es', 'Hormiga roja de bosque', 'Sus hormigueros pueden superar el metro de altura y albergar medio millón de hormigas.', 'De primavera a otoño en pinares; busca montículos abovedados de acículas.', 'Deja los hormigueros intactos: tardan años en construirse.', 'Quédate en los senderos y nunca patees ni excaves un hormiguero.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'es', 'Anémona de bosque', 'Se extiende tan despacio que las alfombras densas delatan un bosque antiguo.', 'En primavera, busca alfombras de flores blancas antes de que los árboles echen hoja.', 'Deja el suelo del bosque intacto para que los rizomas de lento avance prosperen.', 'Disfrútalas donde crecen: arrancarlas quita una flor que tardó años en extenderse.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'es', 'Lirio de los valles', 'Todas las partes de esta planta de dulce aroma son tóxicas si se ingieren.', 'A finales de primavera, sigue el aroma hasta bosques y jardines sombreados.', 'Deja los linderos sombreados y la hojarasca donde crece.', 'No la cortes ni la arranques; mantenla lejos de niños y mascotas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'es', 'Ajo de oso', 'Al ajo de oso sueles olerlo antes de ver sus flores blancas.', 'En primavera, busca hojas anchas y verdes y flores estrelladas en bosques húmedos.', 'Deja el bosque húmedo intacto para que las alfombras rebroten cada año.', 'Si la recolección está permitida localmente, toma poco y nunca arranques los bulbos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'es', 'Calta palustre', 'Una de las plantas autóctonas más antiguas: sobrevivió a la última glaciación en Escandinavia.', 'En primavera, busca grandes flores doradas en marismas, acequias y orillas de charca.', 'Mantén húmedos y sin segar los bordes de charcas y acequias para que pueda florecer.', 'No drenes el terreno húmedo y deja las plantas donde crecen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'es', 'Primavera común', 'Las primaveras fueron tan comunes en los prados de siega que los niños hacían bolas con ellas.', 'En primavera, busca flores amarillas cabizbajas en prados viejos sin abonar.', 'No siegues los prados hasta que las primaveras hayan florecido y granado.', 'No las cortes ni las arranques del campo: las flores de prado están en declive.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'es', 'Margarita mayor', 'Lo que parece una flor son en realidad decenas de flores diminutas apretadas.', 'En verano, busca grandes margaritas blancas en cunetas y prados.', 'Deja una franja de hierba sin segar durante pleno verano para que pueda florecer.', 'No fumigues cunetas y prados con herbicida.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'es', 'Diente de león', 'El diente de león es una de las fuentes de néctar tempranas más importantes para las abejas.', 'Desde primavera casi en cualquier sitio; las flores se abren al sol y se cierran al anochecer.', 'Deja que los dientes de león florezcan en el césped en primavera antes del primer corte.', 'Prescinde de herbicidas para césped y así los polinizadores tempranos conservarán este alimento vital.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'es', 'Brecina', 'Una sola planta de brecina puede producir más de cien mil semillas diminutas.', 'A finales de verano, busca alfombras moradas en brezales abiertos y turberas.', 'Apoya que los brezales se mantengan abiertos y sin drenar.', 'Quédate en los senderos del brezal y nunca enciendas fuego con tiempo seco.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'es', 'Arándano', 'Los arándanos tiñen los dedos de azul y alimentan a todos, desde aves hasta osos.', 'En verano, busca matas bajas con bayas oscuras en pinares y abetales.', 'Deja intacto el sotobosque para que las matas puedan fructificar.', 'Si la recolección está permitida localmente, deja bayas de sobra para la fauna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'es', 'Arándano rojo', 'El arándano rojo se conserva meses gracias a un conservante natural del fruto.', 'A finales de verano y en otoño, busca bayas rojas brillantes sobre alfombras perennes.', 'Deja intacta la vegetación del suelo del bosque para que las alfombras se extiendan.', 'Si la recolección está permitida, pisa con cuidado para no aplastar las plantas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'es', 'Abedul plateado', 'Un abedul sostiene a cientos de especies de insectos, que a su vez alimentan a incontables aves.', 'Todo el año; la corteza blanca que se descama lo hace fácil de reconocer en cualquier estación.', 'Deja las hojas caídas y la madera muerta para enriquecer el suelo y alimentar a los insectos.', 'Evita arrancar la corteza: hiere y debilita al árbol.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'es', 'Pícea común', 'Una pícea de Suecia crece de unas raíces que tienen miles de años.', 'Todo el año en los bosques; sus piñas colgantes son las más largas de todas las píceas.', 'Deja las piñas caídas y la madera muerta, que dan refugio a insectos y hongos.', 'Quédate en los senderos del bosque para no compactar las raíces superficiales de la pícea.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'es', 'Pino silvestre', 'Los pinos viejos brillan anaranjados cerca de la copa y pueden vivir siglos.', 'Todo el año en suelos arenosos y rocosos; busca la corteza anaranjada en la parte alta.', 'Deja en pie la madera muerta y los pinos viejos: son ricos en vida.', 'Nunca enciendas fuego junto a los pinos en suelo arenoso y seco.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'es', 'Lucio del norte', 'El lucio es un depredador de emboscada capaz de lanzarse desde la quietud en un parpadeo.', 'De primavera a otoño en las orillas someras con vegetación de lagos y ríos lentos.', 'Apoya la conservación de los carrizales someros y las plantas acuáticas donde se refugian los alevines.', 'Mantén la contaminación y la basura fuera del agua; respeta las normas locales de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'es', 'Perca europea', 'Las percas cazan en grupo, y sus franjas marcadas rompen el contorno de su cuerpo.', 'En los meses cálidos, cerca de pantalanes, praderas de plantas y desniveles del fondo.', 'Apoya el agua limpia y las estructuras sumergidas que dan refugio a los peces pequeños.', 'Nunca viertas nada en lagos y ríos; respeta las normas locales de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'es', 'Bermejuela (rutilo)', 'Es un pez forrajero clave del que dependen muchos depredadores de los lagos.', 'En los meses cálidos, en cardúmenes cerca de la superficie de lagos y ríos lentos.', 'Apoya el agua limpia y las orillas con vegetación necesarias para el desove.', 'Mantén la escorrentía y la basura fuera del agua; respeta las normas locales de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'nl', 'Gierzwaluw', 'Gierzwaluwen kunnen maandenlang in de lucht blijven en slapen zelfs vliegend.', 'Op warme zomeravonden: kijk hoog boven de daken en luister naar de gierende groepen.', 'Hang een gierzwaluwkast onder de dakrand op vóór de vogels in het voorjaar terugkeren.', 'Laat bij verbouwing de kleine kieren onder de dakrand intact waar ze broeden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'nl', 'Boerenzwaluw', 'Boerenzwaluwen trekken elk jaar helemaal naar zuidelijk Afrika en weer terug.', 'Van het voorjaar tot de vroege herfst scheren ze laag over open velden en water.', 'Laat een schuur- of staldeur op een kier staan zodat ze bij hun nestrichels kunnen.', 'Sloop oude moddernesten niet — zwaluwen gebruiken ze jaar na jaar opnieuw.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'nl', 'Koekoek', 'De koekoek legt haar eieren in de nesten van andere vogels en voedt nooit eigen jongen op.', 'In het late voorjaar: luister naar de ver dragende "koekoek" langs bosranden.', 'Steun insectenrijke hooilanden en houtwallen die de waardvogels van de koekoek voeden.', 'Blijf op de paden bij struweel en rietland zodat waardvogels niet verstoord worden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'nl', 'Roodborst', 'Roodborsten verdedigen hun territorium fel en zingen bij straatlantaarns de nacht door.', 'Het hele jaar in tuinen en bos; ze volgen graag iemand die spit, op zoek naar wormen.', 'Laat een hoek van de tuin met bladafval liggen waar roodborsten kunnen foerageren.', 'Stel zwaar heggensnoeien uit tot het broeden laat in de zomer voorbij is.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'nl', 'Merel', 'De volle, fluitende zang van het mannetje is een van de bekendste van Europa.', 'Het hele jaar; luister bij dageraad en schemer naar mannetjes op daken en boomtoppen.', 'Zet vers water neer om te drinken en te baden, zeker in droge perioden.', 'Houd katten bij zonsopgang binnen tijdens het broedseizoen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'nl', 'Kramsvogel', 'Kramsvogels zijn gezellige lijsters die in luidruchtige, kwetterende wintergroepen rondtrekken.', 'In herfst en winter: kijk hoe groepen bessen van hagen en lijsterbessen plukken.', 'Laat bessendragende struiken zoals lijsterbes en meidoorn de winter door ongesnoeid.', 'Laat afgevallen appels in de winter liggen — ze zijn onmisbaar voedsel bij kou.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'nl', 'Koolmees', 'Koolmezen hebben een enorme woordenschat en leren nieuwe roepjes van hun buren.', 'Het hele jaar; luister vanaf het late winterseizoen naar het heldere "tie-ta tie-ta".', 'Hang een nestkast met een opening van 32 mm op een rustige, schaduwrijke plek.', 'Vermijd bestrijdingsmiddelen in de tuin zodat er genoeg rupsen zijn voor de jongen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'nl', 'Pimpelmees', 'Eén broedsel pimpelmezen kan meer dan duizend rupsen opeten.', 'Het hele jaar in tuinen en bossen, vaak ondersteboven hangend aan dunne twijgen.', 'Hang een kleine nestkast met een opening van 25 mm uit de overheersende wind.', 'Sla insecticiden in het voorjaar over zodat er rupsen zijn voor de jongen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'nl', 'Vink', 'De zang van de vink verschilt per streek, bijna als plaatselijke dialecten.', 'Voorjaar tot herfst; mannetjes zingen een heldere, dalende slag vanaf open zitplaatsen.', 'Laat wat zaaddragende planten en ruige plekjes het seizoen door staan.', 'Houd voedertafels schoon om ziekten onder vinken te voorkomen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'nl', 'Gaai', 'Gaaien begraven elke herfst duizenden eikels en planten hele eikenbossen door er wat te vergeten.', 'Het hele jaar in eikenbos; let in de herfst op flitsen van roze en blauw.', 'Laat gevallen eikels en bladafval onder eiken met rust.', 'Houd honden op de paden in het bos zodat grondfoeragerende vogels niet opvliegen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'nl', 'Grote bonte specht', 'Het "roffelen" in het voorjaar is geen eten zoeken maar een snelle roffel om het territorium te claimen.', 'Het hele jaar; luister laat in de winter naar het roffelen dat door het bos galmt.', 'Laat staand dood hout staan; daarin zitten de insecten waar spechten van leven.', 'Vel geen dode of stervende bomen die nestholtes kunnen bevatten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'nl', 'Witte kwikstaart', 'Het voortdurend wippen met de staart signaleert mogelijk alertheid richting roofdieren.', 'Voorjaar tot herfst bij water en open grond, rennend en stoppend om insecten te grijpen.', 'Houd een stuk kort gras of grind bij het water waar ze kunnen foerageren.', 'Verstoor grind- en oeverstroken niet, waar kwikstaarten eten en broeden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'nl', 'Kraanvogel', 'Kraanvogels voeren in het vroege voorjaar springende, buigende baltsdansen uit.', 'Van voorjaar tot herfst bij moerassen; hun trompetterende roep draagt kilometers ver.', 'Steun de bescherming van ongedraineerde venen en natte hooilanden waar kraanvogels broeden.', 'Bekijk broedmoerassen van een afstand — kraanvogels verlaten verstoorde nesten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'nl', 'Wilde zwaan', 'Wilde zwanen blijven levenslang bij elkaar en kondigen hun komst luid trompetterend aan.', 'In voor- en najaar op meren en ondergelopen velden, vaak in familiegroepen.', 'Steun het nat en ondiep houden van meeroevers en drassige akkers.', 'Voer zwanen nooit brood — het schaadt hen; houd afstand op het ijs.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'nl', 'Wilde eend', 'Kuikens kunnen binnen enkele uren na het uitkomen zwemmen en zelf eten zoeken.', 'Het hele jaar op vrijwel elke vijver, elk meer of elke traag stromende rivier.', 'Voer je eenden, gebruik dan haver, erwten of zaden in plaats van brood.', 'Houd honden in het voorjaar uit het water waar eenden broeden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'nl', 'Buizerd', 'Buizerds zweven op brede vleugels en roepen vaak met een katachtig "pieee-jauw".', 'Voorjaar tot herfst; speur de lucht af naar cirkelende vogels boven velden en bosranden.', 'Steun ruig grasland en akkerranden waar woelmuizen en andere prooi leven.', 'Gebruik nooit rattengif — het klimt via de voedselketen omhoog naar roofvogels.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'nl', 'Visarend', 'Visarenden duiken met de poten vooruit en dragen prooi tot half hun eigen gewicht.', 'Voorjaar tot herfst bij grote meren; let op het bidden gevolgd door een spectaculaire duik.', 'Steun kunstmatige nestplatforms op hoge palen bij visrijke meren.', 'Blijf ver van nestplatforms zodat paren niet van hun eieren worden verjaagd.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'nl', 'Vos', 'Vossen gebruiken het aardmagnetisch veld om hun sprong op verborgen prooi in te schatten.', 'Het hele jaar, het actiefst bij dageraad en schemer langs bos- en veldranden.', 'Laat een wilde, ongestoorde hoek liggen waar vossen kunnen rusten en een hol graven.', 'Zet vuilnisbakken vast en laat nooit schadelijke etensresten achter voor vossen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'nl', 'Egel', 'Een egel legt in één nacht foerageren een paar kilometer af.', 'Van voorjaar tot herfst na donker; in de winter houdt hij winterslaap onder blad- en takkenhopen.', 'Maak een opening van 13 cm in schuttingen zodat egels tussen tuinen kunnen zwerven.', 'Controleer lang gras vóór het maaien en laat bladhopen liggen voor de winterslaap.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'nl', 'Ree', 'Reeën stellen hun dracht uit zodat de kalfjes altijd in de vroege zomer worden geboren.', 'Het hele jaar aan bosranden, het best zichtbaar grazend bij dageraad en schemer.', 'Steun ongemaaide akkerranden en struweel die reeën dekking en voedsel geven.', 'Houd honden in de vroege zomer aangelijnd bij bos, wanneer kalfjes verscholen liggen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'nl', 'Eland', 'De eland is het grootste hertachtige op aarde; een grote stier weegt ruim een halve ton.', 'Het hele jaar in bossen en moerassen, het actiefst bij dageraad en schemer.', 'Steun aaneengesloten bossen en natte corridors die elanden nodig hebben om te trekken.', 'Rijd voorzichtig bij dageraad en schemer op boswegen en nader nooit een kalf.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'nl', 'Eekhoorn', 'Eekhoorns bouwen meerdere nesten en verhuizen ertussen.', 'Het hele jaar in naald- en gemengd bos, het drukst in de vroege ochtend.', 'Laat dennenappels, noten en staande bomen waar eekhoorns eten en nestelen.', 'Houd honden op de paden en verstoor geen bomen die een nest kunnen bevatten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'nl', 'Europese bever', 'Beverdammen scheppen moerassen die vissen, vogels en insecten kilometers ver ten goede komen.', 'Van voorjaar tot late herfst bij traag stromende rivieren, het actiefst in de schemer.', 'Steun het laten liggen van beverdammen en oeverbomen waar dat veilig is.', 'Blijf weg bij burchten en dammen, zeker wanneer de jongen klein zijn.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'nl', 'Sneeuwhaas', 'Sneeuwhazen worden in de winter wit als camouflage tegen de sneeuw.', 'Het hele jaar op open terrein en boskapvlakten, vooral bij dageraad en schemer.', 'Steun een mengeling van open terrein en dekking die hazen het jaar door nodig hebben.', 'Houd honden aangelijnd op open terrein zodat rustende hazen niet worden opgejaagd.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'nl', 'Das', 'Dassen leven in familiegroepen in ondergrondse burchten die generaties lang gebruikt worden.', 'Van voorjaar tot herfst na donker bij bos; de winter verslapen ze grotendeels.', 'Laat ongestoorde taluds en houtwallen liggen waar dassen burchten kunnen graven.', 'Blokkeer of graaf nooit bij een bewoonde burcht — het is hun langjarige thuis.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'nl', 'Gewone dwergvleermuis', 'Deze piepkleine vleermuis eet tot 3.000 muggen en dansmuggen in één nacht.', 'Op zomeravonden: let rond de schemer op de snelle, schokkende vlucht boven tuinen.', 'Hang een vleermuiskast hoog aan een muur of boom die de avondzon vangt.', 'Vermijd fel licht bij verblijfplaatsen en houd de nachtelijke hemel donker voor vleermuizen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'nl', 'Kleine vos', 'Deze vlinder overwintert als volwassen dier, vaak in schuurtjes en op zolders.', 'Van het vroege voorjaar tot de herfst op zonnige bloemen, vooral brandnetels en vlinderstruik.', 'Laat een plek met brandnetels in een zonnige hoek staan — de rupsen hebben ze nodig.', 'Laat overwinterende vlinders in schuurtjes de winter door met rust.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'nl', 'Dagpauwoog', 'De oogvlekken flitsen om vogels af te schrikken en de vleugels kunnen sissen bij het openen.', 'Voorjaar tot herfst op zonnige dagen, op distels, vlinderstruik en afgevallen fruit.', 'Laat een zonnige brandnetelplek groeien voor de rupsen.', 'Stoor volwassen vlinders niet die in schuurtjes en houtstapels overwinteren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'nl', 'Citroenvlinder', 'Het Engelse woord "butterfly" komt mogelijk van de botergele kleur van het mannetje.', 'Een van de eerste vlinders van het voorjaar; kijk op warme dagen langs bosranden.', 'Steun vuilboom en wegedoorn in hagen, de enige planten waar de rupsen van eten.', 'Ruim ruige houtwallen niet op; daar schuilen overwinterende vlinders.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'nl', 'Oranjetipje', 'Alleen de mannetjes hebben de felle oranje vleugelpunten; vrouwtjes zijn wit.', 'In het voorjaar langs vochtige hooilanden en paden waar pinksterbloem groeit.', 'Laat pinksterbloem en look-zonder-look groeien in vochtige, ongemaaide hoeken.', 'Stel het maaien van bermen uit tot de rupsen zijn uitgegroeid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'nl', 'Icarusblauwtje', 'De rupsen van het icarusblauwtje worden soms door mieren verzorgd om hun zoete afscheiding.', 'Vanaf het late voorjaar op zonnig grasland vol klaver en rolklaver.', 'Laat grasland ongemaaid zodat rolklaver en klaver kunnen bloeien.', 'Spuit geen onkruidbestrijder op bloemrijk grasland.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'nl', 'Klein geaderd witje', 'Ondanks de gelijkenis met het koolwitje verkiest het wilde planten boven tuingewassen.', 'Voorjaar tot late zomer in vochtige hooilanden, sloten en bospaden.', 'Laat vochtige hoeken verwilderen met inheemse kruisbloemigen zoals pinksterbloem.', 'Vermijd het draineren en bespuiten van vochtige hooilanden waar het zich voortplant.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'nl', 'Zevenstippelig lieveheersbeestje', 'Eén lieveheersbeestje eet in zijn leven duizenden bladluizen op.', 'Van voorjaar tot herfst op planten met bladluis; in de winter klitten ze samen om te overwinteren.', 'Verdraag wat bladluis en sla sproeien over zodat lieveheersbeestjes te eten hebben.', 'Laat holle stengels en bladafval liggen waar ze de winter doorkomen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'nl', 'Aardhommel', 'Koninginnen zijn in het voorjaar bij de eerste bijen, laag zoemend op zoek naar nestholtes.', 'Van het vroege voorjaar tot de herfst op bloemen; koninginnen zoeken in het voorjaar heggenvoeten af.', 'Plant of laat vroegbloeiende planten staan en laat klaver in het gazon bloeien.', 'Laat ongestoorde taluds en oude muizenholen liggen waar kolonies nestelen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'nl', 'Westerse honingbij', 'Haalbijen vertellen de kast waar bloemen staan door in een acht te dansen.', 'Van voorjaar tot herfst op bloemen, op warme, windstille dagen.', 'Laat door de seizoenen heen uiteenlopende bloemen bloeien en zet een ondiepe waterschaal neer.', 'Spuit niet op bloeiende planten, en nooit midden op de dag.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'nl', 'Grote keizerlibel', 'Een van de grootste libellen van Europa; hij vangt zijn prooi zelfs in de vlucht.', 'Op warme zomerdagen patrouilleert hij langs vijvers en meeroevers.', 'Houd of graaf een vijver met planten en laat de oevers begroeid.', 'Houd vijvers vrij van vervuiling en afspoeling zodat de larven zich kunnen ontwikkelen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'nl', 'Bruinrode heidelibel', 'Heidelibellen zitten vaak op dezelfde warme plek en schieten uit om langsvliegende insecten te grijpen.', 'Van hoogzomer tot herfst bij stilstaand water, zonnend op paden en paaltjes.', 'Laat zonnige zitplekken en begroeiing rond vijvers en sloten staan.', 'Voorkom dat mest of olie in vijvers spoelt waar de larven leven.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'nl', 'Rode bosmier', 'Hun koepelnesten kunnen meer dan een meter hoog zijn en een half miljoen mieren huisvesten.', 'Van voorjaar tot herfst in naaldbos; let op koepels van dennennaalden.', 'Laat mierenhopen ongemoeid — ze zijn jaren in de maak.', 'Blijf op de paden en schop of graaf nooit in een mierenhoop.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'nl', 'Bosanemoon', 'Bosanemonen breiden zich zo traag uit dat dichte tapijten op oud bos wijzen.', 'In het voorjaar: zoek naar tapijten van witte bloemen vóór de bomen uitlopen.', 'Laat de bosbodem ongestoord zodat de traag kruipende wortelstokken kunnen gedijen.', 'Geniet ervan waar ze staan — plukken haalt bloemen weg die jaren nodig hadden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'nl', 'Lelietje-van-dalen', 'Elk deel van deze zoet geurende plant is giftig bij inname.', 'In het late voorjaar: volg de geur naar schaduwrijk bos en schaduwrijke tuinen.', 'Laat schaduwrijke bosranden en bladafval liggen waar de plant groeit.', 'Pluk of rooi hem niet en houd hem uit de buurt van kinderen en huisdieren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'nl', 'Daslook', 'Daslook ruik je meestal eerder dan je de witte bloemen ziet.', 'In het voorjaar: zoek brede groene bladeren en stervormige bloemen in vochtig bos.', 'Laat vochtig bos ongestoord zodat de tapijten elk jaar terug kunnen groeien.', 'Als plukken plaatselijk mag: neem maar weinig mee en trek nooit bollen uit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'nl', 'Dotterbloem', 'Een van de oudste inheemse planten; hij overleefde de laatste ijstijd in Scandinavië.', 'In het voorjaar: zoek grote gouden bloemen in moerassen, sloten en vijveroevers.', 'Houd vijver- en slootranden nat en ongemaaid zodat de plant kan bloeien.', 'Draineer natte grond niet en laat de planten staan waar ze groeien.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'nl', 'Gulden sleutelbloem', 'Sleutelbloemen waren ooit zo talrijk in hooilanden dat kinderen er ballen van maakten.', 'In het voorjaar: zoek knikkende gele bloemen in oude, onbemeste hooilanden.', 'Laat hooilanden ongemaaid tot de sleutelbloemen gebloeid en zaad gezet hebben.', 'Pluk of rooi ze niet in het wild — hooilandbloemen gaan achteruit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'nl', 'Margriet', 'De bloem van de margriet bestaat in werkelijkheid uit tientallen piepkleine bloemen.', 'In de zomer: zoek grote witte margrieten langs wegbermen en in hooilanden.', 'Laat een strook gras de hoogzomer door ongemaaid zodat de plant kan bloeien.', 'Spuit geen onkruidbestrijder op bermen en hooilanden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'nl', 'Paardenbloem', 'Paardenbloemen zijn een van de belangrijkste vroege nectarbronnen voor bijen.', 'Vanaf het voorjaar vrijwel overal; de bloemen openen in de zon en sluiten bij schemer.', 'Laat paardenbloemen in het voorjaar bloeien vóór de eerste maaibeurt.', 'Sla onkruidbestrijders op het gazon over zodat vroege bestuivers dit voedsel houden.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'nl', 'Struikhei', 'Eén heideplant kan meer dan honderdduizend piepkleine zaden voortbrengen.', 'In de late zomer: zoek paarse tapijten op open heide en hoogveen.', 'Steun het open en ongedraineerd houden van heidegebieden.', 'Blijf op de paden op de heide en stook nooit vuur bij droogte.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'nl', 'Blauwe bosbes', 'Bosbessen kleuren je vingers blauw en voeden alles van vogels tot beren.', 'In de zomer: zoek lage struikjes met donkere bessen in dennen- en sparrenbos.', 'Laat de bosondergroei intact zodat de lage struikjes vrucht kunnen dragen.', 'Als plukken plaatselijk mag: laat ruim bessen achter voor de dieren.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'nl', 'Rode bosbes', 'Rode bosbessen blijven maanden goed dankzij een natuurlijk conserveermiddel in de vrucht.', 'In de late zomer en herfst: zoek glanzende rode bessen op groenblijvende matten.', 'Laat de begroeiing van de bosbodem ongestoord zodat de matten zich kunnen uitbreiden.', 'Als plukken plaatselijk mag: loop voorzichtig om de plantjes niet te vertrappen.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'nl', 'Ruwe berk', 'Een berk draagt honderden insectensoorten en voedt daarmee talloze vogels.', 'Het hele jaar; de witte, afschilferende bast maakt hem in elk seizoen herkenbaar.', 'Laat gevallen berkenbladeren en dood hout liggen om de bodem te verrijken en insecten te voeden.', 'Trek geen bast los; dat verwondt en verzwakt de boom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'nl', 'Fijnspar', 'Een fijnspar in Zweden groeit uit wortels die duizenden jaren oud zijn.', 'Het hele jaar in bossen; zijn hangende kegels zijn de langste van alle sparren.', 'Laat gevallen kegels en dood hout liggen; ze bieden onderdak aan insecten en zwammen.', 'Blijf op de paden in het bos om de ondiepe sparrenwortels niet te verdichten.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'nl', 'Grove den', 'Oude grove dennen gloeien oranje bij de top en kunnen eeuwen oud worden.', 'Het hele jaar op zandige en rotsige grond; let op de oranje bast hoog in de stam.', 'Laat staand dood hout en oude dennen staan; ze zitten vol leven.', 'Stook nooit vuur tegen of bij dennen op droge, zandige grond.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'nl', 'Snoek', 'De snoek is een sluiproofvis die vanuit stilstand in een oogwenk toeslaat.', 'Van voorjaar tot herfst in de begroeide ondiepten van meren en trage rivieren.', 'Steun het behoud van rietige ondiepten en waterplanten waar jonge vis schuilt.', 'Houd vervuiling en afval uit het water; volg de plaatselijke visserijregels.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'nl', 'Baars', 'Baarzen jagen in groepen en dragen forse strepen die hun omtrek doorbreken.', 'In de warmere maanden rond steigers, waterplantenvelden en steilranden.', 'Steun schoon water en onderwaterstructuur die kleine vis beschutting geeft.', 'Kieper nooit iets in meren en rivieren; volg de plaatselijke visserijregels.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'nl', 'Blankvoorn', 'De blankvoorn is een sleutelprooivis waarvan veel roofdieren in meren afhankelijk zijn.', 'In de warmere maanden in scholen vlak onder het oppervlak van meren en trage rivieren.', 'Steun schoon water en begroeide oevers waar de vissen kunnen paaien.', 'Houd afspoeling en afval uit het water; volg de plaatselijke visserijregels.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'fr', 'Martinet noir', 'Les martinets peuvent rester en vol des mois durant et dorment même en plein ciel.', 'Par les soirées douces d’été, levez les yeux au-dessus des toits et écoutez les rondes criardes.', 'Posez un nichoir à martinets sous l’avant-toit avant le retour des oiseaux au printemps.', 'Lors de travaux, conservez les petites fentes sous l’avant-toit où ils nichent.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'fr', 'Hirondelle rustique', 'Les hirondelles rustiques migrent chaque année jusqu’en Afrique australe et en reviennent.', 'Du printemps au début de l’automne, on les voit raser les champs ouverts et l’eau.', 'Laissez une porte de grange ou d’appentis entrouverte pour qu’elles atteignent leurs corniches.', 'Ne détruisez pas les vieux nids de boue — les hirondelles les réutilisent d’année en année.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'fr', 'Coucou gris', 'Le coucou pond dans les nids d’autres oiseaux et n’élève jamais ses propres jeunes.', 'À la fin du printemps, écoutez le « cou-cou » qui porte loin depuis les lisières.', 'Soutenez les prairies et les haies riches en insectes qui nourrissent ses hôtes.', 'Restez sur les sentiers près des fourrés et des roselières pour ne pas déranger les hôtes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'fr', 'Rougegorge familier', 'Le rougegorge défend farouchement son territoire et chante la nuit près des lampadaires.', 'Toute l’année dans les jardins et les bois ; il suit volontiers qui bêche, espérant des vers.', 'Laissez un coin du jardin couvert de feuilles mortes où il pourra chercher sa nourriture.', 'Reportez les grosses tailles de haies jusqu’à la fin de la nidification, en fin d’été.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'fr', 'Merle noir', 'Le chant flûté et ample du mâle est l’un des plus reconnaissables d’Europe.', 'Toute l’année ; écoutez les mâles chanter des toits et des cimes à l’aube et au crépuscule.', 'Mettez de l’eau fraîche à disposition pour boire et se baigner, surtout par temps sec.', 'Gardez les chats à l’intérieur au lever du jour pendant la nidification.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'fr', 'Grive litorne', 'La litorne est une grive sociable qui erre en bandes hivernales bruyantes et jacassantes.', 'En automne et en hiver, observez les bandes dépouiller les haies et les sorbiers.', 'Laissez les arbustes à baies, sorbier et aubépine, non taillés pendant l’hiver.', 'Laissez les pommes tombées au sol en hiver — c’est une nourriture vitale par grand froid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'fr', 'Mésange charbonnière', 'La mésange charbonnière possède un vaste répertoire et apprend de nouveaux cris de ses voisines.', 'Toute l’année ; dès la fin de l’hiver, écoutez son chant sonore en deux notes répétées.', 'Installez un nichoir à trou de 32 mm dans un endroit calme et ombragé.', 'Évitez les pesticides au jardin pour que les chenilles suffisent à nourrir les jeunes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'fr', 'Mésange bleue', 'Une seule nichée de mésanges bleues peut consommer plus d’un millier de chenilles.', 'Toute l’année dans les jardins et les bois, souvent suspendue tête en bas aux fines brindilles.', 'Posez un petit nichoir à trou de 25 mm à l’abri des vents dominants.', 'Renoncez aux insecticides au printemps pour laisser les chenilles aux jeunes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'fr', 'Pinson des arbres', 'Le chant du pinson varie d’une région à l’autre, presque comme des dialectes locaux.', 'Du printemps à l’automne ; les mâles lancent une phrase claire et descendante depuis un perchoir dégagé.', 'Laissez sur pied quelques têtes de graines et des coins enherbés pendant la saison.', 'Nettoyez les mangeoires pour éviter la propagation des maladies chez les fringilles.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'fr', 'Geai des chênes', 'Le geai enterre des milliers de glands chaque automne et plante des chênaies entières en en oubliant.', 'Toute l’année dans les chênaies ; guettez à l’automne les éclats de rose et de bleu.', 'Laissez en place les glands tombés et la litière de feuilles sous les chênes.', 'Gardez les chiens sur les sentiers en forêt pour ne pas faire fuir les oiseaux qui se nourrissent au sol.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'fr', 'Pic épeiche', 'Le « tambourinage » du printemps n’est pas une recherche de nourriture mais un roulement pour marquer le territoire.', 'Toute l’année ; à la fin de l’hiver, écoutez le tambourinage résonner dans les bois.', 'Laissez sur pied le bois mort, qui abrite les insectes dont il se nourrit.', 'N’abattez pas les arbres morts ou dépérissants susceptibles de contenir des loges.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'fr', 'Bergeronnette grise', 'Le hochement continuel de la queue signale peut-être sa vigilance face aux prédateurs.', 'Du printemps à l’automne près de l’eau et des sols nus, courant puis s’arrêtant pour happer des insectes.', 'Gardez près de l’eau une bande d’herbe rase ou de gravier où elle pourra chercher sa nourriture.', 'Évitez de piétiner les grèves et les berges où elle se nourrit et niche.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'fr', 'Grue cendrée', 'Les grues exécutent au début du printemps des parades faites de bonds et de révérences.', 'Du printemps à l’automne autour des zones humides ; leurs cris de trompe portent à des kilomètres.', 'Soutenez la protection des tourbières non drainées et des prairies humides où elles nichent.', 'Observez les zones de nidification de loin — les grues abandonnent un nid dérangé.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'fr', 'Cygne chanteur', 'Le cygne chanteur s’unit pour la vie et annonce son arrivée par de puissants appels de trompe.', 'Au printemps et à l’automne sur les lacs et les champs inondés, souvent en groupes familiaux.', 'Soutenez le maintien des rives peu profondes et des champs humides à l’abri du drainage.', 'Ne donnez jamais de pain aux cygnes — cela leur nuit ; gardez vos distances sur la glace.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'fr', 'Canard colvert', 'Les canetons savent nager et se nourrir seuls quelques heures après l’éclosion.', 'Toute l’année sur presque tous les étangs, lacs et rivières lentes.', 'Si vous nourrissez les canards, préférez l’avoine, les pois ou les graines au pain.', 'Tenez les chiens hors de l’eau au printemps, là où les canards nichent.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'fr', 'Buse variable', 'La buse plane sur de larges ailes et lance souvent un miaulement traînant, « piiii-iou ».', 'Du printemps à l’automne ; scrutez le ciel au-dessus des champs et des lisières.', 'Soutenez les prairies rustiques et les bordures de champs qui abritent campagnols et petites proies.', 'N’utilisez jamais de raticides : ils remontent la chaîne alimentaire jusqu’aux rapaces.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'fr', 'Balbuzard pêcheur', 'Le balbuzard plonge serres en avant et peut emporter une proie de la moitié de son poids.', 'Du printemps à l’automne près des grands lacs ; guettez le vol sur place puis le piqué spectaculaire.', 'Soutenez l’installation de plateformes de nidification sur mâts près des lacs poissonneux.', 'Passez au large des plateformes pour ne pas faire quitter les œufs aux couples.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'fr', 'Renard roux', 'Le renard s’aide du champ magnétique terrestre pour ajuster son bond sur une proie cachée.', 'Toute l’année, surtout à l’aube et au crépuscule le long des lisières et des champs.', 'Laissez un coin sauvage et tranquille où les renards peuvent se reposer et creuser un terrier.', 'Fermez bien les poubelles et ne laissez jamais de restes nocifs à leur portée.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'fr', 'Hérisson d''Europe', 'Un hérisson peut parcourir quelques kilomètres au cours d’une seule nuit de quête.', 'Du printemps à l’automne après la tombée du jour ; l’hiver, il hiberne sous les tas de feuilles et de bois.', 'Ménagez un passage de 13 cm dans les clôtures pour qu’il circule d’un jardin à l’autre.', 'Inspectez les herbes hautes avant de débroussailler et laissez les tas de feuilles pour l’hibernation.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'fr', 'Chevreuil européen', 'Le chevreuil diffère sa gestation pour que les faons naissent toujours au début de l’été.', 'Toute l’année en lisière de bois, surtout visible en train de brouter à l’aube et au crépuscule.', 'Soutenez les bordures de champs non fauchées et les fourrés qui lui offrent couvert et nourriture.', 'Tenez les chiens en laisse près des bois au début de l’été, quand les faons restent tapis.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'fr', 'Élan', 'L’élan est le plus grand cervidé du monde ; un grand mâle dépasse la demi-tonne.', 'Toute l’année dans les forêts et les zones humides, surtout actif à l’aube et au crépuscule.', 'Soutenez les massifs forestiers connectés et les corridors humides dont il a besoin pour se déplacer.', 'Roulez prudemment à l’aube et au crépuscule sur les routes forestières et n’approchez jamais un faon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'fr', 'Écureuil roux', 'L’écureuil roux construit plusieurs nids, appelés hottes, et passe de l’un à l’autre.', 'Toute l’année dans les résineux et les bois mixtes, très actif en début de matinée.', 'Laissez cônes, noisettes et arbres sur pied dont il tire nourriture et abri.', 'Gardez les chiens sur les sentiers et ne secouez pas les arbres pouvant porter un nid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'fr', 'Castor d''Europe', 'Les barrages de castors créent des zones humides qui profitent aux poissons, aux oiseaux et aux insectes sur des kilomètres.', 'Du printemps à la fin de l’automne le long des rivières lentes, surtout actif au crépuscule.', 'Soutenez le maintien des barrages et des arbres de berge là où c’est sans danger.', 'Tenez-vous à l’écart des huttes et des barrages, surtout quand les jeunes sont petits.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'fr', 'Lièvre variable', 'Le lièvre variable blanchit en hiver pour se fondre dans la neige.', 'Toute l’année en terrain ouvert et dans les clairières, surtout à l’aube et au crépuscule.', 'Soutenez la mosaïque de milieux ouverts et de couvert dont il a besoin toute l’année.', 'Tenez les chiens en laisse en terrain ouvert pour ne pas faire courir les lièvres au repos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'fr', 'Blaireau européen', 'Le blaireau vit en groupes familiaux dans des terriers souterrains occupés depuis des générations.', 'Du printemps à l’automne après la nuit tombée près des bois ; il passe l’hiver à dormir.', 'Laissez tranquilles talus et haies où il peut creuser son terrier.', 'N’obstruez jamais un terrier occupé et ne creusez pas à côté — c’est son foyer de longue date.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'fr', 'Pipistrelle commune', 'Cette minuscule chauve-souris peut avaler jusqu’à 3 000 moucherons et moustiques en une nuit.', 'Les soirs d’été, guettez au crépuscule son vol rapide et saccadé au-dessus des jardins.', 'Fixez un gîte à chauves-souris haut sur un mur ou un arbre exposé au soleil du soir.', 'Évitez d’éclairer vivement les entrées de gîtes et gardez le ciel nocturne sombre.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'fr', 'Petite tortue', 'Ce papillon hiverne à l’état adulte, souvent dans les remises et les greniers.', 'Du début du printemps à l’automne sur les fleurs ensoleillées, surtout orties et arbres à papillons.', 'Laissez un carré d’orties dans un coin ensoleillé — ses chenilles en dépendent.', 'Ne dérangez pas les adultes hivernant dans les remises pendant la saison froide.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'fr', 'Paon-du-jour', 'Ses ocelles s’ouvrent brusquement pour effrayer les oiseaux, et ses ailes peuvent siffler.', 'Du printemps à l’automne par beau temps, sur les chardons, les buddleias et les fruits tombés.', 'Laissez pousser un carré d’orties au soleil pour ses chenilles.', 'Ne dérangez pas les adultes abrités dans les remises et les tas de bois en hiver.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'fr', 'Citron', 'Le mot anglais « butterfly » viendrait de la teinte jaune beurre du mâle de cette espèce.', 'L’un des premiers papillons du printemps ; cherchez-le en lisière par temps doux.', 'Soutenez les bourdaines et nerpruns des haies, seules plantes dont ses chenilles se nourrissent.', 'Évitez de nettoyer les haies broussailleuses qui abritent les adultes hivernants.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'fr', 'Aurore', 'Seuls les mâles portent les vives pointes orange ; les femelles sont blanches.', 'Au printemps, le long des prairies humides et des chemins où pousse la cardamine des prés.', 'Laissez pousser cardamine et alliaire dans les coins humides non fauchés.', 'Retardez la fauche des bords de route jusqu’à la fin du développement des chenilles.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'fr', 'Azuré commun', 'Ses chenilles sont parfois soignées par des fourmis attirées par leurs sécrétions sucrées.', 'À partir de la fin du printemps sur les pelouses ensoleillées riches en trèfles et en lotier.', 'Laissez la prairie non fauchée pour que lotiers et trèfles puissent fleurir.', 'Évitez de traiter au désherbant les prairies riches en fleurs sauvages.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'fr', 'Piéride du navet', 'Malgré son air de piéride du chou, elle préfère les plantes sauvages aux cultures du jardin.', 'Du printemps à la fin de l’été dans les prés humides, les fossés et les allées forestières.', 'Laissez les coins humides s’ensauvager avec des crucifères indigènes comme la cardamine.', 'Évitez de drainer et de traiter les prés humides où elle se reproduit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'fr', 'Coccinelle à sept points', 'Une seule coccinelle dévore des milliers de pucerons au cours de sa vie.', 'Du printemps à l’automne sur les plantes à pucerons ; l’hiver, elles s’agglutinent pour hiverner.', 'Tolérez quelques pucerons et renoncez aux traitements pour qu’elles aient de quoi manger.', 'Laissez les tiges creuses et la litière de feuilles où elles s’abritent l’hiver.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'fr', 'Bourdon terrestre', 'Les reines comptent parmi les premières abeilles du printemps, bourdonnant au ras du sol en quête d’un trou.', 'Du début du printemps à l’automne sur les fleurs ; au printemps les reines fouillent le pied des haies.', 'Plantez ou conservez des espèces à floraison précoce et laissez fleurir le trèfle de la pelouse.', 'Laissez tranquilles les talus et les vieux trous de mulots où s’installent les colonies.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'fr', 'Abeille domestique', 'Les butineuses indiquent à la ruche où sont les fleurs en dansant en forme de huit.', 'Du printemps à l’automne sur les fleurs, par temps doux et sans vent.', 'Faites se succéder des floraisons variées au fil des saisons et posez une coupelle d’eau peu profonde.', 'Ne traitez pas les plantes en fleur, et jamais en milieu de journée.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'fr', 'Anax empereur', 'L’une des plus grandes libellules d’Europe : elle capture même ses proies en plein vol.', 'Par les journées chaudes d’été, observez-la patrouiller mares et rives de lacs.', 'Conservez ou creusez une mare plantée et laissez ses bords se végétaliser.', 'Préservez les mares de la pollution et du ruissellement pour que les larves se développent.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'fr', 'Sympétrum strié', 'Le sympétrum se pose souvent au même endroit chaud et s’élance pour saisir les insectes de passage.', 'De la mi-été à l’automne près des eaux calmes, en train de lézarder sur sentiers et piquets.', 'Laissez des perchoirs ensoleillés et de la végétation autour des mares et des fossés.', 'Empêchez engrais et huiles de ruisseler vers les mares où vivent les larves.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'fr', 'Fourmi rousse des bois', 'Leurs dômes d’aiguilles peuvent dépasser un mètre de haut et abriter un demi-million de fourmis.', 'Du printemps à l’automne dans les forêts de conifères ; cherchez les dômes d’aiguilles.', 'Laissez les fourmilières intactes — leur construction prend des années.', 'Restez sur les sentiers et ne donnez jamais de coup de pied ni de coup de bêche dans une fourmilière.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'fr', 'Anémone des bois', 'L’anémone des bois s’étend si lentement qu’un tapis dense signale une forêt ancienne.', 'Au printemps, cherchez les tapis de fleurs blanches avant que les arbres ne feuillent.', 'Laissez le sol forestier tranquille pour que ses rhizomes lents puissent prospérer.', 'Admirez-la sur place — la cueillir supprime des fleurs qui ont mis des années à s’installer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'fr', 'Muguet de mai', 'Toutes les parties de cette plante au parfum suave sont toxiques si on les ingère.', 'À la fin du printemps, suivez le parfum jusqu’aux sous-bois et aux jardins ombragés.', 'Laissez en place les lisières ombragées et la litière de feuilles où elle pousse.', 'Ne la cueillez pas et ne l’arrachez pas ; tenez-la hors de portée des enfants et des animaux.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'fr', 'Ail des ours', 'On sent l’ail des ours bien avant d’apercevoir ses fleurs blanches.', 'Au printemps, cherchez les larges feuilles vertes et les fleurs étoilées dans les bois humides.', 'Laissez les bois humides tranquilles pour que les tapis repoussent chaque année.', 'Si la cueillette est permise localement, prenez peu et n’arrachez jamais les bulbes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'fr', 'Populage des marais', 'L’une des plus anciennes plantes indigènes : elle a survécu à la dernière glaciation en Scandinavie.', 'Au printemps, cherchez ses grandes fleurs dorées dans les marais, les fossés et les bords de mare.', 'Gardez les bords de mares et de fossés humides et non fauchés pour qu’elle fleurisse.', 'Évitez de drainer les sols humides et laissez les plantes là où elles poussent.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'fr', 'Primevère officinale', 'La primevère officinale était jadis si commune dans les prés de fauche que les enfants en faisaient des boules.', 'Au printemps, cherchez ses fleurs jaunes penchées dans les vieux prés non amendés.', 'Laissez les prés non fauchés jusqu’à ce qu’elle ait fleuri et grainé.', 'Ne la cueillez ni ne l’arrachez dans la nature — les fleurs de prairie déclinent.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'fr', 'Marguerite commune', 'La « fleur » de la marguerite est en réalité un assemblage de dizaines de fleurs minuscules.', 'En été, cherchez ses grandes marguerites blanches le long des routes et dans les prés.', 'Laissez une bande d’herbe non fauchée jusqu’au cœur de l’été pour qu’elle puisse fleurir.', 'Évitez de traiter au désherbant les bords de route et les prairies.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'fr', 'Pissenlit commun', 'Le pissenlit est l’une des toutes premières sources de nectar pour les abeilles.', 'Dès le printemps à peu près partout ; ses fleurs s’ouvrent au soleil et se ferment au crépuscule.', 'Laissez les pissenlits fleurir sur la pelouse au printemps avant la première tonte.', 'Renoncez aux désherbants de pelouse pour préserver cette nourriture des premiers pollinisateurs.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'fr', 'Callune', 'Un seul pied de callune peut produire plus de cent mille graines minuscules.', 'À la fin de l’été, cherchez les tapis pourpres sur les landes ouvertes et les tourbières.', 'Soutenez le maintien des landes ouvertes et non drainées.', 'Restez sur les sentiers en lande et n’allumez jamais de feu par temps sec.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'fr', 'Myrtille', 'La myrtille teinte les doigts en bleu et nourrit tout le monde, des oiseaux aux ours.', 'En été, cherchez les buissons bas aux baies sombres dans les pinèdes et les pessières.', 'Laissez le sous-bois intact pour que les buissons bas puissent fructifier.', 'Si la cueillette est permise localement, laissez beaucoup de baies pour la faune.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'fr', 'Airelle rouge', 'L’airelle rouge se conserve des mois grâce à un conservateur naturel présent dans le fruit.', 'À la fin de l’été et en automne, cherchez ses baies rouges luisantes sur des tapis persistants.', 'Laissez la végétation du sol forestier tranquille pour que les tapis s’étendent.', 'Si la cueillette est permise localement, marchez avec précaution pour ne pas écraser les plantes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'fr', 'Bouleau verruqueux', 'Un bouleau héberge des centaines d’espèces d’insectes et nourrit ainsi d’innombrables oiseaux.', 'Toute l’année ; son écorce blanche qui s’exfolie le rend reconnaissable en toute saison.', 'Laissez au sol les feuilles tombées et le bois mort : ils enrichissent la terre et nourrissent les insectes.', 'Évitez d’arracher l’écorce, ce qui blesse et affaiblit l’arbre.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'fr', 'Épicéa commun', 'En Suède, un épicéa pousse sur des racines vieilles de plusieurs milliers d’années.', 'Toute l’année en forêt ; ses cônes pendants sont les plus longs de tous les épicéas.', 'Laissez les cônes tombés et le bois mort, qui abritent insectes et champignons.', 'Restez sur les sentiers en forêt pour ne pas tasser les racines superficielles de l’épicéa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'fr', 'Pin sylvestre', 'Les vieux pins sylvestres rougeoient d’orange vers la cime et peuvent vivre des siècles.', 'Toute l’année sur les sols sableux et rocheux ; repérez l’écorce orange du haut du tronc.', 'Laissez sur pied le bois mort et les vieux pins, très riches en vie sauvage.', 'N’allumez jamais de feu contre ou près des pins sur un sol sec et sableux.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'fr', 'Grand brochet', 'Le brochet est un prédateur d’affût capable de jaillir de l’immobilité en un clin d’œil.', 'Du printemps à l’automne dans les hauts-fonds herbeux des lacs et des rivières lentes.', 'Soutenez le maintien des hauts-fonds à roseaux et des herbiers où s’abritent les alevins.', 'Gardez pollution et déchets hors de l’eau ; respectez la réglementation locale de pêche.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'fr', 'Perche commune', 'La perche chasse en bandes et porte des rayures marquées qui brouillent sa silhouette.', 'Pendant les mois les plus doux, autour des pontons, des herbiers et des cassures.', 'Soutenez une eau propre et les structures immergées qui abritent les petits poissons.', 'Ne déversez jamais rien dans les lacs et les rivières ; respectez la réglementation locale de pêche.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'fr', 'Gardon', 'Le gardon est un poisson-proie clé dont dépendent de nombreux prédateurs des lacs.', 'Pendant les mois les plus doux, en bancs près de la surface des lacs et des rivières lentes.', 'Soutenez une eau propre et des berges végétalisées pour la fraie.', 'Gardez ruissellements et déchets hors de l’eau ; respectez la réglementation locale de pêche.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'it', 'Rondone comune', 'I rondoni restano in volo per mesi interi e dormono perfino mentre volano.', 'Nelle sere calde d’estate guarda in alto sopra i tetti e ascolta gli stormi striduli.', 'Monta una cassetta per rondoni sotto la gronda prima che tornino in primavera.', 'Durante i lavori di ristrutturazione conserva le fessure sotto la gronda dove nidificano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'it', 'Rondine comune', 'Le rondini migrano ogni anno fino all’Africa meridionale e ritornano.', 'Dalla primavera all’inizio dell’autunno sfiorano campi aperti e specchi d’acqua.', 'Lascia socchiusa la porta di una stalla o di un capanno perché raggiungano i nidi.', 'Non abbattere i vecchi nidi di fango: le rondini li riutilizzano anno dopo anno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'it', 'Cuculo', 'Il cuculo depone le uova nei nidi altrui e non alleva mai i propri piccoli.', 'A tarda primavera ascolta il «cu-cù» che si propaga lontano dai margini del bosco.', 'Sostieni prati e siepi ricchi di insetti, che nutrono gli uccelli ospiti del cuculo.', 'Resta sui sentieri vicino a cespuglieti e canneti per non disturbare gli ospiti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'it', 'Pettirosso', 'Il pettirosso difende con accanimento il territorio e canta di notte vicino ai lampioni.', 'Tutto l’anno in giardini e boschi; segue volentieri chi vanga, sperando in qualche verme.', 'Lascia un angolo di giardino con le foglie cadute dove possa cercare cibo.', 'Rimanda le potature pesanti delle siepi a nidificazione conclusa, a fine estate.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'it', 'Merlo', 'Il canto pieno e flautato del maschio è tra i più riconoscibili d’Europa.', 'Tutto l’anno; all’alba e al tramonto ascolta i maschi cantare da tetti e cime degli alberi.', 'Metti a disposizione acqua fresca per bere e bagnarsi, soprattutto nei periodi secchi.', 'Tieni i gatti in casa alle prime luci durante la stagione dei nidi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'it', 'Cesena', 'La cesena è un tordo socievole che vaga in stormi invernali chiassosi e cinguettanti.', 'In autunno e in inverno osserva gli stormi spogliare siepi e sorbi delle bacche.', 'Lascia non potati per l’inverno gli arbusti da bacca come sorbo e biancospino.', 'Lascia a terra le mele cadute d’inverno: sono cibo vitale col freddo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'it', 'Cinciallegra', 'La cinciallegra ha un vocabolario amplissimo e impara richiami nuovi dai vicini.', 'Tutto l’anno; da fine inverno ascolta il canto squillante a due note ripetute.', 'Appendi una cassetta nido con foro da 32 mm in un punto tranquillo e ombreggiato.', 'Evita i pesticidi in giardino, così i bruchi bastano a sfamare i pulli.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'it', 'Cinciarella', 'Una sola nidiata di cinciarelle può divorare oltre mille bruchi.', 'Tutto l’anno in giardini e boschi, spesso appesa a testa in giù ai rametti sottili.', 'Monta una cassetta piccola con foro da 25 mm al riparo dai venti dominanti.', 'Rinuncia agli insetticidi in primavera, così i bruchi restano ai pulli.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'it', 'Fringuello', 'Il canto del fringuello cambia da regione a regione, quasi fossero dialetti locali.', 'Dalla primavera all’autunno; i maschi cantano una frase brillante e discendente da posatoi scoperti.', 'Lascia in piedi per la stagione qualche pianta andata a seme e qualche angolo incolto.', 'Tieni pulite le mangiatoie per evitare che le malattie si diffondano tra i fringillidi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'it', 'Ghiandaia', 'La ghiandaia sotterra migliaia di ghiande ogni autunno e, dimenticandone alcune, pianta interi querceti.', 'Tutto l’anno nei querceti; in autunno cerca i lampi di rosa e di azzurro.', 'Lascia indisturbate le ghiande cadute e la lettiera di foglie sotto le querce.', 'Tieni i cani sui sentieri nel bosco, così gli uccelli che cercano cibo a terra non si involano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'it', 'Picchio rosso maggiore', 'Il «tambureggiare» primaverile non serve a mangiare: è un rullo rapido per rivendicare il territorio.', 'Tutto l’anno; a fine inverno ascolta il tambureggiare che risuona tra gli alberi.', 'Lascia in piedi il legno morto, che ospita gli insetti di cui si nutre.', 'Non abbattere alberi morti o deperienti che possano contenere cavità di nidificazione.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'it', 'Ballerina bianca', 'Il continuo oscillare della coda segnala forse attenzione verso i predatori.', 'Dalla primavera all’autunno presso l’acqua e i terreni nudi, correndo e fermandosi per ghermire insetti.', 'Mantieni vicino all’acqua una fascia di erba corta o ghiaia dove possa cercare cibo.', 'Evita di calpestare ghiaie e rive dove si nutre e nidifica.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'it', 'Gru cenerina', 'Le gru eseguono a inizio primavera danze nuziali fatte di salti e inchini.', 'Dalla primavera all’autunno intorno alle zone umide; il richiamo squillante si sente per chilometri.', 'Sostieni la tutela delle torbiere non drenate e dei prati umidi dove nidificano.', 'Osserva le zone di nidificazione da lontano: le gru abbandonano i nidi disturbati.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'it', 'Cigno selvatico', 'Il cigno selvatico si accoppia per la vita e annuncia il suo arrivo con richiami squillanti.', 'In primavera e in autunno su laghi e campi allagati, spesso in gruppi familiari.', 'Sostieni il mantenimento delle rive basse e dei campi umidi al riparo dal drenaggio.', 'Non dare mai pane ai cigni: fa loro male; sul ghiaccio mantieni le distanze.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'it', 'Germano reale', 'I pulcini sanno nuotare e nutrirsi da soli poche ore dopo la schiusa.', 'Tutto l’anno su quasi ogni stagno, lago o fiume lento.', 'Se dai da mangiare alle anatre, usa avena, piselli o semi al posto del pane.', 'In primavera tieni i cani fuori dall’acqua dove le anatre nidificano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'it', 'Poiana', 'La poiana veleggia su ali larghe e spesso lancia un miagolio prolungato, «piii-uu».', 'Dalla primavera all’autunno; scruta il cielo sopra campi e margini di bosco.', 'Sostieni prati incolti e bordi dei campi che ospitano arvicole e piccole prede.', 'Non usare mai veleni per roditori: risalgono la catena alimentare fino ai rapaci.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'it', 'Falco pescatore', 'Il falco pescatore si tuffa con gli artigli avanti e può portare prede pari a metà del suo peso.', 'Dalla primavera all’autunno presso i grandi laghi; osserva lo spirito santo e poi la picchiata.', 'Sostieni le piattaforme artificiali di nidificazione su pali alti vicino ai laghi pescosi.', 'Gira al largo dalle piattaforme, così le coppie non abbandonano le uova per lo spavento.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'it', 'Volpe rossa', 'La volpe si aiuta con il campo magnetico terrestre per calibrare il balzo sulle prede nascoste.', 'Tutto l’anno, più attiva all’alba e al tramonto lungo i margini di boschi e campi.', 'Lascia un angolo selvatico e tranquillo dove le volpi possano riposare e scavare la tana.', 'Chiudi bene i bidoni e non lasciare mai avanzi dannosi a portata delle volpi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'it', 'Riccio europeo', 'Un riccio può percorrere un paio di chilometri in una sola notte di ricerca del cibo.', 'Dalla primavera all’autunno dopo il buio; d’inverno va in letargo sotto cumuli di foglie e legna.', 'Apri un varco di 13 cm nelle recinzioni perché i ricci possano spostarsi tra i giardini.', 'Controlla l’erba alta prima di decespugliare e lascia i cumuli di foglie per il letargo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'it', 'Capriolo', 'Il capriolo ritarda la gestazione perché i piccoli nascano sempre a inizio estate.', 'Tutto l’anno ai margini del bosco, più visibile mentre bruca all’alba e al tramonto.', 'Sostieni bordi dei campi non sfalciati e cespuglieti che offrono riparo e cibo.', 'Tieni i cani al guinzaglio vicino al bosco a inizio estate, quando i piccoli restano acquattati.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'it', 'Alce', 'L’alce è il più grande cervide del pianeta: un maschio adulto supera la mezza tonnellata.', 'Tutto l’anno in foreste e zone umide, più attivo all’alba e al tramonto.', 'Sostieni foreste continue e corridoi umidi di cui l’alce ha bisogno per spostarsi.', 'Guida con prudenza all’alba e al tramonto sulle strade forestali e non avvicinarti mai a un piccolo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'it', 'Scoiattolo rosso', 'Lo scoiattolo rosso costruisce più nidi e si sposta dall’uno all’altro.', 'Tutto l’anno in boschi di conifere e misti, molto attivo nelle prime ore del mattino.', 'Lascia pigne, noci e alberi in piedi da cui trae cibo e riparo.', 'Tieni i cani sui sentieri ed evita di scuotere alberi che possano ospitare un nido.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'it', 'Castoro europeo', 'Le dighe dei castori creano zone umide che favoriscono pesci, uccelli e insetti per chilometri.', 'Dalla primavera al tardo autunno lungo i fiumi lenti, più attivo all’imbrunire.', 'Sostieni il mantenimento di dighe e alberi ripariali dove non creano pericolo.', 'Tieniti lontano da tane e dighe, soprattutto quando i piccoli sono ancora minuti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'it', 'Lepre variabile', 'La lepre variabile in inverno diventa bianca per confondersi con la neve.', 'Tutto l’anno in terreni aperti e radure, soprattutto all’alba e al tramonto.', 'Sostieni il mosaico di aree aperte e riparo di cui la lepre ha bisogno tutto l’anno.', 'Tieni i cani al guinzaglio nei terreni aperti perché le lepri a riposo non vengano inseguite.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'it', 'Tasso europeo', 'Il tasso vive in gruppi familiari in tane sotterranee usate per generazioni.', 'Dalla primavera all’autunno dopo il buio vicino ai boschi; l’inverno lo passa dormendo.', 'Lascia indisturbate scarpate e siepi campestri dove il tasso possa scavare la tana.', 'Non ostruire mai una tana attiva né scavare accanto: è la sua casa di lungo periodo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'it', 'Pipistrello nano', 'Questo pipistrello minuscolo mangia fino a 3.000 moscerini e zanzare in una notte.', 'Nelle sere d’estate osserva all’imbrunire il volo rapido e a scatti sopra i giardini.', 'Fissa una bat box in alto su un muro o un albero che prenda il sole della sera.', 'Evita luci forti sugli ingressi dei rifugi e mantieni buio il cielo notturno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'it', 'Vanessa dell''ortica', 'Questa farfalla sverna da adulta, spesso in capanni e sottotetti.', 'Da inizio primavera all’autunno sui fiori al sole, soprattutto ortiche e buddleja.', 'Lascia una macchia di ortiche in un angolo soleggiato: ai suoi bruchi servono.', 'Non disturbare d’inverno le farfalle che svernano nei capanni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'it', 'Vanessa io', 'Gli ocelli si aprono di scatto per spaventare gli uccelli e le ali possono sibilare.', 'Dalla primavera all’autunno nelle giornate di sole, su cardi, buddleja e frutta caduta.', 'Lascia crescere al sole una macchia di ortiche per i suoi bruchi.', 'Non disturbare gli adulti che d’inverno si riparano in capanni e cataste di legna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'it', 'Cedronella', 'La parola inglese «butterfly» deriverebbe dal giallo burro del maschio di questa specie.', 'Una delle prime farfalle di primavera; cercala lungo i margini del bosco nelle giornate miti.', 'Sostieni le frangole e gli spincervini delle siepi, uniche piante di cui si nutrono i bruchi.', 'Evita di ripulire le siepi cespugliose che riparano gli adulti svernanti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'it', 'Aurora', 'Solo i maschi hanno le vivaci punte arancioni delle ali; le femmine sono bianche.', 'In primavera lungo prati umidi e viottoli dove cresce il billeri dei prati.', 'Lascia crescere billeri e alliaria negli angoli umidi non sfalciati.', 'Rimanda lo sfalcio dei bordi stradali finché i bruchi non hanno finito di nutrirsi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'it', 'Icaro', 'I bruchi di questa licena sono talvolta accuditi dalle formiche, attratte dalle loro secrezioni dolci.', 'Da fine primavera nei prati soleggiati ricchi di trifogli e ginestrino.', 'Lascia il prato non sfalciato perché ginestrino e trifogli possano fiorire.', 'Evita di trattare con diserbanti i prati ricchi di fiori spontanei.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'it', 'Pieride del navone', 'Nonostante somigli alla cavolaia, preferisce le piante spontanee agli ortaggi del giardino.', 'Dalla primavera a fine estate in prati umidi, fossi e viali forestali.', 'Lascia inselvatichire gli angoli umidi con crucifere spontanee come il billeri.', 'Evita di drenare e trattare i prati umidi dove si riproduce.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'it', 'Coccinella a sette punti', 'Una sola coccinella divora migliaia di afidi nell’arco della vita.', 'Dalla primavera all’autunno sulle piante con afidi; d’inverno si raggruppano per svernare.', 'Tollera qualche afide e rinuncia ai trattamenti, così le coccinelle hanno di che nutrirsi.', 'Lascia steli cavi e lettiera di foglie dove si riparano durante l’inverno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'it', 'Bombo terrestre', 'Le regine sono tra le prime api in volo a primavera, ronzando basse in cerca di cavità.', 'Da inizio primavera all’autunno sui fiori; in primavera le regine perlustrano il piede delle siepi.', 'Coltiva o conserva piante a fioritura precoce e lascia fiorire il trifoglio nel prato.', 'Lascia indisturbate scarpate e vecchie tane di topo dove si insediano le colonie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'it', 'Ape mellifera occidentale', 'Le bottinatrici indicano all’alveare dove sono i fiori danzando a forma di otto.', 'Dalla primavera all’autunno sui fiori, nelle giornate calde e senza vento.', 'Fai succedere fioriture diverse lungo le stagioni e metti una ciotola d’acqua bassa.', 'Non trattare le piante in fiore, e mai nelle ore centrali della giornata.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'it', 'Libellula imperatore', 'Una delle libellule più grandi d’Europa: cattura le prede persino a mezz’aria.', 'Nelle giornate calde d’estate osservala pattugliare stagni e rive dei laghi.', 'Conserva o scava uno stagno con piante e lascia le sponde inerbite.', 'Mantieni gli stagni liberi da inquinamento e dilavamenti, così le larve possono svilupparsi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'it', 'Cardinale striato', 'Questi cardinali si posano spesso sullo stesso punto caldo e scattano per ghermire gli insetti di passaggio.', 'Da metà estate all’autunno presso acque ferme, a scaldarsi su sentieri e paletti.', 'Lascia posatoi soleggiati e vegetazione intorno a stagni e fossi.', 'Evita che concimi o oli finiscano negli stagni dove vivono le larve.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'it', 'Formica rufa', 'I loro formicai a cupola superano il metro d’altezza e ospitano mezzo milione di formiche.', 'Dalla primavera all’autunno nei boschi di conifere; cerca le cupole di aghi.', 'Lascia intatti i formicai: costruirli richiede anni.', 'Resta sui sentieri e non prendere mai a calci né scavare un formicaio.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'it', 'Anemone dei boschi', 'L’anemone dei boschi si diffonde così lentamente che i tappeti fitti indicano bosco antico.', 'In primavera cerca i tappeti di fiori bianchi prima che gli alberi mettano le foglie.', 'Lascia indisturbato il suolo del bosco perché i rizomi lenti possano prosperare.', 'Ammirala dove cresce: coglierla toglie fiori che hanno impiegato anni a diffondersi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'it', 'Mughetto', 'Ogni parte di questa pianta dal profumo dolce è velenosa se ingerita.', 'A tarda primavera segui il profumo fino ai boschi ombrosi e ai giardini in ombra.', 'Lascia in posto i margini boschivi ombrosi e la lettiera di foglie dove cresce.', 'Non coglierla né estirparla, e tienila lontana da bambini e animali domestici.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'it', 'Aglio orsino', 'L’aglio orsino si sente con l’olfatto molto prima di vederne i fiori bianchi.', 'In primavera cerca le larghe foglie verdi e i fiori stellati nei boschi umidi.', 'Lascia indisturbati i boschi umidi perché i tappeti possano ricrescere ogni anno.', 'Se la raccolta è consentita localmente, prendine poco e non estirpare mai i bulbi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'it', 'Calta palustre', 'Tra le piante autoctone più antiche: sopravvisse in Scandinavia all’ultima era glaciale.', 'In primavera cerca i grandi fiori dorati in paludi, fossi e sponde degli stagni.', 'Mantieni umidi e non sfalciati i bordi di stagni e fossi perché possa fiorire.', 'Evita di drenare i terreni umidi e lascia le piante dove crescono.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'it', 'Primula odorosa', 'La primula odorosa era così comune nei prati da fieno che i bambini ne facevano palle di fiori.', 'In primavera cerca i fiori gialli penduli nei prati antichi e non concimati.', 'Lascia i prati non sfalciati finché la primula non ha fiorito e prodotto semi.', 'Non coglierla né estirparla in natura: i fiori dei prati sono in declino.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'it', 'Margherita comune', 'Il «fiore» della margherita è in realtà un insieme di decine di fiorellini.', 'In estate cerca le grandi margherite bianche lungo le strade e nei prati.', 'Lascia una fascia d’erba non sfalciata per tutta la piena estate perché possa fiorire.', 'Evita di trattare con diserbanti bordi stradali e prati.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'it', 'Tarassaco comune', 'Il tarassaco è una delle fonti di nettare precoce più importanti per le api.', 'Dalla primavera in poi quasi ovunque; i fiori si aprono al sole e si chiudono all’imbrunire.', 'Lascia fiorire il tarassaco sul prato in primavera prima del primo taglio.', 'Rinuncia ai diserbanti per il prato, così gli impollinatori precoci conservano questo cibo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'it', 'Brugo', 'Una sola pianta di brugo può produrre oltre centomila semi minutissimi.', 'A fine estate cerca i tappeti purpurei sulle brughiere aperte e nelle torbiere.', 'Sostieni il mantenimento delle brughiere aperte e non drenate.', 'Resta sui sentieri nelle brughiere e non accendere mai fuochi con tempo secco.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'it', 'Mirtillo nero', 'Il mirtillo nero tinge le dita di blu e nutre di tutto, dagli uccelli agli orsi.', 'In estate cerca gli arbusti bassi con bacche scure nelle pinete e nelle peccete.', 'Lascia intatto il sottobosco perché gli arbusti bassi possano fruttificare.', 'Se la raccolta è consentita localmente, lascia molte bacche alla fauna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'it', 'Mirtillo rosso', 'Il mirtillo rosso si conserva per mesi grazie a un conservante naturale contenuto nel frutto.', 'A fine estate e in autunno cerca le bacche rosse lucide su tappeti sempreverdi.', 'Lascia indisturbata la vegetazione del suolo forestale perché i tappeti si estendano.', 'Se la raccolta è consentita localmente, cammina con attenzione per non schiacciare le piante.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'it', 'Betulla bianca', 'Una betulla ospita centinaia di specie di insetti e nutre così innumerevoli uccelli.', 'Tutto l’anno; la corteccia bianca che si sfoglia la rende riconoscibile in ogni stagione.', 'Lascia a terra foglie cadute e legno morto: arricchiscono il suolo e nutrono gli insetti.', 'Evita di strappare la corteccia: ferisce e indebolisce l’albero.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'it', 'Abete rosso', 'In Svezia un abete rosso cresce su radici vecchie di migliaia di anni.', 'Tutto l’anno nelle foreste; le sue pigne pendule sono le più lunghe fra gli abeti.', 'Lascia a terra pigne cadute e legno morto, che riparano insetti e funghi.', 'Resta sui sentieri nel bosco per non compattare le radici superficiali dell’abete.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'it', 'Pino silvestre', 'I vecchi pini silvestri hanno la parte alta del tronco color arancio e possono vivere secoli.', 'Tutto l’anno su terreni sabbiosi e rocciosi; cerca la corteccia arancio in alto.', 'Lascia in piedi il legno morto e i pini vetusti, ricchissimi di vita.', 'Non accendere mai fuochi contro o vicino ai pini su terreno secco e sabbioso.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'it', 'Luccio', 'Il luccio è un predatore d’agguato capace di scattare dall’immobilità in un battito di ciglia.', 'Dalla primavera all’autunno nelle basse fondali erbose di laghi e fiumi lenti.', 'Sostieni la conservazione dei canneti bassi e delle piante acquatiche dove si riparano gli avannotti.', 'Tieni inquinamento e rifiuti fuori dall’acqua; rispetta le regole locali di pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'it', 'Persico reale', 'Il persico caccia in branco e porta strisce marcate che ne spezzano la sagoma.', 'Nei mesi più caldi attorno a pontili, praterie sommerse e salti di profondità.', 'Sostieni acque pulite e strutture sommerse che riparano i pesci piccoli.', 'Non gettare mai nulla in laghi e fiumi; rispetta le regole locali di pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'it', 'Rutilo', 'Il rutilo è un pesce preda chiave da cui dipendono molti predatori dei laghi.', 'Nei mesi più caldi in banchi vicino alla superficie di laghi e fiumi lenti.', 'Sostieni acque pulite e sponde vegetate per la riproduzione.', 'Tieni dilavamenti e rifiuti fuori dall’acqua; rispetta le regole locali di pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'pt', 'Andorinhão-preto', 'Os andorinhões conseguem passar meses no ar e chegam a dormir em pleno voo.', 'Nas noites amenas de verão, olhe bem alto sobre os telhados e escute os bandos estridentes.', 'Instale uma caixa-ninho sob o beiral antes de as aves regressarem na primavera.', 'Em obras de renovação, mantenha as frestas sob o beiral onde eles nidificam.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'pt', 'Andorinha-das-chaminés', 'As andorinhas-das-chaminés migram todos os anos até ao sul de África e regressam.', 'Da primavera ao início do outono, veem-se a rasar campos abertos e planos de água.', 'Deixe entreaberta a porta de um celeiro ou barracão para alcançarem os ninhos.', 'Não derrube os ninhos de barro antigos — as andorinhas reaproveitam-nos ano após ano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'pt', 'Cuco-canoro', 'O cuco põe os ovos em ninhos alheios e nunca cria as suas próprias crias.', 'No final da primavera, escute o "cu-co" que se ouve ao longe nas orlas de mata.', 'Apoie prados e sebes ricos em insetos, que alimentam as aves hospedeiras do cuco.', 'Mantenha-se nos trilhos junto a matagais e caniçais para não perturbar as hospedeiras.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'pt', 'Pisco-de-peito-ruivo', 'O pisco defende o território com ferocidade e canta pela noite dentro junto a candeeiros.', 'Todo o ano em jardins e bosques; segue quem cava, à espera de minhocas.', 'Deixe um canto do jardim com folhada onde possa procurar alimento.', 'Adie as podas fortes de sebes até a nidificação terminar, no fim do verão.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'pt', 'Melro-preto', 'O canto cheio e aflautado do macho é um dos mais reconhecíveis da Europa.', 'Todo o ano; ao amanhecer e ao anoitecer escute os machos a cantar de telhados e copas.', 'Ponha água fresca para beber e tomar banho, sobretudo em períodos secos.', 'Mantenha os gatos dentro de casa ao romper do dia durante a época de ninhos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'pt', 'Tordo-zornal', 'O tordo-zornal é sociável e anda em bandos de inverno ruidosos e tagarelas.', 'No outono e no inverno, observe os bandos a despir de bagas as sebes e as tramazeiras.', 'Deixe por podar durante o inverno os arbustos com bagas, como tramazeira e pilriteiro.', 'Deixe no chão as maçãs caídas no inverno — são alimento vital com frio.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'pt', 'Chapim-real', 'O chapim-real tem um vocabulário enorme e aprende chamamentos novos com os vizinhos.', 'Todo o ano; a partir do fim do inverno escute o canto sonoro de duas notas repetidas.', 'Pendure uma caixa-ninho com orifício de 32 mm num local sossegado e sombrio.', 'Evite pesticidas no jardim para que haja lagartas suficientes para as crias.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'pt', 'Chapim-azul', 'Uma única ninhada de chapins-azuis pode comer mais de mil lagartas.', 'Todo o ano em jardins e bosques, muitas vezes pendurado de cabeça para baixo em ramos finos.', 'Instale uma caixa pequena com orifício de 25 mm ao abrigo dos ventos dominantes.', 'Dispense os inseticidas na primavera para deixar as lagartas às crias.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'pt', 'Tentilhão-comum', 'O canto do tentilhão varia de região para região, quase como dialetos locais.', 'Da primavera ao outono; os machos cantam uma frase clara e descendente de poisos descobertos.', 'Deixe algumas plantas em semente e cantos com ervas de pé durante a estação.', 'Mantenha os comedouros limpos para evitar a propagação de doenças entre os tentilhões.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'pt', 'Gaio-comum', 'O gaio enterra milhares de bolotas todos os outonos e, ao esquecer algumas, planta carvalhais inteiros.', 'Todo o ano em carvalhais; no outono procure os relâmpagos de rosa e azul.', 'Deixe intactas as bolotas caídas e a folhada sob os carvalhos.', 'Mantenha os cães nos trilhos da mata para não levantar as aves que comem no solo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'pt', 'Pica-pau-malhado-grande', 'O "tamborilar" da primavera não é alimentação: é um rufo rápido para marcar território.', 'Todo o ano; no fim do inverno escute o tamborilar a ecoar pela mata.', 'Deixe de pé a madeira morta, que guarda os insetos de que se alimenta.', 'Não abata árvores mortas ou em declínio que possam ter cavidades de ninho.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'pt', 'Alvéola-branca', 'O balancear constante da cauda talvez sinalize atenção aos predadores.', 'Da primavera ao outono junto à água e a solos nus, correndo e parando para apanhar insetos.', 'Mantenha junto à água uma faixa de erva rasa ou gravilha onde possa procurar alimento.', 'Evite pisar os cascalheiros e as margens onde se alimenta e nidifica.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'pt', 'Grou-comum', 'Os grous executam no início da primavera danças nupciais feitas de saltos e vénias.', 'Da primavera ao outono junto a zonas húmidas; o chamamento aclarinado ouve-se a quilómetros.', 'Apoie a proteção de turfeiras não drenadas e prados húmidos onde os grous nidificam.', 'Observe as zonas de nidificação à distância — os grous abandonam ninhos perturbados.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'pt', 'Cisne-bravo', 'O cisne-bravo acasala para a vida e anuncia a chegada com chamamentos altos e trompeteados.', 'Na primavera e no outono em lagos e campos alagados, muitas vezes em grupos familiares.', 'Apoie a manutenção de margens pouco fundas e campos húmidos livres de drenagem.', 'Nunca dê pão aos cisnes — faz-lhes mal; mantenha a distância sobre o gelo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'pt', 'Pato-real', 'Os patinhos nadam e alimentam-se sozinhos poucas horas depois de nascerem.', 'Todo o ano em quase qualquer charco, lago ou rio de corrente lenta.', 'Se alimentar os patos, use aveia, ervilhas ou sementes em vez de pão.', 'Mantenha os cães fora de água na primavera, onde os patos nidificam.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'pt', 'Bútio-comum', 'O bútio plana em asas largas e chama muitas vezes com um miado prolongado, "piii-uu".', 'Da primavera ao outono; procure-o a planar alto sobre campos e orlas de mata.', 'Apoie prados rústicos e bordaduras de campos que albergam ratos-do-campo e presas pequenas.', 'Nunca use venenos para roedores: sobem a cadeia alimentar até às aves de rapina.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'pt', 'Águia-pesqueira', 'A águia-pesqueira mergulha de patas à frente e transporta presas com metade do seu peso.', 'Da primavera ao outono junto a grandes lagos; repare no voo pairado seguido de um mergulho.', 'Apoie plataformas artificiais de nidificação em postes altos junto a lagos com peixe.', 'Passe bem ao largo das plataformas para os casais não abandonarem os ovos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'pt', 'Raposa-vermelha', 'A raposa usa o campo magnético da Terra para calibrar o salto sobre presas escondidas.', 'Todo o ano, mais ativa ao amanhecer e ao anoitecer ao longo de orlas de mata e campos.', 'Deixe um canto selvagem e sossegado onde as raposas possam descansar e abrir toca.', 'Feche bem os caixotes e nunca deixe restos de comida nocivos ao alcance das raposas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'pt', 'Ouriço-cacheiro', 'Um ouriço-cacheiro percorre alguns quilómetros numa só noite à procura de comida.', 'Da primavera ao outono depois de escurecer; no inverno hiberna sob montes de folhas e lenha.', 'Abra uma passagem de 13 cm nas vedações para circularem entre jardins.', 'Verifique a erva alta antes de roçar e deixe montes de folhas para a hibernação.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'pt', 'Corço', 'O corço adia a gestação para que as crias nasçam sempre no início do verão.', 'Todo o ano nas orlas de mata, mais visível a pastar ao amanhecer e ao anoitecer.', 'Apoie bordaduras de campos por ceifar e matagais que dão abrigo e alimento.', 'Traga os cães à trela junto à mata no início do verão, quando as crias ficam escondidas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'pt', 'Alce', 'O alce é o maior cervídeo do planeta; um macho grande passa a meia tonelada.', 'Todo o ano em florestas e zonas húmidas, mais ativo ao amanhecer e ao anoitecer.', 'Apoie florestas contínuas e corredores húmidos de que o alce precisa para se deslocar.', 'Conduza com cuidado ao amanhecer e ao anoitecer nas estradas florestais e nunca se aproxime de uma cria.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'pt', 'Esquilo-vermelho', 'O esquilo-vermelho constrói vários ninhos e vai mudando de um para o outro.', 'Todo o ano em bosques de resinosas e mistos, mais azafamado ao início da manhã.', 'Deixe pinhas, frutos secos e árvores de pé onde se alimenta e faz o ninho.', 'Mantenha os cães nos trilhos e evite sacudir árvores que possam ter um ninho.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'pt', 'Castor-europeu', 'As represas dos castores criam zonas húmidas que favorecem peixes, aves e insetos por quilómetros.', 'Da primavera ao fim do outono em rios lentos, mais ativo ao anoitecer.', 'Apoie a permanência das represas e das árvores ribeirinhas onde não haja risco.', 'Afaste-se das tocas e das represas, sobretudo quando as crias são pequenas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'pt', 'Lebre-variável', 'A lebre-variável fica branca no inverno para se camuflar na neve.', 'Todo o ano em terreno aberto e clareiras, sobretudo ao amanhecer e ao anoitecer.', 'Apoie o mosaico de terreno aberto e abrigo de que a lebre precisa ao longo do ano.', 'Traga os cães à trela em terreno aberto para não perseguirem lebres em descanso.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'pt', 'Texugo-europeu', 'O texugo vive em grupos familiares em tocas subterrâneas usadas ao longo de gerações.', 'Da primavera ao outono depois de escurecer junto à mata; passa o inverno a dormir.', 'Deixe intactos taludes e sebes onde o texugo possa escavar a toca.', 'Nunca tape uma toca ativa nem escave ao lado — é a sua casa de longa data.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'pt', 'Morcego-anão', 'Este morcego minúsculo come até 3000 mosquitinhos e mosquitos numa só noite.', 'Nas noites de verão, repare ao anoitecer no voo rápido e aos ziguezagues sobre os jardins.', 'Fixe um abrigo para morcegos bem alto numa parede ou árvore que apanhe o sol da tarde.', 'Evite luzes fortes nas entradas dos abrigos e mantenha escuro o céu noturno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'pt', 'Borboleta-da-urtiga', 'Esta borboleta passa o inverno já adulta, muitas vezes em barracões e sótãos.', 'Do início da primavera ao outono em flores ao sol, sobretudo urtigas e budleias.', 'Deixe uma mancha de urtigas num canto soalheiro — as lagartas precisam delas.', 'Não perturbe no inverno as borboletas que hibernam em barracões.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'pt', 'Borboleta-pavão', 'Os ocelos abrem-se de repente para assustar as aves, e as asas conseguem sibilar.', 'Da primavera ao outono em dias de sol, em cardos, budleias e fruta caída.', 'Deixe crescer ao sol uma mancha de urtigas para as lagartas.', 'Não perturbe os adultos abrigados em barracões e pilhas de lenha durante o inverno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'pt', 'Limoeiro', 'A palavra inglesa "butterfly" talvez venha do amarelo-manteiga do macho desta espécie.', 'Uma das primeiras borboletas da primavera; procure-a nas orlas de mata em dias amenos.', 'Apoie os sanguinhos e espinheiros das sebes, as únicas plantas de que as lagartas comem.', 'Evite limpar as sebes com mato, que abrigam os adultos a passar o inverno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'pt', 'Ponta-laranja', 'Só os machos têm as pontas das asas cor de laranja vivas; as fêmeas são brancas.', 'Na primavera, ao longo de prados húmidos e caminhos onde cresce o agrião-do-prado.', 'Deixe crescer agrião-do-prado e alliária em cantos húmidos por ceifar.', 'Adie o corte das bermas até as lagartas terminarem a alimentação.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'pt', 'Azul-comum', 'As lagartas desta borboleta são por vezes cuidadas por formigas, atraídas pelas suas secreções doces.', 'A partir do fim da primavera em prados soalheiros ricos em trevos e cornichão.', 'Deixe o prado por ceifar para que cornichões e trevos possam florir.', 'Evite pulverizar com herbicida os prados ricos em flores silvestres.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'pt', 'Branca-de-nervuras-verdes', 'Apesar de parecer a borboleta-da-couve, prefere plantas silvestres às culturas de horta.', 'Da primavera ao fim do verão em prados húmidos, valas e carreiros florestais.', 'Deixe os cantos húmidos ganhar vida silvestre com crucíferas nativas como o agrião-do-prado.', 'Evite drenar e pulverizar os prados húmidos onde se reproduz.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'pt', 'Joaninha-de-sete-pintas', 'Uma única joaninha devora milhares de afídeos ao longo da vida.', 'Da primavera ao outono em plantas com afídeos; no inverno juntam-se em grupos para hibernar.', 'Tolere alguns afídeos e dispense as pulverizações para as joaninhas terem que comer.', 'Deixe caules ocos e folhada onde se abrigam durante o inverno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'pt', 'Abelhão-de-cauda-clara', 'As rainhas estão entre as primeiras abelhas da primavera, zumbindo rente ao chão à procura de buracos.', 'Do início da primavera ao outono nas flores; na primavera as rainhas vasculham a base das sebes.', 'Plante ou mantenha espécies de floração precoce e deixe o trevo florir no relvado.', 'Deixe intactos taludes e antigas tocas de rato onde as colónias se instalam.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'pt', 'Abelha-europeia', 'As campeiras indicam à colmeia onde estão as flores dançando em forma de oito.', 'Da primavera ao outono nas flores, em dias quentes e sem vento.', 'Faça suceder floradas variadas ao longo das estações e ponha uma taça de água pouco funda.', 'Não pulverize plantas em flor, e nunca a meio do dia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'pt', 'Libélula-imperador', 'Uma das maiores libélulas da Europa: captura presas mesmo em pleno voo.', 'Nos dias quentes de verão, veja-a a patrulhar charcos e margens de lagos.', 'Mantenha ou abra um charco com plantas e deixe as margens com vegetação.', 'Mantenha os charcos livres de poluição e escorrências para as larvas se desenvolverem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'pt', 'Libélula-comum-de-outono', 'Estas libélulas poisam muitas vezes no mesmo sítio quente e arrancam para apanhar insetos de passagem.', 'Do pino do verão ao outono junto a águas paradas, a apanhar sol em trilhos e estacas.', 'Deixe poisos soalheiros e vegetação à volta de charcos e valas.', 'Evite que adubos ou óleos escorram para os charcos onde as larvas vivem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'pt', 'Formiga-ruiva-do-bosque', 'Os seus formigueiros em cúpula passam do metro de altura e albergam meio milhão de formigas.', 'Da primavera ao outono em bosques de resinosas; procure as cúpulas de agulhas.', 'Deixe os formigueiros intactos — levam anos a construir.', 'Mantenha-se nos trilhos e nunca pontapeie nem escave um formigueiro.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'pt', 'Anémona-dos-bosques', 'A anémona-dos-bosques alastra tão devagar que tapetes densos denunciam mata antiga.', 'Na primavera, procure os tapetes de flores brancas antes de as árvores abrirem folha.', 'Deixe o solo da mata sem revolver para que os rizomas lentos possam prosperar.', 'Aprecie-a onde cresce — colhê-la retira flores que levaram anos a alastrar.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'pt', 'Lírio-do-vale', 'Todas as partes desta planta de perfume doce são venenosas se ingeridas.', 'No fim da primavera, siga o perfume até bosques sombrios e jardins à sombra.', 'Deixe no lugar as orlas sombrias de mata e a folhada onde cresce.', 'Não a colha nem a arranque, e mantenha-a longe de crianças e animais de estimação.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'pt', 'Alho-dos-ursos', 'O alho-dos-ursos costuma cheirar-se muito antes de se verem as flores brancas.', 'Na primavera, procure as folhas largas e verdes e as flores em estrela em matas húmidas.', 'Deixe as matas húmidas em sossego para os tapetes voltarem a crescer todos os anos.', 'Se a colheita for permitida localmente, leve pouco e nunca arranque os bolbos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'pt', 'Malmequer-dos-pântanos', 'Uma das plantas nativas mais antigas: sobreviveu na Escandinávia à última era glaciar.', 'Na primavera, procure as grandes flores douradas em pântanos, valas e margens de charco.', 'Mantenha húmidas e por ceifar as margens de charcos e valas para que possa florir.', 'Evite drenar solos encharcados e deixe as plantas onde crescem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'pt', 'Primavera-comum', 'A primavera-comum era tão frequente nos lameiros de feno que as crianças faziam bolas com ela.', 'Na primavera, procure as flores amarelas pendentes em prados antigos e não adubados.', 'Deixe os prados por ceifar até a planta ter florido e produzido semente.', 'Não a colha nem a arranque no campo — as flores de prado estão em declínio.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'pt', 'Margarida-do-campo', 'A "flor" da margarida-do-campo é na verdade um conjunto de dezenas de flores minúsculas.', 'No verão, procure as grandes margaridas brancas ao longo das estradas e nos prados.', 'Deixe uma faixa de erva por ceifar durante o pino do verão para que possa florir.', 'Evite pulverizar bermas e prados com herbicida.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'pt', 'Dente-de-leão', 'O dente-de-leão é uma das fontes de néctar precoce mais importantes para as abelhas.', 'A partir da primavera quase em toda a parte; as flores abrem ao sol e fecham ao anoitecer.', 'Deixe o dente-de-leão florir no relvado na primavera antes do primeiro corte.', 'Dispense os herbicidas de relvado para os polinizadores precoces manterem este alimento.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'pt', 'Urze-comum', 'Uma única planta de urze pode produzir mais de cem mil sementes minúsculas.', 'No fim do verão, procure os tapetes roxos em charnecas abertas e turfeiras.', 'Apoie a manutenção das charnecas abertas e livres de drenagem.', 'Mantenha-se nos trilhos das charnecas e nunca acenda fogo com tempo seco.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'pt', 'Mirtilo', 'O mirtilo tinge os dedos de azul e alimenta tudo, das aves aos ursos.', 'No verão, procure os arbustos baixos com bagas escuras em pinhais e abetais.', 'Deixe o sub-bosque intacto para que os arbustos baixos possam frutificar.', 'Se a apanha for permitida localmente, deixe muitas bagas para a fauna.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'pt', 'Airela-vermelha', 'A airela-vermelha conserva-se meses graças a um conservante natural do próprio fruto.', 'No fim do verão e no outono, procure as bagas vermelhas luzidias em tapetes sempre-verdes.', 'Deixe a vegetação do solo florestal em sossego para os tapetes se alargarem.', 'Se a apanha for permitida localmente, pise com cuidado para não esmagar as plantas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'pt', 'Bétula-branca', 'Uma bétula sustenta centenas de espécies de insetos e alimenta assim inúmeras aves.', 'Todo o ano; a casca branca que se descama torna-a fácil de reconhecer em qualquer estação.', 'Deixe no chão as folhas caídas e a madeira morta: enriquecem o solo e alimentam os insetos.', 'Evite arrancar a casca, o que fere e enfraquece a árvore.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'pt', 'Abeto-vermelho', 'Na Suécia, um abeto-vermelho cresce a partir de raízes com milhares de anos.', 'Todo o ano nas florestas; as suas pinhas pendentes são as mais compridas de todos os abetos.', 'Deixe no chão pinhas caídas e madeira morta, que abrigam insetos e fungos.', 'Mantenha-se nos trilhos da floresta para não compactar as raízes superficiais do abeto.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'pt', 'Pinheiro-silvestre', 'Os pinheiros-silvestres velhos brilham cor de laranja junto ao topo e podem viver séculos.', 'Todo o ano em solos arenosos e rochosos; repare na casca alaranjada da parte alta.', 'Deixe de pé a madeira morta e os pinheiros velhos, riquíssimos em vida selvagem.', 'Nunca acenda fogo encostado ou perto de pinheiros em solo seco e arenoso.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'pt', 'Lúcio', 'O lúcio é um predador de emboscada capaz de arrancar da imobilidade num piscar de olhos.', 'Da primavera ao outono nos baixios com vegetação de lagos e rios lentos.', 'Apoie a manutenção de baixios com caniço e plantas aquáticas onde os alevins se abrigam.', 'Mantenha poluição e lixo fora de água; siga as regras locais de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'pt', 'Perca-europeia', 'A perca caça em grupo e usa riscas fortes que quebram o seu contorno.', 'Nos meses mais quentes junto a pontões, camas de plantas e quebras de fundo.', 'Apoie água limpa e estruturas submersas que dão abrigo aos peixes pequenos.', 'Nunca despeje nada em lagos e rios; siga as regras locais de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'pt', 'Rutilo', 'O rutilo é um peixe-presa fundamental de que dependem muitos predadores dos lagos.', 'Nos meses mais quentes em cardumes junto à superfície de lagos e rios lentos.', 'Apoie água limpa e margens com vegetação para a desova.', 'Mantenha escorrências e lixo fora de água; siga as regras locais de pesca.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ro', 'Drepnea neagră', 'Drepnelele pot rămâne în aer luni la rând și chiar dorm în zbor.', 'În serile calde de vară, priviți sus, deasupra acoperișurilor, și ascultați stolurile zgomotoase.', 'Montați o cuibarniță sub streașină înainte ca păsările să se întoarcă primăvara.', 'La renovări, păstrați crăpăturile mici de sub streașină, unde își fac cuibul.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ro', 'Rândunica', 'Rândunicile migrează în fiecare an tocmai până în sudul Africii și înapoi.', 'Din primăvară până la începutul toamnei le vedeți zburând razant peste câmpuri și ape.', 'Lăsați întredeschisă ușa unui hambar sau a unei magazii, ca să ajungă la cuiburi.', 'Nu dărâmați cuiburile vechi de lut — rândunicile le refolosesc an de an.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ro', 'Cucul', 'Cucul își depune ouăle în cuiburile altor păsări și nu își crește niciodată puii.', 'La sfârșitul primăverii, ascultați „cu-cu”-ul care se aude departe, de la marginea pădurii.', 'Sprijiniți fânețele și gardurile vii bogate în insecte, care hrănesc păsările-gazdă ale cucului.', 'Rămâneți pe poteci lângă tufărișuri și stufărișuri, ca gazdele să nu fie deranjate.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ro', 'Măcăleandru', 'Măcăleandrul își apără teritoriul cu îndârjire și cântă și noaptea lângă felinare.', 'Tot anul, în grădini și păduri; urmărește adesea pe cine sapă, în speranța unor râme.', 'Lăsați un colț de grădină acoperit cu frunze uscate, unde poate căuta hrană.', 'Amânați tunsul puternic al gardurilor vii până la finalul cuibăritului, spre sfârșitul verii.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ro', 'Mierla neagră', 'Cântecul bogat, ca de flaut, al masculului este printre cele mai ușor de recunoscut din Europa.', 'Tot anul; în zori și în amurg ascultați masculii cântând de pe acoperișuri și din vârful copacilor.', 'Puneți apă proaspătă de băut și de scăldat, mai ales în perioadele secetoase.', 'Țineți pisicile în casă în zori, în perioada cuibăritului.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ro', 'Cocoșar', 'Cocoșarul este o sturzoaică sociabilă, care hoinărește iarna în stoluri gălăgioase.', 'Toamna și iarna, priviți stolurile cum curăță de fructe gardurile vii și scorușii.', 'Lăsați netunse peste iarnă tufele cu fructe, precum scorușul și păducelul.', 'Lăsați merele căzute pe pământ iarna — sunt hrană vitală pe frig.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ro', 'Pițigoi mare', 'Pițigoiul mare are un vocabular uriaș și învață strigăte noi de la vecini.', 'Tot anul; de la sfârșitul iernii ascultați cântecul sonor, din două note repetate.', 'Agățați o cuibarniță cu orificiu de 32 mm într-un loc liniștit și umbrit.', 'Evitați pesticidele în grădină, ca omizile să ajungă pentru hrănirea puilor.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ro', 'Pițigoi albastru', 'O singură pontă de pițigoi albastru poate consuma peste o mie de omizi.', 'Tot anul, în grădini și păduri, adesea atârnând cu capul în jos de crenguțe subțiri.', 'Montați o cuibarniță mică, cu orificiu de 25 mm, ferită de vânturile dominante.', 'Renunțați la insecticide primăvara, ca omizile să rămână puilor.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ro', 'Cinteză', 'Cântecul cintezei diferă de la o regiune la alta, aproape ca niște graiuri locale.', 'Din primăvară până toamna; masculii cântă o strofă limpede, coborâtoare, de pe crengi descoperite.', 'Lăsați în picioare, pe durata sezonului, câteva plante cu semințe și petice de buruieni.', 'Păstrați hrănitoarele curate, ca bolile să nu se răspândească între cinteze.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ro', 'Gaiță', 'Gaița îngroapă mii de ghinde în fiecare toamnă și, uitând o parte, plantează stejărișuri întregi.', 'Tot anul, în stejărișuri; toamna căutați sclipirile de roz și albastru.', 'Lăsați neatinse ghindele căzute și stratul de frunze de sub stejari.', 'Țineți câinii pe poteci în pădure, ca păsările care se hrănesc pe sol să nu fie speriate.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ro', 'Ciocănitoare pestriță mare', '„Toba” de primăvară nu înseamnă hrănire, ci o bătaie rapidă prin care își revendică teritoriul.', 'Tot anul; la sfârșitul iernii ascultați toba răsunând prin pădure.', 'Lăsați în picioare lemnul mort, care adăpostește insectele cu care se hrănește.', 'Nu tăiați arborii morți sau uscați, care pot avea scorburi de cuib.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ro', 'Codobatură albă', 'Legănatul neîncetat al cozii semnalează probabil vigilența față de prădători.', 'Din primăvară până toamna, lângă apă și pe teren descoperit, alergând și oprindu-se după insecte.', 'Păstrați lângă apă o fâșie de iarbă scurtă sau de pietriș unde poate căuta hrană.', 'Evitați să deranjați prundișurile și malurile unde se hrănește și cuibărește.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ro', 'Cocor', 'Cocorii execută la începutul primăverii dansuri nupțiale, cu sărituri și plecăciuni.', 'Din primăvară până toamna, în zonele umede; trâmbițatul lor se aude la kilometri distanță.', 'Sprijiniți protejarea turbăriilor nedrenate și a fânețelor umede unde cuibăresc cocorii.', 'Priviți zonele de cuibărit de la distanță — cocorii părăsesc cuiburile deranjate.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ro', 'Lebădă de iarnă', 'Lebăda de iarnă se împerechează pe viață și își anunță sosirea cu strigăte puternice, de trâmbiță.', 'Primăvara și toamna, pe lacuri și câmpuri inundate, adesea în grupuri de familie.', 'Sprijiniți păstrarea malurilor puțin adânci și a câmpurilor umede, ferite de drenaj.', 'Nu dați niciodată pâine lebedelor — le face rău; păstrați distanța pe gheață.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ro', 'Rață mare', 'Bobocii înoată și se hrănesc singuri la câteva ore după ce ies din ou.', 'Tot anul, pe aproape orice iaz, lac sau râu cu curgere lentă.', 'Dacă hrăniți rațele, folosiți ovăz, mazăre sau semințe în locul pâinii.', 'Țineți câinii departe de apă primăvara, acolo unde rațele cuibăresc.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ro', 'Șorecar comun', 'Șorecarul plutește pe aripi late și strigă adesea cu un miorlăit prelung, „piii-iau”.', 'Din primăvară până toamna; căutați-l rotindu-se sus, peste câmpuri și margini de pădure.', 'Sprijiniți pajiștile nelucrate și marginile de câmp care adăpostesc șoareci de câmp și pradă măruntă.', 'Nu folosiți niciodată otrăvuri pentru rozătoare: urcă pe lanțul trofic până la păsările de pradă.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ro', 'Uligan pescar', 'Uliganul pescar se aruncă cu ghearele înainte și poate căra pradă cât jumătate din greutatea lui.', 'Din primăvară până toamna, lângă lacuri mari; urmăriți zborul pe loc, urmat de un picaj spectaculos.', 'Sprijiniți platformele artificiale de cuibărit, pe stâlpi înalți, lângă lacurile bogate în pește.', 'Ocoliți larg platformele de cuibărit, ca perechile să nu fie alungate de pe ouă.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ro', 'Vulpe roșcată', 'Vulpea se ajută de câmpul magnetic al Pământului ca să-și calculeze saltul asupra prăzii ascunse.', 'Tot anul, cea mai activă în zori și în amurg, pe marginea pădurilor și a câmpurilor.', 'Lăsați un colț sălbatic și liniștit unde vulpile să se odihnească și să-și sape vizuina.', 'Închideți bine pubelele și nu lăsați niciodată resturi de mâncare dăunătoare la îndemâna lor.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ro', 'Arici european', 'Un arici poate parcurge câțiva kilometri într-o singură noapte de căutat hrană.', 'Din primăvară până toamna, după lăsarea întunericului; iarna hibernează sub grămezi de frunze și lemne.', 'Faceți o deschidere de 13 cm în garduri, ca aricii să poată trece dintr-o grădină în alta.', 'Verificați iarba înaltă înainte de a tăia și lăsați grămezile de frunze pentru hibernare.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ro', 'Căprior', 'Căpriorii își amână gestația, ca puii să se nască întotdeauna la începutul verii.', 'Tot anul, la marginea pădurii, cel mai vizibili pășunând în zori și în amurg.', 'Sprijiniți marginile de câmp necosite și tufărișurile care le oferă adăpost și hrană.', 'Țineți câinii în lesă lângă pădure la începutul verii, când puii stau ascunși în iarbă.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ro', 'Elan', 'Elanul este cel mai mare cervideu de pe Pământ; un mascul mare trece de jumătate de tonă.', 'Tot anul, în păduri și zone umede, cel mai activ în zori și în amurg.', 'Sprijiniți pădurile continue și coridoarele umede de care elanul are nevoie ca să se deplaseze.', 'Conduceți cu grijă în zori și în amurg pe drumurile forestiere și nu vă apropiați niciodată de un pui.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ro', 'Veveriță roșcată', 'Veverița roșcată își face mai multe cuiburi și se mută de la unul la altul.', 'Tot anul, în păduri de conifere și mixte, cea mai activă dimineața devreme.', 'Lăsați conurile, nucile și arborii în picioare din care își ia hrana și adăpostul.', 'Țineți câinii pe poteci și evitați să scuturați copacii care ar putea adăposti un cuib.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ro', 'Castor european', 'Barajele castorilor creează zone umede care ajută peștii, păsările și insectele pe kilometri întregi.', 'Din primăvară până toamna târziu, pe râuri lente, cel mai activ în amurg.', 'Sprijiniți păstrarea barajelor și a arborilor de pe mal acolo unde nu există pericol.', 'Păstrați distanța față de vizuini și baraje, mai ales când puii sunt mici.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ro', 'Iepure de munte', 'Iepurele de munte se albește iarna, ca să se camufleze în zăpadă.', 'Tot anul, pe teren deschis și în poieni, mai ales în zori și în amurg.', 'Sprijiniți mozaicul de teren deschis și adăpost de care iepurii au nevoie tot anul.', 'Țineți câinii în lesă pe teren deschis, ca iepurii aflați la odihnă să nu fie fugăriți.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ro', 'Bursuc', 'Bursucii trăiesc în grupuri de familie, în vizuini subterane folosite generații la rând.', 'Din primăvară până toamna, după lăsarea întunericului, lângă pădure; iarna și-o petrec dormind.', 'Lăsați neatinse taluzurile și gardurile vii unde bursucii pot săpa vizuini.', 'Nu blocați și nu săpați niciodată lângă o vizuină locuită — este casa lor de o viață.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ro', 'Liliac pitic', 'Acest liliac minuscul mănâncă până la 3.000 de musculițe și țânțari într-o singură noapte.', 'În serile de vară, urmăriți în amurg zborul rapid și sacadat deasupra grădinilor.', 'Montați un adăpost pentru lilieci sus, pe un perete sau un copac care prinde soarele de seară.', 'Evitați luminile puternice la intrările în adăposturi și păstrați întunecat cerul nopții.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ro', 'Fluturele urzicii', 'Acest fluture iernează ca adult, adesea în magazii și poduri.', 'De la începutul primăverii până toamna, pe flori însorite, mai ales urzici și liliac-de-vară.', 'Lăsați un petic de urzici într-un colț însorit — omizile lui au nevoie de ele.', 'Nu deranjați iarna fluturii care hibernează în magazii.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ro', 'Ochi de păun', 'Petele-ochi se deschid brusc, ca să sperie păsările, iar aripile pot șuiera.', 'Din primăvară până toamna, în zilele însorite, pe ciulini, liliac-de-vară și fructe căzute.', 'Lăsați să crească un petic însorit de urzici pentru omizile lui.', 'Nu deranjați iarna adulții adăpostiți în magazii și stive de lemne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ro', 'Fluturele lămâiță', 'Cuvântul englezesc „butterfly” ar veni de la galbenul ca untul al masculului acestei specii.', 'Unul dintre primii fluturi ai primăverii; căutați-l la marginea pădurii în zilele blânde.', 'Sprijiniți crușinul și verigariul din gardurile vii, singurele plante cu care se hrănesc omizile.', 'Evitați curățarea gardurilor vii cu tufăriș, care adăpostesc adulții peste iarnă.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ro', 'Fluturele cu vârf portocaliu', 'Doar masculii au vârfurile aripilor portocalii aprinse; femelele sunt albe.', 'Primăvara, de-a lungul fânețelor umede și al drumurilor unde crește floarea-cucului.', 'Lăsați floarea-cucului și usturoița să crească în colțuri umede, necosite.', 'Amânați cositul marginilor de drum până când omizile termină de crescut.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ro', 'Albăstrelul comun', 'Omizile acestui fluture sunt uneori îngrijite de furnici, atrase de secrețiile lor dulci.', 'De la sfârșitul primăverii, pe pajiști însorite, bogate în trifoi și ghizdei.', 'Lăsați pajiștea necosită, ca ghizdeiul și trifoiul să poată înflori.', 'Evitați erbicidarea pajiștilor bogate în flori sălbatice.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ro', 'Albilița cu nervuri verzi', 'Deși seamănă cu albilița verzei, preferă plantele sălbatice culturilor din grădină.', 'Din primăvară până la sfârșitul verii, pe fânețe umede, șanțuri și drumuri forestiere.', 'Lăsați colțurile umede să se sălbăticească, cu crucifere native precum floarea-cucului.', 'Evitați drenarea și stropirea fânețelor umede unde se înmulțește.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ro', 'Buburuză cu șapte puncte', 'O singură buburuză mănâncă mii de afide de-a lungul vieții.', 'Din primăvară până toamna, pe plantele cu afide; iarna se adună în grupuri ca să hiberneze.', 'Tolerați câteva afide și renunțați la stropiri, ca buburuzele să aibă ce mânca.', 'Lăsați tulpinile goale pe dinăuntru și frunzele uscate unde se adăpostesc peste iarnă.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ro', 'Bondar de pământ', 'Reginele sunt printre primele albine ieșite primăvara, bâzâind aproape de sol după scorburi.', 'De la începutul primăverii până toamna, pe flori; primăvara reginele cercetează baza gardurilor vii.', 'Plantați sau păstrați specii cu înflorire timpurie și lăsați trifoiul să înflorească în gazon.', 'Lăsați neatinse taluzurile și vechile galerii de șoareci unde se instalează coloniile.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ro', 'Albina meliferă', 'Culegătoarele arată stupului unde sunt florile dansând în forma cifrei opt.', 'Din primăvară până toamna, pe flori, în zilele calde și fără vânt.', 'Faceți să se succeadă înfloriri variate de-a lungul anotimpurilor și puneți un vas puțin adânc cu apă.', 'Nu stropiți plantele înflorite și niciodată la mijlocul zilei.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ro', 'Libelula-împărat', 'Una dintre cele mai mari libelule din Europa: își prinde prada chiar și în zbor.', 'În zilele calde de vară, priviți-o patrulând iazurile și malurile lacurilor.', 'Păstrați sau săpați un iaz cu plante și lăsați malurile acoperite de vegetație.', 'Feriți iazurile de poluare și de scurgeri, ca larvele să se poată dezvolta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ro', 'Libelula comună de toamnă', 'Aceste libelule se așază adesea în același loc cald și țâșnesc după insectele care trec.', 'De la miezul verii până toamna, lângă ape stătătoare, la soare, pe poteci și stâlpi.', 'Lăsați locuri însorite de odihnă și vegetație în jurul iazurilor și al șanțurilor.', 'Evitați ca îngrășămintele sau uleiurile să ajungă în iazurile unde trăiesc larvele.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ro', 'Furnica roșie de pădure', 'Mușuroaiele lor în formă de cupolă trec de un metru înălțime și adăpostesc jumătate de milion de furnici.', 'Din primăvară până toamna, în păduri de conifere; căutați cupolele de ace de brad.', 'Lăsați mușuroaiele neatinse — construirea lor durează ani.', 'Rămâneți pe poteci și nu loviți și nu săpați niciodată într-un mușuroi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ro', 'Floarea-paștelui', 'Floarea-paștelui se răspândește atât de încet, încât covoarele dese trădează o pădure veche.', 'Primăvara, căutați covoarele de flori albe înainte ca arborii să înfrunzească.', 'Lăsați solul pădurii neatins, ca rizomii ei lenți să poată prospera.', 'Bucurați-vă de ea acolo unde crește — culesul ia flori care s-au răspândit ani întregi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ro', 'Lăcrămioară', 'Toate părțile acestei plante cu parfum dulce sunt otrăvitoare dacă sunt înghițite.', 'La sfârșitul primăverii, luați-vă după parfum spre pădurile umbroase și grădinile la umbră.', 'Lăsați la locul lor marginile umbroase de pădure și stratul de frunze unde crește.', 'Nu o culegeți și nu o dezgropați, iar copiii și animalele de companie să nu ajungă la ea.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ro', 'Leurdă', 'Leurda se simte de obicei după miros cu mult înainte de a-i vedea florile albe.', 'Primăvara, căutați frunzele late și verzi și florile în formă de stea în pădurile umede.', 'Lăsați pădurile umede nederanjate, ca covoarele să crească la loc în fiecare an.', 'Dacă recoltarea e permisă local, luați puțin și nu scoateți niciodată bulbii.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ro', 'Calcea-calului', 'Una dintre cele mai vechi plante native: a supraviețuit ultimei glaciațiuni în Scandinavia.', 'Primăvara, căutați florile mari, aurii, în mlaștini, șanțuri și pe marginea iazurilor.', 'Păstrați umede și necosite marginile iazurilor și ale șanțurilor, ca să poată înflori.', 'Evitați drenarea terenurilor umede și lăsați plantele acolo unde cresc.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ro', 'Ciuboțica-cucului', 'Ciuboțica-cucului era cândva atât de răspândită în fânețe, încât copiii făceau ghemotoace din ea.', 'Primăvara, căutați florile galbene aplecate în fânețele vechi, neîngrășate.', 'Lăsați fânețele necosite până când ciuboțica-cucului a înflorit și a făcut semințe.', 'Nu o culegeți și nu o scoateți din natură — florile de fâneață sunt în declin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ro', 'Margaretă', '„Floarea” margaretei este de fapt un mănunchi de zeci de floricele minuscule.', 'Vara, căutați margaretele mari și albe pe marginea drumurilor și în fânețe.', 'Lăsați o fâșie de iarbă necosită până în miezul verii, ca să poată înflori.', 'Evitați erbicidarea marginilor de drum și a fânețelor.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ro', 'Păpădie', 'Păpădia este una dintre cele mai importante surse timpurii de nectar pentru albine.', 'Din primăvară aproape peste tot; florile se deschid la soare și se închid în amurg.', 'Lăsați păpădia să înflorească în gazon primăvara, înainte de prima cosire.', 'Renunțați la erbicidele de gazon, ca polenizatorii timpurii să păstreze această hrană.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ro', 'Iarbă-neagră', 'O singură plantă de iarbă-neagră poate produce peste o sută de mii de semințe minuscule.', 'La sfârșitul verii, căutați covoarele purpurii pe landele deschise și în turbării.', 'Sprijiniți păstrarea landelor deschise și nedrenate.', 'Rămâneți pe poteci în lande și nu aprindeți niciodată focul pe vreme uscată.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ro', 'Afin', 'Afinele lasă degetele albastre și hrănesc tot ce mișcă, de la păsări la urși.', 'Vara, căutați tufele scunde cu fructe închise la culoare în pădurile de pin și molid.', 'Lăsați intact subarboretul, ca tufele scunde să poată rodi.', 'Dacă culesul e permis local, lăsați multe fructe pentru animalele sălbatice.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ro', 'Merișor', 'Merișoarele se păstrează luni întregi datorită unui conservant natural din fruct.', 'La sfârșitul verii și toamna, căutați fructele roșii lucioase pe covoare veșnic verzi.', 'Lăsați neatinsă vegetația de pe solul pădurii, ca aceste covoare să se poată întinde.', 'Dacă culesul e permis local, călcați cu grijă, ca să nu striviți plantele.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ro', 'Mesteacăn', 'Un mesteacăn susține sute de specii de insecte și hrănește astfel nenumărate păsări.', 'Tot anul; scoarța albă, care se cojește, îl face ușor de recunoscut în orice anotimp.', 'Lăsați pe sol frunzele căzute și lemnul mort: îmbogățesc solul și hrănesc insectele.', 'Evitați să smulgeți scoarța, fiindcă rănește și slăbește arborele.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ro', 'Molid', 'În Suedia, un molid crește din rădăcini vechi de mii de ani.', 'Tot anul, în păduri; conurile lui atârnate sunt cele mai lungi dintre toți molizii.', 'Lăsați pe sol conurile căzute și lemnul mort, care adăpostesc insecte și ciuperci.', 'Rămâneți pe poteci în pădure, ca să nu tasați rădăcinile de suprafață ale molidului.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ro', 'Pin silvestru', 'Pinii silvestri bătrâni au partea de sus a trunchiului portocalie și pot trăi secole.', 'Tot anul, pe terenuri nisipoase și stâncoase; căutați scoarța portocalie din partea de sus.', 'Lăsați în picioare lemnul mort și pinii bătrâni, foarte bogați în viață sălbatică.', 'Nu aprindeți niciodată focul lângă pini, pe teren uscat și nisipos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ro', 'Știucă', 'Știuca este un prădător la pândă, care poate țâșni din nemișcare într-o clipită.', 'Din primăvară până toamna, în apele mici, cu vegetație, ale lacurilor și râurilor lente.', 'Sprijiniți păstrarea apelor mici cu stuf și a plantelor acvatice unde se adăpostește puietul.', 'Țineți poluarea și gunoiul departe de apă; respectați regulile locale de pescuit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ro', 'Biban', 'Bibanii vânează în cârduri și poartă dungi puternice, care le sparg conturul.', 'În lunile calde, în jurul pontoanelor, al pâlcurilor de plante și al pragurilor adânci.', 'Sprijiniți apa curată și structurile scufundate care adăpostesc peștii mici.', 'Nu aruncați niciodată nimic în lacuri și râuri; respectați regulile locale de pescuit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ro', 'Babușcă', 'Babușca este un pește-pradă esențial, de care depind mulți prădători din lacuri.', 'În lunile calde, în bancuri aproape de suprafața lacurilor și a râurilor lente.', 'Sprijiniți apa curată și malurile cu vegetație, necesare pentru depunerea icrelor.', 'Țineți scurgerile și gunoiul departe de apă; respectați regulile locale de pescuit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'el', 'Σταχτάρα', 'Οι σταχτάρες μένουν στον αέρα για μήνες και κοιμούνται ακόμη και πετώντας.', 'Τα ζεστά καλοκαιρινά βράδια κοιτάξτε ψηλά πάνω από τις στέγες και ακούστε τα τσιριχτά σμήνη.', 'Τοποθετήστε φωλιά κάτω από τη μαρκίζα πριν επιστρέψουν τα πουλιά την άνοιξη.', 'Σε ανακαινίσεις διατηρήστε τις μικρές σχισμές κάτω από τη μαρκίζα, όπου φωλιάζουν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'el', 'Χελιδόνι', 'Τα χελιδόνια μεταναστεύουν κάθε χρόνο ως τη νότια Αφρική και επιστρέφουν.', 'Από την άνοιξη ως τις αρχές του φθινοπώρου πετούν χαμηλά πάνω από χωράφια και νερά.', 'Αφήστε μισάνοιχτη την πόρτα ενός αχυρώνα ή αποθήκης, για να φτάνουν στις φωλιές τους.', 'Μη γκρεμίζετε τις παλιές πήλινες φωλιές — τα χελιδόνια τις ξαναχρησιμοποιούν κάθε χρόνο.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'el', 'Κούκος', 'Ο κούκος γεννά τα αυγά του σε φωλιές άλλων πουλιών και δεν μεγαλώνει ποτέ δικούς του νεοσσούς.', 'Στα τέλη της άνοιξης ακούστε το «κού-κου» που ταξιδεύει μακριά από τις παρυφές του δάσους.', 'Στηρίξτε λιβάδια και φυτοφράχτες πλούσια σε έντομα, που τρέφουν τα πουλιά-ξενιστές του κούκου.', 'Μείνετε στα μονοπάτια κοντά σε θαμνώνες και καλαμιώνες, ώστε να μην ενοχλούνται οι ξενιστές.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'el', 'Κοκκινολαίμης', 'Ο κοκκινολαίμης υπερασπίζεται λυσσαλέα την επικράτειά του και τραγουδά όλη νύχτα κοντά σε φανοστάτες.', 'Όλο τον χρόνο σε κήπους και δάση· ακολουθεί συχνά όποιον σκάβει, ελπίζοντας σε σκουλήκια.', 'Αφήστε μια γωνιά του κήπου με πεσμένα φύλλα, όπου μπορεί να ψάχνει τροφή.', 'Αναβάλετε το βαρύ κλάδεμα των φυτοφρακτών ώσπου να τελειώσει η φωλεοποίηση, στα τέλη του καλοκαιριού.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'el', 'Κότσυφας', 'Το πλούσιο, φλογερό τραγούδι του αρσενικού είναι από τα πιο αναγνωρίσιμα της Ευρώπης.', 'Όλο τον χρόνο· την αυγή και το σούρουπο ακούστε τα αρσενικά να τραγουδούν από στέγες και κορυφές δέντρων.', 'Αφήστε φρέσκο νερό για πόση και μπάνιο, ιδίως στις περιόδους ξηρασίας.', 'Κρατήστε τις γάτες μέσα τα ξημερώματα στην περίοδο της φωλεοποίησης.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'el', 'Κεδρότσιχλα', 'Η κεδρότσιχλα είναι κοινωνική τσίχλα που περιπλανιέται σε θορυβώδη χειμωνιάτικα σμήνη.', 'Το φθινόπωρο και τον χειμώνα δείτε τα σμήνη να αποψιλώνουν φυτοφράχτες και σορβιές από καρπούς.', 'Αφήστε τους καρποφόρους θάμνους, όπως σορβιά και κράταιγο, ακλάδευτους μέσα στον χειμώνα.', 'Αφήστε τα πεσμένα μήλα στο έδαφος τον χειμώνα — είναι ζωτική τροφή στο κρύο.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'el', 'Καλόγερος', 'Ο καλόγερος έχει τεράστιο ρεπερτόριο και μαθαίνει νέες κραυγές από τους γείτονές του.', 'Όλο τον χρόνο· από τα τέλη του χειμώνα ακούστε το ηχηρό τραγούδι με τις δύο επαναλαμβανόμενες νότες.', 'Κρεμάστε φωλιά με άνοιγμα 32 mm σε ήσυχο, σκιερό σημείο.', 'Αποφύγετε τα φυτοφάρμακα στον κήπο, ώστε οι κάμπιες να επαρκούν για τους νεοσσούς.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'el', 'Γαλαζοπαπαδίτσα', 'Μία μόνο γέννα γαλαζοπαπαδίτσας μπορεί να καταναλώσει πάνω από χίλιες κάμπιες.', 'Όλο τον χρόνο σε κήπους και δάση, συχνά κρεμασμένη ανάποδα από λεπτά κλαδάκια.', 'Τοποθετήστε μικρή φωλιά με άνοιγμα 25 mm, μακριά από τους επικρατούντες ανέμους.', 'Παραλείψτε τα εντομοκτόνα την άνοιξη, ώστε οι κάμπιες να μείνουν στους νεοσσούς.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'el', 'Σπίνος', 'Το τραγούδι του σπίνου διαφέρει από περιοχή σε περιοχή, σχεδόν σαν τοπικές διάλεκτοι.', 'Από την άνοιξη ως το φθινόπωρο· τα αρσενικά τραγουδούν μια λαμπερή, κατιούσα φράση από ακάλυπτα κλαδιά.', 'Αφήστε μερικά φυτά με σπόρους και χορταριασμένες γωνιές όρθια μέσα στη σεζόν.', 'Κρατήστε τις ταΐστρες καθαρές, ώστε να μην εξαπλώνονται ασθένειες ανάμεσα στους σπίνους.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'el', 'Κίσσα', 'Η κίσσα θάβει χιλιάδες βελανίδια κάθε φθινόπωρο και, ξεχνώντας μερικά, φυτεύει ολόκληρα δρυοδάση.', 'Όλο τον χρόνο σε δρυοδάση· το φθινόπωρο αναζητήστε τις λάμψεις ροζ και γαλάζιου.', 'Αφήστε ανέγγιχτα τα πεσμένα βελανίδια και τα φύλλα κάτω από τις βελανιδιές.', 'Κρατήστε τους σκύλους στα μονοπάτια του δάσους, ώστε να μην ξεσηκώνονται τα πουλιά που τρέφονται στο έδαφος.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'el', 'Παρδαλοτσικλητάρα', 'Το ανοιξιάτικο «τύμπανο» δεν είναι αναζήτηση τροφής αλλά γρήγορο χτύπημα που διεκδικεί επικράτεια.', 'Όλο τον χρόνο· στα τέλη του χειμώνα ακούστε το τύμπανο να αντηχεί μέσα στο δάσος.', 'Αφήστε όρθιο το νεκρό ξύλο, που φιλοξενεί τα έντομα με τα οποία τρέφεται.', 'Μην κόβετε νεκρά ή ετοιμοθάνατα δέντρα που μπορεί να έχουν κουφάλες φωλιάς.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'el', 'Λευκοσουσουράδα', 'Το διαρκές κούνημα της ουράς ίσως δηλώνει εγρήγορση απέναντι στους θηρευτές.', 'Από την άνοιξη ως το φθινόπωρο κοντά σε νερά και ανοιχτό έδαφος, τρέχοντας και σταματώντας για έντομα.', 'Κρατήστε κοντά στο νερό μια λωρίδα κοντού χόρτου ή χαλικιού όπου μπορεί να ψάχνει τροφή.', 'Αποφύγετε να ενοχλείτε τα χαλίκια και τις όχθες όπου τρέφεται και φωλιάζει.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'el', 'Γερανός', 'Οι γερανοί εκτελούν νωρίς την άνοιξη ερωτικούς χορούς με πηδήματα και υποκλίσεις.', 'Από την άνοιξη ως το φθινόπωρο γύρω από υγροτόπους· η σαλπιγγοειδής κραυγή τους ακούγεται χιλιόμετρα μακριά.', 'Στηρίξτε την προστασία των αστράγγιστων τυρφώνων και των υγρών λιβαδιών όπου αναπαράγονται.', 'Παρατηρήστε τους υγροτόπους φωλεοποίησης από απόσταση — οι γερανοί εγκαταλείπουν τις ενοχλημένες φωλιές.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'el', 'Αγριόκυκνος', 'Ο αγριόκυκνος ζευγαρώνει για μια ζωή και αναγγέλλει την άφιξή του με δυνατές, σαλπιγγοειδείς κραυγές.', 'Την άνοιξη και το φθινόπωρο σε λίμνες και πλημμυρισμένα χωράφια, συχνά σε οικογενειακές ομάδες.', 'Στηρίξτε τη διατήρηση των ρηχών οχθών και των υγρών χωραφιών χωρίς αποστράγγιση.', 'Μη δίνετε ποτέ ψωμί στους κύκνους — τους βλάπτει· κρατήστε απόσταση πάνω στον πάγο.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'el', 'Πρασινοκέφαλη πάπια', 'Τα παπάκια κολυμπούν και τρέφονται μόνα τους λίγες ώρες μετά την εκκόλαψη.', 'Όλο τον χρόνο σχεδόν σε κάθε λιμνούλα, λίμνη ή αργό ποτάμι.', 'Αν ταΐζετε πάπιες, χρησιμοποιήστε βρώμη, μπιζέλια ή σπόρους αντί για ψωμί.', 'Κρατήστε τους σκύλους έξω από το νερό την άνοιξη, εκεί όπου φωλιάζουν οι πάπιες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'el', 'Γερακίνα', 'Η γερακίνα αιωρείται με φαρδιά φτερά και συχνά κράζει με ένα γατίσιο «πιιι-γιάου».', 'Από την άνοιξη ως το φθινόπωρο· ψάξτε την να κάνει κύκλους ψηλά πάνω από χωράφια και παρυφές δασών.', 'Στηρίξτε τα χέρσα λιβάδια και τα όρια των χωραφιών που φιλοξενούν αρουραίους και μικρή λεία.', 'Μη χρησιμοποιείτε ποτέ ποντικοφάρμακα: ανεβαίνουν την τροφική αλυσίδα ως τα αρπακτικά πουλιά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'el', 'Ψαραετός', 'Ο ψαραετός βουτά με τα πόδια μπροστά και κουβαλά λεία ως και μισή φορά το βάρος του.', 'Από την άνοιξη ως το φθινόπωρο κοντά σε μεγάλες λίμνες· δείτε το αιώρημα και μετά τη θεαματική βουτιά.', 'Στηρίξτε τεχνητές εξέδρες φωλιάσματος σε ψηλούς στύλους κοντά σε λίμνες με ψάρια.', 'Περάστε μακριά από τις εξέδρες, ώστε τα ζευγάρια να μην τρομάξουν και αφήσουν τα αυγά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'el', 'Κόκκινη αλεπού', 'Η αλεπού αξιοποιεί το μαγνητικό πεδίο της Γης για να ρυθμίσει το άλμα της σε κρυμμένη λεία.', 'Όλο τον χρόνο, πιο δραστήρια την αυγή και το σούρουπο στις παρυφές δασών και χωραφιών.', 'Αφήστε μια άγρια, ανενόχλητη γωνιά όπου οι αλεπούδες μπορούν να ξεκουράζονται και να ανοίγουν φωλιά.', 'Ασφαλίστε τους κάδους και μην αφήνετε ποτέ επιβλαβή αποφάγια στη διάθεσή τους.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'el', 'Ευρωπαϊκός σκαντζόχοιρος', 'Ένας σκαντζόχοιρος διανύει μερικά χιλιόμετρα σε μία μόνο νύχτα αναζήτησης τροφής.', 'Από την άνοιξη ως το φθινόπωρο μετά το σκοτάδι· τον χειμώνα πέφτει σε νάρκη κάτω από σωρούς φύλλων και ξύλων.', 'Ανοίξτε πέρασμα 13 εκ. στους φράχτες, ώστε οι σκαντζόχοιροι να κινούνται από κήπο σε κήπο.', 'Ελέγξτε τα ψηλά χόρτα πριν τα κόψετε και αφήστε σωρούς φύλλων για τη νάρκη.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'el', 'Ζαρκάδι', 'Το ζαρκάδι καθυστερεί την κύησή του, ώστε τα μικρά να γεννιούνται πάντα στις αρχές του καλοκαιριού.', 'Όλο τον χρόνο στις παρυφές των δασών, πιο ορατό να βόσκει την αυγή και το σούρουπο.', 'Στηρίξτε ακούρευτα όρια χωραφιών και θαμνώνες που του δίνουν κάλυψη και τροφή.', 'Κρατήστε τους σκύλους δεμένους κοντά στο δάσος νωρίς το καλοκαίρι, όταν τα μικρά μένουν κρυμμένα.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'el', 'Άλκη', 'Η άλκη είναι το μεγαλύτερο ελαφοειδές στη Γη· ένα μεγάλο αρσενικό ξεπερνά τον μισό τόνο.', 'Όλο τον χρόνο σε δάση και υγροτόπους, πιο δραστήρια την αυγή και το σούρουπο.', 'Στηρίξτε συνεχή δάση και υγρούς διαδρόμους που χρειάζεται η άλκη για να μετακινείται.', 'Οδηγείτε προσεκτικά την αυγή και το σούρουπο σε δασικούς δρόμους και μην πλησιάζετε ποτέ ένα μικρό.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'el', 'Κόκκινος σκίουρος', 'Ο κόκκινος σκίουρος φτιάχνει πολλές φωλιές και μετακινείται ανάμεσά τους.', 'Όλο τον χρόνο σε κωνοφόρα και μεικτά δάση, πιο δραστήριος νωρίς το πρωί.', 'Αφήστε κουκουνάρια, καρπούς και όρθια δέντρα από τα οποία τρέφεται και φωλιάζει.', 'Κρατήστε τους σκύλους στα μονοπάτια και μην ταρακουνάτε δέντρα που ίσως έχουν φωλιά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'el', 'Ευρωπαϊκός κάστορας', 'Τα φράγματα των καστόρων δημιουργούν υγροτόπους που ευνοούν ψάρια, πουλιά και έντομα για χιλιόμετρα.', 'Από την άνοιξη ως τα τέλη του φθινοπώρου σε αργά ποτάμια, πιο δραστήριος το σούρουπο.', 'Στηρίξτε τη διατήρηση των φραγμάτων και των παρόχθιων δέντρων όπου δεν υπάρχει κίνδυνος.', 'Κρατηθείτε μακριά από φωλιές και φράγματα, ιδίως όταν τα μικρά είναι ακόμη μωρά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'el', 'Χιονολαγός', 'Ο χιονολαγός ασπρίζει τον χειμώνα για καμουφλάζ πάνω στο χιόνι.', 'Όλο τον χρόνο σε ανοιχτό έδαφος και ξέφωτα, κυρίως την αυγή και το σούρουπο.', 'Στηρίξτε το μωσαϊκό ανοιχτού εδάφους και κάλυψης που χρειάζεται ο λαγός όλο τον χρόνο.', 'Κρατήστε τους σκύλους δεμένους σε ανοιχτό έδαφος, ώστε οι λαγοί που ξεκουράζονται να μην κυνηγηθούν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'el', 'Ασβός', 'Οι ασβοί ζουν σε οικογενειακές ομάδες, σε υπόγειες φωλιές που χρησιμοποιούνται επί γενιές.', 'Από την άνοιξη ως το φθινόπωρο μετά το σκοτάδι κοντά σε δάση· τον χειμώνα τον περνούν κοιμισμένοι.', 'Αφήστε ανενόχλητα πρανή και φυτοφράχτες όπου οι ασβοί μπορούν να σκάψουν φωλιά.', 'Μη φράζετε ποτέ και μη σκάβετε δίπλα σε ενεργή φωλιά — είναι το μακροχρόνιο σπίτι τους.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'el', 'Νανονυχτερίδα', 'Αυτή η μικροσκοπική νυχτερίδα τρώει ως και 3.000 σκνίπες και κουνούπια σε μία νύχτα.', 'Τα καλοκαιρινά βράδια δείτε το σούρουπο τη γρήγορη, σπασμωδική πτήση πάνω από τους κήπους.', 'Στερεώστε φωλιά για νυχτερίδες ψηλά σε τοίχο ή δέντρο που πιάνει τον απογευματινό ήλιο.', 'Αποφύγετε δυνατά φώτα στις εισόδους των καταφυγίων και κρατήστε σκοτεινό τον νυχτερινό ουρανό.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'el', 'Πεταλούδα της τσουκνίδας', 'Αυτή η πεταλούδα ξεχειμωνιάζει ως ενήλικη, συχνά σε αποθήκες και σοφίτες.', 'Από τις αρχές της άνοιξης ως το φθινόπωρο σε ηλιόλουστα άνθη, ιδίως τσουκνίδες και βουδλέιες.', 'Αφήστε ένα κομμάτι με τσουκνίδες σε ηλιόλουστη γωνιά — οι κάμπιες τις χρειάζονται.', 'Μην ενοχλείτε τον χειμώνα τις πεταλούδες που διαχειμάζουν σε αποθήκες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'el', 'Πεταλούδα παγώνι', 'Οι οφθαλμοί ανοίγουν απότομα για να τρομάξουν τα πουλιά, και τα φτερά μπορούν να σφυρίξουν.', 'Από την άνοιξη ως το φθινόπωρο τις ηλιόλουστες μέρες, σε γαϊδουράγκαθα, βουδλέιες και πεσμένα φρούτα.', 'Αφήστε να μεγαλώσει στον ήλιο ένα κομμάτι με τσουκνίδες για τις κάμπιες.', 'Μην ενοχλείτε τα ενήλικα που καταφεύγουν τον χειμώνα σε αποθήκες και στοίβες ξύλων.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'el', 'Λεμονόχρωμη πεταλούδα', 'Η αγγλική λέξη «butterfly» ίσως προέρχεται από το βουτυρένιο κίτρινο του αρσενικού αυτού του είδους.', 'Μία από τις πρώτες πεταλούδες της άνοιξης· ψάξτε τη στις παρυφές των δασών τις ήπιες μέρες.', 'Στηρίξτε τους ράμνους στους φυτοφράχτες, τα μόνα φυτά που τρώνε οι κάμπιές της.', 'Αποφύγετε τον καθαρισμό των θαμνωδών φυτοφρακτών που στεγάζουν τα διαχειμάζοντα ενήλικα.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'el', 'Πορτοκαλόφτερη πεταλούδα', 'Μόνο τα αρσενικά έχουν τις έντονες πορτοκαλί άκρες στα φτερά· τα θηλυκά είναι λευκά.', 'Την άνοιξη κατά μήκος υγρών λιβαδιών και μονοπατιών όπου φυτρώνει το καρδαμίνη.', 'Αφήστε την καρδαμίνη και το σκορδόχορτο να μεγαλώσουν σε υγρές, ακούρευτες γωνιές.', 'Αναβάλετε το κόψιμο των ερεισμάτων ώσπου οι κάμπιες να τελειώσουν την ανάπτυξή τους.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'el', 'Κοινό γαλάζιο', 'Τις κάμπιες αυτής της πεταλούδας τις φροντίζουν ενίοτε μυρμήγκια, που τα ελκύουν οι γλυκές εκκρίσεις τους.', 'Από τα τέλη της άνοιξης σε ηλιόλουστα λιβάδια πλούσια σε τριφύλλι και λωτό.', 'Αφήστε το λιβάδι ακούρευτο, ώστε λωτοί και τριφύλλια να μπορούν να ανθίσουν.', 'Αποφύγετε τον ψεκασμό με ζιζανιοκτόνο σε λιβάδια πλούσια σε αγριολούλουδα.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'el', 'Πρασινόφλεβη λευκή', 'Παρότι μοιάζει με τη λευκή του λάχανου, προτιμά τα άγρια φυτά από τα κηπευτικά.', 'Από την άνοιξη ως τα τέλη του καλοκαιριού σε υγρά λιβάδια, τάφρους και δασικά περάσματα.', 'Αφήστε τις υγρές γωνιές να αγριέψουν με ντόπια σταυρανθή, όπως η καρδαμίνη.', 'Αποφύγετε την αποστράγγιση και τον ψεκασμό των υγρών λιβαδιών όπου αναπαράγεται.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'el', 'Επτάστικτη πασχαλίτσα', 'Μία μόνο πασχαλίτσα τρώει χιλιάδες αφίδες στη διάρκεια της ζωής της.', 'Από την άνοιξη ως το φθινόπωρο σε φυτά με αφίδες· τον χειμώνα μαζεύονται σε ομάδες για να διαχειμάσουν.', 'Ανεχθείτε μερικές αφίδες και παραλείψτε τους ψεκασμούς, ώστε οι πασχαλίτσες να έχουν τροφή.', 'Αφήστε κούφια στελέχη και πεσμένα φύλλα όπου καταφεύγουν μέσα στον χειμώνα.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'el', 'Βομβίνος του εδάφους', 'Οι βασίλισσες είναι από τις πρώτες μέλισσες της άνοιξης, βουίζοντας χαμηλά για να βρουν τρύπες φωλιάς.', 'Από τις αρχές της άνοιξης ως το φθινόπωρο στα άνθη· την άνοιξη οι βασίλισσες ψάχνουν τη βάση των φυτοφρακτών.', 'Φυτέψτε ή διατηρήστε είδη με πρώιμη άνθηση και αφήστε το τριφύλλι να ανθίσει στο γκαζόν.', 'Αφήστε ανενόχλητα τα πρανή και τις παλιές ποντικότρυπες όπου εγκαθίστανται οι αποικίες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'el', 'Δυτική μέλισσα', 'Οι συλλέκτριες δείχνουν στην κυψέλη πού είναι τα άνθη χορεύοντας σε σχήμα οκτώ.', 'Από την άνοιξη ως το φθινόπωρο στα άνθη, τις ζεστές μέρες χωρίς αέρα.', 'Φροντίστε να διαδέχονται η μία την άλλη διαφορετικές ανθήσεις μέσα στις εποχές και βάλτε ένα ρηχό πιάτο με νερό.', 'Μην ψεκάζετε ανθισμένα φυτά, και ποτέ στη μέση της ημέρας.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'el', 'Αυτοκρατορική λιβελούλα', 'Μία από τις μεγαλύτερες λιβελούλες της Ευρώπης: πιάνει τη λεία της ακόμη και στον αέρα.', 'Τις ζεστές καλοκαιρινές μέρες δείτε τη να περιπολεί λιμνούλες και όχθες λιμνών.', 'Διατηρήστε ή σκάψτε μια λιμνούλα με φυτά και αφήστε τις όχθες της με βλάστηση.', 'Κρατήστε τις λιμνούλες μακριά από ρύπανση και απορροές, ώστε οι προνύμφες να αναπτυχθούν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'el', 'Κοινή φθινοπωρινή λιβελούλα', 'Αυτές οι λιβελούλες κάθονται συχνά στο ίδιο ζεστό σημείο και εκτοξεύονται για να πιάσουν έντομα που περνούν.', 'Από τα μέσα του καλοκαιριού ως το φθινόπωρο κοντά σε στάσιμα νερά, λιαζόμενες σε μονοπάτια και πασσάλους.', 'Αφήστε ηλιόλουστα σημεία στάσης και βλάστηση γύρω από λιμνούλες και τάφρους.', 'Αποφύγετε να παρασύρονται λιπάσματα ή λάδια στις λιμνούλες όπου ζουν οι προνύμφες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'el', 'Κόκκινο μυρμήγκι του δάσους', 'Οι θολωτές μυρμηγκοφωλιές τους ξεπερνούν το ένα μέτρο ύψος και στεγάζουν μισό εκατομμύριο μυρμήγκια.', 'Από την άνοιξη ως το φθινόπωρο σε δάση κωνοφόρων· ψάξτε τους θόλους από βελόνες.', 'Αφήστε τις μυρμηγκοφωλιές ανέγγιχτες — χρειάζονται χρόνια για να χτιστούν.', 'Μείνετε στα μονοπάτια και μην κλωτσάτε ποτέ και μη σκάβετε σε μυρμηγκοφωλιά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'el', 'Ανεμώνη του δάσους', 'Η ανεμώνη του δάσους εξαπλώνεται τόσο αργά, ώστε τα πυκνά χαλιά προδίδουν αρχαίο δάσος.', 'Την άνοιξη ψάξτε τα χαλιά από λευκά άνθη προτού βγάλουν φύλλα τα δέντρα.', 'Αφήστε το δάπεδο του δάσους ανενόχλητο, ώστε τα αργά ριζώματα να ευδοκιμήσουν.', 'Χαρείτε την εκεί όπου φυτρώνει — το κόψιμο αφαιρεί άνθη που χρειάστηκαν χρόνια να απλωθούν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'el', 'Κρίνος της κοιλάδας', 'Κάθε μέρος αυτού του γλυκομύριστου φυτού είναι δηλητηριώδες αν καταναλωθεί.', 'Στα τέλη της άνοιξης ακολουθήστε το άρωμα ως τα σκιερά δάση και τους σκιερούς κήπους.', 'Αφήστε στη θέση τους τις σκιερές παρυφές δασών και τα πεσμένα φύλλα όπου φυτρώνει.', 'Μην το κόβετε και μην το ξεριζώνετε, και κρατήστε το μακριά από παιδιά και κατοικίδια.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'el', 'Άγριο σκόρδο', 'Το άγριο σκόρδο συνήθως το μυρίζετε πολύ πριν δείτε τα λευκά του άνθη.', 'Την άνοιξη ψάξτε τα φαρδιά πράσινα φύλλα και τα αστεροειδή άνθη σε υγρά δάση.', 'Αφήστε τα υγρά δάση ανενόχλητα, ώστε τα χαλιά να ξαναφυτρώνουν κάθε χρόνο.', 'Αν η συλλογή επιτρέπεται τοπικά, πάρτε λίγο και μην ξεριζώνετε ποτέ τους βολβούς.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'el', 'Νεροκαλέντουλα', 'Ένα από τα αρχαιότερα αυτόχθονα φυτά: επέζησε στη Σκανδιναβία της τελευταίας εποχής των παγετώνων.', 'Την άνοιξη ψάξτε τα μεγάλα χρυσά άνθη σε έλη, τάφρους και όχθες λιμνούλων.', 'Κρατήστε τις όχθες λιμνούλων και τάφρων υγρές και ακούρευτες, ώστε να ανθίζει.', 'Αποφύγετε την αποστράγγιση υγρών εδαφών και αφήστε τα φυτά εκεί όπου φυτρώνουν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'el', 'Αγριοπρίμουλα', 'Η αγριοπρίμουλα ήταν κάποτε τόσο κοινή στα λιβάδια, ώστε τα παιδιά έφτιαχναν μπάλες από τα άνθη της.', 'Την άνοιξη ψάξτε τα γερτά κίτρινα άνθη σε παλιά, αλίπαντα λιβάδια.', 'Αφήστε τα λιβάδια ακούρευτα ώσπου η αγριοπρίμουλα να ανθίσει και να δέσει σπόρο.', 'Μην την κόβετε και μην τη σκάβετε από τη φύση — τα άνθη των λιβαδιών υποχωρούν.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'el', 'Μαργαρίτα', 'Το «άνθος» της μαργαρίτας είναι στην πραγματικότητα δεκάδες μικροσκοπικά άνθη μαζί.', 'Το καλοκαίρι ψάξτε τις μεγάλες λευκές μαργαρίτες σε άκρες δρόμων και λιβάδια.', 'Αφήστε μια λωρίδα χόρτου ακούρευτη μέσα στο καταμεσήμερο του καλοκαιριού, ώστε να ανθίσει.', 'Αποφύγετε τον ψεκασμό ερεισμάτων και λιβαδιών με ζιζανιοκτόνο.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'el', 'Ταραξάκο', 'Το ταραξάκο είναι από τις σημαντικότερες πρώιμες πηγές νέκταρος για τις μέλισσες.', 'Από την άνοιξη και μετά σχεδόν παντού· τα άνθη ανοίγουν στον ήλιο και κλείνουν το σούρουπο.', 'Αφήστε τα ταραξάκα να ανθίσουν στο γκαζόν την άνοιξη πριν από το πρώτο κούρεμα.', 'Παραλείψτε τα ζιζανιοκτόνα γκαζόν, ώστε οι πρώιμοι επικονιαστές να κρατήσουν αυτή την τροφή.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'el', 'Ρείκι', 'Ένα μόνο φυτό ρείκι μπορεί να παραγάγει πάνω από εκατό χιλιάδες μικροσκοπικούς σπόρους.', 'Στα τέλη του καλοκαιριού ψάξτε τα μοβ χαλιά σε ανοιχτά ρεικότοπα και τυρφώνες.', 'Στηρίξτε τη διατήρηση των ρεικότοπων ανοιχτών και χωρίς αποστράγγιση.', 'Μείνετε στα μονοπάτια στα ρεικότοπα και μην ανάβετε ποτέ φωτιά σε ξηρές συνθήκες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'el', 'Μύρτιλο', 'Τα μύρτιλα βάφουν τα δάχτυλα μπλε και τρέφουν τα πάντα, από πουλιά ως αρκούδες.', 'Το καλοκαίρι ψάξτε τους χαμηλούς θάμνους με σκούρους καρπούς σε πευκοδάση και ελατοδάση.', 'Αφήστε ανέπαφο τον υπόροφο του δάσους, ώστε οι χαμηλοί θάμνοι να καρπίσουν.', 'Αν η συλλογή επιτρέπεται τοπικά, αφήστε άφθονους καρπούς για την άγρια ζωή.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'el', 'Κόκκινο μύρτιλο', 'Τα κόκκινα μύρτιλα διατηρούνται μήνες χάρη σε ένα φυσικό συντηρητικό μέσα στον καρπό.', 'Στα τέλη του καλοκαιριού και το φθινόπωρο ψάξτε τους γυαλιστερούς κόκκινους καρπούς σε αειθαλή χαλιά.', 'Αφήστε ανενόχλητη τη βλάστηση του δασικού εδάφους, ώστε τα χαλιά να απλωθούν.', 'Αν η συλλογή επιτρέπεται τοπικά, πατάτε προσεκτικά για να μη λιώσετε τα φυτά.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'el', 'Ασημένια σημύδα', 'Μια σημύδα στηρίζει εκατοντάδες είδη εντόμων και τρέφει έτσι αμέτρητα πουλιά.', 'Όλο τον χρόνο· ο λευκός φλοιός που ξεφλουδίζει την κάνει αναγνωρίσιμη σε κάθε εποχή.', 'Αφήστε στο έδαφος τα πεσμένα φύλλα και το νεκρό ξύλο: εμπλουτίζουν το χώμα και τρέφουν τα έντομα.', 'Αποφύγετε να ξεφλουδίζετε τον φλοιό, γιατί πληγώνει και εξασθενεί το δέντρο.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'el', 'Ερυθρελάτη', 'Στη Σουηδία μια ερυθρελάτη βλασταίνει από ρίζες χιλιάδων ετών.', 'Όλο τον χρόνο στα δάση· τα κρεμαστά κουκουνάρια της είναι τα μακρύτερα από κάθε ελάτη.', 'Αφήστε στο έδαφος τα πεσμένα κουκουνάρια και το νεκρό ξύλο, που στεγάζουν έντομα και μύκητες.', 'Μείνετε στα μονοπάτια του δάσους, ώστε να μη συμπιέζονται οι επιφανειακές ρίζες.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'el', 'Δασική πεύκη', 'Τα γέρικα δασικά πεύκα λάμπουν πορτοκαλί κοντά στην κορυφή και ζουν αιώνες.', 'Όλο τον χρόνο σε αμμώδη και βραχώδη εδάφη· ψάξτε τον πορτοκαλί φλοιό ψηλά στον κορμό.', 'Αφήστε όρθιο το νεκρό ξύλο και τα γέρικα πεύκα, που είναι γεμάτα ζωή.', 'Μην ανάβετε ποτέ φωτιά πάνω ή κοντά σε πεύκα σε ξηρό, αμμώδες έδαφος.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'el', 'Τούρνα', 'Η τούρνα είναι θηρευτής ενέδρας που εκτινάσσεται από την ακινησία μέσα σε μια ανάσα.', 'Από την άνοιξη ως το φθινόπωρο στα ρηχά με βλάστηση λιμνών και αργών ποταμών.', 'Στηρίξτε τη διατήρηση των ρηχών με καλάμια και υδρόβια φυτά όπου κρύβονται τα μικρά ψάρια.', 'Κρατήστε ρύπανση και σκουπίδια έξω από το νερό· τηρήστε τους τοπικούς κανόνες αλιείας.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'el', 'Πέρκα', 'Οι πέρκες κυνηγούν σε κοπάδια και φορούν έντονες ρίγες που σπάνε το περίγραμμά τους.', 'Τους πιο ζεστούς μήνες γύρω από προβλήτες, φυτοστρώματα και απότομες βυθίσεις.', 'Στηρίξτε καθαρά νερά και βυθισμένες δομές που προστατεύουν τα μικρά ψάρια.', 'Μην πετάτε ποτέ τίποτα σε λίμνες και ποτάμια· τηρήστε τους τοπικούς κανόνες αλιείας.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'el', 'Τσιρώνι', 'Το τσιρώνι είναι ψάρι-λεία κλειδί, από το οποίο εξαρτώνται πολλοί θηρευτές των λιμνών.', 'Τους πιο ζεστούς μήνες σε κοπάδια κοντά στην επιφάνεια λιμνών και αργών ποταμών.', 'Στηρίξτε καθαρά νερά και όχθες με βλάστηση για την ωοτοκία.', 'Κρατήστε απορροές και σκουπίδια έξω από το νερό· τηρήστε τους τοπικούς κανόνες αλιείας.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'hu', 'Sarlósfecske', 'A sarlósfecskék hónapokig a levegőben maradhatnak, és repülés közben is alszanak.', 'Meleg nyári estéken nézzen magasra a tetők fölé, és figyelje a rikoltozó csapatokat.', 'Tegyen ki fészekodút az ereszalja alá, mielőtt a madarak tavasszal visszatérnek.', 'Felújításkor hagyja meg az ereszalja alatti apró réseket, ahol fészkelnek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'hu', 'Füsti fecske', 'A füsti fecskék évente egészen Afrika déli részéig vonulnak, majd vissza.', 'Tavasztól kora őszig figyelje, ahogy alacsonyan siklanak a nyílt szántók és a víz fölött.', 'Hagyja résnyire nyitva a pajta- vagy fészerajtót, hogy elérjék a fészkelőpárkányokat.', 'Ne verje le a régi sárfészkeket — a fecskék évről évre újrahasználják őket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'hu', 'Kakukk', 'A kakukk más madarak fészkébe rakja tojásait, és sosem neveli fel saját fiókáit.', 'Késő tavasszal figyelje a messzire hangzó „kakukk” szót az erdőszélek felől.', 'Támogassa a rovarban gazdag réteket és sövényeket, amelyek a kakukk gazdamadarait táplálják.', 'Maradjon az ösvényeken a bozótosok és nádasok közelében, hogy a gazdamadarak ne zavarodjanak meg.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'hu', 'Vörösbegy', 'A vörösbegy hevesen védi a területét, és utcai lámpák közelében éjszaka is énekel.', 'Egész évben kertekben és erdőkben; szívesen követi az ásó embert, gilisztát remélve.', 'Hagyjon a kert egyik sarkában avart, ahol táplálék után kutathat.', 'Halassza el az erős sövénynyírást, amíg a fészkelés a nyár végén véget nem ér.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'hu', 'Fekete rigó', 'A hím telt, fuvolázó éneke Európa egyik legkönnyebben felismerhető madárhangja.', 'Egész évben; hajnalban és alkonyatkor hallgassa a tetőkről és fakoronákból éneklő hímeket.', 'Tegyen ki friss vizet ivásra és fürdésre, különösen száraz időszakokban.', 'Tartsa bent a macskákat hajnalban a fészkelési időszakban.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'hu', 'Fenyőrigó', 'A fenyőrigó társas rigó, amely zajos, csivitelő téli csapatokban kóborol.', 'Ősszel és télen figyelje, ahogy a csapatok lekopasztják a sövények és berkenyék bogyóit.', 'Hagyja metszetlenül télen át a bogyós cserjéket, például a berkenyét és a galagonyát.', 'Hagyja a földön a lehullott almát télen — nagy hidegben létfontosságú táplálék.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'hu', 'Széncinege', 'A széncinegének óriási hangkészlete van, és új hívóhangokat tanul a szomszédaitól.', 'Egész évben; a tél végétől hallgassa a csengő, két hangból álló ismételt éneket.', 'Akasszon ki 32 mm-es röpnyílású odút csendes, árnyékos helyre.', 'Kerülje a kerti növényvédő szereket, hogy elég hernyó jusson a fiókáknak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'hu', 'Kék cinege', 'Egyetlen kék cinege fészekalj több mint ezer hernyót képes elfogyasztani.', 'Egész évben kertekben és erdőkben, gyakran fejjel lefelé lógva vékony gallyakon.', 'Tegyen ki kis, 25 mm-es röpnyílású odút az uralkodó széliránytól védve.', 'Hagyja el a rovarölő szereket tavasszal, hogy a hernyók a fiókáknak maradjanak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'hu', 'Erdei pinty', 'Az erdei pinty éneke tájegységenként eltér, szinte akár a helyi nyelvjárások.', 'Tavasztól őszig; a hímek szabad ülőhelyről csengő, ereszkedő strófát énekelnek.', 'Hagyjon állva néhány magvas növényt és gyomos foltot a szezon idejére.', 'Tartsa tisztán az etetőket, hogy a betegségek ne terjedjenek a pintyek között.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'hu', 'Szajkó', 'A szajkó minden ősszel több ezer makkot ás el, és a felejtett makkokból egész tölgyesek nőnek.', 'Egész évben tölgyesekben; ősszel figyelje a rózsaszín és kék villanásokat.', 'Hagyja bolygatatlanul a lehullott makkot és az avart a tölgyek alatt.', 'Tartsa a kutyákat az erdei ösvényeken, hogy a talajon táplálkozó madarak ne rebbenjenek fel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'hu', 'Nagy fakopáncs', 'A tavaszi „dobolás” nem táplálkozás, hanem gyors pergés, amellyel a területét jelöli ki.', 'Egész évben; tél végén hallgassa a dobolást, ahogy visszhangzik az erdőn át.', 'Hagyja állva a holt fát, amely a harkály táplálékául szolgáló rovaroknak ad otthont.', 'Ne vágja ki az elhalt vagy pusztuló fákat, amelyekben odú lehet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'hu', 'Barázdabillegető', 'A farok szüntelen billegtetése talán a ragadozókkal szembeni éberséget jelzi.', 'Tavasztól őszig víz mellett és nyílt talajon, futva és megtorpanva kap a rovarok után.', 'Tartson a víz közelében rövid füves vagy kavicsos sávot, ahol táplálékot kereshet.', 'Kerülje a kavicsos partszakaszok bolygatását, ahol táplálkozik és fészkel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'hu', 'Daru', 'A daru kora tavasszal ugrálós, meghajlásokkal teli násztáncot lejt.', 'Tavasztól őszig vizes élőhelyeken; trombitáló hangja kilométerekre elhallatszik.', 'Támogassa a lecsapolatlan lápok és nedves rétek védelmét, ahol a darvak költenek.', 'Távolról figyelje a költőhelyeket — a daru elhagyja a megzavart fészket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'hu', 'Énekes hattyú', 'Az énekes hattyú életre szóló párt választ, és hangos, trombitáló hívással jelzi érkezését.', 'Tavasszal és ősszel tavakon és elárasztott mezőkön, gyakran családi csoportokban.', 'Támogassa a sekély tópartok és nedves szántók megőrzését lecsapolás nélkül.', 'Soha ne etesse kenyérrel a hattyúkat — árt nekik; a jégen tartson távolságot.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'hu', 'Tőkés réce', 'A kiskacsák a kikeléstől számított néhány órán belül úsznak és maguk táplálkoznak.', 'Egész évben szinte bármely tavon, tócsán vagy lassú folyású folyón.', 'Ha eteti a kacsákat, zabot, borsót vagy magvakat adjon kenyér helyett.', 'Tavasszal tartsa a kutyákat a vízen kívül ott, ahol a kacsák fészkelnek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'hu', 'Egerészölyv', 'Az egerészölyv széles szárnyakon vitorlázik, és gyakran macskanyávogásra emlékeztető hangot ad.', 'Tavasztól őszig; keresse, ahogy magasan köröz szántók és erdőszélek fölött.', 'Támogassa a kaszálatlan gyepeket és szántószegélyeket, amelyek pockokat és apró zsákmányt rejtenek.', 'Soha ne használjon rágcsálóirtót: felkúszik a tápláléklánc mentén a ragadozó madarakig.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'hu', 'Halászsas', 'A halászsas lábbal előre csap a vízbe, és testsúlya felével egyenlő zsákmányt is elbír.', 'Tavasztól őszig nagy tavak közelében; figyelje a szitálást, majd a látványos zuhanást.', 'Támogassa a magas oszlopokra állított mesterséges fészektartókat halban gazdag tavak mellett.', 'Kerülje el nagy ívben a fészektartókat, hogy a párok ne riadjanak le a tojásokról.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'hu', 'Vörös róka', 'A róka a Föld mágneses terét is segítségül hívja, amikor rejtett zsákmányra ugrik.', 'Egész évben, leginkább hajnalban és alkonyatkor az erdő- és szántószéleken.', 'Hagyjon egy vadon maradt, háborítatlan sarkot, ahol a rókák pihenhetnek és kotorékot áshatnak.', 'Zárja le a kukákat, és soha ne hagyjon kint ártalmas ételmaradékot a rókáknak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'hu', 'Nyugati sün', 'Egy sün egyetlen éjszakai táplálékkereső úton is megtehet néhány kilométert.', 'Tavasztól őszig sötétedés után; télen levél- és rőzserakások alatt alszik téli álmot.', 'Vágjon 13 cm-es rést a kerítésbe, hogy a sünök átjárhassanak a kertek között.', 'Ellenőrizze a magas füvet kaszálás előtt, és hagyjon avarkupacokat a téli álomhoz.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'hu', 'Őz', 'Az őz késlelteti a vemhességét, hogy a gidák mindig kora nyáron szülessenek.', 'Egész évben az erdőszéleken, leginkább hajnalban és alkonyatkor legelészve látható.', 'Támogassa a kaszálatlan szántószegélyeket és bozótosokat, amelyek fedezéket és táplálékot adnak.', 'Tartsa pórázon a kutyákat az erdő közelében kora nyáron, amikor a gidák rejtve lapulnak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'hu', 'Jávorszarvas', 'A jávorszarvas a Föld legnagyobb szarvasféléje; egy nagy bika fél tonnánál is többet nyom.', 'Egész évben erdőkben és vizes élőhelyeken, leginkább hajnalban és alkonyatkor.', 'Támogassa az összefüggő erdőket és nedves folyosókat, amelyekre a jávorszarvasnak szüksége van.', 'Vezessen óvatosan hajnalban és alkonyatkor az erdei utakon, és soha ne közelítsen borjúhoz.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'hu', 'Vörös mókus', 'A vörös mókus több fészket is épít, és váltogatja őket.', 'Egész évben fenyvesekben és elegyes erdőkben, kora reggel a legszorgosabb.', 'Hagyjon tobozt, magvakat és álló fákat, amelyekből táplálkozik és fészkel.', 'Tartsa a kutyákat az ösvényeken, és ne rázza meg a fákat, amelyekben fészek lehet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'hu', 'Európai hód', 'A hódgátak vizes élőhelyeket teremtenek, amelyek kilométereken át segítik a halakat, madarakat és rovarokat.', 'Tavasztól késő őszig lassú folyású folyók mentén, alkonyatkor a legaktívabb.', 'Támogassa a hódgátak és a parti fák helyben hagyását ott, ahol ez veszélytelen.', 'Maradjon távol a hódváraktól és a gátaktól, különösen amíg a kicsinyek kicsik.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'hu', 'Havasi nyúl', 'A havasi nyúl télre kifehéredik, hogy beleolvadjon a hóba.', 'Egész évben nyílt terepen és erdei tisztásokon, főként hajnalban és alkonyatkor.', 'Támogassa a nyílt terület és a fedezék mozaikját, amelyre a nyúlnak egész évben szüksége van.', 'Tartsa pórázon a kutyákat nyílt terepen, hogy a pihenő nyulakat ne hajtsák meg.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'hu', 'Borz', 'A borzok családi csoportokban élnek földalatti kotorékokban, amelyeket nemzedékek használnak.', 'Tavasztól őszig sötétedés után az erdő közelében; a telet átalussza.', 'Hagyja háborítatlanul a partoldalakat és sövényeket, ahol a borz kotorékot áshat.', 'Soha ne torlaszolja el a lakott kotorékot, és ne ásson mellette — ez a hosszú távú otthona.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'hu', 'Közönséges törpedenevér', 'Ez az apró denevér egyetlen éjszaka alatt akár 3000 muslicát és szúnyogot is elfogyaszt.', 'Nyári estéken figyelje alkonyatkor a gyors, cikázó repülést a kertek fölött.', 'Szereljen denevérodút magasra egy falra vagy fára, amelyet ér az esti nap.', 'Kerülje az erős fényt a búvóhelyek bejáratánál, és hagyja sötéten az éjszakai eget.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'hu', 'Kis rókalepke', 'Ez a lepke kifejlett alakban telel át, gyakran fészerekben és padlásokon.', 'Kora tavasztól őszig napos virágokon, különösen csalánon és nyáriorgonán.', 'Hagyjon egy csalánfoltot napos sarokban — a hernyóinak szüksége van rá.', 'Ne zavarja télen a fészerekben áttelelő lepkéket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'hu', 'Nappali pávaszem', 'A szemfoltok hirtelen felvillannak, hogy megriasszák a madarakat, és a szárnyak sziszegni is tudnak.', 'Tavasztól őszig napsütéses napokon, bogáncson, nyáriorgonán és lehullott gyümölcsön.', 'Hagyjon napos helyen csalánfoltot nőni a hernyóinak.', 'Ne zavarja a fészerekben és farakásokban áttelelő kifejlett lepkéket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'hu', 'Citromlepke', 'Az angol „butterfly” szó eredete talán e faj hímjének vajsárga színe.', 'A tavasz egyik első lepkéje; keresse az erdőszéleken enyhe napokon.', 'Támogassa a sövények kutyabengéjét, az egyetlen növényt, amelyet a hernyói fogyasztanak.', 'Kerülje a bozótos sövények kitakarítását, amelyek az áttelelő lepkéknek adnak menedéket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'hu', 'Hajnalpírlepke', 'Csak a hímeknek van élénk narancsszínű szárnycsúcsa; a nőstények fehérek.', 'Tavasszal nedves rétek és dűlőutak mentén, ahol réti kakukktorma nő.', 'Hagyja megnőni a réti kakukktormát és a kányazsombort nedves, kaszálatlan sarkokban.', 'Halassza el az útszélek kaszálását, amíg a hernyók be nem fejezik a táplálkozást.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'hu', 'Közönséges boglárka', 'E lepke hernyóit néha hangyák gondozzák, amelyeket az édes váladékuk vonz.', 'Késő tavasztól napos, lóherében és szarvaskerepben gazdag gyepeken.', 'Hagyja kaszálatlanul a gyepet, hogy a kerep és a lóhere virágozhasson.', 'Kerülje a vadvirágban gazdag gyepek gyomirtózását.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'hu', 'Repcelepke', 'Bár a káposztalepkére hasonlít, a vadon élő növényeket kedveli a kerti veteményekkel szemben.', 'Tavasztól nyár végéig nedves réteken, árkokban és erdei nyiladékokon.', 'Hagyja elvadulni a nedves sarkokat őshonos keresztesvirágúakkal, például kakukktormával.', 'Kerülje a nedves rétek lecsapolását és permetezését, ahol szaporodik.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'hu', 'Hétpettyes katicabogár', 'Egyetlen katicabogár élete során több ezer levéltetűt fogyaszt el.', 'Tavasztól őszig levéltetves növényeken; télen csoportokba gyűlve telelnek át.', 'Tűrjön meg néhány levéltetűt, és hagyja el a permetezést, hogy a katicáknak legyen mit enniük.', 'Hagyjon üreges szárakat és avart, ahol télen meghúzódnak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'hu', 'Földi poszméh', 'A királynők a tavasz első méhei közé tartoznak, alacsonyan zümmögve keresnek fészeküreget.', 'Kora tavasztól őszig virágokon; tavasszal a királynők a sövények tövét kutatják át.', 'Ültessen vagy hagyjon meg korán nyíló növényeket, és hagyja virágozni a lóherét a gyepen.', 'Hagyja bolygatatlanul a partoldalakat és a régi egérjáratokat, ahol a kolóniák fészkelnek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'hu', 'Nyugati mézelő méh', 'A gyűjtögetők nyolcas alakú tánccal mutatják meg a kaptárnak, hol vannak a virágok.', 'Tavasztól őszig virágokon, meleg, szélcsendes napokon.', 'Gondoskodjon róla, hogy az évszakokon át váltsák egymást a virágzások, és tegyen ki sekély vizestálat.', 'Ne permetezze a virágzó növényeket, és soha ne a nap közepén.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'hu', 'Óriás szitakötő', 'Európa egyik legnagyobb szitakötője: zsákmányát akár röptében is elkapja.', 'Meleg nyári napokon figyelje, ahogy tavakat és tópartokat járőröz.', 'Tartson fenn vagy ásson növényes tavat, és hagyja a partját benőni.', 'Tartsa a tavakat szennyezéstől és bemosódástól mentesen, hogy a lárvák fejlődhessenek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'hu', 'Közönséges őszi szitakötő', 'Ezek a szitakötők gyakran ugyanarra a meleg helyre szállnak vissza, és kicsapnak az arra szálló rovarokra.', 'Nyár közepétől őszig állóvizek közelében, ösvényeken és karókon sütkérezve.', 'Hagyjon napos ülőhelyeket és növényzetet a tavak és árkok körül.', 'Ne engedje, hogy műtrágya vagy olaj mosódjon be a tavakba, ahol a lárvák élnek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'hu', 'Vörös erdei hangya', 'Kupolás bolyaik meghaladhatják az egy méter magasságot, és félmillió hangyának adnak otthont.', 'Tavasztól őszig fenyvesekben; keresse a tűlevelekből épült kupolákat.', 'Hagyja érintetlenül a hangyabolyokat — évekbe telik felépíteni őket.', 'Maradjon az ösvényeken, és soha ne rúgjon vagy ásson bele hangyabolyba.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'hu', 'Berki szellőrózsa', 'A berki szellőrózsa olyan lassan terjed, hogy a sűrű szőnyegek ősi erdőt jeleznek.', 'Tavasszal keresse a fehér virágszőnyegeket, mielőtt a fák kilombosodnának.', 'Hagyja bolygatatlanul az erdő talaját, hogy a lassan kúszó gyöktörzsek megerősödhessenek.', 'Gyönyörködjön benne ott, ahol nő — a szedés olyan virágokat vesz el, amelyek évekig terjedtek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'hu', 'Gyöngyvirág', 'Ennek az édes illatú növénynek minden része mérgező, ha lenyelik.', 'Késő tavasszal kövesse az illatot árnyas erdőkbe és árnyékos kertekbe.', 'Hagyja a helyén az árnyas erdőszéleket és az avart, ahol nő.', 'Ne szedje és ne ássa ki, és tartsa távol a gyermekektől és a háziállatoktól.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'hu', 'Medvehagyma', 'A medvehagymát általában jóval előbb megérzi az orra, mint hogy meglátná fehér virágait.', 'Tavasszal keresse a széles zöld leveleket és a csillag alakú virágokat nedves erdőkben.', 'Hagyja háborítatlanul a nedves erdőket, hogy a szőnyegek évről évre visszanőhessenek.', 'Ha a gyűjtés helyben engedélyezett, vigyen keveset, és soha ne ássa ki a hagymákat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'hu', 'Mocsári gólyahír', 'Az egyik legősibb őshonos növény: Skandináviában túlélte az utolsó jégkorszakot.', 'Tavasszal keresse a nagy aranyszínű virágokat mocsarakban, árkokban és tópartokon.', 'Tartsa nedvesen és kaszálatlanul a tó- és árokpartokat, hogy virágozhasson.', 'Kerülje a nedves talaj lecsapolását, és hagyja a növényeket ott, ahol nőnek.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'hu', 'Tavaszi kankalin', 'A tavaszi kankalin egykor annyira gyakori volt a kaszálókon, hogy a gyerekek labdát gyúrtak belőle.', 'Tavasszal keresse a bókoló sárga virágokat régi, trágyázatlan réteken.', 'Hagyja kaszálatlanul a réteket, amíg a kankalin el nem virágzik és magot nem érlel.', 'Ne szedje és ne ássa ki a vadonból — a réti virágok visszaszorulóban vannak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'hu', 'Réti margitvirág', 'A margitvirág „virága” valójában több tucat apró virág együttese.', 'Nyáron keresse a nagy fehér margarétákat útszéleken és réteken.', 'Hagyjon egy fűsávot kaszálatlanul a nyár közepéig, hogy virágozhasson.', 'Kerülje az útszélek és rétek gyomirtózását.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'hu', 'Pongyola pitypang', 'A pitypang a méhek egyik legfontosabb korai nektárforrása.', 'Tavasztól kezdve szinte mindenütt; virágai napsütésben nyílnak, alkonyatkor záródnak.', 'Hagyja a pitypangot virágozni a gyepen tavasszal az első nyírás előtt.', 'Hagyja el a gyepgyomirtókat, hogy a korai beporzók megtartsák ezt a táplálékot.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'hu', 'Csarab', 'Egyetlen csarabtő több mint százezer apró magot hozhat.', 'Nyár végén keresse a lila szőnyegeket nyílt fenyéreken és lápokon.', 'Támogassa a fenyérek nyitva és lecsapolatlanul tartását.', 'Maradjon az ösvényeken a fenyéreken, és száraz időben soha ne gyújtson tüzet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'hu', 'Fekete áfonya', 'A fekete áfonya kékre festi az ujjakat, és madaraktól medvékig mindenkit táplál.', 'Nyáron keresse az alacsony, sötét bogyós cserjéket fenyvesekben és lucfenyvesekben.', 'Hagyja érintetlenül az erdei aljnövényzetet, hogy az alacsony cserjék termést hozhassanak.', 'Ha a szedés helyben engedélyezett, hagyjon bőven bogyót a vadon élő állatoknak.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'hu', 'Vörös áfonya', 'A vörös áfonya hónapokig eláll a gyümölcsben lévő természetes tartósítószernek köszönhetően.', 'Nyár végén és ősszel keresse a fényes piros bogyókat örökzöld szőnyegeken.', 'Hagyja háborítatlanul az erdőtalaj növényzetét, hogy a szőnyegek terjedhessenek.', 'Ha a szedés helyben engedélyezett, lépjen óvatosan, nehogy összenyomja a növényeket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'hu', 'Közönséges nyír', 'Egy nyírfa több száz rovarfajt tart el, és ezzel számtalan madarat táplál.', 'Egész évben; a fehér, hámló kéreg minden évszakban könnyen felismerhetővé teszi.', 'Hagyja a földön a lehullott nyírleveleket és a holt fát: gazdagítják a talajt és táplálják a rovarokat.', 'Kerülje a kéreg lehántását, mert sebet ejt a fán és gyengíti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'hu', 'Lucfenyő', 'Svédországban egy lucfenyő több ezer éves gyökerekből növekszik.', 'Egész évben erdőkben; csüngő tobozai valamennyi lucfenyő közül a leghosszabbak.', 'Hagyja a földön a lehullott tobozokat és a holt fát, amelyek rovaroknak és gombáknak adnak otthont.', 'Maradjon az erdei ösvényeken, hogy ne tömörítse a luc sekély gyökereit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'hu', 'Erdeifenyő', 'Az öreg erdeifenyők törzse a korona közelében narancsszínben izzik, és évszázadokig élhetnek.', 'Egész évben homokos és sziklás talajon; keresse a törzs felső részének narancsos kérgét.', 'Hagyja állva a holt fát és az öreg fenyőket, amelyek gazdagok az élővilágban.', 'Soha ne gyújtson tüzet fenyőknek támasztva vagy közelükben száraz, homokos talajon.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'hu', 'Csuka', 'A csuka lesből támadó ragadozó, amely szempillantás alatt lendül ki a mozdulatlanságból.', 'Tavasztól őszig tavak és lassú folyók növényes sekélyeseiben.', 'Támogassa a nádas sekélyesek és a vízinövények megőrzését, ahol az ivadék meghúzódik.', 'Tartsa a szennyezést és a szemetet távol a víztől; kövesse a helyi horgászszabályokat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'hu', 'Sügér', 'A sügér falkában vadászik, és határozott sávjai megtörik a körvonalát.', 'A melegebb hónapokban stégek, hínármezők és letörések körül.', 'Támogassa a tiszta vizet és a víz alatti szerkezeteket, amelyek védik a kis halakat.', 'Soha ne öntsön semmit tavakba és folyókba; kövesse a helyi horgászszabályokat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'hu', 'Bodorka', 'A bodorka kulcsfontosságú zsákmányhal, amelytől sok tavi ragadozó függ.', 'A melegebb hónapokban rajokban a tavak és lassú folyók felszíne közelében.', 'Támogassa a tiszta vizet és a növényzettel borított partokat az ívás érdekében.', 'Tartsa a bemosódást és a szemetet távol a víztől; kövesse a helyi horgászszabályokat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'cs', 'Rorýs obecný', 'Rorýsi dokážou zůstat ve vzduchu celé měsíce a spí dokonce za letu.', 'Za teplých letních večerů se dívejte vysoko nad střechy a poslouchejte křičící hejna.', 'Umístěte budku pod okap dříve, než se ptáci na jaře vrátí.', 'Při rekonstrukci zachovejte drobné škvíry pod okapem, kde hnízdí.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'cs', 'Vlaštovka obecná', 'Vlaštovky každoročně táhnou až do jižní Afriky a zase zpět.', 'Od jara do časného podzimu je uvidíte, jak nízko brázdí pole a vodní hladiny.', 'Nechte pootevřená vrata stodoly nebo kůlny, aby se dostaly ke svým hnízdům.', 'Nestrhávejte stará hliněná hnízda — vlaštovky je používají rok co rok.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'cs', 'Kukačka obecná', 'Kukačka klade vejce do hnízd jiných ptáků a nikdy nevychovává vlastní mláďata.', 'Pozdě na jaře poslouchejte daleko nesoucí se „ku-ku“ od okrajů lesa.', 'Podpořte louky a meze bohaté na hmyz, které živí hostitelské ptáky kukačky.', 'Držte se cest u křovin a rákosin, aby hostitelští ptáci nebyli rušeni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'cs', 'Červenka obecná', 'Červenka urputně brání své teritorium a u pouličních lamp zpívá i v noci.', 'Celoročně v zahradách a lesích; ráda sleduje toho, kdo rýpe, v naději na žížaly.', 'Nechte v rohu zahrady vrstvu spadaného listí, kde může hledat potravu.', 'Odložte silný řez živých plotů, dokud koncem léta neskončí hnízdění.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'cs', 'Kos černý', 'Sytý, flétnový zpěv samce patří k nejznámějším v Evropě.', 'Celoročně; za svítání a soumraku poslouchejte samce zpívající ze střech a korun stromů.', 'Vystavte čerstvou vodu k pití a koupání, hlavně v suchých obdobích.', 'Nechte kočky za rozbřesku doma po dobu hnízdění.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'cs', 'Drozd kvíčala', 'Kvíčala je společenský drozd, který se v zimě potuluje v hlučných, štěbetavých hejnech.', 'Na podzim a v zimě sledujte hejna, jak obírají bobule z živých plotů a jeřábů.', 'Nechte přes zimu nestříhané bobulaté keře, jako je jeřáb a hloh.', 'Nechte v zimě spadaná jablka ležet — v mrazech jsou životně důležitou potravou.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'cs', 'Sýkora koňadra', 'Sýkora koňadra má obrovský hlasový rejstřík a nové hlasy se učí od sousedů.', 'Celoročně; od konce zimy poslouchejte zvonivý zpěv ze dvou opakovaných tónů.', 'Pověste budku s otvorem 32 mm na klidné, stinné místo.', 'Vyhněte se pesticidům na zahradě, aby housenek stačilo na nakrmení mláďat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'cs', 'Sýkora modřinka', 'Jediná snůška modřinek dokáže spotřebovat přes tisíc housenek.', 'Celoročně v zahradách a lesích, často visící hlavou dolů na tenkých větvičkách.', 'Umístěte malou budku s otvorem 25 mm mimo dosah převládajícího větru.', 'Vynechejte na jaře insekticidy, aby housenky zůstaly mláďatům.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'cs', 'Pěnkava obecná', 'Zpěv pěnkavy se liší kraj od kraje, skoro jako místní nářečí.', 'Od jara do podzimu; samci zpívají jasnou, klesající frázi z odkrytých větví.', 'Nechte přes sezonu stát pár odkvetlých semenných lat a plevelnatých koutů.', 'Udržujte krmítka čistá, aby se mezi pěnkavami nešířily nemoci.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'cs', 'Sojka obecná', 'Sojka každý podzim zakope tisíce žaludů a tím, že na některé zapomene, vysází celé doubravy.', 'Celoročně v doubravách; na podzim vyhlížejte záblesky růžové a modré.', 'Nechte pod duby nedotčené spadané žaludy a listovou hrabanku.', 'Držte psy na lesních cestách, aby ptáci hledající potravu na zemi nebyli plašeni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'cs', 'Strakapoud velký', 'Jarní „bubnování“ není hledání potravy, ale rychlý víření, kterým si nárokuje teritorium.', 'Celoročně; na konci zimy poslouchejte bubnování rozléhající se lesem.', 'Nechte stát mrtvé dřevo, které hostí hmyz, jímž se strakapoud živí.', 'Nekácejte mrtvé nebo odumírající stromy, v nichž mohou být hnízdní dutiny.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'cs', 'Konipas bílý', 'Neustálé pokyvování ocasem možná signalizuje ostražitost vůči predátorům.', 'Od jara do podzimu u vody a na holé půdě, běhá a zastavuje se, aby chytil hmyz.', 'Udržujte u vody pruh nízké trávy nebo štěrku, kde může hledat potravu.', 'Nerušte štěrkové náplavy a břehy, kde se živí a hnízdí.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'cs', 'Jeřáb popelavý', 'Jeřábi předvádějí časně zjara námluvní tance plné skoků a úklon.', 'Od jara do podzimu u mokřadů; jejich troubení se nese na kilometry daleko.', 'Podpořte ochranu neodvodněných rašelinišť a mokrých luk, kde jeřábi hnízdí.', 'Pozorujte hnízdní mokřady z dálky — jeřábi rušená hnízda opouštějí.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'cs', 'Labuť zpěvná', 'Labuť zpěvná se páří na celý život a svůj přílet ohlašuje hlasitým troubením.', 'Na jaře a na podzim na jezerech a zaplavených polích, často v rodinných skupinách.', 'Podpořte zachování mělkých břehů a mokrých polí bez odvodnění.', 'Nikdy nekrmte labutě chlebem — škodí jim; na ledu si držte odstup.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'cs', 'Kachna divoká', 'Káčata plavou a živí se sama už pár hodin po vylíhnutí.', 'Celoročně téměř na každém rybníce, jezeře nebo pomalé řece.', 'Pokud kachny krmíte, použijte oves, hrách nebo semínka místo chleba.', 'Na jaře nepouštějte psy do vody tam, kde kachny hnízdí.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'cs', 'Káně lesní', 'Káně plachtí na širokých křídlech a často volá kočičím „píííjau“.', 'Od jara do podzimu; hledejte ji, jak krouží vysoko nad poli a okraji lesů.', 'Podpořte neposečené travnaté plochy a okraje polí, kde žijí hraboši a drobná kořist.', 'Nikdy nepoužívejte jedy na hlodavce: stoupají potravním řetězcem až k dravcům.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'cs', 'Orlovec říční', 'Orlovec se vrhá do vody nohama napřed a unese kořist o polovině vlastní hmotnosti.', 'Od jara do podzimu u velkých jezer; vyhlížejte třepotavý let a pak strmý střemhlavý pád.', 'Podpořte umělé hnízdní plošiny na vysokých sloupech u jezer bohatých na ryby.', 'Vyhněte se hnízdním plošinám velkým obloukem, aby páry neopustily vejce.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'cs', 'Liška obecná', 'Liška si při skoku na skrytou kořist pomáhá magnetickým polem Země.', 'Celoročně, nejaktivnější za svítání a soumraku podél okrajů lesů a polí.', 'Nechte divoký, nerušený kout, kde mohou lišky odpočívat a hrabat noru.', 'Zajistěte popelnice a nikdy nenechávejte venku škodlivé zbytky jídla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'cs', 'Ježek západní', 'Ježek urazí za jedinou noc hledání potravy pár kilometrů.', 'Od jara do podzimu po setmění; v zimě hibernuje pod hromadami listí a dřeva.', 'Vyřízněte v plotech otvor 13 cm, aby ježci mohli přecházet mezi zahradami.', 'Zkontrolujte vysokou trávu před sečením a nechte hromady listí pro hibernaci.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'cs', 'Srnec obecný', 'Srnci oddalují březost tak, aby se srnčata rodila vždy na začátku léta.', 'Celoročně na okrajích lesů, nejlépe viditelní při pastvě za svítání a soumraku.', 'Podpořte neposečené okraje polí a křoviny, které dávají krytí a potravu.', 'Vodte psy na vodítku u lesa začátkem léta, kdy srnčata leží ukrytá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'cs', 'Los evropský', 'Los je největší jelenovitý na Zemi; velký samec váží přes půl tuny.', 'Celoročně v lesích a mokřadech, nejaktivnější za svítání a soumraku.', 'Podpořte propojené lesy a mokřadní koridory, které los potřebuje k přesunům.', 'Jezděte opatrně za svítání a soumraku po lesních cestách a nikdy se nepřibližujte k mláděti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'cs', 'Veverka obecná', 'Veverka si staví několik hnízd a přesouvá se mezi nimi.', 'Celoročně v jehličnatých a smíšených lesích, nejčilejší brzy ráno.', 'Nechte šišky, oříšky a stojící stromy, z nichž se živí a v nichž hnízdí.', 'Držte psy na cestách a netřeste stromy, v nichž může být hnízdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'cs', 'Bobr evropský', 'Bobří hráze vytvářejí mokřady, které na kilometry prospívají rybám, ptákům i hmyzu.', 'Od jara do pozdního podzimu u pomalých řek, nejaktivnější za soumraku.', 'Podpořte ponechání bobřích hrází a pobřežních stromů tam, kde je to bezpečné.', 'Držte se dál od hradů a hrází, zvlášť když jsou mláďata malá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'cs', 'Zajíc bělák', 'Zajíc bělák v zimě zbělá, aby splynul se sněhem.', 'Celoročně na otevřených plochách a lesních pasekách, hlavně za svítání a soumraku.', 'Podpořte mozaiku otevřených ploch a krytu, kterou zajíc potřebuje po celý rok.', 'Vodte psy na vodítku na otevřených plochách, aby odpočívající zajíci nebyli honěni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'cs', 'Jezevec lesní', 'Jezevci žijí v rodinných skupinách v podzemních norách užívaných po generace.', 'Od jara do podzimu po setmění u lesa; zimu prospí.', 'Nechte nerušené svahy a meze, kde si jezevci mohou vyhrabat noru.', 'Nikdy nezasypávejte obývanou noru ani nekopejte poblíž — je to jejich dlouholetý domov.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'cs', 'Netopýr hvízdavý', 'Tento drobný netopýr sní za jedinou noc až 3 000 pakomárů a komárů.', 'Za letních večerů sledujte za soumraku rychlý, cukavý let nad zahradami.', 'Umístěte netopýří budku vysoko na zeď nebo strom, kam dosáhne večerní slunce.', 'Vyhněte se ostrému světlu u vchodů do úkrytů a nechte noční oblohu tmavou.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'cs', 'Babočka kopřivová', 'Tento motýl přezimuje jako dospělec, často v kůlnách a na půdách.', 'Od časného jara do podzimu na slunných květech, hlavně na kopřivách a motýlím keři.', 'Nechte v slunném koutě kus kopřiv — jeho housenky je potřebují.', 'Nerušte v zimě motýly přezimující v kůlnách.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'cs', 'Babočka paví oko', 'Oční skvrny se prudce otevřou, aby polekaly ptáky, a křídla přitom dokážou zasyčet.', 'Od jara do podzimu za slunných dnů na bodlácích, motýlím keři a spadaném ovoci.', 'Nechte na slunci vyrůst kus kopřiv pro housenky.', 'Nerušte dospělce, kteří přezimují v kůlnách a hromadách dřeva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'cs', 'Žluťásek řešetlákový', 'Anglické slovo „butterfly“ prý pochází z máslově žluté barvy samce tohoto druhu.', 'Jeden z prvních jarních motýlů; hledejte ho za mírných dnů podél okrajů lesa.', 'Podpořte krušiny a řešetláky v mezích, jediné rostliny, které jeho housenky žerou.', 'Vyhněte se vyčišťování křovinatých mezí, které chrání přezimující dospělce.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'cs', 'Bělásek řeřichový', 'Jen samci mají jasně oranžové špičky křídel; samice jsou bílé.', 'Na jaře podél vlhkých luk a cest, kde roste řeřišnice luční.', 'Nechte řeřišnici a česnáček růst ve vlhkých, neposečených koutech.', 'Odložte sečení krajnic, dokud housenky nedokončí žír.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'cs', 'Modrásek jehlicový', 'Housenky tohoto modráska někdy opatrují mravenci, které lákají jejich sladké výměšky.', 'Od pozdního jara na slunných trávnících bohatých na jetel a štírovník.', 'Nechte trávník neposečený, aby štírovníky a jetele mohly vykvést.', 'Nepostřikujte herbicidy travnaté plochy bohaté na polní květy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'cs', 'Bělásek řepkový', 'Ačkoli vypadá jako bělásek zelný, dává přednost planým rostlinám před zahradní zeleninou.', 'Od jara do konce léta na vlhkých loukách, ve stružkách a na lesních průsecích.', 'Nechte vlhké kouty zplanět s domácími brukvovitými, jako je řeřišnice.', 'Vyhněte se odvodňování a postřiku vlhkých luk, kde se rozmnožuje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'cs', 'Slunéčko sedmitečné', 'Jediné slunéčko za svůj život sežere tisíce mšic.', 'Od jara do podzimu na rostlinách se mšicemi; v zimě se shlukují k přezimování.', 'Snesete-li pár mšic a vynecháte postřiky, budou mít slunéčka co jíst.', 'Nechte duté stonky a listovou hrabanku, kde se přes zimu ukrývají.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'cs', 'Čmelák zemní', 'Královny patří k prvním včelám na jaře, bzučí nízko nad zemí a hledají hnízdní dutiny.', 'Od časného jara do podzimu na květech; na jaře královny prohledávají paty živých plotů.', 'Pěstujte nebo ponechte časně kvetoucí rostliny a nechte jetel kvést v trávníku.', 'Nechte nerušené svahy a staré myší nory, kde si kolonie zakládají hnízda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'cs', 'Včela medonosná', 'Létavky sdělují úlu, kde jsou květy, tancem ve tvaru osmičky.', 'Od jara do podzimu na květech, za teplých bezvětrných dnů.', 'Zajistěte, aby se přes sezony střídaly různé rozkvety, a postavte mělkou misku s vodou.', 'Nepostřikujte kvetoucí rostliny a nikdy ne uprostřed dne.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'cs', 'Šídlo královské', 'Jedna z největších vážek Evropy: kořist dokáže chytit i v letu.', 'Za teplých letních dnů ji sledujte, jak hlídkuje nad tůněmi a břehy jezer.', 'Zachovejte nebo vyhloubte tůň s rostlinami a nechte její okraje zarostlé.', 'Udržujte tůně bez znečištění a splachů, aby se larvy mohly vyvíjet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'cs', 'Vážka obecná', 'Tyto vážky často usedají na totéž teplé místo a vyrážejí po hmyzu, který kolem letí.', 'Od poloviny léta do podzimu u stojatých vod, vyhřívají se na cestách a kůlech.', 'Nechte slunná místa k usednutí a porost kolem tůní a struh.', 'Zabraňte splachu hnojiv či olejů do tůní, kde žijí larvy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'cs', 'Mravenec lesní', 'Jejich kupovitá mraveniště přesahují metr výšky a hostí půl milionu mravenců.', 'Od jara do podzimu v jehličnatých lesích; hledejte kupy z jehličí.', 'Nechte mraveniště nedotčená — jejich stavba trvá roky.', 'Držte se cest a nikdy do mraveniště nekopejte ani nezasahujte rýčem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'cs', 'Sasanka hajní', 'Sasanka se šíří tak pomalu, že husté koberce prozrazují starý les.', 'Na jaře hledejte koberce bílých květů dřív, než stromy vyraší listy.', 'Nechte lesní půdu nerušenou, aby se pomalé oddenky mohly rozrůstat.', 'Kochejte se jí tam, kde roste — trháním mizí květy, které se šířily roky.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'cs', 'Konvalinka vonná', 'Každá část této sladce vonící rostliny je při požití jedovatá.', 'Pozdě na jaře jděte po vůni do stinných lesů a zastíněných zahrad.', 'Nechte na místě stinné okraje lesa a listovou hrabanku, kde roste.', 'Netrhejte ji ani ji nevykopávejte a držte ji mimo dosah dětí a domácích zvířat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'cs', 'Česnek medvědí', 'Medvědí česnek obvykle ucítíte dávno předtím, než uvidíte jeho bílé květy.', 'Na jaře hledejte široké zelené listy a hvězdicovité květy ve vlhkých lesích.', 'Nechte vlhké lesy nerušené, aby koberce mohly každý rok znovu narůst.', 'Je-li sběr místně povolen, vezměte si málo a nikdy nevytrhávejte cibule.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'cs', 'Blatouch bahenní', 'Jedna z nejstarších domácích rostlin: ve Skandinávii přežila poslední dobu ledovou.', 'Na jaře hledejte velké zlaté květy v mokřinách, příkopech a u břehů tůní.', 'Udržujte okraje tůní a příkopů vlhké a neposečené, aby mohla kvést.', 'Vyhněte se odvodňování mokré půdy a nechte rostliny tam, kde rostou.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'cs', 'Prvosenka jarní', 'Prvosenka bývala na senných loukách tak hojná, že z ní děti dělaly kuličky.', 'Na jaře hledejte převislé žluté květy na starých, nehnojených loukách.', 'Nechte louky neposečené, dokud prvosenka nevykvete a nenasadí semena.', 'Netrhejte ji ani ji nevykopávejte z volné přírody — lučních květů ubývá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'cs', 'Kopretina bílá', '„Květ“ kopretiny jsou ve skutečnosti desítky drobných kvítků pohromadě.', 'V létě hledejte velké bílé kopretiny podél cest a na loukách.', 'Nechte pruh trávy neposečený přes vrchol léta, aby mohla vykvést.', 'Nepostřikujte krajnice a louky herbicidy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'cs', 'Pampeliška lékařská', 'Pampeliška je jedním z nejdůležitějších časných zdrojů nektaru pro včely.', 'Od jara skoro všude; květy se otevírají na slunci a za soumraku se zavírají.', 'Nechte pampelišky na jaře v trávníku vykvést před první sečí.', 'Vynechejte trávníkové herbicidy, aby si časní opylovači tuto potravu udrželi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'cs', 'Vřes obecný', 'Jediná rostlina vřesu může vytvořit přes sto tisíc drobných semen.', 'Koncem léta hledejte fialové koberce na otevřených vřesovištích a rašeliništích.', 'Podpořte udržování vřesovišť otevřených a bez odvodnění.', 'Držte se na vřesovištích cest a za sucha nikdy nerozdělávejte oheň.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'cs', 'Borůvka černá', 'Borůvky barví prsty do modra a živí kdekoho, od ptáků po medvědy.', 'V létě hledejte nízké keříky s tmavými plody v borových a smrkových lesích.', 'Nechte lesní podrost nedotčený, aby nízké keříky mohly plodit.', 'Je-li sběr místně povolen, nechte hodně plodů zvěři.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'cs', 'Brusinka obecná', 'Brusinky vydrží měsíce díky přírodní konzervační látce v plodu.', 'Koncem léta a na podzim hledejte lesklé červené plody na stálezelených kobercích.', 'Nechte porost lesní půdy nerušený, aby se koberce mohly šířit.', 'Je-li sběr místně povolen, šlapejte opatrně, ať rostliny nerozdrtíte.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'cs', 'Bříza bělokorá', 'Bříza živí stovky druhů hmyzu a tím i nespočet ptáků.', 'Celoročně; bílá loupající se kůra ji činí poznatelnou v každém ročním období.', 'Nechte spadané listí a mrtvé dřevo ležet: obohacují půdu a živí hmyz.', 'Neodlupujte kůru, poraníte a oslabíte tím strom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'cs', 'Smrk ztepilý', 'Ve Švédsku roste smrk z kořenů starých tisíce let.', 'Celoročně v lesích; jeho převislé šišky jsou nejdelší ze všech smrků.', 'Nechte spadané šišky a mrtvé dřevo ležet, hostí hmyz i houby.', 'Držte se v lese cest, ať neudusáte mělké smrkové kořeny.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'cs', 'Borovice lesní', 'Staré borovice lesní září u vrcholu oranžově a mohou žít staletí.', 'Celoročně na písčité a skalnaté půdě; hledejte oranžovou kůru v horní části kmene.', 'Nechte stát mrtvé dřevo a staré borovice, které jsou plné života.', 'Nikdy nerozdělávejte oheň o borovice opřený ani poblíž nich na suché písčité půdě.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'cs', 'Štika obecná', 'Štika je číhavý dravec, který dokáže vyrazit z nehybnosti během okamžiku.', 'Od jara do podzimu v zarostlých mělčinách jezer a pomalých řek.', 'Podpořte zachování rákosových mělčin a vodních rostlin, kde se ukrývá plůdek.', 'Držte znečištění a odpadky mimo vodu; dodržujte místní rybářská pravidla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'cs', 'Okoun říční', 'Okouni loví v houfech a jejich výrazné pruhy rozbíjejí obrys těla.', 'V teplejších měsících kolem mol, porostů vodních rostlin a hran do hloubky.', 'Podpořte čistou vodu a ponořené struktury, které chrání drobné ryby.', 'Nikdy nic nevylévejte do jezer a řek; dodržujte místní rybářská pravidla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'cs', 'Plotice obecná', 'Plotice je klíčovou kořistní rybou, na níž závisí mnoho jezerních dravců.', 'V teplejších měsících v hejnech blízko hladiny jezer a pomalých řek.', 'Podpořte čistou vodu a zarostlé břehy potřebné k tření.', 'Držte splachy a odpadky mimo vodu; dodržujte místní rybářská pravidla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'sk', 'Dážďovník tmavý', 'Dážďovníky dokážu zostať vo vzduchu celé mesiace a spia dokonca počas letu.', 'Za teplých letných večerov sa pozrite vysoko nad strechy a započúvajte sa do kričiacich kŕdľov.', 'Osaďte búdku pod odkvap skôr, než sa vtáky na jar vrátia.', 'Pri rekonštrukcii zachovajte drobné škáry pod odkvapom, kde hniezdia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'sk', 'Lastovička domová', 'Lastovičky každý rok tiahnu až do južnej Afriky a späť.', 'Od jari do skorej jesene ich uvidíte, ako nízko brázdia polia a vodné hladiny.', 'Nechajte pootvorené vráta stodoly alebo kôlne, aby sa dostali k svojim hniezdam.', 'Nezhadzujte staré hlinené hniezda — lastovičky ich používajú rok čo rok.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'sk', 'Kukučka jarabá', 'Kukučka kladie vajcia do hniezd iných vtákov a nikdy nevychováva vlastné mláďatá.', 'Neskoro na jar počúvajte ďaleko nesúce sa „ku-ku“ od okrajov lesa.', 'Podporte lúky a medze bohaté na hmyz, ktoré živia hostiteľské vtáky kukučky.', 'Držte sa chodníkov pri krovinách a trstinách, aby hostiteľské vtáky neboli rušené.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'sk', 'Červienka obyčajná', 'Červienka urputne bráni svoje územie a pri pouličných lampách spieva aj v noci.', 'Celoročne v záhradách a lesoch; rada sleduje toho, kto ryje, v nádeji na dážďovky.', 'Nechajte v rohu záhrady vrstvu opadaného lístia, kde môže hľadať potravu.', 'Odložte silný rez živých plotov, kým koncom leta neskončí hniezdenie.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'sk', 'Drozd čierny', 'Sýty, flautový spev samca patrí k najznámejším v Európe.', 'Celoročne; za svitania a súmraku počúvajte samcov spievajúcich zo striech a korún stromov.', 'Vystavte čerstvú vodu na pitie a kúpanie, najmä v suchých obdobiach.', 'Nechajte mačky za úsvitu doma počas hniezdenia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'sk', 'Drozd čvíkota', 'Čvíkota je spoločenský drozd, ktorý sa v zime potuluje v hlučných, štebotavých kŕdľoch.', 'Na jeseň a v zime sledujte kŕdle, ako oberajú bobule zo živých plotov a jarabín.', 'Nechajte cez zimu nestrihané bobuľové kríky, ako je jarabina a hloh.', 'Nechajte v zime opadané jablká ležať — v mrazoch sú životne dôležitou potravou.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'sk', 'Sýkorka veľká', 'Sýkorka veľká má obrovský hlasový repertoár a nové hlasy sa učí od susedov.', 'Celoročne; od konca zimy počúvajte zvonivý spev z dvoch opakovaných tónov.', 'Zaveste búdku s otvorom 32 mm na pokojné, tienisté miesto.', 'Vyhnite sa pesticídom v záhrade, aby húseníc stačilo na nakŕmenie mláďat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'sk', 'Sýkorka belasá', 'Jediná znáška sýkorky belasej dokáže spotrebovať vyše tisíc húseníc.', 'Celoročne v záhradách a lesoch, často visiaca hlavou nadol na tenkých vetvičkách.', 'Osaďte malú búdku s otvorom 25 mm mimo dosahu prevládajúceho vetra.', 'Vynechajte na jar insekticídy, aby húsenice zostali mláďatám.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'sk', 'Pinka lesná', 'Spev pinky sa líši kraj od kraja, takmer ako miestne nárečia.', 'Od jari do jesene; samce spievajú jasnú, klesajúcu frázu z odkrytých vetiev.', 'Nechajte cez sezónu stáť pár odkvitnutých semenných metlín a burinových kútov.', 'Udržujte kŕmidlá čisté, aby sa medzi pinkami nešírili choroby.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'sk', 'Sojka škriekavá', 'Sojka každú jeseň zakope tisíce žaluďov a tým, že na niektoré zabudne, vysadí celé dubiny.', 'Celoročne v dubinách; na jeseň vyhliadajte záblesky ružovej a modrej.', 'Nechajte pod dubmi nedotknuté opadané žalude a lístie.', 'Držte psov na lesných chodníkoch, aby vtáky hľadajúce potravu na zemi neboli plašené.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'sk', 'Ďateľ veľký', 'Jarné „bubnovanie“ nie je hľadanie potravy, ale rýchly vír, ktorým si nárokuje územie.', 'Celoročne; na konci zimy počúvajte bubnovanie rozliehajúce sa lesom.', 'Nechajte stáť mŕtve drevo, ktoré hostí hmyz, ktorým sa ďateľ živí.', 'Nerúbte mŕtve alebo odumierajúce stromy, v ktorých môžu byť hniezdne dutiny.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'sk', 'Trasochvost biely', 'Neustále kývanie chvostom možno signalizuje ostražitosť voči predátorom.', 'Od jari do jesene pri vode a na holej pôde, behá a zastavuje sa, aby chytil hmyz.', 'Udržujte pri vode pás nízkej trávy alebo štrku, kde môže hľadať potravu.', 'Nerušte štrkové nánosy a brehy, kde sa živí a hniezdi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'sk', 'Žeriav popolavý', 'Žeriavy predvádzajú zavčas na jar zásnubné tance plné skokov a úklonov.', 'Od jari do jesene pri mokradiach; ich trúbenie sa nesie na kilometre ďaleko.', 'Podporte ochranu neodvodnených rašelinísk a mokrých lúk, kde žeriavy hniezdia.', 'Pozorujte hniezdne mokrade z diaľky — žeriavy rušené hniezda opúšťajú.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'sk', 'Labuť spevavá', 'Labuť spevavá sa párí na celý život a svoj prílet ohlasuje hlasným trúbením.', 'Na jar a na jeseň na jazerách a zaplavených poliach, často v rodinných skupinách.', 'Podporte zachovanie plytkých brehov a mokrých polí bez odvodnenia.', 'Nikdy nekŕmte labute chlebom — škodí im; na ľade si držte odstup.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'sk', 'Kačica divá', 'Káčatá plávajú a živia sa samy už pár hodín po vyliahnutí.', 'Celoročne takmer na každom rybníku, jazere alebo pomalej rieke.', 'Ak kačice kŕmite, použite ovos, hrach alebo semienka namiesto chleba.', 'Na jar nepúšťajte psov do vody tam, kde kačice hniezdia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'sk', 'Myšiak hôrny', 'Myšiak plachtí na širokých krídlach a často volá mačacím „píííjau“.', 'Od jari do jesene; hľadajte ho, ako krúži vysoko nad poľami a okrajmi lesov.', 'Podporte nepokosené trávnaté plochy a okraje polí, kde žijú hraboše a drobná korisť.', 'Nikdy nepoužívajte jedy na hlodavce: stúpajú potravinovým reťazcom až k dravcom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'sk', 'Kršiak rybár', 'Kršiak sa vrhá do vody nohami napred a unesie korisť s polovicou vlastnej hmotnosti.', 'Od jari do jesene pri veľkých jazerách; vyhliadajte trepotavý let a potom strmý pád.', 'Podporte umelé hniezdne plošiny na vysokých stĺpoch pri jazerách bohatých na ryby.', 'Vyhnite sa hniezdnym plošinám veľkým oblúkom, aby páry neopustili vajcia.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'sk', 'Líška hrdzavá', 'Líška si pri skoku na skrytú korisť pomáha magnetickým poľom Zeme.', 'Celoročne, najaktívnejšia za svitania a súmraku pozdĺž okrajov lesov a polí.', 'Nechajte divoký, nerušený kút, kde môžu líšky odpočívať a hrabať noru.', 'Zabezpečte smetné nádoby a nikdy nenechávajte vonku škodlivé zvyšky jedla.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'sk', 'Jež západný', 'Jež prejde za jedinú noc hľadania potravy pár kilometrov.', 'Od jari do jesene po zotmení; v zime hibernuje pod kopami lístia a dreva.', 'Vyrežte v plotoch otvor 13 cm, aby ježe mohli prechádzať medzi záhradami.', 'Skontrolujte vysokú trávu pred kosením a nechajte kopy lístia na hibernáciu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'sk', 'Srnec lesný', 'Srnce odďaľujú brezivosť tak, aby sa srnčatá rodili vždy na začiatku leta.', 'Celoročne na okrajoch lesov, najlepšie viditeľné pri pastve za svitania a súmraku.', 'Podporte nepokosené okraje polí a kroviny, ktoré dávajú kryt a potravu.', 'Voďte psov na vôdzke pri lese začiatkom leta, keď srnčatá ležia ukryté.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'sk', 'Los mokraďový', 'Los je najväčší jeleňovitý na Zemi; veľký samec váži vyše pol tony.', 'Celoročne v lesoch a mokradiach, najaktívnejší za svitania a súmraku.', 'Podporte prepojené lesy a mokraďové koridory, ktoré los potrebuje na presuny.', 'Jazdite opatrne za svitania a súmraku po lesných cestách a nikdy sa nepribližujte k mláďaťu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'sk', 'Veverica stromová', 'Veverica si stavia niekoľko hniezd a presúva sa medzi nimi.', 'Celoročne v ihličnatých a zmiešaných lesoch, najčulejšia zavčas ráno.', 'Nechajte šišky, orechy a stojace stromy, z ktorých sa živí a v ktorých hniezdi.', 'Držte psov na chodníkoch a netraste stromami, v ktorých môže byť hniezdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'sk', 'Bobor vodný', 'Bobrie hrádze vytvárajú mokrade, ktoré na kilometre prospievajú rybám, vtákom aj hmyzu.', 'Od jari do neskorej jesene pri pomalých riekach, najaktívnejší za súmraku.', 'Podporte ponechanie bobrích hrádzí a pobrežných stromov tam, kde je to bezpečné.', 'Držte sa ďalej od hradov a hrádzí, najmä keď sú mláďatá malé.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'sk', 'Zajac belák', 'Zajac belák v zime zbelie, aby splynul so snehom.', 'Celoročne na otvorených plochách a lesných rúbaniskách, hlavne za svitania a súmraku.', 'Podporte mozaiku otvorených plôch a krytu, ktorú zajac potrebuje po celý rok.', 'Voďte psov na vôdzke na otvorených plochách, aby odpočívajúce zajace neboli honené.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'sk', 'Jazvec lesný', 'Jazvece žijú v rodinných skupinách v podzemných norách používaných po generácie.', 'Od jari do jesene po zotmení pri lese; zimu prespia.', 'Nechajte nerušené svahy a medze, kde si jazvece môžu vyhrabať noru.', 'Nikdy nezasypávajte obývanú noru ani nekopte v jej blízkosti — je to ich dlhoročný domov.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'sk', 'Netopier hvízdavý', 'Tento drobný netopier zje za jedinú noc až 3 000 pakomárov a komárov.', 'Za letných večerov sledujte za súmraku rýchly, trhaný let nad záhradami.', 'Osaďte netopierí príbytok vysoko na stenu alebo strom, kam dosiahne večerné slnko.', 'Vyhnite sa ostrému svetlu pri vchodoch do úkrytov a nechajte nočnú oblohu tmavú.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'sk', 'Babôčka pŕhľavová', 'Tento motýľ prezimuje ako dospelec, často v kôlňach a na povalách.', 'Od skorej jari do jesene na slnečných kvetoch, hlavne na pŕhľave a motýlom kríku.', 'Nechajte v slnečnom kúte kus pŕhľavy — jeho húsenice ju potrebujú.', 'Nerušte v zime motýle prezimujúce v kôlňach.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'sk', 'Babôčka pávooká', 'Očné škvrny sa prudko otvoria, aby zľakli vtáky, a krídla pritom dokážu zasyčať.', 'Od jari do jesene za slnečných dní na bodliakoch, motýlom kríku a opadanom ovocí.', 'Nechajte na slnku vyrásť kus pŕhľavy pre húsenice.', 'Nerušte dospelce, ktoré prezimujú v kôlňach a hromadách dreva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'sk', 'Žltáčik rešetliakový', 'Anglické slovo „butterfly“ vraj pochádza z maslovo žltej farby samca tohto druhu.', 'Jeden z prvých jarných motýľov; hľadajte ho za miernych dní pozdĺž okrajov lesa.', 'Podporte krušiny a rešetliaky v medziach, jediné rastliny, ktoré jeho húsenice žerú.', 'Vyhnite sa vyčisťovaniu krovinatých medzí, ktoré chránia prezimujúce dospelce.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'sk', 'Mlynárik žeruchový', 'Len samce majú jasne oranžové špičky krídel; samice sú biele.', 'Na jar pozdĺž vlhkých lúk a ciest, kde rastie žerucha lúčna.', 'Nechajte žeruchu a cesnačku rásť vo vlhkých, nekosených kútoch.', 'Odložte kosenie krajníc, kým húsenice nedokončia žer.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'sk', 'Modráčik obyčajný', 'Húsenice tohto modráčika niekedy opatrujú mravce, ktoré lákajú ich sladké výlučky.', 'Od neskorej jari na slnečných trávnikoch bohatých na ďatelinu a ľadenec.', 'Nechajte trávnik nepokosený, aby ľadence a ďateliny mohli zakvitnúť.', 'Nepostrekujte herbicídmi trávnaté plochy bohaté na poľné kvety.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'sk', 'Mlynárik repkový', 'Hoci vyzerá ako mlynárik kapustový, uprednostňuje plané rastliny pred záhradnou zeleninou.', 'Od jari do konca leta na vlhkých lúkach, v priekopách a na lesných priesekoch.', 'Nechajte vlhké kúty splanieť s domácimi kapustovitými, ako je žerucha.', 'Vyhnite sa odvodňovaniu a postreku vlhkých lúk, kde sa rozmnožuje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'sk', 'Lienka sedembodková', 'Jediná lienka zožerie za svoj život tisíce vošiek.', 'Od jari do jesene na rastlinách s vošticami; v zime sa zhlukujú na prezimovanie.', 'Ak znesiete pár vošiek a vynecháte postreky, budú mať lienky čo jesť.', 'Nechajte duté stonky a lístie, kde sa cez zimu ukrývajú.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'sk', 'Čmeľ zemný', 'Kráľovné patria k prvým včelám na jar, bzučia nízko nad zemou a hľadajú hniezdne dutiny.', 'Od skorej jari do jesene na kvetoch; na jar kráľovné prehľadávajú päty živých plotov.', 'Pestujte alebo ponechajte skoro kvitnúce rastliny a nechajte ďatelinu kvitnúť v trávniku.', 'Nechajte nerušené svahy a staré myšie diery, kde si kolónie zakladajú hniezda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'sk', 'Včela medonosná', 'Lietavky oznamujú úľu, kde sú kvety, tancom v tvare osmičky.', 'Od jari do jesene na kvetoch, za teplých bezveterných dní.', 'Zabezpečte, aby sa cez sezóny striedali rôzne rozkvety, a postavte plytkú misku s vodou.', 'Nepostrekujte kvitnúce rastliny a nikdy nie uprostred dňa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'sk', 'Šidlo kráľovské', 'Jedna z najväčších vážok Európy: korisť dokáže chytiť aj za letu.', 'Za teplých letných dní ju sledujte, ako hliadkuje nad tôňami a brehmi jazier.', 'Zachovajte alebo vyhĺbte tôňu s rastlinami a nechajte jej okraje zarastené.', 'Udržujte tône bez znečistenia a splachov, aby sa larvy mohli vyvíjať.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'sk', 'Vážka obyčajná', 'Tieto vážky často sadajú na to isté teplé miesto a vyrážajú po hmyze, ktorý letí okolo.', 'Od polovice leta do jesene pri stojatých vodách, vyhrievajú sa na chodníkoch a koloch.', 'Nechajte slnečné miesta na sadanie a porast okolo tôní a priekop.', 'Zabráňte splachu hnojív či olejov do tôní, kde žijú larvy.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'sk', 'Mravec lesný', 'Ich kopovité mraveniská presahujú meter výšky a hostia pol milióna mravcov.', 'Od jari do jesene v ihličnatých lesoch; hľadajte kopy z ihličia.', 'Nechajte mraveniská nedotknuté — ich stavba trvá roky.', 'Držte sa chodníkov a nikdy do mraveniska nekopte ani doň nezasahujte rýľom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'sk', 'Veternica hájna', 'Veternica sa šíri tak pomaly, že husté koberce prezrádzajú starý les.', 'Na jar hľadajte koberce bielych kvetov skôr, než stromy vyženú lístie.', 'Nechajte lesnú pôdu nerušenú, aby sa pomalé podzemky mohli rozrastať.', 'Kochajte sa ňou tam, kde rastie — trhaním miznú kvety, ktoré sa šírili roky.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'sk', 'Konvalinka voňavá', 'Každá časť tejto sladko voňajúcej rastliny je pri požití jedovatá.', 'Neskoro na jar choďte za vôňou do tienistých lesov a zatienených záhrad.', 'Nechajte na mieste tienisté okraje lesa a lístie, kde rastie.', 'Netrhajte ju ani ju nevykopávajte a držte ju mimo dosahu detí a domácich zvierat.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'sk', 'Cesnak medvedí', 'Medvedí cesnak zvyčajne zacítite dávno predtým, než uvidíte jeho biele kvety.', 'Na jar hľadajte široké zelené listy a hviezdicovité kvety vo vlhkých lesoch.', 'Nechajte vlhké lesy nerušené, aby koberce mohli každý rok znovu narásť.', 'Ak je zber miestne povolený, vezmite si málo a nikdy nevytrhávajte cibule.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'sk', 'Záružlie močiarne', 'Jedna z najstarších domácich rastlín: v Škandinávii prežila poslednú dobu ľadovú.', 'Na jar hľadajte veľké zlaté kvety v močariskách, priekopách a pri brehoch tôní.', 'Udržujte okraje tôní a priekop vlhké a nekosené, aby mohla kvitnúť.', 'Vyhnite sa odvodňovaniu mokrej pôdy a nechajte rastliny tam, kde rastú.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'sk', 'Prvosienka jarná', 'Prvosienka bývala na senných lúkach taká hojná, že z nej deti robili guľky.', 'Na jar hľadajte ovisnuté žlté kvety na starých, nehnojených lúkach.', 'Nechajte lúky nekosené, kým prvosienka nezakvitne a nenasadí semená.', 'Netrhajte ju ani ju nevykopávajte z voľnej prírody — lúčnych kvetov ubúda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'sk', 'Margaréta biela', '„Kvet“ margaréty sú v skutočnosti desiatky drobných kvietkov pokope.', 'V lete hľadajte veľké biele margaréty pozdĺž ciest a na lúkach.', 'Nechajte pás trávy nekosený cez vrchol leta, aby mohla zakvitnúť.', 'Nepostrekujte krajnice a lúky herbicídmi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'sk', 'Púpava lekárska', 'Púpava je jedným z najdôležitejších skorých zdrojov nektáru pre včely.', 'Od jari takmer všade; kvety sa otvárajú na slnku a za súmraku sa zatvárajú.', 'Nechajte púpavy na jar v trávniku zakvitnúť pred prvým kosením.', 'Vynechajte trávnikové herbicídy, aby si skorí opeľovači túto potravu udržali.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'sk', 'Vres obyčajný', 'Jediná rastlina vresu môže vytvoriť vyše sto tisíc drobných semien.', 'Koncom leta hľadajte fialové koberce na otvorených vresoviskách a rašeliniskách.', 'Podporte udržiavanie vresovísk otvorených a bez odvodnenia.', 'Držte sa na vresoviskách chodníkov a za sucha nikdy nezakladajte oheň.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'sk', 'Čučoriedka obyčajná', 'Čučoriedky farbia prsty domodra a živia kadekoho, od vtákov po medvede.', 'V lete hľadajte nízke kríčky s tmavými plodmi v borovicových a smrekových lesoch.', 'Nechajte lesný podrast nedotknutý, aby nízke kríčky mohli plodiť.', 'Ak je zber miestne povolený, nechajte veľa plodov zveri.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'sk', 'Brusnica obyčajná', 'Brusnice vydržia mesiace vďaka prírodnej konzervačnej látke v plode.', 'Koncom leta a na jeseň hľadajte lesklé červené plody na stálezelených kobercoch.', 'Nechajte porast lesnej pôdy nerušený, aby sa koberce mohli šíriť.', 'Ak je zber miestne povolený, stúpajte opatrne, nech rastliny nerozdrvíte.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'sk', 'Breza previsnutá', 'Breza živí stovky druhov hmyzu a tým aj nespočet vtákov.', 'Celoročne; biela odlupujúca sa kôra ju robí rozpoznateľnou v každom ročnom období.', 'Nechajte opadané lístie a mŕtve drevo ležať: obohacujú pôdu a živia hmyz.', 'Neodlupujte kôru, poraníte a oslabíte tým strom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'sk', 'Smrek obyčajný', 'Vo Švédsku rastie smrek z koreňov starých tisíce rokov.', 'Celoročne v lesoch; jeho ovisnuté šišky sú najdlhšie zo všetkých smrekov.', 'Nechajte opadané šišky a mŕtve drevo ležať, hostia hmyz aj huby.', 'Držte sa v lese chodníkov, nech neudupete plytké smrekové korene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'sk', 'Borovica lesná', 'Staré borovice lesné žiaria pri vrchole oranžovo a môžu žiť stáročia.', 'Celoročne na piesočnatej a skalnatej pôde; hľadajte oranžovú kôru v hornej časti kmeňa.', 'Nechajte stáť mŕtve drevo a staré borovice, ktoré sú plné života.', 'Nikdy nezakladajte oheň opretý o borovice ani v ich blízkosti na suchej piesočnatej pôde.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'sk', 'Šťuka severná', 'Šťuka je číhajúci dravec, ktorý dokáže vyraziť z nehybnosti v okamihu.', 'Od jari do jesene v zarastených plytčinách jazier a pomalých riek.', 'Podporte zachovanie trstinových plytčín a vodných rastlín, kde sa ukrýva plôdik.', 'Držte znečistenie a odpadky mimo vody; dodržiavajte miestne rybárske pravidlá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'sk', 'Ostriež zelenkavý', 'Ostrieže lovia v húfoch a ich výrazné pruhy rozbíjajú obrys tela.', 'V teplejších mesiacoch okolo mól, porastov vodných rastlín a hrán do hĺbky.', 'Podporte čistú vodu a ponorené štruktúry, ktoré chránia drobné ryby.', 'Nikdy nič nevylievajte do jazier a riek; dodržiavajte miestne rybárske pravidlá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'sk', 'Plotica červenooká', 'Plotica je kľúčovou koristnou rybou, od ktorej závisí mnoho jazerných dravcov.', 'V teplejších mesiacoch v kŕdľoch blízko hladiny jazier a pomalých riek.', 'Podporte čistú vodu a zarastené brehy potrebné na neresenie.', 'Držte splachy a odpadky mimo vody; dodržiavajte miestne rybárske pravidlá.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'bg', 'Черен бързолет', 'Бързолетите могат да останат във въздуха с месеци и дори спят в полет.', 'В топлите летни вечери гледайте високо над покривите и се вслушайте в крещящите ята.', 'Поставете къщичка под стрехата, преди птиците да се върнат напролет.', 'При ремонт запазете малките процепи под стрехата, където гнездят.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'bg', 'Селска лястовица', 'Селските лястовици прелитат всяка година чак до Южна Африка и обратно.', 'От пролетта до ранната есен ги виждате да се стрелкат ниско над ниви и води.', 'Оставете вратата на плевня или навес открехната, за да стигат до гнездата си.', 'Не събаряйте старите кални гнезда — лястовиците ги ползват година след година.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'bg', 'Кукувица', 'Кукувицата снася яйцата си в чужди гнезда и никога не отглежда собствени малки.', 'В късна пролет се вслушайте в далечното „ку-ку“ откъм горските краища.', 'Подкрепете ливади и живи плетове, богати на насекоми, които хранят птиците гостоприемници.', 'Придържайте се към пътеките край храсталаци и тръстики, за да не тревожите гостоприемниците.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'bg', 'Червеногръдка', 'Червеногръдката яростно брани територията си и пее нощем край уличните лампи.', 'Целогодишно в градини и гори; често следва копаещия с надежда за червеи.', 'Оставете ъгъл от градината с окапали листа, където да търси храна.', 'Отложете силното подрязване на живия плет, докато гнезденето не приключи в края на лятото.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'bg', 'Кос', 'Плътната, флейтова песен на мъжкия е сред най-разпознаваемите в Европа.', 'Целогодишно; на зазоряване и по здрач се вслушайте в мъжките, пеещи от покриви и корони.', 'Оставяйте прясна вода за пиене и къпане, особено в сухи периоди.', 'Дръжте котките вкъщи призори през гнездовия сезон.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'bg', 'Хвойнов дрозд', 'Хвойновият дрозд е общителен и се скита през зимата в шумни, бъбриви ята.', 'През есента и зимата гледайте как ятата обират плодовете от плетове и офики.', 'Оставете храстите с плодове, като офика и глог, неподрязани през зимата.', 'Оставете падналите ябълки на земята през зимата — при студ са жизненоважна храна.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'bg', 'Голям синигер', 'Големият синигер има огромен репертоар и учи нови повиквания от съседите си.', 'Целогодишно; от края на зимата се вслушайте в звънката песен от два повтарящи се тона.', 'Закачете къщичка с отвор 32 мм на тихо, сенчесто място.', 'Избягвайте пестициди в градината, за да стигат гъсениците за изхранване на малките.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'bg', 'Син синигер', 'Едно люпило сини синигери може да изяде над хиляда гъсеници.', 'Целогодишно в градини и гори, често увиснал с главата надолу по тънки клонки.', 'Поставете малка къщичка с отвор 25 мм, защитена от преобладаващия вятър.', 'Пропуснете инсектицидите напролет, за да останат гъсениците за малките.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'bg', 'Обикновена чинка', 'Песента на чинката се различава по краища, почти като местни говори.', 'От пролетта до есента; мъжките пеят ясна, низходяща фраза от открити клони.', 'Оставете през сезона някои растения със семена и обрасли кътчета непокосени.', 'Поддържайте хранилките чисти, за да не се разпространяват болести сред чинките.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'bg', 'Сойка', 'Сойката заравя хиляди жълъди всяка есен и като забрави част от тях, засажда цели дъбрави.', 'Целогодишно в дъбрави; наесен търсете проблясъците на розово и синьо.', 'Оставете падналите жълъди и листната постилка под дъбовете недокоснати.', 'Дръжте кучетата по горските пътеки, за да не подплашват птиците, хранещи се на земята.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'bg', 'Голям пъстър кълвач', 'Пролетното „барабанене“ не е хранене, а бърза дроб, с която обявява територията си.', 'Целогодишно; в края на зимата се вслушайте в барабаненето, което кънти из гората.', 'Оставете мъртвата дървесина права — в нея живеят насекомите, с които се храни.', 'Не отсичайте мъртви или умиращи дървета, в които може да има гнездови хралупи.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'bg', 'Бяла стърчиопашка', 'Постоянното поклащане на опашката вероятно сигнализира бдителност към хищниците.', 'От пролетта до есента край вода и открита почва — тича и спира, за да улови насекоми.', 'Поддържайте край водата ивица ниска трева или чакъл, където да търси храна.', 'Избягвайте да безпокоите чакълестите брегове, където се храни и гнезди.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'bg', 'Сив жерав', 'Жеравите изпълняват в ранна пролет брачни танци със скокове и поклони.', 'От пролетта до есента около влажни зони; тръбният им зов се чува на километри.', 'Подкрепете опазването на неотводнени торфища и влажни ливади, където жеравите гнездят.', 'Наблюдавайте гнездовите места отдалеч — жеравите изоставят обезпокоените гнезда.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'bg', 'Поен лебед', 'Поеният лебед се сдвоява за цял живот и известява пристигането си със силни тръбни викове.', 'Напролет и наесен по езера и наводнени полета, често в семейни групи.', 'Подкрепете запазването на плитките брегове и влажните полета без отводняване.', 'Никога не хранете лебеди с хляб — вреди им; на леда пазете дистанция.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'bg', 'Зеленоглава патица', 'Патетата плуват и се хранят сами броени часове след излюпването.', 'Целогодишно на почти всяко езерце, езеро или бавна река.', 'Ако храните патици, използвайте овес, грах или семена вместо хляб.', 'Напролет дръжте кучетата извън водата там, където патиците гнездят.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'bg', 'Обикновен мишелов', 'Мишеловът се рее на широки криле и често вика с провлачено, котешко „пииии-яу“.', 'От пролетта до есента; търсете го да кръжи високо над ниви и горски краища.', 'Подкрепете некосените тревни площи и синорите, в които живеят полевки и дребна плячка.', 'Никога не използвайте отрови за гризачи: те се качват по хранителната верига до грабливите птици.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'bg', 'Орел рибар', 'Орелът рибар се спуска с краката напред и носи плячка с половината от собственото си тегло.', 'От пролетта до есента край големи езера; следете зависването и после ефектното спускане.', 'Подкрепете изкуствените гнездови платформи на високи стълбове край богати на риба езера.', 'Заобикаляйте платформите отдалеч, за да не подплашите двойките от яйцата.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'bg', 'Червена лисица', 'Лисицата си помага с магнитното поле на Земята, когато преценява скока към скрита плячка.', 'Целогодишно, най-активна призори и по здрач покрай горските и полските краища.', 'Оставете див, необезпокояван ъгъл, където лисиците да почиват и да копаят дупка.', 'Затваряйте кофите и никога не оставяйте вредни остатъци от храна навън.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'bg', 'Западен таралеж', 'Таралежът може да измине няколко километра в една-единствена нощ на търсене на храна.', 'От пролетта до есента след мръкване; зимата спи под купчини листа и дърва.', 'Направете отвор от 13 см в оградите, за да минават таралежите между градините.', 'Проверявайте високата трева преди косене и оставяйте купчини листа за зимния сън.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'bg', 'Сърна', 'Сърните забавят бременността си, за да се раждат сърнетата винаги в началото на лятото.', 'Целогодишно по горските краища, най-често се виждат да пасат призори и по здрач.', 'Подкрепете некосените синори и храсталаци, които им дават укритие и храна.', 'Дръжте кучетата на каишка край гората в началото на лятото, когато сърнетата лежат скрити.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'bg', 'Лос', 'Лосът е най-едрият елен на Земята; голям самец тежи над половин тон.', 'Целогодишно в гори и влажни зони, най-активен призори и по здрач.', 'Подкрепете свързаните гори и влажните коридори, от които лосът се нуждае, за да се придвижва.', 'Карайте внимателно призори и по здрач по горските пътища и никога не приближавайте малко.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'bg', 'Червена катерица', 'Червената катерица си прави няколко гнезда и се мести между тях.', 'Целогодишно в иглолистни и смесени гори, най-дейна рано сутрин.', 'Оставете шишарки, ядки и стоящи дървета, от които се храни и в които гнезди.', 'Дръжте кучетата по пътеките и не разтърсвайте дървета, в които може да има гнездо.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'bg', 'Европейски бобър', 'Бобровите бентове създават влажни зони, които на километри помагат на риби, птици и насекоми.', 'От пролетта до късна есен край бавни реки, най-активен по здрач.', 'Подкрепете оставянето на бобровите бентове и крайбрежните дървета там, където е безопасно.', 'Стойте далеч от бобровите къщи и бентовете, особено докато малките са дребни.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'bg', 'Планински заек', 'Планинският заек побелява през зимата, за да се слее със снега.', 'Целогодишно на открити места и горски сечища, главно призори и по здрач.', 'Подкрепете мозайката от открити площи и укритие, от която заекът се нуждае целогодишно.', 'Дръжте кучетата на каишка на открито, за да не подгонват почиващите зайци.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'bg', 'Язовец', 'Язовците живеят в семейни групи в подземни дупки, ползвани поколения наред.', 'От пролетта до есента след мръкване край гора; зимата преспиват.', 'Оставете необезпокоявани откоси и живи плетове, където язовците могат да копаят.', 'Никога не запушвайте обитавана дупка и не копайте до нея — това е дългогодишният им дом.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'bg', 'Кафяво прилепче', 'Този мъничък прилеп изяжда до 3000 мушици и комари за една нощ.', 'В летните вечери следете по здрач бързия, накъсан полет над градините.', 'Закрепете къщичка за прилепи високо на стена или дърво, огрявано от вечерното слънце.', 'Избягвайте силна светлина при входовете на убежищата и пазете нощното небе тъмно.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'bg', 'Копривна пеперуда', 'Тази пеперуда зимува като възрастна, често в бараки и тавани.', 'От ранна пролет до есента по слънчеви цветове, най-вече коприва и будлея.', 'Оставете петно коприва в слънчев ъгъл — гъсениците ѝ имат нужда от нея.', 'Не безпокойте през зимата пеперудите, които зимуват в бараки.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'bg', 'Дневно пауново око', 'Очните петна се разтварят рязко, за да стреснат птиците, а крилете могат да изсъскат.', 'От пролетта до есента в слънчеви дни по магарешки бодил, будлея и паднали плодове.', 'Оставете на слънце да порасне петно коприва за гъсениците.', 'Не безпокойте възрастните, които зимуват в бараки и купчини дърва.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'bg', 'Лимонена пеперуда', 'Английската дума „butterfly“ вероятно идва от маслено-жълтия цвят на мъжкия при този вид.', 'Една от първите пролетни пеперуди; търсете я по горските краища в меки дни.', 'Подкрепете зърнастеца в живите плетове — единственото растение, с което се хранят гъсениците ѝ.', 'Избягвайте да разчиствате храсталачните плетове, които подслоняват зимуващите възрастни.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'bg', 'Оранжевовърха пеперуда', 'Само мъжките имат яркооранжеви върхове на крилете; женските са бели.', 'Напролет покрай влажни ливади и пътища, където расте ливадната горва.', 'Оставете ливадната горва и чесновия бурен да растат във влажни, некосени ъгли.', 'Отложете косенето на банкетите, докато гъсениците не приключат храненето.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'bg', 'Обикновено синьовче', 'Гъсениците на това синьовче понякога се гледат от мравки, привлечени от сладките им отделяния.', 'От късна пролет по слънчеви ливади, богати на детелина и звездан.', 'Оставете ливадата некосена, за да могат звезданът и детелините да цъфнат.', 'Избягвайте пръскане с хербицид на ливади, богати на диви цветя.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'bg', 'Зеленожилчеста белянка', 'Макар да прилича на зелевата белянка, предпочита дивите растения пред градинските култури.', 'От пролетта до късно лято по влажни ливади, канавки и горски просеки.', 'Оставете влажните ъгли да подивеят с местни кръстоцветни като ливадната горва.', 'Избягвайте отводняване и пръскане на влажните ливади, където се размножава.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'bg', 'Седемточкова калинка', 'Една калинка изяжда хиляди листни въшки през живота си.', 'От пролетта до есента по растения с въшки; зимата се струпват на групи, за да презимуват.', 'Изтърпете няколко въшки и пропуснете пръсканията, за да има какво да ядат калинките.', 'Оставете кухи стъбла и листна постилка, където се подслоняват през зимата.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'bg', 'Земен бомбар', 'Царицата е сред първите пчели напролет и бръмчи ниско в търсене на гнездови дупки.', 'От ранна пролет до есента по цветовете; напролет цариците претърсват основите на плетовете.', 'Отглеждайте или запазете рано цъфтящи растения и оставете детелината да цъфти в тревата.', 'Оставете необезпокоявани откоси и стари миши дупки, където колониите се заселват.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'bg', 'Западна медоносна пчела', 'Събирачките показват на кошера къде са цветята, като танцуват във формата на осмица.', 'От пролетта до есента по цветовете, в топли и тихи дни.', 'Осигурете различни цъфтежи да се редуват през сезоните и сложете плитка чинийка с вода.', 'Не пръскайте цъфтящи растения и никога по средата на деня.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'bg', 'Императорско водно конче', 'Едно от най-едрите водни кончета в Европа: улавя плячка дори във въздуха.', 'В топли летни дни го гледайте как патрулира над блата и езерни брегове.', 'Запазете или изкопайте водоем с растения и оставете бреговете му обрасли.', 'Пазете водоемите от замърсяване и повърхностни води, за да се развиват ларвите.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'bg', 'Обикновено есенно водно конче', 'Тези водни кончета често кацат на едно и също топло място и се стрелват към прелитащи насекоми.', 'От средата на лятото до есента край застояли води, греещи се по пътеки и колове.', 'Оставете слънчеви места за кацане и растителност около водоемите и канавките.', 'Не позволявайте торове или масла да се отмиват във водоемите, където живеят ларвите.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'bg', 'Червена горска мравка', 'Куполните им мравуняци надхвърлят метър височина и подслоняват половин милион мравки.', 'От пролетта до есента в иглолистни гори; търсете куполите от иглички.', 'Оставете мравуняците недокоснати — изграждането им отнема години.', 'Придържайте се към пътеките и никога не ритайте и не копайте в мравуняк.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'bg', 'Горска съсънка', 'Горската съсънка се разпространява толкова бавно, че гъстите килими издават стара гора.', 'Напролет търсете килимите от бели цветове, преди дърветата да разлистят.', 'Оставете горската почва необезпокоявана, за да укрепват бавните коренища.', 'Радвайте ѝ се там, където расте — брането отнема цветове, разпространявали се с години.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'bg', 'Момина сълза', 'Всяка част от това сладко ухаещо растение е отровна при поглъщане.', 'В късна пролет тръгнете по аромата към сенчести гори и засенчени градини.', 'Оставете на място сенчестите горски краища и листната постилка, където расте.', 'Не го берете и не го изкопавайте и го дръжте далеч от деца и домашни любимци.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'bg', 'Мечи лук', 'Мечия лук обикновено го подушвате далеч преди да видите белите му цветове.', 'Напролет търсете широките зелени листа и звездовидните цветове във влажни гори.', 'Оставете влажните гори необезпокоявани, за да могат килимите да порастват всяка година.', 'Ако брането е разрешено на място, вземете малко и никога не вадете луковиците.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'bg', 'Блатняк', 'Едно от най-древните местни растения: преживяло е последния ледников период в Скандинавия.', 'Напролет търсете едрите златисти цветове в блата, канавки и по бреговете на водоеми.', 'Поддържайте краищата на водоемите и канавките влажни и некосени, за да цъфти.', 'Избягвайте отводняване на мокра почва и оставете растенията там, където растат.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'bg', 'Лечебна иглика', 'Игликата някога е била толкова честа в сенокосните ливади, че децата са правели топки от нея.', 'Напролет търсете поклащащите се жълти цветове в стари, неторени ливади.', 'Оставете ливадите некосени, докато игликата не прецъфти и не завърже семена.', 'Не я берете и не я вадете от природата — ливадните цветя намаляват.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'bg', 'Ливадна маргаритка', '„Цветът“ на маргаритката всъщност е съцветие от десетки мънички цветчета.', 'През лятото търсете едрите бели маргаритки покрай пътищата и в ливадите.', 'Оставете ивица трева некосена през разгара на лятото, за да може да цъфне.', 'Избягвайте пръскане на банкети и ливади с хербицид.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'bg', 'Обикновено глухарче', 'Глухарчето е сред най-важните ранни източници на нектар за пчелите.', 'От пролетта нататък почти навсякъде; цветовете се отварят на слънце и се затварят по здрач.', 'Оставете глухарчетата да цъфнат в тревата напролет преди първото косене.', 'Пропуснете хербицидите за трева, за да запазят ранните опрашители тази храна.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'bg', 'Обикновен пирен', 'Едно-единствено растение пирен може да даде над сто хиляди мънички семена.', 'В края на лятото търсете лилавите килими по открити пустоши и торфища.', 'Подкрепете поддържането на пустошите открити и неотводнени.', 'Придържайте се към пътеките в пустошите и никога не палете огън при сухо време.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'bg', 'Черна боровинка', 'Черните боровинки оцветяват пръстите в синьо и хранят всички — от птици до мечки.', 'През лятото търсете ниските храстчета с тъмни плодове в борови и смърчови гори.', 'Оставете горския подраст непокътнат, за да могат ниските храстчета да плодоносят.', 'Ако брането е разрешено на място, оставете много плодове за дивите животни.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'bg', 'Червена боровинка', 'Червените боровинки се запазват с месеци благодарение на естествен консервант в плода.', 'В края на лятото и наесен търсете лъскавите червени плодове по вечнозелени килими.', 'Оставете растителността на горската почва необезпокоявана, за да се разстилат килимите.', 'Ако брането е разрешено на място, стъпвайте внимателно, за да не смачкате растенията.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'bg', 'Бяла бреза', 'Една бреза поддържа стотици видове насекоми и така храни безброй птици.', 'Целогодишно; бялата, олющваща се кора я прави разпознаваема във всеки сезон.', 'Оставете падналите листа и мъртвата дървесина на земята: обогатяват почвата и хранят насекомите.', 'Избягвайте да обелвате кората — това наранява и отслабва дървото.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'bg', 'Обикновен смърч', 'В Швеция един смърч расте от корени на хиляди години.', 'Целогодишно в горите; висящите му шишарки са най-дългите сред всички смърчове.', 'Оставете падналите шишарки и мъртвата дървесина, които подслоняват насекоми и гъби.', 'Придържайте се към пътеките в гората, за да не уплътнявате плитките смърчови корени.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'bg', 'Бял бор', 'Старите бели борове светят в оранжево към върха и могат да живеят векове.', 'Целогодишно по песъчлива и камениста почва; търсете оранжевата кора в горната част на ствола.', 'Оставете мъртвата дървесина права и старите борове на място — те са пълни с живот.', 'Никога не палете огън до или близо до борове върху суха, песъчлива почва.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'bg', 'Щука', 'Щуката е хищник от засада, който се стрелва от пълна неподвижност за миг.', 'От пролетта до есента в обраслите плитчини на езера и бавни реки.', 'Подкрепете запазването на тръстиковите плитчини и водните растения, където се крие малката риба.', 'Пазете замърсяването и боклука извън водата; спазвайте местните правила за риболов.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'bg', 'Речен костур', 'Костурите ловуват на пасажи и носят ярки ивици, които разбиват силуета им.', 'В по-топлите месеци около кейове, подводна растителност и стръмни спадове.', 'Подкрепете чистата вода и потопените структури, които подслоняват дребната риба.', 'Никога не изливайте нищо в езера и реки; спазвайте местните правила за риболов.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'bg', 'Бабушка', 'Бабушката е ключова риба плячка, от която зависят много езерни хищници.', 'В по-топлите месеци на пасажи близо до повърхността на езера и бавни реки.', 'Подкрепете чистата вода и обраслите брегове, нужни за хвърляне на хайвер.', 'Пазете отточните води и боклука извън водата; спазвайте местните правила за риболов.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'lt', 'Juodasis čiurlys', 'Čiurliai gali išbūti ore ištisus mėnesius ir net miega skrisdami.', 'Šiltais vasaros vakarais žvelkite aukštai virš stogų ir klausykitės klykiančių būrių.', 'Iškelkite inkilą po palange ar stogo atbraila, kol paukščiai pavasarį dar negrįžo.', 'Remontuodami išsaugokite mažus plyšius po stogo atbraila, kuriuose jie peri.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'lt', 'Šelmeninė kregždė', 'Kregždės kasmet migruoja net iki pietinės Afrikos ir sugrįžta.', 'Nuo pavasario iki ankstyvo rudens jos skrieja žemai virš atvirų laukų ir vandens.', 'Palikite praviras klojimo ar pašiūrės duris, kad jos pasiektų savo lizdus.', 'Nenugriaukite senų molinių lizdų — kregždės juos naudoja metai iš metų.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'lt', 'Gegutė', 'Gegutė deda kiaušinius į kitų paukščių lizdus ir niekada neaugina savo jauniklių.', 'Vėlyvą pavasarį klausykitės toli sklindančio „ku-kū“ nuo miško pakraščių.', 'Palaikykite vabzdžiais turtingas pievas ir gyvatvores, maitinančias gegutės globėjus.', 'Laikykitės takų prie krūmynų ir nendrynų, kad globėjai paukščiai nebūtų trikdomi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'lt', 'Liepsnelė', 'Liepsnelė nuožmiai gina savo teritoriją ir prie gatvės žibintų gieda naktį.', 'Ištisus metus soduose ir miškuose; dažnai seka kasantį, tikėdamasi sliekų.', 'Palikite sodo kampą su nukritusiais lapais, kur ji galėtų ieškoti maisto.', 'Atidėkite stiprų gyvatvorių kirpimą, kol vasaros pabaigoje baigsis perėjimas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'lt', 'Juodasis strazdas', 'Sodrus, fleitinis patino giedojimas yra vienas atpažįstamiausių Europoje.', 'Ištisus metus; auštant ir temstant klausykitės patinų, giedančių nuo stogų ir viršūnių.', 'Išstatykite gėlo vandens gerti ir maudytis, ypač sausrų metu.', 'Perėjimo metu auštant laikykite kates viduje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'lt', 'Smilginis strazdas', 'Smilginis strazdas yra draugiškas strazdas, žiemą klajojantis triukšmingais būriais.', 'Rudenį ir žiemą stebėkite, kaip būriai nurenka uogas nuo gyvatvorių ir šermukšnių.', 'Palikite uogingus krūmus, tokius kaip šermukšnis ir gudobelė, žiemai nekarpytus.', 'Palikite nukritusius obuolius ant žemės žiemą — per šalčius tai gyvybiškai svarbus maistas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'lt', 'Didžioji zylė', 'Didžioji zylė turi didžiulį garsų repertuarą ir naujų šauksmų išmoksta iš kaimynų.', 'Ištisus metus; nuo žiemos pabaigos klausykitės skambios dviejų pasikartojančių natų giesmės.', 'Pakabinkite inkilą su 32 mm anga ramioje, pavėsingoje vietoje.', 'Venkite pesticidų sode, kad vikšrų pakaktų jaunikliams maitinti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'lt', 'Mėlynoji zylė', 'Vienas mėlynųjų zylių lizdas gali sunaudoti daugiau nei tūkstantį vikšrų.', 'Ištisus metus soduose ir miškuose, dažnai kabo aukštyn kojomis ant plonų šakelių.', 'Iškelkite mažą inkilą su 25 mm anga, apsaugotą nuo vyraujančių vėjų.', 'Pavasarį praleiskite insekticidus, kad vikšrai liktų jaunikliams.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'lt', 'Kikilis', 'Kikilio giesmė skiriasi pagal kraštą, beveik kaip vietinės tarmės.', 'Nuo pavasario iki rudens; patinai gieda skaidrią, žemėjančią frazę nuo atvirų šakų.', 'Palikite sezonui keletą sėklinių žiedynų ir apžėlusių lopinėlių.', 'Laikykite lesyklas švarias, kad tarp kikilių neplistų ligos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'lt', 'Kėkštas', 'Kėkštas kasmet užkasa tūkstančius gilių ir, dalį pamiršdamas, pasodina ištisus ąžuolynus.', 'Ištisus metus ąžuolynuose; rudenį ieškokite rausvų ir mėlynų blyksnių.', 'Palikite nukritusias giles ir lapų paklotę po ąžuolais nepaliestas.', 'Laikykite šunis ant miško takų, kad ant žemės besimaitinantys paukščiai nebūtų baidomi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'lt', 'Didysis margasis genys', 'Pavasarinis „būgnijimas“ yra ne maitinimasis, o greitas ritmas, kuriuo skelbiama teritorija.', 'Ištisus metus; žiemos pabaigoje klausykitės būgnijimo, aidinčio per mišką.', 'Palikite stovinčią negyvą medieną — joje gyvena vabzdžiai, kuriais genys minta.', 'Nekirskite negyvų ar džiūstančių medžių, kuriuose gali būti lizdo drevės.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'lt', 'Baltoji kielė', 'Nuolatinis uodegos linksėjimas galbūt rodo budrumą plėšrūnų atžvilgiu.', 'Nuo pavasario iki rudens prie vandens ir atviros žemės, bėgioja ir stabteli gaudydama vabzdžius.', 'Palikite prie vandens žemos žolės ar žvyro ruožą, kur ji galėtų ieškoti maisto.', 'Venkite trikdyti žvyrėtus krantus, kur ji maitinasi ir peri.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'lt', 'Pilkoji gervė', 'Gervės ankstyvą pavasarį atlieka poravimosi šokius su šuoliais ir nusilenkimais.', 'Nuo pavasario iki rudens prie pelkių; jų trimituojantis šauksmas girdimas už kilometrų.', 'Palaikykite nenusausintų durpynų ir šlapių pievų apsaugą, kur gervės peri.', 'Stebėkite perėjimo vietas iš toli — sutrikdytus lizdus gervės palieka.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'lt', 'Gulbė giesmininkė', 'Gulbė giesmininkė poruojasi visam gyvenimui ir atvykimą skelbia garsiais trimituojančiais šauksmais.', 'Pavasarį ir rudenį ežeruose bei apsemtuose laukuose, dažnai šeimų būreliais.', 'Palaikykite seklių ežerų pakraščių ir šlapių laukų išsaugojimą be sausinimo.', 'Niekada nešerkite gulbių duona — tai joms kenkia; ant ledo laikykitės atstumo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'lt', 'Didžioji antis', 'Ančiukai plaukioja ir maitinasi patys jau po kelių valandų nuo išsiritimo.', 'Ištisus metus beveik kiekvienoje kūdroje, ežere ar lėtoje upėje.', 'Jei šeriate antis, naudokite avižas, žirnius ar sėklas vietoj duonos.', 'Pavasarį neleiskite šunų į vandenį ten, kur antys peri.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'lt', 'Paprastasis suopis', 'Suopis sklendžia plačiais sparnais ir dažnai šaukia katiniškai „piiii-jau“.', 'Nuo pavasario iki rudens; ieškokite jo sukančio ratus aukštai virš laukų ir miško pakraščių.', 'Palaikykite nešienautas pievas ir laukų pakraščius, kuriuose gyvena pelėnai ir smulkus grobis.', 'Niekada nenaudokite graužikų nuodų: jie kyla maisto grandine iki plėšriųjų paukščių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'lt', 'Žuvininkas', 'Žuvininkas neria kojomis į priekį ir gali nešti grobį, sveriantį pusę jo paties svorio.', 'Nuo pavasario iki rudens prie didelių ežerų; stebėkite kybojimą ore ir tada įspūdingą nėrimą.', 'Palaikykite dirbtines lizdavietes ant aukštų stulpų prie žuvingų ežerų.', 'Aplenkite lizdavietes iš toli, kad poros nebūtų išbaidytos nuo kiaušinių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'lt', 'Rudoji lapė', 'Lapė pasitelkia Žemės magnetinį lauką, kad tiksliau šoktų ant paslėpto grobio.', 'Ištisus metus, aktyviausia auštant ir temstant palei miško bei laukų pakraščius.', 'Palikite laukinį, netrikdomą kampą, kur lapės galėtų ilsėtis ir kasti urvą.', 'Užrakinkite šiukšlių konteinerius ir niekada nepalikite kenksmingų maisto likučių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'lt', 'Europinis ežys', 'Ežys per vieną maisto ieškojimo naktį gali nukeliauti porą kilometrų.', 'Nuo pavasario iki rudens sutemus; žiemą miega po lapų ir malkų krūvomis.', 'Išpjaukite tvorose 13 cm angą, kad ežiai galėtų vaikščioti tarp sodų.', 'Prieš pjaudami patikrinkite aukštą žolę ir palikite lapų krūvas žiemos miegui.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'lt', 'Stirna', 'Stirnos atideda nėštumą, kad jaunikliai visada gimtų ankstyvą vasarą.', 'Ištisus metus miško pakraščiuose, geriausiai matomos ganantis auštant ir temstant.', 'Palaikykite nešienautus laukų pakraščius ir krūmynus, teikiančius priedangą ir maistą.', 'Ankstyvą vasarą laikykite šunis pavadėlyje prie miško, kai jaunikliai guli pasislėpę.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'lt', 'Briedis', 'Briedis yra didžiausias elninis Žemėje; didelis patinas sveria daugiau nei pusę tonos.', 'Ištisus metus miškuose ir pelkėse, aktyviausias auštant ir temstant.', 'Palaikykite vientisus miškus ir šlapius koridorius, kurių briedžiui reikia keliauti.', 'Auštant ir temstant miško keliuose važiuokite atsargiai ir niekada nesiartinkite prie jauniklio.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'lt', 'Paprastoji voverė', 'Voverė susisuka kelis lizdus ir keliauja iš vieno į kitą.', 'Ištisus metus spygliuočių ir mišriuose miškuose, judriausia anksti rytą.', 'Palikite kankorėžius, riešutus ir stovinčius medžius, kuriuose ji minta ir peri.', 'Laikykite šunis ant takų ir nepurtykite medžių, kuriuose gali būti lizdas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'lt', 'Europinis bebras', 'Bebrų užtvankos kuria šlapynes, kurios kilometrus aplinkui padeda žuvims, paukščiams ir vabzdžiams.', 'Nuo pavasario iki vėlyvo rudens prie lėtų upių, aktyviausias temstant.', 'Palaikykite bebrų užtvankų ir pakrantės medžių palikimą ten, kur tai saugu.', 'Laikykitės atokiau nuo bebravietės ir užtvankų, ypač kai jaunikliai maži.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'lt', 'Baltasis kiškis', 'Baltasis kiškis žiemą pabąla, kad susilietų su sniegu.', 'Ištisus metus atviroje vietovėje ir miško kirtimuose, daugiausia auštant ir temstant.', 'Palaikykite atviros erdvės ir priedangos mozaiką, kurios kiškiui reikia visus metus.', 'Atviroje vietovėje laikykite šunis pavadėlyje, kad besiilsintys kiškiai nebūtų vejami.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'lt', 'Barsukas', 'Barsukai gyvena šeimų grupėmis požeminiuose urvuose, naudojamuose kartų kartas.', 'Nuo pavasario iki rudens sutemus prie miško; žiemą jie permiega.', 'Palikite netrikdomus šlaitus ir gyvatvores, kur barsukai galėtų išsikasti urvą.', 'Niekada neužverskite gyvenamo urvo ir nekaskite šalia — tai jų ilgamečiai namai.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'lt', 'Šikšniukas nykštukas', 'Šis mažytis šikšnosparnis per vieną naktį suėda iki 3000 mašalų ir uodų.', 'Vasaros vakarais temstant stebėkite greitą, trūkčiojantį skrydį virš sodų.', 'Pritvirtinkite šikšnosparnių inkilą aukštai ant sienos ar medžio, kurį pasiekia vakaro saulė.', 'Venkite ryškios šviesos prie slėptuvių angų ir palikite naktinį dangų tamsų.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'lt', 'Dilgėlinukas', 'Šis drugys žiemoja suaugęs, dažnai pašiūrėse ir palėpėse.', 'Nuo ankstyvo pavasario iki rudens ant saulėtų žiedų, ypač dilgėlių ir vasarinių alyvų.', 'Palikite dilgėlių lopinėlį saulėtame kampe — jo vikšrams jų reikia.', 'Žiemą netrikdykite pašiūrėse žiemojančių drugių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'lt', 'Dieninis povas', 'Akių dėmės staiga atsiveria, kad išgąsdintų paukščius, o sparnai gali sušnypšti.', 'Nuo pavasario iki rudens saulėtomis dienomis ant usnių, vasarinių alyvų ir nukritusių vaisių.', 'Leiskite saulėtoje vietoje užaugti dilgėlių lopinėliui jo vikšrams.', 'Netrikdykite suaugėlių, žiemojančių pašiūrėse ir malkų krūvose.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'lt', 'Citrinukas', 'Angliškas žodis „butterfly“ galbūt kilęs iš šios rūšies patino sviestiškai geltonos spalvos.', 'Vienas pirmųjų pavasario drugių; ieškokite jo miško pakraščiuose šiltomis dienomis.', 'Palaikykite šaltekšnius gyvatvorėse — vienintelius augalus, kuriuos ėda jo vikšrai.', 'Venkite valyti krūmingas gyvatvores, kuriose slepiasi žiemojantys suaugėliai.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'lt', 'Oranžinis baltukas', 'Tik patinai turi ryškiai oranžinius sparnų galiukus; patelės baltos.', 'Pavasarį palei drėgnas pievas ir keliukus, kur auga pievinė kartenė.', 'Leiskite pievinei kartenei ir česnakinei ropūnei augti drėgnuose, nešienautuose kampuose.', 'Atidėkite pakelių šienavimą, kol vikšrai baigs maitintis.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'lt', 'Paprastasis melsvys', 'Šio melsvio vikšrus kartais prižiūri skruzdėlės, viliojamos jų saldžių išskyrų.', 'Nuo vėlyvo pavasario saulėtose pievose, gausiose dobilų ir garždenių.', 'Palikite pievą nešienautą, kad garždeniai ir dobilai galėtų pražysti.', 'Venkite purkšti herbicidais pievas, gausias laukinių gėlių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'lt', 'Ropinis baltukas', 'Nors panašus į kopūstinį baltuką, jis renkasi laukinius augalus, o ne daržo kultūras.', 'Nuo pavasario iki vėlyvos vasaros drėgnose pievose, grioviuose ir miško kvartalinėse.', 'Leiskite drėgniems kampams sulaukėti su vietinėmis bastutinėmis, tokiomis kaip kartenė.', 'Venkite sausinti ir purkšti drėgnas pievas, kuriose jis veisiasi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'lt', 'Septyntaškė boružė', 'Viena boružė per gyvenimą suėda tūkstančius amarų.', 'Nuo pavasario iki rudens ant augalų su amarais; žiemai jos susispiečia į grupes.', 'Pakęskite šiek tiek amarų ir praleiskite purškimus, kad boružėms būtų ką ėsti.', 'Palikite tuščiavidurius stiebus ir lapų paklotę, kur jos slepiasi žiemą.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'lt', 'Žeminė kamanė', 'Motinėlės yra tarp pirmųjų pavasario bičių — jos zvimbia žemai, ieškodamos lizdo landų.', 'Nuo ankstyvo pavasario iki rudens ant žiedų; pavasarį motinėlės naršo gyvatvorių papėdes.', 'Auginkite ar palikite anksti žydinčius augalus ir leiskite dobilams žydėti vejoje.', 'Palikite netrikdomus šlaitus ir senas pelių landas, kuriose kuriasi šeimos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'lt', 'Naminė bitė', 'Rinkėjos nurodo aviliui, kur yra žiedai, šokdamos aštuoneto formos šokį.', 'Nuo pavasario iki rudens ant žiedų, šiltomis ir ramiomis dienomis.', 'Pasirūpinkite, kad per sezonus keistųsi įvairūs žydėjimai, ir pastatykite seklų vandens dubenį.', 'Nepurkškite žydinčių augalų ir niekada nepurkškite vidurdienį.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'lt', 'Didysis laumžirgis', 'Vienas didžiausių Europos laumžirgių: grobį jis pagauna net ore.', 'Šiltomis vasaros dienomis stebėkite, kaip jis patruliuoja virš tvenkinių ir ežerų pakraščių.', 'Išsaugokite ar iškaskite tvenkinį su augalais ir palikite jo krantus apaugusius.', 'Saugokite tvenkinius nuo taršos ir nuotėkio, kad lervos galėtų vystytis.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'lt', 'Paprastoji skėtė', 'Šios skėtės dažnai tupia toje pačioje šiltoje vietoje ir šauna prie pralekiančių vabzdžių.', 'Nuo vasaros vidurio iki rudens prie stovinčio vandens, kaitinasi ant takų ir stulpelių.', 'Palikite saulėtas tupėjimo vietas ir augaliją aplink tvenkinius bei griovius.', 'Neleiskite trąšoms ar alyvai nutekėti į tvenkinius, kuriuose gyvena lervos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'lt', 'Rudoji miškinė skruzdėlė', 'Jų kupolo formos skruzdėlynai būna aukštesni nei metras ir talpina pusę milijono skruzdėlių.', 'Nuo pavasario iki rudens spygliuočių miškuose; ieškokite kupolų iš spyglių.', 'Palikite skruzdėlynus nepaliestus — jiems supilti reikia metų.', 'Laikykitės takų ir niekada nespirkite ir nekaskite į skruzdėlyną.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'lt', 'Baltažiedė plukė', 'Plukė plinta taip lėtai, kad tankūs kilimai išduoda seną mišką.', 'Pavasarį ieškokite baltų žiedų kilimų, kol medžiai dar nesulapojo.', 'Palikite miško paklotę netrikdomą, kad lėtai plintantys šakniastiebiai galėtų klestėti.', 'Grožėkitės ja ten, kur ji auga — skynimas atima žiedus, plitusius metų metus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'lt', 'Paprastoji pakalnutė', 'Kiekviena šio saldžiai kvepiančio augalo dalis prarijus yra nuodinga.', 'Vėlyvą pavasarį sekite kvapą į šešėtus miškus ir pavėsingus sodus.', 'Palikite vietoje pavėsingus miško pakraščius ir lapų paklotę, kur ji auga.', 'Neskinkite ir nekaskite jos, laikykite atokiau nuo vaikų ir augintinių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'lt', 'Meškinis česnakas', 'Meškinį česnaką paprastai užuodžiate gerokai anksčiau, nei pamatote baltus jo žiedus.', 'Pavasarį ieškokite plačių žalių lapų ir žvaigždiškų žiedų drėgnuose miškuose.', 'Palikite drėgnus miškus netrikdomus, kad kilimai kasmet atželtų.', 'Jei rinkti vietoje leidžiama, pasiimkite nedaug ir niekada nerauskite svogūnėlių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'lt', 'Pelkinė puriena', 'Vienas seniausių vietinių augalų: Skandinavijoje jis išgyveno paskutinį ledynmetį.', 'Pavasarį ieškokite didelių auksinių žiedų pelkėse, grioviuose ir tvenkinių pakraščiuose.', 'Laikykite tvenkinių ir griovių pakraščius drėgnus ir nešienautus, kad jis galėtų žydėti.', 'Venkite sausinti šlapią žemę ir palikite augalus ten, kur jie auga.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'lt', 'Vaistinė raktažolė', 'Raktažolė kadaise buvo tokia dažna šienaujamose pievose, kad vaikai iš jos suko kamuolius.', 'Pavasarį ieškokite linkstančių geltonų žiedų senose, netręštose pievose.', 'Palikite pievas nešienautas, kol raktažolė pražys ir subrandins sėklas.', 'Neskinkite ir nekaskite jos iš gamtos — pievų gėlių mažėja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'lt', 'Didžioji ramunė', 'Ramunės „žiedas“ iš tikrųjų yra dešimtys mažyčių žiedelių, suglaustų kartu.', 'Vasarą ieškokite didelių baltų ramunių pakelėse ir pievose.', 'Palikite žolės ruožą nešienautą per vasaros vidurį, kad ji galėtų pražysti.', 'Venkite purkšti pakeles ir pievas herbicidais.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'lt', 'Paprastoji kiaulpienė', 'Kiaulpienė yra vienas svarbiausių ankstyvųjų nektaro šaltinių bitėms.', 'Nuo pavasario beveik visur; žiedai atsiveria saulėje ir užsiveria temstant.', 'Leiskite kiaulpienėms pražysti vejoje pavasarį prieš pirmą pjovimą.', 'Praleiskite vejos herbicidus, kad ankstyvieji apdulkintojai išsaugotų šį maistą.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'lt', 'Paprastasis viržis', 'Vienas viržio krūmelis gali subrandinti daugiau nei šimtą tūkstančių mažyčių sėklų.', 'Vėlyvą vasarą ieškokite violetinių kilimų atvirose viržynėse ir aukštapelkėse.', 'Palaikykite viržynių išlaikymą atviromis ir nesausinamomis.', 'Viržynėse laikykitės takų ir sausu metu niekada nekurkite ugnies.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'lt', 'Mėlynė', 'Mėlynės nudažo pirštus mėlynai ir maitina visus — nuo paukščių iki lokių.', 'Vasarą ieškokite žemų krūmelių su tamsiomis uogomis pušynuose ir eglynuose.', 'Palikite miško pomiškį nepaliestą, kad žemi krūmeliai galėtų derėti.', 'Jei rinkti vietoje leidžiama, palikite daug uogų laukiniams gyvūnams.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'lt', 'Bruknė', 'Bruknės išsilaiko mėnesius dėl natūralaus konservanto pačioje uogoje.', 'Vėlyvą vasarą ir rudenį ieškokite blizgių raudonų uogų ant visžalių kilimų.', 'Palikite miško paklotės augaliją netrikdomą, kad kilimai galėtų plisti.', 'Jei rinkti vietoje leidžiama, ženkite atsargiai, kad nesutraiškytumėte augalų.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'lt', 'Karpotasis beržas', 'Beržas išlaiko šimtus vabzdžių rūšių ir taip maitina nesuskaičiuojamus paukščius.', 'Ištisus metus; balta, besilupanti žievė padaro jį atpažįstamą bet kuriuo metų laiku.', 'Palikite nukritusius beržo lapus ir negyvą medieną: jie praturtina dirvą ir maitina vabzdžius.', 'Venkite lupti žievę — tai sužeidžia ir silpnina medį.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'lt', 'Paprastoji eglė', 'Švedijoje eglė auga iš šaknų, kurioms tūkstančiai metų.', 'Ištisus metus miškuose; jos nukarę kankorėžiai yra ilgiausi iš visų eglių.', 'Palikite nukritusius kankorėžius ir negyvą medieną, kurie priglaudžia vabzdžius ir grybus.', 'Miške laikykitės takų, kad nesutankintumėte seklių eglės šaknų.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'lt', 'Paprastoji pušis', 'Senos pušys viršūnėje šviečia oranžine spalva ir gali gyventi šimtmečius.', 'Ištisus metus smėlingoje ir uolėtoje žemėje; ieškokite oranžinės žievės kamieno viršuje.', 'Palikite stovinčią negyvą medieną ir senas pušis — jos pilnos gyvybės.', 'Niekada nekurkite ugnies prie pušų ar šalia jų sausoje, smėlingoje žemėje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'lt', 'Lydeka', 'Lydeka yra iš pasalų puolantis plėšrūnas, akimirksniu šaunantis iš nejudrumo.', 'Nuo pavasario iki rudens apžėlusiose ežerų ir lėtų upių seklumose.', 'Palaikykite nendrėtų seklumų ir vandens augalų išsaugojimą, kur slepiasi jaunikliai.', 'Neleiskite taršai ir šiukšlėms patekti į vandenį; laikykitės vietinių žvejybos taisyklių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'lt', 'Paprastasis ešerys', 'Ešeriai medžioja būriais, o ryškios juostos suskaido jų siluetą.', 'Šiltesniais mėnesiais aplink lieptus, augalų sąžalynus ir staigias gelmes.', 'Palaikykite švarų vandenį ir povandenines struktūras, priglaudžiančias mažas žuvis.', 'Niekada nieko nepilkite į ežerus ir upes; laikykitės vietinių žvejybos taisyklių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'lt', 'Kuoja', 'Kuoja yra svarbiausia grobio žuvis, nuo kurios priklauso daugelis ežerų plėšrūnų.', 'Šiltesniais mėnesiais būriais netoli ežerų ir lėtų upių paviršiaus.', 'Palaikykite švarų vandenį ir apaugusius krantus, reikalingus nerštui.', 'Neleiskite nuotėkiui ir šiukšlėms patekti į vandenį; laikykitės vietinių žvejybos taisyklių.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'lv', 'Melnais svīre', 'Svīres spēj mēnešiem palikt gaisā un pat guļ lidojumā.', 'Siltos vasaras vakaros raugieties augstu pāri jumtiem un klausieties spiedzošos barus.', 'Uzstādiet būri zem jumta dzegas, pirms putni pavasarī atgriežas.', 'Renovējot saglabājiet mazās spraugas zem dzegas, kur tie ligzdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'lv', 'Lauku bezdelīga', 'Bezdelīgas ik gadu migrē līdz pat Āfrikas dienvidiem un atpakaļ.', 'No pavasara līdz agram rudenim tās slīd zemu pāri atklātiem laukiem un ūdeņiem.', 'Atstājiet šķūņa vai kūts durvis pievērtas, lai tās tiktu pie savām ligzdām.', 'Nenojauciet vecās māla ligzdas — bezdelīgas tās izmanto gadu no gada.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'lv', 'Dzeguze', 'Dzeguze dēj olas citu putnu ligzdās un nekad neaudzina pati savus mazuļus.', 'Vēlā pavasarī klausieties tālu skanošo „ku-kū” no meža malām.', 'Atbalstiet ar kukaiņiem bagātas pļavas un dzīvžogus, kas baro dzeguzes saimniekputnus.', 'Turieties uz takām pie krūmājiem un niedrājiem, lai saimniekputni netiktu traucēti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'lv', 'Sarkanrīklīte', 'Sarkanrīklīte nikni aizstāv savu teritoriju un pie ielu laternām dzied arī naktī.', 'Visu gadu dārzos un mežos; tā labprāt seko racējam, cerot uz sliekām.', 'Atstājiet dārza stūri ar nokritušām lapām, kur tā var meklēt barību.', 'Atlieciet spēcīgu dzīvžogu apgriešanu, līdz vasaras beigās beidzas ligzdošana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'lv', 'Melnais mežastrazds', 'Tēviņa pilnskanīgā, flautveidīgā dziesma ir viena no atpazīstamākajām Eiropā.', 'Visu gadu; rītausmā un krēslā klausieties tēviņus, kas dzied no jumtiem un koku galotnēm.', 'Izlieciet svaigu ūdeni dzeršanai un peldēšanai, īpaši sausajos periodos.', 'Ligzdošanas laikā rītausmā turiet kaķus iekšā.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'lv', 'Pelēkais strazds', 'Pelēkais strazds ir sabiedrisks strazds, kas ziemā klejo trokšņainos, čalojošos baros.', 'Rudenī un ziemā vērojiet, kā bari noplūc ogas no dzīvžogiem un pīlādžiem.', 'Atstājiet ogu krūmus, tādus kā pīlādzis un vilkābele, ziemai neapgrieztus.', 'Atstājiet nokritušos ābolus zemē ziemā — salā tā ir dzīvībai svarīga barība.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'lv', 'Lielā zīlīte', 'Lielajai zīlītei ir milzīgs skaņu krājums, un jaunus saucienus tā mācās no kaimiņiem.', 'Visu gadu; no ziemas beigām klausieties skanīgo dziesmu no divām atkārtotām notīm.', 'Pakariet būri ar 32 mm atveri klusā, ēnainā vietā.', 'Izvairieties no pesticīdiem dārzā, lai kāpuru pietiktu mazuļu barošanai.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'lv', 'Zilzīlīte', 'Viens zilzīlīšu perējums var apēst vairāk nekā tūkstoš kāpuru.', 'Visu gadu dārzos un mežos, bieži karājoties ar galvu uz leju pie tievām zariņām.', 'Uzstādiet mazu būri ar 25 mm atveri prom no valdošajiem vējiem.', 'Pavasarī izlaidiet insekticīdus, lai kāpuri paliktu mazuļiem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'lv', 'Žubīte', 'Žubītes dziesma atšķiras pa novadiem, gandrīz kā vietējās izloksnes.', 'No pavasara līdz rudenim; tēviņi dzied skaidru, krītošu frāzi no atklātiem zariem.', 'Atstājiet sezonai dažus sēklu ziedkopas un aizaugušus stūrīšus.', 'Turiet barotavas tīras, lai starp žubītēm neizplatītos slimības.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'lv', 'Sīlis', 'Sīlis katru rudeni aprok tūkstošiem zīļu un, dažas aizmirsdams, iestāda veselus ozolu mežus.', 'Visu gadu ozolu mežos; rudenī meklējiet rozā un zilus zibšņus.', 'Atstājiet nokritušās zīles un lapu nobiras zem ozoliem neaiztiktas.', 'Turiet suņus uz meža takām, lai uz zemes barojošies putni netiktu izbiedēti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'lv', 'Dižraibais dzenis', 'Pavasara „bungošana” nav barošanās, bet ātrs ritms, ar ko tas pieteic teritoriju.', 'Visu gadu; ziemas beigās klausieties bungošanu, kas atbalsojas pa mežu.', 'Atstājiet stāvošu mirušu koksni, kurā mīt kukaiņi, ar ko dzenis barojas.', 'Neizcirtiet mirušus vai kalstošus kokus, kuros var būt ligzdas dobumi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'lv', 'Baltā cielava', 'Nepārtrauktā astes šūpošana, iespējams, liecina par modrību pret plēsējiem.', 'No pavasara līdz rudenim pie ūdens un kailas zemes, skrienot un apstājoties ķert kukaiņus.', 'Uzturiet pie ūdens zemas zāles vai grants joslu, kur tā var meklēt barību.', 'Izvairieties traucēt grantainos krastus, kur tā barojas un ligzdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'lv', 'Dzērve', 'Dzērves agrā pavasarī izpilda riesta dejas ar lēcieniem un paklanīšanos.', 'No pavasara līdz rudenim pie mitrājiem; to taurējošais sauciens skan kilometriem tālu.', 'Atbalstiet neizsusinātu purvu un mitru pļavu aizsardzību, kur dzērves ligzdo.', 'Vērojiet ligzdošanas mitrājus no attāluma — traucētas ligzdas dzērves pamet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'lv', 'Ziemeļu gulbis', 'Ziemeļu gulbis pārojas uz mūžu un savu ierašanos piesaka ar skaļiem, taurējošiem saucieniem.', 'Pavasarī un rudenī ezeros un applūdušos laukos, bieži ģimeņu grupās.', 'Atbalstiet seklo ezeru malu un mitro lauku saglabāšanu bez nosusināšanas.', 'Nekad nebarojiet gulbjus ar maizi — tā tiem kaitē; uz ledus turiet distanci.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'lv', 'Meža pīle', 'Pīlēni peld un barojas paši jau dažas stundas pēc izšķilšanās.', 'Visu gadu gandrīz jebkurā dīķī, ezerā vai lēnā upē.', 'Ja barojat pīles, izmantojiet auzas, zirņus vai sēklas, nevis maizi.', 'Pavasarī neļaujiet suņiem ūdenī tur, kur pīles ligzdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'lv', 'Peļu klijāns', 'Klijāns lido plašos spārnos un bieži sauc ar kaķim līdzīgu „piiii-jau”.', 'No pavasara līdz rudenim; meklējiet to riņķojam augstu virs laukiem un meža malām.', 'Atbalstiet nepļautas zālājus un lauku malas, kur mīt strupastes un sīkie medījumi.', 'Nekad nelietojiet grauzēju indes: tās pa barības ķēdi paceļas līdz plēsīgajiem putniem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'lv', 'Zivjērglis', 'Zivjērglis niršanā met kājas uz priekšu un spēj nest medījumu, kas sver pusi no tā svara.', 'No pavasara līdz rudenim pie lieliem ezeriem; vērojiet karāšanos gaisā un tad strauju nirienu.', 'Atbalstiet mākslīgās ligzdošanas platformas uz augstiem stabiem pie zivīm bagātiem ezeriem.', 'Apejiet ligzdošanas platformas ar līkumu, lai pāri netiktu nobiedēti no olām.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'lv', 'Sarkanā lapsa', 'Lapsa izmanto Zemes magnētisko lauku, lai precīzāk lēktu uz apslēptu medījumu.', 'Visu gadu, visaktīvākā rītausmā un krēslā gar meža un lauku malām.', 'Atstājiet mežonīgu, netraucētu stūri, kur lapsas var atpūsties un rakt alu.', 'Nostipriniet atkritumu tvertnes un nekad neatstājiet kaitīgas pārtikas atliekas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'lv', 'Eiropas ezis', 'Ezis vienā barības meklēšanas naktī var noiet pāris kilometru.', 'No pavasara līdz rudenim pēc tumsas; ziemā tas guļ zem lapu un malkas kaudzēm.', 'Izgrieziet žogos 13 cm atveri, lai eži varētu pārvietoties starp dārziem.', 'Pirms pļaušanas pārbaudiet garo zāli un atstājiet lapu kaudzes ziemas guļai.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'lv', 'Stirna', 'Stirnas aizkavē grūsnību, lai mazuļi vienmēr piedzimtu vasaras sākumā.', 'Visu gadu meža malās, vislabāk redzamas ganoties rītausmā un krēslā.', 'Atbalstiet nepļautas lauku malas un krūmājus, kas dod patvērumu un barību.', 'Vasaras sākumā pie meža turiet suņus pavadā, kad mazuļi guļ paslēpušies.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'lv', 'Alnis', 'Alnis ir lielākais briežu dzimtas dzīvnieks pasaulē; liels bullis sver vairāk nekā pustonnu.', 'Visu gadu mežos un mitrājos, visaktīvākais rītausmā un krēslā.', 'Atbalstiet savienotus mežus un mitros koridorus, kas alnim vajadzīgi pārvietoties.', 'Rītausmā un krēslā uz meža ceļiem brauciet uzmanīgi un nekad netuvojieties teļam.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'lv', 'Vāvere', 'Vāvere būvē vairākas ligzdas un pārvietojas starp tām.', 'Visu gadu skuju un jauktos mežos, visrosīgākā agri no rīta.', 'Atstājiet čiekurus, riekstus un stāvošus kokus, no kuriem tā barojas un kuros ligzdo.', 'Turiet suņus uz takām un nekratiet kokus, kuros var būt ligzda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'lv', 'Eiropas bebrs', 'Bebru dambji rada mitrājus, kas kilometriem tālu palīdz zivīm, putniem un kukaiņiem.', 'No pavasara līdz vēlam rudenim pie lēnām upēm, visaktīvākais krēslā.', 'Atbalstiet bebru dambju un krasta koku atstāšanu tur, kur tas ir droši.', 'Turieties tālāk no bebru mītnēm un dambjiem, īpaši kamēr mazuļi ir sīki.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'lv', 'Baltais zaķis', 'Baltais zaķis ziemā kļūst balts, lai saplūstu ar sniegu.', 'Visu gadu atklātās vietās un meža izcirtumos, galvenokārt rītausmā un krēslā.', 'Atbalstiet atklātu vietu un patvēruma mozaīku, kas zaķim vajadzīga cauru gadu.', 'Atklātās vietās turiet suņus pavadā, lai atpūšošies zaķi netiktu dzenāti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'lv', 'Āpsis', 'Āpši dzīvo ģimeņu grupās pazemes alās, kas tiek izmantotas paaudžu paaudzēs.', 'No pavasara līdz rudenim pēc tumsas pie meža; ziemu tie pārguļ.', 'Atstājiet netraucētas nogāzes un dzīvžogus, kur āpši var izrakt alu.', 'Nekad neaizbērējiet apdzīvotu alu un nerociet blakus — tās ir to ilggadējās mājas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'lv', 'Pundursikspārnis', 'Šis sīkais sikspārnis vienā naktī apēd līdz 3000 knišļu un odu.', 'Vasaras vakaros krēslā vērojiet ātro, raustīto lidojumu virs dārziem.', 'Piestipriniet sikspārņu būri augstu pie sienas vai koka, ko sasniedz vakara saule.', 'Izvairieties no spilgtas gaismas pie mītņu ieejām un saglabājiet nakts debesis tumšas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'lv', 'Nātru raibenis', 'Šis tauriņš pārziemo kā pieaugušais, bieži šķūņos un bēniņos.', 'No agra pavasara līdz rudenim uz saulainiem ziediem, īpaši nātrēm un vasaras ceriņiem.', 'Atstājiet nātru laukumiņu saulainā stūrī — tā kāpuriem tās ir vajadzīgas.', 'Ziemā netraucējiet tauriņus, kas pārziemo šķūņos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'lv', 'Dienas pāvacs', 'Acu plankumi strauji atveras, lai iebiedētu putnus, un spārni pie tam var šņākt.', 'No pavasara līdz rudenim saulainās dienās uz dadžiem, vasaras ceriņiem un nokritušiem augļiem.', 'Ļaujiet saulainā vietā izaugt nātru laukumiņam tā kāpuriem.', 'Netraucējiet pieaugušos, kas ziemo šķūņos un malkas grēdās.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'lv', 'Citronpeteris', 'Angļu vārds „butterfly” iespējams cēlies no šīs sugas tēviņa sviesta dzeltenās krāsas.', 'Viens no pirmajiem pavasara tauriņiem; meklējiet to meža malās siltās dienās.', 'Atbalstiet pabērzus dzīvžogos — vienīgos augus, ko ēd tā kāpuri.', 'Izvairieties tīrīt krūmainus dzīvžogus, kas patver pārziemojošos pieaugušos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'lv', 'Oranžgalvis baltenis', 'Tikai tēviņiem ir spilgti oranžie spārnu gali; mātītes ir baltas.', 'Pavasarī gar mitrām pļavām un ceļiem, kur aug pļavas pinkaine.', 'Ļaujiet pļavas pinkainei un ķiploku kreses augt mitros, nepļautos stūros.', 'Atlieciet ceļmalu pļaušanu, līdz kāpuri beiguši barošanos.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'lv', 'Parastais zilenītis', 'Šī zilenīša kāpurus dažkārt kopj skudras, ko vilina to saldie izdalījumi.', 'No vēla pavasara saulainos zālājos, bagātos ar āboliņu un vanagnadziņiem.', 'Atstājiet zālāju nepļautu, lai vanagnadziņi un āboliņi varētu uzziedēt.', 'Izvairieties smidzināt ar herbicīdiem savvaļas ziediem bagātus zālājus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'lv', 'Rāceņu baltenis', 'Kaut arī izskatās pēc kāpostu balteņa, tas dod priekšroku savvaļas augiem, nevis dārza kultūrām.', 'No pavasara līdz vēlai vasarai mitrās pļavās, grāvjos un meža stigās.', 'Ļaujiet mitriem stūriem aizaugt ar vietējiem krustziežiem, tādiem kā pļavas pinkaine.', 'Izvairieties nosusināt un smidzināt mitrās pļavas, kur tas vairojas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'lv', 'Septiņpunktu mārīte', 'Viena mārīte savas dzīves laikā apēd tūkstošiem laputu.', 'No pavasara līdz rudenim uz augiem ar laputīm; ziemai tās sapulcējas grupās.', 'Paciešiet dažas laputis un izlaidiet smidzinājumus, lai mārītēm būtu ko ēst.', 'Atstājiet dobos stublājus un lapu nobiras, kur tās patveras ziemā.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'lv', 'Zemes kamene', 'Mātes ir starp pirmajām pavasara bitēm — tās dūc zemu, meklējot ligzdas alas.', 'No agra pavasara līdz rudenim uz ziediem; pavasarī mātes pārmeklē dzīvžogu pamatnes.', 'Audzējiet vai atstājiet agri ziedošus augus un ļaujiet āboliņam ziedēt zālienā.', 'Atstājiet netraucētas nogāzes un vecas peļu alas, kur saimes ierīko ligzdas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'lv', 'Medus bite', 'Vācējas pastāsta stropam, kur ir ziedi, dejojot astotnieka formā.', 'No pavasara līdz rudenim uz ziediem, siltās un bezvēja dienās.', 'Gādājiet, lai cauri sezonām mainītos dažādi ziedēšanas laiki, un nolieciet seklu ūdens trauku.', 'Nesmidziniet ziedošus augus un nekad ne dienas vidū.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'lv', 'Karaliskā spāre', 'Viena no lielākajām Eiropas spārēm: medījumu tā noķer pat lidojumā.', 'Siltās vasaras dienās vērojiet, kā tā patrulē pār dīķiem un ezeru malām.', 'Saglabājiet vai izrociet dīķi ar augiem un ļaujiet tā malām aizaugt.', 'Sargājiet dīķus no piesārņojuma un notecēm, lai kāpuri varētu attīstīties.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'lv', 'Parastā rudens spāre', 'Šīs spāres bieži nolaižas tajā pašā siltajā vietā un izšaujas pēc garām lidojošiem kukaiņiem.', 'No vasaras vidus līdz rudenim pie stāvošiem ūdeņiem, sildoties uz takām un mietiem.', 'Atstājiet saulainas nolaišanās vietas un augāju ap dīķiem un grāvjiem.', 'Neļaujiet mēslojumam vai eļļai ieskaloties dīķos, kur dzīvo kāpuri.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'lv', 'Sarkanā meža skudra', 'To kupolveida pūžņi pārsniedz metru augstumā un mitina pusmiljonu skudru.', 'No pavasara līdz rudenim skuju mežos; meklējiet kupolus no skujām.', 'Atstājiet skudru pūžņus neaiztiktus — to uzbūvēšana prasa gadus.', 'Turieties uz takām un nekad nespārdiet un nerociet skudru pūznī.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'lv', 'Baltā vizbulīte', 'Vizbulīte izplatās tik lēni, ka blīvi paklāji nodod vecu mežu.', 'Pavasarī meklējiet baltu ziedu paklājus, pirms koki salapo.', 'Atstājiet meža zemsedzi netraucētu, lai lēnās sakneņu saknes varētu plaukt.', 'Priecājieties par to tur, kur tā aug — plūkšana atņem ziedus, kas izplatījušies gadiem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'lv', 'Maijpuķīte', 'Katra šī saldi smaržojošā auga daļa ir indīga, ja to apēd.', 'Vēlā pavasarī sekojiet smaržai uz ēnainiem mežiem un ēnainiem dārziem.', 'Atstājiet vietā ēnainās meža malas un lapu nobiras, kur tā aug.', 'Neplūciet un nerociet to ārā, un turiet to prom no bērniem un mājdzīvniekiem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'lv', 'Lāču loks', 'Lāču loku parasti sajūtat pēc smaržas ilgi pirms ieraugāt tā baltos ziedus.', 'Pavasarī meklējiet platās zaļās lapas un zvaigžņveida ziedus mitros mežos.', 'Atstājiet mitros mežus netraucētus, lai paklāji katru gadu varētu ataugt.', 'Ja vākšana vietēji atļauta, ņemiet nedaudz un nekad neizraujiet sīpolus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'lv', 'Purva purene', 'Viens no senākajiem vietējiem augiem: Skandināvijā tas pārdzīvoja pēdējo ledus laikmetu.', 'Pavasarī meklējiet lielos zeltainos ziedus purvos, grāvjos un dīķu malās.', 'Uzturiet dīķu un grāvju malas mitras un nepļautas, lai tas varētu ziedēt.', 'Izvairieties nosusināt mitro zemi un atstājiet augus tur, kur tie aug.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'lv', 'Pavasara gaiļbiksīte', 'Gaiļbiksīte kādreiz bija tik izplatīta siena pļavās, ka bērni no tās vija bumbas.', 'Pavasarī meklējiet nokarenos dzeltenos ziedus vecās, nemēslotās pļavās.', 'Atstājiet pļavas nepļautas, līdz gaiļbiksīte ir noziedējusi un ienesusi sēklas.', 'Neplūciet un neizrociet to no dabas — pļavu ziedu kļūst arvien mazāk.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'lv', 'Parastā pīpene', 'Pīpenes „zieds” patiesībā ir desmitiem sīku ziediņu kopā.', 'Vasarā meklējiet lielās baltās pīpenes ceļmalās un pļavās.', 'Atstājiet zāles joslu nepļautu cauri vasaras vidum, lai tā varētu uzziedēt.', 'Izvairieties smidzināt ceļmalas un pļavas ar herbicīdiem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'lv', 'Ārstniecības pienene', 'Pienene ir viens no svarīgākajiem agrīnajiem nektāra avotiem bitēm.', 'No pavasara gandrīz visur; ziedi atveras saulē un aizveras krēslā.', 'Ļaujiet pienenēm uzziedēt zālienā pavasarī pirms pirmās pļaušanas.', 'Izlaidiet zāliena herbicīdus, lai agrīnie apputeksnētāji saglabātu šo barību.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'lv', 'Sila virsis', 'Viens virša krūmiņš var izveidot vairāk nekā simts tūkstošus sīku sēklu.', 'Vēlā vasarā meklējiet violetos paklājus atklātos silos un purvos.', 'Atbalstiet virsāju uzturēšanu atklātas un bez nosusināšanas.', 'Virsājos turieties uz takām un sausā laikā nekad nekuriniet uguni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'lv', 'Mellene', 'Mellenes iekrāso pirkstus zilus un baro visus — no putniem līdz lāčiem.', 'Vasarā meklējiet zemos krūmiņus ar tumšām ogām priežu un egļu mežos.', 'Atstājiet meža pamežu neskartu, lai zemie krūmiņi varētu nest augļus.', 'Ja lasīšana vietēji atļauta, atstājiet daudz ogu savvaļas dzīvniekiem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'lv', 'Brūklene', 'Brūklenes saglabājas mēnešiem, pateicoties dabiskam konservantam pašā ogā.', 'Vēlā vasarā un rudenī meklējiet spīdīgās sarkanās ogas uz mūžzaļiem paklājiem.', 'Atstājiet meža zemsedzes augāju netraucētu, lai paklāji varētu izplesties.', 'Ja lasīšana vietēji atļauta, ejiet uzmanīgi, lai nesaspiestu augus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'lv', 'Āra bērzs', 'Bērzs uztur simtiem kukaiņu sugu un tādējādi baro neskaitāmus putnus.', 'Visu gadu; baltā, lobošā miza padara to atpazīstamu jebkurā sezonā.', 'Atstājiet nokritušās bērza lapas un mirušo koksni: tās bagātina augsni un baro kukaiņus.', 'Izvairieties plēst mizu — tas ievaino un vājina koku.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'lv', 'Parastā egle', 'Zviedrijā egle aug no saknēm, kas ir tūkstošiem gadu vecas.', 'Visu gadu mežos; tās nokarenie čiekuri ir garākie no visām eglēm.', 'Atstājiet nokritušos čiekurus un mirušo koksni, kas patver kukaiņus un sēnes.', 'Mežā turieties uz takām, lai nesablīvētu seklās egles saknes.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'lv', 'Parastā priede', 'Vecas priedes galotnes tuvumā mirdz oranžas un var dzīvot gadsimtiem.', 'Visu gadu smilšainā un akmeņainā zemē; meklējiet oranžo mizu stumbra augšdaļā.', 'Atstājiet stāvošu mirušo koksni un vecas priedes — tās ir dzīvības pilnas.', 'Nekad nekuriniet uguni pie priedēm vai to tuvumā sausā, smilšainā zemē.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'lv', 'Līdaka', 'Līdaka ir slēpņa plēsējs, kas acumirklī izšaujas no pilnīga nekustīguma.', 'No pavasara līdz rudenim ezeru un lēnu upju aizaugušajos seklumos.', 'Atbalstiet niedrāju seklumu un ūdensaugu saglabāšanu, kur patveras mazuļi.', 'Neļaujiet piesārņojumam un atkritumiem nonākt ūdenī; ievērojiet vietējos zvejas noteikumus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'lv', 'Asaris', 'Asari medī bariem, un spilgtās svītras sadala to siluetu.', 'Siltākajos mēnešos ap laipām, ūdensaugu audzēm un straujiem dziļuma kritumiem.', 'Atbalstiet tīru ūdeni un zemūdens struktūras, kas patver mazās zivis.', 'Nekad neko nelejiet ezeros un upēs; ievērojiet vietējos zvejas noteikumus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'lv', 'Rauda', 'Rauda ir galvenā barības zivs, no kuras atkarīgi daudzi ezeru plēsēji.', 'Siltākajos mēnešos bariem netālu no ezeru un lēnu upju virsmas.', 'Atbalstiet tīru ūdeni un aizaugušus krastus, kas vajadzīgi nārstam.', 'Neļaujiet notecēm un atkritumiem nonākt ūdenī; ievērojiet vietējos zvejas noteikumus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'sl', 'Hudournik', 'Hudourniki lahko ostanejo v zraku po več mesecev in celo spijo med letom.', 'V toplih poletnih večerih glejte visoko nad strehe in prisluhnite kričečim jatam.', 'Namestite gnezdilnico pod napušč, preden se ptice spomladi vrnejo.', 'Pri prenovi ohranite drobne špranje pod napuščem, kjer gnezdijo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'sl', 'Kmečka lastovka', 'Kmečke lastovke se vsako leto selijo vse do južne Afrike in nazaj.', 'Od pomladi do zgodnje jeseni jih vidite nizko drseti nad polji in vodo.', 'Pustite vrata skednja ali lope priprta, da dosežejo svoje gnezdilne police.', 'Ne podirajte starih blatnih gnezd — lastovke jih uporabljajo leto za letom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'sl', 'Kukavica', 'Kukavica znese jajca v gnezda drugih ptic in nikoli ne vzgaja lastnih mladičev.', 'Pozno spomladi prisluhnite daljnemu „ku-ku“ z gozdnih robov.', 'Podprite z žuželkami bogate travnike in mejice, ki hranijo gostiteljske ptice kukavice.', 'Držite se poti ob grmiščih in trstičjih, da gostiteljske ptice niso vznemirjene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'sl', 'Taščica', 'Taščica srdito brani svoj teritorij in ob uličnih svetilkah poje vso noč.', 'Vse leto na vrtovih in v gozdovih; rada sledi tistemu, ki koplje, v upanju na deževnike.', 'Pustite kot vrta z odpadlim listjem, kjer lahko išče hrano.', 'Odložite močno obrezovanje živih mej, dokler se pozno poleti ne konča gnezdenje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'sl', 'Kos', 'Bogato, flavtasto petje samca je eno najbolj prepoznavnih v Evropi.', 'Vse leto; ob zori in mraku prisluhnite samcem, ki pojejo s streh in vrhov dreves.', 'Postavite svežo vodo za pitje in kopanje, zlasti v suhih obdobjih.', 'Med gnezdenjem imejte mačke ob svitu v hiši.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'sl', 'Brinovka', 'Brinovka je družaben drozg, ki pozimi tava v hrupnih, klepetavih jatah.', 'Jeseni in pozimi opazujte jate, kako obirajo jagode z mejic in jerebik.', 'Pustite grmovje z jagodami, kot sta jerebika in glog, čez zimo neobrezano.', 'Pustite padla jabolka pozimi na tleh — v mrazu so ključna hrana.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'sl', 'Velika sinica', 'Velika sinica ima ogromen glasovni repertoar in se novih klicev uči od sosed.', 'Vse leto; od konca zime prisluhnite zvenečemu petju iz dveh ponavljajočih se tonov.', 'Obesite gnezdilnico z odprtino 32 mm na mirno, senčno mesto.', 'Izogibajte se pesticidom na vrtu, da bo gosenic dovolj za hranjenje mladičev.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'sl', 'Plavček', 'Ena sama zalega plavčkov lahko poje več kot tisoč gosenic.', 'Vse leto na vrtovih in v gozdovih, pogosto visi z glavo navzdol na tankih vejicah.', 'Namestite majhno gnezdilnico z odprtino 25 mm proč od prevladujočih vetrov.', 'Spomladi izpustite insekticide, da gosenice ostanejo mladičem.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'sl', 'Ščinkavec', 'Petje ščinkavca se razlikuje od pokrajine do pokrajine, skoraj kot krajevna narečja.', 'Od pomladi do jeseni; samci pojejo jasno, padajočo frazo z odprtih vej.', 'Pustite čez sezono nekaj semenskih socvetij in zaraščenih kotičkov.', 'Krmilnice imejte čiste, da se med ščinkavci ne širijo bolezni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'sl', 'Šoja', 'Šoja vsako jesen zakoplje na tisoče želodov in z nekaj pozabljenimi zasadi cele hrastove gozdove.', 'Vse leto v hrastovih gozdovih; jeseni iščite bliske rožnate in modre barve.', 'Pustite padle želode in listni opad pod hrasti nedotaknjene.', 'Pse zadržite na gozdnih poteh, da ptice, ki se hranijo na tleh, niso preplašene.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'sl', 'Veliki detel', 'Spomladansko „bobnanje“ ni iskanje hrane, ampak hiter ritem, s katerim si lasti teritorij.', 'Vse leto; ob koncu zime prisluhnite bobnanju, ki odmeva skozi gozd.', 'Pustite stoječ mrtev les, ki gosti žuželke, s katerimi se detel hrani.', 'Ne posekajte mrtvih ali odmirajočih dreves, ki imajo lahko gnezdilne duplje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'sl', 'Bela pastirica', 'Nenehno zibanje repa morda sporoča pripravljenost na plenilce.', 'Od pomladi do jeseni ob vodi in na golih tleh, teka in se ustavlja, da ujame žuželke.', 'Ob vodi ohranite pas nizke trave ali proda, kjer lahko išče hrano.', 'Izogibajte se vznemirjanju prodišč in bregov, kjer se hrani in gnezdi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'sl', 'Žerjav', 'Žerjavi zgodaj spomladi izvajajo svatbene plese s skoki in prikloni.', 'Od pomladi do jeseni ob mokriščih; njihov trobentasti klic se sliši kilometre daleč.', 'Podprite varovanje neosušenih barij in mokrih travnikov, kjer žerjavi gnezdijo.', 'Gnezditvena mokrišča opazujte od daleč — žerjavi vznemirjena gnezda zapustijo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'sl', 'Labod pevec', 'Labod pevec se pari za vse življenje in prihod naznani z glasnimi, trobentastimi klici.', 'Spomladi in jeseni na jezerih in poplavljenih poljih, pogosto v družinskih skupinah.', 'Podprite ohranjanje plitvih jezerskih robov in mokrih polj brez osuševanja.', 'Labodov nikoli ne hranite s kruhom — škoduje jim; na ledu ohranite razdaljo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'sl', 'Mlakarica', 'Račji mladiči plavajo in se hranijo sami že nekaj ur po izvalitvi.', 'Vse leto na skoraj vsakem ribniku, jezeru ali počasni reki.', 'Če hranite race, uporabite oves, grah ali semena namesto kruha.', 'Spomladi pse zadržite proč od vode tam, kjer race gnezdijo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'sl', 'Kanja', 'Kanja jadra na širokih perutih in pogosto kliče z mačjim „piiii-jav“.', 'Od pomladi do jeseni; iščite jo, kako kroži visoko nad polji in gozdnimi robovi.', 'Podprite negojena travišča in robove polj, kjer živijo voluharice in drobni plen.', 'Nikoli ne uporabljajte strupov za glodavce: po prehranski verigi se dvignejo do ujed.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'sl', 'Ribji orel', 'Ribji orel se spusti z nogami naprej in nese plen, težak polovico njegove teže.', 'Od pomladi do jeseni ob velikih jezerih; opazujte lebdenje in nato dramatičen spust.', 'Podprite umetne gnezditvene ploščadi na visokih drogovih ob z ribami bogatih jezerih.', 'Gnezditvenim ploščadim se izognite v velikem loku, da parov ne preženete z jajc.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'sl', 'Rdeča lisica', 'Lisica si pri skoku na skrit plen pomaga z magnetnim poljem Zemlje.', 'Vse leto, najbolj dejavna ob zori in mraku ob gozdnih in poljskih robovih.', 'Pustite divji, nemoten kot, kjer lahko lisice počivajo in kopljejo brlog.', 'Zavarujte smetnjake in nikoli ne puščajte škodljivih ostankov hrane zunaj.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'sl', 'Evropski jež', 'Jež lahko v eni sami noči iskanja hrane prehodi nekaj kilometrov.', 'Od pomladi do jeseni po temi; pozimi prezimuje pod kupi listja in drv.', 'Izrežite v ograjah odprtino 13 cm, da lahko ježi prehajajo med vrtovi.', 'Pred košnjo preverite visoko travo in pustite kupe listja za prezimovanje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'sl', 'Srna', 'Srne odložijo brejost, da se mladiči vedno skotijo v začetku poletja.', 'Vse leto na gozdnih robovih, najbolj vidne pri paši ob zori in mraku.', 'Podprite nepokošene robove polj in grmišča, ki dajejo kritje in hrano.', 'V začetku poletja imejte pse ob gozdu na povodcu, ko mladiči ležijo skriti.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'sl', 'Los', 'Los je največji jelen na Zemlji; velik samec tehta več kot pol tone.', 'Vse leto v gozdovih in mokriščih, najbolj dejaven ob zori in mraku.', 'Podprite povezane gozdove in mokriščne koridorje, ki jih los potrebuje za gibanje.', 'Ob zori in mraku po gozdnih cestah vozite previdno in nikoli ne pristopajte k mladiču.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'sl', 'Navadna veverica', 'Veverica si zgradi več gnezd in se seli med njimi.', 'Vse leto v iglastih in mešanih gozdovih, najbolj dejavna zgodaj zjutraj.', 'Pustite storže, oreške in stoječa drevesa, iz katerih se hrani in v katerih gnezdi.', 'Pse zadržite na poteh in ne stresajte dreves, v katerih je lahko gnezdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'sl', 'Evropski bober', 'Bobrovi jezovi ustvarjajo mokrišča, ki kilometre daleč koristijo ribam, pticam in žuželkam.', 'Od pomladi do pozne jeseni ob počasnih rekah, najbolj dejaven v mraku.', 'Podprite ohranjanje bobrovih jezov in obvodnih dreves tam, kjer je to varno.', 'Držite se stran od bobrišč in jezov, zlasti dokler so mladiči majhni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'sl', 'Planinski zajec', 'Planinski zajec pozimi pobeli, da se zlije s snegom.', 'Vse leto na odprtih tleh in gozdnih jasah, predvsem ob zori in mraku.', 'Podprite mozaik odprtih površin in kritja, ki ga zajec potrebuje vse leto.', 'Na odprtih tleh imejte pse na povodcu, da počivajoči zajci niso preganjani.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'sl', 'Jazbec', 'Jazbeci živijo v družinskih skupinah v podzemnih rovih, ki se uporabljajo generacije.', 'Od pomladi do jeseni po temi ob gozdu; zimo prespijo.', 'Pustite nemotene brežine in mejice, kjer si jazbeci lahko izkopljejo rov.', 'Nikoli ne zasujte naseljenega rova in ne kopljite ob njem — to je njihov dolgoletni dom.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'sl', 'Mali netopir', 'Ta drobni netopir v eni noči poje do 3000 mušic in komarjev.', 'V poletnih večerih ob mraku opazujte hiter, sunkovit let nad vrtovi.', 'Pritrdite netopirnico visoko na steno ali drevo, ki ga ogreje večerno sonce.', 'Izogibajte se močni svetlobi ob vhodih v zatočišča in ohranite nočno nebo temno.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'sl', 'Koprivar', 'Ta metulj prezimi kot odrasel, pogosto v lopah in podstrešjih.', 'Od zgodnje pomladi do jeseni na sončnih cvetovih, zlasti na koprivah in metuljniku.', 'Pustite krpo kopriv v sončnem kotu — njegove gosenice jih potrebujejo.', 'Pozimi ne vznemirjajte metuljev, ki prezimujejo v lopah.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'sl', 'Dnevni pavlinček', 'Očesne pege se sunkovito odprejo, da prestrašijo ptice, krila pa pri tem lahko zasikajo.', 'Od pomladi do jeseni ob sončnih dneh na osatu, metuljniku in padlem sadju.', 'Pustite, da na soncu zraste krpa kopriv za njegove gosenice.', 'Ne vznemirjajte odraslih, ki pozimi prezimujejo v lopah in skladovnicah drv.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'sl', 'Citronček', 'Angleška beseda „butterfly“ morda izvira iz maslenorumene barve samca te vrste.', 'Eden prvih pomladnih metuljev; iščite ga ob gozdnih robovih v milih dneh.', 'Podprite krhliko in kozji češmin v mejicah, edini rastlini, ki ju jedo njegove gosenice.', 'Izogibajte se čiščenju grmovnatih mejic, ki nudijo zavetje prezimujočim odraslim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'sl', 'Oranžni belin', 'Le samci imajo živo oranžne konice kril; samice so bele.', 'Spomladi ob vlažnih travnikih in kolovozih, kjer raste travniška penuša.', 'Pustite penušo in česnovko rasti v vlažnih, nepokošenih kotih.', 'Odložite košnjo bankin, dokler gosenice ne končajo prehranjevanja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'sl', 'Navadni modrin', 'Gosenice tega modrina včasih negujejo mravlje, ki jih privlačijo njihovi sladki izločki.', 'Od pozne pomladi na sončnih traviščih, bogatih z deteljo in nokoto.', 'Pustite travišče nepokošeno, da lahko nokote in detelje zacvetijo.', 'Izogibajte se škropljenju travišč, bogatih s samoniklim cvetjem, s herbicidi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'sl', 'Repni belin', 'Čeprav je videti kot kapusov belin, ima raje samonikle rastline kot vrtnine.', 'Od pomladi do konca poletja na vlažnih travnikih, v jarkih in na gozdnih presekah.', 'Pustite vlažne kote podivjati s samoniklimi križnicami, kot je penuša.', 'Izogibajte se osuševanju in škropljenju vlažnih travnikov, kjer se razmnožuje.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'sl', 'Sedempikčasta pikapolonica', 'Ena sama pikapolonica v svojem življenju poje na tisoče listnih uši.', 'Od pomladi do jeseni na rastlinah z ušmi; pozimi se zbirajo v skupine za prezimovanje.', 'Prenesite nekaj uši in izpustite škropljenja, da imajo pikapolonice kaj jesti.', 'Pustite votla stebla in listni opad, kjer se čez zimo zatečejo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'sl', 'Zemeljski čmrlj', 'Matice so med prvimi čebelami spomladi in nizko brenčijo v iskanju gnezdilnih lukenj.', 'Od zgodnje pomladi do jeseni na cvetovih; spomladi matice preiskujejo vznožja mejic.', 'Gojite ali ohranite zgodaj cvetoče rastline in pustite deteljo cveteti v trati.', 'Pustite nemotene brežine in stare mišje luknje, kjer si kolonije uredijo gnezdo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'sl', 'Zahodna medonosna čebela', 'Nabiralke panju sporočijo, kje so cvetovi, tako da plešejo v obliki osmice.', 'Od pomladi do jeseni na cvetovih, ob toplih dneh brez vetra.', 'Poskrbite, da se čez sezone izmenjujejo različna cvetenja, in postavite plitvo posodo z vodo.', 'Ne škropite cvetočih rastlin in nikoli sredi dneva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'sl', 'Veliki kralj', 'Ena največjih evropskih kačjih pastirjev: plen ujame celo v zraku.', 'Ob toplih poletnih dneh ga opazujte, kako patruljira nad mlakami in jezerskimi robovi.', 'Ohranite ali izkopljite mlako z rastlinami in pustite njene robove zaraščene.', 'Mlake varujte pred onesnaženjem in spiranjem, da se ličinke lahko razvijejo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'sl', 'Navadni kamenjak', 'Ti kačji pastirji pogosto posedajo na istem toplem mestu in švignejo za mimoletečimi žuželkami.', 'Od sredine poletja do jeseni ob stoječih vodah, sončijo se na poteh in kolih.', 'Pustite sončna mesta za posedanje in rastlinje okoli mlak in jarkov.', 'Preprečite, da bi gnojila ali olja spirala v mlake, kjer živijo ličinke.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'sl', 'Rdeči gozdni mravljinec', 'Njihovi kopasti mravljišči presegajo meter višine in gostijo pol milijona mravelj.', 'Od pomladi do jeseni v iglastih gozdovih; iščite kopaste kupe iglic.', 'Pustite mravljišča nedotaknjena — za njihovo gradnjo je potrebnih več let.', 'Držite se poti in nikoli ne brcajte ali kopljite v mravljišče.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'sl', 'Podlesna vetrnica', 'Podlesna vetrnica se širi tako počasi, da gosti tepihi izdajajo star gozd.', 'Spomladi iščite tepihe belih cvetov, preden drevesa ozelenijo.', 'Pustite gozdna tla nemotena, da lahko počasne korenike uspevajo.', 'Uživajte v njej tam, kjer raste — trganje odvzame cvetove, ki so se širili leta.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'sl', 'Šmarnica', 'Vsak del te sladko dišeče rastline je ob zaužitju strupen.', 'Pozno spomladi sledite vonju do senčnih gozdov in zasenčenih vrtov.', 'Pustite na mestu senčne gozdne robove in listni opad, kjer raste.', 'Ne trgajte je in ne izkopavajte je ter jo hranite proč od otrok in domačih živali.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'sl', 'Čemaž', 'Čemaž običajno zavohate veliko prej, kot zagledate njegove bele cvetove.', 'Spomladi iščite široke zelene liste in zvezdaste cvetove v vlažnih gozdovih.', 'Pustite vlažne gozdove nemotene, da lahko tepihi vsako leto znova zrastejo.', 'Če je nabiranje krajevno dovoljeno, vzemite malo in nikoli ne izpulite čebulic.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'sl', 'Navadna kalužnica', 'Ena najstarejših samoniklih rastlin: v Skandinaviji je preživela zadnjo ledeno dobo.', 'Spomladi iščite velike zlate cvetove v močvirjih, jarkih in ob robovih mlak.', 'Robove mlak in jarkov ohranite vlažne in nepokošene, da lahko cveti.', 'Izogibajte se osuševanju mokrih tal in pustite rastline tam, kjer rastejo.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'sl', 'Trobentica', 'Trobentica je bila nekoč tako pogosta na senožetih, da so otroci iz nje delali žogice.', 'Spomladi iščite viseče rumene cvetove na starih, negnojenih travnikih.', 'Pustite travnike nepokošene, dokler trobentica ne odcveti in ne semeni.', 'Ne trgajte je in ne izkopavajte je iz narave — travniškega cvetja je vse manj.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'sl', 'Navadna ivanjščica', '„Cvet“ ivanjščice je v resnici na desetine drobnih cvetkov skupaj.', 'Poleti iščite velike bele ivanjščice ob cestah in na travnikih.', 'Pustite pas trave nepokošen čez vrhunec poletja, da lahko zacveti.', 'Izogibajte se škropljenju bankin in travnikov s herbicidi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'sl', 'Navadni regrat', 'Regrat je eden najpomembnejših zgodnjih virov nektarja za čebele.', 'Od pomladi naprej skoraj povsod; cvetovi se odprejo na soncu in zaprejo v mraku.', 'Pustite regrat spomladi zacveteti v trati pred prvo košnjo.', 'Izpustite herbicide za trato, da zgodnji opraševalci obdržijo to hrano.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'sl', 'Jesenska vresa', 'Ena sama rastlina vrese lahko ustvari več kot sto tisoč drobnih semen.', 'Pozno poleti iščite vijolične tepihe na odprtih resavah in barjih.', 'Podprite ohranjanje resav odprtih in brez osuševanja.', 'Na resavah se držite poti in v suhem vremenu nikoli ne kurite ognja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'sl', 'Borovnica', 'Borovnice pobarvajo prste modro in hranijo vse, od ptic do medvedov.', 'Poleti iščite nizko grmičevje s temnimi jagodami v borovih in smrekovih gozdovih.', 'Pustite gozdno podrast nedotaknjeno, da lahko nizko grmičevje obrodi.', 'Če je nabiranje krajevno dovoljeno, pustite obilo jagod divjim živalim.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'sl', 'Brusnica', 'Brusnice zdržijo mesece zaradi naravnega konzervansa v samem plodu.', 'Pozno poleti in jeseni iščite bleščeče rdeče jagode na vednozelenih preprogah.', 'Pustite rastlinje gozdnih tal nemoteno, da se lahko preproge širijo.', 'Če je nabiranje krajevno dovoljeno, stopajte previdno, da ne poteptate rastlin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'sl', 'Navadna breza', 'Breza vzdržuje na stotine vrst žuželk in s tem hrani nešteto ptic.', 'Vse leto; bela, luščeča se skorja jo naredi prepoznavno v vsakem letnem času.', 'Pustite padlo brezovo listje in mrtev les na tleh: bogatita prst in hranita žuželke.', 'Izogibajte se luščenju skorje, saj drevo rani in oslabi.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'sl', 'Navadna smreka', 'Na Švedskem smreka raste iz korenin, starih več tisoč let.', 'Vse leto v gozdovih; njeni viseči storži so najdaljši med vsemi smrekami.', 'Pustite padle storže in mrtev les, ki nudijo zavetje žuželkam in glivam.', 'V gozdu se držite poti, da ne zbijete plitvih smrekovih korenin.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'sl', 'Rdeči bor', 'Stari rdeči bori proti vrhu žarijo oranžno in lahko živijo stoletja.', 'Vse leto na peščenih in skalnatih tleh; iščite oranžno skorjo v zgornjem delu debla.', 'Pustite stoječ mrtev les in stare bore, ki so polni življenja.', 'Nikoli ne kurite ognja ob borih ali blizu njih na suhih, peščenih tleh.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'sl', 'Ščuka', 'Ščuka je zasedni plenilec, ki v trenutku plane iz popolne negibnosti.', 'Od pomladi do jeseni v zaraščenih plitvinah jezer in počasnih rek.', 'Podprite ohranjanje trstičnih plitvin in vodnih rastlin, kjer se zatekajo mladice.', 'Onesnaženje in smeti naj ne pridejo v vodo; upoštevajte krajevna ribiška pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'sl', 'Navadni ostriž', 'Ostriži lovijo v jatah, njihove izrazite proge pa razbijajo obris telesa.', 'V toplejših mesecih okoli pomolov, sestojev vodnih rastlin in strmih prehodov v globino.', 'Podprite čisto vodo in potopljene strukture, ki nudijo zavetje drobnim ribam.', 'Nikoli ničesar ne zlivajte v jezera in reke; upoštevajte krajevna ribiška pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'sl', 'Rdečeoka', 'Rdečeoka je ključna plenska riba, od katere je odvisnih veliko jezerskih plenilcev.', 'V toplejših mesecih v jatah blizu gladine jezer in počasnih rek.', 'Podprite čisto vodo in zaraščene bregove, potrebne za drstenje.', 'Spiranje in smeti naj ne pridejo v vodo; upoštevajte krajevna ribiška pravila.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'et', 'Piiritaja', 'Piiritajad võivad püsida õhus kuude kaupa ja magavad isegi lennates.', 'Soojadel suveõhtutel vaadake kõrgele katuste kohale ja kuulake kriiskavaid parvi.', 'Pange pesakast räästa alla enne, kui linnud kevadel tagasi jõuavad.', 'Remontides säilitage räästaalused väikesed pilud, kus nad pesitsevad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'et', 'Suitsupääsuke', 'Suitsupääsukesed rändavad igal aastal koguni Lõuna-Aafrikasse ja tagasi.', 'Kevadest varasügiseni näete neid madalalt üle avatud põldude ja vee libisemas.', 'Jätke küüni- või kuuriuks paokile, et nad pääseksid oma pesaäärteni.', 'Ärge lõhkuge vanu savipesasid — pääsukesed kasutavad neid aastast aastasse.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'et', 'Kägu', 'Kägu muneb teiste lindude pesadesse ega kasvata kunagi omaenda poegi.', 'Hiliskevadel kuulake metsaservadelt kaugele kostvat „ku-kuud“.', 'Toetage putukarikkaid niite ja hekke, mis toidavad käo kasvatajalinde.', 'Püsige radadel võsa ja roostiku lähedal, et kasvatajalinde ei häiritaks.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'et', 'Punarind', 'Punarind kaitseb oma territooriumi ägedalt ja laulab tänavalampide juures öö läbi.', 'Aasta läbi aedades ja metsades; järgneb meelsasti kaevajale, lootes vihmausse.', 'Jätke aianurka langenud lehed, kus ta saab toitu otsida.', 'Lükake tugev hekilõikus edasi, kuni pesitsemine hilissuvel lõpeb.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'et', 'Musträstas', 'Isaslinnu rikkalik, flöödine laul on üks Euroopa äratuntavamaid.', 'Aasta läbi; koidikul ja hämaras kuulake isaseid katustelt ja puulatvadelt laulmas.', 'Pange välja värsket vett joomiseks ja suplemiseks, eriti põuastel perioodidel.', 'Hoidke kassid pesitsusajal koidikul toas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'et', 'Hallrästas', 'Hallrästas on seltsiv rästas, kes talvel rändab lärmakates, siristavates parvedes.', 'Sügisel ja talvel jälgige, kuidas parved korjavad marju hekkidelt ja pihlakatelt.', 'Jätke marjapõõsad, nagu pihlakas ja viirpuu, talveks lõikamata.', 'Jätke langenud õunad talvel maha — külmaga on need eluliselt tähtis toit.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'et', 'Rasvatihane', 'Rasvatihasel on tohutu häälevaramu ja ta õpib uusi kutseid naabritelt.', 'Aasta läbi; talve lõpust kuulake helisevat, kahest korduvast noodist laulu.', 'Riputage 32 mm lennuavaga pesakast vaiksesse, varjulisse kohta.', 'Vältige aias pestitsiide, et röövikuid jaguks poegade toitmiseks.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'et', 'Sinitihane', 'Üksainus sinitihase pesakond võib ära süüa üle tuhande rööviku.', 'Aasta läbi aedades ja metsades, sageli rippudes pea alaspidi peentel okstel.', 'Pange üles väike 25 mm lennuavaga pesakast valdavate tuulte eest varju.', 'Jätke kevadel insektitsiidid tegemata, et röövikud jääksid poegadele.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'et', 'Metsvint', 'Metsvindi laul erineb piirkonniti, peaaegu nagu kohalikud murded.', 'Kevadest sügiseni; isased laulavad selget, langevat fraasi avatud oksalt.', 'Jätke hooajaks püsti mõned seemnepead ja umbrohused laigud.', 'Hoidke söötjad puhtad, et vintide seas ei leviks haigused.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'et', 'Pasknäär', 'Pasknäär matab igal sügisel tuhandeid tammetõrusid ja mõned unustades istutab terveid tammikuid.', 'Aasta läbi tammikutes; sügisel otsige roosade ja siniste värvide välgatusi.', 'Jätke langenud tammetõrud ja lehekõdu tammede all puutumata.', 'Hoidke koerad metsaradadel, et maapinnal toituvad linnud ei ehmuks lendu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'et', 'Suur-kirjurähn', 'Kevadine „trummeldamine“ pole toitumine, vaid kiire põrin, millega ta territooriumi nõuab.', 'Aasta läbi; talve lõpus kuulake trummeldamist läbi metsa kajamas.', 'Jätke püstine surnud puit alles — seal elavad putukad, kellest rähn toitub.', 'Ärge raiuge surnud või suremas puid, milles võib olla pesaõõnsus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'et', 'Linavästrik', 'Pidev sabaliputamine annab võib-olla märku valvsusest kiskjate suhtes.', 'Kevadest sügiseni vee ääres ja lagedal pinnasel, joostes ja peatudes putukaid haarama.', 'Hoidke vee ääres madala rohu või kruusa riba, kus ta saab toitu otsida.', 'Vältige kruusakallaste häirimist, kus ta toitub ja pesitseb.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'et', 'Sookurg', 'Sookured esitavad varakevadel kurameerimistantse hüpete ja kummardustega.', 'Kevadest sügiseni märgalade ümber; nende pasunahääl kostab kilomeetrite kaugusele.', 'Toetage kuivendamata rabade ja märgade niitude kaitset, kus kured pesitsevad.', 'Vaadelge pesitsusmärgalasid eemalt — häiritud pesa jätab kurg maha.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'et', 'Laululuik', 'Laululuik paaritub eluks ajaks ja teatab saabumisest valjude pasunahäältega.', 'Kevadel ja sügisel järvedel ja üleujutatud põldudel, sageli perekondade kaupa.', 'Toetage madalate järvekallaste ja märgade põldude säilitamist kuivendamata.', 'Ärge kunagi söötke luiki leivaga — see kahjustab neid; jääl hoidke vahet.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'et', 'Sinikael-part', 'Pardipojad ujuvad ja toituvad ise juba mõne tunni pärast koorumist.', 'Aasta läbi peaaegu igal tiigil, järvel või aeglasel jõel.', 'Kui parte söödate, kasutage leiva asemel kaera, herneid või seemneid.', 'Hoidke koerad kevadel veest eemal seal, kus pardid pesitsevad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'et', 'Hiireviu', 'Hiireviu hõljub laiadel tiibadel ja hüüab sageli kassiliku „piiii-jauga“.', 'Kevadest sügiseni; otsige teda kõrgel põldude ja metsaservade kohal tiirutamas.', 'Toetage niitmata rohumaid ja põlluservi, kus elavad uruhiired ja väike saak.', 'Ärge kunagi kasutage närilisemürke: need liiguvad toiduahelas üles röövlindudeni.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'et', 'Kalakotkas', 'Kalakotkas sööstab jalad ees ja suudab kanda saaki, mis kaalub poole tema enda kaalust.', 'Kevadest sügiseni suurte järvede ääres; jälgige paigallendu ja siis järsku sööstu.', 'Toetage tehispesaaluseid kõrgetel postidel kalarikaste järvede lähedal.', 'Möödu pesaalustest suure kaarega, et paarid ei ehmuks munade pealt ära.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'et', 'Rebane', 'Rebane kasutab Maa magnetvälja, et paremini hinnata hüpet peidetud saagile.', 'Aasta läbi, kõige aktiivsem koidikul ja hämaras metsa- ja põlluservades.', 'Jätke metsik, häirimatu nurk, kus rebased saavad puhata ja urgu kaevata.', 'Kinnitage prügikastid ja ärge kunagi jätke välja kahjulikke toidujäätmeid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'et', 'Siil', 'Siil võib ühe toiduotsimisöö jooksul läbida paar kilomeetrit.', 'Kevadest sügiseni pärast pimedat; talvel talvitub lehe- ja puuriitade all.', 'Lõigake aedadesse 13 cm ava, et siilid saaksid aedade vahel liikuda.', 'Kontrollige enne niitmist kõrget rohtu ja jätke lehehunnikud talvitumiseks.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'et', 'Metskits', 'Metskitsed lükkavad tiinuse edasi, et pojad sünniksid alati varasuvel.', 'Aasta läbi metsaservades, kõige paremini näha koidikul ja hämaras söömas.', 'Toetage niitmata põlluservi ja võsa, mis pakuvad varju ja toitu.', 'Hoidke koerad varasuvel metsa ääres rihma otsas, kui pojad lamavad peidus.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'et', 'Põder', 'Põder on maailma suurim hirvlane; suur pull kaalub üle poole tonni.', 'Aasta läbi metsades ja märgaladel, kõige aktiivsem koidikul ja hämaras.', 'Toetage sidusaid metsi ja märgalakoridore, mida põder liikumiseks vajab.', 'Sõitke koidikul ja hämaras metsateedel ettevaatlikult ja ärge kunagi lähenege vasikale.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'et', 'Orav', 'Orav ehitab mitu pesa ja liigub nende vahel.', 'Aasta läbi okas- ja segametsades, kõige toimekam varahommikul.', 'Jätke käbid, pähklid ja püstised puud, millest ta toitub ja milles pesitseb.', 'Hoidke koerad radadel ja ärge raputage puid, milles võib olla pesa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'et', 'Kobras', 'Kopratammid loovad märgalasid, mis aitavad kilomeetrite kaugusele kalu, linde ja putukaid.', 'Kevadest hilissügiseni aeglaste jõgede ääres, kõige aktiivsem hämaras.', 'Toetage kopratammide ja kaldapuude paigalejätmist seal, kus see on ohutu.', 'Hoidke koprapesadest ja tammidest eemale, eriti kui pojad on väikesed.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'et', 'Valgejänes', 'Valgejänes muutub talvel valgeks, et lumega ühte sulada.', 'Aasta läbi lagedatel aladel ja raiesmikel, peamiselt koidikul ja hämaras.', 'Toetage lageda ala ja varju mosaiiki, mida jänes aasta läbi vajab.', 'Hoidke koerad lagedal rihma otsas, et puhkavaid jäneseid ei aetaks taga.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'et', 'Mäger', 'Mägrad elavad perekondadena maa-alustes urgudes, mida kasutatakse põlvkondi.', 'Kevadest sügiseni pärast pimedat metsa lähedal; talve magavad nad läbi.', 'Jätke häirimatuks kaldaperved ja hekid, kuhu mägrad saavad urud kaevata.', 'Ärge kunagi ummistage asustatud urgu ega kaevake selle kõrval — see on nende pikaaegne kodu.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'et', 'Kääbus-nahkhiir', 'See pisike nahkhiir sööb ühe öö jooksul kuni 3000 sääske ja kihulast.', 'Suveõhtutel jälgige hämaras kiiret, nõksuvat lendu aedade kohal.', 'Kinnitage nahkhiirekast kõrgele seinale või puule, kuhu paistab õhtupäike.', 'Vältige eredat valgust varjepaikade sissepääsude juures ja hoidke ööpimedus alles.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'et', 'Väike-koerliblikas', 'See liblikas talvitub täiskasvanuna, sageli kuurides ja pööningutel.', 'Varakevadest sügiseni päikeselistel õitel, eriti nõgestel ja liblikapõõsal.', 'Jätke päikeselisse nurka nõgeselaik — tema röövikud vajavad neid.', 'Ärge häirige talvel kuurides talvituvaid liblikaid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'et', 'Päevapaabusilm', 'Silmatäpid avanevad järsku, et linde ehmatada, ja tiivad võivad seejuures sisiseda.', 'Kevadest sügiseni päikesepaistelistel päevadel ohakatel, liblikapõõsal ja langenud viljadel.', 'Laske päikeselises kohas kasvada nõgeselaik tema röövikutele.', 'Ärge häirige täiskasvanuid, kes talvituvad kuurides ja puuriitades.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'et', 'Lapsuliblikas', 'Ingliskeelne sõna „butterfly“ tuleneb võib-olla selle liigi isaslooma võikollasest värvist.', 'Üks kevade esimesi liblikaid; otsige teda metsaservadest pehmetel päevadel.', 'Toetage paakspuud hekkides — ainsat taime, mida tema röövikud söövad.', 'Vältige võsastunud hekkide puhastamist, mis varjavad talvituvaid täiskasvanuid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'et', 'Koiduliblikas', 'Ainult isastel on eredalt oranžid tiivaotsad; emased on valged.', 'Kevadel niiskete niitude ja teeäärte ääres, kus kasvab jürilill.', 'Laske jürilillel ja küüslaugurohul kasvada niisketes, niitmata nurkades.', 'Lükake teeperveniitmine edasi, kuni röövikud on toitumise lõpetanud.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'et', 'Ristiku-sinitiib', 'Selle liblika röövikuid hoolitsevad vahel sipelgad, keda meelitavad nende magusad eritised.', 'Hiliskevadest päikeselistel rohumaadel, kus on rohkelt ristikut ja nõiahammast.', 'Jätke rohumaa niitmata, et nõiahambad ja ristikud saaksid õitseda.', 'Vältige metslilledest rikaste rohumaade pritsimist umbrohutõrjevahendiga.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'et', 'Naeriliblikas', 'Kuigi ta näeb välja nagu kapsaliblikas, eelistab ta metsikuid taimi aiakultuuridele.', 'Kevadest hilissuveni niisketel niitudel, kraavides ja metsasihtidel.', 'Laske niisketel nurkadel metsistuda kohalike ristõielistega, nagu jürilill.', 'Vältige niiskete niitude kuivendamist ja pritsimist, kus ta paljuneb.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'et', 'Seitsetäpp-lepatriinu', 'Üksainus lepatriinu sööb oma elu jooksul tuhandeid lehetäisid.', 'Kevadest sügiseni lehetäidega taimedel; talveks kogunevad nad rühmadesse.', 'Taluge mõnda lehetäid ja jätke pritsimised ära, et lepatriinudel oleks toitu.', 'Jätke õõnsad varred ja lehekõdu, kus nad talve üle elavad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'et', 'Maakimalane', 'Emad on kevade esimeste mesilaste seas, sumisedes madalalt pesaauke otsimas.', 'Varakevadest sügiseni õitel; kevadel otsivad emad läbi hekkide alused.', 'Kasvatage või jätke alles varakult õitsevad taimed ja laske ristikul murus õitseda.', 'Jätke häirimatuks kaldaperved ja vanad hiireurud, kuhu pered pesa rajavad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'et', 'Meemesilane', 'Korjemesilased näitavad tarule kaheksakujulise tantsuga, kus õied asuvad.', 'Kevadest sügiseni õitel, soojadel ja tuulevaiksetel päevadel.', 'Hoolitsege, et hooaegade lõikes vahelduksid eri õitsemised, ja pange välja madal veekauss.', 'Ärge pritsige õitsvaid taimi ja mitte kunagi keset päeva.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'et', 'Keisertutikas', 'Üks Euroopa suurimaid kiile: ta püüab saaki isegi õhus.', 'Soojadel suvepäevadel jälgige, kuidas ta patrullib tiikide ja järvekallaste kohal.', 'Säilitage või kaevake taimedega tiik ja laske selle servadel rohtuda.', 'Hoidke tiigid reostusest ja pinnaveest puhtad, et vastsed saaksid areneda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'et', 'Harilik verikiil', 'Need kiilid istuvad sageli samale soojale kohale ja söövitavad mööduvate putukate järele.', 'Kesksuvest sügiseni seisva vee ääres, päikest võtmas radadel ja postidel.', 'Jätke päikeselised istumiskohad ja taimestik tiikide ja kraavide ümber.', 'Vältige väetise või õli uhtumist tiikidesse, kus vastsed elavad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'et', 'Punane metskuklane', 'Nende kuplikujulised pesad ulatuvad üle meetri kõrguseks ja mahutavad pool miljonit sipelgat.', 'Kevadest sügiseni okasmetsades; otsige okastest kuhilaid.', 'Jätke sipelgapesad puutumata — nende ehitamine võtab aastaid.', 'Püsige radadel ja ärge kunagi lööge ega kaevake sipelgapessa.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'et', 'Võsaülane', 'Võsaülane levib nii aeglaselt, et tihedad vaibad reedavad vana metsa.', 'Kevadel otsige valgete õite vaipu enne, kui puud lehte lähevad.', 'Jätke metsapõrand puutumata, et aeglased risoomid saaksid edeneda.', 'Nautige teda seal, kus ta kasvab — korjamine võtab õisi, mis levisid aastaid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'et', 'Maikelluke', 'Iga osa sellest magusalõhnalisest taimest on allaneelamisel mürgine.', 'Hiliskevadel minge lõhna järgi varjulistesse metsadesse ja varjulistesse aedadesse.', 'Jätke paigale varjulised metsaservad ja lehekõdu, kus ta kasvab.', 'Ärge korjake ega kaevake teda üles ning hoidke lastest ja lemmikloomadest eemal.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'et', 'Karulauk', 'Karulauku tunnete lõhna järgi tavaliselt ammu enne, kui näete tema valgeid õisi.', 'Kevadel otsige laiu rohelisi lehti ja tähtjaid õisi niisketest metsadest.', 'Jätke niisked metsad puutumata, et vaibad saaksid igal aastal tagasi kasvada.', 'Kui korjamine on kohapeal lubatud, võtke vähe ja ärge kunagi kiskuge sibulaid välja.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'et', 'Harilik varsakabi', 'Üks vanimaid kohalikke taimi: Skandinaavias elas ta üle viimase jääaja.', 'Kevadel otsige suuri kuldseid õisi soodest, kraavidest ja tiigikallastelt.', 'Hoidke tiigi- ja kraaviservad niisked ja niitmata, et ta saaks õitseda.', 'Vältige märja maa kuivendamist ja jätke taimed sinna, kus nad kasvavad.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'et', 'Harilik nurmenukk', 'Nurmenukk oli heinamaadel kunagi nii tavaline, et lapsed tegid neist palle.', 'Kevadel otsige noogutavaid kollaseid õisi vanadelt, väetamata niitudelt.', 'Jätke niidud niitmata, kuni nurmenukk on õitsenud ja seemned moodustanud.', 'Ärge korjake ega kaevake teda loodusest — niidulilled on kahanemas.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'et', 'Harilik härjasilm', 'Härjasilma „õis“ on tegelikult kümneid pisikesi õisi koos.', 'Suvel otsige suuri valgeid härjasilmi teeäärtest ja niitudelt.', 'Jätke rohuriba läbi kesksuve niitmata, et ta saaks õitseda.', 'Vältige teepervede ja niitude pritsimist umbrohutõrjevahendiga.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'et', 'Harilik võilill', 'Võilill on mesilaste üks tähtsamaid varaseid nektariallikaid.', 'Kevadest alates peaaegu kõikjal; õied avanevad päikeses ja sulguvad hämaras.', 'Laske võililledel kevadel murus õitseda enne esimest niitmist.', 'Jätke murutõrjevahendid tegemata, et varajased tolmeldajad selle toidu säilitaksid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'et', 'Harilik kanarbik', 'Üksainus kanarbikutaim võib anda üle saja tuhande pisikese seemne.', 'Hilissuvel otsige lillasid vaipu lagedatelt nõmmedelt ja rabadest.', 'Toetage nõmmede hoidmist lagedana ja kuivendamata.', 'Püsige nõmmedel radadel ja ärge kunagi tehke kuiva ilmaga lõket.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'et', 'Mustikas', 'Mustikad värvivad sõrmed siniseks ja toidavad kõiki lindudest karudeni.', 'Suvel otsige madalaid tumedate marjadega põõsaid männi- ja kuusemetsadest.', 'Jätke metsaalune puutumata, et madalad põõsad saaksid vilja kanda.', 'Kui korjamine on kohapeal lubatud, jätke ohtralt marju loomadele.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'et', 'Pohl', 'Pohlad säilivad kuid tänu marjas endas leiduvale looduslikule säilitusainele.', 'Hilissuvel ja sügisel otsige läikivaid punaseid marju igihaljastelt vaipadelt.', 'Jätke metsaaluse taimestik puutumata, et vaibad saaksid levida.', 'Kui korjamine on kohapeal lubatud, astuge ettevaatlikult, et taimi mitte muljuda.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'et', 'Arukask', 'Kask peab ülal sadu putukaliike ja toidab nõnda loendamatuid linde.', 'Aasta läbi; valge kooruv koor teeb ta äratuntavaks igal aastaajal.', 'Jätke langenud kaselehed ja surnud puit maha: need rikastavad mulda ja toidavad putukaid.', 'Vältige koore rebimist, mis vigastab ja nõrgestab puud.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'et', 'Harilik kuusk', 'Rootsis kasvab kuusk juurtest, mis on tuhandeid aastaid vanad.', 'Aasta läbi metsades; tema rippuvad käbid on kõigist kuuskedest pikimad.', 'Jätke langenud käbid ja surnud puit maha, need pakuvad peavarju putukatele ja seentele.', 'Püsige metsas radadel, et mitte tallata kuuse pindmisi juuri kokku.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'et', 'Harilik mänd', 'Vanad männid hõõguvad ladva lähedal oranžilt ja võivad elada sajandeid.', 'Aasta läbi liivasel ja kivisel pinnasel; otsige tüve ülaosa oranži koort.', 'Jätke püstine surnud puit ja vanad männid alles — need on elust kubisevad.', 'Ärge kunagi tehke lõket mändide vastu ega nende lähedal kuival liivasel pinnasel.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'et', 'Haug', 'Haug on varitsev kiskja, kes sööstab liikumatusest välja silmapilkselt.', 'Kevadest sügiseni järvede ja aeglaste jõgede taimestunud madalikel.', 'Toetage roostikuga madalike ja veetaimede säilitamist, kus noorkalad varjuvad.', 'Hoidke reostus ja prügi veest eemal; järgige kohalikke kalastusreegleid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'et', 'Ahven', 'Ahvenad jahivad parvedes ja nende selged triibud lõhuvad keha piirjooned.', 'Soojematel kuudel sildade, taimestikualade ja järskude sügavuste ümber.', 'Toetage puhast vett ja veealuseid struktuure, mis varjavad väikseid kalu.', 'Ärge kunagi kallake midagi järvedesse ja jõgedesse; järgige kohalikke kalastusreegleid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'et', 'Särg', 'Särg on tähtis saakkala, kellest sõltuvad paljud järvekiskjad.', 'Soojematel kuudel parvedes järvede ja aeglaste jõgede pinna lähedal.', 'Toetage puhast vett ja taimestunud kaldaid, mida kudemiseks vajatakse.', 'Hoidke pinnavesi ja prügi veest eemal; järgige kohalikke kalastusreegleid.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-swift', 'ar', 'السمامة الشائعة', 'تستطيع السمامة البقاء في الجو شهورًا متواصلة، حتى أنها تنام وهي تطير.', 'في أمسيات الصيف الدافئة، راقب السماء فوق أسطح المنازل وأنصت لأسرابها الصاخبة.', 'ركّب صندوق تعشيش للسمامة تحت طنف السقف قبل عودتها في الربيع.', 'عند ترميم المبنى، حافظ على الفجوات الصغيرة تحت الطنف حيث تعشش السمامة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('barn-swallow', 'ar', 'سنونو المنازل', 'يهاجر سنونو المنازل إلى جنوب أفريقيا ويعود كل عام.', 'من الربيع إلى أوائل الخريف، ابحث عنه وهو ينساب منخفضًا فوق الحقول المفتوحة والمياه.', 'اترك باب الحظيرة أو المخزن مواربًا ليصل إلى حواف أعشاشه.', 'تجنّب إزالة الأعشاش الطينية القديمة؛ فالسنونو يعيد استخدامها عامًا بعد عام.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-cuckoo', 'ar', 'الوقواق الأوروبي', 'يضع الوقواق بيضه في أعشاش طيور أخرى ولا يربّي صغاره بنفسه أبدًا.', 'في أواخر الربيع، أنصت لنداء «كوكو» الممتد القادم من أطراف الغابات.', 'ادعم المروج والسياج النباتية الغنية بالحشرات التي تغذّي الطيور التي يعتمد عليها الوقواق.', 'التزم بالمسارات قرب الأدغال ومنابت القصب حتى لا تُزعج الطيور المضيفة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-robin', 'ar', 'أبو الحناء الأوروبي', 'أبو الحناء شديد الدفاع عن أرضه، وقد يغرّد طوال الليل قرب أضواء الشوارع.', 'طوال العام في الحدائق والغابات؛ وكثيرًا ما يتبع من يقلّب التربة طمعًا في الديدان.', 'اترك ركنًا من الحديقة مغطى بأوراق الشجر المتساقطة ليبحث فيه عن غذائه.', 'أجّل تقليم السياج النباتية الكثيف حتى ينتهي موسم التعشيش في أواخر الصيف.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blackbird', 'ar', 'الشحرور الأسود', 'تغريد الذكر الغني الشبيه بالناي من أشهر أصوات الطيور في أوروبا.', 'طوال العام؛ أنصت للذكور وهي تغرّد من الأسطح وقمم الأشجار عند الفجر والغروب.', 'ضع ماءً عذبًا للشرب والاستحمام، خاصة في فترات الجفاف.', 'أبقِ القطط داخل المنزل عند الفجر خلال موسم التعشيش.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('fieldfare', 'ar', 'السمنة الحقلية', 'السمنة الحقلية طائر اجتماعي يتنقل في أسراب شتوية صاخبة.', 'في الخريف والشتاء، راقب الأسراب وهي تلتهم التوت من السياج وأشجار الغبيراء.', 'اترك الشجيرات المثمرة بالتوت مثل الغبيراء والزعرور دون تقليم خلال الشتاء.', 'اترك التفاح المتساقط على الأرض في الشتاء؛ فهو غذاء حيوي في البرد.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-tit', 'ar', 'القرقف الكبير', 'للقرقف الكبير حصيلة صوتية واسعة، ويتعلم نداءات جديدة من جيرانه.', 'طوال العام؛ أنصت لتغريده الرنان المتكرر بدءًا من أواخر الشتاء.', 'علّق صندوق تعشيش بفتحة قطرها ٣٢ ملم في مكان هادئ ومظلل.', 'تجنّب مبيدات الحدائق ليبقى ما يكفي من اليرقات لإطعام الصغار.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('blue-tit', 'ar', 'القرقف الأزرق', 'حضنة واحدة من القرقف الأزرق قد تلتهم أكثر من ألف يرقة.', 'طوال العام في الحدائق والغابات، وغالبًا ما يتدلى رأسًا على عقب من الأغصان الرفيعة.', 'ركّب صندوق تعشيش صغيرًا بفتحة قطرها ٢٥ ملم بعيدًا عن اتجاه الرياح السائدة.', 'امتنع عن المبيدات الحشرية في الربيع لتتوفر اليرقات للصغار.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-chaffinch', 'ar', 'الحسون الشائع', 'يختلف تغريد الحسون من منطقة إلى أخرى، أشبه ما يكون بلهجات محلية.', 'من الربيع إلى الخريف؛ تغرّد الذكور بجملة نازلة واضحة من أماكن مكشوفة.', 'اترك بعض رؤوس البذور والبقع العشبية قائمة خلال الموسم.', 'حافظ على نظافة مغذّيات الطيور لمنع انتشار الأمراض بينها.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('eurasian-jay', 'ar', 'القيق الأوراسي', 'يدفن القيق آلاف حبات البلوط كل خريف، وينسى بعضها فيزرع غابات بلوط كاملة.', 'طوال العام في غابات البلوط؛ ترقّب ومضات الوردي والأزرق في الخريف.', 'اترك ثمار البلوط المتساقطة وأوراق الشجر تحت البلوط دون عبث.', 'أبقِ الكلاب على المسارات في الغابة حتى لا تُفزع الطيور التي تتغذى على الأرض.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('great-spotted-woodpecker', 'ar', 'نقار الخشب المرقط الكبير', 'قرعه السريع في الربيع ليس بحثًا عن الطعام بل إعلانٌ عن حدود أرضه.', 'طوال العام؛ في أواخر الشتاء أنصت لصدى القرع بين الأشجار.', 'اترك الأخشاب الميتة القائمة، فهي تأوي الحشرات التي يتغذى عليها.', 'لا تقطع الأشجار الميتة أو المحتضرة، فقد تحوي أعشاشًا داخل جذوعها.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('white-wagtail', 'ar', 'الذعرة البيضاء', 'هزّ الذيل المستمر لدى الذعرة قد يكون إشارة تنبّه في وجه المفترسات.', 'من الربيع إلى الخريف قرب المياه والأرض المكشوفة، تركض وتتوقف لالتقاط الحشرات.', 'حافظ على رقعة من العشب القصير أو الحصى قرب الماء لتبحث فيها عن غذائها.', 'تجنّب إزعاج ضفاف الحصى والشواطئ حيث تتغذى الذعرة وتعشش.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-crane', 'ar', 'الكركي الرمادي', 'يؤدي الكركي رقصات مغازلة يقفز فيها وينحني في أوائل الربيع.', 'من الربيع إلى الخريف حول الأراضي الرطبة؛ أنصت لنداءاته البوقية التي تُسمع من مسافات بعيدة.', 'ادعم حماية المستنقعات والمروج الرطبة غير المجفَّفة حيث يتكاثر الكركي.', 'راقب الأراضي الرطبة من بعيد؛ فالكركي يهجر عشه إذا أُزعج.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('whooper-swan', 'ar', 'البجعة الصداحة', 'تتزاوج البجعة الصداحة مدى الحياة وتعلن وصولها بنداءات بوقية عالية.', 'في الربيع والخريف على البحيرات والحقول المغمورة، وغالبًا في مجموعات عائلية.', 'ادعم إبقاء حواف البحيرات الضحلة والحقول الرطبة دون تجفيف.', 'لا تُطعم البجع الخبز أبدًا فهو يضرّه، وابقَ على مسافة منه فوق الجليد.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mallard', 'ar', 'البط الأخضر الرأس', 'تستطيع صغار البط السباحة وإطعام نفسها خلال ساعات من الفقس.', 'طوال العام في أي بركة أو بحيرة أو نهر بطيء الجريان تقريبًا.', 'إن أطعمت البط، فاستخدم الشوفان أو البازلاء أو البذور بدل الخبز.', 'أبعد الكلاب عن المياه حيث يعشش البط في الربيع.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-buzzard', 'ar', 'الحوّام الشائع', 'يحلّق الحوّام بجناحين عريضين وكثيرًا ما يصيح صيحة تشبه مواء القط.', 'من الربيع إلى الخريف؛ ابحث عنه وهو يحلّق دائريًا فوق الحقول وأطراف الغابات.', 'ادعم المراعي الخشنة وحواف الحقول التي تأوي فئران الحقل والفرائس الصغيرة.', 'لا تستخدم سموم القوارض إطلاقًا؛ فهي تصعد السلسلة الغذائية إلى الجوارح.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('osprey', 'ar', 'العقاب النساري', 'ينقضّ العقاب النساري بقدميه أولًا لاصطياد السمك، وقد يحمل فريسة بنصف وزنه.', 'من الربيع إلى الخريف قرب البحيرات الكبيرة؛ ترقّبه وهو يرفرف ثابتًا ثم ينقضّ.', 'ادعم إقامة منصات تعشيش صناعية على أعمدة عالية قرب البحيرات الغنية بالسمك.', 'ابتعد كثيرًا عن منصات التعشيش حتى لا تهرب الأزواج تاركةً بيضها.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-fox', 'ar', 'الثعلب الأحمر', 'يستعين الثعلب بالمجال المغناطيسي للأرض ليقدّر وثبته على فريسة مختبئة.', 'طوال العام، وأنشط ما يكون عند الفجر والغروب على أطراف الغابات والحقول.', 'اترك ركنًا بريًا هادئًا يستطيع الثعلب أن يستريح ويحفر جحره فيه.', 'أحكم إغلاق حاويات النفايات ولا تترك بقايا طعام ضارة للثعالب.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-hedgehog', 'ar', 'القنفذ الأوروبي', 'قد يقطع القنفذ كيلومترين في ليلة واحدة بحثًا عن الطعام.', 'من الربيع إلى الخريف بعد حلول الظلام؛ وفي الشتاء يبيت تحت أكوام الأوراق والجذوع.', 'افتح فجوة بعرض ١٣ سم في السياج ليتنقل القنفذ بين الحدائق.', 'افحص العشب الطويل قبل قصّه واترك أكوام الأوراق لسباته الشتوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roe-deer', 'ar', 'الأيل الأوروبي الصغير', 'يؤخّر الأيل الأوروبي الصغير حمله لتولد صغاره دائمًا في أوائل الصيف.', 'طوال العام على أطراف الغابات، وأوضح ما يكون وهو يرعى عند الفجر والغروب.', 'ادعم حواف الحقول غير المقصوصة والأدغال التي تمنح الأيل الغطاء والغذاء.', 'أبقِ الكلاب مربوطة قرب الغابات في أوائل الصيف حين تختبئ الصغار.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('moose', 'ar', 'الأيل الضخم (الموظ)', 'الموظ أكبر أنواع الأيائل على الأرض؛ وقد يتجاوز وزن الذكر الضخم نصف طن.', 'طوال العام في الغابات والأراضي الرطبة، وأنشط ما يكون عند الفجر والغروب.', 'ادعم ترابط الغابات وممرات الأراضي الرطبة التي يحتاجها الموظ للتنقل.', 'قُد بحذر عند الفجر والغروب على طرق الغابات، ولا تقترب من صغير أبدًا.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-squirrel', 'ar', 'السنجاب الأحمر', 'يبني السنجاب الأحمر عدة أعشاش وينتقل بينها.', 'طوال العام في الغابات الصنوبرية والمختلطة، وأنشط ما يكون في الصباح الباكر.', 'اترك أكواز الصنوبر والمكسّرات والأشجار القائمة التي يتغذى ويعشش فيها.', 'أبقِ الكلاب على المسارات وتجنّب إزعاج الأشجار التي قد تحوي عشًا.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-beaver', 'ar', 'القندس الأوروبي', 'تُنشئ سدود القندس أراضي رطبة تنعش الأسماك والطيور والحشرات لمسافات طويلة.', 'من الربيع إلى أواخر الخريف حول الأنهار البطيئة، وأنشط ما يكون عند الغسق.', 'ادعم ترك سدود القندس وأشجار ضفاف الماء في مكانها حيث يكون ذلك آمنًا.', 'ابتعد عن الأوكار والسدود، خصوصًا حين تكون الصغار حديثة الولادة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('mountain-hare', 'ar', 'أرنب الجبل', 'يتحول فراء أرنب الجبل إلى الأبيض في الشتاء ليتمويه على الثلج.', 'طوال العام في الأراضي المكشوفة وفجوات الغابات، وغالبًا عند الفجر والغروب.', 'ادعم مزيجًا من الأرض المكشوفة والغطاء النباتي يحتاجه الأرنب على مدار العام.', 'أبقِ الكلاب مربوطة في الأراضي المكشوفة حتى لا تُطارَد الأرانب المستريحة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-badger', 'ar', 'الغرير الأوروبي', 'يعيش الغرير في مجموعات عائلية داخل جحور تُستخدم عبر أجيال.', 'من الربيع إلى الخريف بعد حلول الظلام قرب الغابات؛ وينام معظم الشتاء.', 'اترك الضفاف والسياج النباتية دون عبث ليحفر الغرير جحوره فيها.', 'لا تسدّ جحرًا نشطًا ولا تحفر قربه؛ فهو بيته الدائم.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-pipistrelle', 'ar', 'الخفاش القزم', 'يستطيع هذا الخفاش الصغير التهام ٣٠٠٠ من البعوض والحشرات الصغيرة في ليلة واحدة.', 'في أمسيات الصيف، راقب طيرانه السريع المتعرّج فوق الحدائق عند الغسق.', 'ركّب صندوق خفافيش عاليًا على جدار أو شجرة تصلها شمس المساء.', 'تجنّب الأضواء الساطعة عند مداخل المأوى وأبقِ سماء الليل مظلمة للخفافيش.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('small-tortoiseshell', 'ar', 'فراشة السلحفاة الصغيرة', 'تقضي هذه الفراشة سباتها الشتوي وهي بالغة، وغالبًا داخل المخازن والعلّيات.', 'من أوائل الربيع إلى الخريف على الأزهار المشمسة، خاصة القُرّاص والبَدْليَة.', 'اترك رقعة من نبات القُرّاص في ركن مشمس؛ فيرقاتها تحتاجه.', 'اترك الفراشات الساكنة في سباتها داخل المخازن دون إزعاج طوال الشتاء.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-peacock', 'ar', 'فراشة الطاووس', 'تومض بقعها الشبيهة بالعيون لتُفزع الطيور، وقد تُصدر جناحاها فحيحًا عند فتحهما.', 'من الربيع إلى الخريف في الأيام المشمسة، تتغذى على الشوك والبَدْليَة والفاكهة المتساقطة.', 'دع رقعة قُرّاص مشمسة تنمو من أجل يرقاتها.', 'لا تُزعج الفراشات البالغة المحتمية في المخازن وأكوام الحطب خلال الشتاء.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('brimstone-butterfly', 'ar', 'الفراشة الكبريتية', 'يُقال إن التسمية الإنجليزية للفراشة جاءت من لون الذكر الأصفر الزبدي في هذا النوع.', 'من أوائل فراشات الربيع؛ ابحث عنها على أطراف الغابات في الأيام الدافئة.', 'ادعم وجود شجيرات النبق في السياج النباتية، وهي النبات الوحيد الذي تأكله يرقاتها.', 'تجنّب إزالة السياج النباتية الكثيفة التي تأوي البالغات خلال الشتاء.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('orange-tip', 'ar', 'الفراشة برتقالية الأطراف', 'الذكور وحدها تحمل أطراف الأجنحة البرتقالية الزاهية، أما الإناث فبيضاء.', 'في الربيع على امتداد المروج الرطبة والدروب حيث ينمو نبات زهرة الوقواق.', 'دع زهرة الوقواق وخردل الثوم ينموان في الأركان الرطبة غير المقصوصة.', 'أجّل قص حواف الطرق حتى تنتهي يرقاتها من التغذي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-blue', 'ar', 'الفراشة الزرقاء الشائعة', 'يعتني النمل أحيانًا بيرقات هذه الفراشة مقابل إفرازاتها السكرية.', 'من أواخر الربيع في المروج المشمسة الغنية بالبرسيم ونفل قدم الطائر.', 'اترك المروج دون قص لتتمكن أنواع النفل والبرسيم من الإزهار.', 'تجنّب رشّ المروج الغنية بالأزهار البرية بمبيدات الأعشاب.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('green-veined-white', 'ar', 'الفراشة البيضاء خضراء العروق', 'رغم شبهها بفراشة الملفوف البيضاء، فهي تفضّل النباتات البرية لا محاصيل الحدائق.', 'من الربيع إلى أواخر الصيف في المروج الرطبة والخنادق ودروب الغابات.', 'دع الأركان الرطبة تنمو بريًا بالنباتات الصليبية المحلية مثل زهرة الوقواق.', 'تجنّب تجفيف المروج الرطبة أو رشّها حيث تتكاثر.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('seven-spot-ladybird', 'ar', 'الدعسوقة ذات السبع نقاط', 'قد تلتهم دعسوقة واحدة آلاف حشرات المنّ خلال حياتها.', 'من الربيع إلى الخريف على النباتات التي يصيبها المنّ؛ وتتجمع للسبات في الشتاء.', 'تسامح مع بعض حشرات المنّ وامتنع عن الرشّ ليتوفر الغذاء للدعسوقة.', 'اترك السيقان المجوفة وأوراق الشجر المتساقطة حيث تحتمي الدعسوقة في الشتاء.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('buff-tailed-bumblebee', 'ar', 'النحلة الطنانة صفراء الذيل', 'ملكات هذا النوع من أوائل النحل ظهورًا في الربيع، تطنّ منخفضة بحثًا عن جحور للتعشيش.', 'من أوائل الربيع إلى الخريف على الأزهار؛ وتبحث الملكات عند أسفل السياج في الربيع.', 'ازرع أو اترك نباتات مبكرة الإزهار، ودع البرسيم يزهر في المرج.', 'اترك الضفاف وجحور الفئران القديمة دون عبث حيث تعشش المستعمرات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('western-honey-bee', 'ar', 'نحل العسل الغربي', 'تُخبر النحلة السارحة خليتها بموقع الأزهار عبر رقصة على شكل الرقم ثمانية.', 'من الربيع إلى الخريف على الأزهار في الأيام الدافئة الساكنة.', 'دع أنواعًا مختلفة من الأزهار تتفتح عبر الفصول، واترك صحن ماء ضحلًا.', 'تجنّب رشّ النباتات المزهرة، ولا ترشّ أبدًا في منتصف النهار.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('emperor-dragonfly', 'ar', 'اليعسوب الإمبراطور', 'من أكبر اليعاسيب في أوروبا، ويستطيع اصطياد فرائسه في الهواء.', 'في أيام الصيف الدافئة، راقبه وهو يجوب أطراف البرك والبحيرات.', 'احتفظ ببركة أو احفر واحدة بنباتات، واترك حوافها مكسوّة بالنبات.', 'أبقِ البرك خالية من التلوث ومياه الجريان لتتمكن اليرقات من النمو.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-darter', 'ar', 'اليعسوب الرشاق الشائع', 'كثيرًا ما يحطّ هذا اليعسوب على المكان الدافئ نفسه، وينطلق منه لاقتناص الحشرات العابرة.', 'من منتصف الصيف إلى الخريف قرب المياه الساكنة، يتشمس على المسارات والأعمدة.', 'اترك مواضع تشمّس مشمسة ونباتات حول البرك والخنادق.', 'امنع انجراف الأسمدة أو الزيوت إلى البرك حيث تعيش اليرقات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('red-wood-ant', 'ar', 'نملة الخشب الحمراء', 'قد يتجاوز ارتفاع تلال أعشاشها المترًا وتؤوي نصف مليون نملة.', 'من الربيع إلى الخريف في الغابات الصنوبرية؛ ابحث عن تلال مقببة من إبر الصنوبر.', 'اترك تلال الأعشاش دون عبث؛ فبناؤها يستغرق سنوات.', 'التزم بالمسارات ولا تركل تل النمل أو تحفر فيه أبدًا.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('wood-anemone', 'ar', 'شقائق النعمان الحرجية', 'ينتشر شقائق النعمان الحرجية ببطء شديد، حتى إن بساطًا كثيفًا منه يدل على غابة قديمة.', 'في الربيع، ابحث عن بُسُط من الأزهار البيضاء قبل أن تورق الأشجار.', 'اترك أرضية الغابة دون عبث لتزدهر جذوره البطيئة الانتشار.', 'استمتع به حيث ينمو؛ فقطفه يزيل أزهارًا استغرق انتشارها سنوات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lily-of-the-valley', 'ar', 'زنبق الوادي', 'كل أجزاء هذا النبات عذب الرائحة سامّة إذا ابتُلعت.', 'في أواخر الربيع، اتبع الرائحة إلى الغابات الظليلة والحدائق المظللة.', 'اترك أطراف الغابات المظللة وأوراق الشجر المتساقطة حيث ينمو.', 'لا تقطفه ولا تقتلعه، وأبقِه بعيدًا عن متناول الأطفال والحيوانات الأليفة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('ramsons', 'ar', 'الثوم البري', 'غالبًا ما تشمّ رائحة الثوم البري قبل أن ترى أزهاره البيضاء.', 'في الربيع، ابحث عن أوراق خضراء عريضة وأزهار نجمية في الغابات الرطبة.', 'اترك الغابات الرطبة دون عبث لتعاود بُسُطه النمو كل عام.', 'إن كان الجمع مسموحًا محليًا، فخذ القليل ولا تقتلع الأبصال أبدًا.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('marsh-marigold', 'ar', 'آذريون المستنقعات', 'من أقدم النباتات المحلية؛ فقد نجا من العصر الجليدي الأخير في إسكندنافيا.', 'في الربيع، ابحث عن أزهار ذهبية كبيرة في المستنقعات والخنادق وحواف البرك.', 'حافظ على حواف البرك والخنادق رطبة وغير مقصوصة ليتمكن من الإزهار.', 'تجنّب تجفيف الأراضي الرطبة واترك النباتات حيث تنمو.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('cowslip', 'ar', 'زهرة الربيع البرية', 'كانت زهرة الربيع البرية شائعة في مروج الحشيش لدرجة أن الأطفال كانوا يصنعون منها كرات.', 'في الربيع، ابحث عن أزهار صفراء مائلة في المروج القديمة غير المحسَّنة.', 'اترك المروج دون قص حتى تُزهر الزهرة وتُنتج بذورها.', 'لا تقطفها أو تقتلعها من البرية؛ فأزهار المروج في تراجع.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('oxeye-daisy', 'ar', 'الأقحوان الكبير', 'ما يبدو زهرة واحدة في الأقحوان الكبير هو في الحقيقة عشرات الأزهار الدقيقة المتلاصقة.', 'في الصيف، ابحث عن أقحوان أبيض كبير على جوانب الطرق وفي المروج.', 'اترك شريطًا من العشب دون قص خلال منتصف الصيف ليتمكن من الإزهار.', 'تجنّب رشّ حواف الطرق والمروج بمبيدات الأعشاب.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('common-dandelion', 'ar', 'الهندباء البرية', 'الهندباء البرية من أهم مصادر الرحيق المبكرة للنحل.', 'من الربيع فصاعدًا في كل مكان تقريبًا؛ تتفتح أزهارها في الشمس وتنغلق عند الغسق.', 'دع الهندباء تزهر في المرج في الربيع قبل أول قصّة.', 'امتنع عن مبيدات أعشاب المروج ليحتفظ الملقّحات المبكرة بهذا الغذاء الحيوي.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('heather', 'ar', 'الخلنج', 'قد تنتج نبتة خلنج واحدة أكثر من مئة ألف بذرة دقيقة.', 'في أواخر الصيف، ابحث عن بُسُط أرجوانية في المروج المكشوفة والمستنقعات.', 'ادعم إبقاء أراضي الخلنج مفتوحة ودون تجفيف.', 'التزم بالمسارات في أراضي الخلنج ولا تُشعل النار في الأجواء الجافة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('bilberry', 'ar', 'التوت الأزرق البري', 'يصبغ التوت الأزرق البري أصابعك بالأزرق، ويغذّي كل شيء من الطيور إلى الدببة.', 'في الصيف، ابحث عن شجيرات منخفضة بثمار داكنة في غابات الصنوبر والتنوب.', 'اترك الغطاء النباتي السفلي في الغابة سليمًا لتتمكن الشجيرات من الإثمار.', 'إن كان القطف مسموحًا محليًا، فاترك وفرة من الثمار للحياة البرية.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('lingonberry', 'ar', 'التوت الأحمر البري', 'يبقى التوت الأحمر البري صالحًا شهورًا بفضل مادة حافظة طبيعية في ثمرته.', 'في أواخر الصيف والخريف، ابحث عن ثمار حمراء لامعة على بُسُط دائمة الخضرة.', 'اترك نباتات أرضية الغابة دون عبث لتتمكن بُسُطه من الانتشار.', 'إن كان القطف مسموحًا محليًا، فامشِ بحذر تجنبًا لسحق النباتات.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('silver-birch', 'ar', 'البتولا الفضية', 'تعيل شجرة البتولا مئات أنواع الحشرات، وتغذّي بدورها أعدادًا لا تُحصى من الطيور.', 'طوال العام؛ لحاؤها الأبيض المتقشر يجعل التعرّف عليها سهلًا في أي فصل.', 'اترك أوراق البتولا المتساقطة والخشب الميت ليُثري التربة ويغذّي الحشرات.', 'تجنّب تقشير اللحاء، فذلك يجرح الشجرة ويُضعفها.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('norway-spruce', 'ar', 'شجرة التنوب النرويجي', 'تنمو إحدى أشجار التنوب النرويجي في السويد من جذور يبلغ عمرها آلاف السنين.', 'طوال العام في الغابات؛ وأكوازها المتدلية هي الأطول بين كل أنواع التنوب.', 'اترك الأكواز المتساقطة والخشب الميت، فهي تأوي الحشرات والفطريات.', 'التزم بالمسارات في الغابات تجنبًا لضغط جذور التنوب السطحية.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('scots-pine', 'ar', 'الصنوبر الاسكتلندي', 'يتوهّج الصنوبر الاسكتلندي المُعمّر باللون البرتقالي قرب قمته، وقد يعيش قرونًا.', 'طوال العام في الأراضي الرملية والصخرية؛ ابحث عن اللحاء البرتقالي في الأعلى.', 'اترك الأخشاب الميتة القائمة والأشجار المعمّرة، فهي غنية بالحياة البرية.', 'لا تُشعل النار قرب أشجار الصنوبر أو بجوارها في الأراضي الرملية الجافة.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('northern-pike', 'ar', 'سمكة الكراكي الشمالية', 'سمكة الكراكي مفترس كمين ينقضّ من سكون تام في لمح البصر.', 'من الربيع إلى الخريف في المياه الضحلة المليئة بالأعشاب في البحيرات والأنهار البطيئة.', 'ادعم الحفاظ على الضحال القصبية والنباتات المائية حيث تحتمي صغار الأسماك.', 'أبعد التلوث والنفايات عن الماء، والتزم بقواعد الصيد المحلية.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('european-perch', 'ar', 'الفرخ الأوروبي', 'يصطاد الفرخ الأوروبي في مجموعات، وخطوطه الداكنة تُشتّت ملامح جسده أمام المفترسات.', 'في الأشهر الدافئة حول الأرصفة ومنابت الأعشاب والمنحدرات تحت الماء.', 'ادعم نظافة المياه والبنى المغمورة التي تأوي الأسماك الصغيرة.', 'لا تُلقِ شيئًا في البحيرات والأنهار، والتزم بقواعد الصيد المحلية.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
insert into public.species_content (species_id, locale, common_name, fact, when_how, give, protect) values ('roach', 'ar', 'سمكة الروش', 'سمكة الروش غذاء أساسي تعتمد عليه كثير من مفترسات البحيرات.', 'في الأشهر الدافئة، في أسراب قرب سطح البحيرات والأنهار البطيئة.', 'ادعم الحفاظ على نظافة المياه وكساء الضفاف بالنبات من أجل التكاثر.', 'أبعد مياه الجريان والنفايات عن الماء، والتزم بقواعد الصيد المحلية.') on conflict (species_id, locale) do update set common_name=excluded.common_name, fact=excluded.fact, when_how=excluded.when_how, give=excluded.give, protect=excluded.protect;
